INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çimdik Attım Ölüme', 'cimdik-attim-olume-reyhan-sur-l65cd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'eteği toprağa tutkun dağayazında 

türkülere tünemiş 

bulut kepenekli bir çobanım salt 

çakır dikenler banıp 

özümü avuçlarım 

tel örgülü ay ışığından 

elinde beyaz mendiliyle 

