INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Mey....', 'nice-mey-hikmet-feridun-demir-1a74f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nice Mey içmek istedim, hep Fıcıları boştu.

Öyle bir hayat yaşadım ki, içinde özlediğim dünya yoktu.

02.03.2003 

Wermelskirchen-Almanya', 'Nice Mey içmek istedim, hep Fıcıları boştu. Öyle bir hayat yaşadım ki, içinde özlediğim dünya yoktu. 02.03.2003  Wermelskirchen-Almanya...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nice-mey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Sensiz', 'yuregim-sensiz-caner-kuru-ezxdi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tutmak istiyorum, nerede elin,

Sarmak istiyorum, nerede belin,

Nereye baksam hep senin hayalin

Kan ağlar yüreğim, kan ağlar sensiz.

Gözlerime bakan hasret okuyor,

Yüreğim hep acı, hep dert dokuyor,

Gezdiğimiz yerler hep sen kokuyor,

Hep çağlar gözlerim hep çağlar sensiz.

Çekmek zor sevdanın kuraklığını,

Yaşamak ne acı uzaklığını,

Özlüyorum senin sıcaklığını,

Buz bağlar yüreğim, buz bağlar sensiz.', 'Tutmak istiyorum, nerede elin, Sarmak istiyorum, nerede belin, Nereye baksam hep senin hayalin Kan ağlar yüreğim, kan ağlar sensiz. Gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuregim-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-i-brahim-ugur-toprak-bhs59', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani,

Güneş batıdan da doğsa

Sen, hiç gitmeyecektin.

Söylesene! 

Şimdi nerelerdesin? 

Daha dün gibi aklımda,

Beni benden alıp giden gözlerin.

Hani,

Dünya tersine bile dönse,

Hiç birşey değişmeyecekti.

Konuşsana! 

Ne oldu? Ne oldu da,

Hiç birşey söylemeden,

Veda dahi etmeden

Çekip gittin.

Hani,

Sen, hiç gitmeyecektin.

Hani,

        Sen,

               Gitmeyecektin! ..

25.05.04/Salı

10:02/İzmir', 'Hani, Güneş batıdan da doğsa Sen, hiç gitmeyecektin. Söylesene!  Şimdi nerelerdesin?  Daha dün gibi aklımda, Beni benden alıp giden gözlerin...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hani-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahipsiz Kalan Duygular', 'sahipsiz-kalan-duygular-muammer-celik-5it4t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akıttığın gözyaşlarımla 

yıkıyorum yüzümü her sabah

her sabah sensiz uyanıyorum güne

günboyu akşamı bekliyorum 

yıldızın karanlığıma parlar mı diye…

Bilmem kaç yıl geçti bu hüzün, bu hüsranla

kalbimde bıraktığın izleri silmeye uğraşıyorum hala…

Hala seni özlüyorum

hala seni istiyorum

hala seni arzuluyorum

ne tuhaf..! 

Ne tuhaf ki

sana yazdığım şiirler

sana mırıldandığım ezgiler

kulağımda çınlıyor 

öksüz bıraktığın sevgin

hala inim inim inliyor...

İnliyorum sensiz geçen gecelerde

akşamı gelmeyen gündüzlerde

arıyorum seni hala

açılmayan penceremde....

BirDeli

25.05.2004', 'Akıttığın gözyaşlarımla  yıkıyorum yüzümü her sabah her sabah sensiz uyanıyorum güne günboyu akşamı bekliyorum  yıldızın karanlığıma parlar ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sahipsiz-kalan-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel içelim...', 'gel-icelim-hikmet-feridun-demir-izzil', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel içelim hayat Meyini birlikte…

Dostlukla dolduralım kadehleri, yudum, yudum….

Aşkı Maşrapa ile toprağa dökelim…

Sevdayı Tohum diye ekelim…

Yeşersin renga renk çicekler…

Adını Sevdayı Yaşam  koyalım…

25.07.2002- 

Wermelskirchen-Almanya', 'Gel içelim hayat Meyini birlikte… Dostlukla dolduralım kadehleri, yudum, yudum…. Aşkı Maşrapa ile toprağa dökelim… Sevdayı Tohum diye ekelim...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-icelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okumadılar', 'okumadilar-necmi-unsal-4y0k4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rahmet  okudular.                           

Lanet  okudular.                              

Dua  okudular.                                 

Beddua  okudular.                           

Şarkı  okudular.                               

Türkü  okudular.

Kitap  okudular.                              

Mektup  okudular.                           

Ezan  okudular.                              

Meydan  okudular.                          

Yüzümden  okudular.                    

Gözümden  okudular.

Düğüne  okudular.

Canıma  okudular.

Yüzüme  okudular.

Ceddime  okudular.

Martaval  okudular.

Ama,

Bana  bir  şiir  okumadılar.

Beni  okuyan...

11 Mart 2004 Perşembe,  Danimarka-Køge  18.30', 'Rahmet  okudular.                            Lanet  okudular.                               Dua  okudular.                                  ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/okumadilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Olmak', 'gunes-olmak-aynur-uluc-q7i8r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elinin ötesi 

Dokunmadığın gölge 

Koklamadığın karanlık

İçinde büyümediğin çiçek

Olamadığın martı

Atamadığın çığlık

Ucunda kaybolunmuş zaman

Kuyruklu bir yalan

Kendiyle ışıyan 

Yıldız  olmak 

25-05-2004  yazılım

14-09-2005  düzenleme', 'Elinin ötesi  Dokunmadığın gölge  Koklamadığın karanlık İçinde büyümediğin çiçek Olamadığın martı Atamadığın çığlık Ucunda kaybolunmuş zaman...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gunes-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslolan Aşktır', 'aslolan-asktir-metin-yalti-8v82q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sürdürmektir güzel olan, tanışmak değil

Başarmaktır güzel olan,Başlamak değil

Dün olmadıysa,bu gün belkiyse yarın var daha

Kazanmaktır güzel olan kaybetmek değil

Sevmektir asl''olan sevilmek değil.

1983', 'Sürdürmektir güzel olan, tanışmak değil Başarmaktır güzel olan,Başlamak değil Dün olmadıysa,bu gün belkiyse yarın var daha Kazanmaktır güzel...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/aslolan-asktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mis kokulu günlerim', 'mis-kokulu-gunlerim-erol-sen-jowkf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gül kokan günlerime uyandım sabah

İçime çekerken güzel kokusunu

Sarıldım günün güzelliğine

Baharın  ayrı tadına uyanmışım

Mahmur gözlerim biraz kırpık

Güneşe bakmak ne mümkün

Bir banyo alayım gönlümce

Mis kokulu sabahın aşkına

Önüm güneş arkam sebze bahçesi

Yeni ekilmiş filizler severken yaşamı

Yolumda 4 kare çini içinden geçer

1 km ilersi asma bahçeleri

Denizim mis kokar kendine çağırırıken

Dalga sesleri ayrı nağmeler hayata dair

Yalnızlık bitmiş denizim de ısınmış güne

Kucak açmış sevdiği neşeli gülüşmelere

Benim penceremden dağlarıma bakarken

Bazen yeşil bazende koyumsu renklerle

Elbet boşluklar var manzaramda

Gün geçip geceye gelene

Oturup geceye baktım bahçe manzaraları önümde

Pergule yanı hanımeli kokuları

Önümde minyatür güllerden bir demet

Biraz ilersi çam ve güller

Havada güzel bir esinti bahar yanından

Gece böceklerinin nağmeleri sessizlikte

Gökyüzü yıldız bayramı sevinçlerime

Sakinlik ve huzur yaşamın gece içinde

25.05.2004', 'Gül kokan günlerime uyandım sabah İçime çekerken güzel kokusunu Sarıldım günün güzelliğine Baharın  ayrı tadına uyanmışım Mahmur gözlerim bi...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/mis-kokulu-gunlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Benim -1', 'ben-benim-1-sirma-mersin-9wxjx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anlamını bulamadığım cümleler,

Her yanımı  sarmışken! 

Satır arasına gizledim kendimi

Konuşmaların arasında geçen adımı duysamda...

Sessizliği tercih ettim.

Yalancı yüreklerin sahte samimiyetlerden  sebep 

Hep bir mesafe koydum.

Gel geç birisi  olmak yerine,

Yeri sağlam kişiliğimle biri oldum...

Tırnaklarımla kazıdığım bu yolda emekleyerek yol aldım, 

Bu ortamda...

Şimdi ise koşuyorum.

Bi sonraki şansı kaybetmemek için,

Hayatımı kontrol altına koydum...

20.5.04

Not: Ben yine kendimi anlattım!', 'Anlamını bulamadığım cümleler, Her yanımı  sarmışken!  Satır arasına gizledim kendimi Konuşmaların arasında geçen adımı duysamda... Sessizli...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-benim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağdaş Aşkın Ayak Sesleri', 'cagdas-askin-ayak-sesleri-i-brahim-bayraktar-9ugd8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç fahrenhayt derecede kaynar kanım? 

Kalbim, kaç görüşte küt küt atar? 

Kaç gün görmesem burnumda tüter? 

Ya ışık vermezse dibine, 

Gönül gözlü sevgilim! 

Altı boyutluysa gönül gözleri,

Aynı frekansta buluşursa yürekler,

Her frekansı toplamaz mı bünyesinde? 

Hele yakınsa birbirine,

Daha güçlüyse biri diğerinden,

Parazit yapmaz mı? 

Ya, elektriği geç alanlar? 

Aradığını bulamayanlar,

Hatlarında kısa devre olanlar,

İşte onları hiç sormayın; 

Yanar mahşere kadar.

Şimdi zaman değişti,

İletişim had safhada, 

Uzay çağındayız ya; 

Alıcılar güçlü olmalı,

Frekanslar ayarlı.

25.05.2004', 'Kaç fahrenhayt derecede kaynar kanım?  Kalbim, kaç görüşte küt küt atar?  Kaç gün görmesem burnumda tüter?  Ya ışık vermezse dibine,  Gönül ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cagdas-askin-ayak-sesleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıkışmış Hayatlar', 'sikismis-hayatlar-hakan-arikan-cdhcu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk önce; 

Daracık sokak aralarına,

Mahalle maçlarını sıkıştırdık.

Cumbalı,

Bahçeli evlerimizi,

Apartman dairelerine.

Hayatlarımızı,

Pazartesi,cuma ya sıkıştırdık.

Gönül verdik.

Kocaman yüreklere; 

Küçücük aşklar sıkıştırdık.

Bir ömür boyu yaşanacak birliktelikleri,

Bir geceye.

Özlemlerimizi,

Satır aralarına.

Üzüntülerimizi,

Kapı arkalarındaki gözyaşlarına.

Yüzsüzlüğü ve eğlenmeyi,

Cüzdan aralarına sıkıştırdık.

Galiba alıştık artık,

Sıkışık yaşamaya

Ankara Mart 2003', 'İlk önce;  Daracık sokak aralarına, Mahalle maçlarını sıkıştırdık. Cumbalı, Bahçeli evlerimizi, Apartman dairelerine. Hayatlarımızı, Pazarte...', ARRAY['Türk Edebiyatı','Şiir','Hakan Arıkan']::text[], 8.5, '{"poet":"Hakan Arıkan","poet_slug":"hakan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sikismis-hayatlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Sokakta Yaşıyor', 'yasam-sokakta-yasiyor-sirma-mersin-3qsz2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşam! 

Sokak arasındaki yaşananlarla devam ediyor...

Bazen 

Bi apartman önünde çekirdek çıtlatan genç kızların muhabbetinde...

Bazen 

Çocukların çığlıkları arasında  oynanan oyunlarla...

Bazen 

Camdan  cama dedikodu yapan kadınların konuşmaları ile...

Bazen

Sokaktan geçen eskicinin çığırtkan sesinde yaşıyor...

Bazen

Mahalle kahvesinde tavla sesi ile çay yudumlayan delikanlıların fısıltıları ile...

Bu kimliklerin arasına sıkıştırılmış bi yaşam

İşte bu sokakta soluk alıyor

Ve bu sokakta yaşıyor...

22.05.04', 'Yaşam!  Sokak arasındaki yaşananlarla devam ediyor... Bazen  Bi apartman önünde çekirdek çıtlatan genç kızların muhabbetinde... Bazen  Çocuk...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasam-sokakta-yasiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Refah Kampında Füzeyle vurulan adını bilmediğim çocuğa', 'refah-kampinda-fuzeyle-vurulan-adini-bilmedigim-cocuga-ayhan-ozturk-el-duzcevi-0rwm8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni iki yanında iki sopa takılmış.

Ortasında yeşil bir bez olan o tabutun üstünde gördüm.

İnsanlar koşuyorlardı bir elleri havada..

Sense sanki doyamadığın o dünyaya son kez bakar gibiydin..

Adını bilemedim, yazmadı buradaki gazeteler

Ne önemi var ki çocuktun işte.

Daha 10 yaşındaki bir çocuk…

Bizim burada da çocuklar ölüyor.

Ama füzeyle değil…

Hiç dondurma yedin mi bilmem..

Yada hiç oyuncağın oldu mu? 

Kırlarda dolaşıp arkadaşlarınla

Tek kale maç oynadın mı…

Hiç hayal kurdun mu gökyüzüne derin derin bakıp

Ya da….

Bomba sesi duymadığın..

Tahta tüfeğinle oynamadığın…

İki lokmayı kardeşinle paylaşırken..

Ölüm korkusunu…

Evet o 10 yaşındaki yüreğinde ölüm korkusunu

Yaşamadan uyuduğun oldu mu hiç

Artık korkma….

Bak artık öldüremezler seni bir daha…O füzelerle…

Nasılsa öldün...

Artık cennette oynarsın..

Seninle birlikte vurulan arkadaşlarında…

Geride kalanları sakın düşünme..

Anneni, kardeşlerini ve hala yaşıyorsa babanı…

Onlarda kavuşurlar sana en yakın zamanda…

Nasılsa bitmez tanklar..

Nasılsa bitmez füzeler…

Ama biliyorum, seni vuranlar bilmezler..

Ölen sen değilsin..ölen onlar….

Ayhan Öztürk

İstanbul, 21 Mayıs 2004', 'Seni iki yanında iki sopa takılmış. Ortasında yeşil bir bez olan o tabutun üstünde gördüm. İnsanlar koşuyorlardı bir elleri havada.. Sense s...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Öztürk el Düzcevi']::text[], 8.5, '{"poet":"Ayhan Öztürk el Düzcevi","poet_slug":"ayhan-ozturk-el-duzcevi","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/refah-kampinda-fuzeyle-vurulan-adini-bilmedigim-cocuga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-hakan-arikan-x04px', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçücük yüreklere,

Ufacık akıllara sahiptik.

O küçücük yüreklere kocaman aşklar,

Ufacık akıllaraa,

Bir sürü yalanlar soktuk.

Yüreklerimiz kirlendi,

Akıllarımız bizi yalnız bıraktı.

Flörtleri öldürüp,

Dostlukları rafa kaldırdık.

Cüzdanlarımıza,

Bir sürü yeşil yalnızlıklar doldurduk.

Heyecanlarımız,

Kirlenmişlikle,

Yalnız kalma arasında sıkıştı.

Keşke; 

Annemin çocukken anlattığı,

Yedi cücelerden biri olsaydım.

Boyu küçük,

Yüreği büyük cücelerden biri.

Yaşasın pamuk prenses,

Yaşasın yedi cüceler.', 'Küçücük yüreklere, Ufacık akıllara sahiptik. O küçücük yüreklere kocaman aşklar, Ufacık akıllaraa, Bir sürü yalanlar soktuk. Yüreklerimiz ki...', ARRAY['Türk Edebiyatı','Şiir','Hakan Arıkan']::text[], 8.5, '{"poet":"Hakan Arıkan","poet_slug":"hakan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/masal-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cam Maske', 'cam-maske-orhun-basat-55pel', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“ vuslata erdi tüm sokakları 

                                               demir aldı İstanbul..” 

CAM MASKE 

var saydığınız o şirin maske düşünce yüzünüzden 

yok sandığınız bin gecenin güncesi kanadı gördüm 

düşen göz yaşlarına uçmayı öğretiyordunuz 

dinledim gözlerinizi / sonra 

konuştum ellerinizle 

çok acıyordunuz 

(hep yanımda olmanızı istediğimi anlatacaktı bu şiir 

hep yanınızda kalmak istediğim gelmeseydi aklıma..)

yüzümde taşıdığım denizdiniz 

sessizce beklediğiniz iskeleden 

size haber vermeden 

sessizce alıp gittiğim kadın sizdiniz 

bir hüznü emzirirken 

tek kişilik yalnızlığınızda 

ne kadar da bizdiniz..', '“ vuslata erdi tüm sokakları                                                 demir aldı İstanbul..”  CAM MASKE  var saydığınız o şirin maske...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cam-maske-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
