INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son mektup', 'son-mektup-erol-sen-xuelq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir mektup bırakıp gittim sana

Yazılanlar kaleme zülum olmasın diye

Gözlerimdeki yaşlarla yazıldı

Renksiz saydam ve ruhsuz

Bir denizin ortasında kimsesizdim

Bütün kalelerim yıkılmış  süngüm düşmüş

Biten umudun güne doğumuydu belki de

Sabah olduğunda gün ışığını vermişti bana

Canlandım bir ömre yeni doğmuş 

Belki kışın soğuğu üşütmüştü bedenimi

Sıcacık oldum güneşin ışığına

Geçmişi kurcalamaktan sa gelecekte

Elbet limanlarımda olacak 

Elbet her limanda bir sevgilimde

Kürekler ağır gelmiyor bu bedene

Yelkenim fırtınadan yırtılsa da

Bedenim yelken olacak umudun doğumuna

Umutla seven dostlarım yeşerecek

Gün elbet fırtınaya bakacak

Yelkenim umut rüzgarım sevenlerim oldu ya.

25.05.2004', 'Bir mektup bırakıp gittim sana Yazılanlar kaleme zülum olmasın diye Gözlerimdeki yaşlarla yazıldı Renksiz saydam ve ruhsuz Bir denizin ortas...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/son-mektup-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir de Sen Bilsen', 'bir-de-sen-bilsen-caner-kuru-8zce7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül toprağıma ne ektiğimi,

Aşkının derdinden ne çektiğimi,

Bazen bir sel olup ne aktığımı,

Herkese anlattım, bir de sen bilsen…

Damarımda sanki çağlayan kanı,

Hasret ateşinde kaynayan canı,

Kalbimde fırtına koparan anı,

Herkese anlattım, bir de sen bilsen…

Yüreğimde neler gizlediğimi,

Ne hisler, duygular beslediğimi,

Sevgilim seni ne çok sevdiğimi,

Herkese anlattım, bir de sen bilsen…', 'Gönül toprağıma ne ektiğimi, Aşkının derdinden ne çektiğimi, Bazen bir sel olup ne aktığımı, Herkese anlattım, bir de sen bilsen… Damarımda ...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-de-sen-bilsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ElVeda', 'elveda-sule-aydemir-f1i5v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '_____________________veda

bu bir isyan

kaynağı düzenden

değiştirilemeyen

bu bir gidiş 

dalga dalga gelen 

boran olup

yıkıntıya çeviren

bu bir elveda 

dökülemeden 

dudaklarda kalan 

bu bir zaman

tekerrür

____________bilir

dönüşünde 

aralarken kapıyı

aralığında

kalır parmakları

alıp çekemez

____________bilir ki

hafiflemez 

____________acı

bir de

utandırır çığlığı

yüreği 

gözünü 

kapatır

artık

karartmadadır 

şafakları

toprak 

serin

öper 

yüzünü', '_____________________veda bu bir isyan kaynağı düzenden değiştirilemeyen bu bir gidiş  dalga dalga gelen  boran olup yıkıntıya çeviren bu bi...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/elveda-96-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Zakkumlar...', 'zakkumlar-naime-erlacin-eltxn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'zakkum çiçekleri açar tedirgin saatlere

esnemeleri yitirir uyku

acıya sağılır ağuda eriyen an

bırakılır ilk ünlem akşam alacasına

sorgulanır hayat

kaç kıratlık elmastır fikrin özü

ki nur saçar ruha pare pare

örtüsünü yayar yalnızlık 

aşina sıcaklığını geceye

gece yekpare! 

kısılıp kalmaz şiir sevdalısı yürek

kalem ucunda bir maytap tutuşur 

geceye sorulur sonra 

yazgının öncesinde bilenerek kuytuda

önyargısız bakılsaydı dünyaya

sevilirdi mutlaka zakkumlar 

süzülürdü şerbet 

belki sağalırdı menhus illet

uyanarak hayat artı düşlerin koynunda

çıldıran akrebe yol verirdi kalp 

şen bir ölüm seçerdi meselâ

kurak iklimlerin bodur ağacında

tek kişilik sundurmasında efkârın

mihenk taşı oluyor zakkum çiçekleri

fikir efendisi Sokrat’a dokunuyorum

nekes bir Akdeniz akşamının aşüfte kollarında

çıldırdı zakkumlar 

raks ediyorlar 

yanıyor göz kapaklarım

yürek yekpare! 

(25 Mayıs 2004)', 'zakkum çiçekleri açar tedirgin saatlere esnemeleri yitirir uyku acıya sağılır ağuda eriyen an bırakılır ilk ünlem akşam alacasına sorgulanır...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/zakkumlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Kadar Değil', 'benim-kadar-degil-fetih-sait-akkaya-wegk1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ateş gibi cayır cayır yanan yüreğim var 

seni seven,sonuna kadar

herkes sana ilgi duyar,bir yere kadar

ama benim gibi sonsuza kadar değil 

aşktan kör olan gözlerim var 

sadece seni gören,ecel kapıyı çalıp ve sonrasına kadar

herkes senin güzelliğini görebilir

ama inan bana benim gördüğüm güzelliklerin kadar değil

sana olan sevgim var gamze gamze

solan güle can veren.allaha kadar

herkesin sana ilgisi vardır,

ama benim taptığım kadar değil

ellerimde güllerim var aşka susamış 

suyu senin sengin,kökü yüreğim

herkes sana gül verecek tir sonunda solacaktır 

benim gülüm ölesiye kadar solmayacak

GÜLLERİN HEPSİ GÜZELDİR

AMA SENN KADAR DEĞİL

SENİ HERKES SEVER 

İNAN BANA BİİR TANEM

^^BENİM KADAR DEĞİL^^

                 benim kadar değil

                            .

                              ...', 'ateş gibi cayır cayır yanan yüreğim var  seni seven,sonuna kadar herkes sana ilgi duyar,bir yere kadar ama benim gibi sonsuza kadar değil  a...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/benim-kadar-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...İs...', 'i-s-naime-erlacin-y1gk6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kaç harfe sığar hayat

kaç kısım 

tekmili birden

hangi ibresine pusulanın 

sevda

siyah adımlarla arkada

ademoğlu silinmeye yazgılı destan

cezaya kalır boş laf

“böbürlenmek neye yarar

ölümün 

eşitleyiciliğini unutma…”*

sona ermeli an

sona ermeli zaman

türküsünden tanınır insan

Davud’un heykeline bak

nasıl da direniyor 

“yapıttır 

ölümden sonraya kalan” **

boş lakırdı 

mum isi! 

(*)      Bilge Karasu

(**)     Jean Cocteau

(25 Mayıs 2004)', 'kaç harfe sığar hayat kaç kısım  tekmili birden hangi ibresine pusulanın  sevda siyah adımlarla arkada ademoğlu silinmeye yazgılı destan cez...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/is-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Doğum Günün Kutlu Olsun', 'dogum-gunun-kutlu-olsun-mine-ozdemirtas-bpnn7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün gülleri

Koparsam dallarından

Sarılar içimde yeniden filizlenir.

Biliyorum.

Bu yüzden işte

Aç avuçlarını

Senin için

YILDIZLARI İNDİRİYORUM.

Kelimelerin tükendiği yerde

Susuyorsam çaresiz........

Anla.....

.......................... anla ki

SENİ SEVİYORUM.', 'Bütün gülleri Koparsam dallarından Sarılar içimde yeniden filizlenir. Biliyorum. Bu yüzden işte Aç avuçlarını Senin için YILDIZLARI İNDİRİYO...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dogum-gunun-kutlu-olsun-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Bırak! **', 'birak-hulya-simsek-2vs88', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yürürken boş kaldırımlarda âheste,

Fikrin gürleşsin sessizliğe inat.

Sana eşlik eden yağmurla birlikte,

Gözyaşın coşsun çekinme,bırak! 

Ruhunun keskin yankısı yıksın duvarları.

Âlemin sağır kulaklarına ulaşır elbet.

Alnına değsin saf yağmur damlaları,

Kara yazgını katıp seline gitsin,bırak! 

Bekleyenin var mı ki bir kapı ardında? 

Telâşının mânâsızlığına gülüyor kâinat.

Adım adım karışırken kederin yağmura,

Yön verme gövdene,nereye giderse bırak! 

Silik bir imzayla yadigâr kalır adım,

Gören duyar belki cılız sesimi,imdat! 

Etrafta insan kılığında birkaç adım,

Yüzüne bakmadan geçip gitsin,bırak! 

Görmekten bıktıysan kirli ruhları,

Kimsesizliği dost edindiysen ebedî,

Bir damla bile kalmadıysa akacak,

Ne tutuyorsun o canı içinde,bırak! 

    (8.nisan.2003)        Balıkesir        03:07', 'Yürürken boş kaldırımlarda âheste, Fikrin gürleşsin sessizliğe inat. Sana eşlik eden yağmurla birlikte, Gözyaşın coşsun çekinme,bırak!  Ruhu...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/birak-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklarda Bir Yürek', 'uzaklarda-bir-yurek-hakan-arikan-o21gw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilirim; 

Uzaklarda bir yürek var.

Beni bekleyen,

Benim aradığım.

Belki; 

Sokağın başı kadar uzak,

Okyanus ötesi kadar yakın belki.

Korksam da; 

Sokağın başına kadar yürümekten.

Hiç öğrenemesem de yüzmeyi,

Bir bağ var,

Beni o yüreğe bağlayan.

Bilirim bekler vazgeçmeden,

Uzaklara inat.

Gidemediğim sokak başını seyrederim,

Karanlık odamın canımdan.

Resimler çizerim sigara dumanıyla,

Bir nefeste sokak başına.

Önce cumbalı ahşap bir ev,

Her basamağı gıcırdayan,

Uzandığımda,

Tahta aralıklarından yağmuru seyredebildiğim.

Sonra; 

Kara saçlı,

Kara gözlü bir sevda çizerim,

Cumbaya.

Gıcırdayarak indiğim merdivenden,

Beni uğurlayan.

Apansız bir lodos çıkar,

Gecenin karanlığında,

Sabaha karşı.

Alıp götürür sevdaya inat,

Tüm çizgilerini ahşap binanın.

Ama bilirim bekler beni,

Sokak başında bir yürek.

Hava kararınca tekrar çizmem için,

Cumbalı ahşap evi.

Bilirim vazgeçmeden bekler beni,

Belki de lodosa inat,

Uzaklarda bir yürek.

Ankara Haziran 2003', 'Bilirim;  Uzaklarda bir yürek var. Beni bekleyen, Benim aradığım. Belki;  Sokağın başı kadar uzak, Okyanus ötesi kadar yakın belki. Korksam ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Arıkan']::text[], 8.5, '{"poet":"Hakan Arıkan","poet_slug":"hakan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/uzaklarda-bir-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Vakti...', 'gitme-vakti-i-brahim-ethem-bingul-zap62', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlemimdin oldun bin vuslatım

Sözümdün sen oldun şimdi özüm

Aşkıma sen oldun meşkim

Dayanamam yapma yar bunu bana

Bakmaya kıyamadığım

Aşk gözlerinde yaş

Neden,neden

Bu kanlı yaşlar

Nedendir bu dualar? 

Bakmıyorsun bile gözlerime

Hissedemiyorum ellerini

Bekliyorum..

Beklerken de yüreğim

Seninle,sende..

Anladım,kara gülüm

Anladım gelmış gitme vakti

Öldüğüme değil,

Seni ağlattığıma yanarım

Ağlarım seninle,sende...', 'Özlemimdin oldun bin vuslatım Sözümdün sen oldun şimdi özüm Aşkıma sen oldun meşkim Dayanamam yapma yar bunu bana Bakmaya kıyamadığım Aşk gö...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gitme-vakti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Neye Yarar? **', 'neye-yarar-hulya-simsek-c2580', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçime yerleşiyor inceden bir intizâr,

İnsan diyor:''incindiği kadar insanlaşıyor.''

Ruhuma kirli bir is gibi sinsin keder,

İnceldiği yerden kopsun kalbimin can ipi,

                                                       neye yarar? 

Akşam rüzgârı vursun başımı taştan taşa,

Nasırlaşmış kelimelerim ''ah'' değil ''tak'' eder.

Gövdem uzansın bir kayaya boydan boya,

Birkaç damlayla hüzün mühürlesin gözlerimi,

                                                        neye yarar? 

         (11.06.2003-İstanbul)      23:53', 'İçime yerleşiyor inceden bir intizâr, İnsan diyor:''incindiği kadar insanlaşıyor.'' Ruhuma kirli bir is gibi sinsin keder, İnceldiği yerden ko...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/neye-yarar-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Bugün**', 'bugun-hulya-simsek-078mi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlıkla örttüm gözlerimi bugün,

Karamsarlığıysa sıyırıp aldım gönlümden.

Sensizliği tüketircesine seni yaşadım an an...

Bir de mektup yazdım ''Sevgiliye'' diye başlayan.

Yağmurun ezgisini sesin sandım bugün,

Rüzgârın saçlarımı okşayışını ellerin saydım.

Bir umudu daha ateşledim,avutsun diye,

Bir tek seni diledim dün,bugün ve ömrümce....', 'Karanlıkla örttüm gözlerimi bugün, Karamsarlığıysa sıyırıp aldım gönlümden. Sensizliği tüketircesine seni yaşadım an an... Bir de mektup yaz...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bugun-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ada Askerinden Notlar', 'ada-askerinden-notlar-mustafa-sen-5wa8e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep uzakları kolluyor ellerim

Unutulmuş bir Ada’da

sessiz ,  sensiz

Bilinmez okyanuslar

ürpertiyor  sessizliğimi

ateş kor oldu,divaneyim

Başı dumanlı martılar

sessizliğini haykırıyor dudaklarının

nerede yasak aşk oyunlarımız

nerede zümrüt gözlerin

düşlerime ses ver sevgili

………………....orada mısın? 

(sabah 06:00’da aklımdan geçen) 

Sabahın yeşil’ine uyanıp ta

Uygun adımla değil de 

Adıma uygun yürüyerek

Denizi aşmak istiyorum 

İsa gibi

Rüyalarımdaki hayata dalmak

Uyanmamak,

Düşlerime, düşman olmayın! 

(öğlen üzeri aklından geçen saçmalar) 

Farklı şeylere takılıyorum 

Acaba martılar nasıl sevişir? 

Ağaçlar su içer mi kana kana? 

Tüfekler  ağlar mı? 

Sivilceyle sivil hayatın alakası nedir? 

Şafak  kaç ? 

(yat içtiması  civarı aklından geçen) 

yıldızların arasına karışıp

sessizce parıldamak,

oturup oyuncağı elinden alınmış

bir çocuk misali 

ağlamak…..                                                                           

özüm,özler  seni...

gel ey sevgili,

gel…

                                        Mustafa ŞEN

                                      GÖKÇEADA 2004', 'Hep uzakları kolluyor ellerim Unutulmuş bir Ada’da sessiz ,  sensiz Bilinmez okyanuslar ürpertiyor  sessizliğimi ateş kor oldu,divaneyim Baş...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şen']::text[], 8.5, '{"poet":"Mustafa Şen","poet_slug":"mustafa-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ada-askerinden-notlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '&...Hoşçakalın Dostlarım', 'hoscakalin-dostlarim-mine-ozdemirtas-r3jgr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidiyorum.

Elde olmayan sebeplerle

Bu yüzden; 

Bir kez daha... usulcacık

dokunmak istedim 

sıcacık yüreklerinize.

kefeni yırtarsa ruhum

ve................ nasipse

yeniden görüşmek üzere

Huzurunuzdan çekiliyorum

İzninizle.', 'Gidiyorum. Elde olmayan sebeplerle Bu yüzden;  Bir kez daha... usulcacık dokunmak istedim  sıcacık yüreklerinize. kefeni yırtarsa ruhum ve.....', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hoscakalin-dostlarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sobe', 'sobe-altay-ozbek-xqq2e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Farkedenleri gördüm,

Arayanları gördüm,

Bulanları gördüm,

Kendim için umutlandım.

Burnunun ucunu göremeyenleri gördüm,

İblisin büyüsünde dalgınlaşmış; 

Üzüldüm.

Kendimi aradım

Yardım etmek için! 

Başıma musallat olana baktım; 

Kitaplara daldım zayıflığımdan! 

Gördüm!', 'Farkedenleri gördüm, Arayanları gördüm, Bulanları gördüm, Kendim için umutlandım. Burnunun ucunu göremeyenleri gördüm, İblisin büyüsünde dal...', ARRAY['Türk Edebiyatı','Şiir','Altay Özbek']::text[], 8.5, '{"poet":"Altay Özbek","poet_slug":"altay-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sobe-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buluşma Vakti', 'bulusma-vakti-hakki-hakan-kaya-rvvrs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'önce dikenleriyle tanıdım

yaşamı

sonra kokladım 

avuçlarımda topladım 

karanlık yanlarını 

... 

her köşe dönüşümde 

bir çığlık geldi peşimden 

çiçeklerini suladım 

yarama bastım kanlarını 

... 

eksik yanını söylediler 

yaşam ağacının 

göçmen kuşları 

gözlerimi verdiler 

göremedim diye 

bakışlarımı suladılar 

dünüme ağladılar 

...

bir ağıt avlanmış 

açlığı sindirilmesi için 

duygular şaha kalkmış 

savaşçılar yüreklerini kesmiş 

harp alanı boyanmış 

bir akıncı yürüyüşü başlamış 

... 

bedeni dumanlı 

toprak göğsünü açmış 

tütsüler yakılmış 

bekliyor emanetini 

... 

yakın 

yakın bir

buluşma vakti', 'önce dikenleriyle tanıdım yaşamı sonra kokladım  avuçlarımda topladım  karanlık yanlarını  ...  her köşe dönüşümde  bir çığlık geldi peşimde...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bulusma-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki', 'sanki-fetih-sait-akkaya-4s9t0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir umut aradığım son söz 

güneşin doğmasından bile kolay 

çılgın şelale misali

son sözüm ilk sözüm olsun

sana kendimi anlatmak gittikçe zorlaşiyor

seni gördüğüm her gün 

umutsuz...

sevgisiz...

gördüğüm her gün 

dilim çözülmeyen bir gemici düğümü oluyor

sanki sevmek elimdeymiş gibi sana tutkunum

hiç olmazsa güzel bir söz yağmur kokulum

inanki kış kokulum 

sanadüğümlenmiş hayatım

tek çare sen

ellerim titriyor,

dengesizim

esiriyim,

çaresizim,

gözlerim kan ağlıyor,

kalbim durgun

ben SANKİ SANKİ...', 'bir umut aradığım son söz  güneşin doğmasından bile kolay  çılgın şelale misali son sözüm ilk sözüm olsun sana kendimi anlatmak gittikçe zor...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sanki-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Başka', 'senden-baska-hifzi-ozbekmez-0x5em', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzeller içinde sevdiğim sensin

Senden başka benim sevdiğim mi var

Aşkıyla ateşte yandığım sensin 

Senden başka benim sevdiğim mi var

Uğruna şarkılar yazdığım sensin

Adına övgüler dizdiğim sensin

Kollarım dolayıp çözdüğüm sensin

Senden başka benim sevdiğim mi var

Resmine bakıp ta ağladığımsın

Hasretiyle sine dağladığımsın

Benim umudum bel bağladığımsın

Senden başka benim sevdiğim mi var

Latifim hep seni bastım bağrıma

Özlemin gidiyor benim ağrıma

Gönlün kulak versin benim çağrıma

Senden başka benim sevdiğim mi var', 'Güzeller içinde sevdiğim sensin Senden başka benim sevdiğim mi var Aşkıyla ateşte yandığım sensin  Senden başka benim sevdiğim mi var Uğruna...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-baska-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher Vakti', 'seher-vakti-hifzi-ozbekmez-xkq2d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bitmez hüzün çöker içime o an

Saatler geçmez sanki durur zaman

Sevdam alevlenir içimde yanan

Oturur ağlarım seher vaktinde

Kabıma sığmam ki coşar taşarım

Mutluluğu hüznü yalnız yaşarım

Gurbet yollarında dağlar aşarım

Sel gibi çağlarım seher vaktinde

Ateşle yanarken titrerim tir tir

Acılarım gelir aklıma bir bir

Beni yakan onun o özlemidir

Ciğerim dağlarım seher vaktinde

Oturur aşkıma şiir yazarım

Kağıdım kalemim benim pazarım

Sevda yollarında yalnız ozanım

Gönlümü eğlerim seher vaktinde

Ben ona aşığım ona yanarım

Onsuz bu dünya batar sanarım

Hayalde rüyada onu ararım

Ben yarsız neylerim seher vaktinde', 'Bitmez hüzün çöker içime o an Saatler geçmez sanki durur zaman Sevdam alevlenir içimde yanan Oturur ağlarım seher vaktinde Kabıma sığmam ki ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seher-vakti-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-vedat-sarapci-d650s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine yoksun seni aradığım pencerelerde,

Usulcacık geçen özlem yüklü gölgelerde,

Yine yoksun gözlerimin derinliklerinde,

Umutlarda, sevgilerde, gelecekte,

Yine yoksun dudağımdaki her hecede…

(İstanbul, 13 Mayıs 2004)', 'Yine yoksun seni aradığım pencerelerde, Usulcacık geçen özlem yüklü gölgelerde, Yine yoksun gözlerimin derinliklerinde, Umutlarda, sevgilerd...', ARRAY['Türk Edebiyatı','Şiir','Vedat Şarapcı']::text[], 8.5, '{"poet":"Vedat Şarapcı","poet_slug":"vedat-sarapci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yoksun-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-i-brahim-dikmen-2-y9u2s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen ve ben,iki beden,

Yaratılmışız,acılar için neden.

Yıkılmış çökmüşüz kalben,

Ağlamak istiyorum,ta içten.

Neden yarabbim,hayatın çilesi bize,

Ne yaptıkta hor gördün,mutluluğu bize.

Sen ve ben iki beden,

Yaratılmışız,acılar için neden.', 'Sen ve ben,iki beden, Yaratılmışız,acılar için neden. Yıkılmış çökmüşüz kalben, Ağlamak istiyorum,ta içten. Neden yarabbim,hayatın çilesi bi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-ve-ben-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklar ve Sen', 'sokaklar-ve-sen-hakan-arikan-wbb6a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni düşündüm,

Akşam üstlerinin kırık,dökük,telaşlı sokakların da.

Yağan kar örterken; 

Aşkı,

Günahı,

Pişmanlık dolu anları.

Seni aradım,

Akşam üstlerinin kırık,dökük,telaşlı sokakların da.

Ayın pırıltılı ışıklarında,

Burunları açılmış kösele ayakkabılarımla,

Eski binalar,

Paslı yağmur olukları arasında.

Ellerini hatırladım,

Akşam üstlerinin kırık,dökük,telaşlı sokakların da.

Yapraklara benzeyen,

Parmaklarının arasında rüzgarların dans ettiği,

Ellerini hatırlarım.

Seni bekledim,

Akşam üstlerinin kırık,dökük,telaşlı sokakların da.

Denizden çok uzakta,

Yaşamın vurdum duymaz mezarlıkların da.

Seni özledim,

Akşam üstlerinin kırık,dökük,telaşlı sokakların da.

Her tercihte bir şeyler kaybederken.

Seni beklemenin acısı,

Arsızca uyuştururken bedenimi,

Seni özledim.

Sen benim evimdim,

Akşam üstlerinin kırık,dökük,telaşlı sokaklarında.

Badanalı odalarının duvarlarına çiçekler çizdiğim,

Temmuz ayında damında yıldızların ağladığı,

Saçaklarında yağmur damlalarının fısıldaştığı.

Sen; 

Aşktın,

Günahtın.

Pişmanlık dolu anlardın.

Akşam üstlerinin kırık,dökük,telaşlı sokaklarında.

Şimdi yoksun buralar da,

Sensiz yaşamanın bir başka yolu olmalı mutlaka.

Ankara Mart 2003', 'Seni düşündüm, Akşam üstlerinin kırık,dökük,telaşlı sokakların da. Yağan kar örterken;  Aşkı, Günahı, Pişmanlık dolu anları. Seni aradım, Ak...', ARRAY['Türk Edebiyatı','Şiir','Hakan Arıkan']::text[], 8.5, '{"poet":"Hakan Arıkan","poet_slug":"hakan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sokaklar-ve-sen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-saim-gozek-7rasv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kuşun yavrusuna 

taşıdığı yem,

yeni palazlanan yavrunun

sarı tüyleri,

pembe gagası gibiydi

seni sevmek...', 'kuşun yavrusuna  taşıdığı yem, yeni palazlanan yavrunun sarı tüyleri, pembe gagası gibiydi seni sevmek......', ARRAY['Türk Edebiyatı','Şiir','Saim Gözek']::text[], 8.5, '{"poet":"Saim Gözek","poet_slug":"saim-gozek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-sevmek-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Varlığın Bütünlüğümdür Annem**', 'varligin-butunlugumdur-annem-hulya-simsek-ensm8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'beni ben yapan Annem''e...

Yokluğun düşüncesi bile her gün batımında 

İçimde yanan kızıl bir hançer olur Annem.

Gecenin en zalim saatlerinde,

Çıkmaz yolların darlığında,

Çaresizliğine düştüğüm dünyada,

Kendi kanımda boğulduğumda bile,

Yüzünün en şefkatli haritası yol gösterir bana.

Ruhunun sıcaklığından yoksun geçse de şu günlerim

Ben her gece şefkatinin bulaştığı yorgana sarılıp uyuyor

Serin sesinin hayali sularında huzurla yıkanıyor

Ve günü kıskandıracak bir ''merhaba''diyorum Annem

Gece gönlümü boğan korkularımdaki imdatım 

Senin sesinden öğrendiğim dualarım

Yüzümde hala yerli yerindeyse gülüşüm

Nedeni gözümün önünde canlanan hayalin...

Başlangıcı bitiş olan sevgilerin harmanında

Her gün gönlümü kırpan şu dünya hâllerinde

Başımı naçar ellerimin arasına aldığımda

Melekleşen ellerinle varlığımı bütünleyensin Annem.', 'beni ben yapan Annem''e... Yokluğun düşüncesi bile her gün batımında  İçimde yanan kızıl bir hançer olur Annem. Gecenin en zalim saatlerinde,...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/varligin-butunlugumdur-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mimar Sinan', 'mimar-sinan-i-brahim-dikmen-2-fsfcp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlümüzde taht kuran,

Etrafına bilgiler saçan.

İnanki en büyük,

Sensin mimar sinan.

Ellerimiz çarpacak,

Sporcuların koşacak.

Rakibine goller atacak,

Canım mimar sinan.

Pankartlarda senin adın var,

Gönüllerden düşmeyen şanın var.

Seni yalnız bırakmayan öğrencilerin,

İlim saçan öğretmenlerin var.', 'Gönlümüzde taht kuran, Etrafına bilgiler saçan. İnanki en büyük, Sensin mimar sinan. Ellerimiz çarpacak, Sporcuların koşacak. Rakibine golle...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mimar-sinan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayt İstemekmiş', 'hayt-i-stemekmis-yasar-ates-v9tut', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya adına varoluştur yaşamak

Evren bu dünyayı niçin istemiş ki

Hangi duvar ağlamaktan eridi

Hayat işte nevsimiz için istemekmiş

Sürdürdük buralardan yabancı bireyleri

Güldürdük kendimize yalacıları

Acaba temiz mi ki bu gerçekler

Tamamsa sence hayat istemekmiş

İstemeden beklemeden dinlemedik onu

O kimmiş ki dedik sürekli

Ama kaybetmek mi yoksa kazanmak mı

Belli oluyor işte hayat istemekmiş

Bilmiyordum neden demesini ben

Artık dilenmeden geçemem buralardan

Gidiyorum dedikçe kim bu gelenler

Dediler ki erkenden hayat istemekmiş

Hız verdik düzen çarkına

Para ile şöhreti çok canımız çekti

Sanır mısınız ki biz marifetli

Herkes iyi bilir marifetlice hayat istemekmiş

Sevda dönemecinde savrulan gençlik

Gencecik yürekler kürekle sürüklenir

Yüzer çırpınır ama susuz mu kalır

Hayır hayırsever hayat istemekmiş

İstemekmiş hayat dilenemedim ki

Bilenemedim boşlukta duran keskiye

Önemli olan hayat boşmuş gibi olsa da

Esaret ve zihniyette hayat istemekmiş

YILLAR İSTEMEKTEN İBARETMİŞ...

                                                    erdemli_net', 'Dünya adına varoluştur yaşamak Evren bu dünyayı niçin istemiş ki Hangi duvar ağlamaktan eridi Hayat işte nevsimiz için istemekmiş Sürdürdük ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ateş']::text[], 8.5, '{"poet":"Yaşar Ateş","poet_slug":"yasar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hayt-istemekmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz', 'beyaz-sule-aydemir-ujsca', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'beyaza söz kesildi 

kesilmeye an var 

beyaz 

herkesten 

çok çağırır beni

beyaz 

bir son

kaçmadığımsın

beklediğim

sarsan 

bedenimi

beyazın 

beyaz yakar 

cazibesi...

_ _ _ _ _ _ _ _ _ _ ki

_ _ _ _ _ _ _ _ _ _ _ bir beyazdır 

_ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _seni

_ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _  en son koklayıp dokunan', 'beyaza söz kesildi  kesilmeye an var  beyaz  herkesten  çok çağırır beni beyaz  bir son kaçmadığımsın beklediğim sarsan  bedenimi beyazın  b...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beyaz-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takvimin Yaprağı', 'takvimin-yapragi-burak-killioglu-mpzr7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Takvime baktım,

Bugün de geçip gitmiş.

At bir çentik daha! 

Ömrüm de takvim gibi,

Bir yaprak çevirmeden bitmiş.

Aynen bu şiir gibi.', 'Takvime baktım, Bugün de geçip gitmiş. At bir çentik daha!  Ömrüm de takvim gibi, Bir yaprak çevirmeden bitmiş. Aynen bu şiir gibi....', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/takvimin-yapragi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-burak-killioglu-kk20q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne dalgalar aştım

Hayat denen denizde.

Yalnızca sende battım.

Baktım ki,

Sular bileklerimde.', 'Ne dalgalar aştım Hayat denen denizde. Yalnızca sende battım. Baktım ki, Sular bileklerimde....', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-395-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve Dans', 'ask-ve-dans-aysel-coban-6yz8v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel artık, gel ki…..........

Beklemelerim firarda şimdi

Sen gelmezsen

Ben gelirim içimde arzuların dansıyla

Etrafımda özlem tangosu, bire bir gözlerim harekette

Hadi yaklaş, yakınlaş bana

Uzak kaldığım her an için sarıl, sarıl bana

Öyle bak ki…….

Kaçınılmaz sabırsızlığımı anlasan

Hadi anla,

Anlatsana bana, yüreğimin dizginsizliğini

Anlatırken, kollarında yaşa beni

Her adımlar dönüşleri getirsin yeniden 

Gör artık, gör ki……….

Tahammül sınırım tükendi şimdi

Sen görmezsen

Ben hissettiririm göremediklerini, yavaş yavaş

Yüzümde hasretin yılgınlığı, an be an arttıkça

Hadi gül, gülümse bana

Özlediğim her gün için sev, sev beni

Öyle sev ki……

İflah olmaz duygularımı açığa çıkarsan

Hadi çıkar,

Söylesene bana, umulmaz bir akşamın rastlantısını

Söylerken, tanıştığımız o anı yaşat bana

Her hatırlayışlar vuslatları bitirsin yeniden

Kaçma artık, kaçma ki………

Kızgınlık derecem arttı şimdi

Sen anlamazsan

Ben anlatırım anlamadıklarını ağır ağır

Bedenimde çözümsüz kıvranmalar, gün be gün kayboldukça

Hadi dokun, dokun bana

Tükendiğim her ay için hisset, hisset beni

Öyle hisset ki…..

Vazgeçmelerim için elzem olsan

Hadi ol,

Bak bana, görürüm asil duruşun utangaç bakışlarını

Elzemken, kollarımda aşkın dansını et benimle

Her dans edişler ayrılıkları bitirsin yeniden

Gel artık, gel ki………

Sensizliğim yeniden depreşti şimdi

Sen istemezsen

Ben bulurum seni 

Hadi tut ellerimden, öyle tut ki…….

Kaybettiklerimizi geri getirsen

Hadi gel,

Sevişmelerin döngüsü çağırıyor birer birer', 'Gel artık, gel ki….......... Beklemelerim firarda şimdi Sen gelmezsen Ben gelirim içimde arzuların dansıyla Etrafımda özlem tangosu, bire bi...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/ask-ve-dans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdeal', 'i-deal-yasar-ates-owqjl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsan yeterini bilmeli

Bilir maymun iştahını yendikçe

Benden daha kötü durumdakileri kim bilir? 

İnsan, kendi toplumu için amacı olandır

Şair, insanlar için idealleri olandır

Hizmet mutlulukta saklıdır

Toplumda yer bulabilmek de bizde bir görevdir

İdealist olmak, hayaperestlik değil

Sevmek, gerçeği inkar etmek değil

Mutlu olmak yalnızken olur mu hiç? 

Paylaşılmayan sevinç yaşanamaz

İnsan tek başına mutlu olur mu hiç? 

Aynı ve tekdüze yaşantılar

Nefret verir insana, 

Utandırır aynalara bakmaya

Utanırken insan yaşamak güzel belki

Toplumun yaşantısına uygun olmak ta nedir? 

Herkesi aynı kefeye koymak vatanı çökertir

Ne mutlu kendi dünyalarını yaratanlara

Hiç acımaz yaralıların yarası bu yolda! 

Dünya insanlar için varolmuştur

Biz de kalkmış ona acımasız ve yalan deriz

Bilmiyoruz sanki yok ettiklerimizi

Hem yeşili hem de atmosferi katledişi

Hayata dair ne yaptık ki? 

Duyarlı insanlara ne kattık ki? 

Duyarlı bir idealiste aynen şunu dedik; 

''''saçmalama''''

Hayat için değil de kendimiz için yaşadık

Duyarlı ve amaçlı insanları,

Elimizin tersi ile itip boşverdik onları

Belki bilmeyiz hayaller yaşanmaz...

Düşününce aslında rüyalar gerçek değil,

Böyle bir dünyada gerçekler hayatta değil', 'İnsan yeterini bilmeli Bilir maymun iştahını yendikçe Benden daha kötü durumdakileri kim bilir?  İnsan, kendi toplumu için amacı olandır Şai...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ateş']::text[], 8.5, '{"poet":"Yaşar Ateş","poet_slug":"yasar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ideal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Haber Olsun', 'dosta-haber-olsun-yasar-ates-qipul', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Efkarlıyım dostlar haberiniz ola; 

Bu satırlar hüzünlü, burda garibim,

Birkaç sene öncesi ne de güzelmiş,

Sevgilimle olmak, aşkı yaşamak...

Güzel olan hayatı paylaşmak.

Günler ne çabuk geçiyor değil mi? 

Daha dün gibi aklımda gözleri,

Dostlar siz duyun sevgisizliğimi,

Güzel hatıralarla dolu olan geçmişimi...

Silip atamıyorum seninle geçenleri,

Gözümde yaş, gönlümde yalnızlık,

Sensizlik bu kadar mı yakar? 

Sevgili yoksa, insan dost arıyor şimdi...

Ey ümit bağladığım yıllar nereleresiniz? 

Geçmiş viran olmuş bilir misiniz? 

Yaşanmışlıklar sensizken ümit vermiyor,

Dost arıyorum birazcık umudm varken...

Karşıma geçmeni ve boynuma sarılmanı,

O kadar özlemişim ki hiç sorma,

Bir dostum olsa da şimdi yanımda,

Aslında seni istiyor yürek yanımda...

DOSTA:

Bu sobette dost acı söyler,

Dilin acı da olsa yüreğin yeter...

SEVGİLİYE:

Tatlı dilini özledim şimdilerde,

Konuşmak ne güzelmiş seninle...', 'Efkarlıyım dostlar haberiniz ola;  Bu satırlar hüzünlü, burda garibim, Birkaç sene öncesi ne de güzelmiş, Sevgilimle olmak, aşkı yaşamak... ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ateş']::text[], 8.5, '{"poet":"Yaşar Ateş","poet_slug":"yasar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dosta-haber-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Düşünme', 'beni-dusunme-i-smail-sahin-71l2x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir  deliyim  sokaklarda

Güneşten  kaçan  yorgun

Maviler  göremem düşümde

Bir  şahinim  kayalıklarda

Simsiyah  bulutlar  yorganım

Çok  olsa  peşime  takılır  gözlerin

Beni  düşünme

Çok  olsa  düşer

Umutları  sonsuz  göklerin

Ölürüm  bir  sabah  güneşle

Tanrı  da  küser

Yanar  cehennem  olurum

Beni  düşünme', 'Bir  deliyim  sokaklarda Güneşten  kaçan  yorgun Maviler  göremem düşümde Bir  şahinim  kayalıklarda Simsiyah  bulutlar  yorganım Çok  olsa ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beni-dusunme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-gurbuz-vural-kgxp8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anam,sen doğurdun beni

Ama doğum sancıların 

Bende kaldı...

Silme gözlerindeki yaş ile

Gözlerimdeki yaşı.

Ayıramazlar bizi.

Ayıramazlar ayı şavkından.

Ayıramazlar 

Bir çiçeği özünden.

Ayıramazlar seni benden...

Her özlem 

Bir doğum sancısı gibi.

Her gün binlerce

Ölüm doğuruyorum ben...

Hey dostlar! ! ! 

Sormayın bana 

“Bu üzüntün niye? ”

Her gün binlerce 

ölüm doğuruyorum ben...', 'Anam,sen doğurdun beni Ama doğum sancıların  Bende kaldı... Silme gözlerindeki yaş ile Gözlerimdeki yaşı. Ayıramazlar bizi. Ayıramazlar ayı ...', ARRAY['Türk Edebiyatı','Şiir','Gürbüz Vural']::text[], 8.5, '{"poet":"Gürbüz Vural","poet_slug":"gurbuz-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anam-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Gidelim Gönül', 'gel-gidelim-gonul-i-smail-sahin-efj7k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mecnun  olma  gönül  Leyla’yı  sorarlar

Gez  dilediğince  senindir  sokaklar

Aç  kal  susuz  kal  da  Mecnun olma gönül

Ağla  sıkılmadan soğuk yatağında

Ağladığın  kadar  Hızır’sındır  sen

Yaş  senindir  ama  faş  etme  gönül

Yakup  der  acırlar  acıyıp  gülerler

Öleceksen  öl  de  “Aşk”  deme kimseye

İbrahim  ederler  ateşe  atarlar

Ateş  sana  kalır  tanrı  gelmez  gönül

Yar  için  düşsün  baş  balyoz  almak  mertlik

Seviyorum  dersen  dağı  delmek  gerek

Dağ  delinir  ama  su  yok  Şirin yoksa

Deldiğin  dağlarda  ölmek  gerek  gönül

Gel  gidelim  gönül  burda  yürek  kanar

Her  şeyler  boşalmış  hayatlar  zindanda

Yalnızlık  da  güzel  gel  gidelim  gönül

Dost  yabancı  sana  herkesler  yabancı

Gülün  senin  değil  yastık  senin  değil

Valize  ne koydun  yüreğinde  ne’ n  var

Gel  gidelim  gönül  İsmail ederler', 'Mecnun  olma  gönül  Leyla’yı  sorarlar Gez  dilediğince  senindir  sokaklar Aç  kal  susuz  kal  da  Mecnun olma gönül Ağla  sıkılmadan soğ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gel-gidelim-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-nal-n-yildiz-jeh1o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '- Günay''a-

Her sabah uyandığımda

Mevsimsiz aşerdiğim leylâk kokusundaysan Tanrım 

Bırak peşimi, bana acı

Ben sürgünüm, hem küskünüm bir de yasaklı

Bu dünyaya uygun değil duruşum

Her rüzgârda,

Yapraksız kalan,

Asi bir tohumdan ibaret

İncinmiş 

Kırmızısını yitirmiş 

Tek sap gelincik, kara bir nokta ruhum, 

Ben kendine düşen uçurumum

Artık sen karar ver benim yerime, 

Ben üzgünüm, hem üşüdüm, çok da yorgunum 

Bir şeyleri benim için yoluna koy

Ben yalnızım, hem ayarsız, bir de çözüldüm

Her sabah uyandığımda

Mevsimsiz aşerdiğim leylâk kokusundaysan Tanrım 

Şu tembellerin ortak duası

“Hayırlısı neyse” 

Ondan istiyorum ben de 

Pesimist’in pesti

Pes

Sesime bir ses...', '- Günay''a- Her sabah uyandığımda Mevsimsiz aşerdiğim leylâk kokusundaysan Tanrım  Bırak peşimi, bana acı Ben sürgünüm, hem küskünüm bir de y...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dua-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşkenceler Ver Bana', 'i-skenceler-ver-bana-i-smail-sahin-9hyhz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir  ölüm  ver  bana, en  acısından

Mahşeri  olmasın,  doğuşu  olmasın

Bir  yolculuk  ver  bana,  en  uzağından

Hudutu  olmasın,  dönüşü  olmasın

Vereceğin  dağların  geçiti  olmasın

Uçurumlar ver uzanacak  dalı

Altında  tutanı  olmasın

Meyvesi  yoksa,  ağaçlar  ver  bana

Gerçeği  yoksa  hayaller...

Karanlık  zindanlara  koy  beni

Denizlere  at  anahtarını

Bende  hiç  bir  ahın  kalmasın

Bir  acı  ver, zehir  edeyim  bu  hayatı', 'Bir  ölüm  ver  bana, en  acısından Mahşeri  olmasın,  doğuşu  olmasın Bir  yolculuk  ver  bana,  en  uzağından Hudutu  olmasın,  dönüşü  ol...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iskenceler-ver-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Çiçeği - 1', 'kir-cicegi-1-i-smail-sahin-7gdyp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Koşuşursun  dağlarda  kokunla

Bazan  bir  kaya  dibinde

Bazan  bir  yol  kenarında

Kır  çiçeğim

Durulur   ayağına  gelen  fırtınalar

Meltem  olur,  dizlerin  dibine  oturur

Gözlerine  serilir  tüm  saltanatlar

Kır  çiçeğim

Sıra  sıra  arkları  varsa  bağların

Susayınca  ben  senin  için  ağlarım

Saçın  okşayan  yağmuru  olur  dağların

Kır  çiçeğim

Yaprağın  değdir  kanayan  yaralarıma

Kırgınım,  uzun  yoldan  geldim,  yorgunum

Dizinde  dalayım,  unutulmuş  rüyalarıma

Kır çiçeğim', 'Koşuşursun  dağlarda  kokunla Bazan  bir  kaya  dibinde Bazan  bir  yol  kenarında Kır  çiçeğim Durulur   ayağına  gelen  fırtınalar Meltem ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kir-cicegi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-gurbuz-vural-nwdtm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir serçenin

rahminde doğurdum

sevdamı.

Onun içindir

serçe kadar 

ürkek sevdam...

Bir gülün 

gölgesinde büyüttüm

sevdamı.

Onun içindir 

acıların bile

güle çalışı...

                                   (...)', 'Bir serçenin rahminde doğurdum sevdamı. Onun içindir serçe kadar  ürkek sevdam... Bir gülün  gölgesinde büyüttüm sevdamı. Onun içindir  acıl...', ARRAY['Türk Edebiyatı','Şiir','Gürbüz Vural']::text[], 8.5, '{"poet":"Gürbüz Vural","poet_slug":"gurbuz-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdam-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Çiçeği - 2', 'kir-cicegi-2-i-smail-sahin-plyna', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmurlarını  paylaştığımız  şehirden

Ne bıraktın avuçlarıma  Kır  Çiçeği

Tüm  sokakların  zihni  çıkmazda

Kaldırım  kenarında  ağlıyorlar  kahırdan

Çamurlu  sular  sürüklüyor  geleceği

Açmaz  mıydı  buralarda  bir  Kır  Çiçeği

Ovalara  sığmayan  sofralardan  kalan

Nedir  şimdi  bahtımıza   Kır  Çiçeği

Üstün  körü  verilen  bir  artık  zaman

Şimdi  kim  oturur  benim  yerime

Gönlünün  en  güzel  tahtına  Kır  Çiçeği

Nerde... Nerde  şimdi  benim  rüyam

Karanlıklar  revamı  verdiğin  göklere

Yeter  üzdüğün  gel  artık  Kır  Çiçeği', 'Yağmurlarını  paylaştığımız  şehirden Ne bıraktın avuçlarıma  Kır  Çiçeği Tüm  sokakların  zihni  çıkmazda Kaldırım  kenarında  ağlıyorlar  ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kir-cicegi-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoktun', 'sen-yoktun-i-smail-sahin-hew30', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni  en  son  sevdiğimde  Dost

Gözleri  hayatımın  yazgısı

Sen  yoktun

Her  bakışta  umutsuzluğum

Acizliğim,  kavrulduğum

Seni  en  son  sevdiğimde  Dost

Saçları  karanlık  karası

Sen  yoktun

Kıvrımlarında  yok  olduğum

Kokusunda  sarhoşluğum

Hayat  ağır,  yaşamak  zordu

Ölüm  rezil;  sen  yoktun

Beni  en  son  üzdüğünde  Dost

Hiç  eskimemiş  hayallerin

Rahatça  bir  yatağın  vardı

Ben  yoktum

Filizlerin  yeşeriyordu

Hayatın  bereketliydi

Beni  en  son  üzdüğünde  Dost

Hala  yürüyebiliyordun

Düz  ve  geniş  ovarında  sen

Ben  yoktum

Dünyaya  gülebiliyordun

Mutluluğa  varıyordun

Beni  en  son  öldürdüğünde Dost

(acı  hafif  yansıdı  mısraya) 

Kırıyordu biraz kimsesizliğin havası

Sen yoktun

Ağıt yüzde değil  yüreğimde

Akmadı

Hayat ağır, yaşamak zordu

Ölüm rezil, sen yoktun', 'Seni  en  son  sevdiğimde  Dost Gözleri  hayatımın  yazgısı Sen  yoktun Her  bakışta  umutsuzluğum Acizliğim,  kavrulduğum Seni  en  son  se...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sen-yoktun-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-hakan-arikan-g5pq9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her ayrılığın ardından,

Bir şeyler uçup gider yüreğimden,

Ardına bakmadan.

Gebe kalır ruhum,

Yalnızlıklara,

Hüzünlere,

Sancılı bir doğum öncesinde.

Saklanırım en kuytu köşelere,

Ağlamak için gizlice.

Sözler veririm kendime,

Bir daha sevmeyeceğime.

Her şey yabancılaşır,

Uzaklaşır benden; 

Dolaştığım sokaklar,

Paylaştığım dostlar.

Zamanı geldiğinde,

Hüzne gebe kalır ruhum,

Bahara,

Sevdaya gebe kalır birden.

İşte; 

O zaman çıkarım gene unuttuğum sokaklara,

Koşarım,

Paylaştığım dostlara,

Sırf inat olsun diye ayrılığa.

Ankara Ocak 2003', 'Her ayrılığın ardından, Bir şeyler uçup gider yüreğimden, Ardına bakmadan. Gebe kalır ruhum, Yalnızlıklara, Hüzünlere, Sancılı bir doğum önc...', ARRAY['Türk Edebiyatı','Şiir','Hakan Arıkan']::text[], 8.5, '{"poet":"Hakan Arıkan","poet_slug":"hakan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ayrilik-164-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şuan Nerdeyim?', 'suan-nerdeyim-i-smail-sahin-jum9a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şuan  nerdeyim? 

Beşiğinde  sallandığın  parkta

Ancak; 

Ne  sallanan  bir  kız  var  beşikte

Ne  de  onu  izleyen  bir  genç  bankta.

Şuan  nerdeyim? 

Yürüyorum...

Geceleri  gezindiğimiz  sokakta

Tutanım  olmasa  da  koluma  girip

Sürünüyorsam  da  yerlerde

Durabiliyorum  ben  hala  ayakta

Şuan nerdeyim? 

Kürek  çekiyorum  geleceğe

Sen  olmasan  da  kayıkta

Güneş  doğuyor,  gece  çöküyor

Yürek dökülse de geçmişe

Hayat  akıp  gidiyor

Damla  su  olmasa  da  yatakta.

Şuan  nerdeyim?', 'Şuan  nerdeyim?  Beşiğinde  sallandığın  parkta Ancak;  Ne  sallanan  bir  kız  var  beşikte Ne  de  onu  izleyen  bir  genç  bankta. Şuan  ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/suan-nerdeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lodos', 'lodos-hakan-arikan-sidtr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gece lodos; 

İntikam alıyor tüm bulutlar dan,

Siayhını,beyazını ayırmadan.

Besbelli maviyi özlemiş.

O kadaf öfkeli,vurdumduymaz ki,

Hışımla geçiyor,

Karanlık sokaklardan,

Tüm geçmişten,

Hüzünlü özlemlerden.

Halbuki; 

sabah olunca uslanacak.

Tıpkı çocuk misali; 

Uykuya dalacak,

Mavisinin koynun da,

Güneşin sıcaklığın da.

Biliyor musun? 

Benim hiç mavim olmadı.

Ne şiirler de,

Ne de uyandığım sabahlar da.

O yüzden; 

Ne zaman lodos çıksa,

Tenim üşür,yüreğim donar onda.

Lodosun mavi aşk şarkılarını dinlerim,

Karanlık odam da,

Sarı koltuğum da,

Tenim üşür,

Yüreğim donar her lodos ta.

Biliyor musun? 

Hiç mavim olmadı benim,

Ne lodos ta

Ne de Aşk ta.

Ankara Aralık 2002', 'Bu gece lodos;  İntikam alıyor tüm bulutlar dan, Siayhını,beyazını ayırmadan. Besbelli maviyi özlemiş. O kadaf öfkeli,vurdumduymaz ki, Hışım...', ARRAY['Türk Edebiyatı','Şiir','Hakan Arıkan']::text[], 8.5, '{"poet":"Hakan Arıkan","poet_slug":"hakan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/lodos-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun', 'yoklugun-i-smail-sahin-j36yl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen giderken  güneşi  koyucam  cebine

Olur  ya!  Üşürsün  diye  ayazlarda

Sen  giderken son gülücüğümü vericem yüzüne

Olur ya! Üzülürsün diye yollarda

Sen  giderken...  Her  şeyi...

Son  kibriti,  umudu,  son  parçayı

Sokuşturucam  cebine

Son  kanı,  şiirimi,  son  canı,  sesimi

Vericem  sana. Olur  ya..! 

Sen  giderken...  Her  şeyi...

Diyorsun  ki “  Duyar  mısın,  yokluğumu? “

-  Hayır

Bir  sen  varsın  ama 

Var  olmak  kavramının  içinde

Geceleri  karanlığını  çaldığım  sokakları

Kafe Eski’ yi  unutuyorsun

Bir  de  oturduğumuz  o  masayı

(Yokluğunu  nasıl  hissetmemi  bekliyorsun) 

Bir  de  korkumu,  yalnızlığımı,  soğuğumu,

Kimsesizliğimi,  gözyaşlarımı

Napayım  alıcam  senden  de  bir şeyler

Bir  kaç  avare  adım  bahçede  atılacak

Bir  masa,  bir  ağaç,  yalnız  oturacak

Yaralar,  hasretler,  buhranlar,  bekleyişler

Belki  biraz  da

Yıkılan  dünyanın  altından  attığın  gülücükler

Alıp  savurayım  sözlerimi  havaya

Yere  düşmeyecek,  şehir  duracak

Sen giderken hayatımı vericem sana

Çünkü sensiz ihtiyacım olmayacak                                                                    

Sen giderken... Her şeyi..', 'Sen giderken  güneşi  koyucam  cebine Olur  ya!  Üşürsün  diye  ayazlarda Sen  giderken son gülücüğümü vericem yüzüne Olur ya! Üzülürsün diy...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yoklugun-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk', 'cocukluk-hakan-arikan-4ua4f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocukluğumu istiyorum; 

Bahçelereden mevya çalmak,

Sapanımla sokak lambalarını kırmak,

Ellerim çatlayıncaya kadar,

Misket oynamak için.

Çocukluğumu istiyorum; 

Bütün harçlığımı horoz şekerine yatırmak,

Bayramlık ayakkabılarımla top oynamak,

Hayat bilgisi kitabımın arasın da,

Teksas Tommiks okumak için.

Ben büyümek istemiyorum.

Biliyorum büyürsem; 

Aşık olacağım,

Özleyeceğim,

Ve yüreğim acıyacak.

Ben ne aşk,

Ne özlem

Ben sadece çocukluğumu istiyorum

Ankara Aralık 2002', 'Çocukluğumu istiyorum;  Bahçelereden mevya çalmak, Sapanımla sokak lambalarını kırmak, Ellerim çatlayıncaya kadar, Misket oynamak için. Çocu...', ARRAY['Türk Edebiyatı','Şiir','Hakan Arıkan']::text[], 8.5, '{"poet":"Hakan Arıkan","poet_slug":"hakan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cocukluk-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamazsın...', 'unutamazsin-yusuf-ziya-leblebici-vmhrt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni unutmak kolay değil, yıllar bir bir geçse de

Hatıralarım bırakmaz ki, sen hiç istemesen de

Vebalim peşini bırakmaz diyarlara gitsen de

Sen bir beni unutamazsın, başkasını sevsen de

Sevdamı kazıyamazsın, istesen de o kalbinden

Maziler peşini bırakmaz, koşarlar hep gölgenden

Unutmak o kadar kolay mı, silemezsin içinden

Silemezsin atamazsın sen bu aşkı yüreğinden

Senin peşin sıra gelirim, ben kabusun olurum

Kaçma kurtulamazsın benden, gece düşün olurum

Nereye baksan ben çıkarım, senin aynan olurum

Yüzünü yıkamak için su, baktığın göz olurum', 'Beni unutmak kolay değil, yıllar bir bir geçse de Hatıralarım bırakmaz ki, sen hiç istemesen de Vebalim peşini bırakmaz diyarlara gitsen de ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutamazsin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecelerin dervişi...', 'gecelerin-dervisi-yusuf-ziya-leblebici-rhiv0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sokaktaki kör lambaların pusulu loşluğunda

Üstünde olsa da kendini arar sisli gözlerim

Topal yolların berduşvari dönen sarhoşluğunda

Üşüyerek sokaklara serilir titrek bedenim

Aydınlık gün zıtlaşıp, geceye boyandığında

Sanki kaybetmişçesine beyazlık arar ellerim

Demir atarım bu şehrin ıssız kaldırımlarına

Ben gündüzlerin kaçağı, gecelerin dervişiyim

Gökyüzünün kızarıp, yağmurun mızraklaştığında

Yangın olmak isterim, içimi de yakmak isterim

Azrail''i kıskandıracak yüreğimdeki sevdayla

Karanlığın üstüne üstüne erkekçe giderim

Balıkçı türkülerinin kaybolduğu limanlarda

Uyku bilmeyen yakamozların bir divanesiyim

Balıklara karayı şikayet eden nutuklarla

Ben toprakların kaçağı, gecelerin dervişiyim

Taşı düşman, toprağı beton olan bu İstanbul''da

Sabahçı kahvelerinin uykusuz bir köşesiyim

Kanunların inlediği gecenin orta yolunda

İnsanları mest eden bir nihavent şarkı dizesiyim', 'Sokaktaki kör lambaların pusulu loşluğunda Üstünde olsa da kendini arar sisli gözlerim Topal yolların berduşvari dönen sarhoşluğunda Üşüyere...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gecelerin-dervisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaşımsın', 'savasimsin-yusuf-ziya-leblebici-svfqy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her gece uyku diye yatmışım senin sevdana

Açtığım bayrak, içtiğim sevda andı olmuşsun

Şevkim olmuşsun sen, onurlu yaşamsal kavgamda

Memleketimsin sen, benim insanımın korusun

Yüreğimin mantığımla kutupsal savaşında

Her saldırının önüne sanki bir set koymuşsun

Mantığın silah, yüreğin insan olduğu anda

Arkasına gizlenen, yıkılmayan güç olmuşsun

''Dönün'' diye haykırmışsın benden kaçan kuşlara

Düşmanımın önüne kendini siper koymuşsun

Bayrak açmışsın seni istemeyen mantığıma

Dostun olan yüreğime şevk verip volkan olmuşsun

Nam salmışsın sen yüreğimin karlı dağlarında

Dağlarımın eşkiyalarını sen korkutmuşsun

Senin için çarpışılan savaş meydanlarına

Bu sevdanın acı adını kazıyıp koymuşsun', 'Her gece uyku diye yatmışım senin sevdana Açtığım bayrak, içtiğim sevda andı olmuşsun Şevkim olmuşsun sen, onurlu yaşamsal kavgamda Memleket...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/savasimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri', 'serseri-hakan-arikan-wzfih', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Canım gökyüzünde bulutlar istiyor,

Beyaz ve siyah renkli bulutlar.

Beyaz bulutlara sevdamı,

Siyah bulutlara hasretimi yükleyip,

Sana göndermek için.

Canım; 

Bu akşam ecel istiyor.

Uzaklar da bile olsa,

Ruhum sevdamın gölgesi olsun diye.

Canım; 

Bu akşam gitmek istiyor.

Ümitsiz sevdaların bile

Hiç ölmediği mezarlıklara.

Canım; 

Tatlı bir şeyler istiyor.

Canım dudaklarını; 

Tatlının ilk tadını tattığım dudaklarını.

Canım; 

Günah istiyor.

Günahların en tatlısına,

Koynun da girmek istiyor.

Canım; 

Adam olmak istiyor.

Senin yanında,

Dimdik ayakta.

Canım; 

Aşk istiyor.

Canım tatlıyla,

Canım günahla,

Aşk ve sevgiyle,

Canım; 

Canım,sadece seni istiyor.

Ankara Şubat 2003', 'Canım gökyüzünde bulutlar istiyor, Beyaz ve siyah renkli bulutlar. Beyaz bulutlara sevdamı, Siyah bulutlara hasretimi yükleyip, Sana gönderm...', ARRAY['Türk Edebiyatı','Şiir','Hakan Arıkan']::text[], 8.5, '{"poet":"Hakan Arıkan","poet_slug":"hakan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/serseri-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sabah', 'bir-sabah-abdullah-alageyik-0ub3b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sabah vakti ayrılırım senden

Daha gözlerini açmadan

Gece muhabbetinin verdiği ağır uykudan

Siyah iplik beyaz iplikten

Ayırt edilmeden

Sıyrılırım renk katamadığım düşlerinden

Bir sabah vakti ayrılırım senden

Uykunun verdiği sersemlikle

Neler kaybettiğimi bilmeden

Yorgun yollara düşerdim

Daha seni içimde öldürmeden

Bir sabah vakti ayrılırım senden

Tüm güzel şeyleri bırakarak

Aramızda geçen anları

Sırt çantama yüklemeden

Unutarak ayrılırım 

Gözlerin gözlerime düşmeden

Bir sabah vakti ayrılırım senden

Tan ağarmadan

Horozlar ötmeye başlamadan

Ve uyanmadan içimdeki sen

Seni öylece bırakarak ayrılırım

Bir sabah erken

bir sabah vakti ayrılırım senden

daha şehir uyanmadan

kalabalıklaşmadan sokaklar

kaldırımlara basmadan

günaha giden ayaklar

sessizce ayrılırım senden

arkamdan ağlaşsada kuşlar

bir sabah vakti ayrılırım senden

çünkü sabah ayrılması kolay olur

beni aşka çağıran gözlerinden

ve beni amansız  kıskıvrak

yakalayan  sözlerinden,

en aciz anımda...

biliyorum gidişim komaz sana 

ayrılığın acısını hissetmessin

aşk tomurcuğu içinde olgunlaşmamışsa

biliyorum yokluğum bile hissedilmez

daha nicelerinin giremediği o yüreğinde

herşeye  rağmen 

bir sabah vakti ayrılırım senden

aşkımı   canıma hipotek etsemde

                 

                                          06:01:2003', 'Bir sabah vakti ayrılırım senden Daha gözlerini açmadan Gece muhabbetinin verdiği ağır uykudan Siyah iplik beyaz iplikten Ayırt edilmeden Sı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Alageyik']::text[], 8.5, '{"poet":"Abdullah Alageyik","poet_slug":"abdullah-alageyik","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bir-sabah-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki kurşun', 'i-ki-kursun-umut-gungor-u0qsl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğimde iki kurşun vardı,

Doktorlar birini çıkardı,

Ya ikincisi diyecek oldum,

Sevda kurşunu çıkmaz dediler.', 'Yüreğimde iki kurşun vardı, Doktorlar birini çıkardı, Ya ikincisi diyecek oldum, Sevda kurşunu çıkmaz dediler....', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/iki-kursun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Neme Güveneyim', 'ben-neme-guveneyim-erdal-sayil-c9xtw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlmim yok, amelim yok; 

Ben neme güveneyim...? 

Günah mı, sayılmaz, çok; 

Ben neme güveneyim...? 

Gireyim desem yola,

Nefsim benle kolkola,

Akibetim hayrola,

Ben neme güveneyim..? 

Akıl küçük şaşıyor,

Bazen haddi aşıyor,

Kovalasam kaçıyor; 

Ben neme güveneyim...? 

Şeytan vermiş el ele,

Günah diyor, gel hele,

Şehvetim başa bela,

Ben neme güveneyim...? 

Bir iken aklın yolu,

Çekiyor sağı-solu,

Vesveseyle dopdolu; 

Ben neme güveneyim...? 

İbadet, güzel,kolay; 

Yaparsan azığın say,

Evvel aklım olsa hayy,

Ben neme güveneyim...? 

Yalnızım, çaresizim,

Sessizim, naresizim,

Bölündüm, paresizim; 

Ben neme güveneyim...? 

Allah''ım eyle yardım; 

Senin yoluna vardım,

Rahmetin nefse sardım; 

Başka yok güveneyim...!', 'İlmim yok, amelim yok;  Ben neme güveneyim...?  Günah mı, sayılmaz, çok;  Ben neme güveneyim...?  Gireyim desem yola, Nefsim benle kolkola, ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sayıl']::text[], 8.5, '{"poet":"Erdal Sayıl","poet_slug":"erdal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ben-neme-guveneyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karmaşık Sözler', 'karmasik-sozler-abdullah-alageyik-kkb55', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyorum karmaşık sözler benimkisi

Arenaya çıkmadan anlaşılmaz,matador,boğamı

yoksa cılız bir genç mi en iyisi

Eskimo''dur sırtına yükleyip evini

Kutuplarda don tutan

Buz kayalarda yaşamayı en iyi bilen birisi

Biliyorum karmaşık anlatım benimkisi

Karmaşık kafamdan dökülen

Bir türlü birleşmeyen

Asi sözcük hüzmesi

Anlatmak benden gizli kalmış duyguları 

Anlamak sizden gayri gerisi

Biliyorum karmak bir bakış benimkisi

Ama görülmeyeni görüyorum hep

Taşralı bali çeken veletleri

Kan tutmaktan moraran yürekleri

Ve haksızlığa başkaldırmayı bekleyen

Bekledikçe felç geçiren elleri

Ne bileyim görüyorum işte 

seni ve cıvlıtısıyla  parlak gözlerini

belki ondandır anlamsız bakışlarınız

dışlar  feryat  eden sözlerimi', 'Biliyorum karmaşık sözler benimkisi Arenaya çıkmadan anlaşılmaz,matador,boğamı yoksa cılız bir genç mi en iyisi Eskimo''dur sırtına yükleyip ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Alageyik']::text[], 8.5, '{"poet":"Abdullah Alageyik","poet_slug":"abdullah-alageyik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/karmasik-sozler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-hakan-arikan-l5bl3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden erken uyudun ki? 

Oysa; 

Seni ne kadar çok sevdiğimi yeniden anlatacak,

Sana özlemimle,

Yüreğimin ucunu yeniden yakacaktım.

Neden erken uyudun ki? 

Gözlerinden akan her damla yaşı tek tek öpecek,

Sen uyumadan önce,

Koynuna girecektim.

Neden erken uyudun ki? 

Daha sensizliğin ne demek olduğunu anlatacak,

Şiirlerle ben seni uyutacaktım.

Neden erken uyudun ki? 

Seni ne kadar sevdiğimi henüz söylememiştim.

İyi geceler kara sevdam,

Sen uyurken; 

Seni ne kadar sevdiğimi,

Kulağına fısıldadım.

İyi ki erken uyudun.

Ne bunları uyumadan önce sana söyliyebilir,

Ne de; 

Güneşten önce sana günaydın diyebilirdim.

Günaydın kara sevdam,

Günaydın güneş gözlüm,

Günaydın kadınım.

Seni seviyorum.

Ankara Mart 2003', 'Neden erken uyudun ki?  Oysa;  Seni ne kadar çok sevdiğimi yeniden anlatacak, Sana özlemimle, Yüreğimin ucunu yeniden yakacaktım. Neden erke...', ARRAY['Türk Edebiyatı','Şiir','Hakan Arıkan']::text[], 8.5, '{"poet":"Hakan Arıkan","poet_slug":"hakan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/neden-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehri Terketmek', 'bu-sehri-terketmek-cem-ozdemir-52xyu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '...anladım

yaşanmaz artık

gitmek gerek buralardan

terketmek lazım bu şehri...

toplayıp tası-tarağı.. ne varsa

hatırda kalan

bir kaç tatlı anı mesela

bir de ceketi vurup omuza

düşmek lazım yollara

artık yollar nereye götürür

kendi bildiğince

rüzgar nereye savurur

kendi estiğince

bilinmez.. ama

...bildiğim bir şey var ki

o da.. gitmek gerek buralardan

terketmek lazım bu şehri...

yoksa.. diyorum

ayıp mı olur 

geçen yıllara.. ve

yazık mı olur

o yıllarda yaşanan onca hatıraya

o hatıralar ki

her birinde senin adın yazılı

sen onlarda yaşıyorsun

bir tek.. burada yanımda yoksun

yani.. hem varsın.. hem yoksun

yani.. hem bendesin.. hem değilsin

ben de buna yaşamak diyorum

olmaz ki

böyle de yaşanmaz ki

...onun için

gitmek gerek buralardan

ve bir an önce

terketmek lazım bu şehri...', '...anladım yaşanmaz artık gitmek gerek buralardan terketmek lazım bu şehri... toplayıp tası-tarağı.. ne varsa hatırda kalan bir kaç tatlı an...', ARRAY['Türk Edebiyatı','Şiir','Cem Özdemir']::text[], 8.5, '{"poet":"Cem Özdemir","poet_slug":"cem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bu-sehri-terketmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıyrılış', 'siyrilis-abdullah-alageyik-gbi7b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir düş ölür yüreğimin 

Geçit vermez alanlarında

Ve bir sevda tüm haşmetiyle

Yıkar tabularımı yerleşir dünyama

Bir sen olurum bir ben

Bir yıkılırım bir ayağa kalkarım

Her şeye rağmen

Yürürüm dar sokakların

Çirkeflik bulanam yollarında

Aklıma hep sen gelirsin

Yine bulantılar düşüncesiz tavırlar

Hamile bir kadından 

Dostane  garip yaklaşımlar

Bir anne özlemi sarar beni  ağlarım

O an dizginsiz kalır

şaha kalkan atlarım...

Kıpırtısızdır ölen bir kuş

Cansız bedenin için önemsizdir

Önüne çıksada dik bir yokuş

Gece karanlığında baykuş

Sepeserpilmiş gün ışığında

Kanadı kırık bir kuş görürsen

işte o benim

Yalan dolu bir hayattan

Ani bir sıyrılış', 'Bir düş ölür yüreğimin  Geçit vermez alanlarında Ve bir sevda tüm haşmetiyle Yıkar tabularımı yerleşir dünyama Bir sen olurum bir ben Bir yı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Alageyik']::text[], 8.5, '{"poet":"Abdullah Alageyik","poet_slug":"abdullah-alageyik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/siyrilis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güldü', 'bir-guldu-ufuk-nazim-zmdfm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir güldü 

Uzatılan güle.

Uzak bir iklimin 

Ayaz kokusuydun simdi.

Sert rüzgarlarla sınanmış

Hıncında yüzen 

Berrak gözlerinle

İsyanın bulaştığı 

Eşsiz güzelliğinle

Yanımdaydın işte

Zoraki mi? gülümsüyordun

Olsun ben sana sarıldım

İnadına kavradım seni

Kollarımla inadına.

Ve bir gül uzattım güle

Dikenleri içinde

Özgürlüğünü arayan

Kıpkızıl bir gül.', 'Bir güldü  Uzatılan güle. Uzak bir iklimin  Ayaz kokusuydun simdi. Sert rüzgarlarla sınanmış Hıncında yüzen  Berrak gözlerinle İsyanın bulaş...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-guldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Gül', 'kirmizi-gul-ufuk-nazim-g30ey', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidiyorsun

Her şeyi koyup bir

Göz yaşına

Gidiyorsun işte.

Bir yudum çay kadar

Zamanım kaldı,

Gidiyorsun işte.

Göçmen kuşların hüzünlü

Kanatları gibi

Sarılası kolların.

Uçuyorsun bir

Kontrol kabininden

Usulca süzülen 

Bir kırlangıçsın.

Ve şimdi

Dizginlerinden boşanan

Duygu yüklü bir arabadayım

Gün ağarmakta 

Tatlı bir rüyada

Kıpkızıl bir şafak 

Ufkun boynuna atılmakta.

Kızıl bir kement gibi

Sımsıkı sarmakta.

Ve yol kenarında

Kırmızı bir gül

Dolu dolu gözleriyle

Ağlamakta.', 'Gidiyorsun Her şeyi koyup bir Göz yaşına Gidiyorsun işte. Bir yudum çay kadar Zamanım kaldı, Gidiyorsun işte. Göçmen kuşların hüzünlü Kanatl...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kirmizi-gul-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-ufuk-nazim-sr106', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bekleyiştir yaşam

Sınanırken ırmaklarda

Taşların sağlamlığı.

Uğuldarken zamanın

Göğe ırayan kayaları

Susmak

Sessiz ve sakin

Bakmak lazım

Bütün ıssızlığa....', 'Bekleyiştir yaşam Sınanırken ırmaklarda Taşların sağlamlığı. Uğuldarken zamanın Göğe ırayan kayaları Susmak Sessiz ve sakin Bakmak lazım Büt...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bekleyis-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta koyan bulunur', 'nokta-koyan-bulunur-sair-ahrazi-4jqkv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok güvenme kaleme ardı sıra dolanma,

Bâzı ilim gereği ona kıyan bulunur.

Dile muhtâç sanırsın sükût ile gezeni,

O sükûtun içinde nice beyân bulunur.

Fikri alıp eline hallaç gibi savursan,

Perde çekip gözüne uyu diyen bulunur.

İki kulak arası bilen için hazîne,

Fakir kişi düşünsün bizi duyan bulunur.

Dilbâz olma Ahrâzı’ vakit susma vaktidir,

Adın sükût olsa da nokta koyan bulunur.

Her mânâyı bırakıp hatâ için gelenler,

O hatânın yanında ‘’ı’’yı ayan bulunur.', 'Çok güvenme kaleme ardı sıra dolanma, Bâzı ilim gereği ona kıyan bulunur. Dile muhtâç sanırsın sükût ile gezeni, O sükûtun içinde nice beyân...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nokta-koyan-bulunur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yoksun ya!', 'sen-yoksun-ya-yusuf-ziya-leblebici-5zsbk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ha sokak, ha otel odaları

Sen yoksun ya ne farkeder

Ne yemek, ne de içtiğim rakı

Sen yoksun ya kar mı eder

Özlemek ve sevmek acıları

Bana göre mi bu keder

Ağlamak, anınca hatıramı

Sen yoksun ya ne farkeder

Mesken tutmuşum sokakları

Bu adam ne yapar ne eder

Boşver benim bu acılarımı

Sen yoksun ya ne farkeder

Ağlıyormuşum içince meyi

Herkes bir tek bana güler

Yığılırmışım duyunca sen

Sen yoksun ya ne farkeder

Atmışım gömleğimi çorabı

Acı giydim daha beter

Çıplak yürüyorum kaldırımı

Sen yoksun ya ne farkeder', 'Ha sokak, ha otel odaları Sen yoksun ya ne farkeder Ne yemek, ne de içtiğim rakı Sen yoksun ya kar mı eder Özlemek ve sevmek acıları Bana gö...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-yoksun-ya-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım...', 'kadinim-yusuf-ziya-leblebici-qcump', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimde lokmayı sevgiye bandığım

Verdiğin mutluluğun suyuna kandığım

Ortak nefessin sen ciğerime aldığım

Bu günümde benim yarımınsın kadınım

Gözlerim kapanırken seninle uyurum

Güneşin doğuşunu seninle bulurum

Seninle olgun, seninle çocuk olurum

Sen mevsimlerimden baharımsın kadınım

Soframa aş yatağıma baş koyan

Derdime derman marazıma deva olan

Gönlümün yarımısın, bensiz yarım kalan

Beni yüreğinde taşıyansın kadınım', 'Yüreğimde lokmayı sevgiye bandığım Verdiğin mutluluğun suyuna kandığım Ortak nefessin sen ciğerime aldığım Bu günümde benim yarımınsın kadın...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kadinim-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyayı kusacağım...', 'dunyayi-kusacagim-yusuf-ziya-leblebici-n02j9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne etrafımızı çeviren gurbetsi duvar

Ne de aç karnına her gün yediğimiz şamar

Silemedi ki, sildiremedi bu hasreti

Toprak atsalar da üzerine azar azar

Adımlarım gecenin ormanına yol koyar

Ben sustukça türküler susar rüzgar uğuldar

Ben sustukça içim kanar yapraklar hışırdar

Kafamı eğdikçe ayaklarım seni arar

Ben yürüdükçe adımlarım sise bürünmüş

Ben yürüdükçe yollar parçalara bölünmüş

Ne adımlarım sana, ne sen bana gelirsin

Ancak gözümleki yaşta sandalla gezersin

Oysa, yüreğimdeki çıbanın inadına

Tatlı bir dolama olsaydın da parmağımda

Süzülerek yayılsaydın şu avuçlarıma

Nasırlarıma inseydin o sıcaklığınla

Dost bildiğim kararası kara akşamlarda

Sarsaydın beni bir oyanın yumağı gibi

Çıkıp gelseydin şehrin ara sokaklarından

Çöpçü misali dertlerimi süpürür gibi

Bir simidi ikiye bölüp de yediğimiz

Düşvari gerçeklere esen yel dediğimiz

Sevdamızı tütün niyetine çektiğimiz

O günler var ya, bu güne biber ektiğimiz

Teninin, çiçekleri kıskandırırcasına

Menekşenin kokusunu bastırdığı günler

Daha sonra, gittiğin dünüm gelir aklıma

Sisli bir dağ gibi bulandırdın beni mayısta

Yine bu şehrin kapılarını kilitledim

Seni götüren haramiler kaçmasın diye

Caddeyi, sokağı derince içime çektim

Hikayeler yazıldı, gizlendi gözlerime

Bulandım yine, bozuk dünyayı kusacağım

Çekil oradan da, üstüne bari gelmesin

Çıplak ayaklarımla yıllarca dolaştığım

Ateş mezraları sakın seni de küllemesin', 'Ne etrafımızı çeviren gurbetsi duvar Ne de aç karnına her gün yediğimiz şamar Silemedi ki, sildiremedi bu hasreti Toprak atsalar da üzerine ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dunyayi-kusacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip', 'garip-dundar-dikmen-dqqz3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bir garibim İstanbul canavarının kucağında,

Kimsem yok; derdime derman, kuru ekmeğime yoldaş...

Bazen azgın dalgaları seyreder, hüzünlenirim bazen de,

Her gün yeni bir umutla kalkar, dolaşırım kaldırımları garip garip.

Ümide benzer birşey var içimde mutlu olacağım diye,

Dualarım bu umudun tükenmemesi için hep,

Ben de bir yuva kuracağım, rahat yüzü göreceğim elbet,

Ama yazan öyle yazmış; ''Sen dolaş garip garip...''

Neyim var şu yalan dünyada; bir yatak, bir yorgan,bir kilim.

Az kalsın unutuyordum en önemlisi kitaplarım: tek tesellim,

Bazen çekip gitmek geçiyor içimden meçhul sevgilime,

Yönünü bilmediğim bir trene atlamak ve uzaklaşmak bu şehirden. 

Ve yeşilliği bol yüce dağların sarp yamaçlarında,

Sürdürmek garipliğimi saf bir Anadolu köyünde,

Tanışmak ilk ve son aşkımla çeşme başında,

Kurtularak gariplikten ve son demlerimde mutlu olmak...

                                                                İstanbul  1996', 'Ben bir garibim İstanbul canavarının kucağında, Kimsem yok; derdime derman, kuru ekmeğime yoldaş... Bazen azgın dalgaları seyreder, hüzünlen...', ARRAY['Türk Edebiyatı','Şiir','Dündar Dikmen']::text[], 8.5, '{"poet":"Dündar Dikmen","poet_slug":"dundar-dikmen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/garip-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerden bilirdim...', 'nerden-bilirdim-yusuf-ziya-leblebici-eiq4t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölesiye yeminler etmiştin, hani sevmiştin beni

İnkar edip terkedip gideceğini nerden bilirdim

Öylesine sevmiştim ki, canıma can yapmıştım seni

Ben artık sevmiyorum diyeceğini nerden bilirdim

Baharımı yazımı, kalbimi verdim inandım sana

Bir gün beni bırakıp gideceğini nerden bilirdim

Her şeyim sensin, yaşadıklarım sensin diyordun bana

Beni mevsimlerden sileceğini nerden bilirdim

Hani hatıralar, yaşananlar unutulmaz diyordun

Yaşamamış gibi unutacağını nerden bilirdim

Beni hiç kimseye değişmezdin, delice seviyordun

Taş gibi kaldırıp da atacağını nerden bilirdim

Hani baktığın o gözdüm, kana kana içtiğin suydum

İçtiğin bardağı kırıp atacağını nerden bilirdim

Gönlündeki aşk çeşmesi, kokladığın kırmızı güldüm

Yapraklarımı bir bir kopartacağını nerden bilirdim

Benimle olmak hani cennetti, beni sevmek sevaptı

Bu acı günahı işleyeceğini nerden bilirdim

Benimle yaşamak, beni sevmek erişilmez hayattı

Beni terkedip de gideceğini nerden bilirdim', 'Ölesiye yeminler etmiştin, hani sevmiştin beni İnkar edip terkedip gideceğini nerden bilirdim Öylesine sevmiştim ki, canıma can yapmıştım se...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nerden-bilirdim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kemanlar sızlıyor...', 'kemanlar-sizliyor-yusuf-ziya-leblebici-4lqiw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu nasıl nakarat kahırlandırıyor

Gülerim der iken beni ağlatıyor

Bu ne biçim şarkı dağları yıkıyor

Kemanlar sızlıyor, şarkılar ağlıyor

Bu bam tellerinin kahırlı darbesi

Bu tiz seslerinin sağır eden sesi

Bu nasıl şarkı ağlatıyor güftesi

Dağıtıyor böyle yerleri gökleri

Korodaki sesler hüzünle titriyor

Yaşamışlığıma bir ağıt yakıyor

Şu inleyen nağmeler can çekişiyor

Kemanlar sızlıyor, şarkılar ağlıyor', 'Bu nasıl nakarat kahırlandırıyor Gülerim der iken beni ağlatıyor Bu ne biçim şarkı dağları yıkıyor Kemanlar sızlıyor, şarkılar ağlıyor Bu ba...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kemanlar-sizliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Bilemezsin..!', 'bilemezsin-hasan-basri-kale-exnqc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'nasıl da yakın olur

uzaklar

sen bende olunca

bilir misin.? 

nasıl da bitmez

yollar

varışı sen olunca

bilir misin.? 

nasıl da çabuk geçer

zaman

ben benden geçince / seninle

bilir misin.? 

nasıl bir kör düğüşündedir

içimdeki yangın / beynimdeki fırtına

yağmur gözlerinden / gözlerimi

ayıramadığımda

bilir misin.? 

nasıl bir ölümdür / yeniden

bir kez daha

ve

kaçıncı tekrarıdır bu yokluğun/ bitmeyen

bilir misin.? 

beni sende bırakıp

sensiz

dönüş

ne kadar sensiz ve

ne kadar sessizdir...

.........................................BİLEMEZSİN..!', 'nasıl da yakın olur uzaklar sen bende olunca bilir misin.?  nasıl da bitmez yollar varışı sen olunca bilir misin.?  nasıl da çabuk geçer zam...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bilemezsin-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Karşısında Sen Ha!', 'hayat-karsisinda-sen-ha-i-smail-sahin-1y1sn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her şeyin ulaşması gereken bir sonuç var ve sonuca giden hayatın umrunda değilsin sen. Hayat karşısında o kadar küçüksün ki, o ağır cüssesiyle, senin için rotasını değiştiremez. Kızmaya hakkın yok. Tüm insanlığı toplasan da arkana sen bir damlasın işte, döndüremezsin hayata meydan okuyan değirmeni.

Sana kırıklarını toplama demiyorum ama toplasan ne inşa edebilirsin, bu inşaatı ne kadar koruyabilirsin. Dünyanın en büyük depreminin olacağını bildiğin araziye saraylar dikmeye çalışmanın ne anlamı var. 

Yolun sonu başlangıç noktansa ulaşmak istediğin amaç hayallerde.

Sana yerinde kal demiyorum ama ne kadar koşarsan koş; bu maraton sadece bir kum taneciği üzerinde.

Anlam... Anlam dediğini duyuyorum. Varılmak istenen noktanın kendisine gelen yollara verdiği anlam, diyorsun. Sonu ölüme varan hangi yola mutluluğu, huzuru yüklüyorsun. O; kendince, anlamlar yükleyip de mutlu olduğunu sandığın yaşam; senin gerçeklerden kaçışın. Kendini kandırmaya da ihtiyacın var. Bu anlamsızlığa anlam veren sensin. Gerçek; ortada bir şey yok.

Her şeyin ulaşılması gereken bir sonuç var ve sonuca giden hayatın umrunda değilsin sen.', 'Her şeyin ulaşması gereken bir sonuç var ve sonuca giden hayatın umrunda değilsin sen. Hayat karşısında o kadar küçüksün ki, o ağır cüssesiy...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hayat-karsisinda-sen-ha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan Hayat', 'kaybolan-hayat-i-smail-sahin-rcapw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çekiliyor... 

Çekiliyor damarlardan kan, 

Bir deniz gibi mutluluk yatağından. 

Her şey düşüyor, 

Hüzünler asılmış dallarına ağaçların; 

Dayanamıyor kırılıyor,

Yapraklar düşüyor.

Yere düşmeden eskiyor yağmur taneleri. 

Gün doğmadan sabah eskiyor. 

Geceyi bağlamış rıhtıma kayıkçı. 

Vadiler açıyor göz yaşı yanaklarda; 

Yüzler eskiyor. 

Saçlar beyaz, gözler kanlı, ten beyaz, 

Eller titrek, beller bükük; 

Doğarken ilk nefeste 

Bedenler eskiyor. 

Yıkılıyor... 

Bir gece yatmadan önce, 

Hafif bir müzik, 

Çekerken tütünü parmak uçlarına kadar; 

Umutlar yıkılıyor. 

En tazesini, bayatını, iğrencini, 

En doğal olanını hiç dinlemeden; 

Yıkıyor mantık hayalleri. 

Bir acı tutuşturuyor avuçlara; 

Ölü yok, yolcu yok, dert yok, 

Kanama var; 

Yürekler acıyor. 

Hayaller yıkılıyor. 

Nereye koydum ben bunu? 

Kayıp mı ettim? Şimdi buradaydı. 

Otur. Sakin ol. Bir daha düşün. 

En son neredeydi?', 'Çekiliyor...  Çekiliyor damarlardan kan,  Bir deniz gibi mutluluk yatağından.  Her şey düşüyor,  Hüzünler asılmış dallarına ağaçların;  Daya...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kaybolan-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-fatih-eryilmaz-vt7sf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sigarayı bıraktım

Hiç içmiyorum

Senin özlemini yakıp içiyorum bitsin diye

Ben bitiyorum gençliğim bitiyor

Sen bitmiyorsun', 'Sigarayı bıraktım Hiç içmiyorum Senin özlemini yakıp içiyorum bitsin diye Ben bitiyorum gençliğim bitiyor Sen bitmiyorsun...', ARRAY['Türk Edebiyatı','Şiir','Fatih Eryılmaz']::text[], 8.5, '{"poet":"Fatih Eryılmaz","poet_slug":"fatih-eryilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sana-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kudüs - 1', 'kudus-1-i-smail-sahin-34zh7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni  ağlattın  Kudüs

Tanrının  gazabı  üzerime olsun

Dağ  taş  göz  yaşımla  beslensin

Yaşım  kanımla

Beni  üzdün  Kudüs

Ruhum  bir  damlada  boğulsun

Beni  ağlattın  Kudüs

Acın  acım  olduğunda  beri 

Yıkılan  duvarlarının  altında

Kalan  benim  bedenimdi

Beni  üzdün  Kudüs

Dua  eden  bendim  hastalığında

Beni  ağlattın  Kudüs

Gülemezken  esaretinin  hiddetiyle

Beni  düşman  bildin

Silleler  indirdin  yüreğime

Beni  üzdün  Kudüs

Mezarında  yatan  bendim', 'Beni  ağlattın  Kudüs Tanrının  gazabı  üzerime olsun Dağ  taş  göz  yaşımla  beslensin Yaşım  kanımla Beni  üzdün  Kudüs Ruhum  bir  damlad...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kudus-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kudüs - 4', 'kudus-4-i-smail-sahin-b6hna', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen de herkesler gibi ağaçlarımı kesip, 

Evlerimi yıkıp yağmaladığında beni; 

Yalnız kaldım. 

Gittin yolcu. 

Öylesine bir yalnızlıktı ki kimsesiz. 

Parmaklarının ucundan 

Bir damlayı silkeler gibi düştüm kumlara. 

Çaresizdim, kırgındım, sessiz.

Ağlamakla olmayacağını 

Anladığımda arkandan.

Kapattım kapılarımı. 

Yeniden filizler ektim 

Bana bıraktığın harabelere. 

Binalar kurdum tam 

Bıraktığın yerde 

“ Aman” dilemeden doğruldum; 

Bütün kırıntılarımı topladım yeniden. 

Belki acıdığından, 

Belki bir helal dilemek için 

Kapılarıma dayandın sonra. 

Korktum yolcu. 

Dikişler söküldü, yaralar kanamaya başladı,

 “Saracağım” dedin. “ Güven,dedin, 

Her şey senin istediğin gibi olacak 

Bak eksiklerin var 

Bahçelerinde güllerin açacak.” 

Görmediğim bir sihirle, 

Duymadığım sözlerle kırdım kapılarımı.

Yeniden seninle dünyayı sevdim. 

En güzel saraylarıma aldım seni. 

Meyvelerimi verdim, 

Sen gittikten sonra ektiğim 

Ağaçlardan toplayıp. 

Şiirler yazdım, şarkılar söyledim sana. 

Gözlerini güneş ettim gökyüzüme. 

Ben sana inandım yolcu. 

Sana güvendim. 

Tüm beyaz kağıtları, kalemleri, 

Silgileri verdim eline.

Uzun sürmedi doydun yolcu.

Sevgime doydun. 

İkramlarımın tuzunu beğenmedin önce 

Sonra “Meyvelerin bozuk,dedin, 

Sokakların tozlu, çamurlu. 

Delilerin var senin, bilgelerin cahil” dedin. 

Hor gördün. 

Ben sana dünyayı veremezdim 

Ama kendimi verdim. 

Kapılarımı kırarken söylemiştim; 

Ben kumdan yapıldım çünkü burası çöl. 

Bir acı bakışın dönerse üzerime 

Duramam ayakta demiştim. 

Unutmuşsun çoktan sen. 

Unutmuşum sen bir yolcusun. 

Unutmuşsun sen bir yolcusun.

Bilir misin yolcu; 

Bir kez daha talan ettikten sonra beni, 

Kapanırsa bu kapılar tekrar, 

Bir daha açılmazlar ne sana, 

Ne de bir başkasına. 

Hep dirilmekten bıktım ben. 

Bilir misin yıkmakta olduğun duvarlarım 

Benim son canımdı. 

Son canımı sana verdim yolcu. 

Son canımı sana.

Son canım. 

Bu son...

Biliyorum “kalmazsın” değil, 

“Kalamazsın” yolcu. 

Biliyorum idare ettin beni. 

Dedim ya,

Dünyayı veremem sana; 

Sadece kendimi verebilirim.

Gidebilmek için bahaneler ararsın, 

Aramaktansa “gidebilirsin” yolcu.', 'Sen de herkesler gibi ağaçlarımı kesip,  Evlerimi yıkıp yağmaladığında beni;  Yalnız kaldım.  Gittin yolcu.  Öylesine bir yalnızlıktı ki kim...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/kudus-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne oldu bize? ..', 'ne-oldu-bize-yusuf-ziya-leblebici-y543d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Davacıyız dedik

   davalıların arasına girdik.

Ne oldu bize böyle

   biz böyle değildik.

Davacıydık dünlerden

   bugün de aynı terane.

Hep isyan ettik

   ama, sesleri biz dinledik

vuramadık sazın bam teline

   biz söyledik biz dinledik.

El ele verdik isyan ettik

umudu yakalayacağız diye

halay çekip eğlendik.

Bugün de halay var içimizde

  biz de eğlendik

    eğlenenlerden davacıyız dedik.

Ne oldu bize böyle

   biz böyle değildik

Bu davanın çıkar bölümüne mi geçtik

yoksa; 

   kendimize mi yenildik! ..', 'Davacıyız dedik    davalıların arasına girdik. Ne oldu bize böyle    biz böyle değildik. Davacıydık dünlerden    bugün de aynı terane. Hep i...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ne-oldu-bize-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kudüs - 5', 'kudus-5-i-smail-sahin-2nxac', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toprağından aldığım güçle dururum ayakta. 

Tutunurdum ellerine, kollarına. 

Koşuşurduk seninle mutluluğa, 

İnsanlardan saklanarak. 

Bakışlarından hayat akardı, 

Bedenimdeki damarlara, gözlerime. 

Bir dünyamız vardı; 

Seninle benim. 

Gülerdik acırdık herkeslere 

Ve kıskanırdık birbirimizi. 

Neye bilmem, belki tanrıya

 –Çünkü seni düşünürdü gelirdi aklıma- 

Şükrederdim.

Meyveler vermeye başladım, 

Dallarımı uzattım dört bir yana, 

Ben annemi bile sende sevdim. 

Seni sınırların içinde vardı,

Yaşamak varsa eğer. 

Sonra sen sensiz kaldığını söyledin, 

Beni sensiz bıraktın, 

Kuşlar uçup gitti, 

Son kelebek çoktan öldü. 

Bir sürü böcek sardı bedenimi. 

Köklerim söküldü toprağından, 

Suyum bitti. 

Yalvarmak ne kadar rezilse 

Ağlamak o kadar rezil. 

Git diyene kalacağım demek 

O kadar rezil. 

Kızmadım her ağacın doğal sonuydu bu. 

Ötesini aramak kanunlara ters düşerdi. 

Varlığında nefes alışımın ücretiydi bu. 

Kırdın kollarımı, ocaklara attın; 

Doğaldı. 

Her şey iyiydi, hoştu ama bilir misin; 

Senin topraklarında çiçeklerin ekiliydi, 

Ormanların vardı.

Ama... 

Ama benim Kudüs’ üm bir teneydi.', 'Toprağından aldığım güçle dururum ayakta.  Tutunurdum ellerine, kollarına.  Koşuşurduk seninle mutluluğa,  İnsanlardan saklanarak.  Bakışlar...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/kudus-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kunduracı çırağı...', 'kunduraci-ciragi-yusuf-ziya-leblebici-46n26', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kunduracı çırağıydım

küçücük ellerimle pençe çakan

O çekici bazen elime

bazen de örse boş vuran...

Bir çıraktım ben

giyemediğim ayakkabılara kösele çakan

yarınlarına usta hayali taşıyan.

Küçücük dükkanda 

küçücük bir çıraktım ben.

Kunduralar elimin bağı

yırtıkları fakirin alın yazısı

el emeği nafakamızdı.

Gözüm kunduranın derisinde

aklım sokağın köşesinde

misket oynayan çocuklarda.

Onlar misketi kuyuya atar

ben haftalığımı anamın avucuna.

Onlar sokakta körebe

ben, küçücük dükkanda

badem yağlı boyalarla oynardım.

Bir kunduracı vardı

okul harçlığımı çıkardığım.

Üç metrekare dükkanda

dev gibi yürekli bir adam.

Kalın gözlüğündeki

kaşlarını unutamadığım

O dev yürekli adam benim babam...', 'Bir kunduracı çırağıydım küçücük ellerimle pençe çakan O çekici bazen elime bazen de örse boş vuran... Bir çıraktım ben giyemediğim ayakkabı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kunduraci-ciragi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zılgıt...', 'zilgit-yusuf-ziya-leblebici-wjnzn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İsyanın ardındaki ölüm ağıtı

 yabancı değil bize

  bu haykırış, bu zılgıt...

Taşı koysan taş ağlar

  dayanamaz taşlığı.

İlk kez değil 

  bu ağlayış, bu zılgıt

Ne Kızılırmak''tan bir çağlayış

  ne de bulutların kızgınlığı

    göze gelmez

      yüreğe akmaz

        ciğerlerin yakışı...

Vurdukça kızaran dizler

  ne acı hisseder, 

    ne de yanma

duydukça zılgıtı, ağlayan gözlere

   ne mendil dayanır, 

     ne de yazma

Bir zılgıttır anaların haykırışı

bir zılgıttır gelinlerin dağlayışı

Anadolu''nun ağlayışı...', 'İsyanın ardındaki ölüm ağıtı  yabancı değil bize   bu haykırış, bu zılgıt... Taşı koysan taş ağlar   dayanamaz taşlığı. İlk kez değil    bu ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zilgit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Acı Getirdim Avuçlarımda', 'sana-aci-getirdim-avuclarimda-i-smail-sahin-rckwm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin için acı topladım dün gece kaldırımlardan, 

en parke taşı arasında kalmışlarını seçtim. 

Hepsini toplayıp biriktirdim, en siyahlarını. 

Sana yıldızlar toplamak isterdim, 

en “ sen” olanlarını. 

Tek tek, atlamadan gezdim sokaklarda. 

Köşe başlarında bekleyen sersilerden birinin midemi, 

en çok da kalbimi deşmesini isteyerek. 

Senin için acı topladım karşılaştığım bir dilencinin elbisesinden, 

üşümüşlüğünden; acılar topladım 

bir fahişenin gözlerinden, gülen hüznünden. 

Dün gece senin için gezindim Kordon Boyu’ nda. 

Sana denizin dibinde birikmiş dönüşümü olmayan çöpler topladım. 

Sana bedenime sığmayan acılar toplayıp getirdim avuçlarımda. 

Sana kendimi topladım dün gece, 

bir fahişenin gözlerinden, kaldırımlardan, dilenciden; 

bir serserinin elinden mutluluk içmek isteyerek.', 'Senin için acı topladım dün gece kaldırımlardan,  en parke taşı arasında kalmışlarını seçtim.  Hepsini toplayıp biriktirdim, en siyahlarını....', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sana-aci-getirdim-avuclarimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sımsıcak Bir Geceydi', 'simsicak-bir-geceydi-elif-kerenciler-cl4qg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ugultulardan başka bırsey yoktu belki ama

müzik hala kulaklarımda

ve sen

sanki hala yanımdasın

aynı sandalyede

ne güzeldi gülüşün...

25.05.2004

Eskişehir- Drs prk', 'ugultulardan başka bırsey yoktu belki ama müzik hala kulaklarımda ve sen sanki hala yanımdasın aynı sandalyede ne güzeldi gülüşün... 25.05.2...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/simsicak-bir-geceydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Serenad’a Gömüldüm...seninle…', 'serenad-a-gomuldum-seninle-abir-zaki-sgj08', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşin sevgiyle durarak baktığı gibi ufuktan

Ay’ın denize mırıldandığı gibi dağların ardından

Sesinin yankısını duyuyorum meltem rüzgarından

Ve kayboldum sende ben…

Rüzgarın ruhumu sarıp sarmaladığı gibi

Yıldızların ürkek gözlerinde öpülmeyi beklediği gibi

Şarabından tatmak için ”O” an’ın yaklaştığı gibi

Kayboldum sende ben…

Aklımı başımdan alan bu sessizlikle

Varlığınla hayat buluyorum yeniden

Usulca kucaklamanı, sarılmanı özlerken

”O” an’ın tadını çıkarıyorum

Meltem gibi esintine ”ah çektiğimi“

Yansıtabilmek için

Ebedi Cennet bir kez daha bizi beklerken.... 

Çeviren:  M. Çelik

***************************************************************************************

To Be Serenaded…by you… 

as the sun poises lovingly on the horizon 

and the moon croons to the sea behind the mountains 

as I hear the echoes of your words …..in the breeze 

I am lost in you… 

as the wind sweeps into my soul 

and the startled eyes of the stars waiting to be kissed 

as the moments approach to savor your wine 

I am lost in you… 

and in this enchanted stillness 

yearning your smooth embrace 

to revive me in your essence 

enjoying the moments for ever 

while 

eternal heaven awaits us once more 

to echo the whispers, I once 

in your breeze, sighed for … 

May 20, 2004', 'Güneşin sevgiyle durarak baktığı gibi ufuktan Ay’ın denize mırıldandığı gibi dağların ardından Sesinin yankısını duyuyorum meltem rüzgarında...', ARRAY['Türk Edebiyatı','Şiir','Abir Zaki']::text[], 8.5, '{"poet":"Abir Zaki","poet_slug":"abir-zaki","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/serenad-a-gomuldum-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Yıldızım Olmadı Benim', 'hic-yildizim-olmadi-benim-i-smail-sahin-xeg8c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana  yıldızlar  vermek  isterdim; 

Ama  benim  hiç yıldızım  olmadı! 

Nehirler  kenarında  bir bataklıktım  sadece.

Damarlarımda  gelincikler  beslenmedi  benim.

Yamaçlarım  hep  sessiz  hep  kimsesizdi,

Hiçbir  yıldız  yanağımda  parlamadı.

Sana  yakamozlar  vermek  isterdim; 

Ama  benim  hiç  yıldızım  olmadı! 

Kurur  yerlere  düşerim,

Bir  çocuk  ezer,

Bir  rüzgar  alır  savrulurdum,

Umutlarım kırılıncaya dek  vurulıurdum.

Sana  meyve  olmak  isterdim,

Ama  benim  hiç  yıldızım  olmadı! 

Boşluklar  çalınca  bakışlarını,

Sinince  yüreğine  keder,

Bir  çocuğun  gözlerince,

Mutluluklar  vermek  isterdim  sana; 

Ama  benim  hiç  yıldızım  olmadı! 

Sadece  kuru bir  yapraktım  bataklıkta.', 'Sana  yıldızlar  vermek  isterdim;  Ama  benim  hiç yıldızım  olmadı!  Nehirler  kenarında  bir bataklıktım  sadece. Damarlarımda  gelincikl...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hic-yildizim-olmadi-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban', 'kurban-i-smail-sahin-u6lr3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İsimlerle, kavramlarla yaşamıyorum. 

Ben her şeyin özüyle, 

birebir tüm özellikleriyle ilişki kuruyorum.

Yağmur yağar... 

Bulut içimde, damla içimde, çamur içimde. 

Caddelerdeki otobüsler 

içimden geçip gider; 

yolcuları içimde,  duraklar içimde.

Hissedebiliyorum bir kafedeki insanları. 

Sanki hepsi gücünü benden alıyor. 

Ben onları hissetmeyiversem ölecekler. 

Acı çekiyorum ki onlar mutlu olsun. 

Tanrıya 

tüm insanlığın yaşam diyetini ödüyorum. 

Çekilsem aradan olmaz; 

onlar tanrıyla karşılaşamazlar.

Tüm denizlerin kıyısıdır yüreğim, 

yataklarında ben tutarım. 

Gökyüzü  gözlerimin kabında. 

Balık içimde, olta içimde, balıkçı içimde. 

Kafes içimde, serçe içimde, şahin içimde.

Zihnim tüm insanları klozeti, 

zihnimin klozeti yüreğim.', 'İsimlerle, kavramlarla yaşamıyorum.  Ben her şeyin özüyle,  birebir tüm özellikleriyle ilişki kuruyorum. Yağmur yağar...  Bulut içimde, daml...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kurban-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıkılmadım Acımdan', 'sikilmadim-acimdan-i-smail-sahin-b4fk0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Edebiyat...

Yüreğinin içine sokarsın 

Kaleminin sivri ucunu, 

En derinlere banarsın...

Kor haline gelen hislerin kelimeleşir; 

Yan yana gelip resimler çizer bir beyaz kağıda.

Senin her bir harfinde titrediğin, 

Bu tabloyu görenler; 

Sadece edebiyat yapıyor derler.

Hayır! Durun.

Bırak onları sadece sen dur. 

Bir dinle ne olur! 

Edebiyat yapıyorsam nedir bu yaralarım, 

Seni düşünürken ellerimde düşen hayatım.

Ne oldu, nasıl olmalıydı.? 

Ne yapmalıydım bilmiyorum. 

Bir eğil gözlerime... 

Allanıyorum her bakışında açılan bir yarayla. 

Sallanıyor ruhum,

Giderken attığın her bir adımla. 

Seni  bekliyorum duraklarda,

Gelmeyeceğini bildiğim yerlerde,

Geçmeyeceğini bildiğim sokaklarda.

Ben düştüğünü, yıkıldığını gördüm 

Dünyayı saran burçların. 

Altında kaldım kalkmaya çalışmadım. 

Bir ben gördüm kalıntılar altında 

Ağlayan bir çocuğu; 

Acımdan sıkılmadım.', 'Edebiyat... Yüreğinin içine sokarsın  Kaleminin sivri ucunu,  En derinlere banarsın... Kor haline gelen hislerin kelimeleşir;  Yan yana geli...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sikilmadim-acimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkın Kalmasın Bende', 'hakkin-kalmasin-bende-derin-oger-r9mmc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Otur karşıma

Af dile çiçeklerimden

Kırdığın dal yıkılışım olmadı 

Şüpheli olsam da yeşilinden

Hakkın kalmasın bende

Nöbet bana aşk tı ben nöbete

Gece yüzüme baktıkça kusur bende çoğaldı

Uçurumlardan dağlardan tepelerden

Sallandırsınlar assınlar şu dünlerdeki beni

Hakkın kalmasın bende

Uç git iki çatık kaşım arasından

O senli günler halay çeksin ardından

Gönlüme sevdanın buzu yerleşsin

Baygın kokulu bir çiçekte mührün kalsın

Hakkın kalmasın bende

Uçuşan yapraklar gibiydim

Vefasız sevginin yeline nikahlanmışcasına

Dudaklarım gülümserken yüzüne

Acıların  furyasını öğüttüm ağzımda

Hakkın kalmadı bende

Kalmasın da...........', 'Otur karşıma Af dile çiçeklerimden Kırdığın dal yıkılışım olmadı  Şüpheli olsam da yeşilinden Hakkın kalmasın bende Nöbet bana aşk tı ben nö...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hakkin-kalmasin-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma Ki Sanadır', 'sanma-ki-sanadir-i-smail-sahin-bivw0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sanma ki sanadır, gülüm, ezilen bu hayat...

Ağlamadım ki ağlarsam 

Sana değil gözyaşım. 

Beni sana iten, 

Gözümde tanrısallaştıran:

 Yokluğun. 

Olmadığın için seviyorum seni.

Hayalin daha güzel geliyor kalbime. 

Biliyorum öpüversem 

Biter dudakalrının balı, 

Yesem etini kokuşur.

Sen kaçtığın kadar avcıyım ben...

Olmadığın kadar benimsim gülüm. 

Kapımı çalmanı değil

Beklemeyi seviyorum. 

Çektirdiğin acı kadarsın sen. 

Benim olsan herşey biter. 

Seni düşünüp düşünüp de 

Çekemem tütünü çiğerlerime. 

Aradığımda gelmemen, 

Gel diye aramaman besliyor aşkımı. 

Beni sevmediğin için seviyorum seni. 

Ben sana değil aşka aşığım.

Sanma ki sanadır, gülüm, ezilen bu hayat.', 'Sanma ki sanadır, gülüm, ezilen bu hayat... Ağlamadım ki ağlarsam  Sana değil gözyaşım.  Beni sana iten,  Gözümde tanrısallaştıran:  Yokluğu...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sanma-ki-sanadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölecek Olan Değil Ölenim', 'olecek-olan-degil-olenim-i-smail-sahin-ibrzt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbimin her titreyişinde 

Dünyaya vurduğu darbelerdir 

Senin şu bir hamlede okuduğun kelimeler.

Büzülüyor sanıyorum denizleri; 

Çözülüyor, aheste, mavileri gökyüzünün.

Hayallerde bir sen yarattım kendime 

İflas ettiğimde..

Aynı yöne uzanmış iki çiçek, 

Aynı kağıda yazılmış bir gelecek. 

Ben gökyüzü sen deniz; 

Gözlerin afakında el eleyiz. 

Ama...

Korkuları var bir de 

Hayallerden gerçeklere düşmenin... 

Aslında hiç yoksun, 

Üşüyorum. 

Güneşin anlında bir damla suyum, 

Filize ulaşmadan yok oldum. 

Ellerini uzatıp yakalayamıyorsun, 

Yazgı bir çamura saplanmak, 

Bir kaldırım yanağında parçalanmak.

Kimsesizim sensiz. 

Eziliyorum, 

Sahip olamadığım anılarım üzerimde. 

Geçiveriyorsum kıyılarımdan, 

Ne bir uğrak. 

Ben seni izliyordum, 

Sen izlerken benden başka her şeyi. 

Ah! Bilmiyorsun, bilmiyorsun... 

Yüreğimi tatmadan sevildim sanıyorsun, 

Ah bilmiyorsun. 

Ayaklarında ölecek olanlarından değilim, 

Ben ayak bastığın yollarda ölenim. 

Ne ki sana çiçek vermek, 

Ben senin için  çiçek yetiştirenim.

Bir sonraki adımı atmak istemiyorum, 

Sonrakini de. 

Yığılmak. 

Gözyaşlarımla eriyip 

Haykıramadığım feryadımla, 

Söyleyemediğim aşkımla 

Sızmak istiyorum toprağa.

Korkarak, tereddütlerle, 

Ümitlerle yaşamak; acı çekerek; 

YAŞAMAK(!)

Gel demiyorum; 

Cesaretim yok, 

biliyorum ki, gülüm gelmeyecek.', 'Kalbimin her titreyişinde  Dünyaya vurduğu darbelerdir  Senin şu bir hamlede okuduğun kelimeler. Büzülüyor sanıyorum denizleri;  Çözülüyor, ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/olecek-olan-degil-olenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel Ölücem', 'ne-guzel-olucem-i-smail-sahin-anv30', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öldüğümü kokan leşimden anlayacaklar. 

Ne bir gözyaşı akacak yüzüme 

Ne de bir damla su vurulacak tenime. 

Ne saçlar yolunacak başımda 

Ne  bir kimse saracak beni bedenine 

Ne de yanacak kimse gittiğime.

Seni beklerken öleceğim ben, 

Hiç açılmayan kapımı senin açmanı beklerken 

Ve her sabah seninle, 

Senin kollarında uyanmayı beklerken 

Öleceğim.

Bedenim sevinecek ruhumdan kutulduğuna 

Beyazlar açacak, 

Geri dönmeyeyim diye kokacak.

Acını hafifletmemek için, 

Hergün acınla tekrar yoğrulmak için 

Duvarlara astığım hatıralarınla 

Seni seve seve öleceğim ben.

Kurmanı istediğim ama kurmadığın saraylara inat 

Bunu da sen yaptın diye 

Mutlu olmaya çalışacağım harabelerimde. 

Sırf senden diye her bir kırık tuğlaya, 

Toza-  toprağa yüz sürüp sevineceğim.

Ama ben ne güzel öleceğim.

Ölmek  demek ne demekse hakkını vere vere. 

Ölüm karşısında 

Ölümlünün yaşabileceği ne varsa 

Hepsini yaşayarak öleceğim. 

Ağlamadan, titremeden, 

Özümseyerek, hissederek, çekerek.

Öleceğim; 

Beyaz saçlarımla,  yüzümü  gizleyen sakalım, 

Gözlerimi saklayan yüzümle. 

Ölmek demek ne demekse 

Hakkını vere vere  ölücem. 

Ama ben ne güzel ölücem.', 'Öldüğümü kokan leşimden anlayacaklar.  Ne bir gözyaşı akacak yüzüme  Ne de bir damla su vurulacak tenime.  Ne saçlar yolunacak başımda  Ne  ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ne-guzel-olucem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsmi Yok Gidişinin', 'i-smi-yok-gidisinin-i-smail-sahin-fuxl3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir başka şeyden ölmek, 

sadece bir defacık. 

Bir defa orjinal bir nedenden ölmek. 

Bir defa dost dizinde can vermek istedim 

olmadı. 

Bir defa tatlı tatlı bakan gözler altında, 

olmadı. 

İsmi yok gidişinin. 

Her şey yerinde... 

Kafe Eski’ de masalar, 

Hasanağa’ da çimler yerinde. 

Beşiğinde sallandığın parklar, 

oturup seni izlediğim banklar yerinde. 

Güneşin batışını izlediğimiz, 

kıyısında koşuştuğumuz deniz hep yerinde. 

Bir sen yoksun. 

İsmi yok gidişinin.

Havalar hala soğuk, 

oturduğumuz duraklar boş; 

gece yarıları ayak seslerimizi duyan sokaklar, 

köpekler yerinde. 

Bir bardak çayım var, 

seninki de karşımda. 

Hep çayı iki söylüyorum. 

Sen yoksun yanımda. 

Ellerimi uzatıyorum 

ellerime varıyor yine. 

İsmi yok gidişinin.

Son kibriti vermiştim sana, 

karanlıkları aydınlatabileceğim son kibrit. 

Bir gül yanağında son kanı. 

Son şehri. 

Ayakta kalabilen, 

istilaya uğramamış son şehri. 

İsmi yok gidişinin.

Ama gözyaşımı göstermedim sana, 

şiirini okurken. Sakladım. 

Çevirip yüzümden içime döktüm 

gözlerim nemlendiğinde, 

içime doldurdum. 

İsmi yok gidişinin.

Ne olmadığın bir yer var, 

ne de bulunduğun. 

Soğuk bir rüzgar. 

Sıcak göz yaşları. 

Ellerin yok. 

Her şey yerinde, Kafe Eski’ de masalar, 

masalarda sandalyen yerinde. 

Çayın soğuyor. 

Ben de buradayım. 

Bir sen yoksun. 

İsmi yok gidişinin.', 'Bir başka şeyden ölmek,  sadece bir defacık.  Bir defa orjinal bir nedenden ölmek.  Bir defa dost dizinde can vermek istedim  olmadı.  Bir d...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/ismi-yok-gidisinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede', 'nerede-suleyman-ozansoy-ni80o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nerde uğruna can verdiğim

Canan nerede

Can gitti,ten gitti

Ben nerede

Ölüm geldi artık,yolculuk bitti

Ruh nerede

Yokluğun verdiği savaş

Var nerede

Ölüm ve yokluk arasında

Hayat nerede

Bir hatıra bir demet

Zakkum meyhanelerde

Cinayet var zulmet içinde 

Yaşamak nerede

İntiharlar,ölümler,savaşlar

Barış nerede

Nerde o süslü püslü yalanlar

Adalet nerede

Benim aydınlık günlerim kapıda

Gel artık,gelmeli artık,Gel de.....', 'Nerde uğruna can verdiğim Canan nerede Can gitti,ten gitti Ben nerede Ölüm geldi artık,yolculuk bitti Ruh nerede Yokluğun verdiği savaş Var ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Ozansoy']::text[], 8.5, '{"poet":"Süleyman Ozansoy","poet_slug":"suleyman-ozansoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nerede-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kudüs- 2', 'kudus-2-i-smail-sahin-34mul', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalansın Kudüs sen, yalan! 

Yüzüme gülücükler eken

Güneş sandığım 

Kızıl kumlar bulduğum

Tutunduğum 

Gözlerinle Kudüs

Yalan! 

Gökyüzüne uzanan duvarlarınla

 Toprağınla 

Nil gibi dünyayı saran yüreğinle 

Olmadın sen hiç gelmedin 

Yalansın Kudüs! 

Hiç varılmamış bir serapsın sen 

Ne içtim avuçlarından 

Hiç kurulmamış bir şehirsin sen 

Gördüğüm yalandı 

Gezip durdum sokakalarında 

Yürüdüğümüz yollara yağmur yağmadı 

Toprak çamur olmadı

Bir gerçek örülmedi çölün ortasına

Seni ben kurdum zihnimde Kudüs! 

Hiç kurulmamış bir şehir için 

Roma''ya isyan ettim Kudüs!', 'Yalansın Kudüs sen, yalan!  Yüzüme gülücükler eken Güneş sandığım  Kızıl kumlar bulduğum Tutunduğum  Gözlerinle Kudüs Yalan!  Gökyüzüne uzan...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kudus-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kudüs-3', 'kudus-3-i-smail-sahin-mooar', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kumlar...

N-o-k-t-a  n-o-k-t-a...

Kanım yakıyor içimi 

Güneş beynimde 

Hep aynı tepeler her tarafta

Ufuklar aynı, ayak bastığım yerler aynı 

Bazan elinde testisiyle bir kız 

Bazan bisikletleriyle dolaşan çocuklar

Tatlt tatlı gülümsüyorlar tozlu yüzüme

Birisi oyuna çağıryor, birisi suya

Soruyorlar hep son isteğimi

“Varsa son hayalini” söyle

Kumlar, güneş, çocuklar, kız

Yaklaşıyorum 

Tebessümle cavabımı bekliyorlar

Suya bakıyorum, güneşe, bisiklete 

Birden sen beliriyorsun çölün ufkunda

Telaşlanıyorum! 

Sarıp sarmalıyorsun ruhumu

Her kum taneciği bir damla su oluyor 

Denizler üzerinde ağaçlar 

Gülümsüyorsun

Omuzların üzerinde esintiler serin 

Kız ve çocuklar hala bekliyorlar 

“Serap görmeyeyim” diyorum

 “Hayal değil gerçek olsun 

Güneşse güneş kumsa kum”

Kabul edip kayboluyorlar

Ama her taraf deniz hala, ağaçlık 

Vallahi bu toprakalar senin kudüs

Vallahi bu ayaklar senin kudüs 

Çarmıha da gersen

Çiviler çaksan kemiklerime.elllerime 

En büyük tepeye yürüyorum

Son takatimi kullanıp 

Geliyorum!', 'Kumlar... N-o-k-t-a  n-o-k-t-a... Kanım yakıyor içimi  Güneş beynimde  Hep aynı tepeler her tarafta Ufuklar aynı, ayak bastığım yerler aynı ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kudus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnıızlık sen oldu', 'yalniizlik-sen-oldu-recep-i-nkaya-igrcx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ruhum sığmıyor içime

uçmak istiyor

kaçmak istiyor bedenimden

o kadar yıprattınki beni

umudum kalmadı gelecekten

hayallerim vardı hasretinle yandı

bütün mutlu günlerim ellerinde kaldı

şimdi benden çok uzaklardasın

sensiz hayata katlanılırmı

başım hep öne eğik

gözlerim hep dolu dolu

ben sensiz kalamam diyordum

şimdi yalnızlık bana sen oldu', 'ruhum sığmıyor içime uçmak istiyor kaçmak istiyor bedenimden o kadar yıprattınki beni umudum kalmadı gelecekten hayallerim vardı hasretinle ...', ARRAY['Türk Edebiyatı','Şiir','Recep İnkaya']::text[], 8.5, '{"poet":"Recep İnkaya","poet_slug":"recep-i-nkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalniizlik-sen-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşman Geceler', 'dusman-geceler-baykal-kaanalp-32yx1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceleri düşmandı ona

Ona ve yaşama isteğine

Suçu sevmekti,gönülden

İçini yakan ateşini

Doğallığın insanlığın

Kadın olmak suçunu

İşlemişti cesaretle

Geceleri düşmandı ona

Ona ve yaşama isteğine

Derinliklerinde kırk kandil

Yanardı sevdasının

Açıklayamazdı sırdaşına

Sevdiğini delicesine

O sevemezdi bir erkeği

Sevmek suçtu...

Yaşamak zorunda olduğu yerde

“yaşamak ama 

ne yaşamak

belirli kalıplarda 

belirlenmiş çizgilerde

yaşamak,yada

yaşamaya çalışmak”

günlerdir fırtınalar kopuyordu

gözlerinde,yüreğinde

yüreğinin sesiydi bakışları

anlatmak istediklerini

anlatacak tek sözcü

gözleri ve de boş bakışları

uzaklara

gitmek istediği

büyük şehre doğru

bakardı,devamlı,hisleri

kimse tercüme edemezdi

dilsiz hislerini

hoş tercüme etseler bile

kim okuyacaktı

onun hislerini

geceleri düşmandı ona

ona ve yaşama isteğine

ona ve geleceğine

belirsiz olan

kıymetsiz olan

gelmesini beklemediği

geleceğine', 'Geceleri düşmandı ona Ona ve yaşama isteğine Suçu sevmekti,gönülden İçini yakan ateşini Doğallığın insanlığın Kadın olmak suçunu İşlemişti c...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/dusman-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denk Gelir Gelmez Uyak', 'denk-gelir-gelmez-uyak-bekir-mutlu-gokcesu-s7ohq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Katsan da bana 

Huyundan suyundan

Hoşlansam da çoğu

Sarılışından

Beni kendine benzetme

Ben bana benzerim en çok

Bırak dedi bırak

Öyle sandığın gibi 

Bilmem uyak, durak

Beni kendi halime bırak...

Anlamadım önce 

Gülmüşüm...

Sonra devam etti 

Sayma adımlarımı

Hatta koyma adımı 

Kah koşarım

Kah dururum

Ya 

Bir çırpıda doğaçla

Ya da beni yorma

Bırak dedi bırak

Denk gelir gelmez uyak

Sen yine de

Dizginlerimi bırak....

Döndüm baktım geriye

Yine bir sürü kafiye

Alışkanlık işte...

Önüme eğdim başımı

Suç işlemişçesine

Bakamadım

Buğulu iri gözlerine

Biliyorum dedim

Denk gelir gelmez uyak

Tabi ki biliyorum

Asla hükmedilemeyeceğini 

Özgür bir şiire...', 'Katsan da bana  Huyundan suyundan Hoşlansam da çoğu Sarılışından Beni kendine benzetme Ben bana benzerim en çok Bırak dedi bırak Öyle sandığ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/denk-gelir-gelmez-uyak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman Değilim', 'pisman-degilim-baykal-kaanalp-68xg6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ocağıma incir ağacı diktiğinde

suyunu ben verdim,ben büyüttüm

pişman değilim

olmayacağım

hatta yemişini toplayacağım

mideme oturacak olsa da', 'ocağıma incir ağacı diktiğinde suyunu ben verdim,ben büyüttüm pişman değilim olmayacağım hatta yemişini toplayacağım mideme oturacak olsa da...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/pisman-degilim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seslenmek', 'seslenmek-ali-fikri-karadeniz-0n7n3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seslenmek; tüm evrende gürlüyebilmek,

Sonra bulutlara dönmek vardı.

Sevgi tanecikleriyle yaşama geri dönmek,

Bütün canlılara duyulabilmek vardı...', 'Seslenmek; tüm evrende gürlüyebilmek, Sonra bulutlara dönmek vardı. Sevgi tanecikleriyle yaşama geri dönmek, Bütün canlılara duyulabilmek va...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seslenmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni çabuk unutacağım', 'seni-cabuk-unutacagim-recep-i-nkaya-tv9hq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'elime bir kazma verdin

birde kürek

aşkını derin bir mezara gömmem için

gittin sonra elveda diyerek

sana söz deneyeceğim

nerde çıkamayacağın kadar derin bir mezar

nerde sonu olmayan bir uçurum bulduğumda

seni oraya gömeceğim

görüyorsun seni çok cabuk unutacağım', 'elime bir kazma verdin birde kürek aşkını derin bir mezara gömmem için gittin sonra elveda diyerek sana söz deneyeceğim nerde çıkamayacağın ...', ARRAY['Türk Edebiyatı','Şiir','Recep İnkaya']::text[], 8.5, '{"poet":"Recep İnkaya","poet_slug":"recep-i-nkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-cabuk-unutacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süt Kokusu', 'sut-kokusu-aziz-akgun-wzpvd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'insanoğlu 

utan...

beşikteki bebeğin miydi

ellerine bulaşan kan

...

insanoğlu 

utan...

çelik zırhlarını delip te

burnuna gelen o koku

barut kokusu değil

süt kokusu

....

hani o tankından

nefretle fırlayan o bomba

o evin duvarını yıkıpta

süt kokan çocukların 

küçük göğüslerinde

patladığında...

işte o an

yayıldı semaya

yayıldı inadına

kan dolu avuçlardan

süt kokuları...

....

ve sen 

kimseye veremeyeceksin hesabını

kefene sarılmış bir bebeğin

ne kadar yıkasan da çıkmayacak 

ellerinden çocuk kanları

ağır ağır sinecek üniformana 

süt kokuları...

a.z.i.z. a.k.g.ü.n.', 'insanoğlu  utan... beşikteki bebeğin miydi ellerine bulaşan kan ... insanoğlu  utan... çelik zırhlarını delip te burnuna gelen o koku barut ...', ARRAY['Türk Edebiyatı','Şiir','Aziz Akgün']::text[], 8.5, '{"poet":"Aziz Akgün","poet_slug":"aziz-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sut-kokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kargı', 'kargi-ahmet-aksoy-zhut8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dillerinde akrepler gizler insanlar kimi

kiminin tez kiminin geç öldürür zehri

sen kaldır üzerlerinden sis perdelerini

görecesin tavşana kaç tazıya tut dediklerini', 'dillerinde akrepler gizler insanlar kimi kiminin tez kiminin geç öldürür zehri sen kaldır üzerlerinden sis perdelerini görecesin tavşana kaç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kargi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cân beni terk eyler,bu âşk eylemez', 'c-n-beni-terk-eyler-bu-sk-eylemez-sair-ahrazi-k8wjk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir tutar yanı yok hayât.nâfile...

cân beni terk eyler bu âşk eylemez

ecel yol sonu bak,zamân kâfile

cân beni terk eyler bu âşk eylemez

dünyâ duldalık yer.gelen müzdarip

tek yaşayan ölüm! o da ne garip

emri vâki ile nefesi verip

cân beni terk eyler bu âşk eylemez

âh diyen hâl mi ki,tenin çilesi

beden gurbet gibi.hani sılası

hele belli olsun gizli selâsı

cân beni terk eyler bu âşk eylemez

ey ahrâzi dilim! ’’benim’’ desen de

o ben senin değil emânet sende

yârın Azrâil’in hadi sesinde

cân beni terk eyler bu âşk eylemez! 

***', 'bir tutar yanı yok hayât.nâfile... cân beni terk eyler bu âşk eylemez ecel yol sonu bak,zamân kâfile cân beni terk eyler bu âşk eylemez düny...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/can-beni-terk-eyler-bu-ask-eylemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İpekböceği', 'i-pekbocegi-husamettin-gunacti-e441x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tırtıl maaşında hayat yok

yırt kozanı İpekböceğim.

Kelebek ol havalan,

kanatlan en güzel çiçeğe.

ömür kısaymış aldırma,

uç,üç günlük geleceğe...', 'Tırtıl maaşında hayat yok yırt kozanı İpekböceğim. Kelebek ol havalan, kanatlan en güzel çiçeğe. ömür kısaymış aldırma, uç,üç günlük geleceğ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ipekbocegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Ah Canım Seni Çekiyor', 'ah-canim-seni-cekiyor-metin-eser-8ghyv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'S a b a h,

Odamda seher kokusu, kanarya şarkı söylüyor,

Ufukta gece korkusu, Güneşi tutmuş çekiyor,

Bedenim başka bir alem, sensiz uyandım ya bugün,

Gecenin tadı koynumda, ah canım seni çekiyor.

Ö ğ l e,

Temmuz sıcağı yakmayı, gönül yanmayı özlüyor,

Dalga sahile vurmayı, ''düş'' hayalini çekiyor,

İçim tuhaflık diyarı, sensiz kalmayı yaşıyor,

Gecenin tadı ruhumda, ah canım seni çekiyor.

İ k i n d i,

Serseri gönül tembeldir, seni çay gibi düşlüyor,

''Akşam'' yollarda keşifte, ufuktan günü çekiyor,

Bedenim başka bir alem, sensiz türküler söylüyor,

Gecenin tadı şuramda, ah canım seni çekiyor.

A k ş a m,

Yalnızlık hüznün kolunda, bana özlem getiriyor,

Beraberinde biraz da, koyu karanlık çekiyor,

Yüreğim başka bir alem, sensiz geceden titriyor,

Gecenin tadı damakta, ah canım seni çekiyor.

G e c e,

Gözlerim uykuya dargın, geceye nöbet tutuyor,

Rüyayla kabus beraber, beni uykuya çekiyor,

Hayalim başka bir alem, sensiz yatağı itiyor,

Gecenin tadı dudakta, ah canım seni çekiyor.

...........

...........

...........

s a d e c e...........v e...........s a d e c e,

.

c a n ı m....s e n i....ç e k i....ç e k i y o r.

25.05.04 / Frankfurt', 'S a b a h, Odamda seher kokusu, kanarya şarkı söylüyor, Ufukta gece korkusu, Güneşi tutmuş çekiyor, Bedenim başka bir alem, sensiz uyandım y...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ah-canim-seni-cekiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sazan', 'sazan-erol-dal-tsgvd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kulaklarıma dolmuyor

Çığlıklarımın sesi 

Haykırsam da son nefesimi

Duymuyor kimse

Duyulacak sesim

.....

Taş attım

Kuyu bendende sağır

Olmayacak hayallerin peşinde 

Koşan ben

Mutluluk rüzgarını yakalayan 

Hep sen! 

Ben sanki bir ozan

Türkü söyleyen

Ya sen…

Bir garip 

Suda dolaşan sazan', 'Kulaklarıma dolmuyor Çığlıklarımın sesi  Haykırsam da son nefesimi Duymuyor kimse Duyulacak sesim ..... Taş attım Kuyu bendende sağır Olmaya...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-husamettin-gunacti-4nkdw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu deli yakamoz,

şu iri orfoz,

bu keskin iyot 

ve yosun kokusu,

bu coşkulu dere,

yıkık iskele,

alır götürür beni

doğduğum yere....', 'bu deli yakamoz, şu iri orfoz, bu keskin iyot  ve yosun kokusu, bu coşkulu dere, yıkık iskele, alır götürür beni doğduğum yere.......', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlem-163-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçı', 'balikci-husamettin-gunacti-xzcl0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ümitlerini yüklenip

açıldı engine.

ümitleri denize,

balıkları kendine.

birden patladı lodos

battı kırmızı tekne.

balıkları denize,

ümitleri denize...', 'ümitlerini yüklenip açıldı engine. ümitleri denize, balıkları kendine. birden patladı lodos battı kırmızı tekne. balıkları denize, ümitleri ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/balikci-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-i-brahim-atilmis-7nkpz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karabasan gecelerimin 

aymaz yalnızlığında

bir türkü tadında uyanabilmektir umudum

sabahları

simitci çocuğun gevrek sesiyle dağılır

hüzünlerim

ve

kan çanağı gözlerim

aynadan bakarken

yüzümdeki uzamış özlemlerime

bir avuç su gibi

çarpar 

hayalimdeki gülüşün

gün başlar

derdi sarar beni 

karabasan gecelerin', 'Karabasan gecelerimin  aymaz yalnızlığında bir türkü tadında uyanabilmektir umudum sabahları simitci çocuğun gevrek sesiyle dağılır hüzünler...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geceler-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asma Ağacı', 'asma-agaci-onder-cagiran-1x8h5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tatlı sadâlarla gözüm açarken

Nazar eder bana asma ağacı.

Güneş içeriye billûr saçarken

Gülümser bu yana, asma ağacı.

Seher serinliği inceden ince

Âlemi mest eden figân gelince

Hüzünler bir anda döner sevince

Müştâktır ezâna, asma ağacı.		

Seninle olunca ne gam, ne keder

Nice dostun gelir, niceler gider.

Sırrına erişen Mansûr gibi der

Erişir dalına asma ağacı.', 'Tatlı sadâlarla gözüm açarken Nazar eder bana asma ağacı. Güneş içeriye billûr saçarken Gülümser bu yana, asma ağacı. Seher serinliği incede...', ARRAY['Türk Edebiyatı','Şiir','Önder Çağıran']::text[], 8.5, '{"poet":"Önder Çağıran","poet_slug":"onder-cagiran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/asma-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-husamettin-gunacti-laouq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aşk bahar gibi gelmeli

açarak sevda tomurcuklarını.

heyecanı soluğu olmalı,

hissettirmeli kalp ağrılarını.

puslu gecenin örtüsünü

kaldırmalı üzerimden.

çıkartmalı yalnızlık süngüsünü

sonsuza dek yüreğimden...', 'aşk bahar gibi gelmeli açarak sevda tomurcuklarını. heyecanı soluğu olmalı, hissettirmeli kalp ağrılarını. puslu gecenin örtüsünü kaldırmalı...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-3105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çan', 'can-ahmet-aksoy-ytw34', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kaynıyor kabında zamanın

...sıhatini yitirmiş ruhlar

bir bayram sabahı çıldırıyor

..çan kulesindeki zangoçlar

her şey ama her şey buzul çağı

...ve o ısının kurulmuş gölgesi

bitsin diyor günaha esriyiş

lakin dönüyor dünya

......altında ruhlar', 'kaynıyor kabında zamanın ...sıhatini yitirmiş ruhlar bir bayram sabahı çıldırıyor ..çan kulesindeki zangoçlar her şey ama her şey buzul çağı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/can-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şah yolu', 'sah-yolu-i-brahim-atilmis-fy1fp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni yol bildim yoluna geldim

hırçın derelerde çağlayan seldim

aşkınla ferhat olup dağları deldim

can sultan pir sultan

zaman şimdi o zaman değil pirim

ölüme güç yetmez beş para etmez dirim

görsekte zamane yezitlerinden olmaz zulum

şah sultan pir sultan

şahım ali sana adını verdi

hızır yoldaşın oldu sabrını verdi

unutturdun canlara kederi derdi

Ali sultan pir sultan

Atılmışım yoluna yolun insanlık yolu

yaşadığın her an hep onur dolu

yağlı ilmek boynunda hınzırın kolu

haydar sultan pir sultan

gün oldu devran döndü

nice canlar yolundan döndü

gittiğin gün sanki daha dündü

dost sultan pir sultan

adını anmayan canlar utansın

seni bilmeyen kendine yansın

yolum her zaman sana varsın

bir sultan pir sultan', 'seni yol bildim yoluna geldim hırçın derelerde çağlayan seldim aşkınla ferhat olup dağları deldim can sultan pir sultan zaman şimdi o zaman ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sah-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçların Güneşten Almış Rengini', 'saclarin-gunesten-almis-rengini-emrah-avci-t671y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saçların 

Güneşten almış rengini

Gözlerin 

Zümrüt yeşili

Ve...Gözlerim 

Gözlerinin tiryakisi', 'Saçların  Güneşten almış rengini Gözlerin  Zümrüt yeşili Ve...Gözlerim  Gözlerinin tiryakisi...', ARRAY['Türk Edebiyatı','Şiir','Emrah Avcı']::text[], 8.5, '{"poet":"Emrah Avcı","poet_slug":"emrah-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/saclarin-gunesten-almis-rengini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
