INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Demek', 'elveda-demek-caner-kuru-0wdsy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çiçeksiz baharın adı mı olur? 

Sevgisiz  hayatın tadı mı olur? 

Düşün biraz, hemen lafımı olur? 

Elveda demekten kolay ne var ki? 

Çok fazla güvenme bu genç yaşına,

Olur olmaz işler gelir başına,

Tüm dünyan yıkılır gider boşuna,

Elveda demekten kolay ne var ki? 

Çökerse üstüne kara bulutlar,

Kırılırsa eğer bir bir umutlar,

Mücadele etmek aşkı kanıtlar

Elveda demekten kolay ne var ki?', 'Çiçeksiz baharın adı mı olur?  Sevgisiz  hayatın tadı mı olur?  Düşün biraz, hemen lafımı olur?  Elveda demekten kolay ne var ki?  Çok fazla...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/elveda-demek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahın derinliği', 'sabahin-derinligi-metin-kose-wsux8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ezanlar, kuş sesleri

