INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaktın Beni', 'yaktin-beni-murat-karali-kqyqq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saçlarını dağıtmış,

Ne diye bakıyorsun.

Gülüm gönlümü çaldın,

Daha ne istiyorsun.

Yandım,yandım diyerek,

Kapında bekliyorum.

Sevmeye yürek gerek,

Seni çok seviyorum.

Ben acizim geçemem,

Sabır yarışmasını.

Yalvarırım aç artık,

Gönlünün kapısını.', 'Saçlarını dağıtmış, Ne diye bakıyorsun. Gülüm gönlümü çaldın, Daha ne istiyorsun. Yandım,yandım diyerek, Kapında bekliyorum. Sevmeye yürek g...', ARRAY['Türk Edebiyatı','Şiir','Murat Karali']::text[], 8.5, '{"poet":"Murat Karali","poet_slug":"murat-karali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yaktin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka İhsan İstemem', 'baska-i-hsan-i-stemem-muammer-celik-4sg1m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Verme istemem, 

senin olsun gözlerinin rengi

Bakışlarındaki ışığı gözlerime tut yeter... 

Verme istemem,

senin olsun bakışların 

Gözlerinde saklı ruhuna dokunayım yeter... 

Verme istemem,

senin olsun ruhun 

Ruhunun mekanından bir gül uzat yeter... 

Verme istemem,

senin olsun güllerin 

Gönül bahçene işçi tut beni yeter...

BirDeli

30.05.2004', 'Verme istemem,  senin olsun gözlerinin rengi Bakışlarındaki ışığı gözlerime tut yeter...  Verme istemem, senin olsun bakışların  Gözlerinde ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/baska-ihsan-istemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artvin''de Bahar', 'artvin-de-bahar-kamil-aydemir-ugm88', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'oy nazına yandığım

yıllardır sevdanı sırtlandığım

çoruh deyince sen gelirsin aklıma

yokluğun fırtına olur sevinçlerimi kırar

ülkem gibi ağlarım yâr

seni görüşüm artvin’de bahar

gözlerin karanlığımı yırtan iki yıldız

yüreğin ilkokulun bahçesi

sanki sen savşat’ın girişindeki efkar tepesi

insanlığında ağırlarsın herkesi

artvin gibi severim seni yâr

gülüşlerin artvin’in yeşili

dudakların çoruh’un avuçlarında açan narçiçeği

bilgiyle bakan görür gerçeği

sevgiyle örünce geleceği

hüzünü giyinmez dağlar

ne ben

ne de ülkem ağlar

kavuşmamız artvin’de bahar

kafkasların arkasından güle oynaya çıkıp gelen

             güneş gibi

yokluğun ayazında donan bedenimi sarsan

beni yeni güne salsan

uyandırırım uyuyan sokakları

izine ayırırım yağmur toplayan çocukları

ben toplarım yağmurları

hep güzellikler eker güne

aşkı giyinen insan

insan en güzel anadilinde söyler sevgisini

                                              ve türkülerini

yasaklanınca bir halkın dili

utancımdan söyleyemem sevgimi

                                ve türkülerimi

kendi yurtlarında yurtsuzlara sundum yüreğimi

evsizlere gecekondu oldum

cennetin uzaklarda aranmadığı artvin’de doğdum

kendimi mutluluğu taddığım sende buldum

çoruh deyince aklıma sen gelirsin yâr

içimi aşkın doldurur

bende sevgi okyanusu olur

gözlerine varışım artvin’de bahar

kaçkarların tepesinde bir çınarın gölgesinde

içilen rakı gibi sararsın beni

yırtıp atmak için hüzünü

kekre kokulu derelerde ararım yüzünü

kuşlar ki gökyüzüne fırça sallayan resamlar

tablolarından hep mutluluk damlar

sevdamı en iyi onlar anlar

zego kokulum aşk okulum

heder etmemek için ömrümüzün geri kalan günlerini ver elini

koynumda sen artvin’de bahar', 'oy nazına yandığım yıllardır sevdanı sırtlandığım çoruh deyince sen gelirsin aklıma yokluğun fırtına olur sevinçlerimi kırar ülkem gibi ağla...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/artvin-de-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
