INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Çıldırtmak İçin mi O kadar Kırmızı Oldunuz', 'beni-cildirtmak-i-cin-mi-o-kadar-kirmizi-oldunuz-goktu-kara-lzxpb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'doşan sevdaların dinmiş güzelliği

çıngırdak üzerinde daimi çekiciliğin

gülün yaparakları senitte

anlamasan da olur sednayı

gıcırkapı açılıp güller saçılınca

sen uzaklaşınca

göksu ırmağında balıklar 

bulanık suda 

kıyılara vuran seslerin 

tınısı sürekli

belli belirsiz

çocuk küfürleri

o kadar ayrıyım ki senden

söyleyin güller

beni çıldırtmak için mi o kadar kırmızı oldunuz', 'doşan sevdaların dinmiş güzelliği çıngırdak üzerinde daimi çekiciliğin gülün yaparakları senitte anlamasan da olur sednayı gıcırkapı açılıp ...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/beni-cildirtmak-icin-mi-o-kadar-kirmizi-oldunuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne Döneceğim', 'anne-donecegim-hasan-ayar-gy5ad', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anne neredesin ihtiyacım var 

Bu yemyeşil diyar şimdi bana dar 

Uzaktan sevilir mi canındaki yar 

Anne döneceğim üzülme sakın 

Bırakın gurbetler beni bırakın 

Günlerim cefalı aylarım hüzün 

Aklımdan gitmiyor o melek yüzün 

Dakikası ecel, artık gündüzün 

Anne geleceğim günler çok yakın 

Bırakın gurbetler beni bırakın 

Karşıkı dağlarda açtı çiçekler 

Üstünde geziyor mor kelebekler 

Onlarda gurbetten bıkmış gibiler 

Çakın yıldırımlar üstüme çakın 

Bırakın gurbetler beni bırakın

2004', 'Anne neredesin ihtiyacım var  Bu yemyeşil diyar şimdi bana dar  Uzaktan sevilir mi canındaki yar  Anne döneceğim üzülme sakın  Bırakın gurbe...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ayar']::text[], 8.5, '{"poet":"Hasan Ayar","poet_slug":"hasan-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anne-donecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Örtü', 'kara-ortu-sair-taranta-xnbam', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yırtacaksak

bulutların üzerimizdeki kara örtüsünden başlayalım

Çocuk yüzünün sıcaklığı

belli değilmi

yırtılmış karanlığın ürünü olmasından? 

Sende çek gözlerindeki bulutu

Sevgide bulacaksın umudu.', 'Yırtacaksak bulutların üzerimizdeki kara örtüsünden başlayalım Çocuk yüzünün sıcaklığı belli değilmi yırtılmış karanlığın ürünü olmasından? ...', ARRAY['Türk Edebiyatı','Şiir','Şair Taranta']::text[], 8.5, '{"poet":"Şair Taranta","poet_slug":"sair-taranta","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kara-ortu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KaTiLiMiN ElleRİ,', 'katilimin-elleri-mine-ozdemirtas-zc54t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavi tütsülü bir yangında

yandığında,

yitip gider sandınızsa adınız.

Fena halde yanıldınız.

İnanmazsanız

cinayeti işlediğiniz  yere gidip

bakınız.

Dün gece asmıştım akasya dalına.

Orada; size sizi gösteriyor olacak

içimde unuttuğunuz

tütün rengi parmaklarınız.

Hatırlıyorsunuz değil mi? 

onları en son

''gelme'' diyen tümceye

kurşun sürerken kullanmıştınız.

'' uykuya yaslandığında vicdanınız, başınızı kabul ediyor mu yastığınız? ''

28/05/2004...  yersiz/yurtsuz', 'Mavi tütsülü bir yangında yandığında, yitip gider sandınızsa adınız. Fena halde yanıldınız. İnanmazsanız cinayeti işlediğiniz  yere gidip ba...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/katilimin-elleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kız Sevdim Konya''lı', 'bir-kiz-sevdim-konya-li-i-brahim-dikmen-2-wplcp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kız sevdim,konya''lı,

Kıvır kıvır,saçları.

Gönül ferman dinlemez,

Konya''lıma sevdalı.

Arabası var,kırmızı,

Hemde zengin,bey kızı.

Aklım aldı,başımdan,

Konya''lımın,bakışı.

Sür güzelim,konya''ya,

Tez varalım,çumra''ya.

Eğer baban vermezse,

Kaçalım yar,akşama.

Topla yarim,bohçanı,

Artık,burdan kaçmalı.

Baban,bizi bulmadan,

Terk edelim,konya''yı.', 'Bir kız sevdim,konya''lı, Kıvır kıvır,saçları. Gönül ferman dinlemez, Konya''lıma sevdalı. Arabası var,kırmızı, Hemde zengin,bey kızı. Aklım a...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-kiz-sevdim-konya-li-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlerine Varamadım', 'evlerine-varamadim-i-brahim-dikmen-2-lt7l2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Evlerine varamadım,

Ben o''yare bakamadım.

Öyle güzel yüzü vardı,

Doya doya süzemedim.

Yollarına yağmur yağmış,

Yare varmak nede zormuş.

Ben o''yarin delisiyim,

Yarim gitmiş gelin olmuş.

Kaldır camın perdesini,

Bir göreyim cemalini.

Savur sarı saçlarını,

Bir telinin kölesiyim.

Gitti canım gül goncası,

Aldı onu köy ağası.

Vurdun beni ağaoğlu,

Can evimde bak yarası.', 'Evlerine varamadım, Ben o''yare bakamadım. Öyle güzel yüzü vardı, Doya doya süzemedim. Yollarına yağmur yağmış, Yare varmak nede zormuş. Ben ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/evlerine-varamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pınarlardan Denizlere', 'pinarlardan-denizlere-galip-ozdemir-hqxs5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Maharbi pınarından düşen her damla

sevişirdi

kadehlerimize doldurduğumuz

yangılarla

yıldız rüzgarları

saçlarımızı okşardı

mehtap

alnımızı öperdi

kadehler kalkardı

bir gülüşe

bir de iç çekişe

düşerdi içimize

gün görmemiş sevdanın hüznü

sonra sulara damlardı sesimiz

yanıp tutuşurdu ırmaklar

denizlere koşardı türkülerimiz

yanardı

Maharbi pınarından düşen her damla

sevişirdi kadehlerimizdeki bulutlarla', 'Maharbi pınarından düşen her damla sevişirdi kadehlerimize doldurduğumuz yangılarla yıldız rüzgarları saçlarımızı okşardı mehtap alnımızı öp...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/pinarlardan-denizlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-taner-ozyurt-fam5y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni sevdim sensiz 

Seni özledim sensiz 

Seni öptüm sensiz 

Seni düşledim bensiz 

Seni bitirdim sensiz ve bensiz', 'Seni sevdim sensiz  Seni özledim sensiz  Seni öptüm sensiz  Seni düşledim bensiz  Seni bitirdim sensiz ve bensiz...', ARRAY['Türk Edebiyatı','Şiir','Taner Özyurt']::text[], 8.5, '{"poet":"Taner Özyurt","poet_slug":"taner-ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-397-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İndirim Kartı!', 'i-ndirim-karti-turgay-akbulut-b1lt9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'iki eliyle sürüklediği sepetinin ardından,

gururla yürüyen adamı

kıskandığımı sanmayın

somut farklılıklar bir yerde eşitlenir

alış veriş duygumuz gibi,

belkide

hayallerimizde  farklı değildi

harcanmadan sevap kazanılmaz

ne varki

herkes topladığının hesabını verecekti...

siz  ellerimin boş oluşunu

beceriksizliğime sayın

İndirim Kartını soran kasiyere

göstermeme ne hacet

indirime tabi neyim vardı,

şu yalan dünyada

sepeti dolu adamın geçerken malları

terleyende ben olmayacaktım

artık eskisi gibi, 

kapıları açan birileri de yok

herşey otomatik

nasıl olsa ikimize, aynı tonda açılacaktı...

ama son birkez,

içimdeki sese uyup 

açılmadan kapı

dönüp baktım

kasadaki meleğin, bir anlık tebessümleri yansıdı

anlıma

-bu kapıdan eli boş çıkılmaz...diyordu

bu dünyadan günahsız gidilemiyeceği gibi...

toplayabildiğim tek günahım sendin...

sorgu melekleri sorduğunda

söylememe ne hacet

tepeden tırnağa günahkardım

dolu sepetlerin geçmediği bir yerdi...

anladınız mı şimdi! 

indirim kartı nerde gerekli...

(mayıs04)', 'iki eliyle sürüklediği sepetinin ardından, gururla yürüyen adamı kıskandığımı sanmayın somut farklılıklar bir yerde eşitlenir alış veriş duy...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/indirim-karti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelaynaklar;', 'kelaynaklar-caglar-akarsu-90gdj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '...

Gün doğuşunda, binlerce tür kuş,

Gece ve gündüz ayrı uçarlar,

Dünya; sanki kanatlarında,saklanmış,

Aşılmaz bir devrin kuralını, yaşamış,

..

Birden,çırpınırken, sesler,

Bazı şehirlerin,üzerinde,

İskemle tepesinde oturanlar,

Açıkta kalmış başlarında,

Kocaman kelleri,göründü,

..

Kuşlar ve insanlar,

...

Demokrasinin bulutlarında,

Bir gece vakti uçarken,

Kanatları yolunmuş,kelaynakların,

Sanki “dillerini” kesmişler,

çak-çak,ederler, dere kenarında,

Yüksek yerlerde,binlercesi,

İçeri giren ve çıkanlar,

..

Kuşlar ve insanlar,

..

Kimi “hizmet” aşkını taşır,

Kimi dili,takozla aşındırır,

Kanat,bükerken bazı anlarda,

Uçmasını bile, öğrenememişler,

Kılavuzları, önünde yol gösterir.

...

Kuşlar ve insanlar,

Oy pusulası,”rota”da iz sürüyor,

Kelaynaklar tepede,kol geziyor,

Her insanın ” dil”i yaşamışsa,

Ülkede uçarken,  yeni kuşaklar,

Kel başa,şimşir tarak değil! ””

Dilin özünde, erimiş,

Yılların ardından,  nedametli,

Sahiplenmiş,kişiler beklenir.

....

30/mayıs/', '... Gün doğuşunda, binlerce tür kuş, Gece ve gündüz ayrı uçarlar, Dünya; sanki kanatlarında,saklanmış, Aşılmaz bir devrin kuralını, yaşamış,...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kelaynaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-sair-bedircik-jzdrn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soğuk kış gecelerinde, intizar ettim hep

O ılıman nisan yağmurlarını,

Belki, son nefesime kifayet eder diye

Bekledim hep bir saçak altında,

Bir zamanlar, seni bekler gibi! 

Umudumu tüketmeye cüzi kala

Akıttım inadına, hep inadına, gönlümden gözüme

Serpe serpe gönül göz yaşımı,

Ve akırım hep, gene inadına inadına!', 'Soğuk kış gecelerinde, intizar ettim hep O ılıman nisan yağmurlarını, Belki, son nefesime kifayet eder diye Bekledim hep bir saçak altında, ...', ARRAY['Türk Edebiyatı','Şiir','Şair Bedircik']::text[], 8.5, '{"poet":"Şair Bedircik","poet_slug":"sair-bedircik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bekleyis-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüksek Uçma Gönül', 'yuksek-ucma-gonul-ferit-teksoy-8380v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüksek uçma gönül Şahin değilsin

Avcı kötü vurdu,neslin mi kaldı? 

Kerem olsan gezsen koca dünyayı

Yürekten sevecek Aslı''n mı kaldı? 

Mızrabın,sazın yok ozan değilsin

Dinleyen buldun da sözün mü kaldı? 

Acılar bitirdi tahammülünü

Daha dayanacak özün mü kaldı? 

Yamacı dumanlı Ağrı değilsin

Doruğu kar tutmuş yüzün mü kaldı? 

Rengin beyaz artık,mevsiminse kış

Yaprağın döküldü,güz''ün mü kaldı? 

Lâvları fışkıran volkan değilsin

Yangının kül oldu,közün mü kaldı? 

Grup aynı grup,renk aynı renk de

O rengi görecek gözün mü kaldı? 

Kabına sığmayan nehir değilsin

Çağlayan ırmağın,hızın mı kaldı? 

Dindir artık deli gönül sancını

Yüreğinde öfken,sızın mı kaldı?', 'Yüksek uçma gönül Şahin değilsin Avcı kötü vurdu,neslin mi kaldı?  Kerem olsan gezsen koca dünyayı Yürekten sevecek Aslı''n mı kaldı?  Mızrab...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yuksek-ucma-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk olsun', 'ask-olsun-fulya-cetintas-6rglk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kopar beni yalnızlığımdan

Çoğalt beni

Tenin öyle çoğaltıcı

Ve ellerin öyle onarıcı

Gözlerinde bir sevmek bir sevmek ki

Öyle olsun

Bir sevmek gözlerinde

Aşk olsun', 'Kopar beni yalnızlığımdan Çoğalt beni Tenin öyle çoğaltıcı Ve ellerin öyle onarıcı Gözlerinde bir sevmek bir sevmek ki Öyle olsun Bir sevmek...', ARRAY['Türk Edebiyatı','Şiir','Fulya Çetintaş']::text[], 8.5, '{"poet":"Fulya Çetintaş","poet_slug":"fulya-cetintas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-olsun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koy Ver Gitsin Güzelim Hayata', 'koy-ver-gitsin-guzelim-hayata-ahmet-aksoy-09gdf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'terk edip de sen gitmişsin beni

ferman salmış unutmuşsun beni

yokdu demişsin arada sevgi

koy ver gitsin güzelim hayata

bir kaç günde bulmuşsun birini

mutlu olmuşsun leylalar gibi

seviyormuşsun deliler gibi

koy ver gitsin güzelim hayata

vefasız geçermiş ömür demi

aşkımız artık batık gemi

sen de tat benim gibi kederi

koy ver gitsin güzelim hayata', 'terk edip de sen gitmişsin beni ferman salmış unutmuşsun beni yokdu demişsin arada sevgi koy ver gitsin güzelim hayata bir kaç günde bulmuşs...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/koy-ver-gitsin-guzelim-hayata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şevk Barış Aluk Dostuma Yanıt', 'sevk-baris-aluk-dostuma-yanit-ahmet-aksoy-fdyi0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '...........''Sevgili Barış Aluk Dostuma Yanıt''

matem kıvrak türküsüdür ömrün

örtülü anılar açık kapılar

bir gün açılacak çiçek

gizlenir testilerde umut

ki pintidir insan gençken

harcamaz şimdiyi mesut

geçer günler durağan

hep başka bir şekle bürünür şevk', '...........''Sevgili Barış Aluk Dostuma Yanıt'' matem kıvrak türküsüdür ömrün örtülü anılar açık kapılar bir gün açılacak çiçek gizlenir testi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevk-baris-aluk-dostuma-yanit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasan Basri''ye Reddiye Şerhi...', 'hasan-basri-ye-reddiye-serhi-i-brahim-ethem-bingul-y40ij', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '*Ben aşkı kabul etmiyorum

Benim aşkım var

Onuda çılgıncasına yaşıyorum..

*Artık ben sevmiyorum

Niye seveyim ki

Bir sevdiğim var

Onun eline bu dünyada 

Kimse su dökemez ki..

*Ben artık böyle yaşıyorum

Hiç itiraz etmiyorum..

*Neymiş uçurtmalar

*Kendi kendini kandırmalar

Biz binmişiz aşk gemisine

İşimiz yok hayalle yaşıyoruz gerçekle..

*Hangi renkte var siyahın asaleti

*Hangi renkte var kırmızının ihaneti

Siyah kırmızı sevgide olabilir mi

Sadakatte ihanet oabilir mi..

*Bana ne kasırgalardan 

*Bana ne toz dumandan

Bundan sonra bize lazım olan

Oda sevginin en alasından..

*Bana bundan sonra ancak

*Yanan yürek dumanları gerek

Taş yürekten bana ne

Aşktan yanan yürekler gerek..

*Ne işimiz var çiçekle, böcekle

*Bizim yerimiz çöller, parçalanmış yürekler

Şerhe ihtiyaç var mı acaba

Bizim aşkımız merhem, yaralı yüreklere..

*Hiç bir göz aşkla bakmasın

*Hiç bir cümle aşkla kurulmasın

Ben suda yaşarken

Sormam su sen neredesin diye..

*Bu ara

*Bir de yaşasın kötülük

Tabi ki yaşasın kötülük

İşte anlaşılır o zaman iyilik...

*  Hasan Basri''ye Reddiye şiiri..', '*Ben aşkı kabul etmiyorum Benim aşkım var Onuda çılgıncasına yaşıyorum.. *Artık ben sevmiyorum Niye seveyim ki Bir sevdiğim var Onun eline b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/hasan-basri-ye-reddiye-serhi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme artık', 'gelme-artik-erkan-kaner-m3ujb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hüzünlü gözleriyle kuşlar geliyordu

gittiğin yerden

havada asılı gözyaşlarına çarptım

ağlamıştın giderken

ne çare yetişemedim

birazını rüzgara astım hüznümün

sana getirsin istedim

bekledim, gelmedin

gelmedin, yine de bekledim

gelme artık

sen yine beni

''rahat ve umursamaz'' bil sevdiğim

kalbime azap gerek

ben bunu hak ettim

                     (18 nisan 2004) 

                          (manisa)', 'hüzünlü gözleriyle kuşlar geliyordu gittiğin yerden havada asılı gözyaşlarına çarptım ağlamıştın giderken ne çare yetişemedim birazını rüzga...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelme-artik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Binyıllık nefret', 'binyillik-nefret-erkan-kaner-gemvy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'binyıllar sonra

dünyanın bambaşka bir coğrafyasında

uçurumun kenarında

düşmek üzere bile olsam

elini uzatmak istersen

herhangi bir insanmışım gibi bana

bırak öleyim

istemem, uzatma

                         (15 mayıs 2004)', 'binyıllar sonra dünyanın bambaşka bir coğrafyasında uçurumun kenarında düşmek üzere bile olsam elini uzatmak istersen herhangi bir insanmışı...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/binyillik-nefret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Kan Ağlıyor', 'yuregim-kan-agliyor-erdal-sayil-i32ay', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Niye gözümde yaş yok; 

Yüreğim kan ağlıyor...! 

Benim bağrımda taş yok; 

Yüreğim kan ağlıyor...

Bilirsin ağlamam ben,

Her zaman çağlamam ben,

Gönlümü dağlamam ben; 

Yok gözümde bir damla,

Yüreğim kan ağlıyor...

Ne yalnız, ne çoklukta; 

Ne varlık, ne yoklukta; 

Ne açlık, ne toklukta; 

Bilirsin ağlamam ben,

Her zaman çağlamam ben,

Gönlümü dağlamam ben; 

Yok gözümde bir damla,

Yüreğim kan ağlıyor...

Sevsem de, ayrılsam da; 

Bağlansam, darılsam da; 

Gülsem de, kırılsam da; 

Bilirsin ağlamam ben,

Her zaman çağlamam ben,

Gönlümü dağlamam ben; 

Yok gözümde bir damla,

Yüreğim kan ağlıyor...

Gitsen de, geleceksin,

Bakacak, güleceksin,

Anlayıp, bileceksin; 

Bilirsin ağlamam ben,

Her zaman çağlamam ben,

Gönlümü dağlamam ben; 

Yok gözümde bir damla,

Yüreğim kan ağlıyor...

Günlerin geçer, kabul; 

Dökülür takvim pul-pul; 

Ayıptır, tamam, fakat; 

Damlalar iner yol-yol; 

Bilirsin ağlamam ben,

Her zaman çağlamam ben,

Gönlümü dağlamam ben; 

Yok gözümde bir damla,

Yüreğim kan ağlıyor...', 'Niye gözümde yaş yok;  Yüreğim kan ağlıyor...!  Benim bağrımda taş yok;  Yüreğim kan ağlıyor... Bilirsin ağlamam ben, Her zaman çağlamam ben...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sayıl']::text[], 8.5, '{"poet":"Erdal Sayıl","poet_slug":"erdal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yuregim-kan-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1997'' de Doğdum...', '1997-de-dogdum-ahmet-capa-fhd41', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oradaydın.

Bir adım ötedeydin.

Masanın üstünde 

kıpırdamadan duruyordun.

Saçlarının üstünde uykulara daldığı

yeşil bir kazak vardı üstünde

Hani bir semt pazarında

ucuzluktan aldığımız…

Tarih 1997 diye düşülmüş arkasına.

Sevdamız iki ay yaşadı da,

yokluğun neden yedi yıldır hayatta.

Yüzümde mevsimsiz açan bir çiçek hüznü

ve kurumuşluğu 

hasretlerin çatlamış topraklarında.

Üzerime hiç bir şey olmuyor görüyorsun.

Hiç bir gülüşü yapıştıramıyorum dudaklarımın kenarına.

Ben 1997 de doğdum,

ve görüyorsun ölmedim hâlâ.

Sahtekâr bir Hoşgeldin yazısıyla

bezenmişti altın sırmalı kapılar.

Adımımı attım 

yüzüme çarpıldı…

Önünde durduğum bu kapı 

Bilmem ki

yüreğinin hangi yanlış kapısıydı.

Ve bana o kadar yolu geri dönmek kaldı

Giderken de 

çiviledim bir takvim yaprağını yüreğimin kapısına.

Ben 1997 de doğdum,

ve görüyorsun ölmedim hâlâ.

(Mayıs 2004 İst.)', 'Oradaydın. Bir adım ötedeydin. Masanın üstünde  kıpırdamadan duruyordun. Saçlarının üstünde uykulara daldığı yeşil bir kazak vardı üstünde H...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çapa']::text[], 8.5, '{"poet":"Ahmet Çapa","poet_slug":"ahmet-capa","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/1997-de-dogdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşksız Cennet', 'asksiz-cennet-burcu-karakaya-34m1l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birbirine  aşkla bakan gözlerden

Koptu geldi ateş...

Kızgın çöllerde esen rüzgarın

Savurduğu kum tanecikleri gibi sevgi

Dağıldı çöl boyu

Serap a hasret kuruyan dudaklar...

Yanan bedenlerin kalp atışları

Dilin ucunda dansta şimdi.

Kötü dans ediyor kelimeler.

Hep amatör kaldı insan

Sümüklü böcek bile

Dişisiyle daha iyi raks ediyor.

Sonsuz sevginin ışığını

Karartı zaman...

Zaman içinde zaman çıkarttı

Keyfini aşkın ve tutsaklığın

Nasıl ruh tekederse

Kokuşmuş kalbi ve çürüyen bedeni

Bana kimse masal anlatmasın...

Aşk, cehenneme yakışır dostlar

Cennele sevgi baki kalsın...

C.Burcu Karakaya

Antalya

30/05/2004', 'Birbirine  aşkla bakan gözlerden Koptu geldi ateş... Kızgın çöllerde esen rüzgarın Savurduğu kum tanecikleri gibi sevgi Dağıldı çöl boyu Ser...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/asksiz-cennet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir de Ben Yaşasam', 'bir-de-ben-yasasam-baykal-kaanalp-5wekj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'birde ben yaşasam 

savunduğum aşkı 

birde ben öğrensem 

sevilmeyi doyasıya 

çıksam kaf dağına 

hiç inmesem 

çıksam kaf dağına 

üzülmesem 

büyüse burnum 

pinokyo kadar 

uzasa kulaklarım 

yalanlarım kadar 

hiç dönmesem 

gittiğim buluttan 

hiç ölmesem 

sevdalar kadar 

birde ben yaşasam 

savunduğum aşkı 

birde ben kapılsam 

aşkın doyumsuzluğuna 

içsem sevda pınarından 

hiç doymasam', 'birde ben yaşasam  savunduğum aşkı  birde ben öğrensem  sevilmeyi doyasıya  çıksam kaf dağına  hiç inmesem  çıksam kaf dağına  üzülmesem  bü...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-de-ben-yasasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurak Bir Deniz', 'kurak-bir-deniz-baykal-kaanalp-ip6sy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kurak bir deniz gibiyim

içinde hiçbir canlı yaşamayan

ne bir gölge var beni soran

ne de üzerimde bir yelkenli

taşıyorum kavgamı içimde

engel olamaz kimse bana

ne bir ağlayanım var ardımda

ne de çiçek koyacak mezarıma

solgun bakıyorum uzaklara

narin ve ince ruhluyum

istemem peşimde bir sevdalı

ben zaten yoklukta mutluyum

aşkımı dağlara bile söylemem

bir göze çarpar diye

bulutlar minderim bile olsa

yine de sevdalıyım yalnızlığa

suyu pınarından içerim

sevdaya göz ucuyla bakmam

ben vurgunum kardelene

dinlerim sessizliği kara''da', 'kurak bir deniz gibiyim içinde hiçbir canlı yaşamayan ne bir gölge var beni soran ne de üzerimde bir yelkenli taşıyorum kavgamı içimde engel...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kurak-bir-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-baykal-kaanalp-l1d0p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aşkın gözü kördür

kulağı sağır

inanıyorsan sevdiğine

olabildiğince bağır

seni seviyoruuuuuuum

aşk ölmez

aşıklar ölmez

taşıyorsan yanık bir bağır

eğer duymuyorsa seni o sağır

bekleme gelmesini düşlerinden

düşünü kendin kur, kendin çağır

seni seviyoruuuuuuum

aşk hiç bitmez

aşklar bitirilemez', 'aşkın gözü kördür kulağı sağır inanıyorsan sevdiğine olabildiğince bağır seni seviyoruuuuuuum aşk ölmez aşıklar ölmez taşıyorsan yanık bir b...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-seviyorum-191-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaşık', 'sarmasik-burcu-karakaya-r8cqz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bağından koptu sarmaşık

Doludizgin ırmağına koşan

Yüreği sardı.

Yeşiline kandı da gönül

Onu durmadan suladı.

Azdı sarmaşık

Sardı sardı, boğarcasına..

Sevgiyle açan gül sandı gönül

Aldandı.

Sarmaşığın yaprakları bir sarardı,

Bir yeşerdi de 

Gönül bu, basireti bağlandı.

Kesip atamadı.

Bencillik her bir sarmaşık boyu

Güneşe yol aldı.

Adaletsiz sevişmelerde

Zaman sallandı.

Gün bir battı, bir ağardı 

Yaratanın can verdiği toprak,

Olurda kurursa diye düşünmedi

Sarmaşık.

Gönül sallandı her mevsim de

Bir yaz kaldı.

Sevgilerin çürüdüğü mevsim geldi de

Aklın agelmedi sarmaşığın

Kuraklık geliyor...

Bir damla su için

Bedeni titriyor...

C. Burcu Karakaya

Antalya

30/05/2004', 'Bağından koptu sarmaşık Doludizgin ırmağına koşan Yüreği sardı. Yeşiline kandı da gönül Onu durmadan suladı. Azdı sarmaşık Sardı sardı, boğa...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sarmasik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minnet', 'minnet-ahmet-aksoy-u7sdc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'siz ki bir asımlık ömürlerle mahşere ulaştınız

artık sonsuza kadar yerinizdir üstünde başımız

can verdiniz aşkla adına  insanlık ve halklarınız

artık sadece ölümsüzlüğüzün tadına varınız', 'siz ki bir asımlık ömürlerle mahşere ulaştınız artık sonsuza kadar yerinizdir üstünde başımız can verdiniz aşkla adına  insanlık ve halkları...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/minnet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Petrol diye', 'petrol-diye-seref-yildirim-veyii', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sokaklar bomboş......

Etrafta ölümcül sessizlik

Kimileri sığınaklarda,tedirgin 

Alışsalar da bombaların yaşamları yutmasına

Korku dolu gözleri, kurtulabilmenin duasında

İşte yine başladı...

Dehşet saçan uçakların gök gürültüleri 

Dolaşıyorlar sinirlerin sınamasında acımasızca

Yağdırıyorlar  aralıksız lanet yüklerini  tarlalara,binalara,

Emir verenler mutlu,

Alanlarsa görev aşkında gururlu

Hedefler uzak,yakın paramparça atomlarına ayrılırken

Çığlıklar her yanı sarmış, gözler yuvalarından fırlamış,

İnsan bedenleri düşmüş topraklara bir bir

Kafa,kol,bacak uçmuş, dağılmış leş yığınları  etrafa,

Savunma yapan asker, teknoloji karşısında tükenip bitmiş 

Zaman durmuş,alev saçan,ölüm makineleri  durmamış 

Saatler aylara,yıllara dönmüş

Kanlar sel olup pınarlara karışmış,kuşlar bile utanmış uçmaktan 

Bitmiş sonunda bitmesine de; 

Geride ne kalmış? ? ? 

Dualarına sığınmaktan başka güçleri olmayan binler,yüz binler

Nedenini bile anlayamadan, masumca, kokuşmalarda  buluşmuşlar.

Üst üste yığınlar uluşturarak  gübrelere karışmış bedenleri

Süper güç cezasını vermiş asi evladın

İntikamını almış ikizlerin

Hem de, adını bile koymuş katliamlarının

Petrol diye,

Yeni düzen diye,

Dünyayı terörden kurtardım diye,

Kimyadan,biyolojiden  sınıfta kalmasına aldırmadan...... 

30.05 2004', 'Sokaklar bomboş...... Etrafta ölümcül sessizlik Kimileri sığınaklarda,tedirgin  Alışsalar da bombaların yaşamları yutmasına Korku dolu gözle...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yıldırım']::text[], 8.5, '{"poet":"Şeref Yıldırım","poet_slug":"seref-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/petrol-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fark Ve Yanıt', 'fark-ve-yanit-derin-oger-lkzdu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben yaratmadım bu yüreği

Ben tomurcuklanıp ben çiçeklenmedim

Çılgınca esen rüzgâr yürüyen su sendin

Baharın gözündeki güneş kor ateş sendin

Sendin yanmanın acısı

Müjdeli haberim sevgi sözüm iki gözüm

Tenimde sevdiğim nefesimde hissettiğim

Güzel havam hoş kokum duygu sağnağım

Yârim yarım yüreğimdeki coşkum sendin

Sendin gözümün gözdesi

Dudağımı saran nağmelerde

Hasreti yanağımda sönen yaşlarda

Gözümde düşlerimin yol yol gezdiği 

Selam edip adres adres sorduğu sendin

Sendin göğsümün iç çekişi

Adını anmak dudağın sevdasıydı

Nefesinden içip umman olmak gönlün çabasıydı

Susup içime çöktü beni alıp götürüşünün görkemi

Yoruldu anlatmak için seviyorum diyebilmenin farkı

Yürek kendine sivrilerek verdi yanıtını............', 'Ben yaratmadım bu yüreği Ben tomurcuklanıp ben çiçeklenmedim Çılgınca esen rüzgâr yürüyen su sendin Baharın gözündeki güneş kor ateş sendin ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/fark-ve-yanit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerelerdesin?', 'nerelerdesin-vecdi-murat-soydan-2junx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'NERELERDESİN? 

Bana şiir yazdıran güzel kadın,

Bir dua gibi, dilimdedir adın.

Özünde duruyor, eksilmez tadın

Beni çok ağlattın, nerelerdesin? 

Gelirsen, güller dererim yoluna,

Sararım bedenimi de ruhuna,

İste canımı, kurbandır uğruna.

Beni çok inlettin, nerelerdesin? 

Seversen, kalbimi açarım sana.

Şansım olmadı benim aşktan yana,

Son bir şans ver ne olur, acı bana.

Beni çok beklettin  nerelerdesin? 

Muhip Erdener SOYDAN', 'NERELERDESİN?  Bana şiir yazdıran güzel kadın, Bir dua gibi, dilimdedir adın. Özünde duruyor, eksilmez tadın Beni çok ağlattın, nerelerdesin...', ARRAY['Türk Edebiyatı','Şiir','Vecdi Murat Soydan']::text[], 8.5, '{"poet":"Vecdi Murat Soydan","poet_slug":"vecdi-murat-soydan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nerelerdesin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlüğün', 'ozgurlugun-gulden-karabudak-wdvf9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'alazında üşür gönlüm

bir çocuk edasıyla

sığındığım uzvundu göğsün

bel bağlanılan ne varsa

içimde külledim inatla

inancım ezildi sanma

ben yine de bağlıyım

peri yüzlü güzel yalana

bir kuşun kanadında belki

bir bulutun kenarında

belki bir damla inançta

sakladığım tek bir duada

git şimdi istediğin yere

özgürlüğün.../

özgürlüğün içimi erittiğin yerde...', 'alazında üşür gönlüm bir çocuk edasıyla sığındığım uzvundu göğsün bel bağlanılan ne varsa içimde külledim inatla inancım ezildi sanma ben yi...', ARRAY['Türk Edebiyatı','Şiir','Gülden Karabudak']::text[], 8.5, '{"poet":"Gülden Karabudak","poet_slug":"gulden-karabudak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ozgurlugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiye Dair', 'sevgiye-dair-guler-ilgaz-ag4sc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şarkılar söyle bana

Sevgiye dair bu gece

Şarkılar söyle bana

Sevdaya dair bu gece

Kapa gözlerini de

Yüreğinle söyle bu gece

Çalsın sazı ellerin

Alsın götürsün

Karanlığın kelepçelerle bağladığı

Benliğime

Ateşlere atsın dağlasın

Usul usul

Sevginin ışığıyla

O yürekle söylenen

Sevgiye dair

Her bir ezgi

Yaratır yeniden

Özgür bırakır benliğimi

Titrer içim dışım

O coşkuyla yeniden var olurum', 'Şarkılar söyle bana Sevgiye dair bu gece Şarkılar söyle bana Sevdaya dair bu gece Kapa gözlerini de Yüreğinle söyle bu gece Çalsın sazı elle...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgiye-dair-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Gibidir Aşk', 'deniz-gibidir-ask-bekir-mutlu-gokcesu-h1rx5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir an gelir

Hani öyle bir anki

Yolun çoğunu kat ettiğin

Korksan da

Yıkılıp, yıkılıp kalksan da

Yılsan da kimi

Hani tükenmediğin...

Bir an gelir

Yol biter

Hani öyle bir anki

Başlangıcıdır denizin

Ve birden kıyısında

Farkına varırsın kendinin

Deniz gibidir sende aşk

Sonsuz ve imkansız...

İkisini de bitiremezsin...', 'Bir an gelir Hani öyle bir anki Yolun çoğunu kat ettiğin Korksan da Yıkılıp, yıkılıp kalksan da Yılsan da kimi Hani tükenmediğin... Bir an g...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/deniz-gibidir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Sevdan Cehenneme Kaçmış', 'senin-sevdan-cehenneme-kacmis-burcu-karakaya-dk8gb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeni bir varoluş sevmek...Emek emek törpülemek tüm bilinenleri.

Kendisine kalsa insan sınırsız,ama birlikte sevmek sınırlı.Çembere eklenen her insanda daha da sınırlı.Mantık bu yüzden özel de kalmayı seçiyor anlaşıldı.Örneklem büyüdükçe paylaşımlar azalıyor.Yüzdeleri sabitliyemiyor beyin,dağılımın başladığı her yer,bitişin başlangıcı.

Birşeylere başlamanın sıkıntısını,bitişler çoğaldıkça anlıyor insan.Başarının özünü başlangıçlarda buluyor ruhum.Kaybedilen zaferlerin anlamsız güzelliği, kazanılacak zaferlere olan hırsımı arttırıyor.

Ne için, nereye kadar bilinmezliğine verilecek tek cevap..Erkeğini sev. Delice sev.Sen soruları değil, sorular seni kavalasın.

Hayal kurmadan bir hiç insan.Hep güzel hayaller süslüyor yüreğimi.Yitirilen zaman düşünülmeden, koşuyor yürek arzulara.

Ey kahpe kader neden kuytularda beklersin hep beni? Hayallerimi kıskanışın niye, neden beni sana zincirlemek isteyişin ve sana her defasında karşı koyuşum?  Beklenen sen değilsin anla artık, özlenene bırak yaşayışımı.Dostun da senin gibi kahpe.Bıraksın erkeğimin yakasını.

Ah kader, senin terazinin ayarı kaçmış, bırakta ağırlığımızca yaşayalım.Çalma gönülden, çalma sevdadan...Senin sevdan cehenneme

 kaçmış.

C.Burcu Karakaya

Antalaya

30/05/2004', 'Yeni bir varoluş sevmek...Emek emek törpülemek tüm bilinenleri. Kendisine kalsa insan sınırsız,ama birlikte sevmek sınırlı.Çembere eklenen h...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/senin-sevdan-cehenneme-kacmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soyunur Dışım', 'soyunur-disim-orhun-basat-a1q9f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sende kalmış öksüz yanım 

ve yarım yamalak şarkılarım 

taşıyamadığımdandır.

en çok bu saatlerde görünür içim 

soyunur dışım çekinmeden 

yalnızlığımdandır.

siner yüreğime bir deli acı 

kısılır gözleri gecenin

ışığındandır.

bir ıslığın yarısı çağırır beni 

diğer yarısı 

dudaklarında kalır.

ince bir sızıya ayarlı saatlerde 

aynası sevdaya dönük 

bir kadın sancılanır.

belcesi bir kurşuna sevdalı..

Seslendirdiği için; '' Şiir Sesim '' e, Pınar Uslu '' ya teşekkür ve sevgilerimle..', 'sende kalmış öksüz yanım  ve yarım yamalak şarkılarım  taşıyamadığımdandır. en çok bu saatlerde görünür içim  soyunur dışım çekinmeden  yaln...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/soyunur-disim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seven Arar...', 'seven-arar-i-brahim-ethem-bingul-qtq7y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine günlerden pazar

Sen yoksan neye yarar

Telefon çalmıyor yar

Seven bir kere arar...

Aklına mı gelmiyor

Sevda mı kayboluyor

Bu aşk beni üzüyor

Beni benden alıyor...

Başım senle belada

Ben yanarken sevdada

Bir kere anlasan da

Yaşasam aşk dünyanda...', 'Yine günlerden pazar Sen yoksan neye yarar Telefon çalmıyor yar Seven bir kere arar... Aklına mı gelmiyor Sevda mı kayboluyor Bu aşk beni üz...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seven-arar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebessümle', 'tebessumle-bekir-mutlu-gokcesu-6ud9o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben

Debisi artan taşkınlarla

Taşarken sana içimde

Gecelerce

Sevip, okşadın saçlarımı

Ruhumu ve çocuk bakışlarımı

Sen saatlerce...

Ben baş başayken aynada

Puslu suretimle

Ve patlarken volkanlar içimde

Sardın beni sen

Hiç bitmeyen özleminle...

Ben 

Mahkum edecekken kendimi

Yüreksiz sensizliğime

Ve hibe edecekken şiirlerimi

Sana dair geceye

Usulca fısıldadın

Bu gece bana şiir yok mu? 

Diye

Güldürdün beni yine

Güzel sabahlara 

Böyle hep tebessümle...', 'Ben Debisi artan taşkınlarla Taşarken sana içimde Gecelerce Sevip, okşadın saçlarımı Ruhumu ve çocuk bakışlarımı Sen saatlerce... Ben baş ba...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tebessumle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anacığım', 'anacigim-tamer-ozeken-6dfpi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hergün resmine bakıp seni düşünüyorum

Çektiğin acıları okuyorum gözlerinden

Bizleri büyütürken kendin küçülüyordun

Hepimizden ayrı ayrı çekiyordun anacığım

Biliyormusun bende baba oldum

Sen bunu göremedin sevgili anacığım

Senin çektiklerini anlamak için anacığım 

İllede babamı olmak lazımdı bilmiyorum

Seni şimdi çok daha iyi anlıyorum anacığım

Canım anacığım bizleri büyüttün kendini feda ettin

Bizleri burada yanlız bıraktın ve gittin

Seni her geçen gündaha çok arıyoruz

Gittiğin yerde rahat uyu anacığım

Bizleri artık hiç,hiç düşünme anacığım

Senin sayende bizler dimdik ayaktayız

Gözlerimiz yaşlıda olsa anacığım

Bizlere bıraktğın en büyük miras

Birbirimize bağlılığımızdır anacığım

Birgün bizlerde senin gittiğin yere gideceğiz

İşte ozaman,işte ozaman anacığım

Hemen gelip elini öpeceğim anacığım

Bu dünyada hasret kaldığım sana

Bırgün bende kavuşacağım anacığım

Sakın,sakın korkma anacığım kendimi öldürmeyeceğim.', 'Hergün resmine bakıp seni düşünüyorum Çektiğin acıları okuyorum gözlerinden Bizleri büyütürken kendin küçülüyordun Hepimizden ayrı ayrı çeki...', ARRAY['Türk Edebiyatı','Şiir','Tamer Özeken']::text[], 8.5, '{"poet":"Tamer Özeken","poet_slug":"tamer-ozeken","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anacigim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan Hangi Baharda Düştü...? (Hani Hangilerimiz)', 'sevdan-hangi-baharda-dustu-hani-hangilerimiz-mehmet-kizilay-n2inj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hani hangilerimiz..? 

hangi hangiler sorguluyor seni? 

hangi ekinin başağını,

hangi başağın tanesini..

_________________çaldın..

hangi tropikalin süzerek rüzgarını

cehenneme çevirdin 

______________her yanı...

hangi bankizi devşirdin de

aysbergin görünen yüzüyle

__________yüzleşmeye

kalkışıyorsun....................! 

hangi yare sadık kaldın

hangi yari aldatmadın

hangi zulümden kalmadır

______________ihanetin(!)

sevdan hangi baharda düştü

hangi şehrin surlarından

__________________kopardın

kanıksamalarını.................! 

bakışlarımda boğuluşuna 

sebep olan

hangi fahişenin gülüşüdür...? 

gözlerinde titreşen sarhoşluk../

esrikliğindeki ruhsuzluk....neyse..? ? ? 

hangi suda yıkanıp

hangi suyu bulandırdın..

hangi balıkları katlettin..

kaç aşığın sazını

kaç şairin ruhunu çalıp..

_______________öldürdün.

hangi toprağı kirletiyorsun

...utanmak bilmeyen../ gözyaşlarınla..

akdenizi bulandıran 

sen misin? 

ayasofya midenin sekisinde; 

yutkunmuşsun

yutkun! ..

_______bütün burçlarıyla

______________hisarlarıyla

________________kemerleriyle

_____________________sarnıcıyla

______________________sultanahmet''iyle

istanbul''u.../..

hangi topraktır

kirli ayaklarını 

üzerinde gezindiren

hangi rüzgardır

hala

utanmadan

sana sarılan

hangi aydır

kaplara gecede

kapkara yüzüne

hala 

şavkını düşüren..

HANGİ 

HANGİLER

SORGULUYOR 

__SENİ

HANİ

_______HANGİLERİMİZ..? 

1998-Sultanahmet/İst.', 'hani hangilerimiz..?  hangi hangiler sorguluyor seni?  hangi ekinin başağını, hangi başağın tanesini.. _________________çaldın.. hangi tropi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/sevdan-hangi-baharda-dustu-hani-hangilerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-0o0-- Dilimdeki Öfke -0o0--', '0o0-dilimdeki-ofke-0o0-mehmet-kizilay-k2f66', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'soğuk gecelerimden

yorgan yaptım kar ile

dilimdeki öfkeden

vuruldum efkar ile..

.................................

.................................

           .../...', 'soğuk gecelerimden yorgan yaptım kar ile dilimdeki öfkeden vuruldum efkar ile.. ................................. .............................', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/0o0-dilimdeki-ofke-0o0-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbül Şairi', 'bulbul-sairi-musa-tektas-mxi36', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Râhiyalar saçan kokuna kurban

Demişlerdir “Gül’dür Muhammed teri”

Buy-i ıtrın alıp her nefes her an

Seyr-i cemâlindir gözümün feri

Harfler ve heceler seni anlatır

Gündüzler geceler seni anlatır

Doruklar yüceler seni anlatır

Sevmek sevebilmek gönül hüneri

Söz var ki mânidâr, iki hecedir

Söz var ki muamma ve bilmecedir

Her kelime dağlar kadar yücedir

Gelince söylenir zamanı, yeri

Aşkla yaratıldı nûrların nûru

“Ol Muhammed muhabbetin zuhuru”

Fezânın düzeni, dünyanın turu

Kainatta her şey Aşkın eseri

İnandım evvelin sırrı var sonda

Âmennâ Mevlânın nûru var canda

Bir âciz bendeyim dost kapısında

Ey sultanım kabul eyle hakiri

Gül neslini sevdim âşığım güle

Nakşoldu sûreti bu cân-ı dile

Misali andelip düşsem de dile

Namıma desinler “Bülbül Şairi”

			08.06.03', 'Râhiyalar saçan kokuna kurban Demişlerdir “Gül’dür Muhammed teri” Buy-i ıtrın alıp her nefes her an Seyr-i cemâlindir gözümün feri Harfler v...', ARRAY['Türk Edebiyatı','Şiir','Musa Tektaş']::text[], 8.5, '{"poet":"Musa Tektaş","poet_slug":"musa-tektas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bulbul-sairi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötesindeyim', 'otesindeyim-cafer-tayyar-ozkan-lwrsi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Can parem, bir içim suyum,

Sensiz durulmaz ki ruhum,

Sevginle hayat bulurum,

Yaşamın ötesindeyim... 

Can kuşum, en büyük tutkum,

Sana gönülden vurgunum,

Yanımda yoksun durgunum,

Aşkının ötesindeyim...

Dilersen çağır ruhumu,

Sana canımla geleyim,

Gözpınarımsın, cansuyum,

Öpüşün ötesindeyim...

Can bedenden çekilirken,

Sözünün esiri oldum,

Hep kavuşmayı beklerken,

Vuslatın ötesindeyim...

22 Kasım 2002 Ankara', 'Can parem, bir içim suyum, Sensiz durulmaz ki ruhum, Sevginle hayat bulurum, Yaşamın ötesindeyim...  Can kuşum, en büyük tutkum, Sana gönüld...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/otesindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olacak Şimdi+', 'ne-olacak-simdi-bayram-tunca-qg0wu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sendin tutunacak tek dalım

Sendin benim çiçeğim balım

Yalnız sendin neşe kaynağım

Ne olacak şimdi benim halim

Sendin en iyi ilham kaynağım

Ah sendin benim elim ayağım

Sendin benim gözüm kulağım

Senin gibisini nerden bulayım

Sendin benim yegane dayanağım

Ah sensizliği ben nasıl dayanayım

Sendin benim aşım ekmeğim suyum

Sensiz bu âleme hiç olur mu doyum

Sendeydi benim gerekli dört unsurum

Seninle olan anılarımı nasıl unuturum

Şu hicranlı gözyaşımı nasıl kuruturum

Ancak vuslatla bu dertten kurtulurum

31.05.2004-08:05

Aşk Ateşten Gömlek', 'Sendin tutunacak tek dalım Sendin benim çiçeğim balım Yalnız sendin neşe kaynağım Ne olacak şimdi benim halim Sendin en iyi ilham kaynağım A...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ne-olacak-simdi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
