INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Bekliyorum', 'gel-bekliyorum-kamil-boyraz-qjydb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Susunca şarkılar susunca dilim.

Her sabah seninle başlıyor günüm.

Gidişin bu gönüle getirir ölüm.

Geceyi gündüze ekliyorum.

Ölmeden bu beden gel bekliyorum.

Sokaklara koydum senin adını

Almadım başka dilde tadını

Yakma ne olursun yeter canımı

Geceyi gündüzüme ekliyorum.

Ölmeden bu beden gel bekliyorum.

Lal oldu bahçemde ötmez bülbüller.

Açmıyor gönlümde tomurcuk güller.

Seni isteyecek tanrıdan diller.

Geceyi gündüzüme ekliyorum.

Ölmeden bu beden gel bekliyorum.', 'Susunca şarkılar susunca dilim. Her sabah seninle başlıyor günüm. Gidişin bu gönüle getirir ölüm. Geceyi gündüze ekliyorum. Ölmeden bu beden...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gel-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taa içimde ki ateş', 'taa-icimde-ki-ates-kadir-yavuz-kulualp-b8ayd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Taa içimde ki ateşi arıyorum.

Artık yok,biliyorum.

Belki bulurum,sanıyorum.Bulamam biliyorum.

Kin,nefret,heyecan,şevk...hırs,azim

artık............

Belki,bazen misafirliğe gelirsiniz

                                        bekliyorum.', 'Taa içimde ki ateşi arıyorum. Artık yok,biliyorum. Belki bulurum,sanıyorum.Bulamam biliyorum. Kin,nefret,heyecan,şevk...hırs,azim artık........', ARRAY['Türk Edebiyatı','Şiir','Kadir Yavuz Kulualp']::text[], 8.5, '{"poet":"Kadir Yavuz Kulualp","poet_slug":"kadir-yavuz-kulualp","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/taa-icimde-ki-ates-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Çiçeğim''e Son Şiir', 'kir-cicegim-e-son-siir-i-smail-sahin-nbnut', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi uzaktasın sen; çok uzakta

Uzaklardan geliyor sesin

Sesin şimdi bir yabancı

Yabancılarınki gibi sokakta

Sokaklar gibi karmaşık değil gözlerin

Gözlerin anlatıyor herşeyi

Herşeyinle sen bir yolcusun

Yolcuyken öylesine uğradın bana

Bana sıradan bir han gibi

Han gibi yol kenarında yalnızım şimdi

Şimdi uzaktasın sen; çok uzakta', 'Şimdi uzaktasın sen; çok uzakta Uzaklardan geliyor sesin Sesin şimdi bir yabancı Yabancılarınki gibi sokakta Sokaklar gibi karmaşık değil gö...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kir-cicegim-e-son-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler', 'dortlukler-engin-tas-kzmxf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğimiz dağlarda namlulardan atılır

Tetiği kızlarımızın da rahminde

Kanlı bir sofradır yaşanan

Mavilik ayaklarımıza kadar inmeli

xx              xx               xx

Dayanır dilimiz destanımıza

Bir sözlük acılar yıkıcıdır hep

Her şeyin başı dilana varmaktır

Hep düğün olmalı türkü olmalı

xx              xx               xx

Acıdan gelmişim acı olmuşum

Kimi yüreklere sancı olmuşum

Bağlamış başımı olimpios''ta

Aşağıya inmiş nevruz olmuşum

xx              xx               xx

Demlenir aşkımız yıllarımızda

Ateşi azıcık kısmak da gerek

Bir içimlik şiir olsun isterim

Ömrümüz mavide morda yeşilde

xx              xx               xx

Yüreğimiz son yüzyılın kazanı

Ateş beslenir arzular ısınır

Kavgalar doğar insan değerinde

Bundandır kavgamızın gururumuz olması

Bu çağı damgalamak istiyorum

xx              xx               xx

Amacım her zaman gözlerin oldu

Sevgiyi ve korkuyu buluyorum

Gözlerin yaşamın ve ölümün ayırdı

Sürekli kayboluyorum', 'Yüreğimiz dağlarda namlulardan atılır Tetiği kızlarımızın da rahminde Kanlı bir sofradır yaşanan Mavilik ayaklarımıza kadar inmeli xx       ...', ARRAY['Türk Edebiyatı','Şiir','Engin Taş']::text[], 8.5, '{"poet":"Engin Taş","poet_slug":"engin-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/dortlukler-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahh Kamil...!', 'ahh-kamil-ayhan-pamuk-7fpg4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir bebek dogdu bu sabah

Zeynep Kamil''in 350 no''lu odasinda 

Adini Kamil koydular..

Dogar dogmaz konusmaya basladi Kamil...

Önce su istedi Sasal olacakmis.

Sonra...

Karyolasindan kalkip, oturdu bir sandelyeye 

Sasirdi Ana-Baba,

Sasirdi Doktorlar...

Kamil; önce temiz bez istedi altina 

Sonra bir kagit- bir kalem

Yazmaya basladi istediklerini...

''Baglamayin beni, çözün kundagimi

Özgürlük isterim'' yazdi Kamil.

''Tüm çocuklar doyurulsun

Bolluk isterim'' yazdi Kamil.

''Savaslar bitsin, Insanlar ölmesin

Baris isterim'' yazdi Kamil.

''Seven haykirabilsin, utanmasin sevgisinden

Ask Isterim'' yazdi Kamil.

Gezdi...Dolasti...Dünyayi gördü Kamil

Aksam olmadan döndü odasina asik suratla; 

Aldi kalemi kagidi... Tek cümle yazdi Kamil 

''Geri dönmek isterim''

AH KAMIL...! 

SAIRIN NOTU:

Kamil bugün 17 yasinda..Geçenlerde karsilastik..Yillardir görmemistim,merak edip sordum.''NASIL GEÇTI BUNCA YIL..Isteklerine ulasabildin mi? '' ''HEPSI DEGIL AMA BIRINE ULASTIM''..Dedi.''Hangisi''Diye sordum heyecanla...''ARTIK KUNDAKSIZIM'' Dedi.....VAAAH KAMIL...! !', 'Bir bebek dogdu bu sabah Zeynep Kamil''in 350 no''lu odasinda  Adini Kamil koydular.. Dogar dogmaz konusmaya basladi Kamil... Önce su istedi S...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Pamuk']::text[], 8.5, '{"poet":"Ayhan Pamuk","poet_slug":"ayhan-pamuk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ahh-kamil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuğu Bakışlı Bir Göldür Aşk', 'kugu-bakisli-bir-goldur-ask-bulent-ozcan-ns01u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kuğu bakışlı bir göldür aşk

Ay düşleri devşirir

Yakamoz yalanlarla incinir

Kuğu bakışlı bir göldür aşk

Bir ceylan gibi dağlardan süzülür

Yüreğiyle yıldızları emzirir

Kuğu bakışlı bir göldür aşk

Ele geçmez, yaşadıkça sezilir...

Mart 2004, Enfield Island Village, Londra

Bülent Özcan', 'Kuğu bakışlı bir göldür aşk Ay düşleri devşirir Yakamoz yalanlarla incinir Kuğu bakışlı bir göldür aşk Bir ceylan gibi dağlardan süzülür Yür...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kugu-bakisli-bir-goldur-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birkaç Sırdan Damlalar', 'birkac-sirdan-damlalar-i-smet-barlioglu-u4d7i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dayandım ben bir kapalı kapıya,

Akıl almaz, beyin bilmez iş olur.

Hayran oldum bir direksiz yapıya,

Bir anlatsam iki gözün yaş olur.

Baktım ki ben geceler var, sabah yok,

Masalarda yemekler var, tabak yok.

Bu sofrada bir kıral var, uşak yok,

Aklım, fikrim yerden kalkmaz taş olur.

Gözle gördüm; koca güneş aydınlık,

Akla sordum; zindan gibi karanlık,

Yanar ama aydınlanmaz bir anlık,

Bir büyük sır tam önümde faş olur.

Beyin yoksa gözler de yok el de yok,

Konuşacak ağız da yok, dil de yok,

Canlanacak bacak da yok, bel de yok,

Yüz olmazsa sanma kıldan kaş olur.

Dağa değdim elim ile gecede,

Kanatlanıp kayboldu ta yücede,

Koskoca kuş nasıl durmuş bahçede? 

Hiç sanma ki; her uçan çey kuş olur.

Ele sordum; dağ dediğin taş, toprak,

Akla sordum; tüyden hafif bir yaprak,

Hem de uçar nasıl pervaz yaparak,

Zannetme ki bu sırlarla baş olur.

Göstersem ben yapı ile direği,

Kasığından fırlar aklın böbreği,

Cahillerin sır kaldırmaz yüreği,

Kurcalansa gerçekleri düş olur.

Biz açarız sırrımızı bu kadar,

Küçük zarfa büyük şeyler zor sığar,

Zorladınmı zarfı marfı, zarf patlar,

Sanma; bilen bilmeyenle eş olur.

Barlıoğlu der fazlayı sorma hiç,

Almıyorsa o aklını yorma hiç,

Yel gelecek, kaç, önünde durma hiç,

Kaçamayan bir kokacak leş olur.

(NÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 119-121/412)', 'Dayandım ben bir kapalı kapıya, Akıl almaz, beyin bilmez iş olur. Hayran oldum bir direksiz yapıya, Bir anlatsam iki gözün yaş olur. Baktım ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/birkac-sirdan-damlalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Kim İcat Etti?', 'aski-kim-i-cat-etti-caner-kuru-hb6h4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onca çile, onca dert

Yetti canıma, yetti.

Bir de üstüne hasret,

Aşkı kim icat etti? 

Bir hece ki dillerde,

Süründürür çöllerde,

Bırakır ne hallerde,

Aşkı kim icat etti? 

Gözden kalbe bir tokat,

Nefese kalmaz takat,

Çektikçe artar kat kat,

Aşkı kim icat etti? 

Sesim çınlıyor ayda,

Duymuyorsa ne fayda,

Sevmek biraz kolay da,

Aşkı kim icat etti? 

Yanıyorum her gece,

Yaşamak zor böylece,

Var mıydı daha önce? 

Aşkı kim icat etti? 

Dinmez gönül ağrısı,

Feryat gibi çağrısı,

Merak ettim doğrusu,

Aşkı kim icat etti?', 'Onca çile, onca dert Yetti canıma, yetti. Bir de üstüne hasret, Aşkı kim icat etti?  Bir hece ki dillerde, Süründürür çöllerde, Bırakır ne h...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aski-kim-icat-etti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayamazsın', 'anlayamazsin-i-smet-barlioglu-ya2fq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kul değilsen benim gibi yürekten

Sen benim derdimi anlayamazsın.

Yoksa bir taptığın en has ipekten

Sen benim derdimi anlayamazsın

Tatlı uykuları tanıyor isen; 

Çok çabuk doyuyor, kanıyor isen; 

Dünyadan bir lezzet alıyor isen; 

Sen benim derdimi anlayamazsın.

Çile, elem nedir, asla bilmezsin,

Sevgini bölmüşsün, birleştirmezsin,

Malını, mülkünü üleştirmezsin,

Sen benim derdimi anlayamazsın.

Yatıp uyumuşsun sabahlara dek,

Asla olmamışsın kuşlardan ürkek,

Tek kez yer etmemiş beyninde gerçek,

Sen benim derdimi anlayamazsın.

Anlasan balların döner zehire,

Benzer gözyaşların kanlı nehire,

İnleyip bakarsın göklere, yere,

Sen benim derdimi anlayamazsın.

Bakarsın; kalbine saplanmış bıçak,

Sanırsın göğsünü parçalayacak,

Sanki ruhun olur ateşten ocak,

Sen benim derdimi anlayamazsın.

Hasreti bilmezsin, bilmezsin aşkı,

Kaymamış gözünün karası, akı,

Feryadın tutmamış henüz afakı,

Sen benim derdimi anlayamazsın.

Ruhun elemlere dalamayınca,

Aklın kendisinden olamayınca,

Yüreğin bin yerden kanamayınca

Sen benim derdimi anlayamazsın.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 122-123/412)', 'Kul değilsen benim gibi yürekten Sen benim derdimi anlayamazsın. Yoksa bir taptığın en has ipekten Sen benim derdimi anlayamazsın Tatlı uyku...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/anlayamazsin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalp Kirilmasi', 'kalp-kirilmasi-suat-oktay-p71k3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özur dilemekte gec kaldin be guzelim...

gecen Sabah ''KALP KIRILMASI'' na maruz kaldim, cunku! 

KIRIKlar onarilamadi, tum cabalara ragmen! 

Gercek dostlarimin yuregine defnedildim,

cuma namazina mutakiben! 

Otopsi sonucu; dört ''KIRIK'' saptadim kalbimin narin noktalarinda...

En ACISI  duruyor, 

KIRILIRDIGI anki yerinde; 

taaa en dipte! 

Suat Oktay 

Göteborg/Nödinge(29.05.04)', 'Özur dilemekte gec kaldin be guzelim... gecen Sabah ''KALP KIRILMASI'' na maruz kaldim, cunku!  KIRIKlar onarilamadi, tum cabalara ragmen!  Ge...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kalp-kirilmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok mu?', 'yok-mu-i-smet-barlioglu-clq2f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yatma kuru yerde, yüksel engine,

Evrenler içinde evrenler yok mu? 

Hiçbir şey durmuyor kendi kendine,

Bir büyük cevhere imrenen yok mu? 

Hızlar sonsuz olsa; boy sıfır olur,

O var sandıkların hemen kaybolur,

Yerinde yel eser, duman savrulur,

Gaipten kulağa seslenen yok mu? 

Bir evren evrenin zerre ötesi,

Sessizlik içinde sert adım sesi,

Nefesler taşıyor nice nefesi,

Boşluğa sımsıkı yaslanan yok mu? 

Ne evrenler var ki; yağmuru boldur,

Damlası yaş değil, taştan doludur,

Taşların herbiri dağdan uludur,

O taş yağmurunda ıslanan yok mu? 

Ne sular vardır ki; serttir demirden,

Milyonlar el atsa kalkmaz yerinden,

Zerrenin her biri ağır birinden,

Boşluklar içinde paslanan yok mu? 

Göz dediğin organ görmez herşeyi,

Biraz hızlı uçsa; sezmez sineği,

Acep gözönünde uçan deveyi

Görmeyip, seçmeyip yok sanan yok mu? 

Her kime sorarsan bu dünya tektir,

Oysa kaç dünyaya küçük örnektir,

Dünyalar içiçe, hevenk hevenktir,

Hepsini bir sanıp aldanan yok mu? 

Barlıoğlu der ki; sanma göz fersiz,

Nice gözler var ki; tülsüz, perdesiz,

Zannetme ki boşluk kimsiz, kimsesiz,

Boşluğa sarılıp tırmanan yok mu? 

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 124-125/412)', 'Yatma kuru yerde, yüksel engine, Evrenler içinde evrenler yok mu?  Hiçbir şey durmuyor kendi kendine, Bir büyük cevhere imrenen yok mu?  Hız...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yok-mu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mervam', 'mervam-i-brahim-emre-petek-bwo7c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Masum kalbimde gördüğüm                                                                                       Elimde demet demet gülle beklediğim                                                                                     Resmini çizip çizip sildiğim                                                                                           Ve    gecelerce                                          düşlediğim                                                                                      Aşkını hayalimde                                            yaşattığım                                                                                        Meğer senmişsin beklediğim,sevdiğim.', 'Masum kalbimde gördüğüm                                                                                       Elimde demet demet gülle bekle...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Emre Petek']::text[], 8.5, '{"poet":"İbrahim Emre Petek","poet_slug":"i-brahim-emre-petek","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/mervam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kefenin Cebi', 'kefenin-cebi-i-smet-barlioglu-4oto0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neden böyle selamın, sabahın bile para? 

Hele söyle evladım, kefenin cebi mi var? 

Gerçekten neden böyle düşmüşsün uzaklara? 

Hele söyle evladım, kefenin cebi mi var? 

Bir deste yırtık para değerli mi hatırdan? 

Altın dolu olsa da kasa demir, bakırdan,

Gerçeklere göz atma kartal gibi yukardan,

Hele söyle evladım, kefenin cebi mi var? 

Gözlerin aç, gönlün aç, ellerin aç, yüzün aç,

Çalımın neye yarar, komşun ekmeğe muhtaç,

İnsafın parmak kadar, tamahın kulaç kulaç,

Hele söyle evladım, kefenin cebi mi var? 

Serveti fazla olan zor ayrılır dünyadan

Çünkü gemi demirli okyanusa ortadan,

Tabutla mı gelecek servetlerin arkandan? 

Hele söyle evladım, kefenin cebi mi var? 

Bir tane yetmiyor mu? Aynı maldan on tane,

Zevkin doğuştan olmuş tamahına bahane,

Mezara sığacak mı bu saray, o kaşane? 

Hele söyle evladım, kefenin cebi mi var? 

Kısacık ömür için bu ne tükenmez gayret? 

Bu nasıl akıl, mantık, bu nasıl mide, hayret,

Olur a, bu kadar mı cesur olur cehalet? 

Hele söyle evladım, kefenin cebi mi var? 

Kaç Karun göstereyim, ki; olsun örnek sana? 

Yüzbinlerce kıraldan kalanlara baksana,

İnekler zarar eder, kar eden safi dana,

Hele söyle evladım, kefenin cebi mi var? 

Kime hazırlıyorsun? Kimlere topluyorsun? 

El için bu hevesi nasıl da buluyorsun? 

Biraz acı kendine; fazla yoruluyorsun,

Hele söyle evladım, kefenin cebi mi var? 

Kefenin cebi varsa söyle biz de bilelim,

Bu dünyayı ahrete ceplerde götürelim,

Buradaki hayatı orda da sürdürelim,

Hele söyle evladım, kefenin cebi mi var? 

Barlıoğlu diyor ki; kefende cep arama,

Nasibine razı ol, onu fazla zorlama,

Ecel geldiği zaman mertçe can ver, hırlama.

Hele söyle evladım, kefenin cebi mi var? 

(MÜHÜRLÜ KİLİT ismi altında toplanmış şiirlerden > 126-128/412)', 'Neden böyle selamın, sabahın bile para?  Hele söyle evladım, kefenin cebi mi var?  Gerçekten neden böyle düşmüşsün uzaklara?  Hele söyle evl...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kefenin-cebi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-ceyhun-kuburlu-yzbn3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kağıtların üzerine çizdiğim sınırlarda belirlemek seni

Boşluklarla dolu hayatımı tıka basa doldurmak yağmurlu havalarda

İçimi büyük bir hırsla saran yalnızlığı dinlemek uzun bir süre

Ve akşam kalabalığında kendimi bulup bulup yitirmek en kısa zamanda

Acele ettiğim sevdaların acele yaralarını sarmaya çalışıp

Daha fazla kanatmak deri altlarını

Ve sonra bir bahar yaprağı gibi düşüp dalından 

Sarılmak üzeri yaş topraklara

Canımın acıdığı yerde durup dinlenmek en kuytu yalanlarda

Gemisiz limanların iskeleye bağladığı yalnızlığa hoş geldin demek

Ve sonra yeniden başlamak uzun vadeli yaşamıma 

Hiçbir şarkıda bulamadığım ezgiyi 

Aslında benim yarattığımı anlamak

Geçici mutlulukların kölesi haline gelmek

Ve hayatın ıssız bir anında sana kavuşmak

Şimdi buradan tam oturduğum yerden

Seni düşünmek ve senin yabancı kollarla sarmalandığını bilmek

Hiç tanımadığım birine dokunduğunu öğrenmek

Sonra geçirdiğimiz günler üzerine kendimle kavgaya girişmek

Silahın bende olmasına rağmen damarları parçalananın ben olduğunu görmek

Üzerine yağmur damlaları düşmüş ağaç dalları gibi sarmak caddelere

Göremediğin belki de görmek istemediğin fahişe yanlarını 

Yabancı karakterlerde bulmak sadece

Ve buldukça yitirdiğimiz kendimiz gibi 

Bunca zaman sonra hala düşünüyor olmak seni 

Belki bir günlü cümlelerin gölgesinde

Hala umut etmek gözleri yaşlı bir gökyüzü kıvamında

Hala sabırla beklemek gelmeyecek bir gün gibi

Unutmaya cesaretsiz bir şehrin insanı olarak

Yarından seni dilemek 

Her şeye rağmen en güzel masal gibi

Gerçek olmayan bir masal gibi

Kendimi kendi çocukluğumda bulup kandırmak

Özlediğim için sadece özlediğim için

Çocuk yanlarımı sermek balkona yağmurlu bir havada 

Ve üzerine basacağını bile bile seni ilk gördüğüm yerde

Saatlerimi sevdaya kurmak

Hüzünlü oyunların bakışlarında 

Senin tüm kahpe gamzelerini ağlama saatlerime denk getirmek

Her şeye rağmen ezildiğim belki de azaldığım diyelim 

Kaybettiğim anlarda yani

Kazanan yanlarımı bulup tekrar doğrulmak 

Büyük bir güçle tekrar doğrularak kazanmak 

Senin kahpe gamzelerinin aşağılandığı anlarda

Ve sonra hayatın en güzel şarkısını mırıldanmak

Sanki okyanusların üzerinde yürüyen mutlu bir adam gibi

Yada gökyüzünde kısalan sonsuzluk gibi

Yepyeni bir sayfaya başlamak 

Dipnotu düşülmüş isminden kurtarılmış bir sayfaya

“Yeniden” yazarak başlamak

Sızısını her üşüdüğünde duyan kemiğim gibi

Sayfalarında üşüdüğü anlarda içindeki sözlerin sızlattığı ben gibi

Aklımın dipnotuna düşmen

Özlediğim için sadece özlediğim için

Son bir sayfa ayırıp sana

Son bir şiirde güzel sözleri bulup karanlık adamların kitaplarından

Sadece sana hitap etmek

Yalnızca ve yalnız özlediğim için

Yalnızlığın kutsal yanlarını keşfedip

Senin gökyüzüne iyi yanından bakmaya çalışıyorum

Herkesin aşağıladığı senin gökyüzünde

Ben en güzel uçurtmaların çocuk kahramanlarını canlandırıyorum

Şimdi buradan tam oturduğum yerden

O bedenimin tüm kutsallığıyla sarıldığım ince bele bir başkasının sarıldığını görerek

Ve her dokunuşunda tanrı saydığım parmaklarını 

O yabancının teninde dolaştığını bilerek

Sana o sıcak aile mutluluğu değerinde

Son bir bakış sunuyorum

Özlediğin ve belki de özlediğin için terk ettiğin 

Bu hayata, ben bıraktığın yerden bakıyorum

Yarının görüş açısını bu günden sayfalara çizemediğim için

Sana son bir sözle hoşça kal demek

Ve seni bulduğum andaki şarkının

Seni kızdıran sözleriyle, belki de şu yaşadığımız hayatın anlamını taşıyan tek cümleyle 

“Sevmek eskidenmiş güzelim 

Sanki yıllar öncesinde kalan”

Geç kalınmış bir hayatta geri kulaç atarak 

Geldiğin mevsimde senden dönüş bileti bile istemeden

Kaybettiğim ve kaybetmeyi istediğim bu oyunda Senden son bir kez

Kendimi bulma yolculuğu için cam kenarı biletler dileniyorum

“Hani demiştin ya sen giderken

Yolcu yolunda gerek”

Mutluluğun kara sularını bulup kendi mutsuzluğumu

En derin sularda bırakmaya gidiyorum

Hoşça kal yalnızca özlediğim için 

Ve sadece özlediğim için

Ve kavuşamadığım hayal bir gerçek için

Hoşça kal....', 'Kağıtların üzerine çizdiğim sınırlarda belirlemek seni Boşluklarla dolu hayatımı tıka basa doldurmak yağmurlu havalarda İçimi büyük bir hırs...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/hoscakal-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kocamış Olma', 'kocamis-olma-i-smet-barlioglu-s6ldo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İhtiyar saygıya layık olmalı,

Ol bir gün ihtiyar, kocamış olma.

Ummanlar dolaşmış kayık olmalı,

Ol bir gün ihtiyar, kocamış olma.

Ak-pak olur saçı ihtiyarların,

Günü boş geçmemiş bahtiyarların,

Dün nasılsa inan, öyledir yarın,

Ol bir gün ihtiyar, kocamış olma.

İhtiyar mantığı etmiştir yasa,

Geçmiş günlerine hiç etmez tasa,

Aynen Tur Dağı ''nda bir yaşlı Musa,

Ol bir gün ihtiyar, kocamış olma.

Yaşını aklına eş eden yaşlı,

Gayet sakin olur, olmaz telaşlı,

Gözleri yaşlıdır, bağrı da taşlı,

Ol bir gün ihtiyar, kocamış olma.

İhtiyar sözünü düşünür söyler,

Her nasıl söylerse öyle de eyler,

Cahillere kızmaz, sadece güler,

Ol bir gün ihtiyar, kocamış olma.

İhtiyar yaşlanmış züppe değildir,

Yaşlanan sadece cübbe değildir,

İhtiyarlık ardır, rütbe değildir,

Ol bir gün ihtiyar, kocamış olma.

İhtiyar baktı mı ürkmeli insan,

Donmalı damarda edebinden kan,

İhtiyar akılla yükselmiş sultan,

Ol bir gün ihtiyar, kocamış olma.

Beyniyle, aklıyla sever ihtiyar,

Yüzünde yaz vardır, kalbinde bahar,

Öfkelense bile içinde saklar,

Ol bir gün ihtiyar, kocamış olma.

İhtiyarın eli hastaya candır,

Şefkati yakuttur, kendi mercandır,

İhtiyara saygı büyük erkandır,

Ol bir gün ihtiyar, kocamış olma.

İhtiyar baktı mı anlar insanı,

Ayna gibi görür bütün kafanı,

Çünkü tanımıştır cümle cihanı,

Ol bir gün ihtiyar, kocamış olma.

İhtiyar değildir kartalmış nebat,

Boşa geçmemiştir ondaki hayat,

Öfkesi dinmiştir, hırsları rahat,

Ol bir gün ihtiyar, kocamış olma.

Yaşlılık iğrençlik, kirlilik değil,

Sapıklık, bunaklık, delilik değil,

Akılda, fikirde gerilik değil,

Ol bir gün ihtiyar, kocamış olma.

Barlıoğlu der ki; ihtiyar taçtır,

Sadece sevgiye, dosta muhtaçtır,

Gerçek ihtiyarlar derde ilaçtır,

Ol bir gün ihtiyar, kocamış olma.

(Hikmet BARLIOĞLU (1933-2003)  ''NUN

MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 129-131/412)', 'İhtiyar saygıya layık olmalı, Ol bir gün ihtiyar, kocamış olma. Ummanlar dolaşmış kayık olmalı, Ol bir gün ihtiyar, kocamış olma. Ak-pak olu...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/kocamis-olma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-fetih-sait-akkaya-wx4ah', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(D) ünyamsin sen etrafinda kosusturdugum

(i) lk ve son askimsin gençlik çagimda

(L) eyla mecnunu bir seviyorsa ben seni bin seviyorum

(E) y benim yürek sözlüm sevda kokulum

(K) orkmuyorum sevdamdan seni alacagim tanridan     

                            ve o sihirli kelimeyi on binlere söylüyorum

                                            ''SENI ÇOOOK SEVIYORUM''', '(D) ünyamsin sen etrafinda kosusturdugum (i) lk ve son askimsin gençlik çagimda (L) eyla mecnunu bir seviyorsa ben seni bin seviyorum (E) y ...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dilek-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimle Evlenirmisin?', 'benimle-evlenirmisin-ayhan-i-lkmen-mgrsr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazı şeyler var anlatmak istediğim sana,

Anlatsam kızarmısın bana,

Yada, o bir tek sözcüğü söyleyip,

Sarılırmısın boynuma,

Benimle evlenirmisin desem,

EVET dermisin bana.', 'Bazı şeyler var anlatmak istediğim sana, Anlatsam kızarmısın bana, Yada, o bir tek sözcüğü söyleyip, Sarılırmısın boynuma, Benimle evlenirmi...', ARRAY['Türk Edebiyatı','Şiir','Ayhan İlkmen']::text[], 8.5, '{"poet":"Ayhan İlkmen","poet_slug":"ayhan-i-lkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/benimle-evlenirmisin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni görmek imkansiz rüyalarimda olmasa', 'seni-gormek-imkansiz-ruyalarimda-olmasa-fetih-sait-akkaya-t2mif', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir yar sevdim

gül veremedim sevdigimi söyleyemedim

gözlerine bakamadim dikkatlice

içimdeki sevgiyi veremedim

anladim ki ask göz göze gelme 

simdiki tabirce elektirik alma isidir

iste o an çok önemlidir.

ben seni göremedim

seninle sadece rüyalarimda göz göze gelebildim

inan ki 

seni görmek imkansiz

rüyalarimda olmasa

en büyük asklarin temeli budur

belki 3sn belki 5sn

kerem ile asli leyla ile mecnun 

keremin gözlerine çekilen sevda immesi

daglari delip geçmesi

mecnun çöllere düsmesi

iste o gözleri ben göremedim

rüyalarimda bende keremim

bende mecnunum çöllere düsmüs

ah gerçek olsada çöllere düssem

ama 

seni görmek imkansiz

rüyalarimda olmasa 

imkansizlar imkansizligi

rüyalarim rüyalarinı 

gözlerim gözlerini

ben seni kovalar oldum

ama ne çareki

''SENI GÖRMEK IMKANSIZ

RÜYALARIMDA OLMASA''', 'bir yar sevdim gül veremedim sevdigimi söyleyemedim gözlerine bakamadim dikkatlice içimdeki sevgiyi veremedim anladim ki ask göz göze gelme ...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/seni-gormek-imkansiz-ruyalarimda-olmasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Çok Seviyorum', 'seni-cok-seviyorum-ayhan-i-lkmen-21rp3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç bir zaman çiçekler solmasın,

Hiç bir zaman gözlerin ağlamasın,

Tanrıdan tek dileğim,

Seni bana bağışlasın

Bugünlerde bir tuhafım,

Anılarla dolu hertarafım,

Sanadır tek itirafım,

Seni çok çok seviyorum.', 'Hiç bir zaman çiçekler solmasın, Hiç bir zaman gözlerin ağlamasın, Tanrıdan tek dileğim, Seni bana bağışlasın Bugünlerde bir tuhafım, Anılar...', ARRAY['Türk Edebiyatı','Şiir','Ayhan İlkmen']::text[], 8.5, '{"poet":"Ayhan İlkmen","poet_slug":"ayhan-i-lkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-cok-seviyorum-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seherlerde', 'seherlerde-hifzi-ozbekmez-xbf92', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dertler hep tazelenir

Geceleri seherlerde

Benim aşkım alevlenir

Geceleri seherlerde

Bülbül hapistir kafeste

Güller solar deste deste

Adın vardır her nefeste

Geceleri seherlerde

Kurulur çarşı pazarım

Oturur şiir yazarım

Ben bu hayattan bezerim

Geceleri seherlerde

Hasretin bağrımı yakar

Gözlerimden yaşlar döker

Latifim boynun büker

Geceleri seherlerde', 'Dertler hep tazelenir Geceleri seherlerde Benim aşkım alevlenir Geceleri seherlerde Bülbül hapistir kafeste Güller solar deste deste Adın va...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seherlerde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öleceğim', 'olecegim-gokhan-karaduman-vmfth', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani zaman kolluyordun ya

Söylemek için sevdiğini.

Hazırlanabilirsin

Çünkü sabaha kalmaz öleceğim

Ve Mezar taşıma fısıldamanı dileyeceğim.', 'Hani zaman kolluyordun ya Söylemek için sevdiğini. Hazırlanabilirsin Çünkü sabaha kalmaz öleceğim Ve Mezar taşıma fısıldamanı dileyeceğim....', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/olecegim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunamadım Sana', 'dokunamadim-sana-i-lyas-kurt-qrfvt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gördüm gökyüzünde seni,

Uzattım ellerimi,

Günahların en güzelini yaşadın benimle,

Bu ateş cennet''tir be gülüm seninle

Dokunamadım sana, ulaşamadım,

Bu kadar severken seni, yaşayamadım,

Dayanamadım buna, alışamadım,

Bu kadar severken seni, ayrılamadım

Sen kadınım desem, 

Olurmusun benimle,

Güllerin anısına uyusam dizlerinde,

Bu ölüm şereftir be gülüm seninle

Bağlandım sana, kopamadım,

Bu kadar severken seni, bırakamadım,

Katlandım ayrılığa, kaldım tek başıma,

Bu kadar acıya rağmen, ağlayamadım.

(Adana 2004)', 'Gördüm gökyüzünde seni, Uzattım ellerimi, Günahların en güzelini yaşadın benimle, Bu ateş cennet''tir be gülüm seninle Dokunamadım sana, ulaş...', ARRAY['Türk Edebiyatı','Şiir','İlyas Kurt']::text[], 8.5, '{"poet":"İlyas Kurt","poet_slug":"i-lyas-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dokunamadim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tomurcuğun Doğuşu', 'tomurcugun-dogusu-guler-ilgaz-5k7uk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakarken doğaya

Gökler davul gibi

Gümbürderken ışık ışık

Dallar sessizce

Salarken tomurcuğun

İçindeki saklı çiçeğini

Güneşin ışığı ile yıkarken

Bulutlar uyanıp ta

Salınırken nazlı nazlı

Çeker bir tomurcuk

Bulutun içindeki suyu

Dönmek için güneşe yüzünü

Seyrederim öylesine

Doğumun hazırlanışını', 'Bakarken doğaya Gökler davul gibi Gümbürderken ışık ışık Dallar sessizce Salarken tomurcuğun İçindeki saklı çiçeğini Güneşin ışığı ile yıkar...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tomurcugun-dogusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız...Aşk...', 'i-mkansiz-ask-nevin-kurular-n99ri', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kim ne söylerse söylesin / Unutmuş deme

Sevgimize aşkımıza  / İhanet etme

Gözlerinden ayrılığa /gözyaşı dökme

-Sensiz geçen günlerimde / Senle doluyum

........İmkan olsa buluşmaya / Ben dururmuyum

Şu karanlık geceleri / benle yaşasan

Hayalde resimde değil / yanım da olsan

Baharlara doğan güne / senle başlasam

-Bu hasretle ömür geçse,/ Unuturmuyum

......İmkan olsa kavuşmaya / Hiç dururmuyum

Çocuklar kadar masumuz / böyle bir aşkta

Yılların koyduğu aklar / olsada saçta

Ömür boyu seveceğiz / dedik taa.. başta

-Pişman olduğumu sanma / Hiç olurmuyum

......İmkan olsa kavuşmaya / Ben dururmuyum

(Rahmetle andığım..

Dr. Osman İper Tarafından iki ayrı formda Muhayyer Makamda 

bestelenmiş Güftelerim  Bestelerim kitabında yer almıştır.)', 'Kim ne söylerse söylesin / Unutmuş deme Sevgimize aşkımıza  / İhanet etme Gözlerinden ayrılığa /gözyaşı dökme -Sensiz geçen günlerimde / Sen...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/imkansiz-ask-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Kalbim', 'anla-kalbim-azmi-gunes-xmpqt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sorma kalbim

Onu sorma artık bana

Bıraktı gitti

Anla oda vicdansız çıktı

Söyle kalbim

Onu söyle biz böyle mi sevdik

Ağlattı gitti

Anla oda zalim çıktı

Dinle kalbim

Onu dinle bak ne dedi

Hiç seni sevemedimki

Anla oda yalancı çıktı

26.05.2004

11:45

Çarşamba', 'Sorma kalbim Onu sorma artık bana Bıraktı gitti Anla oda vicdansız çıktı Söyle kalbim Onu söyle biz böyle mi sevdik Ağlattı gitti Anla oda z...', ARRAY['Türk Edebiyatı','Şiir','Azmi Güneş']::text[], 8.5, '{"poet":"Azmi Güneş","poet_slug":"azmi-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/anla-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Günden Sonra', 'o-gunden-sonra-i-lyas-ozmen-uokjp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ufuklar karardı renkler simsiyah

İçimden bu şehri yakmak geliyor

Olsa da bin vebal olsa da günah

İçimden bu şehri yakmak geliyor

Belki bir şaşkınım belki de deli

İnsan biraz kadir kıymet bilmeli

Bu son haksızlığı gördüm göreli

İçimden bu şehri yakmak geliyor

Nerede insanlık bu mudur vefa

İyiyi güzeli koydular rafa

Ateşle barutla binlerce defa

İçimden bu şehri yakmak geliyor

Bu ne politika nede siyaset

Bu kirli bir oyun bu bir ihanet

Ya bir deprem gibi ya da bir afet

İçimden bu şehri yıkmak geliyor

Havası is koktu suyu bulandı

Mertlik geçmez oldu namert çoğaldı

İyiler çekildi kötüler kaldı

İçimden bu şehri yakmak geliyor

Bu şehirde gördüm kini nefreti

Vefasızlık oldu ünü şöhreti

İbret-i alem için çakıp kibriti

İçimden bu şehri yakmak geliyor

Sokaklar ağlıyor caddeler yaslı

Gözler görmez olmuş yürekler paslı

Özü buysa eğer bu ise aslı

İçimden bu şehri yakmak geliyor

(29 Mart yerel seçimlerinde yaşadığım şehire büyük emekleri

 geçtiğine inandığım ve tekrar seçileceğine herkes tarafından

 inanılan belediye başkanımızın seçimi kaybetmesi üzerine 

 seçim gecesi o ruh halimle yazmış olduğum şiirimi sizlerle 

paylaşmak istedim.NOT:Kesinlikle siyasi bir duygu değildir)', 'Ufuklar karardı renkler simsiyah İçimden bu şehri yakmak geliyor Olsa da bin vebal olsa da günah İçimden bu şehri yakmak geliyor Belki bir ş...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/o-gunden-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '4Geçmiş Unutulmuyor', '4gecmis-unutulmuyor-nurten-altinok-cjhz1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir tenin kokusu

 leylak

sinmiş dört bir duvarıma

bir izbe oda

kilit vurulmuş güneşin camlarına

anılara

katil rüzgarlar

acıtıyor canımı 

paslı zımpara 

esmeyin

bir o kadar derinlerdeyim

körkütük

bir o kadar vurgunlarda

yürek yarası 

göz ağrısı

esmeyin

bir şarkı

hüzzam

kalaysız bakır sini

yerde çilingir sofra

kapı zilindeki şifre

ellerin

gözlerin

buluşmalar

ayrılmalar

susturun tüm sesleri

takvimlerim ağlıyor

yoğun bakımda gençliğim

kim getirebilir ilk sevgiliyi Beşiktaş’tan

ki yasansin genclik yenibastan

...

.

.

.

.

..

.

........................................................Var git,

Böyle ferman etti Cahit,

Al getir ilk sevgiliyi Beşiktaştan; 

Yaşamak istiyorum gençliğimi yeni baştan..............................Cahit S. Taranci', 'bir tenin kokusu  leylak sinmiş dört bir duvarıma bir izbe oda kilit vurulmuş güneşin camlarına anılara katil rüzgarlar acıtıyor canımı  pas...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/4gecmis-unutulmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buhran Gecelerde', 'buhran-gecelerde-galip-karabatak-1goep', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana uyu deme

Ben uykuyu seninle unuttum

Kan akıyor gözlerimden

Bilemeden

Son yaşımı da sana kuruttum...

Ve bu buhran gecelerde sıkarken dişlerimi,

Tırnaklarım mühürlerdi duvarları

Yalnız senin isminle

Ve kıpkırmızı kanımla

Bilmem kaç yara ardından kabuk bağladı 

Bilmem kaç parmak kırdım

Sensizken

Dişlerim dudaklarıma geçti her gece

Damlayan kanımla adını yazdım ranzaya

Ve gözlerimden firar etti bir çocuk

Seni arayıp bulmaya

Geri getirmeye gitti

Sonra bir çığlık gecenin ortasına düşerken

Vuruldu çocuk alnından, 

Yere serildi

Ama ölmedi inan

gördüm,

yay gibi gerildi...

Gözlerimden firar etti bir çocuk

Seni bulmak için,

sana yenildi...

bense bu buhran gecelerde

bir adın varken aklımda

sustum sana çığlık çığlık

ondandır heralde, bu gecelerde

nerde bir kurşun atılsa 

üstüne hep ben atlarım...', 'Bana uyu deme Ben uykuyu seninle unuttum Kan akıyor gözlerimden Bilemeden Son yaşımı da sana kuruttum... Ve bu buhran gecelerde sıkarken diş...', ARRAY['Türk Edebiyatı','Şiir','Galip Karabatak']::text[], 8.5, '{"poet":"Galip Karabatak","poet_slug":"galip-karabatak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/buhran-gecelerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Kan Çekerde Dönersen Geri', 'kan-cekerde-donersen-geri-nurten-altinok-jojsh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dilerim 

Ayaklarına dolanır yalanların

Dilerim 

Kâbusun olurum

Kan çeker de dönersen geri

Bir gün

Bil ki

Katilin olurum', 'Dilerim  Ayaklarına dolanır yalanların Dilerim  Kâbusun olurum Kan çeker de dönersen geri Bir gün Bil ki Katilin olurum...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kan-cekerde-donersen-geri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Bir Aşk', 'baska-bir-ask-ersen-alper-0j2nd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz birer kumaştık, biçtiler bizi,

Bizlerden elbise diktiler bize,

O gün bu gündür biz hep çıplağız; 

Yürüyen de içi boş bir elbise.

Kör çıplak Mevlana farketti bizi:

Çağırdı ''Yine gel, gene gel! '' diye,

Kendini kendine örtmek var iken 

İçi başka dışı başk''olmak niye? 

Gidemedik kör çıplak  bu çağrıya.

Dışımız başka  aşk, içimiz başka.

İçi dışa aşık etmek mi lazım,

Dışı içe aşık etmek mi yoksa?', 'Biz birer kumaştık, biçtiler bizi, Bizlerden elbise diktiler bize, O gün bu gündür biz hep çıplağız;  Yürüyen de içi boş bir elbise. Kör çıp...', ARRAY['Türk Edebiyatı','Şiir','Ersen Alper']::text[], 8.5, '{"poet":"Ersen Alper","poet_slug":"ersen-alper","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/baska-bir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bilir / Belki Bir Gün', 'kim-bilir-belki-bir-gun-hasan-basri-kale-2ol8b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir sabah 

ya / gün doğmazsa

...........uyandığımda

ya / sen yoksan yanımda

ya / tutamazsam ellerini

bir daha  ellerimde..

hüzünlü / mağrur yüzün

ya / yoksa artık aynalarımda..

sağnak bulutları

yoksa

artık mahzun gözlerinde..

kor alevlerinde yanmıyorsa

artık

sevdamın ıslak dalları..

kokun / nefesin / sıcaklığın / sesin

ya yoksa yanımda ey sevgili...! 

ya..............sen yoksan artık..! 

O gün....

bana çok yabancı 

ve benden çok uzak gözlerinden

son bir kez

............./ yaşamam için

öpmeme izin verir misin..? 

kim bilir / belki bir gün

belli mi olur

...............belki bir gün 

geri dönersin...!', 'bir sabah  ya / gün doğmazsa ...........uyandığımda ya / sen yoksan yanımda ya / tutamazsam ellerini bir daha  ellerimde.. hüzünlü / mağrur ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kim-bilir-belki-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Demir Attı Kızaklarım', 'demir-atti-kizaklarim-guclu-sonmez-xjhnt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Küçük bir kalp ile sana

Tutunmuştum sıkıca

Sen ise düşüncesizce

Attın beni deli rüzgarlara

Dualarında bıraktığın 

Tüm sözleri satın aldım

Geçmiş denen zamana

Birer birer kazıdım

Fırtınalar koparttım

Senden başka alem yokken

Şimdi demir attı kızaklarım

Mumlarını söndürürken

Artık korkmuyorum sevmekten 

Yalınayak koştuğum çöllerde

Büyüdüm ben

Sen uzaklardan bakarken



Yine de

Aklımdan geçersin arasıra

Gönlümün uzağında

Bulurum seni bazen

Kulağıma esen eski bir şarkıda

(İstanbul, Haziran 2004)', 'Küçük bir kalp ile sana Tutunmuştum sıkıca Sen ise düşüncesizce Attın beni deli rüzgarlara Dualarında bıraktığın  Tüm sözleri satın aldım Ge...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/demir-atti-kizaklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdim', 'seni-sevdim-muhsin-aktas-x9q4r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni sevdim be güzelim

Ne yapayım sevdim işte

Acılarını,kızgınlıklarını,nefretini

Sevdim be güzelim,ne yapayım sevdim işte

Çıkmazlar içine girdiğinde

Nefreti sürekli söylediğinde

Yaşamı birlikte göğüslediğimizde

Sevdim be güzelim,ne yapayım işte

Kızgınlığın serseri kurşun gibi saplandığında

Tam yüreğimi hançerlediğinde

Evde beklerken ağladığımda

Sevdim be güzelin,ne yapayım işte

Sen küçücük bir kuşsun inan  kanadı kırık

Bense azrailim hep ölüme alışık

İşimi yapamıyorum,inan senin yüzünden

Sevdim be güzelim,söyle ne yapayım ben? 

Ağlamak sızlamak inanki boşa

Ağaran saçları suçlamak boşa

Sen varsın ya hayatımda gitmese de hoşa

Sevdim be güzelim,söyle ne yapayım ben

Alevin kırmızısı gibi sevdim yürekten

Közleşmiş odun gibikor olup gitsem

Yanarak eriyip,tükenip bitsem 

Sevdim be güzelim söyle ne yapayım ben? 

Yaşamlar sunulmuş istemesekte

Çarpışmış hayatlar tam içimizde

Meyvesi olmuş bak evimizde

Sevdin be güzelim,ne yapayım ben?', 'Seni sevdim be güzelim Ne yapayım sevdim işte Acılarını,kızgınlıklarını,nefretini Sevdim be güzelim,ne yapayım sevdim işte Çıkmazlar içine g...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/seni-sevdim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maveradan da Öte', 'maveradan-da-ote-fatih-kagan-yucel-5egyt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen doğmasan güneş doğmazdı belki

Karanlık gündüzü nasıl tanırdı

Güzellik seninle var oldu sanki 

Görseydi Züleyha Yusuf sanırdı

Elinde tövbenin can veren zehri

Nidanda gizemi haykıran esrar

Çağlatır sükûtun lal olmuş nehri

Yokluğun mestheder varlığın kadar

Ne dillere sığdın ne kelimeye 

Konulmaz adını sevdaya sordum

Ufuğa eriştim ordasın diye

Maveradan bile ötede gördüm

28.05.2004 / Ankara', 'Sen doğmasan güneş doğmazdı belki Karanlık gündüzü nasıl tanırdı Güzellik seninle var oldu sanki  Görseydi Züleyha Yusuf sanırdı Elinde tövb...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kağan Yücel']::text[], 8.5, '{"poet":"Fatih Kağan Yücel","poet_slug":"fatih-kagan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/maveradan-da-ote-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soykırım Tarihi', 'soykirim-tarihi-seref-yildirim-yfcvz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Temerküz kamplarının iskeletleri,

Katarlar dolusu insan yığınları,

Muhteşem görünümlü,katil barakalara ve aksesuarlarına

/İndirildiler ite kaka, 

Sıraya sokuldular silah zoruyla,

Ve birden; 

Kara giysili gestapo şefi; 

Mağrur ve acımasız bağırdı:

-Soyunun pislikler! ! ! ! 

Korkuyla bakan gözler,

Çıldırmış beyinler,

Dermansız vücutlar,

Masumlar,saflar

El ele eşler,

Körpecik bebekler.....

Toplu halde girdiler temizlenmek umuduyla,

Gaz banyolu odalara,salonlara...

Oysa.....

Vanaların kolu çoktan çekilmişti

Gazlar püskürüyor boğma telaşında,

Fırınlar harlı odun yerine,cesetleri  yutmakta

Çığlıklar çocuk,erkek,kadın,

Sonu gelmez bitmez tükenmez çığlıklar.........

Yalvarmalar,dualar,isyanlar boşuna

Zelzeleler oluyor, sallanıyor yıkılıyor canlar

Yanardağlar kükrüyor lav alevlerinde

Deniz dalgalarında boğulmalar, feryatlar

Toplu imhalar......

Sabunlaşmalar.......

Biten vahşet; yeniden başkaları ile devam... binlerde,milyonlarda.........

Kömürleşen soydaş bedenler

Atılmakta kemik yığınları çukurlarına.........

Sürdü gitti........günlerce.......

Bir ırk,

Bir din

Birkaç nesil,

Kurutulmaya çalışılmıştı,

Vicdansız, kafatasçı yaratıklar.....

Soykırım Tarihi yazmıştı, saf ırk sevdasına

Öyle ki; 

Asırlarca belleklerden silinmemecesine.................

01.06.2004', 'Temerküz kamplarının iskeletleri, Katarlar dolusu insan yığınları, Muhteşem görünümlü,katil barakalara ve aksesuarlarına /İndirildiler ite k...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yıldırım']::text[], 8.5, '{"poet":"Şeref Yıldırım","poet_slug":"seref-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/soykirim-tarihi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-muhsin-aktas-l3pny', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu sabah yine senle uyandım

Başın göğsümde uyuyorsun

Saçlarını okşuyorum

Gülerek uyanıyorsun

Tatlı bir tebessümle

Bak hep yanındayım diyorsun

Ellerimi açıp dua etmek geliyor içimden

Çok mutluyum diye

Öpmek için eğiliyorum

Yoksun.....

Yatağım buz gibi oluyor birden

Korkularım bir hançer olup

Saplanıyor yüreğime

İçim cız ediyor

Ağlıyorum

Çünkü sen olmadan

Ben her gün hayalinle yaşıyorum', 'Bu sabah yine senle uyandım Başın göğsümde uyuyorsun Saçlarını okşuyorum Gülerek uyanıyorsun Tatlı bir tebessümle Bak hep yanındayım diyorsu...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-sevmek-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AKıYLa..', 'akiyla-neser-selman-biwci', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Toz mu yağıyor dışarıda

Yoksa renkler mi iflasta

Gözden kaybolsa da güvercinim

Gönüllerin simgesidir akıyla.....', 'Toz mu yağıyor dışarıda Yoksa renkler mi iflasta Gözden kaybolsa da güvercinim Gönüllerin simgesidir akıyla........', ARRAY['Türk Edebiyatı','Şiir','Neşer Selman']::text[], 8.5, '{"poet":"Neşer Selman","poet_slug":"neser-selman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/akiyla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle', 'soyle-muhsin-aktas-670sd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birlikte kürek çekemedik

Seyremedik yakamozları

Bakamadık ayrı gözlerden

Aynı yerlere

Oysa ikimizde o anı yaşadık

Tek bir kalpte

Aynı duygularla yaşamadık mı? 

Aynı sıcak sevgi damlaları

Akmadı mı yüreğimize? 

Koşmadık mırüzgara karşı? 

Islanmadık mı ikimiz

Sonbahar yağmurlarında elele

Gidebilecek miyiz seninle uzaklara? 

Unutabilecek miyiz yalanları? 

Yok edebilecek miyiz

Gözlerdeki mili,yürekteki pası

Söyle be canan söyle

Ne oldu bize

Niçin beceremedik

Sen söyle...........', 'Birlikte kürek çekemedik Seyremedik yakamozları Bakamadık ayrı gözlerden Aynı yerlere Oysa ikimizde o anı yaşadık Tek bir kalpte Aynı duygul...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/soyle-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Vardın', 'sen-vardin-muhsin-aktas-isdro', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana çok acılar çektirdiler

Kızgın demirle dağladılar tenimi

Dövdüler,sövdüler

Aşağıladılar

Bileklerimi kestiler

Damarlarımdan kan değil,sen aktın

Yüreğimi parçalamak istediler

Başaramadılar

Çünkü; 

İçinde bir tek sen vardın...', 'Bana çok acılar çektirdiler Kızgın demirle dağladılar tenimi Dövdüler,sövdüler Aşağıladılar Bileklerimi kestiler Damarlarımdan kan değil,sen...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-vardin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Tembel Melekler', 'tembel-melekler-guclu-sonmez-j1jjb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şarkının düşen sözleri - gerçek sessiz kalıyor

Boş ritimler kaplıyor havayı - şeytan benim müşterim

Evrenin koridorunda yolculuk sözü verdiler

Ama bana kalan sadece boş düşler ve kara kurdun uluması

Çocukluk düşlerim ne zamandır kayıplar

Özgür hisler ne zaman yıkıldılar

Kalplerin hırsızları toprakların efendileri oldular

Cennetin kapıları ne zamandır kirli ellere açıklar

Galaksinin öteki ucundan seyretti

Görmeyi umduğu sevdiğiydi

Özlem içindeki caneşlerin buluşma vakti geldi

Fakat parmaklıklar ardındaki baştan çıkartmalar umutları tüketti

Gecenin kadını beni bilinmeyende bıraktı

Alnımda geleceğin belirsizliği yazılı

Tembel melekler cennetin kalbinde uyuyor

Artık kimse paslanmış duaları dinlemiyor 

----------------

Lazy Angels

Falling words of a song - the truth remains silent

empty rhythms fill the air - devil’s my client

they promised a journey in the universe’s hall

but only got hollow dreams and a dark wolf’s howl

since when my childhood fantasies have vanished

since when the free feelings have been demolished

the thieves of the hearts became the lords of the lands

since when heaven’s gates are open to dirty hands

she watched from the next corner of the galaxy

it was her beloved she’s been wishing to see

time arrived for the longing soul mates’ rendezvous

but temptations behind the bars made hopefuls blue

lady of the night has left me in the unknown

in my forehead future’s uncertainty is shown

lazy angels are asleep in the heaven’s core 

no souls listen to dusted prayers anymore', 'Bir şarkının düşen sözleri - gerçek sessiz kalıyor Boş ritimler kaplıyor havayı - şeytan benim müşterim Evrenin koridorunda yolculuk sözü ve...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/tembel-melekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mükemmel İnsan', 'mukemmel-i-nsan-ferit-teksoy-nee1v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bence mükemmel insan,paylaştırmayı bilir,

Sevgi,öfke,tutku,arzu,hırsını.

Öyle bir denge ki bu,ölçüyü bozarsanız,

Kaçar kantarın topu,yarım eder insanı! ..

Sürekli içki içen bir insanı düşünün 

Yada aşkı para olan bir başkasını 

Çok konuşur diğeri,adını bilirsiniz 

Hiç konuşmayan da var,dinler başkalarını 

Bütün hayatı kumar,servetler batırmıştır 

Ya Leylâ''dır ya Mecnun,bu da kara sevdalı 

Öfkesini yenemez kavga,küfür hayatı

Karnı doyar gözü doymaz,bu da birşey çuvalı

Bu saydıklarımız hep kantarda topu kaçan

Hepsinden azar azar ölçülü olunsaydı

Yeryüzünde bir tane; alkolik,cimri,geveze,duvar,

Kumarbaz,mecnun,küfürbaz,obur..olurmuydu? ..', 'Bence mükemmel insan,paylaştırmayı bilir, Sevgi,öfke,tutku,arzu,hırsını. Öyle bir denge ki bu,ölçüyü bozarsanız, Kaçar kantarın topu,yarım e...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mukemmel-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprak Dökümü', 'yaprak-dokumu-caglar-akdeniz-oqlhi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaprak Dökümü

Anılar halen eskisi gibi taze...

Bir Aralık ayında aşık oldum,

ve Mart ayında soğuk vurdu, yaprak döktüm.

Her zaman ümit vardı benim için...

Güneşi bekledim, doğudan...

ama sen hep batıdaydın.

Solgun yanaklarımda, bir gül damgası.

Titrek ellerimde, bir sigara izmariti.

Buhulu gözlerimde, hep senin görüntün.

Daha akşamı gün etmeden, 

sabah oluyordu, Senin düşlerinle.

Diyorum ki:

..........

01.06.2004 22.12', 'Yaprak Dökümü Anılar halen eskisi gibi taze... Bir Aralık ayında aşık oldum, ve Mart ayında soğuk vurdu, yaprak döktüm. Her zaman ümit vardı...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Akdeniz']::text[], 8.5, '{"poet":"Çağlar Akdeniz","poet_slug":"caglar-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yaprak-dokumu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayacaksın', 'aglayacaksin-muhsin-aktas-1uqfj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birgün,

anlayacaksın yokluğumu

İş işten geçmiş olacak

Duracak,bakacaksın çevrene

Yokluğum yüreğinden vuracak

O an anlayacaksın

Pişmanlığın,

Bir tokat gibi inecek suratına

Ağlayacaksın..

Geçmişteki güzel günler

Tatlı bir tebessüm olacak

Akacak dudaklarından

Arayacak gözlerin hemen bedenimi

Kokumu duyacak,

Sarılacaksın

Yanında bulamadığında

Ağlayacaksın........', 'Birgün, anlayacaksın yokluğumu İş işten geçmiş olacak Duracak,bakacaksın çevrene Yokluğum yüreğinden vuracak O an anlayacaksın Pişmanlığın, ...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aglayacaksin-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm', 'kucugum-muhsin-aktas-ztk0g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen küçücük bir çocukmuşsun

Bilemedim

Keşke,keşke seni

Çocukça sevebilseydim

Bir gün ışık olup geleceğim

Saracağım her tarafını sımsıcak

Sonsuza kadar seni seyredeceğim

İşte o zaman

Seni çocukça seveceğim....', 'Sen küçücük bir çocukmuşsun Bilemedim Keşke,keşke seni Çocukça sevebilseydim Bir gün ışık olup geleceğim Saracağım her tarafını sımsıcak Son...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kucugum-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç kalma', 'gec-kalma-muhsin-aktas-sf641', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geç kalma bak

Yatağımı ısıttım

Odaya çiçekler saçtım

Sevdiğimi anlaman için 

Renk renk ışıklar taktım

Bilirim korkarsın karanlıktan

Gökgürültüsünden ve yanlızlıktan

Koş gel hemen

Işınla kendini

Çok bekletipte

Ne olur üzme beni...', 'Geç kalma bak Yatağımı ısıttım Odaya çiçekler saçtım Sevdiğimi anlaman için  Renk renk ışıklar taktım Bilirim korkarsın karanlıktan Gökgürül...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gec-kalma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma ki Sevgili...', 'sanma-ki-sevgili-vedat-sahin-ff6p0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sanma ki sevgili, kandım aşkına

Deniz gözlerimin, yasındasın sen

Bir yangın ki yandım, döndüm şaşkına

Her sevda sözümün, başındasın sen

Gülüşün kundaklar, kor söndürürüm

Başımı yolundan, zor döndürürüm

İçime dert olur, bor sindiririm

Yanımdayken bile, düşümdesin sen

Nazârın ruhumu, çarmıha gerer

Azârın kıtalar, ardına sürer

Hazarın bitirir, yerlere serer

Ekmeğim, suyum; aşımdasın sen

Sensizlik mi, söner ocağım, barkım

Harâbeye döner, düzenim çarkım

Vasiyetim olur,   yaktığım şarkım

Ölürsem kabrimin, taşındasın sen

30.05.2004 Esting', 'Sanma ki sevgili, kandım aşkına Deniz gözlerimin, yasındasın sen Bir yangın ki yandım, döndüm şaşkına Her sevda sözümün, başındasın sen Gülü...', ARRAY['Türk Edebiyatı','Şiir','Vedat Şahin']::text[], 8.5, '{"poet":"Vedat Şahin","poet_slug":"vedat-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sanma-ki-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykular II Sevgili Barış Aluk Dostumun Desteğiyle', 'haykular-ii-sevgili-baris-aluk-dostumun-destegiyle-ahmet-aksoy-igqrw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'XI

kanım akıyor

sızdıran damarlardan

yerin dolmuyor

XII

sevgi özlemin

tın sesinde büyürdü

sağır etmeye

XIII

her geçen saat

birbirine benzerdi

senin yanında

XIV

güne bakarken

açılır çiçeklerim

sensizlik gece

XVI

şimdi sensizim

hançeremde akrepler

esin rüzgarında

XVII

uutulmuş an

sahipsiz resimlerde

tek mesut zaman

XVIII

hamallar sardı

gemiler geldiğinde

karıncalandı

XIX

ironilerdir

hayatın ilk doğrusu

gariban usum

XX

sofra üzeri

doldurulmuş açlarla

açlar yeniyor', 'XI kanım akıyor sızdıran damarlardan yerin dolmuyor XII sevgi özlemin tın sesinde büyürdü sağır etmeye XIII her geçen saat birbirine benzerd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/haykular-ii-sevgili-baris-aluk-dostumun-destegiyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümüne Sevmek', 'olumune-sevmek-muhsin-aktas-kx3sq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölümüne sevmeye                                                                  

Var mısın desem

Biliyorum

Sen yokum dersin

Sen yok desende

Bir sevgi sözcüğü söylemesende

Yüreğin kararsada

Beni hiç sevmesende

Ben seni ölümüne sevdim

Sen bilmesen de....', 'Ölümüne sevmeye                                                                   Var mısın desem Biliyorum Sen yokum dersin Sen yok desende...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olumune-sevmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecikmiş Sevgiler', 'gecikmis-sevgiler-nihat-albayrak-1526f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mavi ışıklarıyla yivlenen gökyüzü,

Yaseminlerin kokusu,

Erguvan çiçeklerinin büyüsü,

Bahar çoşkusuyla alevlenir ya evren,

Deniz kabukları gibi alırsınya avucuna yaşamı,

O delice gülmeler, o sevişmeler,

Yeniden dirilmek gibi bir şey bu sevda,

Bir tutku,

Yaşamın gizil korkularıyla yoğunlaşmış,

                        ufka doğru yol alan yolculuk,

Bir bekleyiş,

Gecikmiş sevgileri bekler gibiyim! ...

Şimdi yaşamın ufka değen bir gemisindeyim,

Öğlen güneşinde olgunlaşan düşler,

                       Bir güz sağanağı ile ıslanıverdi,

Gül yaprakları çamur içinde,

Dostlar unutmuş,

                      üstelik uykusuz ve yorgunum,

Gecikmiş sevgileri bekler gibiyim! ...

O görkemli özlemler gelip çöktü gecenin içine,

Hüzün bulutlarının arkasına saklanmış yıldızlar,

O delice gülmeler, O sevinçler yok oldu,

Bir çit''in arkasına gizleniverdi tüm dünya,

Gecikmiş sevgilileri bekler gibiyim! ...

Kocaali/27.04.2004 

Nihat ALBAYRAK', 'Mavi ışıklarıyla yivlenen gökyüzü, Yaseminlerin kokusu, Erguvan çiçeklerinin büyüsü, Bahar çoşkusuyla alevlenir ya evren, Deniz kabukları gi...', ARRAY['Türk Edebiyatı','Şiir','Nihat Albayrak']::text[], 8.5, '{"poet":"Nihat Albayrak","poet_slug":"nihat-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gecikmis-sevgiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mana yok şekil yok', 'mana-yok-sekil-yok-yunus-ali-sinanoglu-ke899', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kısacık saçlarına bahar düşüyor

Uzuyorda uzuyor mevsim

Salkım söğüt oluyor

Bakışıyor gözlerin

Altında yeşilliğin

Sıcağı alıp götürüyor

Altın imrahor

Ve bilmek istiyor

Üşüyen gölgeler

Eskittiğin yenileri

Arıyor 

Gerçek renk sahibi

Dilemek istiyor

Gulden kokuyor martılar

Saçılıyor piyasa

Karışım dört hecele dört koca nergis

Kimin eli kimin cebinde

Rüzgar tekrar soruyor

Mevsim niye soğuk

ve kısa saçların uzun

Eskileri yenilet 

Martılar şimdi yorgun', 'Kısacık saçlarına bahar düşüyor Uzuyorda uzuyor mevsim Salkım söğüt oluyor Bakışıyor gözlerin Altında yeşilliğin Sıcağı alıp götürüyor Altın...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mana-yok-sekil-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay', 'ay-baykal-kaanalp-f8pvo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bazen düşünürüm

acaba ay

yukarıda tek başına

ne yapıyor? 

yalnızlık hissediyor mu? diye

sonra,

yıldızları görürüm

ayın yanıbaşında

mutlu olurum

birlikte görünce onları

ve ayın yalnız 

olmadığını bilmek

ferahlatır içimi

su serper yüreğime

sonra yine

takılır aklım

başka bir yere

güneş tek başına

ne yapar? diye.', 'bazen düşünürüm acaba ay yukarıda tek başına ne yapıyor?  yalnızlık hissediyor mu? diye sonra, yıldızları görürüm ayın yanıbaşında mutlu olu...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ay-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal', 'kal-bekir-mutlu-gokcesu-oyv2c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerimde kal

Kucağımda

Dudağımda

Kulağımda

Yüreğimde kal

Yeter ki ömrümce

Sen de kalan

Ben de kal...

Nefesimde kal

Aklımda

Hep böyle kal...', 'Gözlerimde kal Kucağımda Dudağımda Kulağımda Yüreğimde kal Yeter ki ömrümce Sen de kalan Ben de kal... Nefesimde kal Aklımda Hep böyle kal.....', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kal-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Bir Tebessüm İşte', 'tek-bir-tebessum-i-ste-bekir-mutlu-gokcesu-m0zze', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman, zaman

Düşünürüm

Onca yaşanandan

Sonra bugün

Nedir? 

Bize artakalan

Tek bir tebessüm işte

Gözünü kapamadan...

Razıyım yaşamaya

Seninle yeni baştan...', 'Zaman, zaman Düşünürüm Onca yaşanandan Sonra bugün Nedir?  Bize artakalan Tek bir tebessüm işte Gözünü kapamadan... Razıyım yaşamaya Seninle...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tek-bir-tebessum-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Devam Ediyor', 'hayat-devam-ediyor-baykal-kaanalp-7etpg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'burnu kanıyordu

üstübaşı kanrevan

koşarak içeri girdi

tam holü geçmişti ki

anne gördü...

ne oldu sana oğlum

kavgamı ettin

hayır anne

yalan söyleme

tamam yumruk yedim

kimden oğlum

kim vurdu sana

hayat anne

hayat vurdu bana

hayat neden vursun oğlum

hani çok iyi arkadaştınız

yediğiniz, içtiğiniz

ayrı gitmezdi

belli ki çok kötü

birşey yapmışsın kıza

hiç birşey yapmadım anne

bizi adaletle birlikte gördü

o kadar! ! !', 'burnu kanıyordu üstübaşı kanrevan koşarak içeri girdi tam holü geçmişti ki anne gördü... ne oldu sana oğlum kavgamı ettin hayır anne yalan s...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hayat-devam-ediyor-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki Sen Değilsin', 'sanki-sen-degilsin-baykal-kaanalp-2zzs0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hep sorguladın beni

beni ve yaşantımı

sanki seni hiç

yaşamamışım gibi

yeldeğirmenine savaş açan

sadece benmişim gibi

başıma kaktın

yürek yoksulluğumu

sanki öldünde

ardından ağlamadım

denizleri bırakıpda

karaları bağlamadım

hep sorguladın beni

beni ve yalnızlığımı

sanki sen kalabalıklar

içinde yalnız değilsin

sanki sen bir başına

meydan okumuyorsun

boş meydanlara

kalpsiz boşluklara', 'hep sorguladın beni beni ve yaşantımı sanki seni hiç yaşamamışım gibi yeldeğirmenine savaş açan sadece benmişim gibi başıma kaktın yürek yok...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sanki-sen-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**.Kuyu', 'kuyu-vahdet-nafiz-aksu-ij8q1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çalı vardı  pınarla aramızda 

Dudaklarımız kanıyor hala 

Kan kardeşi olduk 

Suyla 

Yollar uzun, güneş tepede 

Yorgunluk,hüzün  ve gurbet 

Yürüyoruz  yıllardır kardeş kardeş

Ey çatlayan dudak...kuruyan dil,

İşte yaklaştık kuyuya 

Yusuf''tan çok önce 

Dost olduk 

Kuyuyla 

Her yıldızda bir kadeh 

Ay kesmiş sofra başını 

Görseniz şaşarsınız vallahi 

Rüzgarın telaşını 

Bir şenlik  ki kuyuda sorma 

Su su su dedik

Sus sus sus dediler 

Ses sese verip  Clarenceyle 

Ölmeden biraz  önce 

Serhoş olduk 

Ağladık 

Korkuyla 

Uyuyuş o uyuyuş 

Ölüş o ölüş

Paramparça serhoş gömlekleri

Görmüyor Adem babamızın 

O gün bu gündür  gözleri', 'Bir çalı vardı  pınarla aramızda  Dudaklarımız kanıyor hala  Kan kardeşi olduk  Suyla  Yollar uzun, güneş tepede  Yorgunluk,hüzün  ve gurbet...', ARRAY['Türk Edebiyatı','Şiir','Vahdet Nafiz Aksu']::text[], 8.5, '{"poet":"Vahdet Nafiz Aksu","poet_slug":"vahdet-nafiz-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kuyu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elliye merdiven dayanan dogumgünü.', 'elliye-merdiven-dayanan-dogumgunu-ayten-ozlem-yesilcali-bcn4a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elliye merdiven dayadım,sanırım 2004 te

Can aradım,dost aradım benimle; 

Bu merdivenin ulaşılmazına erecek..

Can dedigim,cananıyla meşgul olamkta.

Dost dedigim,hayal peşinde koşmakta.

Sevğili  dedigim başka davar gütmekte.

Sabah açtıgımda nette sadece; 

Antoloji yetkilisinin dogum günün kutlu olsun

Mesajını gördügümde..

Anladımki,Benimle bu merdivenin ulaşılmazına,

Antoloji ermekte.

Bekledim geceye belki dostum,can dedigim; 

Ya hatırlarsa arar diye.

Nafile elliye merdiven dayamanın bedeli budur işte.

Olsun be dost,olsun be can,olsun be sevgili.

Biz ne kadarda elliye merdiven dayasak.

Yinede yirmilik kadar yürek var bizde.', 'Elliye merdiven dayadım,sanırım 2004 te Can aradım,dost aradım benimle;  Bu merdivenin ulaşılmazına erecek.. Can dedigim,cananıyla meşgul ol...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/elliye-merdiven-dayanan-dogumgunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykular III Sevgili Barış Aluk Dostum''un Desteğiyle', 'haykular-iii-sevgili-baris-aluk-dostum-un-destegiyle-ahmet-aksoy-h56sh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'XXI

yıllardır yoksun

oysa hep duruyorsun

olduğun yerde

XXII

buyum ben buyum

diyebilmeli insan

eğer değerse

XXIII

kamelya açtı

Çinden uzak bir yerde

itafen Çine

XXIV

öykündü güller

bülbüllerin şevkine

sessiz kırmızı

XXV

bırakmaz artık

tuttu bir kere kalbi 

şair damarım

XXVI

yabanıl ruhum

kaçar doğdum doğalı

saf mutlulukdan 

XXVII

aklım kalmıyor

ne zaman düşsen kalbe

azizim sana

XXVIII

zamansız ölüm

gelme ne olur bize

haber verip de

XXIX

ölüler sırdaş

ve dost birbirlerine

vefalı sadık

XXX

ağlama sakın

cehennemdeyim diye

anahtar sende', 'XXI yıllardır yoksun oysa hep duruyorsun olduğun yerde XXII buyum ben buyum diyebilmeli insan eğer değerse XXIII kamelya açtı Çinden uzak bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/haykular-iii-sevgili-baris-aluk-dostum-un-destegiyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim O?', 'kim-o-umit-kilislioglu-ozger-dihrz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kim o? 

Kim var kapıda? 

Yitik hayallerim mi gelmiş? 

Sanmam...

Evi bulamazlar ki onlar! 

Ey köşe bucak kaçtığım karamsar! 

Konuşsak mı ne! 

Elimdeki anahtarın açacağı kapı

Yapılmadı mı daha? 

Şu kapalı hava iki beden dar yüreğime

Göğüs kafesim çatladı, çatlayacak.

Radyodaki kadın 

Mahvediyor güzelim segâh şarkıyı,

Ocaktaki süt  taşıyor,

Umurumda bile değil...

Sen kapıdaki! 

Hâlâ orada mısın? 

1.Haziran.2004', 'Kim o?  Kim var kapıda?  Yitik hayallerim mi gelmiş?  Sanmam... Evi bulamazlar ki onlar!  Ey köşe bucak kaçtığım karamsar!  Konuşsak mı ne! ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kim-o-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarabi Eşkiyalar', 'sarabi-eskiyalar-zafer-zengin-etnika-i13p4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canım

Ateşler düştü yüzümüze

Gülemedik hiç

Yasak olan 

Sevgili yüzüne

Yasaktı

Adam gibi sevdalanmak

Sevgilinin gül dudağında 

Düşmek yarınlara...

yasaktı! ! ! ''

Kavrulan tendir bayrağımız

Yemindir 

Canımızı verdiğimiz

İnsanımız

Memleket aç

Biz kan içerdik

Mezbahalarda

İşkence odalarında

Yasaktı

Buharı çıkan ekmek

Tuğla duvarlarda yanan

Bana ve arkadaşlara

Canım

Biz öldük

Bir biz kaldık içerde

Zulmü sevmedik diye

Aç öldük

Tok gülemedik memlekete

/Düştü bir şarabi eşkiya daha/Karanfili elinde/İşte dönüyor memlekete

Aç idik

Yinede memleketi sevdik

Hiç gülmedik

Hep seni sevdik

Senin için öldük

Senin için ateşlere sürüldük

/Bilir zulmün zevkidir bizi yakmak/Ellerimizi çıra yapmak

İçin gitti gözüm

Çizdiğim resimler havada

Duvarlarım siyahtı

Yanan arkadaşlara baktığımda

Yolcu verdik

Teni akan yoldaşlara

Elimizden bir mektubu

Okusun memleketin okulu

İşte gidiyor 

Bir şarabi eşkiya daha

Selam sana

Selam memleketim

Selam halkıma

İyi bakın ateş içinde yananlara

Durmayın

Sayın

____Sayın

_________Sayın

Bir daha

_____Biri daha

_________Birileri daha

Aç koyup çocuk ettiler

Şarabi bu eşkiyalar

Hep umut dediler

Karanfil rengi kül bıraktık/Çok açtık/Ateşlere atıldık/Karanfil gibi yandık

Gül kokuyor memleket/İçim sızlar/Gidiyor bir bir /Şarabi eşkiyalar

28 Mayıs 2004 '' Kan konuşmaz ''

Şiirime katkısı için sayın dolunay enver''e tesekkür ederim..sağolsun...saygılarımla..', 'Canım Ateşler düştü yüzümüze Gülemedik hiç Yasak olan  Sevgili yüzüne Yasaktı Adam gibi sevdalanmak Sevgilinin gül dudağında  Düşmek yarınla...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/sarabi-eskiyalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredeydiniz', 'neredeydiniz-mehmet-engin-q7gz6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sonbaharın sarısında tanıdım sizi

İlkbaharın yeşilinde neredeydiniz

Yapraklar arasında bakışan gözler

Papatyalar açarken neredeydiniz

Gönlümde karayeller esiyor artık

Ilık rüzgarlar eserken neredeydiniz

Gün batışını hüzünle izliyor gözlerim

Tan yeri ağarırken siz neredeydiniz', 'Sonbaharın sarısında tanıdım sizi İlkbaharın yeşilinde neredeydiniz Yapraklar arasında bakışan gözler Papatyalar açarken neredeydiniz Gönlüm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Engin']::text[], 8.5, '{"poet":"Mehmet Engin","poet_slug":"mehmet-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neredeydiniz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılarımda Bile Kalmayacaksın', 'anilarimda-bile-kalmayacaksin-mehmet-engin-fs1xe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgimin değerini bilemedin sen

Ahımın yükünü taşıyacaksın

Gönül defterimden sildim ismini

Anılarımda bile kalmayacaksın

Dudağım yasak sana dokunamazsın

Uzatma kollarını sarılamazsın

Yaralı bir kalbi onaramazsın

Anılarımda bile kalmayacaksın

Sefanı sürmeden cefanı çektim

Biraz sevgin olsaydı gitmeyecektim

Ah ettikçe yürekten inleyeceksin

Anılarım da bile kalmayacaksın', 'Sevgimin değerini bilemedin sen Ahımın yükünü taşıyacaksın Gönül defterimden sildim ismini Anılarımda bile kalmayacaksın Dudağım yasak sana ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Engin']::text[], 8.5, '{"poet":"Mehmet Engin","poet_slug":"mehmet-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anilarimda-bile-kalmayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Kanımla Yazdım', 'bu-gece-kanimla-yazdim-tulay-eker-qjvli', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sana bu gece 

gecenin deminde 

demimin mateminde 

matemlerimin çilesiyle 

sevgimin özü 

özümün sözü 

sözümün közü 

közümün külü ile 

yazmak istiyorum 

yazamıyorum... 

akan yaşım 

yaşım kanım 

kanım canım 

canım yazamadıklarım. 

_____özlem 

___________acı 

_______________sevgi 

hepsi sen 

____________BEN.', 'sana bu gece  gecenin deminde  demimin mateminde  matemlerimin çilesiyle  sevgimin özü  özümün sözü  sözümün közü  közümün külü ile  yazmak ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bu-gece-kanimla-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Zaman Durdu...', 'zaman-durdu-erdal-asik-01bcv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne oldu bu saatlere

Küsmüş yelkovan akrep''e

Darılmış dakikalara saniyeler 

Aldırmaz ve de umursamaz

Günler kuçaklaşmıyor 

Haftalar beklemede

Mevsimler ayları özler oldu

İnan sevgilim gittiğin günden beri

Sanki zaman durdu

Dünya dönmez oldu', 'Ne oldu bu saatlere Küsmüş yelkovan akrep''e Darılmış dakikalara saniyeler  Aldırmaz ve de umursamaz Günler kuçaklaşmıyor  Haftalar beklemede...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zaman-durdu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antika Müzayedesi.', 'antika-muzayedesi-musfik-saltik-ycouy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir salonda toplanmış insanlar 

Çok şık giyinip kuşanmışlar

Kürsüdeki adamın idaresinde

Değerli eserlere sahip olmak için 

Birbirleriyle kıyasıya yarışıyorlar

Peş peşe satılıyor değerli tablolar

Porselen tabaklar, lambalar, vazolar

Satın alabilenler gururla gülümsüyorlar

Bana hep itici gelmiştir şu antikalar

Değerli oldukları için çok iyi korunurlar

Gözü gibi bakar onlara sahip olanlar

Bir gün gözünü yumunca sahipleri

El değiştirip başka birinin göz bebeği olurlar

Kim bilir kaçıncı sahiplerini dünyadan yolladılar

Dört yüz yıllık bir lamba halâ sapa sağlam duruyor

Onu yapan ustanın kim olduğunu kimse bilmiyor

En çok yaşayan insan yüz yaşına kadar yaşıyor

Bir porselen vazo yüzyıllara meydan okuyor

Sevemedim, sevemiyorum bir türlü antikaları

Hepsi buram buram ölüm kokuyor.

                                                          Haziran 2004', 'Bir salonda toplanmış insanlar  Çok şık giyinip kuşanmışlar Kürsüdeki adamın idaresinde Değerli eserlere sahip olmak için  Birbirleriyle kıy...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/antika-muzayedesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rengiydi Sebebi', 'rengiydi-sebebi-derin-oger-y5feh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerine bakmayı severdim 

O karanlık bakışlar yüreğimi titretirdi

Kirpiğinin siyahı çekerdi beni kendine

Sevincimin en canlı rengiymişcesine

Çağlayanın dereye merhabası gibiydi

Çılgın bir suydu çarptıkça esrarı bakışlarının

Ne yelkenim olurdu ne küreğim rasgele 

Sen toplardım kirpik uçlarımdan

Gözlerin birikirdi gözlerimin siyahında

Dudaklarımı susturup yüreğime inişinle

Her şey tohum olup aşka yeşerirdi

Siyahtı duygularımın tadı ateşimin rengi 

Siyah bir çerçeveden gökkuşağını seyreder gibi

Gözlerindi en çok siyahı sevmemin sebebi.....', 'Gözlerine bakmayı severdim  O karanlık bakışlar yüreğimi titretirdi Kirpiğinin siyahı çekerdi beni kendine Sevincimin en canlı rengiymişcesi...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/rengiydi-sebebi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızlarım', 'kizlarim-ayten-ozlem-yesilcali-us393', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben güneydoğudan batının Paris ine geldigimde.

Hayatı tozpenbe gördüm.

Ama baktımki gördüğüm gibi degil. 

Burada hayat acımazsız,gönüller kırgın.

Sevgi saygı olayı anamdan babamdan gördügüm.

Terbiye kurallarını aşmış.

Daha siz dünyaya gelmediniz.

İstemeden de olsa bu pariste dünyaya geldiniz.

Benim size veremediklerimi,sakın ola sakınha.

Başkasından öğrenmeye yeltenmeyin.

Kurallar önemli degil,bebeklerim.

Eline diline beline sahip olun derim.

Kula kulluk etmeyin.

Kendi ayaklarınızın üstünde durup dünyaya; 

Karşınıza çıkacak tüm engellere meydan okuyun.

Ölümden ötesi yok,ölecekseniz de şerefinizle ölün.

Zoru başarın erkek kadın ayrımı yapmadan.

Duygusallıgınızı yitirmeden,insanlık sevgisi içinizde bitmeden.

Ananızın verdigi projede yürüyerekten.

Ben gördüm Paris sokaklarında inleyen aglayan gençleri.

İşte bebeklerim bin nasihattan bir nusubet daha hayırlı derler.

Desinler ben örf adetimi sizlere verebildiysem.

Aslan yatağında çakal uyumaz.

Çakallara yem etmedigim sürece.

Evet kızlarım siz büyüdünüz,hayatı tanıyın ben size öğretemedigimce.

Saramadım kucagıma alamadım gördügüm törece.

Pişmanda degilim.

Ama keşke herkes olabilse,hayatın gerçeklerini görebilse... 

Kızlarım hayata veda etsemde,kendinizce ananızın yaptıklarıyla.

Hayatı tanımaya,kimseye boyun egmemeye alınteriyle kazanmaya; 

Hak yememeye yediğin tek lokmada bir kuşun bile hakkı oldugunu; 

Unutmadan,yaşamaya komşunda yoksa siz vermeye.

Alışın zeval görmezsiniz be kızlarım.

Siz aslan yürekli bagrı yanık,hayatta herşeye tanık 

Ananın kızlarısınız.', 'Ben güneydoğudan batının Paris ine geldigimde. Hayatı tozpenbe gördüm. Ama baktımki gördüğüm gibi degil.  Burada hayat acımazsız,gönüller kı...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kizlarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairler cahilde olsa şairdir.', 'sairler-cahilde-olsa-sairdir-ayten-ozlem-yesilcali-fzts6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakma ustam yazılanlara,yaşamamışki; 

Ne sevgi acısı,nede insan hasreti.

Nasibini almamış velet demeye bile utanıyorum.

Yazsın ya kendisi içindeki duyguları isyanları.

Benim senin gibi.

Yürek gerek be ustam,anlını karışlarım.

Yüreği açık  yazan insanı senin benim gibi.

Benim tek hedefim ilk şiirimde bana verdigin; 

Cesaret destek beni nerelere getirdi,bilmekteyim.

İmgenin i sini bilemeden içimden geçenleri kaleme,

Dökmemden  o cesareti sen verdin bana.

Şair budur işte dercesine.

Sen yinede bizim kalbimizde bir usta şair Hasan Basri Kalesin.

Bunu herkes böyle bilsin.

Bir delinin kuyuya attığı ufacık bir çamurla senin yüregin; 

Kalbin iflas etmezse gerek.

Kalemin susmaz biliyorum.

Kalemi tutmaya tutupta yazmaya  yine yürek gerek,ustam.', 'Bakma ustam yazılanlara,yaşamamışki;  Ne sevgi acısı,nede insan hasreti. Nasibini almamış velet demeye bile utanıyorum. Yazsın ya kendisi iç...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sairler-cahilde-olsa-sairdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ugurlayış', 'ugurlayis-cemal-yaman-awtlz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerinde bir demet gül

Beni uğurladığın gün

Biliyor muydun

Bu kadar ayrı kalacağımızı? 

Hasret çukurunda sökülmez

Kökler salacağımızı

Gözlerde kuruyup dökülmez

Yaşlarla dolacağımızı

Biliyor muydun? 

Beni uğurladığın gün

Ellerinde bir demet gül.', 'Ellerinde bir demet gül Beni uğurladığın gün Biliyor muydun Bu kadar ayrı kalacağımızı?  Hasret çukurunda sökülmez Kökler salacağımızı Gözle...', ARRAY['Türk Edebiyatı','Şiir','Cemal Yaman']::text[], 8.5, '{"poet":"Cemal Yaman","poet_slug":"cemal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ugurlayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulaşır', 'bulasir-halil-i-brahim-ozdemir-61qb2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Açılan avuçlara rahmet çabuk ulaşır,

Kurda kuşa merhamet, gökyüzü yağmur taşır.

Kul olmanın gururu, aşkı ve heyecanı,

İlahi sıfatlar ki “Yaratan”dan bulaşır…', 'Açılan avuçlara rahmet çabuk ulaşır, Kurda kuşa merhamet, gökyüzü yağmur taşır. Kul olmanın gururu, aşkı ve heyecanı, İlahi sıfatlar ki “Yar...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bulasir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim Ben', 'ogretmenim-ben-cemal-yaman-nj84r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öğretmenim ben öğretirim eğitirim

Aydınlığa yol verir karanlığı dağıtırım

Yarınları aydınlatmak benim işim gücüm

Aydınlatmak yolunda asla tükenmez gücüm

Bazen en ücra köşesinde yurdun

Bazen en gelişmişinde okulun

Ders verir, güldürür, bildirir, eğitirim

Aydınlığa yol verir karanlığı dağıtırm

Umutlar damlar aydınlık sözlerimden

Ürker, korkar karanlık, gözlerimden

Nesiller koşar medeniyete izlerimden

Ayşelerimden, Ahmetlerimden, Filizlerimden

Aydınlık bir ülke fışkırır dehlizlerimden

Duman olur tüterim fabrikaların bacalarından

Füze olur uçarım yıldızların aralarından

Çiçek olur açarım gençlerin kafalarından

Güneş olur doğarım sınıfların tahtalarından

Öğretmenim ben öğretirim eğitirim

Aydınlığa yol verir, karanlığı dağıtırım.', 'Öğretmenim ben öğretirim eğitirim Aydınlığa yol verir karanlığı dağıtırım Yarınları aydınlatmak benim işim gücüm Aydınlatmak yolunda asla tü...', ARRAY['Türk Edebiyatı','Şiir','Cemal Yaman']::text[], 8.5, '{"poet":"Cemal Yaman","poet_slug":"cemal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ogretmenim-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mart', 'mart-cemal-yaman-llrnp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep haziranı anlatırlar 

Ağustosu anlatırlar hep

Ben martı yaşıyorum 

Martı renkli karlarla kapıkomşu 

Saçaklardan metrelerce sarkıyor buzlar

Soğuk sularda çatlıyor karpuzlar

Ben martı yaşıyorum

Martı renkli karlarla sarmaş dolaş

Kilometrelerce uzakta sevdiklerimden 

Ne yar, ne ana, ne baba, ne kardeş...

Martı anlatmak istiyorum

Martılar bırakmıyor yakamı.', 'Hep haziranı anlatırlar  Ağustosu anlatırlar hep Ben martı yaşıyorum  Martı renkli karlarla kapıkomşu  Saçaklardan metrelerce sarkıyor buzla...', ARRAY['Türk Edebiyatı','Şiir','Cemal Yaman']::text[], 8.5, '{"poet":"Cemal Yaman","poet_slug":"cemal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mart-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesim Motoru / anı', 'kesim-motoru-ani-k-muran-esen-kjwua', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evimizin hemen karşısında bir bahçe var.Bahçede  birkaç tane heybetli ceviz ağacı, bir tane de asma. Ceviz ağaçları, görüş alanımızı kapatıyor ama, benim şikâyetim yok.Çünkü yavaş yavaş büyüdüler, alıştıra alıştıra kapattılar önümüzü.Enflasyon gibi.

İşte bu bahçenin sahibi,  yaşlı ceviz ağaçlarından birini kestirdi.Zavallı ceviz ağacı birkaç gün,  bitkisel hayattaki  hasta gibi öylece yattı yerde.Eskiden balkondan etrafımı seyrederken görüş alanımı kapatan bu ağacın yokluğuna bir türlü alışamadım.Gözümün önümde alabildiğince  açılan manzarayı her görüşümde, o ceviz ağacını aradım, giysilerimden soyunmuş hissettim kendimi.Ya da çok soğuk havada, gece yatakta yatarken;  yorganımın üstüne örttüğüm  ve beni ısıtan battaniyemin üzerimden alındığı hissine kapıldım.Adeta üşüdüm.

Kesilen ceviz ağacını  kesim motoruyla birkaç parçaya ayırdılar. Her parçası bir yerde, öylece kalakaldı zavallı ceviz.Aradan ne kadar zaman geçti bilmiyorum; bir gün bahçenin sahibi   kesilen dalları budadı.Ağacın kalın gövdesinin parçalarını ayrı,  ince dallarını ayrı üstüste istif etti, katar yaptı.Küçük dalları baltayla parçaladı, bahçedeki samanlığa taşıdı.Geride kalan    ana gövdenin  parçalarının yeniden kesilmesi gerekiyor, çünkü boyları oldukça uzun.

İşte o günden beri  birkaç gün arayla, işçi tulumu giymiş bir genç geliyor bahçeye.Elinde kesim motoru, başlıyor  ceviz dallarını kesmeye.Motor bir gürültü çıkarıyor ki, sormayın gitsin.Bahçenin evimize uzaklığı  sekiz – on metre.Yani burnumuzun dibi.İki üç dal kesip, çekip gidiyor.Motorun sesi kesilince; kulaklarımızı tırmalayan motor sesinden kurtulduğumuz için seviniyoruz ailecek..Düşünmüyoruz ki, bugün olmazsa, yarın olacak bu gürültü.Biz  günü kurtarma peşindeyiz.Türk hükümetlerinin ekonomi politikası gibi.

Birkaç gün sonra, yine geliyor aynı kişi.Yine birkaç dal kesiyor, çekip gidiyor.Allah Allah! Bu gencin iş yapmaya niyeti yok.Madem başladın, uçla şu işi. “Ettiğin hayır, ürküttüğün kurbağaya değsin,” demişler. Bugün  iki dal kes, git; üç gün sonra iki  dal daha.Biter mi böyle, karınca buğday taşır gibi! 

Bir gün  henüz iki yaşındaki  torunum bize geldi.Birlikte güldük, oynadık falan.Sonra  öğle uykusuna yattı.Çocuk daha uykuya daldı dalmadı,  bir gürültü duyduk.Sanki beynimizi matkapla deliyorlar.Pencereden bir baktım, motorcu,  cevizin dallarını kesiyor yine.Motorun sesi, dar bir vadide kurulmuş kasabada yankılanıyor adeta.Oğlan  uyandı gürültüden, başladı bağırmaya...Birkaç dakika sonra motor  sustu, torun da sustu. Oh! Çok şükür! ..Baktım  bizim motorcu iki- üç dal kesmiş gidiyor.Sanki özellikle bizim torunu uyandırmaya gelmiş gibi. 

Birkaç gün görünmedi motorcu...Geçen sabah torun geldi yine.Yedik, içtik, güldük, söyledik.Çocuğu öğlen uykusuna yatırdık, daha gözü kararmadan  motor sesiyle irkildik.Allah Allah! Bu genci,   bizim torunu uykudan uyandırmaya mı memur etmişler? Yani tesadüf bu kadar olur.Torun uykuya yatıyor; o genç, cevizin dallarını kesmeye başlıyor.Çocuğu uyandırıp, birkaç dakika sonra  çekip gidiyor.Koşarak evden çıktım, doğru bahçeye.Hani motorcuya; “Kardeşim, çocuk uyuyor, sonra kesseniz olmaz mı? ” falan diyeceğim.Ben merdivenleri inip bahçeye varıncaya kadar motorcu çoktan yolu tutmuş.Yakalayamadım ki......Bir yakalasam biliyorum yapacağımı. “Pehlivana tut demişler, elimden gelse canını alacağım  demiş,” derler ya, o hesap.

Aradan ne kadar zaman geçti bilmiyorum.Bizim torun gene bize geldi.Zaten üç günün biri geliyor.Getirtiyoruz  daha doğrusu.Özlüyoruz keratayı.Motorcuyu çoktan unuttuk.Çocuğu öğle uykusuna yatırdık.Seslerimiz kıstık, öyle konuşuyoruz, uyanmasın diye..Terliklerimizi bile çıkardık ki, gürültü olmasın.Hazır uyumuşken, biz de dinleneceğiz.Uyanıkken, peşinde koşmaktan yorgun düştük annesi de ben de.

Kahvemi pişirdim, tam keyifle yudumlayacağım, motor sesiyle  irkildik.Be adam, nasıl da bilip geliyorsun, bizim torunun uyku saatinde.Torun  uyandı, başladı ağlamaya.Motor sesinden de korkuyor zavallı.Tepem attı.Bir fırladım yerimden, merdivenleri ikişer ikişer iniyorum motorcuyu yakalamak için.Gene üç- beş dal keser, gider diye.

Yanılmamışım.Ben bahçeye vardığımda, kesimi bırakmış, motoru susturmuş, gitmeye hazırlanıyor.Bizim torun uyandı ya, artık gidebilir.Son anda yakaladım.Bahçeden çıkmak üzereymiş..Bir hışımla; “Kardeşim nedir senin bu yaptığın! İkide bir gelip iki odun kesip, bizim torunu uyandırıp gidiyorsun.Şu koca üç katar odun, böyle  üç günde bir, üçer- beşer kesmekle biter mi? Bir gün kes, bitir şunu.Sen de biz de kurtulalım bu işkenceden,” dedim

Genç gülümseyerek, bana ne dedi biliyor musunuz? ......”Ben oduncu değilim.Kesim motoru tamircisiyim.Tamir ettiğim motorları, - nasıl olsa kesilecek - bu odunlar üstünde deniyorum.”......Atalarımız; ” acemi nalbant işi, gâvur eşeğinde öğrenir,” demişler.....Bizim tamirci de, tamir ettiği motorları denemek için bula bula bizim komşunun odunlarını buldu...', 'Evimizin hemen karşısında bir bahçe var.Bahçede  birkaç tane heybetli ceviz ağacı, bir tane de asma. Ceviz ağaçları, görüş alanımızı kapatıy...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kesim-motoru-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel diyemem', 'guzel-diyemem-metin-kose-57l5u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin

Denizin izi

Saçların 

Gülün filizi

Bakışın

Yürütür çaresizi

Ama güzel diyemem

Benim değilsin

Ankara		

(2 Haziran 2004)', 'Gözlerin Denizin izi Saçların  Gülün filizi Bakışın Yürütür çaresizi Ama güzel diyemem Benim değilsin Ankara		 (2 Haziran 2004)...', ARRAY['Türk Edebiyatı','Şiir','Metin Köse']::text[], 8.5, '{"poet":"Metin Köse","poet_slug":"metin-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/guzel-diyemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Küsmüş Kadın', 'aska-kusmus-kadin-hakki-hakan-kaya-l280j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ey yüreğimin zindanındaki 

eli silahlı gardiyan 

ey gözlerimin ışığına 

kepenk vuran kadın 

... 

fırtınaya tutulmuşken 

kalbimin sığ sahilleri 

en ücra kıyılarına 

dalga kıranlar kurdun 

... 

sevdaya ellerim açılmışken 

avuçlarıma güneş topladığım 

çivileyip çaktın umutlarımı 

kanlı vurgunum oldun 

... 

ey karanlık gözleri 

aşka küsmüş kadın 

bir gün 

gözlerindeki yağmurlar 

yüreğinin kuraklığına 

hayat olup akarlar...', 'ey yüreğimin zindanındaki  eli silahlı gardiyan  ey gözlerimin ışığına  kepenk vuran kadın  ...  fırtınaya tutulmuşken  kalbimin sığ sahille...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aska-kusmus-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HerYaş Güzel', 'heryas-guzel-buket-sema-caner-0raon', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ünlü şair 35 yaş yolun yarısıdemiş

Aynalara bakıp bkıp dertlenmiş

Oysa bilememiş koca şair kıymetini

35 yaşyaşların en güzeli

Aldırma, aynalarda insanlar kadar yalancı

Kırışmış yüzün,aklanmış saçların

Kalbinde ağrı, sırtında biryığın yükün

Kaldıramadığın

Olsada ne çıkar

Her yaş istediğin gibi yaşarsan

Güzel ve anlamlı.', 'Ünlü şair 35 yaş yolun yarısıdemiş Aynalara bakıp bkıp dertlenmiş Oysa bilememiş koca şair kıymetini 35 yaşyaşların en güzeli Aldırma, aynal...', ARRAY['Türk Edebiyatı','Şiir','Buket Sema Caner']::text[], 8.5, '{"poet":"Buket Sema Caner","poet_slug":"buket-sema-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/heryas-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Bu Nankörlük', 'neden-bu-nankorluk-i-smet-barlioglu-b8tcw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Verilir. Avuç açi iste yürekten,

Neden bu nankörlük boşuboşuna? 

Seç artık elifi koca mertekten,

Neden bu nankörlük boşuboşuna? 

İstemeyi bilip istesen habbe,

İnan ki verilit koskoca kubbe,

Asla esirgemez en dolu heybe,

Neden bu nankörlük boşuboşuna? 

İstemeyi öğren, dileği öğren,

Dileğe gereken emeği öğren,

Almadan severek vermeyi öğren,

Neden bu nankörlük boşuboşuna? 

Dağları istesen; esirgeyen kim? 

Deryayı istesen; kim, vermeyen kim? 

Hazine istesen; göndermeyen kim? 

Neden bu nankörlük boşuboşuna? 

Hayat istemeden verilmedi mi? 

Sen gelmeden döşek serilmedi mi? 

Herbir ihtiyacın görülmedi mi? 

Neden bu nankörlük boşuboşuna? 

Hazırlık tamamdı senden çok önce,

Güneş henüz yoktu, sadece gece,

Her hesap yapıldı inceden ince,

Neden bu nankörlük boşuboşuna? 

Hava sağlandı ki nefes alasın,

Oran kuruldu ki patlamayasın,

Çekim koyuldu ki fırlamayasın,

Neden bu nankörlük boşuboşuna? 

Arandı; ne yersin, ne hazmedersin,

Ne kadar uyursun, ne defedersin,

Sen hala kalkmış da caf caf edersin,

Neden bu nankörlük boşuboşuna? 

Güneşin mi eksik, ayın mı eksik? 

Samanyollarından payın mı eksik? 

Tarçının, kahven mi, çayın mı eksik? 

Neden bu nankörlük boşuboşuna? 

Denizler verildi, toprak verildi,

Ağaçlar, çiçekler, yaprak verildi,

Kel başa şimşirden tarak verildi,

Neden bu nankörlük boşuboşuna? 

Sesler kimin için, renk kimin için? 

Dallarda meyveden denk kimin için? 

Başlayan, bitmeyen cenk kimin için? 

Neden bu nankörlük boşuboşuna? 

Kokular kimlere, lezzet kimlere? 

Neden büyük denge verildi yere? 

Boışuna mı kondu heykel mermere? 

Neden bu nankörlük boşuboşuna? 

Göz neden verildi, kulak nedendir? 

Ağızlar, dudaklar, yanak nedendir? 

Ateşler, ocaklar, çanak nedendir? 

Neden bu nankörlük boşuboşuna? 

Sular birikti de dağda mı kaldı? 

Üzüm yaratılıp bağda mı kaldı? 

Balık tutuldu da ağda mı kaldı? 

Neden bu nankörlük boşuboşuna? 

Yüksekte mi kaldı sular çukurdan? 

Yağmur mu yağmadı yoksa yukardan? 

Nasip mi almadın bembeyaz kardan? 

Neden bu nankörlük boşuboşuna? 

Sana, çık dağları sula mı dendi? 

Sırtına çok ağır yük mü yüklendi? 

Ne zaman esti de tipi dinmedi? 

Neden bu nankörlük boşuboşuna? 

Pişirilmiş armut düştü ağzına,

Kandırılmış balık girdi ağına,

Gök gübre indirdi aç toprağına,

Neden bu nankörlük boşuboşuna? 

Kıl kadar eksiğin bırakılmadı,

Bu dünya fır döndü, hiç takılmadı,

Verilen başına hiç kakılmadı,

Neden bu nankörlük boşuboşuna? 

Barlıoğlu der ki; dileme, ayıp,

Sana herşey verdi adamdan sayıp,

Sen sadece şükret hergün ağlayıp.

Neden bu nankörlük boşuboşuna? 

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 132-136/412)', 'Verilir. Avuç açi iste yürekten, Neden bu nankörlük boşuboşuna?  Seç artık elifi koca mertekten, Neden bu nankörlük boşuboşuna?  İstemeyi bi...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/neden-bu-nankorluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarımız', 'dostlarimiz-buket-sema-caner-5030w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz dört arkadaşız bir kişi gibi

Öylesine kutsal, sevecen dostluğumuz

Herkesin kıskançlıkla  gıpta ettiği

Dört arkadaşız bir beyin gibi.

Kimse bozamadıysa bu güne değin

Hiçbir şey kopartamadıysa bu zinciri

Bir gün bilinmez nerde nasıl

Elbette kopacak zincirin halkaları

İlk  yolculuk kimindir  bilinmez

Kalan üç kişiağlar içinden.

Eski günler yad edilir

Şerefe kalkar yinekadehler

Mevsim sonbahardır artık

Vakit yaprak dökümüdür.

Sonra birimiz, daha sonra diğeri

Ve son kalanda gidiverir

Kim kaldırır anılarımıza kadehleri

Çocuklarımıza vasiyetimizdir.', 'Biz dört arkadaşız bir kişi gibi Öylesine kutsal, sevecen dostluğumuz Herkesin kıskançlıkla  gıpta ettiği Dört arkadaşız bir beyin gibi. Kim...', ARRAY['Türk Edebiyatı','Şiir','Buket Sema Caner']::text[], 8.5, '{"poet":"Buket Sema Caner","poet_slug":"buket-sema-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dostlarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yutmayın', 'yutmayin-i-smet-barlioglu-9fn63', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan bu dünyada yalnız konuktur,

Ağaçları armuduyla yutmayın.

Köz yiyenin ciğerleri deliktir,

Develeri hamuduyla yutmayın.

Dünyamızda herşey bağlı hesaba,

Fazla yiyen geri verir mutlaka,

Dutu yerse bülbül ötmez bir daha,

Küfeleri tüm dutuyla yutmayın.

Çıplak doğar insan gider çıplakca,

Bir kefendir, o da biraz ıslakca,

Onun için tamahkarlık aptalca,

Semaları bulutuyla yutmayın.

Saray kalır yaptırılsa mermerden,

Ölüm geçer kapı olsa demirden,

Kefenler hiç yapılmıyor samurdan,

Toprakları hududuyla yutmayın.

Bu dünyadan gidecek çey bilgidir,

Bu sergiden kazanılan görgüdür,

Tüm ruhların öz maddesi sevgidir,

Dünyaları aç kurduyla yutmayın.

Sevap götür, herbir duyan beğene,

Sarıp şöyle birkaö metre kefene

Kim götürmüş yanısıra define? 

Gıdaları pis tortuyla yutmayın.

Barlıoğlu diyor; mezar yaklaşır,

Asıl şimdi koyun, kuzu koklaşır,

Gemi gelir her limana yaklaşır,

Hak hukuku kof tartıyla yutmayın.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 137-138/412)', 'İnsan bu dünyada yalnız konuktur, Ağaçları armuduyla yutmayın. Köz yiyenin ciğerleri deliktir, Develeri hamuduyla yutmayın. Dünyamızda herşe...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yutmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Grup Çağrısı', 'grup-cagrisi-sule-aydemir-xwe8s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'http://www.antoloji.com/grup/cagri-duyuru-ilan-aktivite yazarak bu gruba daha hızlı ulaşabilirsiniz 

 

Grup Tanımı 

Bu grubun içinde olduğu kategoriler: Kültür Sanat, Şiir, Yaşam 

---

Çağrı - Duyuru - İlan – Aktivite 

Her türlü etkinliği takip edebilmek maksadı ile açılmış bir gruptur…. Herkesin aktif olması ümidiyle… 

Dilerim dününüz hep bu gününüzü kıskanır.. 

Sevgiyle, 

Şule Aydemir', 'http://www.antoloji.com/grup/cagri-duyuru-ilan-aktivite yazarak bu gruba daha hızlı ulaşabilirsiniz    Grup Tanımı  Bu grubun içinde olduğu ...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/grup-cagrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Konuş', 'sessiz-konus-i-smet-barlioglu-79tp0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben dervişim, sessiz konuş; 

Duygularım karış karış,

İstiyorsan eğer yarış

Yüzyıl önce çık yollara.

Gah yanarız, gah tüteriz,

Tohumlardan tez biteriz,

Bülbüllerden has öteriz,

İnanmazsan sor dallara.

Bugün eriz, dün kuş idik,

Bugün tamız, dün boş idik,

Bugün canız, dün taş idik,

Gözün varsa bak hallara.

Örnek aldık eğrilerden,

Tez ayrıldık gayrılardan,

Çok üstünüz arılardan,

Dilin varsa değ ballara.

Biz taşırız bu zamanı,

Kucaklarız her ummanı,

Yüklenmişiz bu cihanı,

İnanmazsan bak kollara.

Gittik geldik kaç biçimde,

Anlamazsan kalk, ''Niçin? '' de,

Balık olduk su içinde,

Biraz değer ver pullara.

Yararlandık kutsal aftan,

Sıyrılmışız her boş laftan,

Biz sıyırdık samur kaftan,

Bir kez nazar et çullara.

Barlıoğlu mağrur derviş,

Zira, yalnız görünmemiş,

Lütfedilmiş, sürünmemiş,

İnanmazsan sor kullara.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 139-140/412)', 'Ben dervişim, sessiz konuş;  Duygularım karış karış, İstiyorsan eğer yarış Yüzyıl önce çık yollara. Gah yanarız, gah tüteriz, Tohumlardan te...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sessiz-konus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eller', 'eller-metin-kose-75ls4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerim beynimde birer daktilo

Duyular ruhuma sanki pencere

Kaşlarda çatılır düşünen beyin

Ve bir yürek ağlar fonunda neyin

Ankara				 

			

(2 haziran 2004)', 'Ellerim beynimde birer daktilo Duyular ruhuma sanki pencere Kaşlarda çatılır düşünen beyin Ve bir yürek ağlar fonunda neyin Ankara				  			 ...', ARRAY['Türk Edebiyatı','Şiir','Metin Köse']::text[], 8.5, '{"poet":"Metin Köse","poet_slug":"metin-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/eller-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eserleri yazan', 'eserleri-yazan-i-smet-barlioglu-t2t0i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanma ki bu sözler bana aittir; 

Eserleri yazan sadece Allah.

Zebur ''u okuyan güya Davud ''dur,

Eserleri yazan sadece Allah.

O benim içimde, kalemimdedir,

Doğrultup durduğu kelamımdadır,

Her neyi yazarsam O yanımdadır,

Eserleri yazan sadece Allah.

Herbir yanlışımda çizer, düzeltir,

Gücüm yettiğinde beni gözetir,

Kavrayabilirsem söyler, uzatır,

Eserleri yazan sadece Allah.

Lütfederek korur, aşmaz gücümü,

Öte üstelemez yorgun gördümü,

Çok güzel söylerim bana geldimi,

Eserleri yazan sadece Allah.

Bazan cabbar olur her satırımda,

Bazan biriktirir hep hatırımda,

Çabalar dururum yoksa yanımda,

Eserleri yazan sadece Allah.

Yanımda yokluğu tecellisizlik,

Köhne kalıbıma bir ilgisizlik,

Yoksa; her yer O ''nun, O ''nda yersizlik,

Eserleri yazan sadece Allah.

Bazan çok gaffurdur, bal gibi söyler,

Bana söyletir de kendisi dinler,

Bazan kahhar olur, sözü dipçikler,

Eserleri yazan sadece Allah.

Beni yarım asır her an eğitti,

Az ki olgunlaştım; kalktı söyletii,

Her nasıl ettiyse çok güzel etii,

Eserleri yazan sadece Allah.

O benimle iken tevazu neden? 

Nice kidolmuştur O ''nunla beden,

Ele değer vermem elbette ki ben,

Eserleri yazan sadece Allah.

Batlıoğlu der ki; baş bağlı O ''na,

Olmasa gücüm mü yeterdi buna,

O ''ndan büyük yoktur, asla, amenna,

Eserleri yazan sadece Allah.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 141-143/412)', 'Sanma ki bu sözler bana aittir;  Eserleri yazan sadece Allah. Zebur ''u okuyan güya Davud ''dur, Eserleri yazan sadece Allah. O benim içimde, ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/eserleri-yazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cani''ni Coni''nin şeyinde kaldık', 'cani-ni-coni-nin-seyinde-kaldik-murat-demir-s9ek7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sam’a döndü hem terane hem gayda

Ne bağ kaldı, ne gül kaldı, ne ada

Ahmak gibi garibanda, paşada

Cani’nin, Coni’nin elinde kaldık

Figan etme bülbül figanın boştur

Kanadın kırılmış yolun yokuştur

Neye yarar artık koştur, koşuştur

Cani’nin Coni’nin selinde kaldık

Ne dikenim kaldı ne gül ne fişek

Bu nasıl birlikmiş bu kadar gevşek

Salladıkça yere bir bir düşecek

Cani’nin Coni’nin belinde kaldık

Parça parça olduk bitti özümüz

Çakallar kurt olmuş geçmez sözümüz

Dost ile düşmanı seçmez gözümüz

Cani’nin Coni’nin dilinde kaldık

Sağcı solcu dinli dinsiz yapılıp

Senelerdir koyun gibi kırpılıp

Zengin, yoksul, yardımlara kapılıp

Cani’nin Coni’nin kilinde kaldık

Kendi kendimize yetip, yaşarken

İnsan gibi sahralarda koşarken

Nasılda pes edip bu kadar erken

Cani’nin Coni’nin külünde kaldık

Nerdesin yüreğim nerdesin gelki

Damarlara girdi esirlik zerki

Kafese konulmuş kartalın erki

Cani’nin Coni’nin ilinde kaldık

Murat derki artık toplan, toparlan

Bu vatan bizimdir gayrisi yalan

Körmusun, gözlerin görmez mi olan

Cani’nin Coni’nin şeyinde kaldık!', 'Sam’a döndü hem terane hem gayda Ne bağ kaldı, ne gül kaldı, ne ada Ahmak gibi garibanda, paşada Cani’nin, Coni’nin elinde kaldık Figan etme...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cani-ni-coni-nin-seyinde-kaldik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana doğru', 'sana-dogru-i-smet-barlioglu-riobn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aştım derdin üzerinden,

Sildim attım bedenimden

Şimdi var tut ellerimden; 

Geliyorum sana doğru.

Hırslarımı hep boşladım,

Hızlı idim, yavaşladım,

Tenekemi gümüşledim,

Geliyorum sana doğru.

Uyumuştum, uyarıldım,

Gafletlerden kotarıldım,

Tehlikeden kurtarıldım,

Geliyorum sana doğru.

Kalbim nasıl paslanmıştı,

Aklım hırsa yaslanmıştı,

Yaralarım koslanmıştı,

Geliyorum sana doğru.

Çoban nerde, ben nerdeydim? 

Çok dalmıştım, derindeydim,

Ahlaksızın yerindeydim,

Geliyorum sana doğru.

Korku pençe yüreğimde,

Günahlarım üzerimde,

Bir dilekçem var elimde,

Geliyorum sana doğru.

Bağışlar mı olasın sen? 

Kargışlar mı olasın sen? 

Sorguçlar mı olasın sen? 

Geliyorum sana doğru.

Barlıoğlu der ki; Şah ''ım,

Affeyle sen her günahım,

Lütfet, olsun ilk sabahım,

Geliyorum sana doğru.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 144-145/412)', 'Aştım derdin üzerinden, Sildim attım bedenimden Şimdi var tut ellerimden;  Geliyorum sana doğru. Hırslarımı hep boşladım, Hızlı idim, yavaşl...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sana-dogru-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıraların Tek Tesellim', 'hatiralarin-tek-tesellim-cafer-tayyar-ozkan-gbnop', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hissediyorum cananı, boğazım tıkanıyor,

Kalbim kuş gibi göğsümden fırlayacak sanki.

Kurduğum dünyamda nefes alsam da, almasam da, 

Hep yanında olmaktı, hayattan tek isteğim. 

Elim kolum bağlı olsa da, sen olacaksın hayatımda. 

Acılara gömülsem de, hatıraların tek tesellim... 

Gece yarı olmuş, uykudan eser yok gözlerimde,

Gurban olmak değil, ölene dek sevmek istiyorum seni.

Geceler vardır, yüreklere ölüm gibi acı katan,

Sözler vardır, hayata, duygulara değer biçen,

Mevla sevdiği gecelerde kendine açılan elleri,

Gerçek sevginin hürmetine, kalplerde kavuştursun, 

Kıskançlığımdan boğulsam da, yeminlerin tek tesellim...

Orada beni yaşayan, yaşatan parçam var,

Nefes aldığı sürece, sevdamı saygıyla yaşatacak,

Varlığım hep yanın olacak, ama bir kul bilmeyecek. 

Sevgim senin olacak, ölene dek değer bulacak, 

Kalbimde sonsuza kadar sevda ateşin yanacak,

Yüce Mevlam sesimizi duyar da, vuslata koşturur,

Kalplere hüzün değil, aşk şerbetinden doldurur,

Gidişim hep hüzünlendirse de, gelişim mutlu kılar...

Sensizlikten kıvransam da, bakışların tek tesellim...

Doğdum doğalı böylesi sevgi yaşamak senle nasipmiş

Sevmek çok zor, yaşamadan söylemek nafileymiş,

Söylediklerin çok acıttı aylarca, biçare yüreğimi, 

Sevgi var ya sevgi, işte onun adına acısı azaldı, 

Bir gün bir devrim olur, sana son adımı verirsem,

Kendine saygını benimle paylaşacağını bilirsem,

Dudağındaki sevgi sözlerini son nefesimde işitirsem, 

Çok uzun dediğin aşk yollarına, al güller dökeceğim

Her zaman sarılamasam da, kokuların tek tesellim...

Aslında gidecek ne yerim, nede söyleyecek sözüm var, 

Kader ağlarını sessizce örmüş yıllar sonra fark ettik.

Belki yolun yarısında, karanlıklar arasında aşkım var,

Parçan yollarda olsa da, saygıyla uzağı yakın kıldık.

Sakın yanlış anlama, söylediklerim acı çekmemen için, 

Ne olur kızma bana, istediklerim mutluluk rolü için,

Sesini duyamasam da, kulaklarımdaki tek tesellim...

Ne hayallerle, ne ümitlerle mutlu olmaktı dileğimiz, 

Suçlu ne sen, ne de ben. Biliyorsun kelepçeli ellerimiz,

Başka sevgilerde teselli yok, yetmeli bize büyük sevgimiz,

Sen demiştin ya, iyi ki senden ayrılıp cana dönmedim, 

Dayanamazdım derken, gene aynısı olacak diyemedim,

Sensizliğe dayanamasam da, varlığın tek tesellim...

İçim buruk, yüzüm soluk, yüreğim alabildiğine yanık. 

Yalnızım yine sensiz, eşsiz hatıraların tek tesellim, 

Seninle sensiz, çok uzaklarda ölümüne kaldım çaresiz. 

Ölümsüz sevgim seninle, bilirsin tanık meleklerimiz,

Sevgimizi yaşamak kalsa da, acılara merhem zaman. 

Ne getirecek yarınlar, sevda ektiğimiz umutlar bilinmez, 

Belki bu nefes, seni görene dek bir daha alınıp verilmez, 

Belli mi olur, yaşar mı canparçan buralarda sensiz,

Seninle nefes alamasam da, sevdan tek tesellim...

Her ne olursa olsun, cana vardığımda hatıralarımızı,

Kıskançlıkla içini kemiren, yürek titreten duygularını,

Fedakarlıkla bir kenara bırakıp, mutluluğumu istediğini,

Sevdan adına kabul ettim, içimde bir umutla çaresiz,

Canparçam sen mutlu ol, çünkü çok hak ediyorsun,

Ne kadar hakkımı helal etsem de, gönlüme var sitemim...

Çok uzak şehirlerde de olsa, birlikte çarpan yürekler, 

Birbirlerini aynı yürekteymiş gibi sever, hissederler. 

Gün gelir belki elim gider, vuslatta yazdığın mektuplara, 

Uzaklara dalıp seni yaşarım, sarılmışçasına yanı başımda. 

Saçına her dokunduğunda rüzgar, beni hatırla canparçam. 

Sevgim her zaman seninle, mutluluk sevenlerin hakkıdır,

Çok uzaklarda olsan da, gönül bahçemdekiler tek tesellim...

Sabah o müthiş baharı bahar yapan bir hava vardı aslında, 

Lakin şuan gök korkunç gürlüyor, şimşekler çakıyor. 

Belki de gökyüzünün bu hali, ikimizin yüreklerindekidir. 

Şuan gökyüzü, sanki yeryüzüne kavuşmak için çırpınıyor, 

Bana alnının yazısıyla eşlik ediyor gibisin canparçam. 

Hava öyle karardı ki, tıpkı karagözlünün gözleri gibi. 

Şimşeklerse seni ilk gördüğümdeki ifade gibi çok keskin,

Işıl bakışların olmasa da, resimlerin tek tesellim...

Işıl gözlerindeki rengin yeşile dönmesine bakmadan,

Uyku yoksa hala, gecenin bir yarısında gözlerinde,

Benzemez değil mi bitanem? cananın sesini duymayınca,

Sımsıcak nefesi, busesi, tenini titreterek sevmeyince,

Gerçek sevgiyi yaşadım diyemez, boğazına düğüm atarsın,

Gene seninle kurduğum gerçek dünyamın terminalindeyim,

İçim çok buruk sanki seni bekliyormuşum gibi titriyorum.

Seni yaşamasam da, yaşadıklarım tek tesellim...

19 Mayıs 2003 Bursa', 'Hissediyorum cananı, boğazım tıkanıyor, Kalbim kuş gibi göğsümden fırlayacak sanki. Kurduğum dünyamda nefes alsam da, almasam da,  Hep yanın...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/hatiralarin-tek-tesellim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Baharlar Ağlasın', 'bana-baharlar-aglasin-zulfikar-yapar-kaleli-bvtdq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arzu nazenin, kelebek

Tül götürsün, bar ağlasın.

Mecnun sebep, Leylâ dilek

Çöl götürsün, yâr ağlasın.

Acı dayanmaz acıma,

Yetişemem amacıma.

Dolu vursun yamacıma,

Sel götürsün, yar ağlasın.

Yıllar yıkar umudumu

Umut yakar sevda mumu

Sen yoksan koy tabutumu

El götürsün, ar ağlasın.

Sam vurmuş ihsan dağını

Silkeler can otağını

Sis sarmış gönül bağını

Yel götürsün, zor ağlasın.

Yürek yanar da yok çare

Lime lime, pare pare

Sevdam gidecekse yare

Kül götürsün, zar ağlasın.

Yanaştım yolun sonuna

Sitemi koydum yanına

Elim canan divanına

Gül götürsün, hâr ağlasın.

Beni her bahar ağlasın! .', 'Arzu nazenin, kelebek Tül götürsün, bar ağlasın. Mecnun sebep, Leylâ dilek Çöl götürsün, yâr ağlasın. Acı dayanmaz acıma, Yetişemem amacıma....', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bana-baharlar-aglasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güney beneğinin denizi tutan sesi (‘Ama’ ile ‘boşver’in hikayesi)', 'guney-beneginin-denizi-tutan-sesi-ama-ile-bosver-in-hikayesi-akin-akca-pwbrb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“04:28 tarihi”nde yola çıkmış bir şiir

için yazıldı, bu açıklama cümlesinin

De hemen altına, “05 dakikası”.

Sanki bir zaman yolcusu olur bu

İkinci düzeltiş, bu ikinci cümle; 

[ “Yaşanan” ve “yaşanacak” (olan)

Çıkarak vaktin öncesine seyahate]

Bir başlangıç vücutlayan, 

Şiirin (yukardaki)   son cümlesine.

Belli bir akışları vardır.

Kelimeler ve cümleler de insana benzer.

Nereye çekersen oraya gider.

Bazen bir şey düşünürüm, bazen tam onun aksini

Bu aslında bence çok acaip bir şeydir.

“Boşver” lafından çok “ama” demeye benzer

Böyle mevcudiyet kazanan bir olgu:

Bir ayrımdır bu, çok kişiye göre

Sen istediğin için bunu, o ehemmiyetlidir.

(Sarf ayrım olmak için ayrım olmuş

Olması da önemli değildir)

“Boşver” deme, 

Gereksiz inatlara bu laflarla sürüklenme

Yapıcı olsun dirayetin:

Direnensindir.

“Boşver” de diyebilirsin, öte yanda:

Sırf demek adına.

Eylemlerin’ se senin,“ama” laşıyordur; 

Böyle bir ‘eş paralel’de.

Bu vakitler, önemsemeyenin; 

Sıfırlanır belki, ‘bu tavır için koşturacağı’ …

Bir şey düşünürüm bazen:

Zaman bizi içinde sürüklüyor.

Ve o, evren için; 

Tam olarak bir nehir davranışı sergiliyor:

Bizi akıtıyor.

Zaman geliyor yaşlanıyoruz

Bu yüzden.

Karmaşadan olan ama görünmez de olan

Bir düzen eğrisine ulaşmalıyız

Ve ki, böyle sezdiğimiz bir zorunluluk; 

Acaba bizim ektiğimiz bir tohum mu? 

Nasılsa nasıl: Akıtan insan mı, zamanı? 

Elle kavranır mı hiç bunun kanıtı? 

Sanırım bunun adı şiir ya da sevgi …

Bir gün bilim adamları bulur mu, belki? 

Çünkü göreli bir şeydir üzüntü; 

Evren devamlı hareketliyse ki, 

Görünüyor öyle.

Vay be! 

: Tercümanı olan bir nehir; 

Şiirlerdeki “ama” ların

*

Bazen analiz çok fazla, sezme eylemi ise geliyor sonra:

De ki, savaşlar çıkmıyor bunların sonucunda? (!)

“Heil’ diyorsun” diyebilir çıkıp da 

‘Bir SS subayı gibi’; 

Bu lafımı anlamayan birisi.

Ama bir başkası, yarım yamalak anlamayanı; 

Cevap verirsin, değil mi? 

İşte budur boşvermemek:

(Analiz ve sezgi böyle kulaçlar)

Yani duyumsamak ve sonra etüt etmek.

Savaşlar çıkıyor, barış da yaratıyor zeka:

E, bu ne demektir? 

Yani zekadan kavga üretiliyorsa,

‘Barış’ için “boşver” demek ne gariptir! 

Düşüncenin boşvermişliğe, bu nokta, dayandığı’dır.

Ve neden “yarısından çoğu-bilim adamları”nın da

Savaş sanayinde çalıştığını anlatır:

Düşünülebilir mi ki; Hem kavga, hem savaş endüstrisi,

Ne iğrenç bir harmanlama

Ve emek deniyor ya, bunun da adına (sözüm ona) ! …

İşte akıllar çalışkan, bu boşvermişlikle:

Buz dağları kuzeyde, güneyde erimekte! 

Sağol, bak, insanlar böyle olsun:

Keşke hiç kavga etmese! 

-

‘Guneyden’ dostuma ithafen (Kısa bir konuşma sonrası oluşturduğum)', '“04:28 tarihi”nde yola çıkmış bir şiir için yazıldı, bu açıklama cümlesinin De hemen altına, “05 dakikası”. Sanki bir zaman yolcusu olur bu ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/guney-beneginin-denizi-tutan-sesi-ama-ile-bosver-in-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kovuk', 'kovuk-sule-aydemir-at15d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-ah düşlerim 

terasında oturuyorum

beş katlı bir ağaç

uzanmış dalları

ellerimi okşuyor 

rüzgarlı yaprakları

saçlarım savruluyor

kokunu dolduruyor 

aç genzim

içimde dolaşıyorsun 

deli gibi

çıkmaz sokaklara çarpıyorsun

çıkış yok biliyorsun

acılarımı nasıl ıkınarak 

güneşleri doğurduğumu

biliyorsun

saflaşıyor tenim

yüreğim derenin dibi 

düden taşları gibi

bembeyazsın

biliyorsun 

-ah düşlerim 

ne zaman geliyorsun

*kalemi gönülden mürekkepli kadının günlüğünden', '-ah düşlerim  terasında oturuyorum beş katlı bir ağaç uzanmış dalları ellerimi okşuyor  rüzgarlı yaprakları saçlarım savruluyor kokunu doldu...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kovuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Sensiz', 'gece-sensiz-hikmet-yakisir-0ydlf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece sessiz, gece sensiz.

Gece karanlık, gece yoksul,

Aşk yoksulu, sevgi yoksulu

Ben yoksul, ben çaresiz

Gelincik kokulu yar’im nerdesin? 

Alıştım sana can, alıştım.

Sevdim seni yar.

Yokluğuna alışmaya çalıştım

Olmadı, olmuyor

Gelincik kokulu yar’im nerdesin? 

Sen yoksan ben yokum.

Sen yoksan hayat yok,

Sen yoksan kainat yok,

Sensizliğe alışamadım can, alışamam

Gelincik kokulu yar’im nerdesin? 

Sen başını başka omuzlara koydun,

Ben kokunu başka tenlerde aradım.

Gecenin kör karanlığında silahı çekip

Kalbimdeki seni vuruyorum.

Gelincik kokulu yar’im nerdesin? 

Sol yanıma bakıyorum, delik deşik

Seni arıyorum, yoksun.

Söküp kalbimi atıyorum kedilere,

İçinde sen yoksun diye.

Gelincik kokulu yar’im nerdesin? 

Ya bana gel, ya beni yanına al.

Ya atıl kollarıma, ya beni sar.

Sensiz çekilmiyor hayat can.

Bu dünya sensiz bana dar.

Gelincik kokulu yar’im nerdesin? 

30 Mayıs 2004', 'Gece sessiz, gece sensiz. Gece karanlık, gece yoksul, Aşk yoksulu, sevgi yoksulu Ben yoksul, ben çaresiz Gelincik kokulu yar’im nerdesin?  A...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gece-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler Şahit', 'geceler-sahit-serkan-aslan-g7lux', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu şehir şahit Seni Sevdiğime,

İnsanları olmasa da, ışıkları şahit.

Gündüzleri olmasa da, geceleri şahit.

Kaldırımları, şarkıları şahit.

Her sabah seninle doğuyor,

Her gece sensiz ölüyorum ben.

Bu şehir şahit öldüğüme,

İnsanları olmasa da, ışıkları şahit.

Gündüzleri olmasa da, geceleri şahit.

Kaldırımları, şarkıları şahit.

İşte bu koca şehir şahit; 

Seni severek öldüğüme....

Kör karanlık şahit Papatyam değişime.....

(11 Mayıs 2004 / 01:15)', 'Bu şehir şahit Seni Sevdiğime, İnsanları olmasa da, ışıkları şahit. Gündüzleri olmasa da, geceleri şahit. Kaldırımları, şarkıları şahit. Her...', ARRAY['Türk Edebiyatı','Şiir','Serkan Aslan']::text[], 8.5, '{"poet":"Serkan Aslan","poet_slug":"serkan-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/geceler-sahit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Gözlüm-e', 'gece-gozlum-e-hikmet-yakisir-zhat6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece gözlerinle bir bakışın

Bakışınla can yakışın

Gözümden kalbime akışın

Ne büyük hazdır gece gözlüm

Gece gözlerinde şimşek çakan

Alev alev canımı yakan

Güzelliğinle caka satan

Vahşi bakışlı gece gözlüm

Gece gözlerinde var bir dünya

O dünyada gördüm rüya

Rüyamda benim olmuşsun güya

Ne güzel rüyaydı gece gözlüm

Bakışınla canımı da yaksan

Güzelliğinle caka da satsan

Ancak rüyamda benim olsan

Yinede seveceğim gece gözlüm

Gün ol güneşim ol yak beni

Ay ol gece mehtabında öp beni

Deniz ol deryalarında sar beni

Ne olursan ol benim ol gece gözlüm

02 Haziran 2004', 'Gece gözlerinle bir bakışın Bakışınla can yakışın Gözümden kalbime akışın Ne büyük hazdır gece gözlüm Gece gözlerinde şimşek çakan Alev alev...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gece-gozlum-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yeniden', 'ask-yeniden-reyhan-sur-60hms', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dalarsınız bir anda denizin koynuna

suyla dolar kulaklarınız 

tıkanırsınız

kabuk bağlamıştır söylemlerin acısı

sızlar tüm dokularınız

kendi sesiniz bile duyulmaz olur

artar bulantılar

başınız döner 

ve yosunlu derinlikler

yitiklerinizi ararsınız 

kusarsınız kendinizi

dağlardan bırakılan alevli tekerlek gibi

döne döne 

düşersiniz uçurumlardan

kendi ekseninize

nereye baksanız kaldırıp başınızı

gri bir bulut oturmuştur gözlerinize

karanlıktasınız işte 

sessizlik tamtamlarını çalar

siz duyarsınız 

başkası duymaz

çıldırırsınız

vurdumduymaz bir dünyada

içinizde yol alırken çığlıklarınız 

sarılacak hiçbir şey bulamazsınız

yörüngesi bozuk  dünyadan

merkezkaç kuvveti atar sizi

parçalandıkça savruluşlar

gök adalarda kaybolursunuz

..

gün gelir 

yeniden 

kumları yalayan su olur

yüreği kaynatan ateş 

ve yedi kuşak çiçekte

döllenmeye hazır 

aşk tohumları saçar polenler

yeniden çoğalırsınız

aşk

yeniden', 'dalarsınız bir anda denizin koynuna suyla dolar kulaklarınız  tıkanırsınız kabuk bağlamıştır söylemlerin acısı sızlar tüm dokularınız kendi ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ask-yeniden-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-mustafa-ercanli-svtbj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aramızda yollar olsa bile bil ki  senden  uzaklarda  değilim

Anlasana artık yanında   baktığın nergizdeyim.

Belki sana teninden daha yakın

Her nefeste  atan yüreğindeyim', 'Aramızda yollar olsa bile bil ki  senden  uzaklarda  değilim Anlasana artık yanında   baktığın nergizdeyim. Belki sana teninden daha yakın H...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ercanlı']::text[], 8.5, '{"poet":"Mustafa Ercanlı","poet_slug":"mustafa-ercanli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ozlem-165-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soruyorum', 'soruyorum-mustafa-ercanli-p18ef', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen ben olurmusun ben seni sevdiğimden beri senim

Ben sevgine müebbet yemiş bir mahkumum.

Sen üzerinde iki damla yaş olan okuduğum mektubum olurmusun.

Açılsa diyorum bütün  paslı  kapılırım sonuna kadar yüreğimin 

Sen serinletecek sevda rüzgarım olurmusun.

Yüreğim kaldırırmı bilmem bunca sızıyı

Ama ben! Ben sana tövbe edemedim.

Ben  sensiz gündüzde geceyi kalabalıklarda yanlızlığı yaşadım.

Şimdi sana haykırıyorum cevap ver.

Yaşamama sebep  umudum, sevgilim olurmusun? ? ? ? ? ? ? ? ?', 'Sen ben olurmusun ben seni sevdiğimden beri senim Ben sevgine müebbet yemiş bir mahkumum. Sen üzerinde iki damla yaş olan okuduğum mektubum ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ercanlı']::text[], 8.5, '{"poet":"Mustafa Ercanlı","poet_slug":"mustafa-ercanli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/soruyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Avuç', 'bir-avuc-reyhan-sur-usomb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'daldırdıkça ellerimi 

denizin kuytularına 

kumlar kayar parmak aralarımdan 

ve bir avuç mavi kalır 

gözlerimi daldırdıkça güneşin kızıl karnına 

kan kaybeder çiçekler rengarenk 

bir avuç gelincik kalır

yanık yapraklarıyla 

derinden akarak su yollarında 

daldırdıkça yüreğimi toprak altına 

sürgünlerle bezeli 

salkım saçak kökler kalır 

bir avuç 

yıldızların şavkına daldırdıkça  tenimi 

yıkanırım yakamozlarında 

değerim ateşine çığlık çığlığa aşkın 

küllerim kalır 

yağarım oluklarına ellerinin 

avuç avuç...', 'daldırdıkça ellerimi  denizin kuytularına  kumlar kayar parmak aralarımdan  ve bir avuç mavi kalır  gözlerimi daldırdıkça güneşin kızıl karn...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-avuc-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşılıksız', 'karsiliksiz-mustafa-ercanli-wffhd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç duymadın senin için ağlarken hıçkırıklarımı 

Bilmedin fotograflarının neden kaybolduğunu 

Sevmedin çiçekleri sevdiğin kadar 

Anlamdın sana çöl ortasında kalmış suzus biri  gibi 

Sevgine nasıl susadığımı

Hissetmedin kaygısızca  sana yazdığım 

imalı sevgi sözcüklerini 

Hiç bilmedin düşünürken nasıl hayallere daldığımı

Özlemedin ki  benim seni özlediğim kadar

Hiç yazmadın o kağıtlara 

Benim sana   yazdığım  veremediğim mektuplarım  kadar

Sen unuttun  mu bilmem fakat 

Sen benim unutmaya çalıştığım  unutamadığımsın.', 'Hiç duymadın senin için ağlarken hıçkırıklarımı  Bilmedin fotograflarının neden kaybolduğunu  Sevmedin çiçekleri sevdiğin kadar  Anlamdın sa...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ercanlı']::text[], 8.5, '{"poet":"Mustafa Ercanlı","poet_slug":"mustafa-ercanli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karsiliksiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenti', 'beklenti-mustafa-ercanli-q6eve', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessizliğin sesi olsam 

Haykırsam bütün sevenlerin türküsünü 

Seyrine dalarken sevenlerin.  bu güzelliklerin

Ve yollara bakarken beklediğim sen olsaydın.

Ağzımda bir şarkı 

Ve karşımda hep hayalin vardı

Bir türlü alışamadığım oldun  sensizlik.

Sensizliğin ortasında seni beklesem.

Kalemlerim ve kağıtlarım olsada yazsam 

Birinci sigaram hiç bitmese ve bir nefes daha çeksem

Doldurdu dört bir yanımı senin hayalin. 

Gitmeyeceğine inandırsam kendimi hayalimde 

Hep böylece  beklediğim sen olsan', 'Sessizliğin sesi olsam  Haykırsam bütün sevenlerin türküsünü  Seyrine dalarken sevenlerin.  bu güzelliklerin Ve yollara bakarken beklediğim ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ercanlı']::text[], 8.5, '{"poet":"Mustafa Ercanlı","poet_slug":"mustafa-ercanli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beklenti-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-naime-erlacin-oq4v6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir çocuk ağlıyor uzakta

bütün çocuklar benim

kan ağlıyor yüreğim

kaç arşın insanlık katlettik 

kaç kıyımdan yürüyüp gittik sırıtarak

yaseminlerce sevdik hayalleri

düş konakları inşa ettik

ürküttü gerçekler sonra

öteledik korkarak

değeri bilinmezdi dost canların

dost avuçların sıcaklığı

çocuklardı yalnızca anlayanlar 

ve çocuk kalanlar

“suçum nedir” diye sorma sakın

sen mazi kadar

sen gelecek kadar suçlusun

çünkü çocuksun! 

(2 Haziran 2004)', 'bir çocuk ağlıyor uzakta bütün çocuklar benim kan ağlıyor yüreğim kaç arşın insanlık katlettik  kaç kıyımdan yürüyüp gittik sırıtarak yasemi...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/agit-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mükemmel İnsan', 'mukemmel-i-nsan-necmi-unsal-6uacm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mükemmel  insan,  kendini  Rabbinde  bulandır.

Kaçarak  benlikden, yüce Rabbe  sokulandır.

''Kendini bilen Rabbini bilir '' der peygamber.

Hakk''ı bilen etrafa hep saçar  misk-ü amber.

11 Mart 2004 Perşembe,  Danimarka-Køge  22.42

8+6', 'Mükemmel  insan,  kendini  Rabbinde  bulandır. Kaçarak  benlikden, yüce Rabbe  sokulandır. ''Kendini bilen Rabbini bilir '' der peygamber. Hak...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mukemmel-insan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yadigar*', 'yadigar-kubilay-enginol-e37be', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kocaman bedeninde hep umutsuzluk taşıdı

Gözlerinde,hep sevgi vardı

Günün renkli yaşamından,giderdi karanlığa

Hep isyan ederdi,içindeki yanlızlığa

Beyoğlunun ışıkları bile aydınlatamazdı içini

Korkunç sonunu,kendiside bilirdi

Film sokağında,figürasyon rolleri

Başka bir heveslendirir,orada bekleyenleri

Çay''a karışmış simit,birde umut

İş çıkamzssa ekmek götürmeyi unut

Dayak yemişsin,ne olacak,rol icabı

Para kazanıyorsun kardeşim,yok ayıbı

O gün yine istenmedi,küstü gündüze

Parası yoktu,gidemezdi otele

El, ayak iyice çekilince beyoğlundan

Muhallebicinin önü,korurdu onu soğuktan

İmalat sıcağını buraya üflerdi

İşi bilen garibanlar,gece oraya giderdi

Son kez uzandı yadigar mazgala

Kurtuldu,uyanamadı bir daha

Bu şiir merhum Yadigar Ejder''e ithaf edilmiştir', 'Kocaman bedeninde hep umutsuzluk taşıdı Gözlerinde,hep sevgi vardı Günün renkli yaşamından,giderdi karanlığa Hep isyan ederdi,içindeki yanlı...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yadigar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçer miyim...', 'vazgecer-miyim-i-brahim-ethem-bingul-bpq92', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geldin bin naz ile nazlım

Ben de o kadar sevilseydim 

Kim bilir neler neler ederdim

Belki hayatını zindana çevirirdim...

Hemen kötüye yorma böyle

İtirazın varsa söyle

Bir bana bak,bir de kendini gözle

Haklıyım diyorsan gel konuş benle

Naz et be sevgilim,seni sevenim

Ben kıymet bilmez değilim

Bir parça sevgini göster sevgilim

Ben seni sevmişim vazgeçer miyim', 'Geldin bin naz ile nazlım Ben de o kadar sevilseydim  Kim bilir neler neler ederdim Belki hayatını zindana çevirirdim... Hemen kötüye yorma ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vazgecer-miyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırladım', 'hatirladim-sirma-mersin-rhrxk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nemli gözlerden 

Düşen, düşen her damlada...

Ayrılığa gebe kalan

Özlemimizi hatırladım 

..............................................................

..............................................................

..............................................................

Ter kokan bedenimin

Islaklığında 

Teninin sıcaklığını hatırladım...

............................................................

............................................................

............................................................

Seni hatırladıkca! 

Aklımda, bedenimde 

Bir tuhaf oluyor...

.........................................................

.........................................................

Her ne varsa,

Seni hatırlıyorum.

31.05.04', 'Nemli gözlerden  Düşen, düşen her damlada... Ayrılığa gebe kalan Özlemimizi hatırladım  .......................................................', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hatirladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk için', 'ask-icin-abdusselam-bugur-hdty6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben, aşk''a ömür biçenlerden değilim! 

Ki... Tutku''dan anlamam.

Ben mahşeri görmüş; yaşayanlardan değilim! 

Ki... Aşk olmadan yaşanmam! ...', 'Ben, aşk''a ömür biçenlerden değilim!  Ki... Tutku''dan anlamam. Ben mahşeri görmüş; yaşayanlardan değilim!  Ki... Aşk olmadan yaşanmam! ......', ARRAY['Türk Edebiyatı','Şiir','Abdüsselam Bügür']::text[], 8.5, '{"poet":"Abdüsselam Bügür","poet_slug":"abdusselam-bugur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-icin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadın Sen', 'anlamadin-sen-ozgen-topcu-oufhf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu zavallı gönlüm kafayı sana

Taktı ama beni anlamadın sen

Kavuşmak ne zaman diyerek fala

Baktı ama beni anlamadın sen

Benim için yoktur dünyada eşin

Gel doğsun odama sevda güneşin

Genç yaşta içimi hasret ateşin

Yaktı ama beni anlamadın sen

Direncim kalmadı kadere karşı

Sen beni etmişşin bir sabır taşı

Dönmedin diyerek gözüm kan yaşı

Döktü ama beni anlamadın sen

Kolaymı yürekten biranda silmek

Ne gelir aklına deyince sevmek

Seni sevdim diye dünyamı felek

Yıktı ama beni anlamadın sen

                    Özgen Topçu', 'Şu zavallı gönlüm kafayı sana Taktı ama beni anlamadın sen Kavuşmak ne zaman diyerek fala Baktı ama beni anlamadın sen Benim için yoktur dün...', ARRAY['Türk Edebiyatı','Şiir','Özgen Topçu']::text[], 8.5, '{"poet":"Özgen Topçu","poet_slug":"ozgen-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anlamadin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kalp Bendeyken', 'bu-kalp-bendeyken-caner-kuru-rj8ax', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Git gidersen, benden bir şey bekleme,

Çekemem derdini bana yükleme,

Alışığım ben her çeşit iklime,

Daha çok severim, bu kalp bendeyken.

Sen düşün bırakıp gittiğin günü,

Sen ağla, sen üzül, sen yak gönlünü,

Paylaşamam senle aynı hüzünü,

Daha çok severim, bu kalp bendeyken.

Sensiz de severim hem de delice,

Yalnız mı kalırım sandın, her gece,

Tanrım bana ömür versin sadece,

Daha çok severim, bu kalp bendeyken.', 'Git gidersen, benden bir şey bekleme, Çekemem derdini bana yükleme, Alışığım ben her çeşit iklime, Daha çok severim, bu kalp bendeyken. Sen ...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-kalp-bendeyken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalıp Gidiyorum Bazen', 'dalip-gidiyorum-bazen-ensar-cevval-regkh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalıp gidiyorum bazen

Bir vapur güvertesinde yol alırken

Ekmek attığım martıların ardından; 

Su gözlerimi çekiyor

Gözlerim bedenimi

Ansızın tutunuyorum korkuluğa

Ardımdan uzanan ellerde avunuyor başım.

Dalıp gidiyorum bazen

Kız kulesinden İstanbul’u seyrederken

Selam verdiğim gemilerin ardından; 

Martılar aklımı çeliyor

Kollarım bedenimi

Apansız kanatlanıyorum sonsuzluğa

Koltuktan düşüyor yastığını kaybeden başım.

Üsküdar 20 Mayıs 2004

Ensar Cevval', 'Dalıp gidiyorum bazen Bir vapur güvertesinde yol alırken Ekmek attığım martıların ardından;  Su gözlerimi çekiyor Gözlerim bedenimi Ansızın ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dalip-gidiyorum-bazen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur penceresi 4', 'yagmur-penceresi-4-mustafa-tugrul-kosar-03q08', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimşekler odamda çakıyor 

Çaktıkça moraran bir köşedeyim 

Son kibrit yarım tek bekler sigaram 

Usul usul gel küçüğüm 

Yak da birlikte tütelim 

Ben uyurum şimdi buhran içinde 

Can veren kurban gibi titrerim 

Gıcırdamazsa kapım uyanmam 

Top atsalar duymam anlayacağın 

Birkaç dalım daha kurur dökülür 

Yine yoksa eğer ağlayacağın 

Küçük kız,büyük kadın,ulu kuvvet 

Ölüm yalnızlığım var bitti rehavet 

Gören sen,bilen sen,hisseden sen 

Başka bedenlerde döküldü alnım 

İnkarcı olmam artık bir fırsat versen 

Günahımı affet boncuk bakışlı Tanrım 

Uyurken,uyanıkken kaç türlü karabasan 

Etime saldırıp kanımdan bir tas içiyor 

Bir kabus,bir vahşet bıraktın bu yerde 

Caddeden sokaklardan yanık yüzler geçiyor 

Virane kalıntılar ilk görünen bu yerde 

İçimde tek parça sen bir intihar geçiyor 

Sensiz gece her saat bir asıra bedeldir 

Unutmadım inkarım şeytanınkine eşittir 

Merhamet yine senden gelir affın malum olur 

Hükmü gündüze geçer biter rezaletler gecesi 

Ilık bir güneşle uyanırım her sabah 

Gözlerimi bilirsin hep yağmur penceresi...', 'Şimşekler odamda çakıyor  Çaktıkça moraran bir köşedeyim  Son kibrit yarım tek bekler sigaram  Usul usul gel küçüğüm  Yak da birlikte tüteli...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yagmur-penceresi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kadar Olur', 'bu-kadar-olur-gulsen-senderin-s8mt1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni yaşamak öyle hoş ki, bu kadar olur

Hoşgörü yorganıyla ak göğsünde uyumak.

Gönüllere sığmayan kutsallığa sığınmak

O kadar sarıyor ki beni, bu kadar olur

Aşkın varabildiği sevgi, bu kadar olur! 

O kadar güzelsin ki güzel: bu kadar olur

Güneş doğar gün batar, sesin kulaklarımda

Öyle bir bağ verdin ki derin bu kadar olur

Her an gülüşün açar yaşam şafaklarımda

Seni yaşıyorum hep seni, bu kadar olur! 

Emeğinle bir hayat verdin, bu kadar olur

Sevgi ördün bizlere kaderin ağından bak

Zorlukları başarmak, yenmek; bu kafar olur

O sevginin gücüdür, iğneyle kuyu kazmak! 

Sen gibi çile çektim, çile bu kadar olur! 

Yediveren gül kokun, tende bu kadar olur

Öyle yakıyor ki ah! '''' Gülannem, Anneciğim ''''

Sen benden ayrı bense üç yavrumdan da ayrı.

Başka sevgi tanımam, senin sevginden gayrı

Öylebir sevgidir ki, '''' ANNE '''', bu kadar olur! 

12-05-2002-Pazar

Beylikdüzü-İstanbul.', 'Seni yaşamak öyle hoş ki, bu kadar olur Hoşgörü yorganıyla ak göğsünde uyumak. Gönüllere sığmayan kutsallığa sığınmak O kadar sarıyor ki ben...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bu-kadar-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menderes', 'menderes-i-brahim-dikmen-2-72k1v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çivrilin,kekik kokan eteklerinde yuvan,

asırlık çınarların,koca palamutların,kan kırmızı vişnelerin,

can suyu oldun asırlardır.

nice ovalara hayat verdin,her yudumunda.

Gülümsediler...! 

boy boy mısır tarlaları,bembeyaz teninde akaltın pamuk kozaları.

her gittiğin yere bereket götürdün,ekinler ekmek oldu,pamuklar urba,

hırka,tenimize göğnek oldu.

İsmel emmi''nin yüzü güldü sayende,kübra nine''min gözleri güldü bereketinden.

memleketime nam saldı sayende,dağlarından yağ aktı,ovalarından bal asırlarca.

barajlar kurduk vadilerinde,suladık ovamızı,taze balığını yedik.

ne güzeldi o''yayın balıkları,ve hala negüzel çengi kıvrımların.

tarhler boyu uygarlıklara kucak açtın,eteklerinde.ne medeniyetler gördü eşsiz güzellikteki çengi kıvrımların.

Egeye hayat verdi içilesi billur suyun,süzüle süzüle,denize dökülüşünü seyrettik hep,koca denizde son buluşunu,kucaklaşmanı,tanrıların kumuyla.

                                  Hep seyredeceğiz seni,herzaman suyunda hayat bulacağız,çocuk gibi haşarı,elif kızın uysal edasıyla,akışını seyredeceğiz.

                                  Rakkasenin oynaklığında,çengi kıvrımlarında daha asırlarca hayat bulacak ege.daha çok medeniyetler kurulacak kıyılarında.

                                    MENDERES........!', 'Çivrilin,kekik kokan eteklerinde yuvan, asırlık çınarların,koca palamutların,kan kırmızı vişnelerin, can suyu oldun asırlardır. nice ovalara...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/menderes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar Kırılır Yüreğimde', 'aynalar-kirilir-yuregimde-suskun-dunyam-remdm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlayamadım ben bu hayatı, 

Anlayamadım zamanın işleyişini, 

Yaşamın gerektirdiğini. 

Zaman kirli ve çirkin, 

Aynalar sahte aynalar bozuk, 

Yanlış gösteriyorlar; 

Ruhum bu kadar güzel değil, 

Bu kadar temiz değil, 

Kirlendi artık, kirlendi. 

Gerçek değil bu dünya, 

Uzaklarda ki yıldızlar gibi, 

Benim gibi yalan. 

Dün yine konuşmadım kimseyle, 

Konuşamadım. 

İnsanların yüzüne bakmadım, 

Bakamadım. 

Kimselere bir kinim yok aslında 

Benim kavgam kendimle, 

Hayatı sevememkle, 

Aynada ki çirkinliğimle, 

Utandığım yüzümle, 

Benim kavgam ölümle... 

Bir rüya gördüm gece, 

Melekler girdi düşüme, 

Berrak bir dehliz ortasında; 

Dokundular yüzüme. 

Gitme dediler kal, 

Daha yapacağın çok şey var. 

Utanamdan ağladım utanmadan. 

Gözyaşlarımı avuçlarıma biriktirip, 

Çirkinliğimi yıkadım.. 

Uyandığımda pencerede bir kuşla konuştum 

O da anlamadı beni sevmek istedim kaçtı 

Bu kadar korkunçmuydum? 

Bu kadar yabanimiydim? 

Korkulacak kadar çirkin mi? 

Neydi beni bu denli çirkin yapan? 

Yolda yürüken bir adam baktı suratıma 

Sonra tükürdü kaldırıma! 

Kaldırım mıydı tükürüğü çeken? 

Yoksa hayat mıydı tükürülen? 

Yok yok bu böyle olmayacak 

Sürmeyecek bu yalnızlıklar 

Tükürmekten başka ne var yapılacak? 

Akşam güneşi batıyor marmaradan 

Umutlar batıyor yalnızlıklar başlıyor 

Gece karanlığında utanç duvarında 

Ağlamalar başlıyor 

Aynalardaki çirkinlikler görünüyor 

Ay ışığından kan damlıyor 

Bulutlardan acılar çakıyor 

Uzakta ki yıldızlar ağlıyor 

Bir tepeye çıktım 

Yüksekce bir uçurum 

İsyan bulutu toplanmış beynimde 

Taşlar yuvarladım uçurumdan 

Ay ışığına küfür ettim 

Bir güzellik aradım beynimde 

Bir umut aradım 

Bulamadım 

Hep böyle oluyor her zaman 

Yarım kalır hayallerim 

Umutarım dağılır 

Biter düşlerim geceleri 

Gündüz karanlığında kaybolur yalnızlığım 

Bağırmak isteyince sesim duyulmaz olur 

Ben yorgun ben bitkin 

Aynalar kırılır yüreğimde 

(04/06/2002 -Yeniköy 10:30)', 'Anlayamadım ben bu hayatı,  Anlayamadım zamanın işleyişini,  Yaşamın gerektirdiğini.  Zaman kirli ve çirkin,  Aynalar sahte aynalar bozuk,  ...', ARRAY['Türk Edebiyatı','Şiir','Suskun Dünyam']::text[], 8.5, '{"poet":"Suskun Dünyam","poet_slug":"suskun-dunyam","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/aynalar-kirilir-yuregimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümün Son Adı', 'gonlumun-son-adi-caner-kuru-jka76', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüsrana uğradım bu genç çağımda,

Viran oldu gitti gönül bağım da.

Biriken damlalar şu yanağımda,

Gönlümün sevgiye imdadı oldu.

İçinde olduğum öyle bir an ki,

Tüm dünya başıma yıkılmış sanki.

Seni kollarıma almak inan ki,

Tüm hayatımın tek muradı oldu.

Gömüldüm içimin yalnızlığına,

Beni de aldı bak, kader ağına.

Sevilmek mutluluk verir çoğuna,

Benimse gönlümün feryadı oldu.

Yetmiyor gözyaşı her şey biterken,

Ne varsa götürdü zaman geçerken.

Elveda deyip de sen de giderken,

Yalnızlık gönlümün son adı oldu.', 'Hüsrana uğradım bu genç çağımda, Viran oldu gitti gönül bağım da. Biriken damlalar şu yanağımda, Gönlümün sevgiye imdadı oldu. İçinde olduğu...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonlumun-son-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç kesik', 'uc-kesik-metin-kose-yjqaq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüm hayatı keser

Caddeler sokakları

Kapılar boşlukları

Dalgın elini keser

Salata yapmak için

Doğrarken soğanları

Bir de delikanlılar

Kaldırım kenarında

Gelip geçen kızları

Ankara

(2 haziran 2004)', 'Ölüm hayatı keser Caddeler sokakları Kapılar boşlukları Dalgın elini keser Salata yapmak için Doğrarken soğanları Bir de delikanlılar Kaldır...', ARRAY['Türk Edebiyatı','Şiir','Metin Köse']::text[], 8.5, '{"poet":"Metin Köse","poet_slug":"metin-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/uc-kesik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gitti', 'o-gitti-umit-kilislioglu-ozger-4bryd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O gitti...

Geriye kalan

Bahçe duvarına tebeşirle yazdığı adı,

Yastıkta saçlarının kokusu,

Yanağımda öpücüğünün tadı...

Yüreğim sudan çıkan balığın hâlini, 

Çaresizliğini anladı.

Kollarım ardından uzadı,

Uzadı,

Uzadı...

(2. Haziran 2004)  

Not: Şükürler olsun ki o hayatta.

         Sadece bir yabancı ülkede şimdi.', 'O gitti... Geriye kalan Bahçe duvarına tebeşirle yazdığı adı, Yastıkta saçlarının kokusu, Yanağımda öpücüğünün tadı... Yüreğim sudan çıkan b...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/o-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değirmen', 'degirmen-vedat-koseoglu-nmanr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir büyük değirmen taşında öğütülürken zaman,

