INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakın Gel', 'yakin-gel-caner-kuru-ay134', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllardır dinmeyen derdin ilacı,

Gönlümün meyvesi, sevgi ağacı

Gel otur yanıma, başımın tacı,

Uzak durma öyle, yakın gel yakın.

Gül biraz, ümit ver, kırma kalbimi,

Yakıp da bırakma, sar şu bedeni,

Görenler zavallı sanmasın beni,

Uzak durma öyle, yakın gel yakın.

Gel de yıllar süren bu hasret bitsin

İçimden acılar savrulsun gitsin

Gönlümün feryadı duymana yetsin

Uzak durma öyle, yakın gel yakın.', 'Yıllardır dinmeyen derdin ilacı, Gönlümün meyvesi, sevgi ağacı Gel otur yanıma, başımın tacı, Uzak durma öyle, yakın gel yakın. Gül biraz, ü...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yakin-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesini Duyuyorum', 'sesini-duyuyorum-hamit-kunt-kttop', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sesini duyuyorum uzat elini

Gözlerinde büyüttüğün o yufka yürekli adam

Tükendi cüssesinin içinde serabını kovalamaktan

Yüreğinde damıttığın kızıl sevdayı ışınla yüreğime

Sesini duyuyorum uzat elini

Sesini duyuyorum uzat elini

Gözlerimi yapıştırdım geceye

Bak ki  kapanmasın

Işığını gözlerinden alan yüreğimdeki yıldızlar

Sakin bir deniz kenarında

Yüzüne yansıyan dolunayın saçlarına takılsın

Sesini duyuyorum uzat elini

Sesini duyuyorum uzat elini

Bitsin şu uzaktan yangınlarımız

Dokunsun iki kızıl sevda dudak dudağa

Bilmediğimiz diyarlara gidelim

Tanımadığımız sokakları

Görmediğimiz yüzleri

Yürümediğimiz patikaları

Beraber keşfedelim

Koklamadığımız gülleri

Birlikte derelim

Sesini duyuyorum uzat elini

Sesini duyuyorum uzat elini

Büyüdüğümü çoktan unuttum ben

Sevdan yüreğime düştükten beri

İşte geldim gönlünün kapısına

Boşalttım elimi eteğimi

Kapını çalmamı beklemeden

İçimdeki çocuğun tut elinden

Al içeri

Sesini duyuyorum uzat elini

Sesini duyuyorum uzat elini

O küçük bedenine sığmayan sevdanı doldur geceye

Düet yapıp asalım yıldızların kuyruğuna

En güzel aşk şiirlerini

Yüreğindeki büyük ateşten 

Bir kıvılcım sıçrat gözlerime

Buluşsun  kutupları sevdanın

Zıtların vuslatı yaksın kavursun

Büyütsün yürekleri

Yılların enkazında bir el bekleyen duygularını haykır kulaklarıma

Sesini duyuyorum uzat elini

                                                              08/06/2004-İzmir', 'Sesini duyuyorum uzat elini Gözlerinde büyüttüğün o yufka yürekli adam Tükendi cüssesinin içinde serabını kovalamaktan Yüreğinde damıttığın ...', ARRAY['Türk Edebiyatı','Şiir','Hamit Kunt']::text[], 8.5, '{"poet":"Hamit Kunt","poet_slug":"hamit-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/sesini-duyuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garbin Memed', 'garbin-memed-ali-gencay-28pe4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yıllardan arta kalan

dilde kahır 

bir de garibin memed di

siyatikli bacak 

tahtalı diğeri 

titrek elinde tütün tabakası 

üzeri Çin''ce işlemeli 

çok kez dolamış kağıdı tütünü 

ellerinden belli 

sararan bıyıklarda kaç kez söylemişti 

o uçuk bir ezgiyi 

anladı bakışlarımdan merakı sezdi 

kenarından kaldırıp sekiz köşe kasketi 

dedi; 

''''yanaş hele berime gel,gel bi,, 

o koca taştan adam

dillendi

kelimeleri divana serildi 

Kore''de vermiş bacağının birini 

kabartıp göğsünü 

duman dolu ağzıyla 

dedi; 

''''vallah birini daha veririm vatan için ne ki,, 

siyatik kilitlemiş diğerini 

tütüne de orda alışmış 

gakoş onbaşıya sövüp durdu 

tabaka ölünce ondan kalmış 

iki yıl dolmamış askerliği 

tahtalınmış bacağı 

sonra 

baba ocağı 

anası karışlar vermiş 

babası öküzler devirmiş 

harman vakti evlenmiş 

ne bilsin 

yeni gelin 

dememişler alınca ederini 

koca tutmuş zemheride ete köyün gencini 

bir kez daha vurmuş kaderi 

ısırdı bıyıklarını dikti gözlerini 

dedi; 

''''kahpenin dölü kırdı belimi,, 

çınlamış telgrafın telleri 

beş,on gün sonra 

gelmiş emmi oğlunun bayraklı kefeni 

ağıtlar

yitikler 

köy mahşer yeri 

koca kış geçmiş 

bahara bağlamış kader 

kapkara

tezek kokulu geceleri 

babası

amucaları

demişler 

koma başları yerde bebeleri 

almış yengesini nikahına 

bir kez bile dokunmadan geceleri 

ne baba demiş 

nede emmi bebeleri 

hep davar gütmüş 

gündüzleri

geceleri

tabakalar yetmez olmuş 

bir,bir 

art arda yakmış 

yanmış ciğeri 

adını garibin memed 

koymuş diğerleri 

ne ana kalmış 

ne baba 

ne de yadigar yengesi 

bebeler adam olmuş 

biri maliyede defterdar 

diğeri 

deniz teğmeni 

çıkardı tahta bacağını 

yılları gibi yanan ateşe atı verdi 

kuşağından çıkarıp tabakasını 

tütünü ateşe verdi 

mendiline sardığı madalyayı çıkardı 

dedi; 

'''' al bunu al kurban olurum 

herkese söyledim deli dediler 

ne ola da cesedim sancakla geleydi,, 

içim yandı 

kalktım divandan

izin istendi 

ne bitmez geceydi 

sabahın kuşluk vakti 

sala verildi 

ölen garbin memed di 

gün yarılamadan 

gömüldü kahır dolu 

bedeni', 'yıllardan arta kalan dilde kahır  bir de garibin memed di siyatikli bacak  tahtalı diğeri  titrek elinde tütün tabakası  üzeri Çin''ce işleme...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/garbin-memed-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim dur diyecek? ..', 'kim-dur-diyecek-yusuf-ziya-leblebici-qhyf1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yer kapmak uğruna birilerine yağ yakmış

Dinazorlar var koltuklarına çivi çakmış

Zorlu merdivenleri bir bir çıktıktan sonra

Dönüp utanmadan kendi tabanını  satmış

Haklarımızdan sav''anlar var iken bizleri

Kendini polat sananlar germiş bu çitleri

Kimi el tezgahında kendine bez dokurken

her geçen gün kopartır aradaki ipleri

Hangi sevi için gen''leri kıpırdar durur

Hangisi halk için ilkeli hakkı savunur

Koltuklarına zincirlenmiş bu dinazorlar

Yüzünüze gülüp de sırtınızdan vururlar.

Bir o yana bir bu yana yuvarlanan toplar

Elbet bir gün bizim ayağımıza da konar

Tavadan kazana yakılan düşünsel yağlar

Korkarım ki bir gün bizim pilava da sızar

Düşmana sorsan bizim düşmanımız kim diye

Sinsice gülüp bizi gösterecek eliyle

Halkçı olup da görmeyen varken içimizde

düşmana düşman demek de bizim neyimize? 

Güneş olan bir Deniz koymuşken önümüze

İdealleri boğacak  Deniz neye yarar? 

Halkız deyip halkça yaşarken halkın içinde

Dalgadan kopuk, susuz bir Deniz kime yarar? 

Gittiler diyelim, yerine kimler gelecek  

Bu zihniyet varken  bu böyle devam edecek

Toplar zıplayıp da, yağlar hala yanıyorken

Bu gidişe, bu haksızlığa kim dur diyecek! ..', 'Yer kapmak uğruna birilerine yağ yakmış Dinazorlar var koltuklarına çivi çakmış Zorlu merdivenleri bir bir çıktıktan sonra Dönüp utanmadan k...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kim-dur-diyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçilmez Öykü', 'vazgecilmez-oyku-ali-safak-bali-9mc68', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biçare garipler, çığlık çığlığa gömer sancıları yüreğine 

zira sözcükler her dem zehirdir ehil elde, sözcükler zulüm

her sessiz çığlıkla yeniden alevlenir yangın, külleceğine 

bil öyleyse, nasıl ve kimden gelirse gelsin, huzurdur ölüm

sadece gözü kapalı yaşanandır gerçek, mutluluk suskunlukta

ne şartlar girer araya, ne ruhlar başka sevdalara öykünür 

söyleyemeden anlattığın, duymadan çıktığın bir doruk nokta

gör işte, çaresiz kimsesizliğe rağmen, ne vazgeçilmez öyküdür', 'Biçare garipler, çığlık çığlığa gömer sancıları yüreğine  zira sözcükler her dem zehirdir ehil elde, sözcükler zulüm her sessiz çığlıkla yen...', ARRAY['Türk Edebiyatı','Şiir','Ali Şafak Balı']::text[], 8.5, '{"poet":"Ali Şafak Balı","poet_slug":"ali-safak-bali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vazgecilmez-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Depresif', 'depresif-vural-celiker-mzzgk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aynaya baktım uzamış saçlarım; 

Hem morarmış gözaltlarım..

Tadı yok eskisi gibi elmanın! 

Günler,dünleri özletiyor,

Tüm renkler birbirine giriyor; 

Sen bilirsin Doktor:

Yeşil reçeteki beyaz haplar iyi gelir mi geçmişime? 

Peki ya dağılır mı bulutlar? 

Hanidir hayatımdalar; bir yağmur verdiler bir de kar..

Gözlerimde daimi bir sonbahar..

Gülmeyi unuttum,aklıma gelmiyor..

Bir de adımı ki karakterime inattı:

En azından şirin bir addı! !', 'Aynaya baktım uzamış saçlarım;  Hem morarmış gözaltlarım.. Tadı yok eskisi gibi elmanın!  Günler,dünleri özletiyor, Tüm renkler birbirine gi...', ARRAY['Türk Edebiyatı','Şiir','Vural Çeliker']::text[], 8.5, '{"poet":"Vural Çeliker","poet_slug":"vural-celiker","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/depresif-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öksüz Bir Mektup', 'oksuz-bir-mektup-eren-sahin-y8igm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu Mektubu Hiç Dönmeyecek Birine Gönderiyorum; Bile Bile........... 

Gidiyorsun, peşinsıra martılarım gidiyor, çocukluğum Gidiyor, kalbim gidiyor beraberinde... Ellerim kalıyor Geriye titrek ve yorgun... 

Gidiyorsun, mevsimi bana zehir ederek... 

Paslanmış kadehte içiyorum yollarının tortusunu,sen Arkana bakmadan gidiyorsun... 

Ki ben kimsenin peşinden koşmadım durdurmak için; 

Şimdi sen gidiyorsun; ''gitme,kal ne olursun kal'' desem... 

Yalvarmak istiyorum... 

İçimdeki İsa geriliyor aşkının çarmıhına; 

Bilmiyorsun gerildikçe çakılıyor yüreğim yüreğinin tılsımına....... 

Gidiyorsun; gitme... 

Bak konuştum; GİTME! .. 

Derin bir maviye dönüşüyor sularım,içinde yalnızlığını kucakladığım... 

Gitme susakalırım çığlık çığlığa... 

Susuşum olma bu evren içinde; 

Dilim ol dola beni hayatın cehennemine... 

Gitme...yazık etme yaşanan senelere.......... 

Fırtınanın rotasına çizildim yollarına esiyorum, 

''dur'' diyorum, ''gitme''... 

Sen gidiyorsun... 

Altına alın teri, yürek sızısı dökülmüş şiirler gidiyor..... 

Gidiyorsun...sonsuz bir sonbahar uğurluyor paltonu.... 

Susuyorum... 

Biliyorsun... 

Seni bıraktığın sonbaharın altında bekliyorum bile bile gelmeyeceğini... 

Gidiyorsun, uğruna çileler çektiğim sevdiğim... 

Gençliğim gidiyor...... 

Elif... 

Lam.... 

Mim..... 

umut susar...sessizce bekler çocuk........', 'Bu Mektubu Hiç Dönmeyecek Birine Gönderiyorum; Bile Bile...........  Gidiyorsun, peşinsıra martılarım gidiyor, çocukluğum Gidiyor, kalbim gi...', ARRAY['Türk Edebiyatı','Şiir','Eren Şahin']::text[], 8.5, '{"poet":"Eren Şahin","poet_slug":"eren-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/oksuz-bir-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'G-özlersin Bilirim...', 'g-ozlersin-bilirim-muammer-celik-cx0wq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'G-özleyen gözlerini

G-özler gözlerim…

G-özünü

G-özüme saldığım…

BirDeli

08.06.2004', 'G-özleyen gözlerini G-özler gözlerim… G-özünü G-özüme saldığım… BirDeli 08.06.2004...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/g-ozlersin-bilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Rütbemsin', 'tek-rutbemsin-cem-veysel-gul-v0atm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin sadeliğin

Her seferinde umutlarımı kışkırtıyor,

Umutlarımsa beynime sığmıyor artık,

Beynimdeki bu sessiz düşüncelerin gürültüsü,

Kulaklarımdan dışarı çıkıp,

Beni ele verecekmiş gibi korkutuyor.

Korkuyorum çünkü

Hücrelerimdeki bu sesler,bu gürültü

Seni sevdiğimi haykırıyor,

Hücrelerimin koşusturması,

Geleceğimizle ilgili planlarımı anlatıyor.

Yani seninle beni,

Ortak dünyamızı anlatıyor bu sessiz sesler.

Hayat o kadar acımasızki,

Hem sevmeyi öğretiyor insana,

Sevdirmemek içinde engeller çıkarıyor.

Hani dünyada her şey dengeli

Benim için bu dengesizlik niye? 

Bu sesler beni çıldırtacak

Bu sessiz sesler alıp uzaklara götürüyor beni

Ya bu sesleri dinleyip sevmeye devam edeceğim,

Yada kendi kendimi yiyip bitireceğim.

Hani her biten bir sevda için 

Bir yıldız kayar derler ya

O kayan yıldızlardan olmayacağım.

Veya o yıldızları rütbe mahiyetinde takmayacağlm,

Zaten rütbeye ne gerek

Benim tek rütbem ve yıldızım sensin.

Yani ben sana vurgun sen bana aşıkken

 Bu çılgın sese kulak verip

Seni sevmeye devam edeceğim.

Bu aşkın; 

Kayan yeni bir yıldız olmasına izin vermeyeceğim.

Seni sevmeye devam,

Seni seviyorum sevgilim...

                       Cem Veysel Gül

                       04/02/2004....saat:15:06

                        Cafe Spielplatz/Gmünd/Deutschland', 'Senin sadeliğin Her seferinde umutlarımı kışkırtıyor, Umutlarımsa beynime sığmıyor artık, Beynimdeki bu sessiz düşüncelerin gürültüsü, Kulak...', ARRAY['Türk Edebiyatı','Şiir','Cem Veysel Gül']::text[], 8.5, '{"poet":"Cem Veysel Gül","poet_slug":"cem-veysel-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/tek-rutbemsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mısramı Daha Vur..', 'bir-misrami-daha-vur-tulay-eker-6fyt7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne zormuş...

Ayrılığın tuzuna banmak

Namlunun ucunda çırpınmak

Yarin goncasına hasret ekmek

Yalnızlığın sırtında bıçak bilemek..

Dilimin sustuğu yerde sevdayı damıtmak

Şehrimde ölümsüz yanımdan vurulmak..

Ne zormuş sensizlik sonrası..

Çayımın şekerinin azalması

Dudağımdaki izi sigaramın yakması

Kısır gülüşlerimde mezar açmak yaşıma

Yıldızları alıp koynuma sarılmak akşamlara

Nefeslerimin derinliklerine seni içime çekmek 

Sonra..sonrasında,yokluğuna sarılmak üşümek

Dünüm,

_ Bugünüm

 __   Yarınımsın

 ____      Uzaksın...

Bak şimdi..

Sevgimi yüreğime uzun hava yaptım

Yokluğuna ağıtlar yaktım

Düğümler attım matemlerime,her düğümde yandım

_______Dilim ağlıyor

Kimse duymuyor

_____Sensizlik ertesi

Nefeslerimin en karanlık demi.

Haydi durma..

____________Bir mısramı daha vur!', 'Ne zormuş... Ayrılığın tuzuna banmak Namlunun ucunda çırpınmak Yarin goncasına hasret ekmek Yalnızlığın sırtında bıçak bilemek.. Dilimin sus...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-misrami-daha-vur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül mü Kaldı', 'gonul-mu-kaldi-caner-kuru-l3qot', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her yanımızı kin, nefret bürüdü

Aşka değer veren gönül mü kaldı? 

Kötülük başını aldı yürüdü

Aşka değer veren gönül mü kaldı? 

Her yanda örülü kaderin ağı

Kopuyor insanın hayata bağı

Gösterin sımsıcak bir sevgi bağı

Sevmesini bilen gönül mü kaldı? 

Hep çıkar gözetmek tek yol, tek usul

Kimin umrunda ki, ağlıyorsa kul,

Şimdi varsa yoksa; şöhret, para, pul

Aşka değer veren gönül mü kaldı?', 'Her yanımızı kin, nefret bürüdü Aşka değer veren gönül mü kaldı?  Kötülük başını aldı yürüdü Aşka değer veren gönül mü kaldı?  Her yanda örü...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-mu-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Olmak Kolay Şey', 'asik-olmak-kolay-sey-ahmet-yetgin-rum69', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkın da bir kuramı var, bir tarihçesi

metabolizması, mevsimi, hormonları

Verimli toprakları, aşkın bir ülkesi var

aşkın çölleri var, ve ormanları

Aşık olmak fidan dikmek gibi bir şey

nasıl her güzel şey hak ederse emeği

sulamak, çapalamak gerek; uğraşmak

Ama her asit yağmuru yıpratır sevgiyi

Aşık olmak kolay şey

zor olan yaşatmak...

Ne kadar bilirsek canım

o kadar iyi.

Fotoğraf albümleri var beynimizde

Her resimde hüzün

fonda kuru yapraklar

Acılar, acılar ve acıtıcılar

ve hep sonbaharın solan rengi

Varolmak başlı başına trajedi

Hangi derinlikte yaşarsak

öyle kazınır izi

Aşık olmak kolay şey

zor olan yaşatmak...

Ne kadar gülersek canım

o kadar iyi.

Limon çekirdeğine sığmaz meselelerden

Ceviz kabukları kırmak

Farkında olmak kahrolasıya

Kıskanmak

Çıldırmak, çıldırtmak

tüketmek belleği

Aşık olmak kolay şey

zor olan yaşatmak...

Ne kadar delirsek canım

o kadar iyi.

İnsan kaç kere aşık olabilir

ya da kaç kere ölünür hayatta? 

Gecenin bir yarısı

ter boşanır bölünen uykularına

Ve her yeni gün yeni bir ümitle 

yeniden başlarsın yarım rüyalarına...

Yarı ölülerle kumar

Dünya bir laboratuar

Hayat, ölümden yaşam

yaşamdan ölüm damıtma deneyi

Kirlenmemiş ruhlar için

aşık olmak dünyanın en kolay şeyi

Zor olan yaşatmak

ölmek pahasına da olsa yaşatmak...

Ne kadar ölürsek canım

o kadar iyi.', 'Aşkın da bir kuramı var, bir tarihçesi metabolizması, mevsimi, hormonları Verimli toprakları, aşkın bir ülkesi var aşkın çölleri var, ve orm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yetgin']::text[], 8.5, '{"poet":"Ahmet Yetgin","poet_slug":"ahmet-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/asik-olmak-kolay-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikenli Tel', 'dikenli-tel-emre-oguz-hb84f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I

Aşka kaçardi şiirler 

Çocukken.

De ki; 

Huzur

Bayramlık ayakkabının içinde saklidir

Ezilmiş

II

 Aşka kaçardi resimler

Anneler, babalar

Ve balonlar

Aşka kaçardi 

Resimlerde

III

De ki; 

Olur olmaz duyduğum

Bu ölü sözler

17 yaşımın toyluğu

Kulağıma fısıldanan ezan, sır

Ve ıslandığım rahmet

Aşk değil

IV

De ki; 

Ergensin.

Ne yaprağın yeşil

Ne suyun berrak

Kanın deli akar.

Hayatın şah damarından

V

De ki; 

Şaşı bakar adama

Duvarlarımda boy boy yükselen 

Cinnet

Ve omuzlarıma abanan  bu

İlahi sir

Aşk değil

VI

De ki; 

Bir aldanıştır bu

Otuzunda bir adamın

Kanayan parmakları

Ve mucize

Yalandir.

VII

Uzun koridorlarda

Ağlamak düşmüştür

Mağrur bir fahişenin

Payina 

De ki; 

Gözyaşı ve

Aklımı çalan ziya

Aşk değil

VII

Bir yağmur sonrasi

Ufuklara salarsın ruhunu

Ve akıl; 

Dikenli telidir hayatın

Atmişında

VIII

De ki; 

Şakketti ömrün

Baba olacak yaşta

Hala

Bir damladır yaşamak gözlerinde

Akamayan

IX

Sıkı sıkıya tuttuğun

Son nefesidir

Ezdiğin ve ezildiğin 

hayatın', 'I Aşka kaçardi şiirler  Çocukken. De ki;  Huzur Bayramlık ayakkabının içinde saklidir Ezilmiş II  Aşka kaçardi resimler Anneler, babalar Ve ...', ARRAY['Türk Edebiyatı','Şiir','Emre Oğuz']::text[], 8.5, '{"poet":"Emre Oğuz","poet_slug":"emre-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/dikenli-tel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamın üstünde', 'aksamin-ustunde-i-lker-ozluk-nhfq7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akşamın üstünde yürüyorum. Elimde sarhoş bir mektup okudukça sızıyor cümleleri. Sadece gözlerin parlıyor yüreğimde, bir kuğuyu okuyorum sonra, kanatlarını çırpıyor berrak sulara, ben okudukça ağarlaşıyor ben okudukça sızıyor hayatın temizliğinde, bir çoban geziyor sürü sürü, kavalı ile, kanlı canlı canları ile, okudukça duruyor yavaşlıyor tüm heyecanı, uyukluyor kavalının sesi, sızan bir gölgenin canlı bedenine yaslıyor kendine, sonra bir yaprak kımıldıyor dalında, okudukça düşüyor ağır ağır, bir lodosa bir poyraza vura vura keseliyor rüzgarı, bir yanı düşüyor bir yanı yeşil, toprak kokuyor hala okudukça sızıyor mis gibi toprakta. Elimde sarhoş bir mektup, hayatın en renkli yerinde, bal olan bal arıları gibi okudukça sızıyor hepsi, sonra kelebekler çıkıyor içinden, her biri ayrı renk okudukça sızıyorlar aynı zamanın içine rengarenk, içinde bir bahar gelin gibi geziyor. Okudukça önce duvağını sonra kendini seriyor papatyalar gibi, ağır ağır sızıyor hayatın kokusuna, içinde aşktan kalma mevsim dolaşıyor her yüreğe vura vura, aşktan kalma güller dökülüyor her bir yanaktan, her bir söz üşütüyor bedenleri, okudukça titriyor hepsi, okudukça sızıyor kapatıyor elleri ile yüzünü. Gözlerin parlıyor içinde, sesin tane tane yayılıyor, dudağında hüzünlü bir şarkı kendini ıslıklıyor, saçların dolanıyor rüzgarın içine, içinde biri el ele kucaklıyor güneşi, rüyaların roman oluyor. Sonra okudukça sızıyorsun  mektubun en sıcak ve yeni yanmış köşesine. Tam beni anlatıyor ki bende sızıyorum senin yanıklığına. Akşamın üstünde yürüyorum. Çocukluğum geliyor koşarak, bana yetişmek için derin derin nefes alıyor sadece, bağı çözülüyor dizlerinin, bir düşüyor akşamdan, bir kalkıyor sabahtan, tatlı olan tatlı şeker gibi, cebinde bir resim seni çiziyor hala. Tıpkı balıkçı teknelerinin boyası gibi. Akşamın üstünde büyüyorum. Aslında üşüyorum içimde bir rüzgar seni savuruyor, yarım yamalak bir aşkın serseri bakışları gibi. Bir masal gibi büyüyorum küçük bir çocuğun gecesinde, büyüyorum sana kadar. Sen elim ayağım olana kadar. Akşamın üstündeyim. Yanımda gündüzden korkan her şey var, ağaçlar, çiçekler tıpkı kendi mahallesi gibi oynaşıyorlar kendi aralarında, seni beni kovalar gibi, akşamın üstündeyim. Üstümde üşüyen bir hırka, yanımda senin sıcaklığın, telaşında büyümüşüm sana kadar, uzanmışım öylece, öylece donakalmışım işte. Akşamın üstünde akşam üstü bir zamanım işte. Yanımda olması gereken kadar sen varsın işte, hiçbir evin penceresi açık değil yanımda, ben ne zaman çıksam akşam üstüne, sonunda sızıyorum işte...senin Akşam üstünde...', 'Akşamın üstünde yürüyorum. Elimde sarhoş bir mektup okudukça sızıyor cümleleri. Sadece gözlerin parlıyor yüreğimde, bir kuğuyu okuyorum sonr...', ARRAY['Türk Edebiyatı','Şiir','İlker Özlük']::text[], 8.5, '{"poet":"İlker Özlük","poet_slug":"i-lker-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/aksamin-ustunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazsam mı? ..', 'yazsam-mi-i-lker-ozluk-f8b80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni nereye yazsam bilemiyorum, ne zaman dursan karşımda tüm cümlelerim tutuşur oluyor, eline not sıkıştırdığım bahar epey oldu gideli, sen açmazsan kendini, başka çiçeklerde solarım akşamları, kök tutmaz bedenim, yüzümü kıra çalmaz benim, acırım, kokunu yayarım her bir tarafa da, sır olur gecenin karasıyımdır. Her bir yana dağılır hasretim, her yerde sen, içime çekerim, derin derin gelirsin  nefesime, o kadar çoksundur ki, iğne atsam düşmez yere,  yüreğimi yaktın ya benim, gecenin ateşi oldu içim, her baktığında, her açtığında perdeni, camının önünde söndürdüm kendimi, öyle buruşuk, öyle yeni yıkanmış gibi asarım kendimi, ne zorum var bilmem ama, sen gelmezsen ben solarım kendimi. Yalın ayak gezer toprak, yalın çıplak bir gece gölgeler kendini bedenimde, her elini tuttuğumda bir gemi dalgalandırır beni, her şafağın sahibi gibi gezer rüyalarım, bir benim hayalim tutar mayayı, bir benim hayalimde iki sevgili, bir beni gezdirir zaman, bir seni görürüm deli, bir aklım başımda değildir benim, yürürüm çamurlu gözlerinin en balçık gölcüğünde, su ister yanarım, gece sigara yakar üzerimde, yine de önce ben sönerim, seni kesmez bu aşk, ne kadar susuz içsen de kar etmez gece, eline gözüne dolarsın sarhoşluğu, ben yine duramam sabaha durduğum gibi. Seni nereye yazsam bilemiyorum, mürekkebim dökülüyor dilimden, elimden geliyorsun çağlayarak, gözümün ucuna satır başı çekiyorum karadan, kara gözlü, seni nereye yazsam bilemiyorum, bahanelerimi döküyorum ardından yolunu kısaltmak için, bazen kendim dökülüyorum heyecanla, ne zaman toplasam her defasında eksiliyorum, senin adında su yolu, senin adında yağmur ve senin adında traşlı kalem, nereye yazsam, peşim sıra diziliyorum, seni nereye yazsam bilemiyorum. Sana ne zaman acıksam tokluğumun şiirleri geliyor aklıma, ve ismini görüyorum, eski Türkçe’nin nakışlı kitabında, bir çocuk gibi büyüyorsun, her yıl, her saat ve her dakika, koşarak özlediğim sokaklar gibi, sokak dediğim de, bir kadın gibi sahici, sokak dediğim de, bir erkek gibi gerçek, sokak dediğime bakma, bir aşk gibi tekme tokattır gecenin karasında, nereye vurduğu belli değildir, bir yanak kızarır, bir yürek yarar kendini, sokak dediğim deli ve doludur böyle, iğne atsam düşmez yere, sokak dediğim senin gözünün karasıdır aslında. Seni nereye yazsam bilemiyorum, onun için terk-i diyarın kervanında geziyorum, seni nereye yazsam bilemiyorum, aklıma geldikçe… seni nereye yazsam orada olacağını biliyorum, seni bu yüzden, nereye yazacağımı bilmiyorum…', 'Seni nereye yazsam bilemiyorum, ne zaman dursan karşımda tüm cümlelerim tutuşur oluyor, eline not sıkıştırdığım bahar epey oldu gideli, sen ...', ARRAY['Türk Edebiyatı','Şiir','İlker Özlük']::text[], 8.5, '{"poet":"İlker Özlük","poet_slug":"i-lker-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/yazsam-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesinin geldiği tarafa doğru', 'sesinin-geldigi-tarafa-dogru-i-lker-ozluk-ch70p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sesinin geldiği yerleri dinliyorum.

En derin ve sonsuz nehirler gibi.

Rakım''ı fazla olan, dağlardan akıyorsun,

En kuru gölgelerime.

puslu bir baharın, yalın ayak kıraa''ları gibiyim,

Senin yürüdüğün yolları, üşüyorum aslında.

Elini tuttuğun fidan gibi büyüyorum.

Ne yana baksam sen varsın aslında, hep sen olunca,

İlker''i buruşturup atıyorum bir yana,

Bir yanda adın, ben büyüyorum aslında.

üzdüğüm zamanları dövüyorum, dalgalarla.

yüz yaşında, yüz yerinden,

üstümde değil nasıl durayım.

Yürüyorum öyle,

Orta yaşın telaşlanan gölgesi gibi,

Rüyalarım seni görüyor hala

Ulu orta çiçekler gibi

Masum; bir rengi gözlerinin ucuna sermişim, dalgalar var kenarımda, ben aslında seni büyüyorum gecenin bir kıyısında, anlayacağın geceye karıştırdık yine kendimizi, artık tüm ışıklar, yüzüme vuran nazik bir rüzgarla ışığı azalan mumlar gibi sönüyor, bir müzik kutusunun üzerinde gibisin eflatun kıyafetinle bacakların bitişik, parmak uçlarında öylece yakalamışsın sonsuz sessizliği, ben seni büyüyorum en terbiyeli oyuncaklarla, sükut bbenim adımlarımla yürüse bile çiçeklerim solmuyor benim, şimdi trompetler senin ve benim için çalıyor, güneşin geldiği yoldan ilerliyorum, ben işin aslında seni büyüyorum hep, her ağacın gölgesi benim, her dalın meyvesi, her derenin balıkları, sevginin yüzüme vurduğu yaştayım ben, senin baktığın yaşta değil, senin küstüğün yerdeyim ben, seni büyüyorum dedim ya kendimce, orta yaşın gece karanlığında, her yerim ateş böceği, ışıklı yapraklar gibi, seni koşup, seni yoruyorum aklımın seyirinde, her bir yere dolaşıyor ayaklarım, içimde karadüzen sürekli sana demirliyor kendini, ne yana baksam dağ gibi çöküyorum işte, ben hala seni büyüyorum, yorgun denizin küçük yaşta teknesinde, her liman kulaklarımı çınlatıyor benim, ben sağarın oluyorum senin gürültünde, ben seni kokuıyorum bataklığın ortasında, nanelerim dökülüyor her çamura, ben yine seni büyüyorum işin aslında, içimde bir süvari seni taşıyor her yeni zamana...', 'Sesinin geldiği yerleri dinliyorum. En derin ve sonsuz nehirler gibi. Rakım''ı fazla olan, dağlardan akıyorsun, En kuru gölgelerime. puslu bi...', ARRAY['Türk Edebiyatı','Şiir','İlker Özlük']::text[], 8.5, '{"poet":"İlker Özlük","poet_slug":"i-lker-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sesinin-geldigi-tarafa-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahalleli işte', 'mahalleli-iste-i-lker-ozluk-nnb8b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabahın sarhoşluğuna denk geldi, kimisi uyanık, kimisi hep dinlerdi… hepsi arkadaşımdı aslında, hepsinin rakısı sandığın üzerindeydi. Ne güzel kesmiş peyniri bizim bakkal efendi! ...ip gibi, kendi ipiyle. Aynı ipte üç yıldız, denizin parlak serinliğinde. Hepsi arkadaşımdı mahallenin çocuğu… kimisi gözünü kaçırırdı konuşurken, kimisi konunun içinde dinlerdi kendiliğinden, kiminin de sevdalısı vardı mahalleden, hep bir mahalleydi aslında içimizden geçen. En ince şiiri severdi bizimkisi, sazın en ince telinden geçerdi okurken, içinde mahallenin en güzel kızı gezerdi, arada birde kendi gezerdi, neden gezdiğini kimseler bilmezdi, biz ona bekçi misin? Derdik. Ama o yinede durmaz gezerdi, biz ne zaman of çeksek, o hemen başka bir şiir seçerdi, içinde  Feraye hepimizin gönlünden geçerdi, ne mahalleliydi, nede bey kızı biz sadece onu içimize çekerdik. Bizim mahalle böyle girerdi işte sabahın geç saatlerine. Aramızda birde göçüp gidenler vardı, helva almaya diye çıkarlardı yola, kendileri hiç gelmezdi ama helvaları gayet güzeldi. Arada birde, seher nine gezerdi sokaklarda, elinde gümüş bakır taşırdı hep, içinde bulgur, biraz umut ve göz yaşı olurdu sıcak sıcak, ne meze olurdu bize, nede düşünmeden geçerdik mevzuatı, hazır yanımızdayken deniz, öylece yelkenlerdik dertlerimizi, belki ufku açılır diye. Açılırda bizde saçılırız diye… mahalleli erken inerdi düşünceye, erkenden sandıklar dizilirdi bir köşeye, bakkal İsmail, kasap recep, birde kitapçı Ruşen yakarlardı geceyi, bizim bağrımız gibi açılırdı tül perdeler, hepsi gelinlik, hepsi gerçekten severdiler. Birde bizim reisler, balığı ilk icat edenler, hep komik şeyler söylerler, ama sadece kediler gülerdi. Biz ne zaman gülsek bizim 

Sandıkta balık biterdi. Bir efkar türküsü söylerdi içimizden birisi, bütün mahalle dinlerdi. Bizim mahalle, düşüncelere hep geç inerdi … kiminin yalanı yatsıya, kiminin ki sabaha kadar sürerdi, kimide yaşadığı hayatı yalan diye söylerdi, ışıklar bile fakirdi, bir yanar birde sönerdi, işte böyle bir mahalle tıpkı deniz kıyısında fener gibi. Bizim mahalle erken inerdi düşüncelere,  inerdi yedi cihanın masum türküsü yüreklere, dışarıda, umut, kimse okuyamazdı mektuplarını, başlardı gece devriyesi bekçi Mehmet’in, bir düdük yatıyorduk, bir düdük kalkmıştık zaten, işe kaldırıyordu mahalleliyi, çalışmak sevda gibidir. Diyordu, bir tek sevdası da buydu aslında, çocukların topunu keserdi bazen, sonra dayanamaz birde maaşını keserdi acımadan, içinde sevgi, aslında o da bizim mahalleden. Böyle bir mahalle işte bizimkisi, kusura bakmayın sabahın sarhoşluğuna denk geldi, kimisi uyanık, kimisi hep dinlerdi. Hepside arkadaşımdı, sandıkta rakı da biterdi, mahallede gecede, yarım hayalli düşerdi boyunlarımız, sevgiler umutların içinde öylece giderdi. Bizim mahalle yarına erken girerdi… 

19-05-2004 (başka bir mahalleden) …', 'Sabahın sarhoşluğuna denk geldi, kimisi uyanık, kimisi hep dinlerdi… hepsi arkadaşımdı aslında, hepsinin rakısı sandığın üzerindeydi. Ne güz...', ARRAY['Türk Edebiyatı','Şiir','İlker Özlük']::text[], 8.5, '{"poet":"İlker Özlük","poet_slug":"i-lker-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/mahalleli-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pa-pat-ya', 'pa-pat-ya-rukiye-sadol-vvxys', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgiliye beyaz papatyayi verdim; sonu seviyor cikan

günes gösterdi sariyi, yaparaklar fisildasti cilveli, kuslar ucustu

heyecanli

hepsini gözleri ele verdi

kendince yasarken benden olsun diye

Sevgiliye beyaz papatyayi verdim; sonu sevmiyor cikan 

bulutlar esmeri sahiplendi, sonbahar susdurdu yapraklari, perde oldu yürege

sis

hepsini gözleri ele verdi

kendince aglarken benden ciksin diye

Sevgiliye beyaz papatyalari verdim

ask adinca yasansin diye; 

Isimsiz sonlari olan kirmizi.', 'Sevgiliye beyaz papatyayi verdim; sonu seviyor cikan günes gösterdi sariyi, yaparaklar fisildasti cilveli, kuslar ucustu heyecanli hepsini g...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Sadol']::text[], 8.5, '{"poet":"Rukiye Sadol","poet_slug":"rukiye-sadol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/pa-pat-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hokus Pokus', 'hokus-pokus-tolga-akturk-g4u6g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir eski zaman tüneli çocukluğum 

Ta geçmişe uzanan

Ellerimde kır çiçekleri 

Eskiyi unutmak zor olan.

Bir ıssız ada hikayesi çocukluğum

Kaç gemi batmış yakınında,

Kaç kişi boğulmuş kıyısında.

Bir eski zaman tüneli çocukluğum 

Gözüm hep arkada.

Bir yaşam kavgası çocukluğum

Elimin kiri, hayatımın son filmi.

Eski bir fotoğraf çocukluğum 

Siyah beyaz ama yepyeni.

Kapkara gecelerden umut koparıp geçen

Düşleri sınırsız bir derin uyku çocukluğum,

Güneşi merak etmeyen en son gün,

Gözleri ışıl ışıl bakmaya kıyamadığım

En son bakış çocukluğum.

Son nefesin çığlıkları 

Heder olmada hayatımın en güzel yılları.

Geçmede zaman, keman susmada, kemancı sus pus.

Çal be kemancı çal 

Bu son kabus.

	

Bir eski zaman tüneli çocukluğum 

Herkese,her şeye

				HOKUS POKUS! ! !', 'Bir eski zaman tüneli çocukluğum  Ta geçmişe uzanan Ellerimde kır çiçekleri  Eskiyi unutmak zor olan. Bir ıssız ada hikayesi çocukluğum Kaç ...', ARRAY['Türk Edebiyatı','Şiir','Tolga Aktürk']::text[], 8.5, '{"poet":"Tolga Aktürk","poet_slug":"tolga-akturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hokus-pokus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aça-69 (Syk-4b)', 'aca-69-syk-4b-akin-akca-arghq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ÖRÜMCEĞİN GÖZLERİNDE

Oraya doğdum, mekansız bir vakt, ama

Vakt, zamanın olmadığı hiçbir yerde

Fakat zamanın içinde, kaleidoskop dışı da:

Bir ‘photon’ gibi,olmayan anti parçacığı; 

‘Sınırsız genişleyen’ bir şey cenkleşiyor

(Kendisi belli, düşmanı belli, hayat) 

Evren ile, bir balon gibi, sabit çevresi.

Söylemeye balkon serenatçıları başladı şarkı, gıcırdattğında telleri bir kemancı, tek, damdaki.

Birey’i toplum yapar ama uzlaşıcı; kendi giden gider, on defa düşeş düşen zar senfonisinde 

Yalpa verme korkusunun

Hayata düştüğü an

Açılan o kuyu, bucaksız,

Pek insafsız..

Karabasanlar doğaçlayan

Dikey eğrisinde

Düşüşün..

Aynadan içre,

Namütenahi

Sonluluğa

… Değil iki,

(Tamamlanmış

Gide-duran’ında

Durağan ya da ‘o olmayan’) 

Bir.

Bu kadar kendinden emin olma ‘nihai çöküş-takdir ulağı-Avalon’:

Baharlar açar çiçek, sonra kış aylarından,nice; ama değildir de

Bu bile, onu kendi kendisiyle yoğuran.

                                                   

                                                               

                                                                 

                                                         

                                          

                                         

Yeterliyse gece, ki gecedir aydınlığın hali, üzgün:

Seviş benimle.

Ama tutuşmasın çırpı, çalı: bitli bir düşüncenin malı, sadece tutuşan döşek, yorgan:

Öyleyse yanalım biz: Biz yanalım; değil sen, değil ben.

Ateş başınca atılan tokadın eli tutulur ‘yanmayan tortu tutmamış 

Gerçek olmayandan’.

Kar suyuna basılır bu ateş haspası-köz, 

Canlandırmak daha adına körüklenenin.

Seksin yetiştiği noktayı sayarsan kendine, ele bulaşmış kan ve kir: 

Çocuklarda kuş,ağaçlardaki dal; 

Konar kuşlar buraya, çocukların çektiği ağaçları; uçurtma

Taktığın allığı neden şallığa sürmüyorsun üzerindeki.

Düşer maske de açıklarlar sana, 

Kurulan düzeneğin barındırmayışını hata.

Kemiklerdeki kalsiyum, oksijen soluduğum:

Belki dersin her şey yıldızlarla başlamadı:

Milyonlarca yıllık hidrojenin bulutu kalıntısı değildir

Dersin belki de bulutların içinde gerçekleşen mucizeye.

Bunun oluşturduğu girdaplar ve dalgalanmalar da

“Denizin şoku değildi” diyebilirsin:

Ama daha da fazla emilenin dev hidrejen 

Bulutları oluşturup etraflarında refleks verişini,

Açıklamak zordu oluşumunu

Gökadalar doğdu ve sonra yıldızlar 

Bir kedinin basarlar kuyruğuna ve o sıçrar

Kötüsünde akıl vardır insanın kullanmaz; 

Bir tane kedi bile kuyruğuna basılmadan üzerine atlamaz.

--

son üç satır için ilham doğaçlayıcı Güneyden can dostuma teşekkürler

Sam Neill’in sunu’sunu yaptığı BBC ‘Space (Uzay) ’ belgeseline de,

ilham verme açısından, kısa katkılarından dolayı teşekkürler', 'ÖRÜMCEĞİN GÖZLERİNDE Oraya doğdum, mekansız bir vakt, ama Vakt, zamanın olmadığı hiçbir yerde Fakat zamanın içinde, kaleidoskop dışı da: Bir...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/aca-69-syk-4b-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceviz - Beyin', 'ceviz-beyin-metin-kose-sqzv2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağaçtaki cevizin

Yaprağı nasıl kokar

Ellerinle açarsan

Eline kına yakar

En dıştaki o yeşil

Sanki kafa derisi

Meşe kadar sert olur

Kabuğundan gerisi

Hazine saklar gibi

İçteki ince zarı

Kırmadan çıkarırsan

Bir beyin’dir tamamı

Daldaki yeşil ceviz

Bir beyin biçiminde

Beynin gümüş iyonu

Yalnız ceviz içinde

Nasıl bir oluştur bu

Hep gerçeği aratan

Koskoca bir dünyayı

Bir cevizde yaratan

Ankara				 

(8 haziran 2004)', 'Ağaçtaki cevizin Yaprağı nasıl kokar Ellerinle açarsan Eline kına yakar En dıştaki o yeşil Sanki kafa derisi Meşe kadar sert olur Kabuğundan...', ARRAY['Türk Edebiyatı','Şiir','Metin Köse']::text[], 8.5, '{"poet":"Metin Köse","poet_slug":"metin-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ceviz-beyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Özleminle Boş Koridorlarda...', 'ben-ozleminle-bos-koridorlarda-mehmet-seyidhasanoglu-zxjxb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şafağında martılar uyandırır; şehrimin! 

Gelecek olan geceyse, günün ardından; 

Günlerim; şenlik havasında,

Gecelerim ise; sen tadında! ....

Ben ve sevdam burada,

Sen ise; sevgimden habersiz uzak diyarlarda,

Ben, yine özleminle boş koridorlarda.....

                                       28.04.2003

                                      Gevaş / Van', 'Şafağında martılar uyandırır; şehrimin!  Gelecek olan geceyse, günün ardından;  Günlerim; şenlik havasında, Gecelerim ise; sen tadında! .......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Seyidhasanoğlu']::text[], 8.5, '{"poet":"Mehmet Seyidhasanoğlu","poet_slug":"mehmet-seyidhasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ben-ozleminle-bos-koridorlarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Horoz Şekeri', 'horoz-sekeri-ebru-delice-ulcxg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çocukluğumun ilk kahramanı

tornet sahibi,

topal Temel abi

tornet gezileri

horoz şekeri

bir de kağıttan uçurtmalar

bir sokak arasında; 

ne olduğunu anlamadan

gençliğinin ilk çağında

solcusun diye

vurdu  seni

çocukluk arkadaşın...

.................

ne zaman horoz şekeri görsem

tornetinle sen gelirsin usuma

hayal, meyal

bir yumru düğünlenir boğazıma

gözlerime buğu..

yutkunamam...

bir daha; horoz şekeri

yemeden büyüdüm ben

ve sevemedim sağımı

hep sol yanıma dönmem ondan', 'çocukluğumun ilk kahramanı tornet sahibi, topal Temel abi tornet gezileri horoz şekeri bir de kağıttan uçurtmalar bir sokak arasında;  ne ol...', ARRAY['Türk Edebiyatı','Şiir','Ebru Delice']::text[], 8.5, '{"poet":"Ebru Delice","poet_slug":"ebru-delice","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/horoz-sekeri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolunay Kalbinde...', 'dolunay-kalbinde-bahtiyar-orhan-ha7qd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne zaman çıksam yarıyollara kapanır bütün ufuklar 

içimde dolunaylı yakamozlar 

gözlerimde mevsim renkleri 

kim bu ismi seslenecek 

kim seyirtecek gözlerini benden 

hangi adımda tökezleyeceğim sana 

neden sorular bu kadar fazla 

ve neden cevaplar hep asılı kalır gri bakışlarda 

kaç imgeyi kaybettim asılsız aşklarda 

şimdi yürüsek bu yağmurları 

adlarını bilmemize gerek yok ıslandığımız sokakların 

kelimelerin boynuna sarılsak 

içimizi açsak yabancı soluklara 

ki kaç yolculuk başladığı yerde biter 

kaç aşk dolunay olur kalbinde...', 'ne zaman çıksam yarıyollara kapanır bütün ufuklar  içimde dolunaylı yakamozlar  gözlerimde mevsim renkleri  kim bu ismi seslenecek  kim seyi...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Orhan']::text[], 8.5, '{"poet":"Bahtiyar Orhan","poet_slug":"bahtiyar-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dolunay-kalbinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Nakışım', 'hayat-nakisim-unal-yuzer-qqnok', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllardır düşlerimde büyüttüğüm

Bir sır gibi sakladı seni gece.

Geldin sonunda, yanımdasın, yüreğimde...

Gecemin kutup yıldızı,

Günümün güneşi,

Gönlümün sultanısın.

Ağır seviyorum seni

Biliyorum sende beni seviyorsun

Hele bir bakıyorsun,

Eriyorum, yeniden aşık oluyorum

Eşsiz, zümrüt gözlerine

Hele bir de yokluğun çökmezmi

Bir an olsa bile özlüyorum seni,

Bir an bile olsa yanıyorum hasret yangınlarında

Hiç bırakma beni yalnızlığına.

Yanımda kal Zümrüd-ü Anka''m

Yaşayalım bulutların üstünde,

Yaşayalım sevdamızı,

Paylaşalım hayatımızı,

Yüreğimiz sevişsin her daim,

Tükensin ömrümüz avuçlarımızda.

Aşkınla can bulan kalbim

Boş kalmasın hiç bebeğim

Seviyorum çünkü seni, özlüyorum.

Sen, hayatımın anlamısın,

Yaşanılası sevdamsın

Yani ömrüm, yani korkularımı yenişim.

Sen, zulamdaki hasretsin

Yani, yokluğunda gurbetlenişim, yani özleyişim

Sen, durgunluğumsun

Yani, öfkelerimin eceli, yani bekleyişim

Sen, gönlümdeki kadınımsın

Yani, namusum, helalim, yani her şeyim

Sen, yaşanılası sevdamsın

Ve ben seni seviyorum HAYAT NAKIŞIM...', 'Yıllardır düşlerimde büyüttüğüm Bir sır gibi sakladı seni gece. Geldin sonunda, yanımdasın, yüreğimde... Gecemin kutup yıldızı, Günümün güne...', ARRAY['Türk Edebiyatı','Şiir','Ünal Yüzer']::text[], 8.5, '{"poet":"Ünal Yüzer","poet_slug":"unal-yuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hayat-nakisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Benim Aşkımdı', 'o-benim-askimdi-i-lyas-ozmen-j879g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiden bihaber kalbi demirden

O benim aşkımdı o benim sevdam

Sırtımdan vurup da ellere giden

O benim aşkımdı o benim sevdam

Ellere gül idi bana da diken

O dalga geçerdi ben sever iken

Alaylı,alaylı arkamdan gülen

O benim aşkımdı o benim sevdam

Ellerin kolunda aşkım hevesim

Mutluluk oynayan renksiz bir resim

Yüzünde anlamsız sahte tebessüm 

O benim aşkımdı o benim sevdam

Ellere bal şeker bana bir zehir

Gururum kırıldı başım eğilir

Son sözümdür ona kendisi bilir

O benim aşkımdı o benim sevdam

Gülerken ağlatan bir çatık kaşlı 

Bakarken öldüren acı bakışlı

Gördüğünü seven maymun iştahlı

O benim aşkımdı o benim sevdam

O kötü talihim o kara yazım

İçimden çıkmaz dert yürekte sızım

Başımın belası gönül hırsızım

O benim aşkımdı o benim sevdam', 'Sevgiden bihaber kalbi demirden O benim aşkımdı o benim sevdam Sırtımdan vurup da ellere giden O benim aşkımdı o benim sevdam Ellere gül idi...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-benim-askimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soruyur Seni', 'soruyur-seni-i-lyas-ozmen-b777v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidişinle tadı tuzu kalmayan

Sabahlar akşamlar soruyor seni

Seninle birlikte batıp doğmayan 

Güneşle yıldızlar soruyor seni

Bize sırdaştılar gündüz ve gece

Onlarda gülerdi yüzün gülünce

Parkta duruyorlar şimdi garipçe

Banklarla masalar soruyor seni

Hani oradaydı ilk tanışmamız

İlk defa küsmemiz ilk barışmamız

El ele göz göze dolaştığımız

Sahiller kumsallar soruyor seni

Eğik geziyorum başım önümde

Diyorlar ki hani o güzel nerde

Köpük,köpük olmuş bizim sahilde

Denizler dalgalar soruyor seni

Şahitler aşkıma ömrüm boyunca

Boyun büküyorlar seni duyunca

Sıra,sıra duran o yol boyunca

Serviler çınarlar soruyor seni

Kalmadı güzelim seni sormayan

Yokluğuna acı hüzün duymayan

Gittiğinden beri damla yağmayan

Yağmurlar bulutlar soruyor seni

İster dalga geç sen ister gülümse

Garip haller oldu burda herkese

El ele vermişler bilmem nedense

Düşmanlarla dostlar soruyor seni', 'Gidişinle tadı tuzu kalmayan Sabahlar akşamlar soruyor seni Seninle birlikte batıp doğmayan  Güneşle yıldızlar soruyor seni Bize sırdaştılar...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/soruyur-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-tevfik-karinca-b6juq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yalnızlıgımın alıp götürdüğü sonsuzluklarda

tatlı  bir ürperti seni düşlemek

alışagelmişliğin ötesinde birseyler var

mutsuzluğa inat

kendimle hesaplaştığım  ve ödeşemediğim muhasebe

ne vicdana uyar

ne de yazar o kara kaplı  kitap

sadece senin değil 

kimsenin anlamadığına mı yanayım

yoksa

gereksizliğine mi  umursamanın

bitiverecek nasıl olsa bu

dostlar alışverişte görsün misali  hayat

kalabalıklardaki  sahteciliklere  inat

bir tatlı ürperti yine de seni ummak

bilinmezliğinde tüm olanların', 'yalnızlıgımın alıp götürdüğü sonsuzluklarda tatlı  bir ürperti seni düşlemek alışagelmişliğin ötesinde birseyler var mutsuzluğa inat kendiml...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solduran Bahar', 'solduran-bahar-tufan-afsar-wz9f1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baharda solan çiçek

Olmayı düşledim hep

Açmak haramsa bana 

Solmamak neye fayda...

Baharda yalnız bülbül

İsteği,güldüren gül

Gülmek haramsa bana

Ağlamamak ne fayda...

Baharda çöldedir Mecnun

Leyla''daki aşk sönmüş mum

Kavuşmak haramsa bana

Çölde gezmemek ne fayda...

Baharda solan çiçek

Olmayı düşledim hep

Açmak haramsa bana

Solmamak neye fayda...', 'Baharda solan çiçek Olmayı düşledim hep Açmak haramsa bana  Solmamak neye fayda... Baharda yalnız bülbül İsteği,güldüren gül Gülmek haramsa ...', ARRAY['Türk Edebiyatı','Şiir','Tufan Afşar']::text[], 8.5, '{"poet":"Tufan Afşar","poet_slug":"tufan-afsar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/solduran-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döü - V', 'dou-v-akin-akca-10ig3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne olacak ki, ne olacak? 

Öldüğümüzde kim neyi soracak? 

Mahzeninde tahtanın

Yıllanacak şarap, bürüyecek! 

Gözümüzün önünde giderler

Onlarla toprağı doldururlar

Tek sen varsındır toprak

Tepenin üstünde.

Bakarsın gidişe, yitişe

Son söylenenler hatırlanır

Ve yaşananlar yaşamda:

Bir sürü..

Nefes almayanın büstünde

Kuruldu oyuncak.

Ölen öldü,

O, artık senle oynayacak.

*

Dörtlükler dök dizelere

Ki şekilli olsun; 

Düz gidenlere ağıtlar,

Başucuna konsun 

Artık pürüz olan anıtlar.

Anılanlar: Kaldılar.

Cennet ise cennet,

Azim, musluktan 

Sağdılar, beklenmezdi

Böylesi; soğukluk,

Sahte; son zamanlarda

Sana sinmişti:

Son lafın olmuş fakat,

söyledin:

''Oymuş, buymuş,

Şuymuş.''

Neyi nasıl

Demeli

Oturtmalı 

Taşları

Değil ki; 

Neydi,

Ne değildi

Bile:

''Neydi,

Ne olacaktı? ''

Yazarken 

Değil mi, sanat; 

Bir gün baktık:

Olacakmış bu

Sana kanat.', 'Ne olacak ki, ne olacak?  Öldüğümüzde kim neyi soracak?  Mahzeninde tahtanın Yıllanacak şarap, bürüyecek!  Gözümüzün önünde giderler Onlarla...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/dou-v-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül-ü Hicranî', 'gul-u-hicran-tufan-afsar-tb07k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün olur ağlarsa gül

Duraksız uçar bülbül

Ama ağlasada hergün bülbül

Dönüp bir kere bakmaz ona gül

İşte o zaman düşünür bülbül

Olsun mu şimdiki yari sümbül

Buna içerlemez gül,

Gidene kadar bülbül...', 'Gün olur ağlarsa gül Duraksız uçar bülbül Ama ağlasada hergün bülbül Dönüp bir kere bakmaz ona gül İşte o zaman düşünür bülbül Olsun mu şimd...', ARRAY['Türk Edebiyatı','Şiir','Tufan Afşar']::text[], 8.5, '{"poet":"Tufan Afşar","poet_slug":"tufan-afsar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gul-u-hicrani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız Hayal', 'adsiz-hayal-tufan-afsar-o2fss', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayallerle dolu bir ormanda

Gecelr gündüz,gündüzler gece...

Bir sensin gerçek,bu rüyada

Düşler bile beni anlatmakta

Bir kuytuda büyüdü hayaller

Sense bulutların üstünde,

Gözlerin kapalı,benden habersiz.

Bense seni arıyorum yeryüzünde

Bir sen kalsan bir de ben

Sakin bir yel esse üstümüzden

Bir hiç uğruna gitmişiz bu yerden

Sen bir yana ben diğerine...

Bekliyorum dilimde son bir türküyle

Seviyor sevmiyor,seviyor sevmiyor...

Bir papatya falına bağlamışım umudumu

Yoksa hazin bir son mu bu? 

Gün olur gelirsin,

Sorarım sana bunca bahar nerdesin? 

Beklemem yanıtını çekip giderim.

Sen sadece hayalimsin...', 'Hayallerle dolu bir ormanda Gecelr gündüz,gündüzler gece... Bir sensin gerçek,bu rüyada Düşler bile beni anlatmakta Bir kuytuda büyüdü hayal...', ARRAY['Türk Edebiyatı','Şiir','Tufan Afşar']::text[], 8.5, '{"poet":"Tufan Afşar","poet_slug":"tufan-afsar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adsiz-hayal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-koksal-akar-4gshi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakmayın siz onun gülüşlerine

Dumanlı her zaman başı babamın

Yıllar oldu çare yoktur derdine

Karboran savrulur kışı babamın

Ömrünce gurbeti eylemiş mesken

Zamansız ak düşmüş saçına erken

Yadeller gülüpte bayram ederken

Dinmez gözündeki yaşı babamın

Kimbilir kaçıncı yalnız bayramı

Yine de çıkarmaz seyre merâmı

Aslısı terketmiş garip Kerem''i

Yanık yüreğinin başı babamın

Yıllarca gurbetin çekmiş kahrını

Ekmeğine katıp yutmuş zehrini

Gençliğine vurmuş hasret mührünü

Kavuşmak hayali /düşü babamın

Alışamaz oldu giden zamana

Yüreği kan ağlar yaşlar bahane

Yavrusundan ayrı deli /divane

Gezinip ağlamak işi babamın', 'Bakmayın siz onun gülüşlerine Dumanlı her zaman başı babamın Yıllar oldu çare yoktur derdine Karboran savrulur kışı babamın Ömrünce gurbeti ...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/babam-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunda', 'yoklugunda-can-ozeken-vmhvu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün oturduğum bu yerden kalkıp,

Ufuğa sesleneceğim

Ağaçların yaprakları sallanırken rüzgarla 

Bakışlarımı ileri dikeceğim

Güneşin vurduğu kolumun gölgesini

Yamacımda göreceğim

Nefesimi çekerken ciğerlerime

Elimi hafifçe yukarıya kaldırıp

İşaret parmağımla insanlara mezarını göstereceğim

Merak etme sevdiğim 

Başındaki nöbeti kimseye devretmeyeceğim...', 'Bir gün oturduğum bu yerden kalkıp, Ufuğa sesleneceğim Ağaçların yaprakları sallanırken rüzgarla  Bakışlarımı ileri dikeceğim Güneşin vurduğ...', ARRAY['Türk Edebiyatı','Şiir','Can Özeken']::text[], 8.5, '{"poet":"Can Özeken","poet_slug":"can-ozeken","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yoklugunda-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen Yoksun', 'bir-sen-yoksun-can-ozeken-ztxzy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sen vardın 

Düşünüpte, 

Hayalinle avuttuğum gönlümün parçası.

Bir sen vardın,

Odamdaki çerçeveli resminle

Gözlerimden içeri süzülüp 

Kalbimin derinliklerine işleyen.

Bir sen vardın,

Yarım kalan duygularımı körükleyen

Ateşe barutla giden

Sevgide sınır bilmeyen.

Bir sen vardın,

Yastığa başımı koyduğumda

Aklıma gelen, kalbimi çelen

Gizlilik nedir bilmeyen.

Bir sen vardın,

Ben''den öteye giden

Beni bana sığdıramayıp

Dünya''yı düşünen.

Bir sen vardın.

Şimdi mi? 

Bir sen yok''sun...', 'Bir sen vardın  Düşünüpte,  Hayalinle avuttuğum gönlümün parçası. Bir sen vardın, Odamdaki çerçeveli resminle Gözlerimden içeri süzülüp  Kal...', ARRAY['Türk Edebiyatı','Şiir','Can Özeken']::text[], 8.5, '{"poet":"Can Özeken","poet_slug":"can-ozeken","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-sen-yoksun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Yoksun', 'yine-yoksun-erol-dal-nwtdm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine yoksun

Hepte bana düşer ağlamak

Rüzgârlarla konuşmak

Benim derdimdir

Zaten dumanlarda

Yine yoksun

Tenindeki koku, vurur beni

Koklarım her yeri

Elimde

Dudak izlerin kalmış

Sigaranın kertiği

Gezdirir dururum 

dudaklarımda.

Yine yoksun 

Atlı arabalar geçer hayalimden

Yaylı, atlı, arabalar.

Seni uzak koyan 

Atlı, yaylı arabalar.

maziden hatıralar.

....

Uyuya kalırım öylece 

.....

Yine yoksun

Yatakta, bomboş kollarım

arar seni 

Ağlarım gizlice

...

Islanır yatağım

Islak düşler görürüm

Düşler ki.! 

Düşler seni delice.

...

Yine yoksun

Yoksul evimde; 

.....

Yine, yine, yine

Yoksun……

Kahretsin

Yapayalnızım', 'Yine yoksun Hepte bana düşer ağlamak Rüzgârlarla konuşmak Benim derdimdir Zaten dumanlarda Yine yoksun Tenindeki koku, vurur beni Koklarım h...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yine-yoksun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Hırsızı', 'sevgi-hirsizi-mehmet-yilmaz-n97gk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen sensizlige isyan ediyorum,

Aglamak istiyorum sensiz gecen günlerime,

Bir damla gözyasıyla atmak istiyorum,

İcimde saplanan o duyguları ve hüzünleri,

Ama ağlamayı bile beceremiyorum,

Cünkü sen kalbimden baska gözyaslarımı da caldın.

Yalnız kalmayı istedigim de bile,

Bombos kalbimle kalmak istedigim de bile istedigim olmadı

Sen yalnızlıgımıda sürükledin kendinle.

Günlerce yatamadım,hayallere dalmak istedim,

Gözlerim dikilir tavana her yerde seni görürdüm.

Uyuyamazdım,sensiz bir basıma yatamazdım.

Sabah olmayı durmazdı,saatler dururdu sen olmadan sanki

Cünkü sen hayallerimide calmıstın.

Kayan bir yıldız misali düştü hayaller gözlerimin önünden

Bir kadeh içkide unutmak istedim seni,

İciyordum ama gene unutamayacaktım seni biliyordum.

Ama bir anlık o bir kadehde seni unutmak istedim,

Ama olmadı sen kadehimdeki içkiyi bile calmıstınm,

kadehimin icinde sen vardın...

Dısarı atardım alel acele kendimi..

Basım hep yerde gezerdim,

O bitmek bilmeye kaldırımlarda yürürdüm,

Ortalık zifiri karanlıktı sonu olmayan bir gözkyüzü gibi,

Bir ısık karsıma cıkacak diye yürürdüm,

Ama ısıgımıda aydınlıgımda calmıstın...

İstedigin beni yoketmek miydi? 

Galiba öleydi beni yoketmekti,bunu basarıyordun sen...

Bir mum misali eriyordum sanki...

Aydınlatamaz oldum etrafımı..

Çünkü sen bir gözyasımı,duygularımı,hayallerimi,yalnılıgımı,umıutlarımı hayellerimi,gözümün önünden gecen yıllarımı, bir kadeh içkimi bile calmıstın...

Tabi calacaktın sen sevgi hırsızı degil miydin? 

Ama hırsızlıgını bilki kendi icinden calıyordun..

Bunun asla farkında değildin...

Çünkü Ben senin icinde kaybolmus bir sevdayım...

(17/12/2003)', 'Bazen sensizlige isyan ediyorum, Aglamak istiyorum sensiz gecen günlerime, Bir damla gözyasıyla atmak istiyorum, İcimde saplanan o duyguları...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sevgi-hirsizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
