INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Mehmet', 'adi-mehmet-mehmet-yilmaz-dd7c0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Askın deli dolu aktıgı zamanda dogdu Mehmet,

Günes o kadar büyülüydü ki o an,

O sıcaklık hayata merhaba dediginde yüregine isliyordu.

İlerde tutkulu bir asık olacagı belliydi sanki.

Bir fidan misali yavas yavas filizleniyordu.

Sanki bir ask yolculuguna cıkıyordu

Duygusunu,askını,sevgisini yanına almıstı.

Ve bu yolculukta ilk askını tadıyordu 

Belki bu ask bir hüzün belkide kısmet,

Ama bu askta Mehmet hep cekti eziyet eziyet...

O vefasız ilk askı ne gösterdi sevgi ne de merhamet,

Sanki belliydi,ask acısını simdiden tadacagı,

İlk gözyasısını,ilk haykırsını, ve askla ilgili ne varsa tüm duyguları...

Yavas yavas tatmaya ve her seferinde yüregine bir centik daha acmaya basladı 

Ama Mehmet''in aglaması bir baskaydı,

Gözyasları sadece icine akardı,

Aglaması bir baskaydı,

Ve yüreginde bir titreme ve ardından simsekler kopardı.

Bu ilk ask sayfasınıda kapatıyordu...O iz ölene kadar yüreginde 

kalacaktı...

Yolculuguna devam ediyordu...

Bazen kırgın bazen hayata küsmüs,

Bazende caresizce cırpınısı geldikce aklına yüregindeki duygu agar geliyordu,tasıyamıyordu...

Belkide bunları hakketmiyordu 

Ama Adı Mehmet cekecekti eziyet.

Hayat ona öyle rol vermistiki katlanacaktı zor olsada oynayacaktı bu rolü.

Bir sevdigi insan  icin herseye katlanır...

Gerekirse bir kat elbisesini satar,

Sadece onun elini tutmak ve gözlerine bakmak icin,

Sevmekten baska bir sucu yoktu 

Hep sevdi ama her defasında hüzünle bitti.

Mehmet Gene aglıyordu.

Ama sefer icinde atmıyordu,

Gökyüzündeki yıldızlara bakıyor ve onlarla paylasıyordu.

Mehmet icin ölüm bile kötü degil asksızlık kadar,

Yalnız kaldıgında gerci hep yalnızdı,

Odasına cekilir dinledigi tatlı bir müzikle koyuverirdi kendini düşünür düsünürdü...

Acaba derdi? ''Ben bu ask yolculugunda ne zaman sonduragima ulasacagim''? 

Ne zaman askın elini tutup doyasıya sarılıp, teninin kokusunu iç cekerek yüregine atacaktı...

Zaman o kadar acı ki...

Bir rüzgar misali ordan oraya savruluyordu Mehmet.

Birden icini kapladı acı. kin, nefret.

Sevmek istemiyordu artık,ne sevmeyi ne de sevilmeyi...

Her sevdiginde gene hüzün vuruyordu gönlüne.

Her askı ya yalan sölüyordu ya da ihanet.

Ama yılmıyordu Mehmet bu ugurda savasıp, bagımsızlıgını ilan edecekti.

Bir kösede onu bekleyen biri vardı elbet.

Ama kimdi o askı bilemiyordu.

Ve belki o yüzden her askta cekti eziyet.

Umut  yolcusu simdi Mehmet,

Askin ta kendisiydi, askin adiydi,

Tükenmezdi icindeki sevgi kipirtilari.

Askla dogdu ve askla ölmeliydi.

                                    (28/01/2004)', 'Askın deli dolu aktıgı zamanda dogdu Mehmet, Günes o kadar büyülüydü ki o an, O sıcaklık hayata merhaba dediginde yüregine isliyordu. İlerde...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/adi-mehmet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla', 'beni-hatirla-hurrem-yalcin-z706y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Resmine her bakışımda

Kendi kanıma giriyorum

Yok oluyorum

Bunu unutma....

Beni her terk edişinde

Can kaybından ölüyorum

Gömülüyorum

Sakın bunu da unutma....

Yağmur damlaları toprağa 

Toprak yeşile her kavuştuğunda 

Beni hatırla...

Çünkü

Yağmur damlaları 

Ve

Bahar dalları

Daima seni hatırlatacak

Bana...

08 Haziran 2004 / İstanbul', 'Resmine her bakışımda Kendi kanıma giriyorum Yok oluyorum Bunu unutma.... Beni her terk edişinde Can kaybından ölüyorum Gömülüyorum Sakın bu...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beni-hatirla-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Dünyam', 'benim-dunyam-mehmet-yilmaz-wfkt4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlüm ne sevmeyi haketti ne de sevilmeyi,

Gözyasım ne aglamayi hakketi ne de icli icli bakmayı,

Yüregim sadece dert cekmeyi, 

Hüzün kokan siirler yazmayı öğrendi...

Ben yüregimin sesini her defasında duyduğumda,

Ben gözlerimin her yıldıza bugulu baktıgında,

Ben saclarımın, ellerimin, tenimin her durusunda,

Aklımda sadece sen vardın.

Beni bu gizemliğe, bu entrika hayata sürükleyen sendin.

Benim duygularımı bu denli körükleyen senin sevgindi.

Ates gibi yakıcı kordu.

Bir kıvılcımı dünyala degerdi.

Ama sen anlayamadın ne sevgimi, ne de yüregimi

Sen sadece yoketmeyi,aglatmayı,düşündürmeyi,hüzünlendirmeyi sectin,

Bense her defasında yenik,her defasında yalnız kalmayı sectim.

Bilki ben bunları hic ama hic hakketmedim...

Sevdim sadece sevdim,

Her defasında bir yenisi ekledim,

Her defasında basım yerde ve BEN acılar cektim.

Yenildim...

Ama hic yılmadım.

Savastım,savasmaya galip gelmeye kararlıydı bu yürek.

Belki sen değildin Beni seven,

Belki sen değildin elimi tutan,

Belki sen değildin gözlerime icli icli bakan,

Bunu öğrendim bunu hissettim o sen değildin...

Seviyordum hayatı

Seviyordum cünkü Ben sevgi doluydum,

Yüregim koskocam bir dünyaydı.

Bu dünyayı Kimse yıkamazdı.

Cünkü siirlerim dünyami ayakta tutan tek hatıraydi.

Ve ben yazdıkca; 

Dünyama yeni bir imparatorluk daha kurulacakti,

Bagımsızlık, özgürlük,hepsi dünyamın icindeydi.

Ve ben yazdıkca; 

Dünyayı sevgi dolu bir zamana sürükleyecegim,

Ve yolun basındaYım,

Ve yazıyorum,

Ve Ben burdayım..

Yüregim taaa surda...

Anlatılamaz,anlatamıyorum...

Hissedilir sadece hissetmek...

Hissedilmeye baslandı sanki...

O halde sizde Benim düymadasınız...

Hosgeldiniz...

                                   (08/06/2004)', 'Gönlüm ne sevmeyi haketti ne de sevilmeyi, Gözyasım ne aglamayi hakketi ne de icli icli bakmayı, Yüregim sadece dert cekmeyi,  Hüzün kokan s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/benim-dunyam-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmar II', 'i-mar-ii-ahmet-aksoy-3frlx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yüreğimde imar ettiğim kent

..büyür zamanın örsünde

ve şüphesiz her şehir gibi

......tükenecek gününde

yüksel gözlem kuleleri

demir kapılar

ardında en mahrem şiirler

...altın gizlenir düşümde

beklenir büyük tufan alev

....kralken yanmak ne güzel

ah o gün yıkılır bu şehir

....ve anılarda dim dik', 'yüreğimde imar ettiğim kent ..büyür zamanın örsünde ve şüphesiz her şehir gibi ......tükenecek gününde yüksel gözlem kuleleri demir kapılar ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/imar-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke (deneme)', 'keske-deneme-nedim-saatcioglu-97wrp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KEŞKE…	

Hadi her şeyi bir kenara bırak….bir mum yak ve içiyorsan bir sigara…kapat gözlerini ve bütün “keşke”lerinle yüzleş bugün…

Hayatın sana küstüğü anları düşün ve onlara neden olan “keşke”lerini… hadi yüzleş… yüzleş ki; her “keşke”yi bir “iyi ki” ile sıvayabilesin. yüzleş ki yarın “ben bugün yeniden doğdum” diyebilesin. 

Yaşamın senden çaldıklarını…senin ondan aldıklarını…her şeyden öte yaşadıklarını düşün…her “keşke”nin yerine bir “iyi ki” koy yaşadığın anlara ve anları böl yıllara… hadi “keşke”lerini say, senin için  yüzlerce “keşke”nin karşına bir “iyi ki” koy, yaşanan anlara inat...hadi tart… ve düşün hangisi ağır diye… … …

Ne çok şey almıştır zaman ve ne çok şeyi tüketmiştir farkına varmadan.insan en çok kaybettiği değerler için ağlar ve en çok yitik zamanlarda bıraktığımız “keşke”leri yaşarız ömrümüzde. ne çoktur dilimizdeki yeri,ne çok anlam saklarız bu tek kelimede,ne büyük bir sırdır yüreğimizde son nefese kadar taşımamız gereken. peki ya “iyi ki” saklamak zorunda olmadığımız en karanlık gecede bile bize ışık olan, herkesle paylaştığımız kaç tane “iyi ki” var hayatımızda.

Sen her gece mumlar yakarsın ve ağlarsın en saf yanınla…ama  ”keşke”ler yapışır yakana. bir tünel olmalıdır hayatın karanlığında, ışığa uzanan bir dehliz…ne kadar yakındır oysa beklenen ışık, görürsün, ama yaklaştıkça kaybolur hayatındaki “keşke”lerin gölgesinde. bütün renkler yitirir anlamını, bütün anlamlar kaybolur… kendini en mutlu hissettiğin  anda bile bir “keşke” çıkar karşına, seni umutsuzluğa sürükleyen.

İçeriyi  “iyi ki” olan hiçbir “keşke” yoktur. 

Hadi her şeyi bir kenara bırak bütün “keşke”lerinin karşına tek bir tane “iyi ki” koy…kapat gözlerini…ve düşün… … …

“keşke”ler ıslıkla “iyi ki”ler yumrukla yıkılır unutma…! ! ! 

Hadi “iyi ki” askerlerinden bir ordu kur kendine. bütün “keşke”lere savaş aç, pusuya düşür onları,denizden geçemiyorsan karadan yürüt gemilerini, kavgada namertlik yoktur unutma. varsın senin için kalleş desinler, sırtından kurşunla onları. sonra bir dar ağacı kur yüreğinde  geri kalan bütün “keşke”leri idamla yargıla ve as… yürü ardına bakmadan. başın dik olsun, muhteşem bir savaş kazanmış muzaffer bir komutan edasıyla yürü, adımların tereddüt etmesin “iyi ki”lere giderken.

“zorbalar görünüşte galiptir” ***unutma

 Çünkü “keşke”ler yok artık… yokuş yok…viraj yok… artık  ömrünün her karesini dilediğin renge boyayabileceğin bir yol var önünde, hep “iyi ki”lere uzanan, hep iyilerin olduğu. boya dilediğince boya her umut ayrı bir renk, her hayal bir desendir avuçlarında unutma.

Yaşam bir düş değildir, hangi rüyayı görmek  istiyorsan onu hayal edersin ve kapatırsın gözlerini. bırak hayat bütün “keşke” yapraklarını döksün takviminden.dünün hükmü dünde kalmıştır çünkü. 

Tek kural vardır yaşamda.   “DÜŞÜN…İNAN…BAŞAR…” 

Hadi her şeyi bir kenara bırak…bir mum yak ve içiyorsan bir sigara…birleştir kirpiklerini  ve yeniden öğret gözlerine “iyi ki”leri görmeyi. 

Eline bir sözlük al önce KEŞ sonra İYİ kelimelerinin anlamına bak.hadi karar ver hangisi daha hoş geliyorsa kulağına yarın sabah onları kat hayatına…  … … olur mu… … … … … … … … … … …

 “İYİ ki”			“İYİ ki”			“İYİ ki”

“İYİ ki”			“İYİ ki			“İYİ ki”

“İYİ ki”			“İYİ ki”		“İYİ ki”

“İYİ ki”			“İYİ ki			“İYİ ki”

“İYİ ki”			“İYİ ki”		“İYİ ki”

*** Abraham LİNCOLN', 'KEŞKE…	 Hadi her şeyi bir kenara bırak….bir mum yak ve içiyorsan bir sigara…kapat gözlerini ve bütün “keşke”lerinle yüzleş bugün… Hayatın sa...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/keske-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat 21', 'saat-21-ersan-kurt-q9ghz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saat 21''lerde yazılırmış hep şiirler, 

ister mahpusta ol ister okulda, 

ne gözlerinin fincan karası unutulur 

ne de bıraktığın ten sıcaklığı, 

ister yakında ol ister uzakta. 

Kuzey Denizi, 8 haziran 2004', 'Saat 21''lerde yazılırmış hep şiirler,  ister mahpusta ol ister okulda,  ne gözlerinin fincan karası unutulur  ne de bıraktığın ten sıcaklığı...', ARRAY['Türk Edebiyatı','Şiir','Ersan Kurt']::text[], 8.5, '{"poet":"Ersan Kurt","poet_slug":"ersan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/saat-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yemini', 'ask-yemini-hande-caner-o3gk9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bin bir çiçek içinde öyle bir bahçesin ki

Koklayan sarhoş olur dalgınlaşır gözleri

Sevgilim sen öyle bir billurlaşan Gölsün ki

Kayboluyor aynada hakikatin izleri.

Kömür gibi kap kara, sevgilim o bakışın

Gözünün bebeğinde yorgun ruhum eriyor

O kadar tatlı sesle çağlıyor ki akışın

Çavlanların önünde gönüller ürperiyor.

Ben de senin bu büyüleyen havanda

Umut dolu hayaller içinde yaşıyorum

Benliğimle gölgemi bırakmışım biryana

Görünmez bir hayal gibi dolaşıyorum.

Kadere bırakma bu sevginin önemini

Yükseltelim göklere ışıklarda yıkansın

Dudaklarda beliren inançlı aşk yemini

Yalancının bahtında bir volkan gibi yansın.

HANDE CANER

pimp myspace', 'Bin bir çiçek içinde öyle bir bahçesin ki Koklayan sarhoş olur dalgınlaşır gözleri Sevgilim sen öyle bir billurlaşan Gölsün ki Kayboluyor ay...', ARRAY['Türk Edebiyatı','Şiir','Hande Caner']::text[], 8.5, '{"poet":"Hande Caner","poet_slug":"hande-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ask-yemini-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Akşam', 'sabah-aksam-baykal-kaanalp-1kujx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'görünce gönül gülünü

kokladım sabah akşam

alınca aşk ödülünü

sakladım sabah akşam

vermişsin aldıklarını

topladım yapıtlarını

attığın mektuplarını

okudum sabah akşam

hiç inanmadım sana

kapanmışsın odana

bir şarkı yazmışsın bana

dinledim sabah akşam

hastaymışsın ne oldu

güzelliğin sarardı soldu

mendilim yaşla doldu

kuruladım sabah akşam

kaldırdım gitarını

çalmıyorum şarkını

gözyaşımla mezarını

suladım sabah akşam

zaman geçiyor dolu dizgin

sensiz çalmıyor ezgin

gezdiğin yerleri üzgün

dolaştım sabah akşam', 'görünce gönül gülünü kokladım sabah akşam alınca aşk ödülünü sakladım sabah akşam vermişsin aldıklarını topladım yapıtlarını attığın mektupl...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sabah-aksam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şans Daha', 'bir-sans-daha-baykal-kaanalp-mtgvy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hayata

bir şans daha veriyorum

iplerini çözdüm

artık serbest

istediği yere gidebilir', 'hayata bir şans daha veriyorum iplerini çözdüm artık serbest istediği yere gidebilir...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-sans-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekmek ve Çocuk', 'ekmek-ve-cocuk-zehra-cam-brtw4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kanlı çizmelerin

Toprağı dövdüğü coğrafyalarda

Fırıncıların çocuklarını doğurdu kadınlar

Hangi maya eksiltti hamuru bilmeden

Yalnız ve karnesiz bir somun için

Fırıncıların çocuklarını doğurdular

''Köprülerin altından çok sular geçti''

Enlemler boylamlar 

Birbirine düğümlendi haritalarda

Şimdi

Ayak altında kalan coğrafyalarda

Yine fırıncıların çocuklarını doğuruyor kadınlar

Hangi bela ekşitti 

Bedeni bilmeden

Francalı''dan Ruj''a kadar

Fırıncıların çocuklarını doğuruyor kadınlar', 'Kanlı çizmelerin Toprağı dövdüğü coğrafyalarda Fırıncıların çocuklarını doğurdu kadınlar Hangi maya eksiltti hamuru bilmeden Yalnız ve karne...', ARRAY['Türk Edebiyatı','Şiir','Zehra Çam']::text[], 8.5, '{"poet":"Zehra Çam","poet_slug":"zehra-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ekmek-ve-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usanmaz', 'usanmaz-baykal-kaanalp-rr5kc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tekrar

tekrar

