INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum Yanıyor...', 'erzurum-yaniyor-i-smet-barlioglu-qdbmu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şube: 9-91122-2518

Konu: Erzurum Yanıyor adlı senaryo Hk.

Hikmet Barlıoğlu

Malta Akdeniz Caddesi

Şemseddin Sami Sokak

Şener Apartmanı No: 7

Fatih - İstanbul

''Erzurum Yanıyor'' adlı senaryonuzun filme çekilmesinde bir mahzur olmadığına dair ilgili komisyon tarafından verilen 29/6/1963 gün ve 174 sayılı kararın size tebliğ edilmek üzere 2/7/1963 tarih ve 80843 sayılı yazımızla Erzurum Valiliği ''ne gönderildiği dosyanın tetkikinden anlaşılmaktadır.

Keyfiyet, mezkur valiliğe yazdığınız 19/6/1963 günlü dilekçenize karşılık olarak tebliğ olunur.

(İmza) 

Sabri Sözer

Müsteşar Muavini

İçişleri Bakanı Y.''

Hikmet Barlıoğlu ''nun merak edenlere bir küçük not olarak...)', 'Şube: 9-91122-2518 Konu: Erzurum Yanıyor adlı senaryo Hk. Hikmet Barlıoğlu Malta Akdeniz Caddesi Şemseddin Sami Sokak Şener Apartmanı No: 7 ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/erzurum-yaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yani Ölsem Mi', 'yani-olsem-mi-oguzkan-bolukbasi-l9axv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi sen

Bir elma ağacının dalında asılı olsan

Veya bir zerdali dalında

Şehir olmasa etrafında

Gözlerini gizleyen 

Bir tabiatın ortasında

Kaval çalsam

Sırtımı yaslayıp 

Gölgende ferah bulsam

Da

Çoban olsam sürüsünü kaybetmiş

Neyi anlatır düşlerim

Kokuna meyleden yalnızlığı mı

Doğan günle başlayan umutları mı

Çoktan seçmeli hayaller kuruyorum

Güzel ne varsa yanıtlarda

Hiçbirini işaretliyorum

Umutsuzlukların hepsini

Hayallerime kurşun sıkıyorum

Ölmüyorlar

Tekli sevdaların zamanı

İlhamlarımı birleştiriyorum

Bir resim çıkmıyor

Sana benzeyen

Sevdalarımı terk ediyorum

Bırakmıyorlar

 Şimdi sen

Bir elma ağacının dalında asılı olsan

Veya bir zerdali dalında

Koca bir kentte 

Evlerin arasında

Ben kaval çalmasam

Yanından geçerken kokunu duymasam

Gövdene sarılmasam

Gözlerini düşlemesem

Yani ölsem mi', 'Şimdi sen Bir elma ağacının dalında asılı olsan Veya bir zerdali dalında Şehir olmasa etrafında Gözlerini gizleyen  Bir tabiatın ortasında K...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yani-olsem-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Of Ki Of', 'of-ki-of-adnan-ferit-vypyl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yutkun

Zorla..

Bu da geçer boğazından senin

Hak benim

Mal senin

Yetim de değilim..

Elimin emeği gözümün nuru

alnımın teri 

terimin  bedeli

sana ne değilmi

boş bunların hepsi..

Allah''ın rızkı

kulun hakkı

bunlarıda geçelim

inananmı kaldı..

alınca canını

tövbe eden  neden  ben

Allah''dan af dileyen

Ve neden affı yok

Tek adres cehennem.

Der ki  Adnan Ferit

Ne düzen kalmış

Ne de düzenleyen

Allah''ın gücüne gitmesin ama..

Dinsizle imansız işbirliğinde

Kaldık buralarda bi çare..', 'Yutkun Zorla.. Bu da geçer boğazından senin Hak benim Mal senin Yetim de değilim.. Elimin emeği gözümün nuru alnımın teri  terimin  bedeli s...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/of-ki-of-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapatmayın güneşimizi', 'kapatmayin-gunesimizi-husamettin-gunacti-bjtpn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kim kapattı önünü

doğan güneşin,

tutsak edip

karanlığa bizleri.

sevmekse sevdik ölesiye,

sevilmesekte bir kere.

yağmur gibi yağdık 

yeryüzüne,

sürgün olup yürüdük

kardeşliğe.

adamıştık kendimizi

barış tohumlarını yeşertmeye,

ama başaramadık.

kapattılar önünü 

doğan güneşin.

oysa Gül fidanları ekmiştik

y ü r e k l e r i m i z e.

şimdi Kasımpatları biçiyoruz

m e z a r l a r ı m ı z a....', 'kim kapattı önünü doğan güneşin, tutsak edip karanlığa bizleri. sevmekse sevdik ölesiye, sevilmesekte bir kere. yağmur gibi yağdık  yeryüzün...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kapatmayin-gunesimizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedensiz...', 'nedensiz-burcin-onatoglu-odklz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Başka bir dünyanın masumluğunda

Aşk diye bir şey varsa

Rengini yitirmemişse zamanlar

Adın ruhuma çizilmiş resim olur

Neden sorulmaz sevdiğim

Gidişin sonum

Belki de kanayan yarım olur...', 'Başka bir dünyanın masumluğunda Aşk diye bir şey varsa Rengini yitirmemişse zamanlar Adın ruhuma çizilmiş resim olur Neden sorulmaz sevdiğim...', ARRAY['Türk Edebiyatı','Şiir','Burçin Onatoğlu']::text[], 8.5, '{"poet":"Burçin Onatoğlu","poet_slug":"burcin-onatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nedensiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sevdanın Rengi Şarabi', 'bu-sevdanin-rengi-sarabi-derin-oger-3mgoa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nedenim olmuşsun

Niçinler deprem gibi

Sorsam titrek bir çiçeğe 

Yüzüme bakar içli içli

İki gözüm anlar halimi

Üşür bebeği ürperir içi

Yaşlarımın pınarı

Andırır köpüren denizi

Dalgalarının rengi şarabi

Acının doğurduğu yara

Yüreğimde prangalı kilitli

Ah zamanın burnu tilki

Kokladı kokladı kokladı

Bitiremedi bendeki seni

Uçurum ne ölüm ne ki

Başımın dumanı alnımın teri

Her batan günün ardında

Bu sevdanın rengi şarabi....', 'Nedenim olmuşsun Niçinler deprem gibi Sorsam titrek bir çiçeğe  Yüzüme bakar içli içli İki gözüm anlar halimi Üşür bebeği ürperir içi Yaşlar...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bu-sevdanin-rengi-sarabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş', 'kus-husamettin-gunacti-k4teq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'rengin yeşil,sarı,mavi,

özgürlüğün nerde hani.

kanatlarını çırpma öyle,

sanki uçup gidecek gibi.

evin güzel,sense süslü,

yine de kuşsun altı üstü.

sesin eh işte şöyle böyle,

ötersin sabah ve akşamüstü.

yaşarsın belki üç-beş sene,

bağlarsın insanları kendine.

tam da sevip alışmışken,

ölüp gidersin birdenbire.', 'rengin yeşil,sarı,mavi, özgürlüğün nerde hani. kanatlarını çırpma öyle, sanki uçup gidecek gibi. evin güzel,sense süslü, yine de kuşsun altı...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kus-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrıl da gel', 'ayril-da-gel-husamettin-gunacti-8ycrx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'altılı''da arar kısmetini,

yese de hergün darbesini.

ayrıl da gel diyerek

bitirir elindeki sermayesini.

tam ikiyüz At''a bakar,

sıfırı tüketse eşya satar.

ayrıl da gel diyerek

hipodrom''a neşe katar.

At mı Eşek mi çözemez,

bülteni gözlüksüz göremez.

ayrıl da gel diyerek

zararın hesabını bilemez.

bu işin sonu hüsran.

ayrıl da gel yüzünden

ayrıldı koca''dan

zavallı Hicran...', 'altılı''da arar kısmetini, yese de hergün darbesini. ayrıl da gel diyerek bitirir elindeki sermayesini. tam ikiyüz At''a bakar, sıfırı tüketse...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayril-da-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip yazdı / Hikayeler Bir (1)', 'garip-yazdi-hikayeler-bir-1-gencay-coskun-imtbz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Garip yazdı 

Tanıdık bir yol 

Bile yoktu 

Her adımda 

Biraz daha çok 

Kendime gidiyordum 

Güneşin ışıkları yakıyordu beni 

İçimin yakanların gibi değildi acısı

Her solukta yalnızlık 

Öfkelendiren arıların sokması sözlerin sonunda

Duvarlarda ellerimin izi

Ellerimde duvarların izi kalıyor

Sargıda geçiyordu zaman 

Soranlara kapı çarptı bahanelere uyduruyorum

Pekala biliyordu herkes 

Gönlüme çarpanları

Ben çarpamıyordum

Ellerimin morarmış yüzüne 

Bakamıyordum 

Kararmış bir geleceği görüyordum

Yufkadan gönlüm 

Sigara böreği kıvamına getirilmiş

İki gözyaşına 

Yelkenleri suya indiriyordu 

Suya inmeyense 

Gelmeyecek umutlardı

Bir garip yazdı 

Yola çıkmam 

Başlı başına tesadüftü 

Küf kokuyordu kitaplarım

Açılmayı bekliyordu 

Bir türlü açamamıştım 

Öfkenin tünellerinde 

Ne sevindirik olmuşlardı

Okuma bayramlarında 

İlk yapraklarına 

Gözlerim değince 

Bir garip sevişmeydi 

İlk okumalarım 

Bir garip yazıydı 

Yüreğimi vuran 

Bir garip yazdı 

Belki de 

Geride çok şey bırakmıştım 

Yada gerilerde

Benden çok şey kalmıştı 

Girdabın içindeyken 

Dünyam dediğin 

Kıpırdamaz bile yerinden 

Sıkılırsın ince ince 

Aslı sorunu girdaptan 

Çıkmak istediğinde 

Adamakıllı yaşarsın 

Ama yinede akıllanmazsın 

Bir garip yazdı 

Yazacak çok şey vardı 

Kaçamak saatlerdi 

Kaçırdıklarım 

Birazda benli zamanları 

Hayal ediyordum

Çok da çabalıyordum 

Zaman kaçakçılığını 

Yapmak benim harcım 

Hiç değildi 

Karılırken harcım 

Hep çok şeyler eksikti

Dağ tepe orman 

Gidiyordum 

Harbiden garip bir yazdı 

Yazamadıklarım 

Garip bir yazdı 

Sarmaşık dolu kenarları 

Deli bir orman vardı 

İlk defa nefes aldığını

Hissettiriyordu insana 

Ağır gelmiyordu 

Damlaları yağmurun 

Kürek çektim

Ilık rüzgarlara

Bir akşamı başlıyordu 

Bir garip yazın 

Sığınaklar kuruyordum

Çatma derme malzemeyle

Yıldız koynunda uyumak 

Zordu denilse de

Biz ay yıldız görmeden 

Hiçbir zaman uyuyamadık

Garip bir insanlıktı 

Her şeyi kendilerinin 

Sanırlardı 

Onlara göre anlamlı 

Bizlere göre 

Hayırsız bir dünyaydı 

Uğruna ölünesi mekanların 

Üstündeki hamam böcekleriydi

Bazı üst düzey insan kopyaları

Kendilerinden başkalarının 

Güzel yaşama şansı yoktu 

Üstünde bastıkları toprak 

Soludukları hava 

İçtikleri su 

Eğlenip dönüştükleri 

Yerleri bilirlerdi

Ama altında bu mekanlara

Kan, hayat, can  verenleri 

Çabukça unutup silerlerdi 

Unutulan insanlar 

Unutanları asla unutmazlardı 

Bir oradan bir oraya dolaşırlardı

Bekledikleri gün 

Er ya da geç gelecekti 

Bir garip insanlıktı 

İnsan olmayı 

Yeni yeni unutup 

Tekrar öğrenmeye çalışırlardı ki

Bu garip bir zaman kaybıydı 

Hafızaları su gibiydi 

Hangi kaba girse 

Onun şeklini alırlardı

Bir tek kendi kaplarına 

Sığmaz 

Bir tek kendi kaplarını

Dolduramazlar

Bir tek kendi kaplarını 

Beğenmezlerdi

Kaplarına marka koyarak 

Kendilerini fişlerlerdi 

Bir garip yazdı 

Aşık olmak 

Bile çok riskliydi 

Mermi hızında 

Birden bitiyordu süren

İzi kalıyordu 

Bedenin içinde bir yerde 

Hayasızlar imparatorluğunun 

Paralı korkak 

Sevişken yaratıkları vardı 

Aman Allah ım 

Bu yaratıklar nede çoktu 

Modernlik kisveleri boynunda

Yalanların bini bir paraydı

Ona buna yalakalık 

Yapanlar

Doğrularla erirlerdi

Adamların umurunda bile değildi ki 

Garip bir yazdı 

Yalanları hep 

Aydınlar yazdı 

Gerçekleri hep 

Garibanlar yazdı 

Bir garip zamandı 

Tam dibine düşmüştüm 

İki arada bir derede 

Sevmeye çalışıyordu 

Gönlüm güzellikleri

Sözde aydınlığın 

Parlak karanlığına 

Sevdalandım 

Belki dilim 

Varmadı 

Negatif eksende 

Orijinden geçip 

Pozitif bir cümle kuramadım 

Hep içime işledim sevdamı 

Yıkıntıların üstüne bir şehir kurdum

Tuğlaları kayadan 

Bir daldan uzansa da kanım 

Sevinç çığlıkları atası geliyordu insanın 

Atacak organlarım ipotek altındaydı

Ansızın serilebilirdi

Gülden halılar topraklara

Ufuklara sevdalanmıştım

Sonsuz bir döngüden çıkıp 

Diğer sonsuz döngü için 

Beklemek lazımdı 

Dil susacaktı 

Gönül konuşurdu 

Gönülden sesini 

Kimsecikler dahil duyan olmazdı 

Güz tadında şerbetler 

Kış tadında bozalar

Yaz tadında sular içilirdi 

Gerçekten seven başkasına 

İlişkilendirmezdi kendini 

Beklenmezdi sonlar

Duyumlara kulak kapalı 

Kar maskeli adamlardı 

Sevdamı götüren 

Susarak beklemek 

Acı veriyordu 

İçimi bilen sevdam 

Beni beklemişti ama 

Ben asla uzanmamıştım 

Yalancı meyvelere 

Her ne kadar gerçek görünseler bile 

Dokunmamıştım bir dalına 

Yukarıdan inmiştik yeryüzüne 

Buradan sonra gidecek yer

Sınırlı, sonu sonsuz bir zamandı

Ben seni beklemiştim

Kısır bir gürültüde 

Topraklar içinde 

Sense bir başka gönülde 

Gönül öldüren 

Sunmuştun bronz bir kadeh içinde

Garip bir yazdı 

Sonu garip bir hikaye oldu 

Hikayeler Bir (1)', 'Garip yazdı  Tanıdık bir yol  Bile yoktu  Her adımda  Biraz daha çok  Kendime gidiyordum  Güneşin ışıkları yakıyordu beni  İçimin yakanların...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":208,"source_url":"https://www.antoloji.com/garip-yazdi-hikayeler-bir-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar geldi', 'bahar-geldi-husamettin-gunacti-4w1ef', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'başımı döndürür,

sarhoş eder beni

bu çiçeklerin kokusu.

sanki hiç yokmuş gibi

çıkar gider içimden

yalnızlık korkusu.

bari siz uyanmayın

otlar karıncalar,inanmayın ona.

bulunmaz mı acaba

şu sahte güneşin ilacı.

erken gelen baharla aldanır,

insanlar ve Erik ağacı...', 'başımı döndürür, sarhoş eder beni bu çiçeklerin kokusu. sanki hiç yokmuş gibi çıkar gider içimden yalnızlık korkusu. bari siz uyanmayın otla...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bahar-geldi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmadım', 'unutmadim-husamettin-gunacti-df17g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ak çarşaflara uzandılar

aşk ve ihtiras karışımı.

çarşafları kırıştı,

yakıştılar sonsuz geceye.

aşkları bin yıl sürdü

binbirgece masallarında.

sevda Gül''dü,menevişlendi

gönüllerinin sırça sarayında.

ak çarşaflara uzandılar,

sevgi ve saygı karışımı.

elleri yüzleri kırıştı,

yakıştılar sonsuz geceye.

anılarımda kalmışlar,

geçmişten bugüne ve geleceğe...', 'ak çarşaflara uzandılar aşk ve ihtiras karışımı. çarşafları kırıştı, yakıştılar sonsuz geceye. aşkları bin yıl sürdü binbirgece masallarında...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unutmadim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pazarcı', 'pazarci-husamettin-gunacti-pf2p5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sabahın körü bostan''a, hal''e,

kimisi sebze alır,kimisi meyve.

uykusuzluk sorun değil,

yorgun dönse de akşam eve.

kış dondurur,yaz kavurur,

fırtına kopar,yel savurur.

her yiğidin harcı değil,

her biri on nüfus doyurur.

tezgahı kur,çadırı çek,

bekle müşteri gelecek.

yemek saati belli değil,

ne bulursa onu yiyecek.

ilk müşteri göründü ufukta,

sattıklarını sayar bir solukta.

saygıda kusur mümkün değil,

beklese de akşama dek soğukta.

toka,küpe,tencere,tava,

kazak,gömlek,etek,oklava.

ne sattığı mühim değil,

ekmek parasıdır asıl dâvâ.

her malın ayrı diziliş sırası,

dünya akçe pazarda yer kirası.

ayazda durmak kolay değil,

romatizma''dır bu işin mirası.

pazarcıdır o, içimizden olan,

yıllardır tazeyi ucuza sunan.

takdir etmemek elde değil,

kimi Malatya''dan kimi Muş''tan...', 'sabahın körü bostan''a, hal''e, kimisi sebze alır,kimisi meyve. uykusuzluk sorun değil, yorgun dönse de akşam eve. kış dondurur,yaz kavurur, f...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/pazarci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-husamettin-gunacti-ok9um', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ormandaki Meşe, Kayın, Gürgen,

hepsi de gençtir benden.

aşkım gözünde 

etmese de beş metelik,

n''olur kalma uzaklarda.

yalnızım,yorgunum da üstelik...', 'ormandaki Meşe, Kayın, Gürgen, hepsi de gençtir benden. aşkım gözünde  etmese de beş metelik, n''olur kalma uzaklarda. yalnızım,yorgunum da ü...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalnizim-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuçlarımdan Kaydım', 'avuclarimdan-kaydim-bekir-mutlu-gokcesu-btmil', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İmkansıza sardım

Yıldızları saydım 

Yine dün gece

Aydım

Sana aydım...

Kaç kuş kanadında

Uçarken aklım

Avuçlarındaki esaretime

Ve rutubeti 

İşlerken sensizliğin

İliklerime

Nasıl olur da? 

Düşler uçurmayı

Özgürlük sandım...

Oysa ben aşıktım

Birden uyandım

Sana doğru hızla

Avuçlarımdan kaydım...', 'İmkansıza sardım Yıldızları saydım  Yine dün gece Aydım Sana aydım... Kaç kuş kanadında Uçarken aklım Avuçlarındaki esaretime Ve rutubeti  İ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/avuclarimdan-kaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader ve Gerçek -RPT', 'kader-ve-gercek-rpt-erol-dal-qkmmz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her adımda 

yaklaşan aksin

Kızılcık çukurunda.

Ruhumu arar 

yoksa son nefesin

Sağır sularda.

Gitmişte olsa da bedenin

Adsız gemiyle arşa

Silinmez kötü kaderin

Melekler üstüne konsa.

Yırtılmışta olsa mazin

Tükense de nefesin

Boş ver git

Sen gerçeksin

Gerçek; 

Senin kaderin

../87', 'Her adımda  yaklaşan aksin Kızılcık çukurunda. Ruhumu arar  yoksa son nefesin Sağır sularda. Gitmişte olsa da bedenin Adsız gemiyle arşa Sil...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kader-ve-gercek-rpt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte Dostların Eline Düşürme Allah''ım! ! !', 'sahte-dostlarin-eline-dusurme-allah-im-kemal-dadasoglu-5yf74', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dost var; uğrunda ölünür...

Dost var; uğrunda can vermek bile ''ucuz'' kalır..

Dost var; sevdiği insana bir zarar gelecek endişesiyle,

Akrep, çıyan yuvalarını topuğuyla kapar...

Bunu yapmak yetmez dost için...

Sevdiği insan uğruna ömrünü verir.

Verilen bir ömürdür...

Bir yılını, iki yılını, on yılını, yirmi yılını değil, ''ömrünü'' vermiştir...

Dost var; Sevdiği insanın uğruna ölmeye hazırdır.

Düşmanlar gelecek, 

katletmek istedikleri Nebi''nin yatağında vefalı bir genç, delikanlıyı bulacaktır...

Bu delikanlı dosttur... Ve hep ''dost'' kalmıştır.

Dost var; güle benzer...

O kadar güzel kokar ki, dikenlerinin verdiği acı hissedilmez...

Bir de dost var ki, dikenlerinin yol açtığı kan ve yara korkusundan, 

gül rayihasını almak mümkün değildir.

Dost var; hazmedemez...

Sindirim sistemi bozuktur...

Dost var; fırına girmeyi sevmez... Ama, ekmeği herkesten önce böler...

Dost var; sözü itibarsız senettir... Güvenirseniz müflis olursunuz...

Dost var;  yollarda bırakır...

Böylesiyle adım bile atılmaz.

Yola beraber çıkmak, neticeyi kabullenmektir.

Dost var; düşmandan tek farkı, biraz daha mütebessimdir. 

Ama bir düşmeye gör; düşmanın ''kahkahaları'', 

O''nun ''tebessümünün'' yanında ''sessiz'' kalır.

Dost var; Iyiliğini istemez... Düşman için önüne bir taş da o kayar.

Sonra bu da yetmez ''dost'' için! ..

''Belki benim koyduğum taşla düşmez'' diye, senin düşmanına da, 

''şuraya ip germeyi unutma'' diye tembihte bulunur.

Dost var sadece yüzüne güler...

Arkandan vurmak, hançerlemek için ''malzeme'' arar. Hiçbir fırsatı kaçırmaz.

Lakin bunlar da ''dosttur''! ..

''Düşmanım'' diyemeyeceğimiz dostlar! ...

Böylelerini görünce oturur bir köşede ağlar; ''Dostların eline düşürme Allah''ım'' dersiniz.

Ah! Hz.Ebu Bekir..., Ah! Hz.Ali... Müslümanlığı sizlerden öğrendik. 

Keşke dostluğu ve vefayı da sizlerden öğrenebilseydik... 

									Kemal DADAŞOĞLU', 'Dost var; uğrunda ölünür... Dost var; uğrunda can vermek bile ''ucuz'' kalır.. Dost var; sevdiği insana bir zarar gelecek endişesiyle, Akrep, ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Dadaşoğlu']::text[], 8.5, '{"poet":"Kemal Dadaşoğlu","poet_slug":"kemal-dadasoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sahte-dostlarin-eline-dusurme-allah-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenildim Anne! ! !', 'yenildim-anne-kemal-dadasoglu-nwnao', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anneciğim! Evlatlar vardır başarılarını, zaferlerini yazarlar... 

Sana yazacak bir başarım, bir ödülüm yok anne.

Keşke olsaydı da, seni sevindirebilseydim.

Keşke, benimde anneme yazacak, anlatacak başarılarım olsaydı.

Ama yok anne...

Sevdiğin, okşadığın saçlarıma aklar düştü anne. 

Ilk evvel saçlarım hayat mücadelesinde yenildi.

Düşmanlarım hep benden güçlü oldu anne. 

Onların tahta kılıçları benim çelikten kılıcımı paramparça etti.

Onlar beni yenmek için ne senaryolar yazdı, ne iftiralar attılar. 

Ben, ''masumum'' bile diyemedim.

Düşmanlarıma hep yenildim anne. 

Ve ne yazık ki, dostlarıma da... 

Dostlarımda beni hep yendi... 

Ben onları dost bilirken onlar beni meydanlarda tuş ettiler. 

Arkamda hep bir hançer yarası oldu anne. 

Senin anlayacağın, dostlarım beni düşmanlarımdan daha beter etti! 

Kahkahayı unuttum, tebessümle dost oldum. 

Yüzümde acı bir tebessüm var şimdi. Bahtıma yenildim anne! 

Çocukluk yıllarımın özlemiyle seni aradım anne... 

Senden daha şefkatlisini, daha merhametlisini bulamayacağımı bilerek... 

Her şey küçükken güzelmiş anne. 

Şimdi büyüdüm ve yenilmeyi öğrendim anne.

Gülü çok sevdim, hele alını, pembesini... 

Bahtıma hep beyazı düştü anne...

O çok sevdiğim güllerin, dikenlerine yenildim anne...

Açlığa-tokluğa, hastalığa-sağlığa, dosta-düşmana... 

Hepsine ama hepsine yenildim...

Senin anlayacağın hayata yenildim anne...

Yenildim...

								Kemal DADAŞOĞLU', 'Anneciğim! Evlatlar vardır başarılarını, zaferlerini yazarlar...  Sana yazacak bir başarım, bir ödülüm yok anne. Keşke olsaydı da, seni sevi...', ARRAY['Türk Edebiyatı','Şiir','Kemal Dadaşoğlu']::text[], 8.5, '{"poet":"Kemal Dadaşoğlu","poet_slug":"kemal-dadasoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yenildim-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkbahar', 'i-lkbahar-husamettin-gunacti-uvt8u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne güzel tanda açan kırmızı gül,

ya küçücük meyvesiyle kızılcık.

ne güzel mis kokulu mor sümbül,

tiz sesiyle sabahı karşılayan sığırcık.

ne güzel yağmurda toprağın kokusu,

ya çiçekten çiçeğe konan arılar.

ne güzel toprağı hissetme duygusu,

ah o çalı çırpı taşıyan kuşlar.

ne güzel özgürce patlayan tomurcuk,

ya geceyi delen börtü böcek sesleri.

ne güzel kelebek kovalayan çocuk,

hayalimde yaşatan o eski günleri...', 'ne güzel tanda açan kırmızı gül, ya küçücük meyvesiyle kızılcık. ne güzel mis kokulu mor sümbül, tiz sesiyle sabahı karşılayan sığırcık. ne ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ilkbahar-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı ve Vade', 'gozyasi-ve-vade-zafer-zengin-etnika-fx7yh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sessizce

Gidiverdi ayrılık

Beni  çocukca ağlatan

Ey adam

Gözyaşının vadesi yok mu! 

Izdırap gülü mü büyütür 

Hep hayat

Kim sevecek nazlı bakışları

Sen sevmekten korkan

Aşk''ı sırf acı sanan

Kendine yanan

Dağlanan

Adam 

Kopar zincirini

Kim sevecek ellerini

Sen gidince

Kim sevecek gülleri

Yetmez ağrılığa

Sevdayı yarım bırakanlara

Bu el ki taş öğütürken

Takılır pamuk tarlalarına

Sancılanır

Unutmaz ayrılınca

Sen adam

Gül görünce

nasılda döndün kendine

Unutmamısşın kendini 

Yontmamışsın derini

Sarıldın ki bırakma

Gül kalsın

Can kalsın

Sevda olsun

Can olsun

Tren yollarında  türkü söyleyen bebeler gibi

Memleket yollarında yar ismi söylemek

Adamca/Ozanca yollar alıp

Gül dermek

Gül''e ömür vermek

İşte bu hayat demek

Git kapıları çarpmadan

Dönme geri/Sevdalanmadan

Git ömrün açık olsun

Gidebildiğindir/Dönüp ardına bakma...

30 Mayıs 2004 '' Kan konuşmaz ''', 'Sessizce Gidiverdi ayrılık Beni  çocukca ağlatan Ey adam Gözyaşının vadesi yok mu!  Izdırap gülü mü büyütür  Hep hayat Kim sevecek nazlı bak...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/gozyasi-ve-vade-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıymet Bilmeyiz!', 'kiymet-bilmeyiz-ahmet-agdere-u63uh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sokakta çocuklar dolaşır, ayakları çıplak,

Bizde ise lüks iskarpinler, kara, kahve ve ak.

Batarken ayaklarına kırıklar, çakıl taşları,

Gönlümüzde geçer daha iyi mırıltıları! 

Hastanede bir hasta, upuzun yatar komada,

Bizdeyse, dudakta süzülmekte bir dal sigara.

Hazırken kavuşmaya O’na, dilinde besmele, 

Durur rakı masası, çerez, meze ve besleme! 

Çalışır durur bizim inek Kamil gece gündüz,

Bizde ise zaman çoktur, sefaya devam düm düz..

O çoğaltırken rızkını, büyük bir hararetle,

Biz de devam oynaşmaya komşu kızı Hayret’le! 

Bilmeyiz ha parada, zamanda,sıhhatte kıymet,

Varsın sürsün devran, kopsun ebedi kıyamet.

Olmaz umrumuzda bir şey, dibi görene kadar,

Gördükten sonra basarız feryat: “Kurtar bizi Yar! ”', 'Sokakta çocuklar dolaşır, ayakları çıplak, Bizde ise lüks iskarpinler, kara, kahve ve ak. Batarken ayaklarına kırıklar, çakıl taşları, Gönlü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kiymet-bilmeyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kaybolus Hikayesi', 'bir-kaybolus-hikayesi-mehmet-yilmaz-drqy7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Issız bir gecenin karanlıgında yürüyorum adım adım,

Bir yandan da son bir nefeslik kalmıs olan sigaramı cekiyorum icime,

Onu da bir yana attım simdi,

Tıpkı senin de Beni bir yana attıgın gibi.

Sigaramın dumanını ic cekerek havaya doru üfledim, 

O anda yıldızların bana baktıgını farkettim.

Yıldızlar bana öyle bakıyorlarda ki sanki benim ne dertte oldugumu biliyorlardı.

Keske onlarla paylassma askımı, hüznümü sevincimi gözyasımı, duygularımı,

Ama onlarda anlamayacaklar Beni...

Ben baska dünyada onlar baska dünyada,

Tıpkı seninle benim dünyam gibi...

Ben senin pesinde sen baska askın pesinde.

Söyle bir saatime bakıyorumda vakitte baya bir gecmis...

Sen yatagında mısıl mısıl uyurken,

Ben askından virane olmus bir derbeder gibi dolasıyorum sokaklarda, o bitmek bilmeyen kaldırmlarda.

Düsünüyırumda zaman hep aynı kalsa,

Sensiz kaldıgım bin gün degilde, bir gün olsa,

Ama ne care; düşünmekte yetmiyor kaybolan askıma.

Sanki karanlıgın icine düsmüs aydınlıgını arıyor bir ısık arıyor sanki,

Ama ne fayda kayboldu bir kere ask acısı cekmis onu icine

Keske bir anda cıksa karsıma o karanlıgın icinden,

Beyazları giymis bir peri misali cıksa karsıma...

Ama ne care; hayal kurmakta yetmiyor kaybolan askıma...

Yolunu kaybetmis bir kus misali...Kayboldu gözümün önünden...

Biliyorum o da gelmeyecek, bir kus gibi...

Ya güzel diyarlara gidecek,,,

Ya da güzel sandıgı diyarda hayatını tüketecek.

Tıpkı seninle benim hayatım gibi,

Ya bu kalp seni bırakmayacak,

Ya da bu kalpte seninle birlikte topraga girecek.

Belki de askımın gücü zamana yenik düsecek,

Tıpkı karanlıgın aydınlıga olan inancının bittigi gibi,

Sana olan askımda habersiz Kaybolup Gidecek...

(27/06/2003)', 'Issız bir gecenin karanlıgında yürüyorum adım adım, Bir yandan da son bir nefeslik kalmıs olan sigaramı cekiyorum icime, Onu da bir yana att...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-kaybolus-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mirasın', 'mirasin-hurrem-yalcin-laofi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çekmecemde duran

hani mavi ceketli

resmine her baktığımda 

kanım çekilir damarlarımdan 

yerine hasretini bırakır ya 

işte bu da gidişinin 

yegane mirası oldu bana....

08 Haziran 2004', 'çekmecemde duran hani mavi ceketli resmine her baktığımda  kanım çekilir damarlarımdan  yerine hasretini bırakır ya  işte bu da gidişinin  y...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mirasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim', 'kalbim-i-brahim-atilmis-35skw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kalbim...

dinledimde ne oldu sanki seni? 

sen bir kez olsun dinlemedin ki beni

ne geldiyse basima

iyi yada kotu

bazen hos

bazande anlamsiz ve bos

hep senin yuzunden degilmi? 

pir pir ettinmi bir kere

söz gecmez sana

alemi cihan gelse kar etmez artik

dedigim dedik caldigim duduk misali.

ne etmeli, ne demeli sana bilmemki? 

gene heyecanlandin her nasilsa bu ara

hani yeni biri olsa kizmayacagim sana

ilahi; 

esek bile bir kere dusermis camura

sayende camursuz yasayamaz oldum hayatta

sen akillanmayacakmisin be usta?', 'kalbim... dinledimde ne oldu sanki seni?  sen bir kez olsun dinlemedin ki beni ne geldiyse basima iyi yada kotu bazen hos bazande anlamsiz v...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kalbim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acımasızlık', 'acimasizlik-mehmet-yilmaz-uqt0i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökyüzü bulutlar icinde sanki,

Ama bilmez ki benim bucektigim derdi.

Ben yalnız basıma yürürken adım adım,

Bir yandan da düsünüyorum, fakat bir cıkar yol bulamadım.

Söyle bir düsündüm kendi kendime ''''Acaba yalnızlıgım mı beni sürüklüyor,yoksa kaderimin bana bıraktıgı kötü miras mı''''? 

Sanırım herseyi hissedebilecek hala geldim,

Terkedilmisligin,yalnız gecen zalim yılların, galiba pesine takılıp gidiyorum.

Belkide ''zamansız gelen hüznün'' icinde boguluyorum.

Derdimi kime anlatsam onu da bilmiyorum.

Zaman su gibi akiyor gözlerimin önünden,

Ne yapsam, duygularımı anlatamıyorum.

Ben nerde hata yaptım? 

Ah! bir  anlatabilsem ne acılar cektigimi,

Diger taraftan da keske burda olmasaydım.

Cektigim bu acıları, bu korkuları yasamasaydım.

Ama keskelerde faydasız.

Bazı seyler var aklımdan cıkaramıyorum,

Galiba ben bu belirsizligi yasıyorum,adını koyamıyorum bu belirsizligin.

Yok yere bitip tükeniyorum.

Aslında yalnızlıgımı, sadece yalnızlıgımı istiyorum.

Ne care onu da yapamıyorum.

Dedim ya zamansız gelen hüznün icinde boguluyorum.

Gercektende her günü endise icersinde, umutsuz bir sekilde bekliyorum.

Unutmak istiyorum basaramıyorum.

Kalbim her kalıba giriyor mutluluk, sevkat, sevgi, acı, keder,

Zıtlıkları bir arada yasıyorum.

Acımasızlıkti icinde bulundugum bu hayat ve bana acımıyordu...

(31/03/2003)', 'Gökyüzü bulutlar icinde sanki, Ama bilmez ki benim bucektigim derdi. Ben yalnız basıma yürürken adım adım, Bir yandan da düsünüyorum, fakat ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/acimasizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlama', 'anlama-mehmet-yilmaz-6zhcs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzünlendim yine bu gece,tabi her gece oldugu gibi,

İcimde olan o ask varya o deli ask! 

Yine haykırdı sensizlige, yine haykırdı yalnızlıga,

Yine haykırdı seni ne kadar sevdigini.

Ama sen yine anlamadın beni.

Ben icimde ki askın esiri olmus bir derbederdim sanki.

Ne oldugumu  anlayacak bir halde degildim,

Sürekli aglıyordum  sensizligime, caresizligime,

Bir mum misali eriyordum.

Seviyordum lanet olsun! sen beni sevmesende,

İçime saplanan o kahrolası duyguyu atamıyordum..

Aglıyordum, dayanamıyordum seni seviyordum...

Diz cöktüm seni bana vermeyen karanlıga,

Bağırdım, haykırdım karanlığıa seni sevdigimi,

O da anlamadı beni, vermedi seni bana

Vermedi aydınlıgımı bana! Vermedi iste.

Basımı yukarı kaldırdıgımda bir yıldız kayıyordu,gözlerimin önünden, kalbime düstü o yıldız,

Titremeye baslıyordum, içimde simsekler kopuyordu,

Aglıyordum,gözyaslarım sel olup gidiyordu.

Gözyaslarımla boğulmak istiyordum...

Ama sen gene anlamadın Beni...

Ben sevdim sen anlamadın Beni...

Bundan sonra da anlama Beni..

Daha fazla tasıyamıyorum seni ve sevgini

(14/10/2003)', 'Hüzünlendim yine bu gece,tabi her gece oldugu gibi, İcimde olan o ask varya o deli ask!  Yine haykırdı sensizlige, yine haykırdı yalnızlıga,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anlama-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar', 'bir-zamanlar-akin-samiloglu-h37yl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar diye başlardı,

Hayatımın aptalca yönleri.

Çocukluğuma verirdim hep.

Peki ya geride kalan gözyaşlarım....! 

Hangi denizde kimbilir.

Uzanırsam tutabilir miyim dersin.? 

Bir uzana bilsem,

Bilirimki o zaman 

Gözlerim bir güneş.

Bir zamanlar güneşimde bir güneşti...

Herşey

Bir zamanlar diye başladı.', 'Bir zamanlar diye başlardı, Hayatımın aptalca yönleri. Çocukluğuma verirdim hep. Peki ya geride kalan gözyaşlarım....!  Hangi denizde kimbil...', ARRAY['Türk Edebiyatı','Şiir','Akın Şamiloğlu']::text[], 8.5, '{"poet":"Akın Şamiloğlu","poet_slug":"akin-samiloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-zamanlar-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum II', 'seni-seviyorum-ii-mehmet-yilmaz-73a2n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'S eni seviyorum,sevgin beni ayakta tutuyor, beni hayata bağlıyor.

E n güzel günlerim bana verdigin yüreginle yasıyor.

N e olursa olsun incitme kanatma o yüregi,

İ zin ver yüregimizi kenetleyip, simsiki saralim birbirimizi.

Sev beni bırakma ellerimi,

En güzel mavilikleri göster yesil gözlerime,

Vaat ettigim bir sevgi sundum tüm benliğine,

İster kır, ister parcala tüm bedenimi, ama sakın ola bırakma beni.

Y asamın boyunca hep senin icin hayal kurup seni bekledim.

O lur olmadık yerde düşlerime giren sendin belkide,

Rahatım simdi cünkü her yerdeyim seninle.

Unutma seninle olan tüm güzellikleri,

Mehmet seninle yasıyor istedigi sadece bir sevgi.

                                                       .......Elbet istedigi senin yüreginde gizli,

                                                   ....... Bir sey  var sende taa yüregimde adını koyamıyorum.

                                                ........Ruh esi derler adına ama bu cevapta yetersiz bulamıyorum.

Ucsuz bucaksız deryasın sanki ve ben yüzlerce fırtınayla savasmıs geminin kaptanı gibi yüreginin kıyılarına vuruyorum.

Seni bambaska bir tutkuyla seviyorum...

(14/02/2004)', 'S eni seviyorum,sevgin beni ayakta tutuyor, beni hayata bağlıyor. E n güzel günlerim bana verdigin yüreginle yasıyor. N e olursa olsun incit...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-seviyorum-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü', 'gokyuzu-mehmet-yilmaz-uvd2f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gökyüzünden kayan bir yıldız gibi düstün yüregime

Öyle bir iz bıraktın ki su yanan gönlümde,

Korunmaya muhtac bir yıldızdı o

Ama simdi söndü sen beni unutu gidince...

Caresizim simdi,yoklugun o kadar acı ki,

Yaraladı tüm bedenimi

Ebediyende silinmeyecek yüregimdeki yaranın izi,

Cünkü özlemin yakıyor beni...

(15/03/2004)', 'Gökyüzünden kayan bir yıldız gibi düstün yüregime Öyle bir iz bıraktın ki su yanan gönlümde, Korunmaya muhtac bir yıldızdı o Ama simdi söndü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gokyuzu-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duymak İstediğim Sözler Vardı', 'duymak-i-stedigim-sozler-vardi-muhtesem-oksel-oj1gt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duymak istediğim, sözler vardı,

Senden bir kez olsun duymadığım.

Ben hiçbir zaman “canın” olmadım.

Söylemediğin cümleler vardı,

Bir kez olsun söyleyemediğin.

 “Seni seviyorum” ilk  baştaydı.

Duyulmamıştır “aşkım” dediğin.

“Seni seviyorum”dan çekindin.

Belki, inat değil seninkisi.

Belki de, söylemekten acizdin.

Söylemek korkutuyordu seni.

Seni tanıdığım günden beri,

Bir gün  söylersin diye bekledim,

Beni ne kadar çok sevdiğini.

Tam iki yıl boyunca bekledim.

Bekledim, bir gün beni sevmeni.

Söylesene  ben  hiç öyle miydim? 

Saklamadım duygularımı ben.

Sen benim aşkımdın, sevgilimdin.

Sen benim kalbimdin, bebeğimdin.

“Seni seviyorum İlkay”, derdim

Zorla lütfedip “ben de” dediysen,

Kendimi şanslı kabul ederdim.

Ne hissettiysem sana söylerdim.

O günü hiç hatırlıyor musun? 

Haziran ayının yedisiydi.

Bir tuhaftın o gün, huzursuzdun.

İlk defa böylesine mutsuzdun.

Ağzındaki baklayı çıkardın.

“Artık ayrılmalıyız” diyordun, 

Yaşananlar bitsin istiyordun.

Neden ayrılalım? diye sordum.

Sesin titriyor ve ağlıyordun.

“Neden mi? ” dedin, “belli değil mi? ”.

“Koca aptal seni seviyorum”

Sonunda duydum istediğimi.

Sonunda istediğimi duydum.

Böyle mi olsun istemiştim ben.

Neden dört dörtlük olmaz  ki,neden? 

17.11.2003', 'Duymak istediğim, sözler vardı, Senden bir kez olsun duymadığım. Ben hiçbir zaman “canın” olmadım. Söylemediğin cümleler vardı, Bir kez olsu...', ARRAY['Türk Edebiyatı','Şiir','Muhteşem Oksel']::text[], 8.5, '{"poet":"Muhteşem Oksel","poet_slug":"muhtesem-oksel","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/duymak-istedigim-sozler-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyor', 'bilmiyor-ferit-teksoy-x2t55', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneş batarken yanan ufuklar gibi

Yüreğimde yangın sönmek bilmiyor

Seni benden alan herşeye küstüm

Bu hasret,bu özlem bitmek bilmiyor

Kapkara bir kâbus bana geceler

Sabahlar bir türlü olmak bilmiyor

Sensizlik beynimi yiyen bir böcek

Ne yapsam beynimden gitmek bilmiyor

Sana kızamıyor,küsemiyorum

İçimdeki sitem bitmek bilmiyor

Suçlu arıyorum,bulamıyorum

Feryadım,figanım dinmek bilmiyor

Alın yazısı mı nedir? ..bilinmez

Yazan silip bizi yazmak bilmiyor

Beklemekten sabır taşı çatladı

Dualar yerine varmak bilmiyor', 'Güneş batarken yanan ufuklar gibi Yüreğimde yangın sönmek bilmiyor Seni benden alan herşeye küstüm Bu hasret,bu özlem bitmek bilmiyor Kapkar...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilmiyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Ben', 'neden-ben-mehmet-yilmaz-ovmrr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bak gene gece oluyor,

Yine karanlık, yine ısık yok odamda.

Yine yalnızlıgıma soruyorum bunun hesabını,

Neden diye sorma bana! 

Sen sürükledin beni karanlığa...

Hiç bir asktan korkmazdım,sen beni korkuttun,

Askın sevginin oldugu bu hayattan beni soguttun.

Ne gerek vardı tüm bunlara,

Dürüst olmak varken neden sıgındın yalana

Payalasmak varken Neden kacıp gittin? 

Gene elimde sigaram, gene karsımda toz duman.

Göremiyorum artık yasamı,

Askı sevigiyi göremiyorum..

Tek caldıgın bu degildi! 

Güzel gözlüm derdin bana simdi degilim bakma bana! 

Neden diye de sorma bir daha,

Neden sensin ey yar! 

Tüm bunların nedeni sensin...

Karsına soyunup cıkmıstım,

Hayatta olan ne cirkin,ne kötü seyler varsa hepsinden arınmıstım...

Dürüstlügümle güvenimle yeri geldi saflıgımla cocuksulugumla cıktım karsına,

Anlayamadın...

Simdi Neden içinde kaybolmaya mahkum ediyorum seni.

Cünkü bu askta olan Tek gercek Neden...

(31/03/2004)', 'Bak gene gece oluyor, Yine karanlık, yine ısık yok odamda. Yine yalnızlıgıma soruyorum bunun hesabını, Neden diye sorma bana!  Sen sürükledi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/neden-ben-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bir Anlata Bilsem Sana Olanları', 'ah-bir-anlata-bilsem-sana-olanlari-cemil-akkaya-zvo4s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zamanı bitmiş bir bilet

raylara takılmış bir mektup

sonu belli olmayan denizler

yada bir avuç göz yaşı

dolduramaz sendeki aşkı

düşen her damla

sahildeki kum taneleri

güneşin parlaklığı

anlatamaz sendeki aşkı

yada seni seven yüreğim

seni özleyen gözlerim

belkide seni sende kaybeden hasretim

anlatamaz sendeki aşkı

yada avutulması zor özlem

yada silinmesi zor bir leke

yada sen sen

silenmesi zor bir aşk

yada sensizlik

tıpkı sensizliği

bir defada anlatmaya çalışmak

inan yetmiyor özlemini

anltmaya hiç bir mısra

anlatamıyor sana olan özlemimi

anlatamıyor sana olan sevgimi', 'zamanı bitmiş bir bilet raylara takılmış bir mektup sonu belli olmayan denizler yada bir avuç göz yaşı dolduramaz sendeki aşkı düşen her dam...', ARRAY['Türk Edebiyatı','Şiir','Cemil Akkaya']::text[], 8.5, '{"poet":"Cemil Akkaya","poet_slug":"cemil-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ah-bir-anlata-bilsem-sana-olanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeşme''de Akşam', 'cesme-de-aksam-yusuf-ziyaeddin-sivaslioglu-2keaj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çeşme''de seyret akşamı

Unutturur gamı, hazanı

Sakız üstünde batarken güneş

Yunanlı ile olursun kardeş

Sonra Ay çıkar doğudan

Mavi sularda görürsün yakamozları

Sürüklerken peşinde yıldızları

Hatıramda canlanır Ege Kızları

İnbatla birlikte soluk alır

Çay bahçeleri, rıhtımdaki kahveler

Birden gözümde canlanır

İnebahtı''nda yitirdiğimiz leventler.

(Çeşme, 23 Mayıs 2004)', 'Çeşme''de seyret akşamı Unutturur gamı, hazanı Sakız üstünde batarken güneş Yunanlı ile olursun kardeş Sonra Ay çıkar doğudan Mavi sularda gö...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cesme-de-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanırdım', 'sanirdim-yusuf-ziyaeddin-sivaslioglu-7v3n6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanırdım, ilk aşkım

Son aşkım olacak

Sanırdım, ilk aşklarım

Hep hatırlanacak

Sanırdım, hayat

O''nunla birlikte duracak

Sanırdım, şarkılardaki gibi

Leyla, Mecnun''un olacak

Son aşkım,son sevgilim

Yıllardır elimdedir elin.

(İstanbul, 11 Mayıs 2004)', 'Sanırdım, ilk aşkım Son aşkım olacak Sanırdım, ilk aşklarım Hep hatırlanacak Sanırdım, hayat O''nunla birlikte duracak Sanırdım, şarkılardaki...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sanirdim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Editörün Seçimi', 'editorun-secimi-yusuf-ziyaeddin-sivaslioglu-sms94', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Editörün seçimi böyle

Seçim oturmamış gönüllere

Nasıl bir seçim böyle

Lütfen editörüm söyle

Editörün seçimi benziyor

Bizdeki birinci lig maça

Bakmıyor ne göz, ne de kaşa

Seçiminle Editörüm bin yaşa

(İstanbul, 2 Mayıs 2004)', 'Editörün seçimi böyle Seçim oturmamış gönüllere Nasıl bir seçim böyle Lütfen editörüm söyle Editörün seçimi benziyor Bizdeki birinci lig maç...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/editorun-secimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanırdım Bütün Aynaları', 'kiskanirdim-butun-aynalari-hikmet-karakus-axcw4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrılığın şansı yoktu; 

Zincire vururdum zamanı,

Devirirdim dağları,

Kıskanırdım   bütün aynaları 

        sana gülümser diye..

Anlayacağın; 

      seni  böyle sevmiştim,

Oysa şimdi; 

       kalbim senin ellerinde

       paramparça

       paramparça...

(Ank.2004)', 'Ayrılığın şansı yoktu;  Zincire vururdum zamanı, Devirirdim dağları, Kıskanırdım   bütün aynaları          sana gülümser diye.. Anlayacağın;...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiskanirdim-butun-aynalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleme...!', 'bekleme-musfik-saltik-073bo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçinden geliyorsa  birisi için bir şeyler yapmak yap.

Sevgi vermek istiyorsan birisine ver.

Fedakarlık etmek  istiyorsan birisi için et.

Çabalaman gerekiyorsa güzel şeyler  için çabala.

Sana  kötülük edene iyilik etmekse senin doğrun et.

Sevdiğinin peşinden koşman gerekiyorsa koş.

Yardım isteyenden  yardımını esirgeme

Hayatın boyunca mutlu olmak, kırılmamak 

Hep dimdik ayakta kalmak yıkılmamak  istiyorsan

Asla karşılık ve vefa bekleme.

                                                       Haziran 2004', 'İçinden geliyorsa  birisi için bir şeyler yapmak yap. Sevgi vermek istiyorsan birisine ver. Fedakarlık etmek  istiyorsan birisi için et. Çab...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bekleme-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime ne', 'kime-ne-ufuk-nazim-6rpbi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çaresiz bir surum.

Zamanın kıyısına

Mıh gibi çakılmışım 

Kime ne.

Heybetime 

Kartallar konamaz

Dağların usunda 

Bulut bulut dolanır

Bakışlarım

Kime ne.', 'Çaresiz bir surum. Zamanın kıyısına Mıh gibi çakılmışım  Kime ne. Heybetime  Kartallar konamaz Dağların usunda  Bulut bulut dolanır Bakışlar...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kime-ne-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğüm', 'dugum-ufuk-nazim-joik0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dolanası bir düğüm.

Sevgi dolu bir nehir.

Kör düğümleri çöze çöze

Akıyor nehir.

Damar damar 

Katıyor canını cana

Öylesine duru

Öylesine mavi mavi

Akıyor altında günün.

Akıyor sevda sevda.', 'Dolanası bir düğüm. Sevgi dolu bir nehir. Kör düğümleri çöze çöze Akıyor nehir. Damar damar  Katıyor canını cana Öylesine duru Öylesine mavi...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dugum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soluklanıyor Gün', 'soluklaniyor-gun-ufuk-nazim-gu2ov', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soluklanan gün.

Bir kuyu dibi.

Karartılmış bir ünlem.

Sağaltılmış bir yara.

Irmak sesinden.

Orman nefesine yayılan

Derin bir soluk bu.

İşte gün soluklanıyor gene

Derin bir kuyunun

Karanlık dibinde

İnadına kana kana 

Soluk alıyor.

Ormanların nefesine 

Ilgıt ılgıt 

Katıyor ışığını

Gün soluklanıyor.', 'Soluklanan gün. Bir kuyu dibi. Karartılmış bir ünlem. Sağaltılmış bir yara. Irmak sesinden. Orman nefesine yayılan Derin bir soluk bu. İşte ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soluklaniyor-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüyen Yürekdi', 'buyuyen-yurekdi-ufuk-nazim-izvqj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sulanan neydi

Susayan zamanda

Susan neydi

Eskirken çığlıklar.

Çığlar büyürken

Çağıldayan neydi.

Gölgesinde günün

Büyüyen yürekti.', 'Sulanan neydi Susayan zamanda Susan neydi Eskirken çığlıklar. Çığlar büyürken Çağıldayan neydi. Gölgesinde günün Büyüyen yürekti....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/buyuyen-yurekdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandı', 'uyandi-ufuk-nazim-5f54e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soluk bir bahar sabahı

Uyandı.

Ellerinde 

Uyuşup kalmış iki göz.

Ovuşa ovuşa

Kıpkızıl iki güneşe dönmüşdü.

Sessizliği dinledi.

Aynadan yansıyan yabancıya

Uzaktan yan bir bakış fırlattı.

Olağan bir sıradanlıkla

Günlük uğraşlara daldı.

Ve pencerernin perdesini araladı

Yıllarca ona umut olan

Ufkun kızıl tonajları

Kızıl bir kement gibi

Boğazına dolanıyordu.

Soluksuz kaldığını hissetti

Perdeyi kapadı.

Susamıştı

Elleri ne kadarda güçlüydü

Avuçlarında çalkalanan suyun

Berraklığını izledi

Avuçlarından çizgi çizgi

Boğum boğum 

Aydınlık içer gibi

Kana kana içti hayatı.

Şimdi ne yapmalıydı.

İnsanların arasına 

Nasıl karışacaktı.

Ah beyaz kanatlarıyla

Sonsuz mavinin sınırsızlığında

Süzülebilseydi.

Her şeyin üzerinde

Sade beyaz bir martı

Kanat kanat

Özgürlük ve sadelik içinde.

Gerçekler acı

Puslu bir havada

Sırtlanların arasına nasıl karışılır

Yaralanmadan.', 'Soluk bir bahar sabahı Uyandı. Ellerinde  Uyuşup kalmış iki göz. Ovuşa ovuşa Kıpkızıl iki güneşe dönmüşdü. Sessizliği dinledi. Aynadan yansı...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/uyandi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARANLlKLARDAN...', 'karanllklardan-baki-son-ep9dz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ışık...

Vurmaz pencerelerden.

İşte yine,

Yalnızım...! 

Gün ışıkları istiyorum

Karanlıklardan...

Yabancı sesler yükseliyor

Uzaklardan...! 

Başka yüzler görüyorum,

Gölgende...! 

Bak karşındayım işte...

Kapındayım.! 

Yalnızlığımla,

Seni bekliyorum...

Gün ışıkları istiyorum,

Karanlıklardan...', 'Bir ışık... Vurmaz pencerelerden. İşte yine, Yalnızım...!  Gün ışıkları istiyorum Karanlıklardan... Yabancı sesler yükseliyor Uzaklardan...!...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karanllklardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toz zerreleri', 'toz-zerreleri-ufuk-nazim-ph7fw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Irayan neydi

Yüreğinin tınısında eriyen

Zamana inat.

Çırpınışların elbet 

Bir sebebi vardı.

Uçsuz bucaksız kırların

Eşssizliğinde

Soluksuz koşmak.

Evet amaç ırayana,

Uçana kaçana

Bir amaç lazım.

Her yol bir hedefe varırken,

O yaman bir hızla

Uçarcasına geçtiğini sanıyordu.

Ama oda sıradandı aynıydı.

Peki nedeni neydi

Bu sıradanlığın.

Sonsuzluğun ortasında

Toz zerreleri

Hep aynıydı.

Rüzgarlardı onları farklı kılan.

Asi devingen rüzgarlar.

Savrulan bir toz zerresiydi o

Bulut bulut yayılan uçuşan.

Fark devinimde.', 'Irayan neydi Yüreğinin tınısında eriyen Zamana inat. Çırpınışların elbet  Bir sebebi vardı. Uçsuz bucaksız kırların Eşssizliğinde Soluksuz k...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/toz-zerreleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşleri', 'gulusleri-ufuk-nazim-sieg4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çıktı evden

Ağır ağır adımlarla yürüyordu

Issız bir adada gibi

Sanki etrafında kimseler yok

Adımları emin

Boynu eğik

Belli çoktan 

Kaldırımlara akmış düşleri.

Gülüşleri

Taşlar kadar eski

Ve soğuk.', 'Çıktı evden Ağır ağır adımlarla yürüyordu Issız bir adada gibi Sanki etrafında kimseler yok Adımları emin Boynu eğik Belli çoktan  Kaldırıml...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gulusleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşine Gidiyor', 'i-sine-gidiyor-ufuk-nazim-cgbs5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İşte memur oldu 

İşine gidiyor

Düşün ufukları daraldı

Soluğu azaldı İşte memur oldu 

İşine gidiyor

Düşün ufukları daraldı

Soluğu azaldı 

Ve inancı yaşama

Bir masanın

Soğuk zemini kadar donuk.

Dar bir kalıpda yoğrulan

Ekmeğe erecek 

Hamur gibi.

Ama bitecek 

Çabucak tükenecek

Düş gibi.', 'İşte memur oldu  İşine gidiyor Düşün ufukları daraldı Soluğu azaldı İşte memur oldu  İşine gidiyor Düşün ufukları daraldı Soluğu azaldı  Ve ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/isine-gidiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın en çekilmez anları', 'yasamin-en-cekilmez-anlari-ahmet-kose-1pncm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşte....! 

yaşamın en çekilmez anları

...istemez,

bilmiyorum,

farketmez,

sıkkınım,

olmaazz,

şimdi değil,

belki,

yarın olur,

gidesim yok,

ne olacak ki,

düşünürüz,

anlamam,

yapamam,

karışmam,

ben yokum,

triplerinde geziniyorum hiç kımıltısız 

bu bulanıklığında maviliğin

soramam kimseye

bir külün içinde unuttum yüreğimi

bilmiyorum ne zaman çıktı yangın 

kimlerdi kurtulan

kimde ne izler kaldı

elimde kalan kimdi

yüreğimi küllerde bırakan.

Ölü aşk bedenleri mezarlığımda

coşkulu küreklerim

sızılı kazmalarım

çukurlar açıyorum.

Yaşamın en çekilmez anları

yüreğin kazıldığı anlar.

5/Haz./04/bitez', 'İşte....!  yaşamın en çekilmez anları ...istemez, bilmiyorum, farketmez, sıkkınım, olmaazz, şimdi değil, belki, yarın olur, gidesim yok, ne ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yasamin-en-cekilmez-anlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ancak Ölüm Ayırır', 'ancak-olum-ayirir-erdal-sayil-ts04a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Parmağına batan diken,

Yüreğimde mızrak olur...

İncitip de seni üzen; 

Elimdeyse helak olur...

Her halini ayrı sevdim,

Bambaşka,apayrı sevdim,

Zannetme ki gayrı sevdim; 

Sensiz dünyam çorak olur...

Senelerce aradım ben,

Dünyaları taradım ben,

Bir tek işe yaradım ben; 

Sana açık kucak olur..

Güllerden mi,çileden mi...? 

Doğruluktan hileden mi...? 

Gönülden mi,sineden mi...? 

Senin aşkın tuzak olur...

Gönüllüce yakalandım,

Bile-bile yaralandım,

Kapalıydım,aralandım; 

Senden geçmek uzak olur...

Her anımda sen yaşarsın,

Belki sevgiyle aşarsın,

Ancak sevgiyle uçarsın; 

Birliğimiz ap-ak olur...

Seni sevdim,özüm budur,

İster güldür,ister soldur,

Gönlümdeki istek budur; 

Ancak ölüm firak olur...', 'Parmağına batan diken, Yüreğimde mızrak olur... İncitip de seni üzen;  Elimdeyse helak olur... Her halini ayrı sevdim, Bambaşka,apayrı sevdi...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sayıl']::text[], 8.5, '{"poet":"Erdal Sayıl","poet_slug":"erdal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ancak-olum-ayirir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır Hayat Gül', 'sir-hayat-gul-zafer-zengin-etnika-c4vd3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Namlu üstünde

Çiban çıkar içinde

Gülemezsin bile bile

Gözün hep içinde

Dönsem mi 

Bir darbelik hınçtır yalan

Öksüz ölümlerin gölgesi

Saklayamaz gerçek ışığı

Aniden mi olsa kopuş

Sindire sindiremi

Ağır yerinden kalkmıyorken

Akıl veren rüzgar sesleri

Saklıyor niyeti

Masalara gömsen elini

Cekip gider mi dili

Nasıl anlatılır

İçimdek i ben

Kaç dil

Kaç lüğat lazım

Haytamı zekanın boşluğu

Harami türküleri söylettin dost

Bile bile kestin elimi

Bile bile zehrettin yüzümü

/  Demiştim toprak sevmez tohumdan ayrılmayı

Büyütür 

Sesini dinler

Kaybedeceğini bile bile

Güler yüzüne

Ekmek olur

İner mideye /

Gülsem/Gül/sen 

Sırmıdır kendi bildiğim/Hayat...

9 Haziran 2004 '' Kan konuşmaz''', 'Namlu üstünde Çiban çıkar içinde Gülemezsin bile bile Gözün hep içinde Dönsem mi  Bir darbelik hınçtır yalan Öksüz ölümlerin gölgesi Saklaya...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sir-hayat-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Sıcak Alev Lekesi *', 'sicak-alev-lekesi-mehmet-kizilay-ne1ig', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ateşin yakmaktan aciz kaldığı

sevgimi../.. yüreğinde sakladığım

____________gülün yaprağı

ateşe verilmiş yabani bir

korkaklıkla..

aylarca yanan ateşten

sıcak alevin lekesi düşmüş

gülün yüzüne

erişememiş o gül yüreğine..

dokunamamış sevgime..

gaye ısınmaksa...(?) 

üşümemenin kuralı ise 

başkalarının evini yakmak

DONDUR BENİ ALLAH''IM..!', 'ateşin yakmaktan aciz kaldığı sevgimi../.. yüreğinde sakladığım ____________gülün yaprağı ateşe verilmiş yabani bir korkaklıkla.. aylarca ya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sicak-alev-lekesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kamuflaj', 'kamuflaj-nilay-aksu-xausf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-aynası üşüyen birine-

‘aşk kansız bir cinayettir’ diyor biri

delilleri topla, izleri yok et

ışıkları yakmadan git 

bir ölüyü daha vurup sırtına

sana yeni bir yol gerek 

bunca kırık düş batmışken ayaklarına

nerede, ne zaman açıldı ruhunda bu onulmaz yara? 

her şeyi sil baştan yaşamak masallara yakışır

şimdi gece gündüz aynı masalı anlat dur

hayatı ıskalamış bir adama

bir yokmuş ve hiç olmamış diye başlayan

çilingiri senmişsin gibi bütün kilitli kapıların

gülümseyerek gir içine, sarsılarak boşal! 

sevmek ağır bir ölümdür kimilerine

içinden yol geçen bir dağa baka baka

sessizce ölünür, sessizce sevişmeyi beceremeyecek kadar

yalındır, yalansızdır,yalnızdır sevmek ağır bir ölümdür kimilerine

kimse inanmıyor ki  mutluluk sözcüğüne

lambayı söndür, perdeyi çek

soyun yalanlarını, sevişme izlerini sıyır

annene bağır: ‘aynam üşüdü, ısıt! ’

sana yeni bir yol gerek şimdi

yeni bir cinayet

yaşamak bundan böyle

-ağzında kekre bi’ kavun tadı-

G ü l ü m s e m e k', '-aynası üşüyen birine- ‘aşk kansız bir cinayettir’ diyor biri delilleri topla, izleri yok et ışıkları yakmadan git  bir ölüyü daha vurup sır...', ARRAY['Türk Edebiyatı','Şiir','Nilay Aksu']::text[], 8.5, '{"poet":"Nilay Aksu","poet_slug":"nilay-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kamuflaj-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Hayal', 'bos-hayal-aras-gurler-prrc4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'boş hayaldi o

yitti gitti düşüncelerimden

sigaraydım onun elindeki

söndürdü beni kendi derim üzerinde

söndüremedi hiç, hiç sönmem ben

yanıoyordum hala elinde

o bana bakmadan çöpe boşalttı

düştüm bende hiç ses çıkaramadan

sesim filtremden geçmedi

geçemedi sesim, emdiler sesimi

düştüm hala yanarken ben

anlamadın sen yandığımı

attın yere elini yakmadan ben

yakamadım elini, 

birşey hissettiremedim sana

biteceğim belliydi ama senin elindeydim

değerlendiremedin son kalıntımı

değerlendiremedim bende zamanı

zamanı geldiğinde bitmek yerine

çok hızlı yandım, çok çabuk içirttim kendimi

her tütünüm yandı benim

sen yaktın hepsini, beni mazoşistliğimle

yaktın hepsini sen, acıyı en isterken ben

istemedende olsa isteyemedim ben seni

dönemedim tekrar parmaklarının arasına

düşerken ben,

kıvılcımlarımı boşluğu aydınlatmak için kullandım

yapamadım, dönemedim dudaklarına

çekmen için birkez daha

dileyemedim allahtan, kendi elimle kendimi söndürmeyi...', 'boş hayaldi o yitti gitti düşüncelerimden sigaraydım onun elindeki söndürdü beni kendi derim üzerinde söndüremedi hiç, hiç sönmem ben yanıoy...', ARRAY['Türk Edebiyatı','Şiir','Aras Gürler']::text[], 8.5, '{"poet":"Aras Gürler","poet_slug":"aras-gurler","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bos-hayal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yaptın?', 'ne-yaptin-aras-gurler-re09e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'naptın sen bana

bana ne yaptın sen

ne oluyor bana

bana ne oluyor göremiyorum

anlatmıyorlar bana ne oluyor

söylemiyorlar

hiçbir ayna 

göstermiyor düşlerimi

düşüncerimi gösteremiyor

kırılıyor aynalar

bana ne oldu? 

oldu bana ne? 

bir yerden düştüm 

ayağa kalkamıyorum

kalkamıorum ayağa

düştüm bir yerden

ittin beni bir yerden

itildim ben kendimi atarak

atıldım bir metrelik dev uçurumdan

neden bu kadar yara aldım? 

kırıldı bir taraflarım

bana ne oluyor şu anda

neler oluyor bana

göremioyurum anlatmıyorlar

söyleyin diorum acı acı bakanlara

ağızlarını açamıyorlar

kelime ses dönüşüyor 

ses anlamsızlığa

çıkmıyor senin adın ağzımdan

kaslarım çalışamıyor

istemsiz söylüyorum adını artık

neler oluyormuş bana anlamıorum

cümleler uzuyor 

kelimeler kısalıyor artık

tükenmektemiyim söylemiyorlar

bitmedim onu biliyorum sanki

biraz önce birşeyler olmuş bana

ben delimi oluyorum yoksa? 

söylüyor yok birşeyin geçer

geçmiyor düşünemedikçe

düşündükçe dahada acıyor

anlamadım neler oldu oluyor olmuş

sen bana anlatmadın hiçbir zaman

ne yaptığını bana...', 'naptın sen bana bana ne yaptın sen ne oluyor bana bana ne oluyor göremiyorum anlatmıyorlar bana ne oluyor söylemiyorlar hiçbir ayna  gösterm...', ARRAY['Türk Edebiyatı','Şiir','Aras Gürler']::text[], 8.5, '{"poet":"Aras Gürler","poet_slug":"aras-gurler","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ne-yaptin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamalar Yakışır Bize Bulutlu Ağlamalar', 'aglamalar-yakisir-bize-bulutlu-aglamalar-nevin-kurular-u5ktq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saymadık,

kaç güneş çiğnedi ufukları 

bir sigara içimlik zamanı bölüşmeden geçirdiğimiz

tüketirken anları

aramadık neredeydik biz.

yazılmamış şiir kadar özgür sanırdık değerlerimiz.

Mavi sulara bıraktık kaderi keyfince

umutlar sahipsiz.

Ağustos ortasında beklenilen

puslu eylül gibiyiz.

Ağlamalar yakışır bize artık

Bulutlu ağlamalar

Bilmeliyiz.

Vuslatlar,

öksüz istasyonların

raysız trenleri kadar çaresiz.

Arzular silinmiş yol haritasında 

ıslıklarla söylenir

sazsız,  sözsüz türkülerimiz.

Birlikte taşınmalı 

yanarsa yansın yüreğimiz  ormanlarca

buz basarız yaramıza  dağlarca hissetmeyiz.

Kanarsa kanasın 

mendile sakladığımız gözlerimiz

belki:

rastık kadar yakmaz gözleri gün gelir

şehrin sokaklarındaki iz.

Mutlu iki  çocuk gibiydik oysa

O yollarda  ikimiz.', 'Saymadık, kaç güneş çiğnedi ufukları  bir sigara içimlik zamanı bölüşmeden geçirdiğimiz tüketirken anları aramadık neredeydik biz. yazılmamı...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aglamalar-yakisir-bize-bulutlu-aglamalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Albümde Saklı Hayal Olduk Şimdi...', 'albumde-sakli-hayal-olduk-simdi-nesrin-gocmen-bewoa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu kadar uzakta olmasa idik,

Şu anda yanına koşar gelirdim....

Albümde, mazide kalmasa idik,

Kükremiş sel olur, coşar gelirdim.......

11/06/2004', 'Bu kadar uzakta olmasa idik, Şu anda yanına koşar gelirdim.... Albümde, mazide kalmasa idik, Kükremiş sel olur, coşar gelirdim....... 11/06/...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/albumde-sakli-hayal-olduk-simdi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldüğümü Farzettim / deneme', 'oldugumu-farzettim-deneme-k-muran-esen-sa15q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Evde yalnız olduğum bir gündü. Nedense birden ölüm geldi aklıma. Her zaman, sevdiklerimin yokluğunu; onların yokluğunda ne yapacağımı düşünürüm, ama bu kez kendi yokluğumu düşündüm. Bir an için öldüğümü farzettim.........  “Ölsem, annem, babam, kardeşlerim, kızım, eşim, arkadaşlarım ne yaparlar acaba? ” dedim.

Yokluğumda uzaktan, yakınlarımın neler yaptığını izledim. Ölümümün; dünyada hiçbir şeyi değiştirmediğini, yakınlarımı pek etkilemediğini gördüm. Ne kadar sıradan biriymişim meğer. Dünyada herşey sağlığımdaki gibiydi. Yaşam devam ediyordu. Bir tek ben yoktum,  o kadar. 

Ablam, kardeşlerim eskisi gibi yoğun iş temposunda idiler. Acıktıklarında yemek yiyorlar, susadıklarında su içiyorlardı. Normal yaşantılarını sürdürüyorlardı. Sanki  ne ben ölmüştüm, ne de onlar beni kaybetmişlerdi. Ağır yaşam koşulları, yokluğumu unutturmuş olmalıydı onlara. Yoksa  böylesine bir kalemde silip atamazlar beni.

Evimde bazı eşyalar değişmişti. Koltuklar, kanepeler farklıydı. Son öğrencilerimle çektirdiğim ve bilgisayar masamda duran fotoğraf yoktu. Vestiyerde ne hırkam vardı ne yağmurluğum.Ayakkabılarım kalkmış, onların yerine başka bayan ayakkabıları konmuştu. Banyoda; saç fırçalarımı, fön makinemi, deodorantımı de göremedim.

Eşimin yanında bir kadın vardı. Benden  genç ama çirkin bir kadın. Güzel görünmek için çok çaba vermiş  fakat  bu konuda hiç de başarılı olamamış bir görüntüsü vardı. Kanepeye yanyana oturmuşlardı eşimle. Sağlığımda, hiçbir kadını eşime bu kadar yakın görmemiştim...Eşim  çok mutlu görünüyordu  yanında Beni çoktan unutmuş bir hali vardı. Birlikte televizyon izliyorlardı.  Bunu pek yapmıyorduk sağlığımda. Çünkü tv izlemeyi pek sevmezdim. 

Ama eşimin mutlu görüntüsüne hiç inanmadım, inanmak istemedim. Otuz yıl yanında olan, yatağını ve bedenini ısıtan, birçok şeyi paylaştığı bir kadını, bir kalemde silip atmak öyle kolay olmamalı. Ben onun eskimiş ayakkabısı gibiydim. Biraz deforme olmuş, ama ayağının şeklini almış ve o nedenle en rahat edebildiği ayakkabısı gibi. Hiçbir yeni ayakkabı içinde rahat edemez o. Eski ayakkabısını arar, biliyorum.

Sonra babamı gördüm. Sakalları iyice uzamış, yüzündeki çizgiler daha da derinleşmişti. Bakışlarını belli bir noktaya dikmiş, dalıp gitmişti. Hep kendisini kaybetmekten korkardım sağlığımda.Yüreğinin, evlât acısıyla böyle kavrulacağını hiç aklıma getirmemiştim. Avcuna sıkıştırdığı mendil ilişti gözüme. Canım babacığımın benim için göz yaşı döktüğünde kullandığı, gözyaşlarını gizlediği mendil..

Kızım, genç yaşına rağmen  olgun bir kadın görünümündeydi. Yorgun, bitkin, üzgündü. Gözleri kan çanağına dönmüştü ağlamaktan. Kendisiyle birlikte ağlayacak, acısına ortak olacak bir kardeşi olmadığı için, bunu kendisinden esirgediğim için, bana kızıyor olmalıydı. Odanın duvarlarında fotoğraflarım vardı. Bu fotoğrafların birinde; kızımla başbaşa vermiştik. Hatırlıyorum, piknikte çekilmişti bu fotoğraf. Rüzgâr saçlarımızı uçuşturmuş, bir kısmını yüzümüze indirmişti. Hatta  bu fotoğraftaki perişan halimizi gören ve o zaman henüz beş- altı yaşında olan yeğenim; “ Hala! Bu fotoğrafı çektirdiğinizde siz çok mu fakirdiniz? ” diye sormuştu. Öylesine perişan bir görüntümüz vardı fotoğrafta.

Öğrencilerim  hayal kırıklığına uğrattılar beni. Çoğu, ölümümden habersiz görünüyordu. Benden aldıkları ilk  feyzi, coşkuyu, azmi çoktan unutmuş gibilerdi. Sanki ömürlerinin beş yılını benimle birlikte geçirmemişlerdi. Onların gözünde; yaşını başını almış, yıllarca öğretmenlik yaptıktan sonra emekli olmuş, hatta belki de yaşlı bir öğretmendim ben. Onlara göre, yaşım öyle büyüktü ki.

Giysilerimin hiç biri yoktu gardıropta.Öğrencilerimin karşısına özenli bir şekilde çıkmak  için ne çok giysi alırdım sağlığımda. Hiç biri yok şimdi. Öğrencilerime veda ederken üzerimde olan, her giydiğimde  bana okuldaki son günümü hatırlatan kırçıllı lâcivert takımım yok. Kahverengi döpiyesim, bej döpiyesim, kemik rengi döpiyesim de yok. Ya o çeşit çeşit çantalarım? Onlar nerdeler acaba? Bir çantam vardı, büro tipi, kahverengi. O çantamı çok severdim. Çok büyüktü. İçine, aklıma ne gelirse koyardım. Öğrencilerime lâzım olur diye yara bantları, kâğıt mendiller, kurşun kalemler, saçı dağılan öğrencilerin saçlarını toplamak için tokalar, daha neler neler. Bu çantayı taşımaktan sol elimin avcu nasır tutmuştu. Emekli olduktan bir süre sonra, bu nasır kaybolmuştu. Çok üzülmüştüm. Mesleğime, öğrencilerime ait bir işareti kaybettim diye.

Evimin pencere kenarlarındaki, bahçedeki çiçekler bakımsızdı. Belli ki onlara, vitamin hapı veren yoktu. Kendi vitamin haplarımdan verirdim onlara. Onlar da çoştukça coşarlar, renk renk açarlardı. Şimdi ise sararan yaprakları, solan çiçekleriyle kötü bir görüntü veriyorlar.Yokluğum, hemen belli oluyor çiçeklerin görüntüsünden.

Peki ya arkadaşlarım? En çok onlar şaşırttı beni, en çok onlar hayal kırıklığına uğrattı. Sohbetlerinde adım  hiç geçmiyordu. Beni çok sevdiğini sandıklarım hatta emin olduklarım bile, yokluğuma çoktan alışmışlardı. Birlikteyken anlattığım fıkralara gülenler, sohbetimi tatlı bulanlar sanki onlar değillerdi. Hiç birini üzgün görmedim.Yokluğum, televizyonda severek izlenen bir dizinin sonu gibiydi sanki onlar için.Yapımcılar, ya devamını çekerler ya da onun yerine yeni bir dizi yaparlardı. Bana olan sevgileri; bu kadar mı yüzeyseldi, bu kadar mı pamuk ipliğine bağlıydı? 

Peki ya annem? Annemi zor tanıdım. Nasıl değişmiş! Birden yaşlanmış. Baktığı yeri görmüyor gibi. Seccadenin başında namaz kılıyordu. Gözleri, çukurlarına iyice çekilmişti. Omuzlarına yüklenmiş bir ağırlığın altında eziliyor gibiydi.....Sonra kalktı seccadeden. Adeta iki büklüm oturdu kanepeye. Gözlerinin pırıltısı yok olmuş. Yokluğuma en çok üzülen o. Yokluğumun en çok etkilediği kişi o. Annemim kalbini, beynini okuyorum adeta. Kendisinden önce çekip gittiğim, onun sırasını aldığım için kahroluyor.

Ölümümün; arkamda bıraktığım, çok sevdiğim birçok kişi için, hiç de dayanılmaz olmadığını anladım.Sağlığımda; birçok kişi için çok değerli, vazgeçilmez, yokluğuma dayanılmaz olduğumu sanırdım. Nasıl yanılmışım! 

İşte bu düşündüklerim, - güya- bu gördüklerimden sonra, ölümden daha da korkar oldum. Ayrıca, varlığımın, birçok kişi için pek de değerli  olmadığını anladım. Yalancı sevgi ve dostluklara  inanmakla ne kadar hata yaptığımı da........Demek  ki, birçok kişi için ben bir hiç’im! Yazık!', 'Evde yalnız olduğum bir gündü. Nedense birden ölüm geldi aklıma. Her zaman, sevdiklerimin yokluğunu; onların yokluğunda ne yapacağımı düşünü...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oldugumu-farzettim-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Mevsimi Kalmadı İstanbul’un', 'mevsimi-kalmadi-i-stanbul-un-guclu-sonmez-veqma', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mevsimi kalmadı İstanbul’un

Ne ilkbaharı, ne de sonbaharı

Ellerime dolu dolu bir kış

Sımsıcak bir yaz bıraktı

İlham perileri

Bulutların ardında 

Denizlerin dibinde saklı

Toprak bile şaşırdı

Bilemedi

Açsa mı çiçeklerini

Dökse mi yapraklarını...

Sen de olmasan bu şehirde

Yazacak bir şeyim kalmazdı

(İstanbul, Haziran 2004)', 'Mevsimi kalmadı İstanbul’un Ne ilkbaharı, ne de sonbaharı Ellerime dolu dolu bir kış Sımsıcak bir yaz bıraktı İlham perileri Bulutların ardı...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mevsimi-kalmadi-istanbul-un-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandırmayın', 'uyandirmayin-burhan-kucuk-69872', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uyandırmayın

Hangi pencereye koşsam

Gün vurmuyor cama

Elimde sigara

Dolamdım durdum tüm gece

Artık uyandırmayın...

Kapatıyorum gözlerimi

Öyle sahte ışıkları

Vurup yüzüme..

Burhan KÜÇÜK

Kdz.Ereğli-11.06.2004', 'Uyandırmayın Hangi pencereye koşsam Gün vurmuyor cama Elimde sigara Dolamdım durdum tüm gece Artık uyandırmayın... Kapatıyorum gözlerimi Öyl...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/uyandirmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken', 'giderken-halil-kesken-bdi33', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir köşeye oturmuş

İçin için ağlıyordun

Belliki yaptıklarından

Pişmanlık duyuyordun

Bir elinde resimler

Mektuplar da yanındaydı

Dizilmişti boş kadehler

Perişan bir halin vardı

Sana verdiğim karanfil

Saçlarında duruyordu

Yanındaki müzik seti

Şarkımızı çalıyordu

O kadar da güzeldin ki

Sanki kesildi nefesim

Herşeyi unutup birden

Sana sarılmak istedim

Seni seviyorum diye

Her an bağırabilirdim

Tam boş vermişken herşeye

Gururumu yenemedim.', 'Bir köşeye oturmuş İçin için ağlıyordun Belliki yaptıklarından Pişmanlık duyuyordun Bir elinde resimler Mektuplar da yanındaydı Dizilmişti b...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/giderken-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğultulu Geceler', 'ugultulu-geceler-nusret-turan-muixo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denizleri coşturan

Kayalara vurduran

Köpekleri kudurtan

Uğultulu geceler

Uykular gitti elden

Geçilmiyor bu selden

Korkulmaz mı bu elden

Uğultulu geceler

Bulutlar küme küme

Umutlar gitti güme

Geceler döndü güne

Uğultulu geceler

Ağaçlar kırılıyor

Ufuklar daralıyor

İçimi karartıyor

Uğultulu geceler

Düşmüşüm gurbet ele

Hayaller düştü sele

Pislikler çıktı bele

Uğultulu geceler

24.03.2004/BODRUM

Saat:03.16', 'Denizleri coşturan Kayalara vurduran Köpekleri kudurtan Uğultulu geceler Uykular gitti elden Geçilmiyor bu selden Korkulmaz mı bu elden Uğul...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ugultulu-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünden Kurbanım', 'dunden-kurbanim-nusret-turan-6hxsb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gelmesin gurbetten acı haberin

Gece gündüz yollarını gözlerim

Yıldızım güneşim inan ki sensin

Yeşil gözlerine dünden kurbanım

Dünya zevklerinden olmaz haberim

Kuşlarla cananım, haber salarım

Bir sesini duysam bayram ederim

Yeşil gözlerine dünden kurbanım

Dünya cilvesine olmaz sitemim

Düştüm hasretime yanar giderim

Uzaklarda kalma hep yanımda ol

Yeşil gözlerine dünden kurbanım.', 'Gelmesin gurbetten acı haberin Gece gündüz yollarını gözlerim Yıldızım güneşim inan ki sensin Yeşil gözlerine dünden kurbanım Dünya zevkleri...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dunden-kurbanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey Senin', 'hersey-senin-nusret-turan-ptr7w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bağlar, bahçeler senin

Bir kurumuş gül benim! ..

Dolar senin, mark senin! ..

Bir gariban dost benim

	

Han senin, villa senin.

Acı, acı aşk benim

Top senin, tüfek senin! ..

Bir kırık, kalem benim.

Havalan çık göklere! ..

Yerdeki böcek benim.

Seni pek çok sevsinler

Bir vefalı yar benim

Antalya-1997', 'Bağlar, bahçeler senin Bir kurumuş gül benim! .. Dolar senin, mark senin! .. Bir gariban dost benim 	 Han senin, villa senin. Acı, acı aşk b...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hersey-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Torun İstiyorum 2', 'torun-i-stiyorum-2-nusret-turan-hrxar', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir elinde yabası

Bir elinde kaması

Dokuz dağın belası

Bir Torun istiyorum

Kartalda oynayacak

Güzel goller atacak

Dünyaya taç olacak

Bir Torun istiyorum

Yeşil yeşil gözleri

Şeker gibi sözleri

Tüm kızların özlemi

Bir Torun istiyorum

Özden ödün vermemiş

Haram lokma yememiş

Hile nedir bilmemiş

Bir Torun istiyorum

Ata’sını bilecek

Vatanını sevecek

Uğruna can verecek

Bir Torun istiyorum

31.03.2004/BODRUM', 'Bir elinde yabası Bir elinde kaması Dokuz dağın belası Bir Torun istiyorum Kartalda oynayacak Güzel goller atacak Dünyaya taç olacak Bir Tor...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/torun-istiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masalsız Kız Düşleri', 'masalsiz-kiz-dusleri-tahsin-ozmen-d92po', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Bazı babaların kızlarıyla tek aktivitesi,

               Ya giyeceği ceketi tutturmaktan,

               Ya da yiyeceği yemeği yaptırmaktan ibaretttir.-

Duyguları paramparça, kanatları acı içinde, hayal aleminde,

Bir kere dahi baba masalıyla uyutulmamış,

küçük bir kız çocuğuydum ben.

Yine de, kendi kendimi koynuma alır, 

kocaman kocaman hayaller kurardım.

Belki babam okşar diye sürekli saçlarımı tarardım.

Dışları gibi içleri de güzel olsun diye 

bebeklerime makyaj malzemesi yedirir, entarimdeki gülleri sulardım.

Hiç baba sevgisi tatmadım, 

Çocukluğumu benden söküp alan tokatlar dışında, hiç baba eli tutmadım.

Hayali bir babam vardı,

Ne zaman gök gürlese, onun kucağına atlar boynuna dolanırdım.

Babam bana sarılırsa, içimden kelebek sürüleri havalanacak sanırdım.

Gözyaşlarımı kendim silerdim,

Uyku sorunumu, kendi kendime masallar anlatarak çözerdim.

Hiç sevmezdim ağaçlara bıçak, kuşlara sapan çeken çocukları,

Kağıtlara, dalları kuş dolu ağaç resimleri çizerdim.

Kendimle yemeğe çıkar, kendimle gezerdim.

Hem aklımı hem bedenimi üşütmüşlüğüm çoktu.

Çünkü hep üstü açık yatardım ölümü giyinmiş annemi göreyim diye, 

Bilirdim ki annem üstümü örtmeden hiç yatmazdı.

En çok babasız çocukları vurduğu için, gece ve karanlık yoktu hayal dünyamda,

Altın sarısı saçlarıyla masalcı bir babaydı benim için güneş, hiç batmazdı.

Çocuklara pamuk şekeri yapardım yere indirip bütün bulutları, güneşi bulutlar kapatmazdı.

Gökleri gezdirirdi melekler;

Güneş’in ikizleriymiş Dünya ve Ay,

ölenlerin ruhlarıymış yıldızlar.

Annem doğurmamış melekleri, 

bir gece olsun babalarından masal dinleyememiş kızlarmış onlar.

1999

* Düşünmek Yaşamın Pasını Silmektir, Karina Yayınevi, Ank, 2018', '-Bazı babaların kızlarıyla tek aktivitesi,                Ya giyeceği ceketi tutturmaktan,                Ya da yiyeceği yemeği yaptırmaktan...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Özmen']::text[], 8.5, '{"poet":"Tahsin Özmen","poet_slug":"tahsin-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yureksiz-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayma', 'sayma-i-smet-barlioglu-h75tp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boşadır bu köşkler, kervansaraylar,

Kurduğun düzeni saltanat sayma.

Ömrü tüketiyor bu geçen aylar,

Koyduğun noktayı kainat sayma.

Sana denildi ki; bin kere şükret,

Önce şükür gelir, sonra nedamet,

Atladın sırayı sayarken, hayret,

Bu düzensiz işi bir kerrat sayma.

Kuruttun, yamaçtan akmıyor dere,

Kestiğin fidanlar ölmek üzere,

İşi düzenledin kendine göre,

Kirli fermanını has berat sayma.

Atının sırtında ağır bir eyer,

Hayvanın ağzında gem varmış meğer,

Bunun neresi at? Hele bir göster,

Zavallı esiri yağız at sayma.

Dili tutsak eder vurduğun bağlar,

Dil söz etmez ama içinden ağlar,

Işık hızlı değse delinir dağlar,

Her dağı deleni o Ferhat sayma.

Canın mal içindir, düşüncen para,

İşin dalavere, düzen, dubara,

Gelenler çıkarcı hep yanın sıra,

Böyle bir dostluğu refakat sayma.

Kafan bomboş ise sinen boş olur,

Düşmanın zekiyse hiylen boş olur,

Bir yumruk yedinmi sillen boş olur,

Boşa giden şeyi marifet sayma.

Bir suçu işlerken görülmedinse; 

Yahut görüldün de incinmedinse; 

Epeyce bir zaman ertelendinse; 

Mühlet tanınmıştır, merhamet sayma.

İnsan kafasıyla ancak insandır,

Gücüne güvenen yalnız yabandır,

İnsanın değeri sanma mintandır,

Altından kürk giysen kıyafet sayma.

Tümü görevlidir denizin, yelin,

Gayreti boşadır hiylenin felin,

Sana verilende rızkı var elin,

Bolca verileni atıfet sayma.

Düzenin sırrı var, çarkın sırrı var,

Kanalın sırrı var, arkın sırrı var,

Denkliğin sırrı var, farkın sırrı var,

Sakın tesadüfte isabet sayma.

Barlı der; sözlerim üryan içindir,

Diyet ödedinse rüyan içindir,

Bir bela gördünse dünyan içindir,

O henüz geride; kıyamet sayma.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 316-318/412)', 'Boşadır bu köşkler, kervansaraylar, Kurduğun düzeni saltanat sayma. Ömrü tüketiyor bu geçen aylar, Koyduğun noktayı kainat sayma. Sana denil...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sayma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşmez Kalkmaz Bir Allah', 'dusmez-kalkmaz-bir-allah-i-smet-barlioglu-63zl6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'La ilahe illallah,

Düşmez kalkmaz bir Allah.

Her nefeste bismillah,

Düşmez kalkmaz bir Allah.

Kainat ters çevrilir,

Herşey geri verilir,

Saltanatlar devrilir,

Düşmez kalkmaz bir Allah.

Dönen gökler toz olur,

Yıldızlar yaz boz olur,

Güneş tuzla buz olur

Düşmez kalkmaz bir Allah.

Hazineler pul etmez,

Mal, mülk birlikte gitmez,

Güç bekayı belirtmez,

Düşmez kalkmaz bir Allah.

Sultan düşer çaresiz,

Karun kalır parasız,

Düşmek, kalkmaz sırasız,

Düşmez kalkmaz bir Allah.

Bozulur hasbahçeler,

Devden doğar cüceler,

Gaiptendir silleler,

Düşmez kalkmaz bir Allah.

Saraylardan yel geçer,

Saltanattan el geçer,

Tamahlardan sel geçer,

Düşmez kalkmaz bir Allah.

Bakarsın han kalmamış,

Dizde derman kalmamış,

Damarda can kalmamış,

Düşmez kalkmaz bir Allah.

Yudum içilmez aştan,

Can çekilir yavaştan,

Ten sıyrılır kumaştan,

Düşmez kalkmaz bir Allah.

Yürek porsur bez gibi,

Beden olur buz gibi,

Bakış olur söz gibi,

Düşmez kalkmaz bir Allah.

İstesen bel doğrulmaz,

O bülbül dil doğrulmaz,

Çökmüş o fil, doğrulmaz,

Düşmez kalkmaz bir Allah.

Barlıoğlu hüngürder,

Gönlü gümbür gümbürder,

Dün düştü, yarın düşer,

Düşmez kalkmaz bir Allah.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 319-321/412)', 'La ilahe illallah, Düşmez kalkmaz bir Allah. Her nefeste bismillah, Düşmez kalkmaz bir Allah. Kainat ters çevrilir, Herşey geri verilir, Sal...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/dusmez-kalkmaz-bir-allah-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırdan Konuşak', 'sirdan-konusak-i-smet-barlioglu-x3awp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceler çok uzun, sabah çok uzak,

Uyuma erenler, sırdan konuşak.

Göz gözü görmeyen bir karanlıkta

Göğü kamaştıran nurdan konuşak.

Yaratan yaratmış sağlam yapıyı,

Yok gibi gösterip koymuş çatıyı,

Örtmüş başka yola çıkan kapıyı,

Bırak başka yolu, burdan konuşak.

Perde var perdenin ilerisinde,

Kervanlar yürüyor yolun tersinde,

Ova var ovanın az gerisinde,

Gizli ovalardan, kırdan konuşak.

İnan; boş değildir bomboş odalar,

Yerlerden göklere seğirtenler var,

Duvardan duvara bir kardır yağar,

Senin bilmediğin kardan konuşak.

Dever var insandan daha ufacık,

Yanlarında insan küçük bir çocuk,

Yola bir çıkarsak bitmez yolculuk,

Nara benzemeyen nardan konuşak.

Senin tok sandığın asla tok değil,

Yaylar yay değildir, oklar ok değil,

Yokluğun içinde varlar yok değil,

Yokları bırakıp vardan konuşak.

Sanma ki bedende kol var, kanat yok,

Sanma ki zerrede asla san ''at yok,

Sanma ki çöl ıssız, çölde hayat yok,

Sina ''dan konuşak, Tur ''dan konuşak.

Hangi dükkan satar? Kulak alalım,

Göz satan var mıdır? Bir göz bulalım,

Cevher kaynağını gel arayalım,

Bedenler yaratan yardan konuşak.

Erenler, yangın yok, içimdir yanan,

Korkma, deprem değil, kalbim; uyanan,

Gördüğün sel değil, gözüm; boşanan,

Ahlardan konuşak, zardan konuşak.

Barlıoğlu yoksul, zavallı derviş,

Gönlünü kaldırıp bir sırra vermiş,

Bir sevda uğrunda ölmüş dirilmiş,

Barlı ''dan konuşak, Bar ''dan konuşak.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 322-324/412)', 'Geceler çok uzun, sabah çok uzak, Uyuma erenler, sırdan konuşak. Göz gözü görmeyen bir karanlıkta Göğü kamaştıran nurdan konuşak. Yaratan ya...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sirdan-konusak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonyazın Şiiri', 'sonyazin-siiri-bahri-karaduman-cqquv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hiç gelmeyecek yarınlara sığındık

ve aldanmayı yeğleyip

unutmayı denedik

soğuk rüzgârlı bir kış sabahının 

ürpertisiydi sanki her şey

tedirgin

           ürkek

oysa ılık güz akşamları gibi olmalıydı sevgimiz

şimdi

damlamayan gözyaşları 

en derinlerde saklı

ne sen varsın

ne de sevdalı bir yürek

ilkyaz geliyor diyor dostlar

ilk bitti çoktan

     geriye

              son kaldı', 'hiç gelmeyecek yarınlara sığındık ve aldanmayı yeğleyip unutmayı denedik soğuk rüzgârlı bir kış sabahının  ürpertisiydi sanki her şey tedirg...', ARRAY['Türk Edebiyatı','Şiir','Bahri Karaduman']::text[], 8.5, '{"poet":"Bahri Karaduman","poet_slug":"bahri-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sonyazin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık', 'i-nsanlik-i-smet-barlioglu-egtv2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''İnsanlık öldü mü? '' Deme ey derviş,

İnsanlık acaba sağ mı ki; ölsün? 

Geldim ki; insanlık bitmiş, tükenmiş,

İnsanlık acaba sağ mı ki; ölsün? 

Yetimin malını buldum kursakta,

Yoksulun hakkını gördüm barsakta,

Adalet insandan hayli uzakta,

İnsanlık acaba sağ mı ki; ölsün? 

Atlılar yayanın sırtına binmiş,

Yerde birşey bulan almış, sevinmiş,

İnsanlar insana boşa güvenmiş,

İnsanlık acaba sağ mı ki; ölsün? 

Dertliler dertliden bekliyor şifa,

Tutan tuttuğuna ediyor cefa,

Kalmamış kimsede ahdine vefa,

İnsanlık acaba sağ mı ki; ölsün? 

Üstüne gülen var adlin, insafın,

Kazığı belinde birçok esnafın,

Herkes arkasında binbir cafcafın,

İnsanlık acaba sağ mı ki; ölsün? 

Herkes ar, namusa sınır tanıyor,

Damarlar çatlamış, yara kanıyor,

Hırsız malı soymuş, canı arıyor,

İnsanlık acaba sağ mı ki; ölsün? 

Gördüm ki; arılar yine darlarda,

Soğana çeviren yine kenarda,

Deha sahipleri yine zararda,

İnsanlık acaba sağ mı ki; ölsün? 

Alaya alınmış ilimle irfan,

Satılan mal olmuş bir tek damla kan,

İnsan gömüyorlar canı çıkmadan,

İnsanlık acaba sağ mı ki; ölsün? 

Eskiden böyleydi, şimdi de böyle,

Ruh kurtulur ama bilmem ki neyle,

Kuyu kazılıyor hergün iğneyle,

İnsanlık acaba sağ mı ki; ölsün? 

Geldim ki; değişen fazla birşey yok,

Yanık kaval susmuş, ortada ney yok,

İşler görülüyor amma deney yok,

İnsanlık acaba sağ mı ki; ölsün? 

Barlıoğlu şaşar bu garip hale,

Her gelen gidiyor ağlaya, güle,

Yüreğimiz dolmuş yaman gaile,

İnsanlık acaba sağ mı ki; ölsün? 

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 325-327/412)', '''İnsanlık öldü mü? '' Deme ey derviş, İnsanlık acaba sağ mı ki; ölsün?  Geldim ki; insanlık bitmiş, tükenmiş, İnsanlık acaba sağ mı ki; ölsün...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/insanlik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Ötesi mi Aydınlık', 'gecenin-otesi-mi-aydinlik-bahri-karaduman-c3j5b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yüzüne sarı çiğdemlerin aydınlığı vurmuş

güzel çocuk

hazır mısın yolculuğa

yolun Fikret''in dediği gibi

hep çakıl hep diken değil bugün

çakıllar kaya

dikenler tel örgüsü

arada bir coplanmak da 

yürek yarası

güz sıcaklarının bunalttığı 

bu kıyı kentinde 

seni

       geleceğini

                         düşünüyorum

                                               yaslı

bir çocuk büyütmenin mutluluğu

hiç mi hiç yok içimde

kederli duvarlar gibiyim bugün

bütün kapılar kapanmış sanki önümde

çıkmaz sokaklarda

                               yapayalnızım

yüzüne sarı çiğdemlerin aydınlığı vurmuş

güzel çocuk

gençliğime selâm söyle', 'yüzüne sarı çiğdemlerin aydınlığı vurmuş güzel çocuk hazır mısın yolculuğa yolun Fikret''in dediği gibi hep çakıl hep diken değil bugün çakıl...', ARRAY['Türk Edebiyatı','Şiir','Bahri Karaduman']::text[], 8.5, '{"poet":"Bahri Karaduman","poet_slug":"bahri-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gecenin-otesi-mi-aydinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhum İncinir', 'ruhum-i-ncinir-i-smet-barlioglu-eh0uv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hakkım olmayanı ikram eyleme; 

Alamam erenler, ruhum incinir.

Benim olmayanı meram eyleme; 

Veremem erenler, ruhum incinir.

Ne hakkım var benim yetim hakkında? 

Hangi meyvem mevcud elin dalında? 

Ben yolcu değilim haram yolunda,

Gelemem erenler, ruhum incinir.

Bir tek haram lokma domuz, it kanı,

Tadınca canavar eder insanı,

Ben haram saymışım dile yalanı,

Söylemem erenler, ruhum incinir.

Ulu derya ister bir küçük balık,

Halk mevcud değilse olmaz sultanlık,

Öğretmesin bana kimse fenalık,

Öğrenmem erenler, ruhum incinir.

Domuz ne ki gezse kuzu postunda

Kolayca tanınır herbir kastında,

Layık olmayanı bir taht üstünde

Göremem erenler, ruhum incinir.

Cahilin rızkı yok nurdan, billurdan,

Yaban nerde ise korkarım ordan,

Bu yüzden çağırma beni kapıdan

Giremem erenler, ruhum incinir.

Cehalet sardı mı bir kez meydanı,

Yollara düşmeli ilmin kervanı,

Çünkü durmak değil, kaçmak zamanı,

Duramam erenler, ruhum incinir.

Çare arar oldum binbir derdime,

Yola çıkmak gerek geceden yine,

Ben yolu bulurum kendi kendime,

Soramam erenler, ruhum incinir.

Ben çoktan terkettim tatlı uykumu,

Artık eliyorum çölleri, kumu,

Bilinen şey için güzel aklımı

Yoramam erenler, ruhum incinir.

Yaşadığın dünya ne sırlar saklar,

Bakan görmedimi sırrı savsaklar,

Aranmış, bulunmuş şeyleri tekrar

Aramam erenler, ruhum incinir.

Bedenim basamak, aklım merdiven,

Kırk yıl odun kırdım dergaha zaten,

Yeniden kırmayı bekleme benden,

Kıramam erenler, ruhum incinir.

Barlıoğlu der ki; vadem dolmadı,

Talepte bulundum, kabul olmadı,

Yüreğim yekindi, başvuramadı,

Vuramam erenler, ruhum incinir.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 328-330/412)', 'Hakkım olmayanı ikram eyleme;  Alamam erenler, ruhum incinir. Benim olmayanı meram eyleme;  Veremem erenler, ruhum incinir. Ne hakkım var be...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/ruhum-incinir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amma Velakin...!', 'amma-velakin-i-brahim-dikmen-2-h257r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki gönül bir olunca,

Samanlık seyran olurmuş.

Gülün dikeni olmasa.

Amma velakin..................! 

Aşkın gözü kör olunca,

Gönül ferman dinlemezmiş.

Birde dil yarası olmasa.', 'İki gönül bir olunca, Samanlık seyran olurmuş. Gülün dikeni olmasa. Amma velakin..................!  Aşkın gözü kör olunca, Gönül ferman din...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/amma-velakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dallarda Çiçek', 'dallarda-cicek-bahri-karaduman-nbwc8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gül rengi olur akşam

sıcak ve ateşli

varlığın bir damar gibidir

tutuşturur bedeni

sabahım tenin

yüreğin güneşimdir

yavaş yavaş yaklaşır akşam

gülümseyerek gelir

şaraba döner tüm güller

eller birleşir gözler birleşir

çok yakında bir çığlık

içim ürperir

geceye dururken karşı yakalar

beyaz bir tüy uçar

kuşlar yükselir', 'gül rengi olur akşam sıcak ve ateşli varlığın bir damar gibidir tutuşturur bedeni sabahım tenin yüreğin güneşimdir yavaş yavaş yaklaşır akşa...', ARRAY['Türk Edebiyatı','Şiir','Bahri Karaduman']::text[], 8.5, '{"poet":"Bahri Karaduman","poet_slug":"bahri-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dallarda-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Sen', 'yalniz-sen-alper-sezener-wpxq2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapıyorum gözlerimi

İşte hiçbir şey yok senden başka

Şehir, gök ve bulutlar

Yalnız sen

Yalnız yarım bıraktığım sigaramın dumanından

Ve ciğerlerimde oluşan yazgıdan öteye geçebileceğim

Gönlümde kuleler devrilirken 

Ve gönlümde yırtılırken boyandığım düşlerin sarsıcı sanrısı

bir adam ölmeyecek artık herkes uykudayken

Ağlamayacak bir kadın 

Beyaz giymiş bir ceylan görülecek rüyalarda

Ben avcı olmayacağım

Sen de ceylan', 'Kapıyorum gözlerimi İşte hiçbir şey yok senden başka Şehir, gök ve bulutlar Yalnız sen Yalnız yarım bıraktığım sigaramın dumanından Ve ciğer...', ARRAY['Türk Edebiyatı','Şiir','Alper Sezener']::text[], 8.5, '{"poet":"Alper Sezener","poet_slug":"alper-sezener","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalniz-sen-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Aşığım', 'ben-sana-asigim-murat-demir-w6rsx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimde dermanım dışımda nurum

Bahçemde çiçeğim bağımda gülüm

Şerefim gururum zevkim onurum

Ben sana mecburum sen değil misin? 

Güneşim yıldızım mehtabım ayım

Bulutum yağmurum şekerim çayım

Hayatta ki hayım mutluluk payım

Ben sana hasretim sen değil misin

Yarınım umudum elim ayağım

Sıcağım sovuğum yolum durağım

İlkimden sonuma  tek sığınağım

Ben sana aşığım sen değil misin', 'İçimde dermanım dışımda nurum Bahçemde çiçeğim bağımda gülüm Şerefim gururum zevkim onurum Ben sana mecburum sen değil misin?  Güneşim yıldı...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-sana-asigim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilim seni dileyim (Türküsel)', 'dilim-seni-dileyim-turkusel-burhan-kucuk-4mxiu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dilim seni dileyim (Türküsel) 

Yarim seni bu çağında seveyim

Üstüne al basma,fistan alayım

Aşkınla ben kor közlerde yanayım

Dilim seni dilim dilim dileyem

Sensiz ben dünya malını neyleyim

Yarim yollarını gözler dururum

Bekletme gayrı aşkına köleyim

Dilim seni dilim dilim dileyem

Burhan KÜÇÜK

Kdz.Ereğli-11.06.2004', 'Dilim seni dileyim (Türküsel)  Yarim seni bu çağında seveyim Üstüne al basma,fistan alayım Aşkınla ben kor közlerde yanayım Dilim seni dilim...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dilim-seni-dileyim-turkusel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarıldım mısralarıma', 'sarildim-misralarima-burhan-kucuk-sagjx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sarıldım mısralarıma

Önce siyah pantolonum,

Siyah gömleğim,gözlüğüm

En son seni de attım kalbimden

Kaçıyorum artık

Sahte bakış,sahte yüzlerden

Ve

 Sıkıca sarılıyorum

Beni hiç bırakmayan

Tek dostum mısralarıma

Ki

Gün geçtikçe sevgisi büyüyen

Burhan KÜÇÜK

Kdz.Ereğli-10.06.2004', 'Sarıldım mısralarıma Önce siyah pantolonum, Siyah gömleğim,gözlüğüm En son seni de attım kalbimden Kaçıyorum artık Sahte bakış,sahte yüzlerd...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sarildim-misralarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerimi Kaybettim Yaprakların Sarısında', 'duslerimi-kaybettim-yapraklarin-sarisinda-necmi-unsal-zib85', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duvarı  kerpiç,  badanası  kireç

Babamın  ahşap  evi.

Çocukluğum  gömülü,

Anılarımın  kabri  bir  nevi.

Evin  önünde  asma  çardağı.

Ben  gölgesinin  serinliğinde,

Elimde  çay  bardağı.

Yudumladığım  çay  değil,  anı  seli.

Kalbimin  acı  koruğu,  buralardan  gideli.

Çardakta  üzümler  delik  delik.

Önemli  değil  zaten  onlar  göstermelik.

Arılar  etrafında  pervane.

Ben  kendi  alemimde,  arılardan  kime  ne! 

Sararan  yapraklar  habercisi  güzün.

Her  rüzgarda  titrer,  kaplar  hüzün.

Ben  düşlerimi  kaybettim

Yaprakların  sarısında.

Bu  değirmende  ağardı  saçlarım

Ömrümün  yarısında.

Kışı  bekler  sararan  yapraklar

Çardağın  üzerinde.

Bense  baharı  beklerim,

Baharsa  gök mavisi  gözlerinde...

‘Doldur’  dedi  babam,  ‘doldur  çayımı’! 

sesiyle  döndüm  kendime.

Söz  geçiremedim  bendime.

Doldu  gözlerim.

Yine  sensiz  geçirdim izin ayımı.

3 Nisan 2004 Cumartesi, Danimarka-Køge 23.39', 'Duvarı  kerpiç,  badanası  kireç Babamın  ahşap  evi. Çocukluğum  gömülü, Anılarımın  kabri  bir  nevi. Evin  önünde  asma  çardağı. Ben  gö...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/duslerimi-kaybettim-yapraklarin-sarisinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Sana Geldim', 'yine-sana-geldim-cafer-tayyar-ozkan-x5x6d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasretinden ağladıkça yağan yağmurlardan,

Hatıraları düşledikçe uçan karlardan,

Yalnız dinledikçe eskimeyen şarkılardan,

Kurtulup yine sana geldim tatlı sevdiğim...

Kavuşmaların kaybolup gittiği anlardan,

Sensizde olsa yaşattığımız mekanlardan,

Beni yalnız bırakmayan acı rüyalardan,

Sıyrılıp yine sana geldim tatlı meleğim...

Aşkımızı mahkum eden soğuk duvarlardan,

Acıyı katık yapıp düştüğüm yollardan,

Dakikalarda olsa gördüğüm diyarlardan,

Ayrılıp yine sana geldim tatlı çiçeğim...

Yüreği geçip mantığınla sever olmuşsun,

Karşımda korkuyu silip güvenle durmuşsun,

Demek beni sahiplenecek kadar sevmişsin,

Hissedip yine sana geldim tatlı kadınım...

Rüzgarın estiği, yüreğin sevdiği yere,

Umudun güldüğü, güneşin doğduğu göze,

Vuslatın aktığı, hasretin yaktığı söze,

İnanıp yine sana geldim tatlı sevgilim...

Buğulu pencereye yazdığım ağıtlardan,

Gözyaşlarıyla sulanmış gönül bahçesinden,

Kıskançlıktan delirdiğim gecenin koynundan,

Özleyip yine sana geldim tatlı nedenim...

Gönüllerde raks eden muratların sesiyle,

Dile gelmeyen sözlerin amansız hissiyle,

Vuslata koşacak bedenlerin ümidiyle,

Ağlayıp yine sana geldim tatlı dilberim...

19 Aralık 2003 Bursa', 'Hasretinden ağladıkça yağan yağmurlardan, Hatıraları düşledikçe uçan karlardan, Yalnız dinledikçe eskimeyen şarkılardan, Kurtulup yine sana ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yine-sana-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınırsız Sınır', 'sinirsiz-sinir-vedat-koparan-vq7td', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-akıyor zamanın zamanı yuttuğu 

karanlıklar yamalı bohça eğreti gülüş- 

zamanı gelmiştir gidişlerin 

bir ağaç döker kabuklarını 

bir dal uç verir soyunur geceye 

bir yaprak düşer dalın kırılışından 

karışır kan revan güne sızılar 

gün vurgunu kuytuluklarda acılar 

ihanet söylencesinden arsızca sızar 

üç yanım mavi /üç yanım deniz 

iki yanım yangın /iki yanım susuz 

kaç zamanın vurgunudur 

içimdeki göç /içe göç tutsak 

hep o –bu yanım/arada sınırsız sınır 

ben özgürsem sende/ sen tutsak bende 

gel kıralım bu paslı zinciri birlikte. 

Vedat K 10.06.2004', '-akıyor zamanın zamanı yuttuğu  karanlıklar yamalı bohça eğreti gülüş-  zamanı gelmiştir gidişlerin  bir ağaç döker kabuklarını  bir dal uç ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sinirsiz-sinir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecelerin Mülteci Yolculuğunda', 'gecelerin-multeci-yolculugunda-vedat-koparan-dt0xz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-Sen Ben Halleri-

Hava kapalı yağmur gelecek görünüyor 

Biraz rüzgarda çıktı dallar dans ediyor 

Yaprakların hışırtılarını duyuyorum 

Rüzgarın sesine karışan düşlerim 

Seni aradı gözlerim iyi ki var resmin 

Güzel gözlerinde yoksun mavileri içiyorum 

Seni sana en iyi sen anlatır sen anlarsın 

Bir başka deyişle insan en iyi kendini tanır 

Bilmezsin ki bende ki senin nasıl olduğunu 

Ah bir dinlesen bende ki seni sana anlatsam 

Bir kale yaptım sağanak acılarımdan 

Eller yangın alevi gözler bal sıcağı rengi 

Bakışlarda gün akşamı terleri 

Gökyüzünden düşen her bir toz zerreciği 

Özgürlüğün, okyanusların derin mavileri 

Sevginin sarmalında iç denizlere gidişi 

Bilsen deniz nasıl yakın kılar 

Kendini kendinde çağladıkça 

Kaçak bir buluttan bir bulata 

Her gece seninle gitmekteyim 

Sana bu sevgi bu özlem bu mavi 

Sen de ben her şeyi, sende beni 

Dünün yoksun bağrında bu günü 

Geleceğe uzanan umudun gülüşünü 

Gecelerin mülteci yolculuğunda 

Sen hallerini görmekteyim 

Düşmesin gecelerin kararan buğusuna 

Sarmasın mor menekşeyi sessizlik 

Ben burada ne kadar yalnız sen orada ne kadar 

Ne kadar az senlerde ne kadar çok ya sen … 

Kaçak düşler dolunayın yüzünde 

Evet dün gece konuştum yine seninle 

Bir süredir çok berbatım 

Neden! Sormuyorum 

Bu deniz bu denli kirli 

Bu gök neden karalara bürülü 

Yırtamaz mı bağrının pusunu 

Sormuyorum 

Senin neden bende olduğunu 

Düş/mek sana 

Tut ellerimi düşüyorum üşüyorum 

Düşmek gözlerinden uyanan sabaha 

Serin ıslak geçer bahar sabahları 

Kolla kendini güneşe ser tenini 

Essin tarumar eden rüzgar 

Uçuşsun saçların gelsin kokun 

Savrulsun gülün yaprakları 

Çek kendine beni içimdeki derin sızı 

-Evrenin sonsuzluğunda 

Bu Sessizlik Yangınını Kırmak İçin Bir Yerden Başlamalı...! - 

Vedat K 04.06.2004', '-Sen Ben Halleri- Hava kapalı yağmur gelecek görünüyor  Biraz rüzgarda çıktı dallar dans ediyor  Yaprakların hışırtılarını duyuyorum  Rüzgar...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/gecelerin-multeci-yolculugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seremoni', 'seremoni-vedat-koparan-7alys', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ahali gün erkencesin de gelmiş 

Ekin’ime dadanır 

Korkuluktan kork 

Yok 

Karga gaklıyor 

Gak gak gak 

Sürüsüne bereket pes 

Saksasağan leş 

Saklıyor 

Sak sak sak 

Domuz dalmış körleme 

Burnun ucundan görmez öte 

Kurt ulur çakal sürer 

Aslanlar nerede 

Kuyruklarını tramvay mı çiğnedi ne 

He he he 

Çek kulağını şebek 

Yeme fıstığımı atarım kafana fındığı 

Kabartır göğsünü ayıcıklar sızlar ayaklar 

Ah ah ah 

Dağdan inip bağdakini görmezde 

Dadanı vermiş balına 

Güneş tepesinde arı kızgın mı kızgın 

Vız vız vız 

İğneler dolanıver dilime 

Kuzucuklar bahar sevincinde 

Hopla hopla hoplaya 

Hadi gidin çimene 

Dolanı dolanı verin otlaya otlaya 

İdare edin bol değil haberiniz ola 

Ekin’im nazlı gelincik süzülüşü 

Düz olsun yol, usta tutar çekül’ü 

Güneş değil yakıp kavuran 

Çalar makamda hüzzam… 

Zarafetin ihtişamında toplandı heyeti fasıl. 

Vedat K 03.06.2004', 'Ahali gün erkencesin de gelmiş  Ekin’ime dadanır  Korkuluktan kork  Yok  Karga gaklıyor  Gak gak gak  Sürüsüne bereket pes  Saksasağan leş  ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/seremoni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teşekkür! ....(ABİR''e)', 'tesekkur-abi-r-e-naime-erlacin-8pdpd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok özel bir armağan hazırlamışsın bana sevgili Abir…. 

Hatırlanmak tarifi imkansız, anlatılmaz güzel bir duygu. Şarap gibi yıllanarak değerlendiğim doğru mu bilemem ama sen her ne kadar kabul etmesen de artık yaşlanıyorum. Duygular eskimiyor; aksine keskinleşiyor, güçleniyor ancak ben gün geçtikçe uzatmaları oynadığımı hissediyorum…. 

Oldum olası yaş günlerini, törenleri, özel günleri sevmem. Her nedense içimi bir hüzün kaplar. Bunun yaşla bir ilgisi de yok üstelik. Gençliğimde de böyleydim. Bayramların, yılbaşlarının, doğum günlerinin en yalnız insanı daima ben olurdum… 

Bugün ise özellikle kızım uzaklarda iken, yalnızlığımı paylaşan eşimle her zamankinden hüzünlü başladım güne. Hayatımı gözden geçirdim. İçimde o hiç tükenmeyen sevgileri ve dostlarımı düşündüm. Yeryüzünde acı çeken onca insanı düşünüp bir yandan halime şükrederken bir yandan da yüreğim ezildi. Sonra 9.15’de kapım çalındı ve 25 yıllık bir dostu buldum karşımda. Elinde, adını bilemediğimiz çok güzel, kırmızı ve güle benzer bir çiçek vardı. Saksıdaydı. Bu demekti ki, benimle uzun süre yaşayabilecekti. Sarıldık birbirimize ve yüreğim ısınmaya başladı birden. O sırada Sevgili Çağıl Ener’den bir kargo ulaştı evime. Kütüphanemi zenginleştirecek bir sürü kitap göndermişti. Ve Kelaynak kupası! ...Zamanlaması harikaydı yine... 

Derken bir telefon aldım. Tanımadığım bir çiçekçi evde olup olmadığımı soruyordu. Teslimatı olduğunu söylüyordu. Biraz sonra Çağıl’ın bembeyaz kocaman buketi geldi. Nihayet PC’imi açtım. Antoloji yetkilisi doğum günümü kutluyordu.  Ve senin şiirini gördüm. Gözyaşları içinde okudum. Şimdi hüzünlü kalbim sıcacık. Bunca acının ortasında kutlama hakkım var mı bilmiyorum ama dostların varlığını bilmek çok hoş bir duygu…

Sen ki bana onur duyarak sakladığım birbirinden güzel şiirler armağan etmiştin. Bugün o ince ve hassas yüreğinden kopup gelen bir yenisini eklemişsin. Nasıl teşekkür edebilirim sana? Böyle bir davranışın sözlü karşılığı yok ki! ...

Hüznümü ısıttın. Gurur duydum, onur duydum, sevgi doldum arkadaşım…

İyi ki varsın! ! ! ....

Ve iyi ki varsınız dostlar…Abir’in hoşgörüsüne sığınarak sizlere en içten teşekkürlerimi sunuyorum…

Hepinizi çok seviyorum :))

(11 Haziran 2004)', 'Çok özel bir armağan hazırlamışsın bana sevgili Abir….  Hatırlanmak tarifi imkansız, anlatılmaz güzel bir duygu. Şarap gibi yıllanarak değer...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tesekkur-abir-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Tüketiriz', 'omur-tuketiriz-murat-sahin-3kx5n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ömür tüketiriz aşkın peşinde

Budur günahımız, kârımız bizim

Cehennem ateşi neylesin bize

Yürekte gizlidir nârımız bizim

Mecnun oldum şu alemin dilinde

Savrulur dururum sitem yelinde

Gönül küle döndü aşkın elinde

Cihanı yakmıştır zârımız bizim

O bahçadan bu bahçaya girersin

Türlü çiçeklerden hasret derersin

Gurbet ellerinde neyi ararsın

Gönülde saklıdır yârımız bizim

Beklerim bir akşam kapım çalınmaz

Halin nedir diye soran bulunmaz

Güle dikeninden yanaşan olmaz

Sol yanda saplıdır hârımız bizim

Bârânîyem ayrı düştüm gülüme 

Ah eder gezerim Leyla çölünde 

Bir kuru baş kaldı omuz üstünde

İşte budur bütün varımız bizim', 'Ömür tüketiriz aşkın peşinde Budur günahımız, kârımız bizim Cehennem ateşi neylesin bize Yürekte gizlidir nârımız bizim Mecnun oldum şu alem...', ARRAY['Türk Edebiyatı','Şiir','Murat Şahin']::text[], 8.5, '{"poet":"Murat Şahin","poet_slug":"murat-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/omur-tuketiriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş Ocağı', 'tas-ocagi-rahim-tas-ohwt8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Taş Ocağı 

  



Ocağımız tütüyordu 

Gözyaşı akıttı kader 

Küllendi yanan korumuz 

Üfle baba, etek çırp anneciğim 

Yine tütsün taş ocağı..

eylül 1986 

Rahim TAŞ', 'Taş Ocağı     Ocağımız tütüyordu  Gözyaşı akıttı kader  Küllendi yanan korumuz  Üfle baba, etek çırp anneciğim  Yine tütsün taş ocağı.. eylü...', ARRAY['Türk Edebiyatı','Şiir','Rahim TAŞ']::text[], 8.5, '{"poet":"Rahim TAŞ","poet_slug":"rahim-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tas-ocagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta - Çırak', 'usta-cirak-i-brahim-ugur-toprak-u761t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Usta - çırak ilişkisi 

Derdim bizimkisi.

Sen de hep sorardın, 

Neden böyle dediğimi.

Ne diyor üstad bak:

''Büyük ustalık işidir sevmek''

İşte bu yüzden 

Ben ustayım,

Sense hala çırak.

10.06.04/Perşembe

23:34/İzmir', 'Usta - çırak ilişkisi  Derdim bizimkisi. Sen de hep sorardın,  Neden böyle dediğimi. Ne diyor üstad bak: ''Büyük ustalık işidir sevmek'' İşte ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/usta-cirak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Ve Sen', 'gece-ve-sen-sirma-mersin-g3dc3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş battığında

Karanlığı kucaklamaya hazırlanan gece

Gökyüzündeki yerini almak için

Ay ve yıldızlar yolla çıktı

..................................................................................

.................................................................................

Birşeyler söylemek için

Hadi telefonu aç

Ona sevdiğini anlatan

Bikaç yürekten dökülen

Cümlelerle seslen! 

''Varlığından güç alıyorum

İyiki varsın bitanem...''

...............................................................................

...............................................................................

Rüyalarımın  büyüsü ile 

Geceyi seninle 

Solukladığımda

Sabah olsun istemem

Geceyi yalnız ikimiz yaşıyoruz

Belki de bunun en güzel tarafı

Sessizlikte birbirini kucaklayan mutluluğumuz...

11.06.04

..................... Her Gecenin İçinde Yaşananlar........', 'Güneş battığında Karanlığı kucaklamaya hazırlanan gece Gökyüzündeki yerini almak için Ay ve yıldızlar yolla çıktı .............................', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gece-ve-sen-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni bulamazsın', 'beni-bulamazsin-mustafa-tugrul-kosar-dmqfh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vicdanın başıboş bırakmaz seni 

En az benim gibi olursun ancak 

Bir deli hırsıyla arasan beni 

Gitmiş hayalimi bulursun ancak 

Tozlu albümünü açmaya kalksan 

Özlemin arttıkça gözyaşı katsan 

Sarılırmı diye umutla baksan 

Cansız bedenimi görürsün ancak 

Gecene gün olmaz artık gözlerim 

Uzanmaz sancını almaz ellerim 

Teninde günbegün biter izlerim 

Beni tükendikçe bulursun ancak 

Çınlamaz kulağım ansanda bilmem 

Duayla gözyaşı döksende bilmem 

Belki kavuşursun belkide gelmem 

Beni rüyalarda görürsün ancak 

Ağlasan nafile yansan nafile 

Umutla yollara düşsen nafile 

Hadi ben bir yana adımı bile 

Bir mezar taşında görürsün ancak', 'Vicdanın başıboş bırakmaz seni  En az benim gibi olursun ancak  Bir deli hırsıyla arasan beni  Gitmiş hayalimi bulursun ancak  Tozlu albümün...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beni-bulamazsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fark', 'fark-naime-erlacin-8e9oo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“aşk yoksa yaşamak yok”

demiştim bir zamanlar

-yaş neredeyse elli

bir tuhaf baktılar yüzüme

dediler “kadın ne anlatıyor böyle”

yaşam çarkının dişlilerinde

fazlasıyla muzdariptiler hesaplı temaslardan 

tek bir bakıştı oysa sevda 

nabza dönüşen kısacık bir an 

kalp var 

kutupta ortanca büyütür 

tomurcuklanır tundrada 

aşkı bilmeyen 

içemez bir tas su 

durur öylece ayazmada 

“aşk yoksa yaşamak yok”

değişmez bu söylem

fark burada! 

-yaş elli dokuz bugün... 

(11 Haziran 2004)', '“aşk yoksa yaşamak yok” demiştim bir zamanlar -yaş neredeyse elli bir tuhaf baktılar yüzüme dediler “kadın ne anlatıyor böyle” yaşam çarkını...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/fark-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Yıldızı (Venüs)', 'coban-yildizi-venus-ali-aydin-9wcfa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evrenin el değmemiş tek kutsal bakiresi,

Güneşin ışığından başkası görmedi tenini.

Milyonlarca ışık yılı aşkımızın menzili,

Mars’ın yörüngesinde sema yaparak döneceksin.

Yıldızlar dans ederek izleyecek geçişini,

Tanımsız gezegenler selam duracak, 

Saflığın ve bitimsiz güzelliğin karşısında. 

Venüs’ün rüzgarına kapılıp, sonsuzluğunda ölmek isterim.

10.06.2004', 'Evrenin el değmemiş tek kutsal bakiresi, Güneşin ışığından başkası görmedi tenini. Milyonlarca ışık yılı aşkımızın menzili, Mars’ın yörünges...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydın']::text[], 8.5, '{"poet":"Ali Aydın","poet_slug":"ali-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/coban-yildizi-venus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazmak', 'yazmak-hakan-arikan-0qikn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yazmak; 

Dokunabilmek kelimelerle,

Uyuyanlara.

Bir damla göz yaşını avuçlayabilmek,

Satır aralarında üşümek,

Kaybolup uykusuz düşlere gitmek.

Yazmak; 

Sessiz çığlıklara şahit olmak,

Yeri geldiğinde adam olmak,

Olmadık zamanda çocuklaşmak.

Bence yazmak; 

Adam gibi,

Çocuk coşkusuyla,

Aşık olmak

Ankara Nisan 2003', 'Yazmak;  Dokunabilmek kelimelerle, Uyuyanlara. Bir damla göz yaşını avuçlayabilmek, Satır aralarında üşümek, Kaybolup uykusuz düşlere gitmek...', ARRAY['Türk Edebiyatı','Şiir','Hakan Arıkan']::text[], 8.5, '{"poet":"Hakan Arıkan","poet_slug":"hakan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yazmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicran Yükü', 'hicran-yuku-zulfikar-yapar-kaleli-wczpt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tahammül gösterip hicran yükünü,

Çekemezsem, emeklerim boşuma.

Bir yolunu bulup zehrin kökünü,

Sökemezsem, emeklerim boşuna.

Elemeden asar isem eleği,

Gerçek edemezsem kutlu dileği,

Şu nefis denilen zalim bileği,

Bükemezsem, emeklerim boşuna.

Ayırdım aslından çakılı, kumu,

Utanırım elbet insanlık bu mu? 

Bütün bulutlara çiçek tohumu,

Ekemezsem, emeklerim boşuna.

Dümensiz geminin göründü koyu,

Var ile yokluğun saniye boyu,

Tutup gökyüzünden yağmuru, suyu,

Dökemezsem, emeklerim boşuna.

Can tuzağa düşer gerince ağı,

Gelip geçenlerin anlık uğrağı,

Güneşin sırtına zafer bayrağı,

Dikemezsem, emeklerim boşuna.', 'Tahammül gösterip hicran yükünü, Çekemezsem, emeklerim boşuma. Bir yolunu bulup zehrin kökünü, Sökemezsem, emeklerim boşuna. Elemeden asar i...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hicran-yuku-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağı Öpen Kız', 'bayragi-open-kiz-zulfikar-yapar-kaleli-zf91w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sayamadım kaç yıl oldu göçeli,

Hedefimde güneş, oklamaktayım

Yıllar oldu şerbet diye içeli,

Zehiri gönülden paklamaktayım.

Kaç asırdır allı turna karalı,

Kurşun yemiş kanatları yaralı,

Gönül bu güzeli sardı saralı,

Kara  talihimi aklamaktayım.

Zaman mı, asır mı, çağ mı hatalı? 

Bulut mu, yağmur mu, dağ mı hatalı? 

Hasta mı, ölü mü, sağ mı hatalı? 

İçimde acılar saklamaktayım.

Dünyaya aşk ektim, nefret yetişti,

Ne gül açtı, ne de bülbül ötüştü,

Güneşin gözüne bir figan düştü,

Her yerde kan, barut koklamaktayım.

Koyun kuzusuna meler, meleşir,

Gün bulutu, bulut dağı dolaşır,

Kara gün haberi çabuk ulaşır,

Derde yeni dertler eklemekteyim.

Akrep bıldırcını düşürdü ağa,

Kaleli sırrını gömer toprağa,

Bayrağını öpen kızı bayrağa,

Nişanladım, düğün beklemekteyim.', 'Sayamadım kaç yıl oldu göçeli, Hedefimde güneş, oklamaktayım Yıllar oldu şerbet diye içeli, Zehiri gönülden paklamaktayım. Kaç asırdır allı ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bayragi-open-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz geldi', 'yaz-geldi-akin-akca-9srai', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '‘Genel geçer hayata dair 

bir bakışın ürünü’ ‘sıradan,

ortasında körpecik gecenin’; 

ay yükselten, 

tek, sen bindin 

o trene: 

Sonuna daha vardı gecenin; 

Gecenin ortası bitmişti, 

“Trene tek senle 

bineceğim” dedin 

Geldi bak, yaz! ! 

Güneşin orta yere çıkarttığı buz! 

(Buzları, eritirken onları…)

 Sen bir kenara yaz. 

Yaz ki, hep hatırlarız -

öyledir de ya... 

- Kara kışta ve 

yağan ‘taze, 

pembe karda’ 

Eritiyor bak güneş, 

Nur geldi toprağın yüzüne … 

O; 

kendini attı kendi 

 üzerinde, 

(Ölü toprağını.) 

ölçmek için sevgililerin şanını. 

Tan yerinde, sevinç! 

Çocukluk, bir kıvanç! … 

Güneş eritti buzları; 

Neden sonra huzur yine 

 konca, 

Eller, yılmayıp 

 kenetli sabredince. 

* 

Ve şimdi gemiler uzaktaki bir duba,

Yüzerek çıktığın boyunu geçen yerde; 

Ve plajda, seyyar, iki sayfiye; 

Koşuyorlar, denize! ! ... 

Ve denizden,

 hoppaa! 

 sıcak kumlarla 

Cebelleşerek, 

 panik içinde, 

Şemsiye altına, 

 şezlonga……….... 

Dingindir serinlemiş 

kumlar; ve yaz gecelerinde, 

Yakılan cehennem sıcağında, 

Ateşlerinde, guitar eşliğinde. 

‘Dönen kendine’, 

 benlikler döner kendi etrafında, 

 dans ederler! ... 

“Yaz geldi” derler! ...

* 

Dalgaların sesini dinler,

Tek damlası için 

 tuzlu suyun, 

Okyanusta uğultu 

 olan karanlık 

 sessiz gölün… 

Ve okyanusun dibinde 

 de Nice denizler coşar, 

‘Kumları 

 girdaplarına-

 ilk dördün’ 

Sabah markete gidecek

 bermuda şortlar; 

Yine aynı güneşin 

 altında; 

Doğru –

 insanların içinden 

- Gazetecinin yolundan.', '‘Genel geçer hayata dair  bir bakışın ürünü’ ‘sıradan, ortasında körpecik gecenin’;  ay yükselten,  tek, sen bindin  o trene:  Sonuna daha v...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/yaz-geldi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir kere', 'bir-kere-can-i-rfan-q3mho', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimi kere 

  ot gibi düşlerim

Korkularımı düşlerim,

 ilk filizlendiğim andaki.

Havamı kararıyor,bulutlar mı artıyor,gök mü gürlüyor,

   fırtına,yağmur,kar,yıldırımlar ve

   patlayan ses mi var? 

Ödüm kopardı.

Serpildiğimi düşlerim.

Ovalara,bayırlara,dağlara,taşlara,yeryüzüne..

Bir genç kız yada oğlan gibi.

Kimi kere açların midesinde,kimi kere tokların ayakları altında.

Yağmur yağsa altınımdır benim.

Korkularım mı kalmadı ne? 

Açan çiçekler,kokan güller,papatyalar,laleler,orkideler,ağalar,beyler! 

Güldüğünüzde dişleriniz görünüyor.

Bir bakın halinize bir kere.

İnmeseniz de bir kere mideye 

Alınacaksınız ayaklar altına 

                      elbet bir kere.

Üstümüzde inekler olduğu sürece.', 'Kimi kere    ot gibi düşlerim Korkularımı düşlerim,  ilk filizlendiğim andaki. Havamı kararıyor,bulutlar mı artıyor,gök mü gürlüyor,    fırt...', ARRAY['Türk Edebiyatı','Şiir','Can İrfan']::text[], 8.5, '{"poet":"Can İrfan","poet_slug":"can-i-rfan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-kere-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günüm İnsanı', 'gunum-i-nsani-i-lyas-ozmen-547e0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Merhamet fakiri doğuştan kalpsiz

Sevmeyi unutmuş günüm insanı

Sanki birer robot kör sağır dilsiz

Gülmeyi unutmuş günüm insanı

Oysa bir kaldırsa eğik başını

Görecek manasız kör savaşını

Anlamsız döktüğü gözün yaşını

Silmeyi unutmuş günüm insanı

Kendini düşünür bakmaz kimseye

Bencillik bilmemki kimden hediye

Dilinde tek bir söz ''''hep bana'''' diye

Vermeyi unutmuş günüm insanı

Kavgayı görmesin kanatsız uçar

Hoşgörü yerine şiddeti seçer

Eliyle diliyle hep yara açar

Sarmayı unutmuş günüm insanı

Özmen''em yalan yok bende böyleyim

Onlar gibi bende nefs''e köleyim

Aynı bakar körüz nerden bileyim

Görmeyi unutmuş günüm insanı', 'Merhamet fakiri doğuştan kalpsiz Sevmeyi unutmuş günüm insanı Sanki birer robot kör sağır dilsiz Gülmeyi unutmuş günüm insanı Oysa bir kaldı...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunum-insani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olimpiyat Meşalesi', 'olimpiyat-mesalesi-caner-kuru-rr6oe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir meşale yakmışlar, adı olimpiyat

Sevgi, dostluk,barışmış bunların gayesi.

Peki, nerden geliyor duyulan bu feryat? 

Bu acı, gözyaşının kimlere payesi? 

Hiç bir şey söylemeyin, susuverin bari,

Ne bu yalan dolanlar, kardeşlikten yana? 

Sizin uygarlığınız bu kadar ileri! 

Döktüğünüz kanları için kana kana.

Ortaçağ karanlığı dediğiniz dönem,

Bundan daha aydınlık, daha insancaydı.

Güzelim dünyamızı ettiniz cehennem,

Her yana hırsı,kini bu uygarlık yaydı.', 'Bir meşale yakmışlar, adı olimpiyat Sevgi, dostluk,barışmış bunların gayesi. Peki, nerden geliyor duyulan bu feryat?  Bu acı, gözyaşının kim...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olimpiyat-mesalesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kararsız yolcu', 'kararsiz-yolcu-elif-sebnem-akal-wy6na', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yoklar Limanı''na attık demiri

''yolculuk buraya kadar'' demiş biri

kim? 

bavullar dolusu kırgınlıklarım

karaya indi

yanımdalardı bunca zaman

da

şimdi? 

doğru 

anlaşılmadım hiç

ben değildim şiir yazan

o başka biriydi sanki

''devamı yok

bu son'' diyen 

hangimiz olmalı

ben mi? 

''kaçak yolcu şair olan, inmeli! ! ! ''

bağırdı kaptan

İnsem mi

ben de insem mi? 

kaptanın adı SEVDAymış

vurup

yollara düşsem mi?', 'Yoklar Limanı''na attık demiri ''yolculuk buraya kadar'' demiş biri kim?  bavullar dolusu kırgınlıklarım karaya indi yanımdalardı bunca zaman d...', ARRAY['Türk Edebiyatı','Şiir','Elif Şebnem Akal']::text[], 8.5, '{"poet":"Elif Şebnem Akal","poet_slug":"elif-sebnem-akal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kararsiz-yolcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Üstte Gözlerin', 'en-ustte-gozlerin-oguzkan-bolukbasi-rtvf8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüzgâra vermişim ne varsa senden

Bir de yelkenimi şişirmiş haince

Ve muzırca

En üstte gözlerin

Gökte

Demir kazıktan daha parlak

Öylece giderim

Sarhoş bir dalganın üzerinden

Kayıp

Bir gökada arayıp

Uzayın en uzak köşelerinde

Issız adalar yerine

Yanımda üç şey götürmek gerekirse

Bir sensizlik

Bir yalnızlık

Bir de umut derim

Şekerim

Rüzgâra vermişim ne varsa senden

Umut kaldı

Anlayan halimden

Avuçlarım yanıyor

Bu hasretin alevinden

Sulara bırakıyorum kendimi

Sular yanıyor

Nerede bir aşk görsem

Utanıyor 

En önce gözlerin', 'Rüzgâra vermişim ne varsa senden Bir de yelkenimi şişirmiş haince Ve muzırca En üstte gözlerin Gökte Demir kazıktan daha parlak Öylece gider...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/en-ustte-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Herşeyimsin', 'benim-herseyimsin-emekcan-uzal-yoj66', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen benim herşeyimsin aşkım

Başka kollarda olduğunu bile bile vazgeçemediğim

Karlara inat yollarında yürüdüğüm

En umutsuz anımdaki küçük umudum

Herşeyin sıradan olduğu dünyada 

Kendime ait sıradışı dünyam

En özel anlarım

Düşünmeye kıyamadığım

Hasretinin bile güzel olduğu sevdiğim

Yıldızlara baktıkça gördüğüm

Onlar kadar imkansız olduğunu bildiğim

Yerine kimseyi koyamadığım

Buğulu camlara adını yazdığım

Yağmur damlaları olduğunu düşünüp 

Sırılsıklam ıslandığım

Bir an olsun aklımdan silemediğim

Sen benim herşeyimsin aşkım

Kendimden çok sevdiğim', 'Sen benim herşeyimsin aşkım Başka kollarda olduğunu bile bile vazgeçemediğim Karlara inat yollarında yürüdüğüm En umutsuz anımdaki küçük umu...', ARRAY['Türk Edebiyatı','Şiir','Emekcan Uzal']::text[], 8.5, '{"poet":"Emekcan Uzal","poet_slug":"emekcan-uzal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/benim-herseyimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Dilli', 'ates-dilli-hakki-hakan-kaya-10y6u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir sevgi kopardım 

canımdan

tohum olup karışsın diye

toprağa

...

görmedim bile 

küçüklüğümü

attımda dağlara

...

vurdu bağrına 

toprağın rüzgarı

güneşmi açtı 

şimşek mi çaktı

daha gün görmemiş 

tomurcuk

sevgisiz kaldı

...

ateş dilli yağmurun

nefesi yetemedi

yarın gelen su 

dün yiten hayatı

göremedi

...

kuruldu yine

sevgi fakları

kuruttu denizimi

içimin yangınları...', 'bir sevgi kopardım  canımdan tohum olup karışsın diye toprağa ... görmedim bile  küçüklüğümü attımda dağlara ... vurdu bağrına  toprağın rüz...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ates-dilli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Sevgi', 've-sevgi-hakki-hakan-kaya-myxkt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayalkırıklığı

...

Hani çıkarken, 

ayağın kayarda düşersin ya

Hani gülerken, 

aklına gelirde ağlarsın ya

Hani gelirken, 

hiç gelmediğini bilirsin ya

Hani severken, 

hiç sevilmediğini anlarsın ya

...

ve sevgi

...

Hani soğuk havada gelirde aklına, 

Üşümesin diye düşünmezsin ya...', 'Hayalkırıklığı ... Hani çıkarken,  ayağın kayarda düşersin ya Hani gülerken,  aklına gelirde ağlarsın ya Hani gelirken,  hiç gelmediğini bil...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ve-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mürit', 'murit-kemal-beyatli-5fujd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Giriş: 

Bir hoyrat çınlar göklerde 

Büyüdükçe büyür,olur Sitare 

Düş yollara,çöllere gönül 

Durmadan o nuru ara... 

Sararmış bir kitabenin 

Arasında kuruyan bir gül 

Yapraklarında tılsımlı çizgiler 

Her çizgi bir Sitare (1) 

Her çizgi bir Kerkük 

Ve Hümeyra (2)   satırlara sıkışmış 

Harflerin ayağında prangalar 

Biliyorum Hümeyra bir konuşsa 

Pir konuşacak 

Sitare,Kerkük,Hümeyra 

Üçgenindeki aşkı 

Senden,benden gayri 

Kimse duyamaz hocam 

''Saçağ (3)   ardı 

Gerdandı saçağ ardı 

Ay batsa gün kareli 

Kara gün saç ağardı'' 

İçini yer,yer ve yerdi... 

''Ahin Min-el Fi-raki'' 

İşte başlar sazın telleri 

Mızrabı kemirmeye 

Ve dünya durur,sular akmaz,kuşlar uçmaz 

Her şey tersine döndü 

Mehterin tokmağı davulu aradı 

Emirler havada kaldı 

Bu minval da uzar Orta Asya''dan 

Bir otağın yanı başında duran 

Alperenin avazı 

Damar damar işler tenimize 

Maziden atiye kırpar gözlerini küheylan 

Ve dizginini salıverir bu aşk 

Hümeyra''nın dili tutulmasaydı 

Gözlerinden akan sözler 

İki damla yaş olmasaydı Hasa Çayı''nda (4) 

Boz kırlar avucumuz kadar küçülmeseydi 

Ferhat dağlarla uğraşmazdı 

Bir sen anlarsın bu aşkı hocam 

Bir de ben 

Demet demet hazırlanmıştı ışık hüzmeleri 

Bir yolu gösteriyordu 

İşaretler hep o yöne idi 

Sitare''nin gözleri 

Hümeyrada idi 

''Haydi Ya Allah'' dermişcesine 

Kan damarda atıyordu 

Burçlar yeni şekiller çizdi 

Dur durak bilmeyen aklım 

Göğün altında her yer senindir,diyen aklım 

Dünya''yı elekten geçirip süzdü 

Bu kez ben yorgun düştüm 

Üşüyorum 

Gel beni kucakla 

Her şey mazide mi kaldı yoksa 

Şimdi orada Kerkük Sitare''siz 

Ve ben burada Kerkük''süz 

Pençesine takılırım isyanın 

Deler sınırları sesim 

Ama orada Kerkük yalnız 

Sayıklarım ışık nerede 

Kime ne söyledi 

''Konuş benimle Hümeyra'' 

Kerkük yalnız,ben yalnız 

Yalnızlık beni öldürüyor hocam 

''Allah''ü Me-alsabirin'' şerbetini içiyorum 

''Ve sığınırım içime''(5) 

Bir sen anlarsın bu aşkı hocam 

Bir de ben 

Tiryakiler saf tutmuş 

Döner memlekette kimisi 

Kimisi memleket için döner 

Bir tekke yurdum kadar sınırları 

Her sütunu bir dua, 

Şeyhim,zikrinle uyandır Kürşad''ı 

Uykudan sök 

Herkes üstüme geliyor 

Kalabalıkta koşuyorum sana 

Ermişliğim kök kök 

Aç kapıyı izin ver 

Müridinim,işte geliyorum Kerkük

Açıklamalar

1-Sitare:Dilaver Cebeci''nin bir şiirinin ve şiir kitabının adıdır. 

2-Hümeyra:D.Cebeci''nin bir şiirinin adı 

3-Saçağ:Irak Türkleri ağzı,saçağı demek 

4-Hasa Çayı:Kerkük''te bir çay adı 

5-Ve sığınırım içime:D.Cebeci''nin bir şiirinin ve kitabının adı', 'Giriş:  Bir hoyrat çınlar göklerde  Büyüdükçe büyür,olur Sitare  Düş yollara,çöllere gönül  Durmadan o nuru ara...  Sararmış bir kitabenin  ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Beyatlı']::text[], 8.5, '{"poet":"Kemal Beyatlı","poet_slug":"kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/murit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanoğlu....', 'i-nsanoglu-baris-pinar-tumer-do2nn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanoğlunun eski

alışkanlığıyım....

Eskimiş artık

hiç hatırlanmayan

dünyasıyım...

Kibirini çaldığı

ateş parçasıyım...

Kırgın unutulmuşluğuyum....

Irmaklarda tazelediği

arınmışlığıyım....

Nakşettiği unutulmazlığıyım

aynı zamanda....

Onların derya içre olup da

deryayı bilmeyen balıklarıyım...

Ben insanoğluyum....

Aynı zamanda....', 'İnsanoğlunun eski alışkanlığıyım.... Eskimiş artık hiç hatırlanmayan dünyasıyım... Kibirini çaldığı ateş parçasıyım... Kırgın unutulmuşluğuy...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/insanoglu-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-omer-temel-2mnff', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yara nazar ettim,nazarınan ben.

Yardan yaralandım,azar ınan ben.

Bir değil de,bin parçaya bölündüm.

Yarın dilindeki,hızar ınan ben.

Ayak oldum,Kapılara atıldım.

Direk oldum,tavanlara çatıldım.

O na buna,  üç kuruşa satıldım.

Yarın gönlündeki, pazarınan ben.', 'Yara nazar ettim,nazarınan ben. Yardan yaralandım,azar ınan ben. Bir değil de,bin parçaya bölündüm. Yarın dilindeki,hızar ınan ben. Ayak old...', ARRAY['Türk Edebiyatı','Şiir','Ömer Temel']::text[], 8.5, '{"poet":"Ömer Temel","poet_slug":"omer-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sensizliğin Sonu', 'sensizligin-sonu-guclu-sonmez-w925g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Heyecanlıyım

İçimde

Firar hazırlığında bir kalp

Ne kadar zaman geçti

Sensizliğe terkettiğinden beri

Hatırlıyor musun hani

Çabucak döneceğim dediğini

Epey oldu başlayalı

Günler yerine çizmeyi ayları

Kimsesiz düşüncelerime takılıp

Fethettin her şeyinle aklımı

Sensizliğe alışamadım 

Sensizliği anlayamadım...

Sensizliğin kitaplarını

Sensizliğin filmlerini

Sensizliğin refakatini

Hiç sevmedim - sevmeyeceğim...

Dün aradın

Kelimelerin 

Müjde dağıtan cümleler oluşturdu

Ama bugün ben

Sensizliğin acısına kaldığım yerden 

Devam edeceğim

Ta ki yarın sen

Bir daha gitmemek üzere

Kapımı çalana dek

(İstanbul, Haziran 2004)', 'Heyecanlıyım İçimde Firar hazırlığında bir kalp Ne kadar zaman geçti Sensizliğe terkettiğinden beri Hatırlıyor musun hani Çabucak döneceğim ...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sensizligin-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günün Kutlu Olsun', 'dogum-gunun-kutlu-olsun-derin-oger-1owkf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Canım Naime Erlaçin e

Yüreği gülüm 

Yüreği zambağım

Yüreği sımsıcacığım

Sen sükûndun ben deli rüzgâr

Yüreğinin bahçelerinden yapraklar çaldım

Sandım ki her yer deniz

Nemli sokak taşlarına çok takıldım

Dizlerim hep bu yüzden  yaralıydı

Göğüs kaynatıp sıcacık sardın

Yüreği gülüm ü unutmadım 

Dere oldum da denizine ulaşamadım

Sen çeşmeydin  ben musluğu açamadım

Adresi yazılmamış bir yoldum

Yüreği gülüm onarılmaz mı bu sonbahar

Geç mi kaldım

Doğum günün kutlu olsun....', 'Canım Naime Erlaçin e Yüreği gülüm  Yüreği zambağım Yüreği sımsıcacığım Sen sükûndun ben deli rüzgâr Yüreğinin bahçelerinden yapraklar çaldı...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dogum-gunun-kutlu-olsun-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parçalı Bulutlu Sevda', 'parcali-bulutlu-sevda-ersan-kurt-0mwva', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok parçalı tek bir hayat

Yıllar birden geçmiyor

Ama düne bile uzak

Yarına ne kadar yakınız

Baktım ki bugün de bitmiş

Her zamankinden daha yalnız.

A Layli-E.Kurt /Ankara 8 Haziran 2004', 'Çok parçalı tek bir hayat Yıllar birden geçmiyor Ama düne bile uzak Yarına ne kadar yakınız Baktım ki bugün de bitmiş Her zamankinden daha y...', ARRAY['Türk Edebiyatı','Şiir','Ersan Kurt']::text[], 8.5, '{"poet":"Ersan Kurt","poet_slug":"ersan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/parcali-bulutlu-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aça-69 (Syk-5a)', 'aca-69-syk-5a-akin-akca-31szj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Altında Ay’ın, geceye karanlık çökmüştü

‘Zifiri siyah olmayan bir kirli kahverengi’ nin

Suları kıyısında, daha açıkça renkli,

Tepeler ve kir denizinden daha koyu ağaçlar

Yükseliyordu, barındırdığı canlılığı yutmaya nazır.

Bir silüet belirmişti tam da bu sırada:

Engin ufkun çekirdeğinde ya da

Çekirdeğin kendisi oydu, 

Ağaçtan bir dikili taş yükseldi

Tepesinde beton dikitler ve onlara ait

Pencereler barındıran,

‘Bu pencerelerin çatısı Japon yapılar’

En üstte yüzüyor, süzülüyordu.

İki tane ince kol, bu ‘orman-dağı’nı tutuyordu.

Ama o, en derinde açık yeşil, berrak deniz

Sınırsızlığı gökyüzüyle 

Bir noktada bitişmiş edimsiz:

Güçlüydü temeli, pınar ordaydı; 

Bazen sesli, bazen suskun, ama ‘Su Yer-Kulesi’! 

Teleferik gibi bir şeyle asılanlar vardı

Bu orman dağı’nın zirvesine doğru-

Diğer taraftaki inziva ama yine yeşil, 

Ayrık bölgeden: İçinde teleferiğin biri var mıydı? 

Bir koridor oluştu, sanatsal bir uzaylı şahaseri,

(Yürüyenler vardı, kafalar kukuletalı

Büyükçe sol gözleri ve büyüyen giderek..

Kırmızı gölgeler içinde kırmızı suratlı.)

Demirler var önünde,

Çıkacaksın uğraştığında sanki, 

Gayretin sana şevk verdiğinde-

…Video oyunlarındaki gibi! 

Savaşçı uzaylı uygarlığı,

Belki de geçmişimiz gibi:

Eller kavuşturan barışçıl atalarımızın

Bizimle, yarınımızı oluşturuşu.

Bir geminin içine uzandı daha sonra

Bu koridor, kamara pencereleri gibi:

Otel camları yanlardaydı,

Gün ışığı yerlerdeydi, hava aydınlık,

Ne bitmez bir uzunluk,

Belki de imamların cirit attığı

Bir hastanenin en alt katı

Tek tük insan oluşumları,

Garipçe sırıtıyorlar,

Bir kapıyı açarak odalardan birine daldım,

Sıra sıra cesetler, uskumru gibi istiflenmişler

Gözü kırpmamıştım, yukarı çekildiğimi hissettim:

(Gülen yoktu, sırıtan yoktu, ‘orman dağına giden boştu’)

(İki ayaklı kuleye doğru gidiyordum

Az önce imamların bakışları altındaydım:

Şimdi aşağı baktım; aşağı yok, yukarı da

Sis vardı, is de yoktu)

Teleferikteydim.

…', 'Altında Ay’ın, geceye karanlık çökmüştü ‘Zifiri siyah olmayan bir kirli kahverengi’ nin Suları kıyısında, daha açıkça renkli, Tepeler ve kir...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/aca-69-syk-5a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Züleyha (*)', 'zuleyha-mehmet-seyidhasanoglu-9lnqq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Z amana yenik düştüğüm bir vuslattı! 

Ü rkek ve biraz da yabani,

L alezar''ları didik didik edercesine aradım... yoktun! 

E n yüreksiz anımda yakaladın beni; 

Y alnız ve yorgunluğun haddindeyken yani! 

H ıçkırıklar düğümlene dursun yüreğimde; 

A ğlamaktan utanmadığım bir vuslattı; beni bulduğun! ....

                                       11.06.2004 /  cuma

                                          LİLAS / Van

                                    

(*) :  bu şiir dostum Necati''nin benden  ZÜLEYHA '' yı anımsatan bir şiir  istemesi ve benim o''nu kıramamam sonucu  yazılmıştır. Aksi halde anlattığım Züleyha'' nın benim için; bir hayal ürünü olduğunu belirtmek isterim....', 'Z amana yenik düştüğüm bir vuslattı!  Ü rkek ve biraz da yabani, L alezar''ları didik didik edercesine aradım... yoktun!  E n yüreksiz anımda...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Seyidhasanoğlu']::text[], 8.5, '{"poet":"Mehmet Seyidhasanoğlu","poet_slug":"mehmet-seyidhasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zuleyha-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelincik Zamanı', 'gelincik-zamani-zeki-ergin-jf6il', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'her bahar

gelincikler açar yüreğimde

acılarım tazelenir

kan kusarım

acılarımla başbaşa kalır 

hep susarım

sanki kök boya halıdır

yurdumun her yanı

acılardan umuda kesmiş

bir gelincik tarlasıdır

_erenköy 11haz04

_dağlara ver sırtını yt:haz09', 'her bahar gelincikler açar yüreğimde acılarım tazelenir kan kusarım acılarımla başbaşa kalır  hep susarım sanki kök boya halıdır yurdumun he...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelincik-zamani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Doğmak', 'yeniden-dogmak-erdal-sayil-c2bwe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kıvılcımın tutuşturdu yüreğimi,

Goncan gül-gül açıldı tenimde...

Teslim ettim eline benliğimi; 

Bir ben daha doğdu kendimde...', 'Kıvılcımın tutuşturdu yüreğimi, Goncan gül-gül açıldı tenimde... Teslim ettim eline benliğimi;  Bir ben daha doğdu kendimde......', ARRAY['Türk Edebiyatı','Şiir','Erdal Sayıl']::text[], 8.5, '{"poet":"Erdal Sayıl","poet_slug":"erdal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yeniden-dogmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-husamettin-gunacti-4v4s7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'boz bulanık ırmakla gel

mil ve tortu''yu sürükleyerek.

dağdan kopan kaya''yla gel

taş kalbini yumuşatarak.

birden boşalan sağanakla gel

ahmak gönlümü ıslatarak.

kör karanlığı delipte gel,

gel n''olursun! 

gel de nasıl gelirsen gel...', 'boz bulanık ırmakla gel mil ve tortu''yu sürükleyerek. dağdan kopan kaya''yla gel taş kalbini yumuşatarak. birden boşalan sağanakla gel ahmak ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gel-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askım', 'askim-mehmet-yilmaz-466n0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Askım sevdigim tek dermanım bak yinegeldim karsındayım.

En güzel duygularımla,

Erisilmez tutkularımla,

Unutulmayacak bir askla yanındayım.

Yüreginin kapılarını ac bak ben geldim.

Yolda yürürken yalnızlıgıma rastladım,

Yalnız kalamadıgı icin üzgün oldugunu söledi.

Ardından üzüntüyle karsılastım,

Eskisi gibi üzülemedigini söyledi.

Bu olanların hepsinin nedeninin sen oldugunu söylediler.

Ve bende sana olan askımı anlattıktan sonra cekip gittiler.

Bir ara seni anlatmamı istediler.

Anlatmak güc bakında görün dedim.

Ve esrarengiz bir sekilde kaybolup gittiler.

Arkalarından su dökmek isterdim,

Ama icimdeki sevinc gözyasları sana aitti, onlara veremezdim.

Simdi herkes hakkettigi yerde.

Onlar sonu olmayan gönüllerde,

Ben senin sıcacık yüreginde.

Sürgünüm artık sevgi dolu kalbinde.

(23/03/2004)', 'Askım sevdigim tek dermanım bak yinegeldim karsındayım. En güzel duygularımla, Erisilmez tutkularımla, Unutulmayacak bir askla yanındayım. Y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askim-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göç', 'goc-husamettin-gunacti-zikro', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sattı çiftini çubuğunu,

doldurdu tıka basa bavulunu,

tuttu İstanbul''un yolunu,

arkasına bile bakmadan.

görmüştü kaç kez filmde,

taşı toprağı altın şehirde,

geçinirim dedi bir şekilde,

umutsuzluğa kapılmadan.

ama tahmini yanlış tuttu,

neye el attıysa kuruttu,

koca şehir onu da yuttu,

insanları tanıyamadan.

sattı ayakkabısını paltosunu,

eline aldı boş bavulunu,

tuttu köyünün yolunu,

arkasına bile bakmadan...', 'sattı çiftini çubuğunu, doldurdu tıka basa bavulunu, tuttu İstanbul''un yolunu, arkasına bile bakmadan. görmüştü kaç kez filmde, taşı toprağı...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/goc-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönderilmemiş Bir Mektup Daha! ...', 'gonderilmemis-bir-mektup-daha-mehmet-seyidhasanoglu-kue6k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğimdi; seni görmeden, sana dair şiir yazdıran,

Yüreğimdi; seni canımdan da can belleten,

Gözlerimdi; yokluğunda, ateş kırmızısı...

Hani bir şiir yazsam sana dair! 

Sonra da gitsem! 

Kızar mısın? 

Yoksa; 

Ardımdan gözyaşı döküp, gitme mi dersin? ....

''tek gıcığım''...

Aklında bulunsun! 

Sana dair, şiirler biriktiriyorum cebimde,

Sana dair hayaller ve anlatılması güç ve doyumsuz bir aşk....

Sana dair bir dünya kurdum bize! 

Sadece ikimiz....

Yanımızda; 

Sigara, çay, makarna,

Haa! birde senin için yazdığım şiirler.....

Var mısın benimle gelmeye? 

Var mısın? 

Varım! 

dersen; 

Bil ki ben, 

Kırmızı karanfili kurumuş sokağın başında,

Seni kayıtsız, bekliyor olacağım.....

imza: tek gıcığın

                                 11.06.2004 / cuma

                                     Lilas / Van', 'Yüreğimdi; seni görmeden, sana dair şiir yazdıran, Yüreğimdi; seni canımdan da can belleten, Gözlerimdi; yokluğunda, ateş kırmızısı... Hani ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Seyidhasanoğlu']::text[], 8.5, '{"poet":"Mehmet Seyidhasanoğlu","poet_slug":"mehmet-seyidhasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gonderilmemis-bir-mektup-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi anlat', 'haydi-anlat-husamettin-gunacti-0wq2x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boğazdaki eski yalı,

sende kimbilir neler saklı.

içinde ne aşklar yaşandı,

fırtınalı ve hülyalı.

hiç anlatmıyorsun niye,

gerek yok çekinmene.

senin sırrın diye,

korkma söylemem kimseye...', 'Boğazdaki eski yalı, sende kimbilir neler saklı. içinde ne aşklar yaşandı, fırtınalı ve hülyalı. hiç anlatmıyorsun niye, gerek yok çekinmene...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/haydi-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karıncalar', 'karincalar-husamettin-gunacti-o6pls', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ağaca yaslanmış dururken

Karıncaları gözledim.

tümen tümen sıralanmışlar,

düğünleri mi vardı ne.

her yüzde ayrı telâş,

sanki dünyayı taşıyorlar.

böyle tembel otururken,

utandım ve imrendim onlara.

Arılara,Kuşlara,Karıncalara...', 'ağaca yaslanmış dururken Karıncaları gözledim. tümen tümen sıralanmışlar, düğünleri mi vardı ne. her yüzde ayrı telâş, sanki dünyayı taşıyor...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karincalar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığıma', 'yalnizligima-zubeyde-yilmaz-gmf2p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasret denizinde yüzdüm yine

Binlerce martı tepemde

Yalnızlığıma çığlık attı....

Özlemin ufka doğru

Yelken açtı

Durduramadım gidişi son sürat.....

Attığım her kulaç

Belki sana ulaşırım diye....

Yanan yüreğimi sustursun dalgalar

Islatsın kuruyan dudaklarımı

Saçlarımı okşuyor biryandan rüzgar...

Kayboluyorum,boğuluyorum

Uçsuz bucaksız hasret denizinde

Beni dibe çekiyor mavi perde

Köpüren hiddetinde....

Tut artık elimden,tut be gülüm

Çek çıkar beni derinlerden

Gücümü tüketti hasretin

Boğulmak istemiyorum SENSİZLİKTE.......

                                             11/06/22004', 'Hasret denizinde yüzdüm yine Binlerce martı tepemde Yalnızlığıma çığlık attı.... Özlemin ufka doğru Yelken açtı Durduramadım gidişi son süra...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizligima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi', 'haydi-husamettin-gunacti-x17zk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'katıl çok sesli korosuna ormanın

 sessizliğin sesi

 ürkek dalların armonisi

 hesabını sorsun geçmiş yılların

 uğultusuna dokun

 ya da saçlarına rüzgârın

 samyeliyle savrulsun

 maske takan duyguların

 göz pınarlarında gölle

 aşk yüzünden çektiklerini

 suskun yalnızlığınla dölle

 kimsesiz güz çiçeklerini

 haydi durma..! 

 durma söyle

 söylenmemiş sevda türkülerini...', 'katıl çok sesli korosuna ormanın  sessizliğin sesi  ürkek dalların armonisi  hesabını sorsun geçmiş yılların  uğultusuna dokun  ya da saçlar...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/haydi-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-husamettin-gunacti-xwvuh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sevgimi kuşlara,

derdimi bulutlara,

kalbimi bir tek sana

açmaya korkuyorum.

insanların yanına,

yıldızların koynuna,

haksızların suyuna

gitmeye korkuyorum.

sevip yalnız uyuyanı,

derde derman olmayanı,

aşka sadık kalmayanı

görmeye korkuyorum.

kalpsizlerin kalbine,

zalimlerin evine,

aşıklar denizine

girmeye korkuyorum.

içine sevgim dolmadan,

saçlarım ağarmadan,

sana âşık olmadan

ölmeye korkuyorum...', 'sevgimi kuşlara, derdimi bulutlara, kalbimi bir tek sana açmaya korkuyorum. insanların yanına, yıldızların koynuna, haksızların suyuna gitme...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/korkuyorum-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akarsu', 'akarsu-husamettin-gunacti-mvieh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bizler,

aynı kaynaktan doğan

delişmen sulardık.

kimimiz 

çağlayan olduk,

kimimiz

çay olmayı

arar olduk...', 'bizler, aynı kaynaktan doğan delişmen sulardık. kimimiz  çağlayan olduk, kimimiz çay olmayı arar olduk......', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/akarsu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim revaçta?', 'kim-revacta-husamettin-gunacti-gyl2x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'insanlar, sabah akşam

bir ömür çalışmakta.

kimi helâl para peşine,

kimi vurgun kapkaçta...', 'insanlar, sabah akşam bir ömür çalışmakta. kimi helâl para peşine, kimi vurgun kapkaçta......', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kim-revacta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağır Olsada-RPT', 'agir-olsada-rpt-erol-dal-e9c33', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağır olsa da 

Ödemek bu borcu

Alın yazımsın 

Kaderde ihanette varmış

Ölmek de', 'Ağır olsa da  Ödemek bu borcu Alın yazımsın  Kaderde ihanette varmış Ölmek de...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/agir-olsada-rpt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Albeni', 'albeni-yunus-salis-7ezba', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bedenim bakir

birkaç öpüştür

al

dudaklarım senindir bu gece

bakirliğim sana teslim

al beni

bedenim seninleyken var

kaçıncı zamansız bekleyişimin

kaçıncı amansız feryadımın meyvesisin

yalan bir yaşamda

yalansız kalabiliyorsam

şeffafsam

aşk gibi

red edilmişcesine bağlıysam 

senden sebep

dudaklarımda dolaşan

dudaklarımdan

albeni

götür başka bir diyara 

senden evvelinde yoktu aşk

seni bir bahar akşamı

bir bahar nefesi

seni

anlıyor musun

sırf seni

sus da dolaş dudaklarımda

bari yaşam

bir gecelik de olsa

bana aksın

alsın

götürsün dudaklarında 

dicle den fırat a', 'bedenim bakir birkaç öpüştür al dudaklarım senindir bu gece bakirliğim sana teslim al beni bedenim seninleyken var kaçıncı zamansız bekleyiş...', ARRAY['Türk Edebiyatı','Şiir','Yunus Şalış']::text[], 8.5, '{"poet":"Yunus Şalış","poet_slug":"yunus-salis","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/albeni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*....İşte Öyle Bir Gece....*', 'i-ste-oyle-bir-gece-erdal-asik-zu1ff', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bitmez sandığımız gecede

Yalnız biz vardık o sahilde

Ay ışığıyla parlayan

Gümüşten dalgalar

Şarkı söylüyordu gür sesiyle

Rüzgarın esintisiyle

Alkış tutuyordu yapraklar

Yıldız kümeleri süslüyordu

Göz kırpıyordu parıltılı semalardan

Aşkımızın alevi yanarken 

Gölgeler kendinden geçmiş

Sevişiyordu kumsalın üstünde

Gece ağlamaklı ardımızdan

Şafağın zayıf ışıkları 

Üstümüze düşerken

Yaşlar dökülüyordu tenimize

Özlem dolu bakışlarla

Yüzümüze gülüyordu güneş

Unutulmaz gecenin ardından

Mutluluk ışıkları saçıyordu

Uzaklardan tüm evrene', 'Bitmez sandığımız gecede Yalnız biz vardık o sahilde Ay ışığıyla parlayan Gümüşten dalgalar Şarkı söylüyordu gür sesiyle Rüzgarın esintisiyl...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/iste-oyle-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Tutundum', 'sana-tutundum-mehmet-cevik-hazerfen-cx1c2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'öyle bir yerde

öyle bir haldeyim ki şimdi

ellerim yara bere içinde

dalları kar yüklü çam ağaçları

gece ise balçık gibi

yapışmış yüreğime

yüreğimin baharında sakladığım güzel

neredesin? 

kuş uçmaz, kervan geçmez

bu uzak dağ kışlasında

nöbetini tutuyorum hasretinin

korkuyorum bazen de ölümden

seni bir daha göremeyeceğimden

terkedilmiş

boşaltılmış bi köy gibiyim

içimde baykuşlar öter

çıplak ayaklı çocuklar

yüreğimi ezer

bu viran içinde

bir hüzünlü asker

sadece seni özler

seni özlemenin ayrı bir tadı var

bir kokusu bir rengi var

ışığı var

aydınlatıyor dağları

bir bakışın 

bir gülüşün var

sanki cudi

bir sesin var 

yurdun bir ucundan bana gelen

sanki ilkbahar

bir yıldız gibi parlıyor gözlerimde

gece erken iniyor buralara

gidiyor güneş

kurtlara ve silahlara kalıyor dağlar

özlemek ağlamakla karışıyor

sonra anlamsız bir korku 

beni içine alıyor

ölüm sinsice yaklaşıyor

bu kadar saçmalığın içinde

anlamı olmayan herşey

sesinle değer kazanıyor

yaşamak 

ancak sayende çekilir hale geliyor

ama ben yine de

ağlamaklı oluyorum 

senden uzak her gece

her sabaha adınla başladım

bir dua gibi 

adını boynumda taşıdım

sana ve 

birde yıldızına sığındım bu dağlarda

öyle bir benim ki şimdi ben

ağzımda bir hasret türküsü

dudaklarımda sigara

yüreğimde sımsıcak sen

15.01.2004

 Mehmet Çevik (Hazerfen)', 'öyle bir yerde öyle bir haldeyim ki şimdi ellerim yara bere içinde dalları kar yüklü çam ağaçları gece ise balçık gibi yapışmış yüreğime yür...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çevik (Hazerfen)']::text[], 8.5, '{"poet":"Mehmet Çevik (Hazerfen)","poet_slug":"mehmet-cevik-hazerfen","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/sana-tutundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarışın Dilber', 'sarisin-dilber-sukru-demir-udxcb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep korktum sarışın dilberlerden

Sevmelerinden yalancı gülüşlerinden

Korkumun üstüne gittim

Sarışın dilbere gönül verdim.

Güzel görünen günlerde

Yaşamaya çalışılan mutluluklarda 

Hep korkumun üstüne gittim

Sarışın dilbere gönül verdim.

Doğrumu yaptım yanlış mı bilemedim

Bir anda kendimi evli buluverdim

Hep korkumun üstüne gittim 

Sarışın dilbere gönül verdim.

Mutlu olacağımı düşünürken 

Boşanıverdim birden

Hep korkularımın üstüne gittim

Sarışın dilberden nefret ettim.

Hep kaçmaya çalışırken

Yakamdan düşüremediğim 

Hep korkularımın üstüne gittim

Sarışın dilberden nefret ettim.

Kalk yanımdan sarışın dilber

Kapılacağım yeniden

Korkularımın üstüne gidemeden

Sarışın dilbere gönül vereceğim.

Hayatımı yeniden dağıttırmadan

Sacımı başımı yoldurmadan

Korkularımı tekrar yaşatmadan

Git sarışın diber git.', 'Hep korktum sarışın dilberlerden Sevmelerinden yalancı gülüşlerinden Korkumun üstüne gittim Sarışın dilbere gönül verdim. Güzel görünen günl...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Demir']::text[], 8.5, '{"poet":"Şükrü Demir","poet_slug":"sukru-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sarisin-dilber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertler', 'dertler-baykal-kaanalp-uffo3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kasap et derdinde

et kasap derdinde

biz et yemezler

ot derdinde', 'kasap et derdinde et kasap derdinde biz et yemezler ot derdinde...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dertler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandırılmak', 'kandirilmak-baykal-kaanalp-kvcrl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kaçınılmaz bir zamanı

kuşanmak,

ya da kuşatılmak

belli belirsiz anlarla

ayıklıyamamak

gereksizliğini,gerekmezliğini

dolu tribünlere oynamak

kadar göz alıcı

göz boyayıcı

kandırılmak

kandırılmaya çalışılmak', 'kaçınılmaz bir zamanı kuşanmak, ya da kuşatılmak belli belirsiz anlarla ayıklıyamamak gereksizliğini,gerekmezliğini dolu tribünlere oynamak ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kandirilmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmalı', 'olmali-baykal-kaanalp-cyptm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'inmek istediğin bir sondurak 

olmalı hayatında 

köşebaşında bekleyen 

bir yarının yoksa 

bağladığın umutları 

kendin çözmüşsen, ilmek ilmek 

vurdumduymazsa 

avlamak istediğin 

uçamayan avın 

demirini paslandıracağın 

bir rıhtımın olmalı 

olmalı sevdaya dönüşen 

tutkun olmalı 

olmalı kalpleri mühürleyen 

mührün olmalı 

ya taşımalısın 

yanık bir bağır 

ya da taşınmalısın 

aşkından ağır ağır', 'inmek istediğin bir sondurak  olmalı hayatında  köşebaşında bekleyen  bir yarının yoksa  bağladığın umutları  kendin çözmüşsen, ilmek ilmek ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/olmali-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Okunmalı', 'siir-okunmali-baykal-kaanalp-t3q23', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şiir okunmalı

bakanlar görmemeli

görenler bakmalı

bir yerlere götürmeli

götürdüğü yerden geri getirmeli

ulaştırmalı bulutlara

sonra insan kendi ayaklarıyla

inebilmeli çıktığı yerden

yarıp bakabilmeli

sevdiğinin yüreğini gönlünce

ameliyat etmeli kendini

bir doktor gibi

yaramaz uru kendi çabasıyla

yakabilmeli parça parça

öğretmeli yeniden yazmayı

herkese sınırsızca,gönüllüce

anlatabilmeli derdini

aşık,maşukuna

zamansız,mekansız,gamsız

korkusuzca

kendine güvenerek

severek,isteyerek

şiir okunmalı', 'şiir okunmalı bakanlar görmemeli görenler bakmalı bir yerlere götürmeli götürdüğü yerden geri getirmeli ulaştırmalı bulutlara sonra insan ke...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/siir-okunmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimbilir? ...', 'kimbilir-mursel-gokaydin-udfvk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kim derdi birgün böylesi yalnızlığa hapsedileceğimi

Kim bilebilirdi böylesi biçare kalabileceğimi

Hani dostluğuma kıymet veren arkadaşlarım

Hani, nerdeler şimdi? 

Eksik olan nedir, hayatı usandıran ne? 

Bu kaçıncı hüsrandır, bu kaçıncı arbede? 

Ölüm, her saniye adım adım gelirken...

Varsa eğer vuslatı halen daha ertelemenin anlamı ne? 

Kaç bahar eskittik, ne umutlar ekşittik kimbilir...

Bakışlarımız artık yorgun,

Yüzümüz artık solgun, farkındamısın? 

Karanlıktan korkmaksa eğer tüm bunlara sebep,

Yaşanılan bu zindansı günler çokmu daha güzel? 

Artık ellerim biraz daha pörsümüş gibi,

Yüzümdeki kırışıklıklar birazcık daha fazla.

Saçlarıma aklar düşmüş, 

Bakışlarıma usanmışlık,

Yirmili yaşlarımdan nekadar uzağım,

Heyecanlarımdan ne kadarda ırak.

Oysa bir arpa boyu yol alamadan,

Umutlarım mı küstü nedir? 

Heyecanlarım neden buz gibi? ...

Elem denen şeyin dudaklarımı mesken tutuşun anlamı ne? 

Neden sesim titrek artık, adımlarım neden bu kadar yavaş.

Oysa daha yolun başında bile değiliz belki

Yoksa, daha başlamadan kaybetmekmidir bu? 

Yoksa, daha adam gibi adam olamadan...

Umutları yeşertemeden...

Yaşlanmakmıdır, yaş almakmıdır....

Yoksa son durağa gelişin hissiyatımı? .....

16.04.2004   11:41', 'Kim derdi birgün böylesi yalnızlığa hapsedileceğimi Kim bilebilirdi böylesi biçare kalabileceğimi Hani dostluğuma kıymet veren arkadaşlarım ...', ARRAY['Türk Edebiyatı','Şiir','Mürsel Gökaydın']::text[], 8.5, '{"poet":"Mürsel Gökaydın","poet_slug":"mursel-gokaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kimbilir-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yalısı', 'ask-yalisi-seyfettin-kardas-yv7qd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yalımız olmalı,

Tepenin başında,

Taşı benden, toprağı senden...

Terimizi katmalıyız sıvasına,

Ellerimiz değmeli boyasına,

Kapısı, dostu  düşmanı tanımalı,

Görünce dostu kendi buyur etmeli,

Görünce düşmanı, kendi defetmeli,

Bahçesi sen gibi gül olmalı,

Odaları ben gibi sevgi dolmalı,

Biz gibi olmalı, 

Aşk yalısı...', 'Bir yalımız olmalı, Tepenin başında, Taşı benden, toprağı senden... Terimizi katmalıyız sıvasına, Ellerimiz değmeli boyasına, Kapısı, dostu ...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Kardaş']::text[], 8.5, '{"poet":"Seyfettin Kardaş","poet_slug":"seyfettin-kardas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-yalisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutmalı', 'seni-unutmali-seyfettin-kardas-4ww4d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece öyle uzun olmalı ki

Sabaha kadar herşey yanmalı

Sen, hatıralar, aşk ve sana dair olanlar

Bu gece öyle uzun olmalı ki

Külleri de yok etmeli, hiçbir iz kalmamalı geçmişten

Ya seni unutmalı, ya kendimi  yakmalı.', 'Bu gece öyle uzun olmalı ki Sabaha kadar herşey yanmalı Sen, hatıralar, aşk ve sana dair olanlar Bu gece öyle uzun olmalı ki Külleri de yok ...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Kardaş']::text[], 8.5, '{"poet":"Seyfettin Kardaş","poet_slug":"seyfettin-kardas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-unutmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taht', 'taht-seyfettin-kardas-0mhw8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tahtın var,

Kalbimin sarayında

Bahçesinde yemyeşil ağaçlar ve cıvıl cıvıl çocuklar

Ve seni yansıtan masmavi bir göl

İster çarp kapıyı çık,

İster oradan hükmet dünyama.', 'Bir tahtın var, Kalbimin sarayında Bahçesinde yemyeşil ağaçlar ve cıvıl cıvıl çocuklar Ve seni yansıtan masmavi bir göl İster çarp kapıyı çı...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Kardaş']::text[], 8.5, '{"poet":"Seyfettin Kardaş","poet_slug":"seyfettin-kardas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/taht-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şey Diyecektim', 'bir-sey-diyecektim-zafer-karalar-a8c93', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaç kez gidip-geldim kapına

            Dünyanın en yorgun denizi oldum

                        Endenozya kıyılarında

            Bir şey diyecektim sana 

            Yine de demek isterim



            Seni tanımadan önce bir yanım mı ağrırdı

            Ondan mı seninle su serpilir yüreğime

            Sana söyleyecek  bir sözüm vardı

            Bu değildi biliyorum



            Bağırmak geliyordu içimden

                         çıkıp yüksek tepelerde

            Rüzgârlar kesiyordu  sesimi

            Bu değildi söylemek istediğim

            Sana söyleyecek başka bir sözüm vardı

          

            Dokunmak geliyordu içimden

            Uzanıp dokunamıyordum sana

            Kalkmıyordu kollarım

            Tutsak gemilerin zincirleri gibi

            Paslanmış dökülüyordu sulara



            Bir şey diyecektim sana

            Kaç kez gidip-geldim kapına 

            Elim varmadı kapının koluna

            İçimdeki ses susmuyordu

            Ölünür diyordu

            Senin uğruna

            Senin yoluna', 'Kaç kez gidip-geldim kapına             Dünyanın en yorgun denizi oldum                         Endenozya kıyılarında             Bir şey di...', ARRAY['Türk Edebiyatı','Şiir','Zafer Karalar']::text[], 8.5, '{"poet":"Zafer Karalar","poet_slug":"zafer-karalar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-sey-diyecektim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yürek Birdi...', 'i-ki-yurek-birdi-i-brahim-ethem-bingul-6j3cb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çektin gittin istemeden

Bu kadar çok severken

Gidiyorum demeden hem de öpmeden

Yakışmadı sana beni böyle çok severken

Hani hayatımız bizimdi 

Ne o mutlu mu onlar şimdi

Ayrılmam diyen kimdi

Unuttun mu iki yürek birdi

Hava sıcak ten terliyor

Yürek yalnız çok üşüyor

Sevişsen ne olur yürek titriyor

Yürek sevişmeyince insan ısınmıyor.

www.iebingul.com', 'Çektin gittin istemeden Bu kadar çok severken Gidiyorum demeden hem de öpmeden Yakışmadı sana beni böyle çok severken Hani hayatımız bizimdi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iki-yurek-birdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz Umut', 'umutsuz-umut-zafer-karalar-8firq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni görünceye kadar geldi benimle

            Sonra takılıp gözlerine

            Ayrıldı benden



            O günden beri nedense bilmem

            Biraz sen, biraz ben

            Gidiyoruz peşinden



            Beni sende, seni bende istiyor

            Ölmaz öyle şey diyecekken

            Kayboluyor birden



            Dedim ya gidiyorum peşinden

            Bakıyorum sana varmış

            Göz kırpıyor gözlerinden



            Alıp geliyorum, kolay olmuyor

            Umutsuz bir umut ki bu

            Kahroluyor kederinden', 'Seni görünceye kadar geldi benimle             Sonra takılıp gözlerine             Ayrıldı benden             O günden beri nedense bilmem  ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Karalar']::text[], 8.5, '{"poet":"Zafer Karalar","poet_slug":"zafer-karalar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/umutsuz-umut-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-zafer-karalar-8hl0i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sensiz yaşarken

Uyurken uyanıkken

Neden örtülü yüzün? 

Seni sensiz yaşarken 

Birlikte dolaşırken

Neden çıkmıyor sesin? 

Seni sensiz yaşarken

Gülerken ağlarken

Nerdesin sen nerdesin?', 'Seni sensiz yaşarken Uyurken uyanıkken Neden örtülü yüzün?  Seni sensiz yaşarken  Birlikte dolaşırken Neden çıkmıyor sesin?  Seni sensiz yaş...', ARRAY['Türk Edebiyatı','Şiir','Zafer Karalar']::text[], 8.5, '{"poet":"Zafer Karalar","poet_slug":"zafer-karalar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nerdesin-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş ve Gerçek', 'dus-ve-gercek-zafer-karalar-z9xsp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yorgun bedenin

aç gönlüne

dar geliyor...

Bu sandal

o kıyılara taşımaz

seni... 

Unut artık...

Unut o düşleri...', 'Yorgun bedenin aç gönlüne dar geliyor... Bu sandal o kıyılara taşımaz seni...  Unut artık... Unut o düşleri......', ARRAY['Türk Edebiyatı','Şiir','Zafer Karalar']::text[], 8.5, '{"poet":"Zafer Karalar","poet_slug":"zafer-karalar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dus-ve-gercek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Tuhaf İnsanım', 'ben-bir-tuhaf-i-nsanim-umit-kilislioglu-ozger-2y6ad', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yanım doğuludur, 

Batılı öbür yanım; 

Akıl süzgecim yoktur,

Ben bir tuhaf insanım.

Kandırmaya kalkarım

Allah’ı ve kulları; 

Kopyayı çeke çeke, 

Tümlerim okulları.

Diplomalı cahilim,

Hiçbir işe yaramam; 

Tanımam, ilim, bilim

Sanatı hiç aramam.

Kitap okumak çile! 

Ne geçecek elime? 

Yeter de artar bile,

Bana üç yüz kelime.

Sözlükleri nedeyim? 

Uzak benden kaygılar,

Haydi artık gideyim

Size sonsuz saygılar! 

(12.Haziran.2004)', 'Bir yanım doğuludur,  Batılı öbür yanım;  Akıl süzgecim yoktur, Ben bir tuhaf insanım. Kandırmaya kalkarım Allah’ı ve kulları;  Kopyayı çeke...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-bir-tuhaf-insanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir a', 'zincir-a-aytekin-arik-cuq8v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hüzünlendiren ırağında ilgisiz

janjan kadifesi lastikli

minnoş nankör olmuş

ölmüş padişah rahmetsiz

seviyesiz şu talih

utanmaz üstsüz veballi

yalnızlığı zorunlu

		1', 'hüzünlendiren ırağında ilgisiz janjan kadifesi lastikli minnoş nankör olmuş ölmüş padişah rahmetsiz seviyesiz şu talih utanmaz üstsüz veball...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zincir-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarmıha Gerilmeyi Hakettim', 'carmiha-gerilmeyi-hakettim-hakan-karci-ocyso', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çarmıha gerilmeyi haketti yüreğim.

Bu suçluluğumun itirafıdır

Kaybolan umutların sebebi benim

Benim yüzümden kararır gökyüzü

Bir anda çehresi değişir hayatın

Rüzgarlar ben varım diye kasırga olur

Dökülen her gözyaşı benim eserim.

Çarmıha gerilmeyi haketti yüreğim.

Af kelimesini sildim lügatten

Hafifletici hiçbir nedenim yok

Hesaba sığmaz zaman dilimlerince hapsedilmeliyim zindanlarda

İşkencelerin en dayanılmazı yapılmalı

Çatlamalı dudaklarım bir damla suya hasret

Bir deri bir kemik kalmalıyım

Çarmıha gerilmeyi haketti yüreğim.

Paslı çiviler çakılmalı hiç acımadan

Her günahım için ayrı ayrı

Oluk oluk boşanmalı kanım

Yine de atmalı kalbim tüm kalpsizler için

Yaşarken son demlerini.

Asırlarca bekletilmeli ibret-i alem için cansız bedenim

Çarmıha gerilmeyi haketti yüreğim.

Yaptıklarına pişman edilmeli henüz yaşıyorken

Sevdaları bir bir yüzüne vurulmalı.

Seni çıkarmalılar karşıma,

Yüreğim kanarken gör beni diye.

İşte o an kırılmalı tüm direncim

Tükenmeliyim sen görmeden,

Tükenmeli yüreğim, sensizliğe isyanı içinde.

(c)   Hakan Karcı', 'Çarmıha gerilmeyi haketti yüreğim. Bu suçluluğumun itirafıdır Kaybolan umutların sebebi benim Benim yüzümden kararır gökyüzü Bir anda çehres...', ARRAY['Türk Edebiyatı','Şiir','Hakan Karcı']::text[], 8.5, '{"poet":"Hakan Karcı","poet_slug":"hakan-karci","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/carmiha-gerilmeyi-hakettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir b', 'zincir-b-aytekin-arik-z9qlm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bezmiş canından çelik

derman eyler faydasız

gitmiyor ğ hayalinden

ışık istemez Jüpiter

kan lekesi memesinde

niçin olmuştu öcü

papağanlığa razı sırdaşı

şaşırmış teni uyuşuk

üşür varlığı yalan 

zamanı ayıplar

			

		2', 'bezmiş canından çelik derman eyler faydasız gitmiyor ğ hayalinden ışık istemez Jüpiter kan lekesi memesinde niçin olmuştu öcü papağanlığa ra...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-b-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-gokhan-oflazoglu-hy9nh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen kıpkırmızı gülen

herkes için ölensin.

Sonsuzca kucaklayan,

.....için için ağlarken....

yalnız sevgi verensin.

Biliyorum susuşun

ben gidiyorum diye.

Ama, çöküşlerimde

sen hep güç verendin.

Şimdi öyle bakma bana,

sen ölümsüz güzelsin.

Döneceğim yine ben,

aldırma hiç.

Hayatı kuran sensin.

Aralık, 85', 'Sen kıpkırmızı gülen herkes için ölensin. Sonsuzca kucaklayan, .....için için ağlarken.... yalnız sevgi verensin. Biliyorum susuşun ben gidi...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/annem-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir c', 'zincir-c-aytekin-arik-d2tar', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'cansız çiçek derlenmez

eskimiş fistan gibi

ğ hapsetmiş ısınmıyor

ikinci jandarma karakolunda

leyleğin meramı neydi

onbaşı örneğine paydos

rahat sanma şimdi 

tutsak umutsuz üzgün

vurgun yanıyor zavallı

aşkı budanmış

		3', 'cansız çiçek derlenmez eskimiş fistan gibi ğ hapsetmiş ısınmıyor ikinci jandarma karakolunda leyleğin meramı neydi onbaşı örneğine paydos ra...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-c-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir d', 'zincir-d-aytekin-arik-dv6ri', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'defolu ehlidil fercrisadık

gibiydi ğ hoşnutsuz

ılgarlanmış iliksiz jilesi

kamuflenmiş loş meneviş

narin olmuş ölük

pürüzsüz reyhan süslenmiş

şarkılar tahriklemiş uçkun

ümera vaktiyle yaşlanacak

zira aşka bakış

cemekandan çıkacak

		5', 'defolu ehlidil fercrisadık gibiydi ğ hoşnutsuz ılgarlanmış iliksiz jilesi kamuflenmiş loş meneviş narin olmuş ölük pürüzsüz reyhan süslenmiş...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-d-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leblebi Kokar Dünyası', 'leblebi-kokar-dunyasi-zafer-zengin-etnika-fyb0c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saçları sarı çocuk

Kafasında kullası*

Leblebi kokar dünyası

Büyüdükçe boğar aynayı

Hayat bu

Hemen yutulmamalı

Saçları sarı hala

Kiraz dalı gömleği

Beyaz kol sıvalı

Çocuk saçların nasıl da sarı

Öldün mü çocuk

Yaşarken güzel yüzüme

Sevdiğim candın

Saçları sarı çocuk

Onlara nasıl kıydın

Sen dudak büken candın

Bir canı

Kızamık şekerine mi aldın

Saçları sarı çocuk

Üflüyor gülü

Yaprağı kopuyor dalından

Bir canı var canından

Saçları sarı çocuk

Kafasında kullası

Leblebi kokar dünyası

Ellerinde var nasırı

Kızıl şekeri çaldımı

/Yar yüzü tadı/Kırmızı

Çekirdek yemiş

Dişleri ondan acı

Gülüşü omuz sıcaklığı

İlişmesen de bir mevsim uyusak

Sonra 

Elma çekirdeği çalan

İlk çocuk olsak

Hazine bu

Kimseye çaktırmadan saysak

Bir/iki/gözlerin

Üç/dört/ellerin

Beş/altı..ooff yüreğim

Bitirdi giderken

Kimseye söylemeden

Vasiyet etmeden

Bir iki sen...

Alay eder koca adamlar/leblebinin tozuyla/Bir boğumluk tadı var oysa

27 Mayıs 2004 '' Kan konuşmaz ''

*Orlon veya yünden örülen takke''ye benzer sapka.', 'Saçları sarı çocuk Kafasında kullası* Leblebi kokar dünyası Büyüdükçe boğar aynayı Hayat bu Hemen yutulmamalı Saçları sarı hala Kiraz dalı g...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/leblebi-kokar-dunyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufaklık', 'ufaklik-yagmur-damlasi-aczua', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O ki! 

Düş gecelerimin yalnızlık türküsü

O yaşayamadığım gençliğim

Lanetli günlerimin amentüsü

Uğruna canımı bile verebileceğim

Nedenlerimin bir adım ötesi

Avuçlarımda kan

Mayamda hamur 

Yanağımdaki son yağmur 

hep O

O ki!', 'O ki!  Düş gecelerimin yalnızlık türküsü O yaşayamadığım gençliğim Lanetli günlerimin amentüsü Uğruna canımı bile verebileceğim Nedenlerimin...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ufaklik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir e', 'zincir-e-aytekin-arik-jq1uf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'evli fırsat gözetmiyen

ğ hotbin ılgım

ikiside jüri koltuklarında

liberalizm maneviyat nakkaresi

olanlar ölçüsüz palavra

romantizm sürtülmüş şilte

tutku uğraş üçgeninde 

vargel yargısı zamparalık 

açlık başlamadan caydırılan

çaba diktatörlüğü

		6', 'evli fırsat gözetmiyen ğ hotbin ılgım ikiside jüri koltuklarında liberalizm maneviyat nakkaresi olanlar ölçüsüz palavra romantizm sürtülmüş ...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir f', 'zincir-f-aytekin-arik-qua85', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'fakir görünen ğ

hasretliğine ısmarladığı inciler

jest kabahati lüzumsuzluğu 

malum nadim oflaz 

örtünmüş perişanlığı rakipsiz 

saçlarının şavkı tutulmuş 

unsurlu ücretsiz vesikalı 

yapmacık zebun ağaç 

bakımsız cansız çiçek

derneşiksiz eğlek

		7', 'fakir görünen ğ hasretliğine ısmarladığı inciler jest kabahati lüzumsuzluğu  malum nadim oflaz  örtünmüş perişanlığı rakipsiz  saçlarının şa...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-f-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir g', 'zincir-g-aytekin-arik-jp7w8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gizil ğ hayırlısı 

ıstıraplı isteksiz jigolo

kırmızı lokum morarmış

nasip olmadı ölüm

parçalanmış rağbet sinesi

şebnem tutmuş uykusu

ün vermiş yazğısı

zulme abone basbayağı

cezası çağcıl değil 

ensesinde felek

		8', 'gizil ğ hayırlısı  ıstıraplı isteksiz jigolo kırmızı lokum morarmış nasip olmadı ölüm parçalanmış rağbet sinesi şebnem tutmuş uykusu ün verm...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-g-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir h', 'zincir-h-aytekin-arik-9whis', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hürya ırzına ismetsiz

jölesi koyulaşmış limon

mertlik nafile oynaşa

ödül para rüşvet

siyaset şaibeli tanık

ucuz ülkücülük vukuflu

yarınsız zifiri akşamlarda

bin cefayla çaresiz

denetliyen eniştesi fırsatçı

gönyesiz ğ

		10', 'hürya ırzına ismetsiz jölesi koyulaşmış limon mertlik nafile oynaşa ödül para rüşvet siyaset şaibeli tanık ucuz ülkücülük vukuflu yarınsız z...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-h-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir ı', 'zincir-i-aytekin-arik-mtmph', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ıspatula işçisi Japon

kalmış lisede mahmur 

nemli odada öncel

paylanan rüsva sahipsiz

şeytan türemiş umarsız

üryan veballi yetingen

zevksiz albenisiz birliktelik

cembiyenlenmiş çürük dal

ehil feryatsız güne

ğ helalleşmez

		11', 'ıspatula işçisi Japon kalmış lisede mahmur  nemli odada öncel paylanan rüsva sahipsiz şeytan türemiş umarsız üryan veballi yetingen zevksiz ...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir j', 'zincir-j-aytekin-arik-t9u89', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'jandarmalık kollasaydı lirizm

mumyalanırdı nacakla ormancı

özür paganizmin resmi

susturulmuşluğu şekvacı tahripkar

uzantı üzüntüsüne varoşlar

yenilense ziyan akşamlar

başkasına cahillik çatallaşmak

denge eşitsizliği fıkra

garipsenen ğ hayelci

ırmağın içinde

		13', 'jandarmalık kollasaydı lirizm mumyalanırdı nacakla ormancı özür paganizmin resmi susturulmuşluğu şekvacı tahripkar uzantı üzüntüsüne varoşla...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-j-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller', 'guller-dilek-farhood-4ybwq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sakin koyma

Gonderdigim gulleri vazoya

Korkarim solar renkleri

Kiyamam onlara bakmaya...

Gonderemem resmimi

Alip koklarsin diye

Istemem uzulmeni

Katlanirsin hasrete

Gonderdigim gulleri

Al iyisi koy gonlune

Kirik dokuk dikenleri

Batmasin yuregine

Gonderemem resmimi

Avutamam yalanla seni

Ne yapar o kagit parcasi? 

Sen en iyisi bekle beni...', 'Sakin koyma Gonderdigim gulleri vazoya Korkarim solar renkleri Kiyamam onlara bakmaya... Gonderemem resmimi Alip koklarsin diye Istemem uzul...', ARRAY['Türk Edebiyatı','Şiir','Dilek Farhood']::text[], 8.5, '{"poet":"Dilek Farhood","poet_slug":"dilek-farhood","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guller-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etti', 'etti-i-smet-barlioglu-lbglh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Davrandım kalemime,

Güvendim kelamıma,

Yanlış geldi yanıma,

Bendeki tashih etti.

Kalemi tuttu eli,

Dilime indi dili,

Uydurduğum hayali

Bir kesin sahih etti.

Diz çöktük beraberce,

Ağladık gündüz, gece,

Hem de eyledik secde,

Kendini tesbit etti.

Sırrı koydu önüme,

İletti yüreğime,

Anlamadım ben yine,

Örnekle tasrih etti.

Lütfetti bu Barlı ''ya,

Bu gerçek efkarlıya,

Günahlardan karlıya

Atiyi tarih etti.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 331-332/412)', 'Davrandım kalemime, Güvendim kelamıma, Yanlış geldi yanıma, Bendeki tashih etti. Kalemi tuttu eli, Dilime indi dili, Uydurduğum hayali Bir k...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/etti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak Arayım Derken+', 'hak-arayim-derken-bayram-tunca-emhsk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hakkımı arayım dedim arttı derdim

Eli kurtarayım derken, koptu belim

Çile anlatayım derken yoruldu dilim

Şu hayat öykülerim acıklı birer film

Hak arayım derken, haksızlığa uğradım

Sanki suçlu benimmişim gibi horlandım

Havale edildim bir kapıdan öbür kapıya

N edeyim bozmuşlar bu güzelim yapıya

İnsan hakları, tüketici hakları, hep lafta

Sanık ile mağdur mahkemede aynı safta

Dayısı olanlar, her yerde daima ön safta

Çıkan kanunlar uygulamada kaldı sınıfta

Çilem gelmemiştir pişmiş tavuğun başına

Gerçi kiş bile dememiştim, elin tavuğuna

Gözüm yoktu hiç kimsenin malı mülkünde

Çünkü haram yoktu, emdiğim ak sütümde

Ah şu hayat göründüğü gibi toz pembe değil

Hey dost sanma ki herkes yaptığı işinde ehil

Şu cihanda öyleleri var ki sanki de Ebu Cehil

Bencileyin düşersen zalime hayatın olur rezil

15.05.2004-15.05

''Aşk Ateşten Gömlek''', 'Hakkımı arayım dedim arttı derdim Eli kurtarayım derken, koptu belim Çile anlatayım derken yoruldu dilim Şu hayat öykülerim acıklı birer fil...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hak-arayim-derken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arama Şeytan ''ı', 'arama-seytan-i-i-smet-barlioglu-oesvn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İzinsiz bir mala değdiğin zaman

Arama Şeytan ''ı; işte ordadır.

Kast ile bir cana değdiğin zaman

Arama Şeytan ''ı; işte ordadır.

Dedikodu yapsan kendi kendine,

Gizlide içine girdimi hiyle,

Kapını sımsıkı kitlesen bile

Arama Şeytan ''ı; işte ordadır.

Senin olmayanı alıyor isen,

Biriyle gıybete dalıyor isen,

Gören olmasa da çalıyor isen

Arama Şeytan ''ı; işte ordadır.

Bir gözde bir tek çöp gördüğün zaman,

Birine eksik mal verdiğin zaman,

İzinsiz bir yere girdiğin zaman

Arama Şeytan ''ı; işte ordadır.

Öfke yüreğine gelip otursa,

Ahlaksız bir hayal önünde dursa,

İbadet ederken çıkarın varsa

Arama Şeytan ''ı; işte ordadır.

Acizin başında cabbarlandınmı,

Yalan, dolan için kibarlandınmı,

Gücüne güvenip barbarlandınmı

Arama Şeytan ''ı; işte ordadır.

Haklıyı hakkından caydırır olsan,

Haksızı hak diye saydırır olsan,

Gözünü namusa kaydırır olsan

Arama Şeytan ''ı; işte ordadır.

Sakladınmı suçu hem de işleyip,

Kaptınmı bir hakkı hem de dişleyip,

Vurdunmu birini hem de şişleyip

Arama Şeytan ''ı; işte ordadır.

Kendin aç değilken açsa yakının,

Haramla dolmuşken kirli çıkının,

Hakkını yemişken helal uykunun

Arama Şeytan ''ı; işte ordadır.

Eğilimin yoksa Şeytan yaklaşmaz,

Onla uğraşmazsan o da uğramaz,

Şeytan ahlaklıya değmez, bulaşmaz,

Arama Şeytan ''ı; işte ordadır.

Barlıoğlu der ki; boz, akdin varsa,

Bir haksızlık için gönlün kalkarsa,

Varlığın elleri nara yakarsa

Arama Şeytan ''ı; işte ordadır.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 333-335/412)', 'İzinsiz bir mala değdiğin zaman Arama Şeytan ''ı; işte ordadır. Kast ile bir cana değdiğin zaman Arama Şeytan ''ı; işte ordadır. Dedikodu yaps...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/arama-seytan-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hükmetsen Hükmedilir', 'hukmetsen-hukmedilir-i-smet-barlioglu-akiba', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Peşin hükümlü olma,

Hükmetsen; hükmedilir.

Her anında O ''na git,

Bekletsen; bekletilir.

Kötü işe erk etme,

Kalbe günah zerketme,

Seviyorsan terketme,

Terketsen; terkedilir.

Hırslının hali yaman,

Sonunda der elaman,

Verilene her zaman

Şükretsen; şükredilir.

Değer verme tek pula,

Hem paraya, hem mala,

Darda kalmış yoksula

Lütfetsen; lütfedilir.

Bir hakka bir iş yeter,

İşi kolayca göster,

Gereğinden çok beter

Terletsen; terletilir.

Düzünden tut özünü,

Verdinmi tut sözünü,

Haksız yere gözünü

Parlatsan; parlatılır.

Yap ancak gereğini,

Hem de iyiden iyi,

Yoksulun yüreğini

Darlatsan; darlatılır.

Barlı der; dal, yaprak ol,

Ahlak için kıvrak ol,

Namusa göz, kulak ol

Kirletsen; kirletilir.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 336-337/412)', 'Peşin hükümlü olma, Hükmetsen; hükmedilir. Her anında O ''na git, Bekletsen; bekletilir. Kötü işe erk etme, Kalbe günah zerketme, Seviyorsan ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hukmetsen-hukmedilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmadı Yerde', 'kalmadi-yerde-i-smet-barlioglu-1kuc2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hikmet der; çobandım, derbeder idim,

Aşkı durur sandım, sürdüm yürüdüm,

Düştüm bir ateşe, yandım, eridim,

Kurudu çamurum kalmadı yerde.

Hikmet der; atlara çakıyorum nal,

Gönlüm demirlerle olmuştu hoşhal,

Kalmadı böylece bende hiç mecal,

Ekşidi hamururm, kalmadı yerde.

Hikmet der; hoıcaydım, sesim Davud ''i,

Kanıma batırdım tüyden dividi,

Gaiplerden bana ''Gel'' eylenildi,

Tükendi umurum, kalmadı yerde.

Hikmet der; terziydim, işim ipekle,

Ömrümü döverdim tunçtan dibekle,

Bana emredildi; ''Gel, biraz bekle'',

Küflendi samururm, kalmadı yerde.

Hikmet der; yapardım boya, badana,

Çok cevher sıvadım kerpiç duvara,

Terkettim dünyamı, oldum avara,

Yıkıldı mamurum, kalmadı yerde.

Hikmet der; derviştim, gönlüm delice,

Çıldırdım, sayrıdım bir aşk gelince,

Ağladım durmadan gündüz ve gece,

Kırıldı billurum, kalmadı yerde.

Barlıoğlu der ki; oldum ürperiş,

Bir ayni duayı eyledim derpiş,

Hala yaşıyorum, geliş o geliş,

Döküldü yağmurum, kalmadı yerde.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 338-339/412)', 'Hikmet der; çobandım, derbeder idim, Aşkı durur sandım, sürdüm yürüdüm, Düştüm bir ateşe, yandım, eridim, Kurudu çamurum kalmadı yerde. Hikm...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kalmadi-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niçin?', 'nicin-i-smet-barlioglu-yrl7m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben çoktan soyundum şalvardan, şaldan,

O samur kürkleri niçin giyeyim? 

Meyve benim değil, çalınmış daldan,

O haram lokmayı niçin yiyeyim? 

Ben herşeye baktım, hem de görerek,

Sözümü söyledim, hem de bilerek,

Sır bana verildi esirgenerek,

Onu cahillere niçin vereyim? 

Çok şeyi topladım zerre ve zerre,

Sırredip sakladım bir kutsal yere,

Kalkıp kıyamazken saf gönüllere

Ayaklar altına niçin sereyim? 

Kendimi vermişim sırra, nikahta,

Ömrü tamamladım ah ile vahta,

Çilemi doldurdum eski dergahta,

Yeniden dergaha niçin gireyim? 

Çekersen cefayı çek dervişlerle,

Hayatın süslensin menevişlerle,

Uğraşmak dururken güzel işlerle

Ahlaksız uğraşı niçin seveyim? 

Barlıoğlu diyor; zerre boş değil,

Her derviş görünen bir derviş değil,

Çirkinde güzellik görülmüş değil,

Ağuyu bal gibi niçin göreyim? 

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 340-341/412)', 'Ben çoktan soyundum şalvardan, şaldan, O samur kürkleri niçin giyeyim?  Meyve benim değil, çalınmış daldan, O haram lokmayı niçin yiyeyim?  ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/nicin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niçin Böylesin?', 'nicin-boylesin-i-smet-barlioglu-7qssa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yedirsen cimrisin, yiyorsan cömert,

Madem öylesin de niçin böylesin? 

Söylerken çok mertsin, dinlerken namert,

Madem öylesin de niçin böylesin? 

İçerde kibarsın, dışarda kaba,

Ellere hovarda, kızına baba,

Bazan bir günaydın, bazan merhaba,

Madem öylesin de niçin böylesin? 

Hakkına kartalsın, borcuna sinek,

Alırken dosdoğru, verirken dönek,

Görünüşte kavun, gerçekte kelek,

Madem öylesin de niçin böylesin? 

Gündüz elin işler, dilin gümbürder,

Gece o heybetin kıl gibi biter,

Elinle dilini aczin kilitler,

Madem öylesin de niçin böylesin? 

Zengine mahkumsun, toksula hakim,

Ele cahil cellat, kendine hekim,

Özünle kabuğun ayrı nitekim,

Madem öylesin de niçin böylesin? 

Çullulara dostsun, çulsuza düşman,

Pullulara köpek, pulsuza yılan,

Mazluma belasın, zalime güman,

Madem öylesin de niçin böylesin? 

Haramda zehirsin yahut zemberek,

Zorbalık dendimi kobra, engerek,

Hiylede, yalanda demir değenek,

Madem öylesin de niçin böylesin? 

Ağlarsın dışarda, gülersin evde,

Kölesin şhirde, ağasın köyde,

Dışın zemzemlerde, için alevde,

Madem öylesin de niçin böylesin? 

Barlıoğlu der ki; düz ol cetvelden,

Bir gün yeller geçer altın temelden,

Asla farklı tutma kendini elden,

Madem öylesin de niçin böylesin? 

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 342-344/412)', 'Yedirsen cimrisin, yiyorsan cömert, Madem öylesin de niçin böylesin?  Söylerken çok mertsin, dinlerken namert, Madem öylesin de niçin böyles...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/nicin-boylesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pabuç Pahalı', 'pabuc-pahali-necmi-unsal-6qgr0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevda çarşısında benim pabuç dama atıldı.

Sevgiler alıp satardım,  dükkanım  kapatıldı.

Pabucumu ahu  gözlüm verdi artık  elime.

Pabuç bırakmadım, hüzün doladım ben belime.

Çok safım, anlayamadım; hep pabucum çevrildi.

Pabucumu giydirdiler ters,  filizim  devrildi.

Eşiğinde  aşındırdım yollar, pabuç  eskittim.

Beklerim visâli,  kabul etmezse  artık  bittim.

Ben pabucu yarım, baktım ki pahalı bu pabuç; 

Dedim kendime:“ Pabuçsuz kaç, hemen buradan uç.”

Anladım, bildim; ayarım  pabuçtan  çok  aşağı.

Tüylenmiş  tay  gibiyim ben,  gıdıklıyor  kaşağı.

Dünyaları  bir  pabuca  çalışırım  sokmağa.

Ben  çan  oldukça  daha  çok  alışırım  tokmağa.

Onu beklerken  aklımı  kapısında  okuttum.

Bir pabucu  büyük buldum da kendimi okuttum.

6 Nisan 2004 Salı, Danimarka-Køge  22.37

8+7', 'Sevda çarşısında benim pabuç dama atıldı. Sevgiler alıp satardım,  dükkanım  kapatıldı. Pabucumu ahu  gözlüm verdi artık  elime. Pabuç bırak...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/pabuc-pahali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayamalağın Kızı', 'mayamalagin-kizi-ali-gencay-exejm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çarık ayağında sırtında abası

yehdiydi anne kucağında

Yemende kalınca babası

yokluktan kurumuş göğüsleri

çatlamış topraklar neyler anası

sahanda çok su az çavdar maması

ağlamaktan gözleri görmez olmuş

her gıcırdayışında hayatın kapısı

‘’Oğlum,, der dururmuş büyük anası

Abdullah da ibişin abdulmuş adı

seferberlik duyurulmuş 

Garbdan alınmış Osmanlı tuğrası

On beşli türküsüyle uğurlanmış

Sulsusokağı çınlatan  at nalları

Yemen’e çıkmış pusulası

daha giymeden kalpağı 

baba evinde matem havası

demek ondandı ağabeyime  bakıp bakıp

 ‘’babamın adı ağzımın tadı,,

onda buldu onda yaşadı hep babası

hafiften sendeleyerek yürürmüş

köyün kadınları maymalak demişler

daha ondokuzundaymış anası

mart dokuzu çıkmış

avradı ölen davulcu dünürcü gelmiş

yeniden kınalanmış ayası

yıllar yılları kovalamış

yemen türküsü tellenmiş

ne haber gelmiş nede babası

yehdi büyümüş gelinlik olmuş

evermişler alınmadan başlık parası

yiğidi olmuş heykel ali damadı

oda kınalanmış yüreğinde baba acısı

on çocuk doğurmuş

yedisi ölmüş üçü başının kadası

ölenler abdulmuş

kalanlar Ömer’i Minüres’i Fatımas’ı

yiğidini vermiş cigaraya

mart dokuzu zemheri ayazı

torunlar bir kucak dolusu çiçek tarlası

ömür bu seten taşı 

zamanı dolan gider bibim gibi

dikilir mezar taşı', 'çarık ayağında sırtında abası yehdiydi anne kucağında Yemende kalınca babası yokluktan kurumuş göğüsleri çatlamış topraklar neyler anası sah...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/mayamalagin-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Bir Mektup', 'garip-bir-mektup-umit-kilislioglu-ozger-7r90h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgilim bak! 

Bu gece pencereyi açık bırak! 

Umurumda değil yasa masa

Ayaklarımın ucuna basa basa

Gelip, gireceğim evine.

Sen sevine sevine,

Yatak odana gir, yat

Kapıyı da iyice kapat.

Çıkma tıkırtı duyarsan! 

Sevinirim eğer masaya 

Yiyecek ve çiçek de koyarsan.

Sürprizimi  sakın bozma,

Bekle! 

Olma sabırsız.

İmza: Hırsız

(12.Haziran.2004)', 'Sevgilim bak!  Bu gece pencereyi açık bırak!  Umurumda değil yasa masa Ayaklarımın ucuna basa basa Gelip, gireceğim evine. Sen sevine sevine...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/garip-bir-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YarımHaziran', 'yarimhaziran-sule-aydemir-3g5ij', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'daha az önce 

yalnızlık çaldı kapımı

alamadım içeriye 

açıp da kapıyı

kirpiğimin ucu kadar 

uzak acısı

ayrılığın mevsimi

gelir 

aylardan haziran

yaşama karşı

dizlerim kırılır 

boynum bükülür aşka

yüreğimi saklarım

köşe bucak

dağlarım içimi

yaşam bu

beni dinler mi 

bir 12 haziran sabahı

giymiş yalnızlık

en güzel giysisini 

daha az önce 

kapımı çaldı yine 

tükürdüm cesaretime 

aldım içeriye

mutluluğum 

kirpiğimin 

ucu kadar uzaktı 

____ilk ölüşümündür 

___________bir 12 haziran sabahı



*kalemi gönülden mürekkepli kadının günlüğünden', 'daha az önce  yalnızlık çaldı kapımı alamadım içeriye  açıp da kapıyı kirpiğimin ucu kadar  uzak acısı ayrılığın mevsimi gelir  aylardan haz...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yarimhaziran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyamet', 'kiyamet-naime-erlacin-5661j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'önce kendinden ayrı düşüp, sonra buluşan bir çığlıktır şair…N.E.

 ayrılık yazdım gecelerce

ayrı düşmelerimi benden

bitti sandım

renk kardım paletimde yeniden 

kefen biçtim ölüme 

susturdum sirenleri

içimi meczup bir rüzgar doldurdu

kehribar saraylardan savrulan yakıcı bir tül gibi

rüzgar deli

rota 

kelamın mahşeri

geçitler kavilde gizli 

sordum esatire:

“geçilir mi ayrılık”

dedi 

“geçilmez! 

rüyadır içinde yürünen

şart düşer ayrılığa ayrılık

önce kavuşmak gerek

sonra yalnızlık”

sonra? 

“kıyamete uzar bu yol, yürü! ”

(12 Haziran 2004)', 'önce kendinden ayrı düşüp, sonra buluşan bir çığlıktır şair…N.E.  ayrılık yazdım gecelerce ayrı düşmelerimi benden bitti sandım renk kardım ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kiyamet-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Korkuyorum masum ölümden', 'korkuyorum-masum-olumden-i-lkgul-celebioglu-t6kt9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son sıgaramdı sanki bu

Bir an yaşamdan farklı olan

Mahsum ölümü hatırladım

Gözlerimi bile kapatmaya korkuyordum

Masumluğunu yaşamayan

Yaşamda kalmak istercesine

........

Ölüme çağıran hastalık,

Pençesini geçirmiş beynime

Saydığım günler ve azalan ömrüm

Gözlerimi bile kapatmaya korkuyordum

Masumluğunu yaşamayan

Yaşamda kalmak istercesine', 'Son sıgaramdı sanki bu Bir an yaşamdan farklı olan Mahsum ölümü hatırladım Gözlerimi bile kapatmaya korkuyordum Masumluğunu yaşamayan Yaşamd...', ARRAY['Türk Edebiyatı','Şiir','İlkgül Çelebioğlu']::text[], 8.5, '{"poet":"İlkgül Çelebioğlu","poet_slug":"i-lkgul-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/korkuyorum-masum-olumden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Gibiyim', 'gibiyim-i-lkgul-celebioglu-os379', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'her insanın ödeyeceği bir bedel vardır,

hayatın zorluklarını elbet aşacaktır

gülmekte ağlamakta birer oyuncaktır

oyuncağı elinden alınmış çocuk gibiyim.

Dertsiz başım karalar bağlar

insanoğlu bu hep böyle yaşar

gülerken ağlamak neye yarar

Ağlanacak halime güler gibiyim.

Çiçek dalından koparılsa solmaz mı

balık sudan çıksa yaşar mı

karagün dostu birgün çıkar mı

Teknesi batmış kaptan gibiyim.', 'her insanın ödeyeceği bir bedel vardır, hayatın zorluklarını elbet aşacaktır gülmekte ağlamakta birer oyuncaktır oyuncağı elinden alınmış ço...', ARRAY['Türk Edebiyatı','Şiir','İlkgül Çelebioğlu']::text[], 8.5, '{"poet":"İlkgül Çelebioğlu","poet_slug":"i-lkgul-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gibiyim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '/Düşündümse yalan/', 'dusundumse-yalan-i-lkgul-celebioglu-dvyxf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir dünya kurmuştum kendime hayallerimle

Dünyamın içinde kuşlar,çiçekler güzel insanlar var

Boş bir anı kalsın isteme ellerimde

Geçmişe bakıp bir of çektimse YALAN

Saatini doldurup gidecek bu yolcu

Hani hep bekler zaten zaman gerçekleri

Hayat bazen çok rahat bazen çok yorucu

Bir çaresizliğe düştümse YALAN

Eriyen kar taneleri gibi oldu hayat

Oysa sevmeyi sevilmeyi bilmeliydi insan

Elveda deyip giderken içim çok rahat

Hakkımı haksız düşündümse YALAN', 'Bir dünya kurmuştum kendime hayallerimle Dünyamın içinde kuşlar,çiçekler güzel insanlar var Boş bir anı kalsın isteme ellerimde Geçmişe bakı...', ARRAY['Türk Edebiyatı','Şiir','İlkgül Çelebioğlu']::text[], 8.5, '{"poet":"İlkgül Çelebioğlu","poet_slug":"i-lkgul-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dusundumse-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülküye Nöbet', 'ulkuye-nobet-ahmet-aksoy-w458e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'mavzerinin gölgesi vurdu ayın

o ki nöbet tutar etrafında dünyanın

..........................ışıktan uzak kalınca 

....................................çakallar üşüşür başa

..........................güneş uykuya dalınca 

....................................şeytan keşfe çıkara yaya

ama hep biri vardır bekleyen

gözleri yorgun elleri nasır

............kimi aziz olur kimi şair

...................ülküsünde ışığın', 'mavzerinin gölgesi vurdu ayın o ki nöbet tutar etrafında dünyanın ..........................ışıktan uzak kalınca  .............................', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ulkuye-nobet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benlik', 'benlik-cengiz-oyke-2ux7k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir adam çıktı ortaya 

Elini kaldırıp havaya 

Benim ben dedi 

Bütün benler güldü adama 

Bırak dediler benliği sen sen ol 

Benlik yakışmaz insan olana 

Adam kızdı onlara 

Hepiniz toplansanız bir ben edermisiniz 

Benlerden biri çıktı ortaya 

Çekti okunu vurdu adamı 

Can çekişen adama ben Azrailim 

Sen kim oluyorsun dedi.', 'Bir adam çıktı ortaya  Elini kaldırıp havaya  Benim ben dedi  Bütün benler güldü adama  Bırak dediler benliği sen sen ol  Benlik yakışmaz in...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Öyke']::text[], 8.5, '{"poet":"Cengiz Öyke","poet_slug":"cengiz-oyke","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benlik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşük', 'usuk-ahmet-aksoy-o8juw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aslım yalandır benim

........mayamda günah

şeytanda neymiş a canım

.........istexsem kanar mıyım

sürgün yemiş ruhum dünyevi arzuya

......acı çeker cehenem budur

cennet dediğin ölmek olmalı

......hayat dediğin amaca yoldur', 'aslım yalandır benim ........mayamda günah şeytanda neymiş a canım .........istexsem kanar mıyım sürgün yemiş ruhum dünyevi arzuya ......acı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/usuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevgim Başkadır Başka', 'benim-sevgim-baskadir-baska-tulay-sustam-156l4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I.

Senin gelinciğin ben

Benim kelebeğim sen

''Gelincik boynunu büker,

Kelebeğin ömrü azdır '' derler. 

Sen benim tomurcuğuma konduktan sonra

Ben hiç boynumu bükmedim

Ben hiç solmadım...

Ömrümü ömrüne ekledim kelebeğim

Olur da...

Bir başka çiçeğe konarsan

Ömrümü ömründen alırım

Boynumu toprağa karşı bükerim...

II.

Sen koca çınarım

Sen gözbebeğim

Sen ömrüm, yaşama sevincim

Sen kurumayasın diye...

Gölgende seni gözyaşlarımla sularım

Olur da...

Bir başkası gölgende dinlenirse

Dalların bir başkasına kol kanat gerirse

Köklerin bir başka toprağa kök salarsa

Gövdeni kökünden ayırırım

Gözyaşlarımı siler, kurumanı beklerim. 

(çömez şaire)', 'I. Senin gelinciğin ben Benim kelebeğim sen ''Gelincik boynunu büker, Kelebeğin ömrü azdır '' derler.  Sen benim tomurcuğuma konduktan sonra B...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/benim-sevgim-baskadir-baska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örümcek''ler', 'orumcek-ler-ahmet-aksoy-kraye', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çek kılıcını Dartanyan

....dostum Portos sende hazırlan

...geliyor yaklaşan meteorlar gibi

.....................................savaş vakti

ki artık yok bizim için

............bahtiyar bir an

...ağımız meşakkattir 

yıldızlara uzanan', 'çek kılıcını Dartanyan ....dostum Portos sende hazırlan ...geliyor yaklaşan meteorlar gibi .....................................savaş vakti ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/orumcek-ler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Üstüne', 'gercek-ustune-i-smet-barlioglu-29v16', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Demir bir kütleyi çok ağır sanan

Sırrın eşiğinden girmemiş olur.

Tuncun sertliğine kanıp inanan

Perdenin ardını görmemiş olur.

Suyu göremeyen taşlardan kavi,

Kuşu göremeyen file müsavi,

Mantıkla etmeyen aklı tedavi

Henüz alfabeyi bilmemiş olur.

Bir insan sandımı toprağı toprak; 

Ona yaprak gelir daldaki yaprak,

Kekeler gerçeği ufalayarak,

Tek adım beriye gelmemiş olur.

Gördükleri şeyi gerçek sananlar,

Bir cisme değenler, alıp tutanlar,

Lezzeti tadanlar, sesi duyanlar

Mantıktan tek bir ders almamış olur.

Akıllar verdimi hayale özü

Artık ne algılar, ne dinler sözü,

Gerçektir zanneder mavi, kırmızı,

Gerçekle başbaşa kalmamış olur.

İnsanlar hayale doğru gittimi,

Bastığı yerlere çok güvendimi,

Yıldızlı gökleri boş görmedimi

Gerçekler aşikar olmamış olur.

Barlıoğlu der ki; sırlar derince,

Şekil neye yarar göremeyince? 

İnsan biröok sırrı keşfetmeyince

Gerçeği arayıp bulmamış olur.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 345-346/412)', 'Demir bir kütleyi çok ağır sanan Sırrın eşiğinden girmemiş olur. Tuncun sertliğine kanıp inanan Perdenin ardını görmemiş olur. Suyu göremeye...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gercek-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Unutmadan gidiyorum', 'unutmadan-gidiyorum-i-lkgul-celebioglu-fgbxl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Belâsız günlerin,belalı bir vaktinde bıraktın ellerimi

Zamansız bir gidişin cezasını çektirdin yüreğime

Ayrılık kokan rüzgârlara salıverdin bedenimi

Oysa ben hiçbirzaman unutmadım seni', 'Belâsız günlerin,belalı bir vaktinde bıraktın ellerimi Zamansız bir gidişin cezasını çektirdin yüreğime Ayrılık kokan rüzgârlara salıverdin ...', ARRAY['Türk Edebiyatı','Şiir','İlkgül Çelebioğlu']::text[], 8.5, '{"poet":"İlkgül Çelebioğlu","poet_slug":"i-lkgul-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/unutmadan-gidiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '8 Yağmuru', '8-yagmuru-turgay-kaygi-zfpw2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'son günlerde

ne yaptımsa

kurtaramadım kendimi

çiğnendikten sonra fırlatılıp atılmış

bir sakız gibi hissetmekten...

üstüne sizi gördüm

düş müydünüz gerçek mi belirsiz...

açık olan şu:

siz

siz değildiniz...

bir vakitler

yemin ederim ki

ne kalemin yazası vardı

ne dudakların anası isminizi

velakin bu beyin denilen

et yığınında

kan niyetine dolaşıyordu resminiz...

muhteşem bir karanlığın ortasında

ezbere bildiğim mutluluğu bağırmaktaydık bir ağızdan

tam da çizdiğim labirentlere gizlediğim boğma rakıyı

çıkaracaktım ki yerinden

bir bebek ustalığıyla ağladığınızı duydum... ne tuhaf! 

gel de şimdi o rakıyı boğma! 

......................

......................

üzgünüm! kapadığınız kapıları

bizzat ben kilitledim üstünüze...

bıraksam kaçar gidersiniz! 

kırlangıçlık var gibi ruhunuzda! 

ne kadar zırlasanızda

o kapıların ardında

sonsuza dek benimsiniz...

sözkonusu sizseniz şayet

ben gayet deliyim! 

(inegöl,  28.05.2004)', 'son günlerde ne yaptımsa kurtaramadım kendimi çiğnendikten sonra fırlatılıp atılmış bir sakız gibi hissetmekten... üstüne sizi gördüm düş mü...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/8-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Demişim', 'ask-demisim-ozgur-aysun-beksari-8ev81', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Koca bir denizin ortasındaymışım

Yürüyormuşum üstelik..

Yukarı kaldırmışım başımı

Masmavi gökyüzü..

Aşağı indirmişim

Mavi büyük bir deniz

Ve bendeniz,

Çok susamışım

Nefeste alamazmışım üstelik...

Anlamamışım.

Üstte mavi gökyüzü

Altta parlak bir deniz

Ben susuz,nefessiz

Şaşırmışım...

Seni beklermişim üstelik

Hiç görmediğim ama bildiğim

Adına aşk dediğim seni...

Nereden geleceksin bilmemişim

İçim öyle acımış ki 

Beklemişim...

Yağmur yağmış gökyüzünden toplamışım her damlayı

İçlerine bakmışım

Balıklar geçmiş ayaklarımın arasından 

Sana bakmışım

Heryerde aramışım...

Bir gün gelmiş çıkmışsın ortaya

Ama bilememişim

Su mu göndermiş seni yoksa havamı

Hangisine şükretmeliymişim

Gelmişsin ya

Olsunmuş

Sevinmişim....

Sonra bir başlamışsın konuşmaya

Kurşun gibi her kelime

Saplanmış yüreğime

Ağır yaralanmışım..

Olsun sana hiç kızmamışım...

Sen değilmişsin beklediğim

Anlamışım...

Arkanı dönüp giderken sen, ben ağır yaralı,

Sana el sallamışım...

Ve yine koca deniz ortasında

Yalnız bir ben kalmışım...

Başımı yukarı kaldırmışım

Tanıdık gökyüzü...

Ve aşağı indirmişim mavi bir deniz

Ama aynı görünmemiş gözüme ikiside

Bendeniz,

Çok susamışım, hala nefessizmişim üstelik....

Sokup kalbimin içine elimi

Seni avucuma almışım..

Seni gömmeye kıyamamışım...

Sırf deniz ve gökyüzü

Kıskanmasınlar diye birbirlerini

Seni bölmüşüm ikiye...

Yarını fırlatmışım gökyüzüne

Kimse uzanamasın diye

Yıldız yapmışım...

Kalanı serpmişim denizlere

Kimse açamasın diye

Midye yapmışım...

Hediye etmişim seni gökyüzüne ve denize...

Sen güzel arkadaşım! 

Bana aşkımı soruyorsun? 

Gökteki yıldız

Midyedeki inci

Nasıl oldu Sanıyorsun?', 'Koca bir denizin ortasındaymışım Yürüyormuşum üstelik.. Yukarı kaldırmışım başımı Masmavi gökyüzü.. Aşağı indirmişim Mavi büyük bir deniz Ve...', ARRAY['Türk Edebiyatı','Şiir','Özgür Aysun Beksarı']::text[], 8.5, '{"poet":"Özgür Aysun Beksarı","poet_slug":"ozgur-aysun-beksari","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/ask-demisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kürt Kardeşlerimize Düşen Tarihi Sorumluluk', 'kurt-kardeslerimize-dusen-tarihi-sorumluluk-vahdet-nafiz-aksu-13iyx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Avrupa  birliğinin sihirli eli değer değmez bizim meşhur '' Kürt Meselesi '' buzdolabından siyaset mutfağının tezgahına iniverdi.

Önce anadilde yayın. Sonra '' kahramanların ''  tahliyesi... Derken,  yurdumuzun çeşitli yörelerinde tekrar başlatılan terörist saldırılar.  Başbakan vekilinin tahliye edilen eski milletvekillerini kabulü ve söz konusu kişilerin  basın önünde deklere ettikleri  '' ateşkes çağrısı  ''.

PKK renkleriyle meclis kürsüsünden  Kürtçe yemin eden Leyla Zana''ya, o tarihlerde Bekaadan  '' Zana, helal sana ''  mesajları ileten  katil Öcalan, şimdi de hapishaneden zafer gülücükleri gönderiyor olmalı. Çünkü hanım kızımız her ne kadar suret-i haktan görünse de, yaptığı açıklamanın satır aralarında  başkanına selam göndermeyi ihmal etmiyor ve  içeride tutsaklar olduğu sürece sevinemeyeceğini belirtiyor. İçerideki teröristlere mahkum, ya da tutuklu demiyor... Savaş halindeki İki hasım  devletin savaş vaziyetindeki tutuklularını tanımlayan kavramı bilinçli olarak kullanıyor: Tutsak...

TERÖR SİMSARLARINI ARADAN ÇIKARALIM 

Geldiğimiz bu kritik noktada, sicilleri vatana ihanetle kirlenmiş, terör örgütüyle irtibatları ispatlanmış kişilerle işbirliği son derece yanlış bir tutum. 

Türk halkıyla kaynaşmış, bütünleşmiş Kürt halkının da bu kişilere itibar etmemesi, açılan temiz sayfanın kirletilmemesinin ilk şartı. Tarih boyunca sürdürdüğümüz kardeşliği, tabii mecrasında yine sürdürmeliyiz ve geleceğe el ele kol kola  birlikte yürümeliyiz. 

Bunun için ne dıştan güdümlü terör örgütü artıklarına, ne de sahte önderlere ihtiyaç var. Devlet olarak bu simsarları asla muhatap almamalıyız. Kürt kardeşlerimiz de haklı taleplerini bu terör kanlılarına ihale etmesinler lütfen. Temiz isteklerini kanla, göz yaşıyla kirletmesinler. Yarın birer kahraman edasıyla bölgeye koşacak olan bu simsarları çiçeklerle, PKK renkli flemalarla karşılamasınlar. 

Evet sonuna kadar kardeşlik istiyoruz biz de...Ama aramızdan bu engelleri, terör artıklarını ayıklayarak, samimiyetle kucaklaşarak.

TÜRKLERLE KÜRTLERİN TARİHİ KARDEŞLİĞİNE GÖLGE DÜŞÜREN

PKK VE ONUN UZANTILARI OLDU HEP...

Türk Milletinin tarihi ile Kürt kardeşlerimizin tarihi iç içe bir seyir takip eder. Şöyle bir hatırlayalım, aynı bayrağı şerefle taşıdığımız, kader birliği yaptığımız dönemleri.

1776 Küçük Kaynarca Antlaşmasından sonra güçsüzlüğünü idrak eden  Osmanlı hemen Kürt  kardeşlerine dayadı sırtını...Sırtından bıçaklanmayacağına inanarak...Önemli Kürt aşiretlerinin reislerinin komutasında (içlerinde kürt kökenli osmanlı subayları da vardı. Cibranlı Halit Bey gibi)  özel alaylar kurdu. HAMİDİYE ALAYLARI. Bunun yanısıra kürt aşiretleri reislerinin çocuklarının eğitimi için özel bir okul açıldı. 

Diğer taraftan Küçük Asya''da daha önceleri yerleşen Ermeni misyonerleri ermenilerin milli duygularını tahrik ediyor ve isyana teşvik ediyorlardı. İşte ermenilerin silaha sarıldıkları her isyanı Hamidiye Alayları bastırmıştır. (Özellikle Sasun, Talori ve Van isyanları) .

CUMHURİYETİ BİRLİKTE KURDUK 

Osmanlının son dönmelerindeki bütün savaşlarda omuz omuza birlikteydik, Türk  ve  Kürt  olarak. Çanakkale''de, Yemende...Her yerde...

İstiklal Savaşının her safhasında da aynı gayeler için çarpışıp kan döktük. Sonrasında acı olaylar da oldu elbet...İsyanlar...Müslüman Türk ''ün tekrar müstakil bir devlet kurmasını hazmedemeyen dış güçlerin kışkırtmasıyla yerel isyanlar baş gösterdi.

Sonra yine dış odaklı en büyük ihanet oyunu sahnelendi. PKK yıllarca kan döktü, vahşet sergiledi. Türk Milletinin bu yangını söndürmesinde de Kürt kardeşlerimizin katkıları, yardımları oldu...Tabii ki ihanet içinde olanlar da vardı...

Türk Ordusunun zaferi  ile sonuçlanan bu süreçten sonra, birkaç gündür yine silahlı çatışmalar baş göstermeye başladı. Yine askere pusular, polise kalleş kurşunlar...

ATEŞKES NE DEMEK YAHU 

Bu çabaların başarılı olması mümkün değil...Türk Devleti, Milleti ve ordusuyla bir bütün olarak bu gibi olayların karşısında kahramanca duracaktır... Artık bu topraklarda isyan, kalkışma, ihanet organizasyonlarının kök salması eskisi kadar kolay olmayacaktır.

Bu süreçte Kürt kardeşlerimize tarihi görev düşüyor... Hemen kapılarını, pencerelerini kapatsınlar bu zehirli rüzgara...Hemen tavır koysunlar.  '' İçimizde size kanacak ahmak bulamazsanız, kardeşi kardeşe kırdıramazsanız, askere polise, öğretmene kurşun sıkacak parmak bulamazsınız bizde ''  diye bir kahraman haykırış bekliyoruz...

Sanki karşımızda bir meşru güç varmış gibi, bir devletle muhatapmışız  gibi iki de bir ateşkes sözleri duymak istemiyoruz.  Eski DEPLİLERİN  bu tür çaba ve eylemleri bu bakımdan bize ıstırap veriyor, gönlümüze hiç hoş gelmiyor.

Mahpusluktan  kahramanlığa terfi ettirilen bu şeddeli teröristler Türk Milletine ve Kürt''lere iyilik yapmak istiyorlarsa, bir köşeye çekilsinler ve gözümüze görünmesinler...

KÜRTLERİN  KADERİ, TÜRKİYE''NİN KADERİYLE YOĞRULMUŞ

Kürtlerin geleceği Türkiye''nin geleceğine bağlıdır. Türkiye Cumhuriyeti  ayakta kaldığı sürece kürtler şimdiye kadar olduğu gibi onun bir parçası olarak   rahatça yaşayacaktır.

Türkiye''nin zayılaması, parçalanması, kürtler içinde felaket olacaktır. ''  Bağımsız Kürdistan ideali ''diplomatik bir fantaziden ibarettir. Ve büyük devletimize karşı  '' sökmediği ''  görülmüştür....Bu gerçeği PKK nın kanlı lideri de görmüş ve ifadelerinde silahlı mücadelenin çare olmadığını açıkça dile getirmiştir.

Öyleyse kardeşlik ve eşit vatandaşlık idealini sözden eyleme geçirelim birlikte ve asla dolduruşa gelmeyelim.

Birkaç eski tutuklunun tahliyesini zafer çığlıklarına dönüştürmeyelim.

Her iki taraf için de '' TEENNİ '' zamanıdır...', 'Avrupa  birliğinin sihirli eli değer değmez bizim meşhur '' Kürt Meselesi '' buzdolabından siyaset mutfağının tezgahına iniverdi. Önce anadild...', ARRAY['Türk Edebiyatı','Şiir','Vahdet Nafiz Aksu']::text[], 8.5, '{"poet":"Vahdet Nafiz Aksu","poet_slug":"vahdet-nafiz-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kurt-kardeslerimize-dusen-tarihi-sorumluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah ''ı İstiyorum', 'allah-i-i-stiyorum-i-smet-barlioglu-82znc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Servette gözüm yoktur; 

Allah ''ı istiyorum.

Cennet ''te gözüm yoktur; 

Allah ''ı istiyorum.

Kıl kadar balık gördüm,

Fil kadar balık gördüm,

El kadar balık gördüm,

Allah ''ı istiyorum.

Gördüm çiçek sayısız,

Gördüm böcek sayısız,

Gördüm mihenk sayısız,

Allah ''ı istiyorum.

Yılanlar var ziynetli,

Birbirinden heybetli.

Her hünerde izzetli

Allah ''ı istiyorum.

Her ağıza yediren,

Dağı, taşı giydiren,

Kainatı döndüren

Allah ''ı istiyorum.

Her uçanda bir kanat,

Her kanatta renk, san ''at,

Nakış gibi kainat.

Allah ''ı istiyorum.

Tohum atsan bitiyor,

Köpek sürü güdüyor,

Merkep deve yediyor.

Allah ''ı istiyorum.

Sinekte bir zarafet,

Karıncada dirayet,

Her tavusta bir haşmet.

Allah ''ı istiyorum.

Kelebekler bir sergi,

Bir bir seyret yeter ki,

Yaratmak O ''na özgü; 

Allah ''ı istiyorum.

Dikeni unutmayan,

Yorulmayan, yatmayan,

Hiç eksik yaratmayan

Allah ''ı istiyorum.

Yaradılmışı gördüm

Yaradanımı sevdim,

Hikmet der çok özledim,

Allah ''ı istiyorum.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 347-349/412)', 'Servette gözüm yoktur;  Allah ''ı istiyorum. Cennet ''te gözüm yoktur;  Allah ''ı istiyorum. Kıl kadar balık gördüm, Fil kadar balık gördüm, El...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/allah-i-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklı Olmayan', 'akli-olmayan-i-smet-barlioglu-pjzth', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklı olmayana hele dönüp bak; 

Değer hükümleri budaklı, dallı.

Bilemez ne gözdür, hangisi kulak,

Gör ki nasıl garip, nasıl zavallı.

Bilmez kimliğini, bilmez işini,

Bilmez ayağını, bilmez başını,

Bilmez yüreğini, bilmez düşünü,

Gör ki nasıl garip, nasıl zavallı.

Seçemez dost kimdir, düşman hangisi,

Namus hangisidir, vicdan hangisi,

Görgü neye denir, irfan hangisi,

Gör ki nasıl garip, nasıl zavallı.

Bakarsın ağlıyor, gülecek iken,

Bakarsın duruyor, gelecek iken,

Ne sorsan bilmiyor, bilecek iken,

Gör ki nasıl garip, nasıl zavallı.

Kendine bakınca sanır başkası,

Her gün büyüyerek artar kuşkusu,

Kedere dönüşür bazan kuşkusu,

Gör ki nasıl garip, nasıl zavallı.

Olmadık sesleri duyduğu olur,

İşi bitirmişken caydığı olur,

Başını kütüğe koyduğu olur,

Gör ki nasıl garip, nasıl zavallı.

Yer versen; çekinir, korkar, oturmaz,

Otursa yerinden kaldırılamaz,

Yaptığı hiçbir iş birini tutmaz,

Gör ki nasıl garip, nasıl zavallı.

Barlıoğlu acır akılsızlara,

Akılsız haklıdır hep aklı sıra,

Akılsız görürsen bunu hatırla,

Gör ki nasıl garip, nasıl zavallı.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 350-351/412)', 'Aklı olmayana hele dönüp bak;  Değer hükümleri budaklı, dallı. Bilemez ne gözdür, hangisi kulak, Gör ki nasıl garip, nasıl zavallı. Bilmez k...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/akli-olmayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Munzur''a Karşı', 'munzur-a-karsi-genco-yilmaz-vx385', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün yitirirsen inancını,

Sevgiye dair

Dersim''de bir dağ yamacına çık

Munzur''a karşı

Suyun sesini dinle,

Kendini birde,

Hiç dinlemediğin kadar

Munzur''a karşı kendini dinle...

Mayıs, 2004 umudun kırıldığı an', 'Bir gün yitirirsen inancını, Sevgiye dair Dersim''de bir dağ yamacına çık Munzur''a karşı Suyun sesini dinle, Kendini birde, Hiç dinlemediğin ...', ARRAY['Türk Edebiyatı','Şiir','Genco Yilmaz']::text[], 8.5, '{"poet":"Genco Yilmaz","poet_slug":"genco-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/munzur-a-karsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Bayramı', 'cocuk-bayrami-genco-yilmaz-v58z9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya''nın çocukları geliyordu,

Çocukların dünyasını karartan memleketime

Iraklı bir çocuk

Elinde bir çicek

Uzatıyordu meclisteki başkana

Ayırdında olmadan

B52''leri Iraklı kardeşlerine hediye edene...', 'Dünya''nın çocukları geliyordu, Çocukların dünyasını karartan memleketime Iraklı bir çocuk Elinde bir çicek Uzatıyordu meclisteki başkana Ayı...', ARRAY['Türk Edebiyatı','Şiir','Genco Yilmaz']::text[], 8.5, '{"poet":"Genco Yilmaz","poet_slug":"genco-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cocuk-bayrami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek Gzölerinde Martı Olsam', 'dilek-gzolerinde-marti-olsam-kamil-aydemir-45d4y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'izin vermem ki acılar senden bir dal kırsın

hamsi gibi kıpır kıpırsın

karadeniz kokuyorsun

yüreğime her dalışında

sevgin üzerine sevgi dokuyorsun

bana koşuyor arzuların

ama kendin korkuyorsun

sol gözün kordonboyu

sağ gözün sahil yolu

elele verince ikisi

oluyorlar saman yolu

inan ki sıkılmam

gözlerinde dolanıp dursam ömür boyu

ah yaralı güvercinim

üşürüm mart’tan beri

eylül kanatır beni

dudakların ağustos mu desem

koynun güneş

güzelliğin bahar

cinsel arzuyu artırıyormuş haziran

benim haziranım sen

öpücük çiçekleriyle soysan beni

güneş koynuna alsan sımsıkı sarsan

eriyip sana karışsam

mutluluk toplanmaz ayrılıklardan

gülüşlerin hayatın dalından asık kiraz

bir kadına ancak bu kadar yakışır naz

yüreğim telleri kırık tozlu saz

saçlarını kırık tellerin yerine taksam

her dokunuşumda

günün ciğerlerine mutluluk ezgileri bıraksam

ve dilek

gözlerin martısı olsam

hayatı çirkinleştirenlerin inadına

umudu yeşerten türküler çığırsam', 'izin vermem ki acılar senden bir dal kırsın hamsi gibi kıpır kıpırsın karadeniz kokuyorsun yüreğime her dalışında sevgin üzerine sevgi dokuy...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/dilek-gzolerinde-marti-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masmavi', 'masmavi-i-smail-sahin-nt2o3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Binalar, köprüler, ağaçlar...

ayaktadır da

Görünmez; yıkılmıştır dünya..

Renkleri dökülür göklerin

Masmavi üstümde dursan da.', 'Binalar, köprüler, ağaçlar... ayaktadır da Görünmez; yıkılmıştır dünya.. Renkleri dökülür göklerin Masmavi üstümde dursan da....', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/masmavi-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su', 'su-firat-celik-dncxs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Su; ezelden ebede açılan temiz kapı

Saflığın ve ulviliğin namzeti bir yapı

Su; kemâlâta eren ufuktaki son yamaç

Ruhların nefesine atom gücünde ilaç

İnsan, gönlünde aradığı o sese muhtaç

Tüm ruhlar sudaki derûni o manâya aç

Ruhumuz ebed''e giden tüm yolları gözler

Allah, bu yolun izini akan suda gizler

Su''da gizlenmiştir tek gâye''nin yolculuğu

Acaba sonsuzluğa akan tek yolcu su mu?

Neden bütün kirler suda bulur temizliği?

Berraklığın tek sırrı akan suda mı gizli?

Su ile yoğrulmuş insanın varlıkta harcı

Olmasa aşk su da bulur mu hayat ağacı?

Tüm bu suâllerin ilacı sudadır suda

Hakk''a kapalı yollar karanlık okyanusta

Gönlünde aradığın huzurlu ses sudadır

Kanmasa insan suya hep kirli bir didârdır

Hikmeti dingin bir meşk ile cennetten gür ses

Peteğin tadı muvakkat, suda bâki nefes

Yaşanacak herşey yaşananların eskisi

Asırlar hep geçse de su herşeyin yenisi

Su akar yol uzar, su akar yollar hep uzar...

Aşılmaz dağları ancak coşkun bir su aşar

Suyun insana gösterdiği en güzel yanı

İnsanın ebedi cennette havz ı ayanı!

Suda hoş esinti, suda sonsuzluğun izi

Sudadır sönmez ebedi hayat meşâlesi

Mücerred hislerin ulaştığı son nokta bu!

Maddeyi mânada gören bulur sonsuzluğu!

Fırat Çelik', 'Su; ezelden ebede açılan temiz kapı Saflığın ve ulviliğin namzeti bir yapı Su; kemâlâta eren ufuktaki son yamaç Ruhların nefesine atom gücün...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çelik']::text[], 8.5, '{"poet":"Fırat Çelik","poet_slug":"firat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/su-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yelkovan', 'yelkovan-i-smail-sahin-75fsw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zehrin batıp kaçsam da,

Dolanıp dolanıp gelirdim.

Sen yelkovanı beklerdin,

Sittin sene sana koşsam da.

Ah, Yelkovan! 

Bin bir nazla yürürdü.

Ne seni ne de bekliyor olmanı

Takardı kafasına

Sırf sen mutlu ol diye; 

Daha hızlı dolanmaya çalışırdım,

Yelkovan hemen varsın diye sana.

Oysa ayak sürürdü...

Ne olur Yelkovan! 

Gel sevdiğime

Ne olur Yelkovan! 

Sev sevdiğimi

Gücüm tükenince,

Kırılsa da bacaklarım,

Verebilmek için sana hayalini; 

Atılırdım ileriye, geri düşsemde

Zorlardım son zamanı.

Ne olur Yelkovan! 

Gel sevdiğime,

Ne olur Yelkovan! 

Sev sevdiğimi,', 'Zehrin batıp kaçsam da, Dolanıp dolanıp gelirdim. Sen yelkovanı beklerdin, Sittin sene sana koşsam da. Ah, Yelkovan!  Bin bir nazla yürürdü....', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yelkovan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir k', 'zincir-k-aytekin-arik-4t7lo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kalmasaydı Leyla Mecnunsuz

nasıl onu özliyecekti

periler riyakarları sınamış

şansı tıkanmış ulaşamaz

üyesi vicdansız yanılgıya

zümrüt altın bunaltıcı

caddeler çekilmiyor dökük

emel feleğin gölgesinde

ğ hiçten ılımaz

ilgisizligi jeotermik

		14', 'kalmasaydı Leyla Mecnunsuz nasıl onu özliyecekti periler riyakarları sınamış şansı tıkanmış ulaşamaz üyesi vicdansız yanılgıya zümrüt altın ...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-k-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar Düşünsün', 'yar-dusunsun-i-smail-sahin-m9rwo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben giderim...

Nereyedir? 

Yol düşünsün.

Ben atlarım...

Düşer miyim? 

Dağ düşünsün.

Ban yanarım...

Söner miyim? 

Yel düşünsün.

Ben açarım...

Kurur muyum? 

Bağ düşünsün.

Ben geceyim...

Biter miyim? 

Gün düşünsün.

Ben ölürüm...

Mezarımı,

Sağ düşünsün.

Ben öterim...

Kanar mıyım? 

Gül düşünsün.

Ben sessizim...

Yalnız mıyım? 

Dost düşünsün.

Ben ölürüm...

Derdim nedir? 

Yar düşünsün.', 'Ben giderim... Nereyedir?  Yol düşünsün. Ben atlarım... Düşer miyim?  Dağ düşünsün. Ban yanarım... Söner miyim?  Yel düşünsün. Ben açarım......', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yar-dusunsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paylaşamam ki', 'paylasamam-ki-cafer-tayyar-ozkan-vobep', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bülbül kafesinde,

Sense, kalbimde güzelsin; 

Bir tanem seni; 

Çektiğim her nefeste,

Biçtiğim her mevsimde,

Kokladığım her çiçekte,

Yazdığım her satırda,

Gördüğüm her şeyde,

Kurduğum her düşte,

Seviyor, özlüyor, istiyorum...

Ey yüreğimin eşsiz kaptanı,

Gönlümün seyir defterini,

Seninle yazdım bunca zaman,

Mevsimler boyu gezdim aşk limanlarını,

Senden sonra kalbimin yelkenini,

Dolduracak fırtınayı tutamam ki...

Canıma can katacak,

Ukdelerimi yaşatacak,

Ruhumu uzak diyarlara götürecek,

Canımın cananını bulamam ki...

Sensiz sevda şarkılarını,

Duygularımın satırlarını,

Kokunu getirecek rüzgarlarını,

Bir kalemde silip de,

Senin sevdanın üzerine, 

Can verecek sevda kuramam ki.

Seninle sensiz geçen akşamlarını,

Yüreğimin çaresiz çırpınışlarını,

Ne zemheriyi, ne de sonbaharı bekleyen,

Umuda yol veren hırçın sözlerini,

Zamanın acımasız akışını,

Sevgi dolu sözlerini,

İşitirsem, durduramam ki...

Bana geleceğin zamanı bilsem,

Kollarımda canımı cananımı sevsem,

Sonbaharımda baharımı bulsam,

Duaların kabul olduğunu görsem,

İçime akan gözyaşlarını kurutsam,

Aşkının doyumsuz sıcaklığını alsam,

Bir an olsun seni paylaşamam ki...

27 Aralık 2002 Ankara', 'Bülbül kafesinde, Sense, kalbimde güzelsin;  Bir tanem seni;  Çektiğim her nefeste, Biçtiğim her mevsimde, Kokladığım her çiçekte, Yazdığım ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/paylasamam-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir l', 'zincir-l-aytekin-arik-37qzv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'letafet mayası nerede

okşar öfkesini pişmanlık

restora sayılmaz şaşkınlık

taşkınlık umursanmıyan  ünsiyet

vamp yüzsüzlük zavallılığı

acelecilik baştan curcuna

çaçaron değil erotik

faminist gözükür ğ

huzursuz ırkçılık iğneler 

jiletler kaslarını

		15', 'letafet mayası nerede okşar öfkesini pişmanlık restora sayılmaz şaşkınlık taşkınlık umursanmıyan  ünsiyet vamp yüzsüzlük zavallılığı aceleci...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-l-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir n', 'zincir-n-aytekin-arik-xnyys', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'nadir olmaz ölüm

partal resim siyahlığı

şık titiz utangaç

ürem varken yadırganmaz

zalimce ağlayan bacısı

cahil çirkin değil

erdem ferden güzel

ğ huyunda ısrarlı

inekle jaguarın koşusu

luzumsuz mazeret

		17', 'nadir olmaz ölüm partal resim siyahlığı şık titiz utangaç ürem varken yadırganmaz zalimce ağlayan bacısı cahil çirkin değil erdem ferden güz...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-n-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir m', 'zincir-m-aytekin-arik-d07ob', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'mağfur nefsi oflaz

öneze pususunda ruhen

sonbahar şehveti tükenmez

umman üzerinde vikayesiz

yalapşap zevcelikten aymaz

bezgin cavalacoz çiçek

darmaduman eğlencesiz felçli

göçmen ğ hayranı

ıstırar içinde jurnalci

kereviz leziz

		16', 'mağfur nefsi oflaz öneze pususunda ruhen sonbahar şehveti tükenmez umman üzerinde vikayesiz yalapşap zevcelikten aymaz bezgin cavalacoz çiçe...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir o', 'zincir-o-aytekin-arik-c2yjz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'optimizm ölçü pençeresi

rasyonalizm süzgeç şelalesi

tecrübesizlik ulus üşengeçliği

vaşak yılmaz zehirden

ah besler canavar

çingen dayısı ehven

firez gibiydi ğ

haziran ıslığı inliyor

jenosit kurbanları lambasız

mabetler nimetsiz

		18', 'optimizm ölçü pençeresi rasyonalizm süzgeç şelalesi tecrübesizlik ulus üşengeçliği vaşak yılmaz zehirden ah besler canavar çingen dayısı ehv...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir p', 'zincir-p-aytekin-arik-2k1ir', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'pürüzlü rağbetsiz sevği

şahika tükenmez umut

üçgül viranlarda yaygın

zemheri ayında bolluk

ceren çokluğunda darlık

ensesinde felek garibin

ğ hisseder ışığı

ince jilet kesiği

lüks mum nurluğunda

oyalanır örğüsüyle

	

		20', 'pürüzlü rağbetsiz sevği şahika tükenmez umut üçgül viranlarda yaygın zemheri ayında bolluk ceren çokluğunda darlık ensesinde felek garibin ğ...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-p-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Acıdır', 'ayrilik-acidir-i-smail-baharsen-d1raa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ayrılık acıdır zehirden daha çok

uzayan yollarda kaybolmak gibi

yıldızlara kanıp yok olmak gibi

ayrılık karadır geceden daha çok 

sabahı hesapsız beklemek gibi

dertlere dert eklemek gibi

ayrılık soğuktur buzdan daha çok

düşüp çaresizliğe kıvranmak gibi

karlar içinde yanmak gibi

ayrılık zalimdir zamandan daha çok

hasatı gecikmiş tarlalar gibi 

bozumu ertelenmiş bağlar gibi

ayrılık zordur zordan daha çok

inadana dünyada yaşamak gibi

zoru zoruna acıyı tatmak gibi...', 'ayrılık acıdır zehirden daha çok uzayan yollarda kaybolmak gibi yıldızlara kanıp yok olmak gibi ayrılık karadır geceden daha çok  sabahı hes...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ayrilik-acidir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir r', 'zincir-r-aytekin-arik-lf3kw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'reçine sayılır şıra

tadı unutulmaz üzüm

vermut yadsınmaz zayiat

ayrılmış birinden caygın

çalışır debelenir evhamlanır

firensiz gider ğ

hastalansa ıhlamur içse

jütler  kadar lobelya

musallat nane otu

ölse pişman

		21', 'reçine sayılır şıra tadı unutulmaz üzüm vermut yadsınmaz zayiat ayrılmış birinden caygın çalışır debelenir evhamlanır firensiz gider ğ hasta...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zincir-r-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Bizim Buralar', 'sensiz-bizim-buralar-i-smail-baharsen-cine9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dün yine bir düğün oldu bizim mahallede

sizin evin yanındaki evde...

ne kadarda güzeldi 

karşımdaki mutluluk

sensiz bizim buralar,

bir burukluk var mutluluklarda..

bir feryat gecelerden duyduğum

bir acı gözyaşı gökyüzünün hüznü

kapkara sokakların rengi..

güller bile solmuş kederden,

birde sensiz beni düşün...

hayal hayal yaşıyorsun,

elin elime değmez,

gözün gözüme bakmaz...

umrumda değil,

hayat denen film,

biz bu filmden çıktık nasıl olsa..

varsın dalgalansın marmara,

ağlasın her gece taksim

haliçte bütün gemiler batsın.

dünya dönsün neye yarar

zaman geçsin neye yarar...', 'dün yine bir düğün oldu bizim mahallede sizin evin yanındaki evde... ne kadarda güzeldi  karşımdaki mutluluk sensiz bizim buralar, bir buruk...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sensiz-bizim-buralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne şiir ne mısra ne de kalem', 'ne-siir-ne-misra-ne-de-kalem-sair-ahrazi-60ftc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Al bu cânı benden al bahtımı Yâr,

Adını andıkça anasım gelir.

Yokluğun ateşse mahşer bu diyâr,

Kuru dallar gibi yanasım gelir.

Ne şiir ne mısra ne de kalem,

Diyemez derdimi söz olsa âlem.', 'Al bu cânı benden al bahtımı Yâr, Adını andıkça anasım gelir. Yokluğun ateşse mahşer bu diyâr, Kuru dallar gibi yanasım gelir. Ne şiir ne mı...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ne-siir-ne-misra-ne-de-kalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmuru Dinle', 'yagmuru-dinle-ajda-meseli-womz8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmuru dinle çisil çisil.

Yüreğinde sakla gözyaşını.

Sessiz sedasız gir yağmurun koynuna,

Bırak, sırılsıklam olsun düşüncelerin.

Ne vakit bir matem sarar yüreğini,

Ne vakit deli bir rüzgar alır götürür seni...

Yağmuru dinle,

Şarkısında, bir başka diyar olsun meskenin.

Dinsin artık fırtınalar yüreğinde,

Bak, hala şarkı söylüyor yağmur! 

Berrak kokusunu çek ciğerlerine...

Yağmuru dinle...', 'Yağmuru dinle çisil çisil. Yüreğinde sakla gözyaşını. Sessiz sedasız gir yağmurun koynuna, Bırak, sırılsıklam olsun düşüncelerin. Ne vakit b...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagmuru-dinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Kış', 'kara-kis-mehmet-cevik-hazerfen-gq2b7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belli ki 

......... yağmur

Belli ki 

........ donmuş bir damla bu

Gelip de yüreğimin 

.............................üstüne konan

Belli ki seni özlemişim

İçimin kırlarının 

................... açan tek çiçeği

Omzumun 

.............. yüreğimin tek sahibi

Şu faninin 

............. kurtarıcı meleği

02.02.2004

Silopi

 Mehmet Çevik (Hazerfen)', 'Belli ki  ......... yağmur Belli ki  ........ donmuş bir damla bu Gelip de yüreğimin  .............................üstüne konan Belli ki sen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çevik (Hazerfen)']::text[], 8.5, '{"poet":"Mehmet Çevik (Hazerfen)","poet_slug":"mehmet-cevik-hazerfen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kara-kis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadeh Yaşamak', 'bir-kadeh-yasamak-ajda-meseli-uhv5f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir damla ıstırap, 

Bir kadeh şaraba bedel.

Bir kadeh yaşamak, 

Bir damla zaman eder.', 'Bir damla ıstırap,  Bir kadeh şaraba bedel. Bir kadeh yaşamak,  Bir damla zaman eder....', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-kadeh-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün...', 'dun-mehmet-cevik-hazerfen-s6w26', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün yine yüzümü boyadım

Patika yollarda koştum, 

................................. yoruldum

Yattım ranzama 

....................... uyudum

Dün yine seni düşündüm

Tuttum elinden

Kır bahçelerinde gezdirdim 

Bir bardak çayla 

Bir paket sigara bitirdim

Ağlayan gözlerle

Salya sümük bir halde 

.................................seni aradım

Ulaşamadım, kaderime çattım

Nedir ki yani dedim

Yarın duyarsın sesini...

Kendimi kandırdım.

Eşrefe* borcum vardı

Tüm yemeğimi 

.....................onunla paylaştım

Aç kaldım, 

Yine sigaraya dadandım

Karmakarışıktım, 

....................... yattım

Sonra güneş doğdu 

............................. dağlar arasından

Kalktım,

.........her şeyi

Yine sana yazdım...

Günaydın meleğim

Sana doğudan

Dünü gönderdim... 

30.01.2004

Silopi

(Eşref, sevgili köpeğimiz)

 Mehmet Çevik (Hazerfen)', 'Dün yine yüzümü boyadım Patika yollarda koştum,  ................................. yoruldum Yattım ranzama  ....................... uyudum D...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çevik (Hazerfen)']::text[], 8.5, '{"poet":"Mehmet Çevik (Hazerfen)","poet_slug":"mehmet-cevik-hazerfen","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dun-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğuda Hasret', 'doguda-hasret-mehmet-cevik-hazerfen-ea8lw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben burada 

..................neler mi yapıyorum? 

Hasretliğin filozofu oluyorum

Sana cennetten ırmaklar akıtıp

Yağmurları izliyorum

Yedi rengini de görüp

Saçlarına taçlar yapıyorum

İmkansızlıkların şarkısını söyleyip

Rüzgarla gelen ölüme 

................................gülüyorum

...

Bin yıllık hasretime 

............................ ağlıyorum sonra

Adını yazıp 

.............. sınırlara

Tanımadığım insanlara ezberletiyorum

Sonra kaldırıp başımı

Uzun uzun gökyüzüne bakıyorum

Yıldızlarla seviniyorum

Kendimi 

Beni izlediğini sanarak 

.................................... avutuyorum

Çatlayan ellerime, 

Ağrıyan dizlerime aldırmadan

Dağ taş dolaşıyorum

Tütün sarıp parmaklarımı yakıyorum

Birde...

İmkansız olduğunu bile bile

Seni buralarda 

...................... arıyorum

Ah be meleğim

Ben bu hasretle 

........................ baş edemiyorum

17.03.2004

Cudi

 Mehmet Çevik (Hazerfen)', 'Ben burada  ..................neler mi yapıyorum?  Hasretliğin filozofu oluyorum Sana cennetten ırmaklar akıtıp Yağmurları izliyorum Yedi re...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çevik (Hazerfen)']::text[], 8.5, '{"poet":"Mehmet Çevik (Hazerfen)","poet_slug":"mehmet-cevik-hazerfen","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/doguda-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz Ayrılık', 'caresiz-ayrilik-mehmet-cevik-hazerfen-l4nn5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman seni yazacak olsam

Çaresiz kalır 

......................tüm kelimeler

Kalem utanır yazmaktan 

Ellerim titrer 

.....................ağlamaktan

Yüreğimde hüzün, 

...............................yüreğimdesin gülüm

Dayanamıyorum artık

Seni burada bırakıp ta gitmelere

Ayrılık acı ile süzülüp de

Damarlarımdan giriyor içime

Hüzün bulutlarının işgali 

Bu gece 

................yine gözlerimde

Güzel bir şehrin terminalinde

Yüzün ay gibi parlıyor

Gecenin karanlığında

En mağrur türküler 

................................ yine dilimde

Bin yıllık hasret var 

Sürgün yüreğimde

Bir zakkum gibi büyür şimdi bağrımda

Zehrini akıtır yüreğime 

.......................................bu ayrılık

Senden uzaklaştığım 

....................................her adımda

Bilmeli ki bu Bursa şehri

Geceden sonra

Tepelerine güneşi getiren 

.............................................gözlerindir

Bu şehri güzel yapan

Bilmeli ki, 

..................tutamadığım

O güzel yüreğindir

28.05.2004

23:10

Bursa

 Mehmet Çevik (Hazerfen)', 'Ne zaman seni yazacak olsam Çaresiz kalır  ......................tüm kelimeler Kalem utanır yazmaktan  Ellerim titrer  ........................', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çevik (Hazerfen)']::text[], 8.5, '{"poet":"Mehmet Çevik (Hazerfen)","poet_slug":"mehmet-cevik-hazerfen","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/caresiz-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beceriksiz İntihar', 'beceriksiz-i-ntihar-mehmet-cevik-hazerfen-hbejr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir ip var sanki, 

______________yağlı

Boynuma geçirilmiş

Kaç kere denedim 

________________ bilemezsin

Tutup ta boynumdaki ipi 

___________________çekmeyi

Denedim...

Her seferinde de

______________ elimden kaydı

Bu dağda, bu 

_____________ yalnız adam

Hasretten, 

__________hakikaten 

Bugün ilk kez 

_____________ağladı

06.01.2004

Çalışkan

 Mehmet Çevik (Hazerfen)', 'Bir ip var sanki,  ______________yağlı Boynuma geçirilmiş Kaç kere denedim  ________________ bilemezsin Tutup ta boynumdaki ipi  ___________...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çevik (Hazerfen)']::text[], 8.5, '{"poet":"Mehmet Çevik (Hazerfen)","poet_slug":"mehmet-cevik-hazerfen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/beceriksiz-intihar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitime Doğru', 'bitime-dogru-mehmet-cevik-hazerfen-2sr0v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ekinler boy verdi

Dağlar yeşile kesildi

Rütbeli ürpertiler

Artık önemsizleşti.

Belki de

Günler sana yaklaşıyor diye

Sözcükler böyle doyumsuz

Çiçek açıyor yüklemler

Seni büyütüyor da her gün 

Yeni bir yıldız takıyor 

 ______________saçlarına

İçimdeki bitimsiz özlemler...

25.04.2004

Silopi

 Mehmet Çevik (Hazerfen)', 'Ekinler boy verdi Dağlar yeşile kesildi Rütbeli ürpertiler Artık önemsizleşti. Belki de Günler sana yaklaşıyor diye Sözcükler böyle doyumsuz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çevik (Hazerfen)']::text[], 8.5, '{"poet":"Mehmet Çevik (Hazerfen)","poet_slug":"mehmet-cevik-hazerfen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bitime-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanın Tarihçesi', 'i-nsanin-tarihcesi-ahmet-aksoy-n06gq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'amaçsızca yaşadı adam

ne bir stratejisi vardı ne de ülküsü onun

yürüdü böcekler gibi

koştu kaplanlar gibi

yedi kurtlar gibi

uyudu ayılar gibi

ve öldü acılı insanlar gibi', 'amaçsızca yaşadı adam ne bir stratejisi vardı ne de ülküsü onun yürüdü böcekler gibi koştu kaplanlar gibi yedi kurtlar gibi uyudu ayılar gib...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/insanin-tarihcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nur''a Dizeler', 'nur-a-dizeler-ahmet-aksoy-vu1k9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ulaşılmış hangi zafer mutlu eder sensiz

bu dünyada sultan ahirette olsam aziz', 'ulaşılmış hangi zafer mutlu eder sensiz bu dünyada sultan ahirette olsam aziz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/nur-a-dizeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlediğimsin....', 'ozledigimsin-hulya-arisan-cbu3z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzaksın,

ulaşılmazsın,

varlığını bildiğim

_____ aşkımsın...

            Özlediğim geceme,

             yıldız.

             Tenimde arzu,

              gözlerimde 

               __________nursun....

Istanbul, 12 Haziran 2004', 'Uzaksın, ulaşılmazsın, varlığını bildiğim _____ aşkımsın...             Özlediğim geceme,              yıldız.              Tenimde arzu,   ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ozledigimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın Tetiğini Çekince...', 'zamanin-tetigini-cekince-mehmet-sahin-yanardag-26wph', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakıyorum kendi öz gözlerimle,

Ki çoktan kaçırmış olmalıyım, 

Göremiyorum tepemdeki cinlerimi.

Sakinleşiyorum artık sanırım,

Usul usul dinleniyorum bünyemin dışında.

Bakıyorum da hayli değişmişim,

Beynim bronzlaşmış galiba.

Beyaz sayfalarım kararmış.

Karıncalar önce küle 

Sonra damarlarıma basıyor.

Kara katran akıyor ellerimden,

Gözlerim kara bağlıyor.

Yarası sızlıyor yine yüreğimin,

Şu zaman fırtınalarının tahriş ettiği.

Yürü anca varırsın diyor aklım,

Fakat kavuşacak bir mekânım,

Var mıydı ki bir yarim? 

Yine anımsıyorum, kahretsin! 

Silinmez mi insanın şu beyni? 

Düşünüyorum…

……..................... ve “evreka! ”

Çözüm; 

Kafatasımda yakışıklı bir delik.

Ve bunun bir tek yolu; 

Dokuz kalibrelik bir çelik!', 'Bakıyorum kendi öz gözlerimle, Ki çoktan kaçırmış olmalıyım,  Göremiyorum tepemdeki cinlerimi. Sakinleşiyorum artık sanırım, Usul usul dinle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şahin Yanardağ']::text[], 8.5, '{"poet":"Mehmet Şahin Yanardağ","poet_slug":"mehmet-sahin-yanardag","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zamanin-tetigini-cekince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Denen Film', 'ask-denen-film-mustafa-komuscuoglu-wffz1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar bende oynamıştım

O aşk denen kısa metrajlı filmde,hemde başroldeydim

Senaryo güzeldi,güzel başlamıştı herşey

Önce ben arkadaşlarla bir fastfood da idim.

Sonra esas kız geliyordu yanımıza

Ben ilk görüşte aşık oluyordum,onun yeşil gözlerine

Daha sonra birşekilde birkaç kez daha karşılaşıyorduk

Bir kaç buluşma ve sonra asıl filme start veriliyordu

Filmin adı aşktı.Başrolünde ben ve o vardı

Filmin en güzel sahneleri sahillerde geçiyordu

Ara arada bir kaç kafeye gidiyorduk

Herşey mükemmele yakın gidiyordu

Anlıycanız bizde figüranlarda

Rollerimizi çok ama çok iyi yapıyorduk

Bir gün aniden esas kız fikir deyiştiriverdi

Sözüm ona başka bir aşk filminden daha iyi bir teklif almış

Onun çekimlerine başlayıp bizim filmi bırakmış

Onun söylediğine göre rolünü beğenmemiş

Rol gereği bile olsa yanında başka bi jön istemiş

O yüzdenmiş çekimleri böyle ansızın bırakıp gitmesi

Dedim ya filmimizin adı aşk,kısa metrajlı diye

Senaryo birden deyişiverdi,tabi filmin adıda

Bu seferki gerçektende uzun metrajlıydı

Yeni filmin adı ayrılık sancısı

O güne kadar çektiklerimizi aynen kullandık

Yeni filmi üstüne çektik.

Bu sefer rolüm zordu çok zordu

Hep bekleyen ve ne olursa olsun seven bir genci canlandırıyordum

Bazen sabahlara kadar ağlayan,bazen şair olan bir genci

Dedim ya film işte

Yoksa olmaz olamaz gerçekte böyle bu kadar büyük bir sevgi

Neyse anlatmayla bitmez bu filim çekeceğimiz daha çok sahne var

Çekimleri muhtemelen bir ömür boyu sürer

Rolüm bu sefer zor,gerçekten de çok zor

Çünkü bundan sonraki bütün sahnelerde; 

Gözü yaşlı yüreği yaslı,gelmeyeceğini bile bile

Sevdiğini bekleyen aşık bir genci canlandırıyorum

Rolüm zor gerçekten çok zor çünkü

Çünkü ben aslında kendimi oynuyorum...', 'Bir zamanlar bende oynamıştım O aşk denen kısa metrajlı filmde,hemde başroldeydim Senaryo güzeldi,güzel başlamıştı herşey Önce ben arkadaşla...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ask-denen-film-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Aşkı Oyuncak Sandım', 'ben-aski-oyuncak-sandim-mustafa-komuscuoglu-519qb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorum bizim aşkımızda tek suçlu bendim

Tek hatalı olan bendim kıymetini bilemedim

Hani küçük çocuklar oyuncaklar için ağlar

Kavuşuncada kaldırıp bir kenera atarlar ya

İşte ben de ilk kez aşka kavuşunca

Öyle çocuksu bir şımarıklığa kapıldım

Ve aşkı bir oyuncak sandım istediğim zaman benim olacak

Yada bana hiç küsmeden bir kenarda duracak

Ama öyle deilmiş aşk kaçar gidermiş

Ne kadar ağlasan da yalvarsanda dönmezmiş geriye

Ve kalp ölürmüş geçmişi her hissettiğinde

Yokluğunu ve boşluğunu her hissettiğinde

Meğer bu kalp her sensiz atışında ölürmüş

Bunu şimdi anladım malesef şimdi

Ne yazık ki yokluğunda,sensizlikte anladım

Ve anladım ki sen hayalimdeki kız deildin

Aslada hayalimdeki kız olmayaksın biliyorum

Biliyorum çünkü sen,sen benim bir ömür boyunca

Hayallerimdeki deil kalbimdeki kızdın ve hep öyle kalacaksın...', 'Biliyorum bizim aşkımızda tek suçlu bendim Tek hatalı olan bendim kıymetini bilemedim Hani küçük çocuklar oyuncaklar için ağlar Kavuşuncada ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-aski-oyuncak-sandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmezsin Ki', 'bilmezsin-ki-mustafa-komuscuoglu-djxpk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi sağ yanın boş sol tarafında bir başkası

Çekmedinki hiç nerden bileceksin sen aşk acısını

Hasretin sızısını, pişmanlığın faydasızlığını

Bilmezsin ki sen senin bende nasıl yaşadığını

Bilmezsinki sen o yeşil gözlerine hala nasıl vurgun olduğumu

Her esen rüzgarın ruhumu nasıl ordan oraya savurduğunu

Geceler boyu hiç durmadan sızını içimde duyduğumu

Bilmezsin ki sen hala sana nasıl delice aşık olduğumu 

Sen şimdi uzaklardasın hayellerdesin rüyalardasın

Yıldızlar kadar parlaksın ama bi okadarda uzaklardasın

Güneş kadar güzelsin,sıcaksın ama sevgilim sen

Sen şimdi başkasının güneşi başkasının yıldızı başkasının herşeyisin

Sen veda busem; delice sevdiğim,benim ilk gözağrım,herşeyimdin

Sen yağmur bakışlım; ilk gözyaşım ilk ayrılık sancımdın

Sen yaz aşkım; on sekiz yaşımın en güzel armağanıydın

Ve sen çılgın kuşum; sen asla unutmayacağım güzel bi rüyaydın...', 'Şimdi sağ yanın boş sol tarafında bir başkası Çekmedinki hiç nerden bileceksin sen aşk acısını Hasretin sızısını, pişmanlığın faydasızlığını...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilmezsin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-mustafa-komuscuoglu-f5lq5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her geceyi sabah ettiğim sokaklar

Sizdemi küstünüz bana

Her sabah aşındırdığım yollar

Sizdemi düşman kesildiniz bana

Her gün hayatla kavgam yetmiyormuş gibi

Şimdi dost bildiklerimde sırtını dönmüş bana

Bir deli rüzgar esti önce adı zaman

Çaldı benden herşeyimi bir bir

Önce çocukluğumu çaldı benden sonra gençliğimi

Son darbeydi senin gidişin

Son çaldığıydın benden zamanın

Belkide ondandı bu kadar çabuk yaşlanmam

Daha dün sokakta misket oynuyorken

Bu gün yangınlarda kül olmam

Belki de ondandı sensizliğe bir türlü alışamam

Bilirsin dünya çok kere aldandım sana

Çok kere kandım türlü yalanlarına

Ama artık bu son olsun,ben gidiyorum

Gidiyorum yalan dünya,herşeyim sana kalsın

Bana ait olmayan tüm sevdalar

Sayende yaşanamayan tüm aşklar

Ve senin vermeden aldığın herşey sana kalsın

Bahar gelmiş,çiçekler açmış,kuşlar ötmüş,banane

Dünya gözyaşından arınmış,ağlayan yokmuş,banane

Hem bahar geldiyse hiç sonbahar gelmiyecek mi? 

Ağlayanlar kalmadıysa,yağmurlar olmayacak mı? 

Her esen rüzgarda bir sevgiliden diyerinin yanağına

Hasret dolu,özlem dolu ve sevda kokulu bir buse konmayacakmı

Boşver be yalan dünya ben gidiyorum

Kalanlar sizin olsun yanlız yaşadıklarım yeter bana

Ve son defa bir eyvallah çekerek tüm aydınlıklara

Tüm sevdalara ve tüm aşıklara

Binip gidiyorum sessiz gemi denen meçhul karanlığa

Gidiyorum öksüz kalan karanlıklar,elveda

Gidiyorum tamamlanamayan mısralar,elveda

Gidiyorum işte yalan dünya senden çok uzaklara

Gidiyorum sevgilim gidiyorum,ELVEDA..', 'Her geceyi sabah ettiğim sokaklar Sizdemi küstünüz bana Her sabah aşındırdığım yollar Sizdemi düşman kesildiniz bana Her gün hayatla kavgam ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/elveda-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bilir?', 'kim-bilir-mustafa-komuscuoglu-bbq19', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerim şimdi neden suskunsunsunuz

Neden boş boş duruyorsunuz neden? 

Can mı kalmadı sizde yoksa,yoksa

Yanlız kaldınız diye isyan mı ediyorsunuz şiirlere

Yapmayın etmeyin ellerim yüreğim yarım kaldı

Gözlerim boşlukta kaldı,aklım beni bıraktı

Bir siz kaldınız bir sizler yadigarsınız

Bari siz bari siz yapmayın böyle ellerim

Hatırlayın o sevgilinin elini tuttuğunuz günleri

O güzel o mutlu günleri onların aşkına bari

Hadi yazıverin içimdeki bir kaç satırı

Bak işte böyle oldum bu günlerde sevgilim

Ellerime bile söz geçiremez oldum

Hiçbirşey hiçbir uzvum dinlemiyor beni

Hepsi ayrı ayrı aynı adı sayıklıyor

Seni...

Ama...

Olmaz diyorum yalvarırım diyorum

Bana yarım kalbimin zulmü yeter

Birde siz etmeyin diyorum ve

Saatler boyu yalvarıyorum gözlerime

AKıtmayın artık yaşlarınızı diye

Söz geçeiremiyorum ne yapayım

Sen gittiğinden beri böyleyim işte

Sigarayı günde üç pakete çıkardım

İşte bir ciğerlerim isyankar deil

Bir onlar dinliyor sözümü

Öyle çekiyorlar ki nikotini içlerine

Sanki senin boşluğunu doldurmak istercesine

Ama nafile be gönlüm sende biliyorsun

Üç deil beş pakette içsen sevgisizlikte

Ne fayda giden dönmez geriye

Bilir bu yaralı yürek bunu ondandır yarım atışı

Yarısı senle atar orada diğer yarısıysa

Oda ben gibi sensizlikte çırpınır yuvasında

Ama ben niye kızıyorum ki ellerime,gözlerime

Ben seni seven ben burada böyle çaresizken

Ne yapsın ellerim seni özlemekten başka

Ne yapsın gözlerim ağlamaktan başaka

Of ulan of gene efkar bastı herzamanki gibi

Gene işte gene özledim seni özledim be vicdansız

Özledim işte seni vefasız özledim

Tüm benliğimle herşeyimle özledim seni

Ve bıktım artık avutmaya çalışmaktan yüreğimi

Gİdiyorum artık sensizlikten ellerimi alıp

Gözlerimi alıp yüreğimi senli sokaklardan kazıyıp gidiyorum

Arama beni bir daha bulamazsın çünkü ben artık

Yangınlarda kül,yağmurlarda bir damla olurum

Kim bilir belki sensiz diyarlarda senli rüyalar görürüm

Ve kim bilir belkide o rüyalardan bir gün

Hiç uyanmam ve hep seninle kalırım kim bilir...', 'Ellerim şimdi neden suskunsunsunuz Neden boş boş duruyorsunuz neden?  Can mı kalmadı sizde yoksa,yoksa Yanlız kaldınız diye isyan mı ediyors...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/kim-bilir-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen benimsin', 'sen-benimsin-mustafa-komuscuoglu-wj8al', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerim şimdi neden suskunsunsunuz

Neden boş boş duruyorsunuz neden? 

Can mı kalmadı sizde yoksa,yoksa

Yanlız kaldınız diye isyan mı ediyorsunuz şiirlere

Yapmayın etmeyin ellerim yüreğim yarım kaldı

Gözlerim boşlukta kaldı,aklım beni bıraktı

Bir siz kaldınız bir sizler yadigarsınız

Bari siz bari siz yapmayın böyle ellerim

Hatırlayın o sevgilinin elini tuttuğunuz günleri

O güzel o mutlu günleri onların aşkına bari

Hadi yazıverin içimdeki bir kaç satırı

Bak işte böyle oldum bu günlerde sevgilim

Ellerime bile söz geçiremez oldum

Hiçbirşey hiçbir uzvum dinlemiyor beni

Hepsi ayrı ayrı aynı adı sayıklıyor

Seni...

Ama...

Olmaz diyorum yalvarırım diyorum

Bana yarım kalbimin zulmü yeter

Birde siz etmeyin diyorum ve

Saatler boyu yalvarıyorum gözlerime

AKıtmayın artık yaşlarınızı diye

Söz geçeiremiyorum ne yapayım

Sen gittiğinden beri böyleyim işte

Sigarayı günde üç pakete çıkardım

İşte bir ciğerlerim isyankar deil

Bir onlar dinliyor sözümü

Öyle çekiyorlar ki nikotini içlerine

Sanki senin boşluğunu doldurmak istercesine

Ama nafile be gönlüm sende biliyorsun

Üç deil beş pakette içsen sevgisizlikte

Ne fayda giden dönmez geriye

Bilir bu yaralı yürek bunu ondandır yarım atışı

Yarısı senle atar orada diğer yarısıysa

Oda ben gibi sensizlikte çırpınır yuvasında

Ama ben niye kızıyorum ki ellerime,gözlerime

Ben seni seven ben burada böyle çaresizken

Ne yapsın ellerim seni özlemekten başka

Ne yapsın gözlerim ağlamaktan başaka

Of ulan of gene efkar bastı herzamanki gibi

Gene işte gene özledim seni özledim be vicdansız

Özledim işte seni vefasız özledim

Tüm benliğimle herşeyimle özledim seni

Ve bıktım artık avutmaya çalışmaktan yüreğimi

Gİdiyorum artık sensizlikten ellerimi alıp

Gözlerimi alıp yüreğimi senli sokaklardan kazıyıp gidiyorum

Arama beni bir daha bulamazsın çünkü ben artık

Yangınlarda kül,yağmurlarda bir damla olurum

Kim bilir belki sensiz diyarlarda senli rüyalar görürüm

Ve kim bilir belkide o rüyalardan bir gün

Hiç uyanmam ve hep seninle kalırım kim bilir...', 'Ellerim şimdi neden suskunsunsunuz Neden boş boş duruyorsunuz neden?  Can mı kalmadı sizde yoksa,yoksa Yanlız kaldınız diye isyan mı ediyors...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/sen-benimsin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmayınca...', 'sen-olmayinca-mustafa-komuscuoglu-s1hlv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bu aşka ölümüne sevdalıyım öyleki; 

Bakmasın bu gözler baktığı sen olmayınca

Tutmasın bu eller tuttuğu  sen olmayınca

Varsın atmasın bu kalp her atışında sen olmayınca

İşte sevgilim ben bu sevdaya böyle ölümüne yeminliyim

Her nekadar sen bu aşk denen rüyayı çoktan unutmuş olsanda...', 'Ben bu aşka ölümüne sevdalıyım öyleki;  Bakmasın bu gözler baktığı sen olmayınca Tutmasın bu eller tuttuğu  sen olmayınca Varsın atmasın bu ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-olmayinca-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-mustafa-komuscuoglu-vd8hf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin hançer misali yaralayan o gözlerin

Ah o bir zamanlar yaşama sevinci veren gözlerin

Şimdide her yabancı bakışıyla deli boranlar

İçimde fırtınalar koparan yeşil gözlerin

İşte ben o gözlerde bir ömür hapsolmayı istedim sadece

Çok şey mi istemiştim ki senden ayrıldık seninle

Bir seni seviyorum deyişine yada bir sıcak gülüşüne

Yahut saçlarının bir teline fedaya hazırdım bu canımı

Ama sanırım senden çok şey istemişim

Ve....

İşte ayrıldık biz seninle sen ve ben diye

Bİrbirimize eskisi gibi yakın deiliz

Hatta hiç mi hiç yakın deiliz şimdi

Belki uzaktan çok ama çok uzaktan birazcık yakınız

Ve işte ayrıyız artık seninle

Sen ve ben ayrı ayrı yürüdük bir zamanlar

Ayrılık denen o uzun ve zorlu yolda

Bir seni bir sevdanı yoldaş bildim kendime

Ama olsun ben bir seni sevdim o yolda bile

Sen bu yolu bırakalı çok oldu biliyorum

Yeni sevgilinle sana mutluluklar diliyorum

Biliyormusun sevgilim artık üzülmüyorum senin yokluğuna

Yanlız hala yanıyorum o aptalca çocukluğuma

Sen şimdi hernerede ve herkiminle olursan ol

Ben burda gülüyorum senin gülüşünü hatırladıkça

Hala bir senin için yazıyorum şiirlerimi

Belkide ilk aşkım olduğundan olsa gerek,unutamıyorum

Hiçbirşey eskisi gibi olmadı senden sonra

Sen belki daha fazla seversin bir başkasını demiştin

Senden sonra bir daha sevemedim bir başkasını

Bir daha asla söyleyemedim o iki kelimeyi

İlk sana söylemiştim kirlensin istemedim belki

Belkide söylemek gelmedi içimden

Her harfi seni hatırlattığı için

Senden sonra birdaha gitmedim

Seninle her zaman gittiğimiz o kafeye

Her köşesinde biz varız diye

Ama aslında baktığım her yerde zaten hep sen vardın

Gözlerimi kapattığım her yerde hep biz vardık

Tıpkı şimdi resimlerde olduğu gibi

Tıpkı şimdi resimlerde kaldığı gibi

Biliyormusun çokta önemli deil artık benim için 

Her gece aynı karanlığa kapatıyoruz ya gözlerimizi

Her sabah merhaba diyoruz ya aynı güne işte beraberiz

Varsın olmasın kaderimde bir daha sana kavuşmak

Koymaz be sevgilim sen her gece rüyalarda benimsin

Yanlız her gördüğüm okyanus yeşili gözde seni arıyorum hala

Sen olmadığını ve senin olamıyacağını anlayınca da

Başımı öne eğip gidiyorum sol tarafımdaki cehennemin tam ortasına

Ve sevgilim biliyormusun...

Sana hala delice aşığım

Lanet olsun ki bu lanetlenmiş sevda da hala

Hala bir sana vurgunluğum ve hala sana bu çaresiz kalp atışlarım

Hala seni seviyorum anlıyormusun hala seni çok ama çok seviyorum...', 'Gözlerin hançer misali yaralayan o gözlerin Ah o bir zamanlar yaşama sevinci veren gözlerin Şimdide her yabancı bakışıyla deli boranlar İçim...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/seni-seviyorum-197-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Olmak', 'senin-olmak-tansel-yucelen-dq2r3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'siyah beyaz film gibi akıverdin sen bana

kaybolan haritada buldun beni o sokakta

	hep senin olmak

	istedim hayatımın her anında

	senin olmak

	sadece zamanın her yanında

dokundum vücuduna sen nefes aldığında

bacakların kolların gözlerin her yanımda

	hep senin olmak

	istedim hayatımın her anında

	senin olmak

	sadece zamanın her yanında

			yanlızlıkla kalma

			senin olmayı diledim bu hayata

			hep senin olmak

	hep senin olmak

	istedim hayatımın her anında

	senin olmak

	sadece zamanın her yanında

	hep senin olmak

	senin olmak

	sadece senin olmak

	istedim

	hep senin olmak

	senin

	sadece senin', 'siyah beyaz film gibi akıverdin sen bana kaybolan haritada buldun beni o sokakta 	hep senin olmak 	istedim hayatımın her anında 	senin olmak...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/senin-olmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Yazıyorum', 'sadece-yaziyorum-tansel-yucelen-dxuiq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yazıyorum bir mum ışığında

	bilmem gece saat kaç

		bilmem günlerden ne

yazıyorum işte ben

	bazen ağlatan bir melodi

		bazen güldüren bir ufaklık gibi

ne olduğunu

	ne içerdiğini

		neyden bahsettiğini

bilmeden satırlarımın

	yazıyorum işte ben yine

			sadece

			        yazıyorum', 'yazıyorum bir mum ışığında 	bilmem gece saat kaç 		bilmem günlerden ne yazıyorum işte ben 	bazen ağlatan bir melodi 		bazen güldüren bir ufa...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sadece-yaziyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sözler, Tek Soluk', 'son-sozler-tek-soluk-tansel-yucelen-mtu78', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu hikaye bir kızın 

son sözleriyle doğdu

tutunamadı o hayata 

inişlere ve çıkışlara

o ağladı derinlerinden

bitmeyen umutlarında

gençti dokunamadı 

yaşama 

mutluluğa ve acılara

geçtiği yollar 

anılar 

dönüşü olmayan anlar

ve sessiz kaldı 

sonunda 

tek solukta', 'bu hikaye bir kızın  son sözleriyle doğdu tutunamadı o hayata  inişlere ve çıkışlara o ağladı derinlerinden bitmeyen umutlarında gençti doku...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/son-sozler-tek-soluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Gün', 'son-gun-mustafa-komuscuoglu-65yj0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son bir günündeyim çileli hayatımın

Yanıtlanmamış sorular,verilmemiş cevaplar

Ve daha yaşanmamış aşklar var önümde

Ve gün batımları yavaşça hazırlanıyor bensiz bir daha ki geceye

Adı ölüm olana dakikalar ve hatta saniyeler kala

Adı sevda olan güzel benden çok uzaklarda

Gidişimden habersiz,öpüşümden habersiz

Bedenini sarana rüzgar deyip de geçiyor

Ve gidiyor geldiğpi masal diyarlara

Ben giderken son birkaç saatimde yaşıyorum geçmişimi

Ve hala seviyorum veda edemediğim tek güzeli

Ve bin ömre bedel seven bu deli kalbimi

Avutuyorum,anlatarak senle geçen son günümü

Masum bir ruhla doğan faniler seven bir kalple ölecekler

Sen beni hiç sevmesende ardımdan sana aşıktı diyecekler

Ve son nefesimde son sözüm senin adın olsun diye; 

Sensiz geçen bir ömrün sensiz geçen o son günün de

Gene seni sadece seni ve hep seni severek teslim olacağım

Adı Ölüm adı sensizlik adı Azrail olan kara meleğe...', 'Son bir günündeyim çileli hayatımın Yanıtlanmamış sorular,verilmemiş cevaplar Ve daha yaşanmamış aşklar var önümde Ve gün batımları yavaşça ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/son-gun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz', 'i-simsiz-tansel-yucelen-vl9ln', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yazıyorum bir mum ışığında

	bilmem gece saat kaç

		bilmem günlerden ne

yazıyorum işte ben

	bazen ağlatan bir melodi

		bazen güldüren bir ufaklık gibi

ne olduğunu

	ne içerdiğini

		neyden bahsettiğini

bilmeden satırlarımın

	yazıyorum işte ben yine

isimsiz bu yazdıklarım

	adsız bu gece yaşadıklarım

		sonu olmayan kimliksiz derin bir uçurum

					      ya da 

		nereye estiğini bilmeyen rüzgar gibi

					isimsiz

					    ve adsız

					           çünkü

					               yoksun sen 

						        burada

oysa nasılda özledim seni ben

	nasılda sarmak isterdim şimdi seni ben

		nasılda anlam katmak isterdim ben düşlerime bu an

bu satırlara ilham veren güzel 

		sen değil misin

bu melodinin ya da çocuğun rüyalarını süsleyen kız 

				sen değil misin

sensiz anlarıma katlanmamı sağlayan

		o anların sonunda hep seni 

			görebilmem değil mi

sensiz yaşayabilmemi sağlayan

		daima senle olacağımı bilmek 

				  değil mi

işte o zaman gel yanıma

         gel

	 gel de 

	      bu isimsiz satırların

	             bu isimsiz anların

		          bir adı olsun...

				gel...

				ge...

				g...

				...

				..

				.

isimsiz...', 'yazıyorum bir mum ışığında 	bilmem gece saat kaç 		bilmem günlerden ne yazıyorum işte ben 	bazen ağlatan bir melodi 		bazen güldüren bir ufa...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/isimsiz-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarına Veda', 'yarina-veda-mustafa-komuscuoglu-67b7s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Irmaklar denize akar ve aşıklar yanlız aşka ağlar

Onun için sevdiğim,sanma ki gözden senin için yaşlar akar

Bu gözler sevgilim ancak; 

Öksüz kalan bir sevdanın ardından ağlar

Belki hala seviyorum seni ve unutamadım gözlerini

Belki hala duyuyorumdur kokunu ve özlüyorumdur seni

Ama sakın sanma kendini akan gözyaşlarımın sebebi

Çünkü benim özlemim sendeki sana deil bendeki sana

Bundan sonra böyleyim ben deyişemem de artık

Ben hala dünü yaşıyorum bugünü yada yarını istemem

Ve sonsuza dek dünde kaldığımda gene senden habersiz

Buralardan çekip giderim ellerin üstünde ve sensiz

Her ne kadar beni uğurlayan sesin sen olmasını istesemde

Ve ayrılırken bende seni seviyorum diyebilmeni dilesemde

Beni uğurlayan bir erkek sesi olur senin sesin yerine

Ve veda cümleleri ''Er kişi niyetine olur'' seni seviyorum yerine...', 'Irmaklar denize akar ve aşıklar yanlız aşka ağlar Onun için sevdiğim,sanma ki gözden senin için yaşlar akar Bu gözler sevgilim ancak;  Öksüz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yarina-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmiş Olsun', 'gecmis-olsun-tansel-yucelen-pox49', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hayat zor derler

hüzünler gülmeler

yaşanmış hikayeler

olmayan sevgiler

bana ağır gelmiyor

bir son vermiyor

günler bitmiyor

sen varsan -yanımda-



	sen 

	herzaman

	iyi ol

	bebeğim

	üzülme

	yatma

	güzelim

	geçmiş olsun

bir gün gülmesen

yanımdan gitsen

ellerini çeksen

ölürüm -ben sensiz-

	sen 

	herzaman

	iyi ol

	bebeğim

	üzülme

	yatma

	güzelim

	geçmiş olsun

hayat zor derler

yalan söylerler

bulursan sevgiyi

yaşarsın -sonsuzda-

ben buldum seni

o güzel çiçeği

bırakmam asla

ölsem -bile senle-', 'hayat zor derler hüzünler gülmeler yaşanmış hikayeler olmayan sevgiler bana ağır gelmiyor bir son vermiyor günler bitmiyor sen varsan -yanım...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gecmis-olsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaman Ali', 'yaman-ali-mustafa-komuscuoglu-ycrii', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yamansın yalansız ve aşıksın be ali

Civanmert ve delikanlı sevdan kadar

Sevsende ölesiye,sevdandan vazgeçebilecek kadar

Aşkı yaşayanlardansın be yaman ali

Sevdiğin mutlu olsun diye,mutluluğundan geçtin

O seni terketsede sen onu terkedemedin

Geceleri gözyaşlarınla hep isyan ettin

Genede kimseye belli etmedin be yaman ali

Gönlüne bir deil bin güneşi hapsettin

Cehennemden beter ateşlerde kendini kor ettin

Cihanı dize getirip bir güle boyun eğdin

Genede kimseye belli etmedin be yaman ali

Sevdanı bir sır bildin kendine,açık etmedin

Yedi cihana sığmayan bir sevdayı bir gönle hapsettin

Sevgiliyle geçen bir anı bir ömre bedel biçtin

Genede kimseye belli etmedin be yaman ali

Yamansın be ali civanmert ve delikanlı

Sevgilinin mutluluğu için yaktın kendini

Bu sevdaya bir ömür biçtin ve bin ömür sevdin

Genede kimseye belli etmedin be yaman ali

İşte bak gidiyor eller üstünde cenazen be yaman ali

Sevdan kadar beyaz kefene sarılı bedenin gidiyor

Senden geriye ne kaldı be yaman ali

Bir ömre sığmayan tek kişilik bir aşktan

Ve yazdığın bu son şiirden başka be yaman ali...', 'Yamansın yalansız ve aşıksın be ali Civanmert ve delikanlı sevdan kadar Sevsende ölesiye,sevdandan vazgeçebilecek kadar Aşkı yaşayanlardansı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yaman-ali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Rengi', 'gecenin-rengi-tansel-yucelen-69zw1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sessizce giden duygular kalplerden

akarlar bir nehire gözlerden

yok olur pamuktan hayaller

ardında buruk çehreler

bu işte bir yanlızlık var

tutulmamış o sözler var

buğulu aynadan göremezsin

sen seni benim gibi bilemezsin

	gecenin rengi kalmadı sensiz

	düşler ağladı çaresiz

	yitik bir mutluluğum bile kalmadı

	son sigaram şimdi bitti

	tüm şarkılar sona geldi

	bir labirentteyim ben kimsesiz

	ama bıktım ben bu renkten

son kez bakıyorum günlere

yaşanmış o güzel sahnelere

soğuktum senden geçerken

sende yaptın beni severken

	gecenin rengi kalmadı sensiz

	düşler ağladı çaresiz

	yitik bir mutluluğum bile kalmadı

	son sigaram şimdi bitti

	tüm şarkılar sona geldi

	bir labirentteyim ben kimsesiz

	ama bıktım ben bu renkten', 'sessizce giden duygular kalplerden akarlar bir nehire gözlerden yok olur pamuktan hayaller ardında buruk çehreler bu işte bir yanlızlık var ...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gecenin-rengi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''nun Hikayesi', 'o-nun-hikayesi-tansel-yucelen-pz4l6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'düşlerden sonra bir soğuk yağmurda

bugünü gördü elleri arasında

bir hayaldi bir macera

geldiği yerden çok uzakta

dur dediler gitme kal burda

savaştı o onun uğruna

uzun zaman zordu günler

yaşadı durdu o dudağında

	yıllar sonra bir sonbaharda

	mutluluğa gidermiş kendi başına

sevmek zor sessiz acılarda

buldu kendini onun kollarında

bir hayaldi bir macera

geçti yılları mutlu birsonla

	yıllar sonra bir sonbaharda

	mutluluğa gidermiş kendi başına', 'düşlerden sonra bir soğuk yağmurda bugünü gördü elleri arasında bir hayaldi bir macera geldiği yerden çok uzakta dur dediler gitme kal burda...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/o-nun-hikayesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye Kadar', 'nereye-kadar-tansel-yucelen-kwl72', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir an zaman aksa sessiz ya da

kum saati dursa ve öyle kalsa

ben senin şarkını hep söylesem

gözlerin gözlerimde ve o

       adı geçen sözcükler

       sözü edilen gerçekler

		nereye ka''dar bu şarkılar

		nereye ka''dar bu mısralar

		sen yoksan yanımda ne-re-ye kadar

bugün dünya dönmez konuşamam ve

ben sessiz kaldım masal içinde

sen yoksun burda bedenim üşür

ve ruhum zaten çürümekte

       adı geçen sözcükler

       sözü edilen gerçekler

		nereye ka''dar bu şarkılar

		nereye ka''dar bu mısralar

		sen yoksan yanımda ne-re-ye kadar

-  son nefesim kalmadı -

-  sözcüklerim alındı -

-  kaçtığım hayal işte o -

	nereye ka''dar bu şarkılar

	nereye ka''dar bu mısralar

	sen yoksan yanımda ne-re-ye kadar', 'bir an zaman aksa sessiz ya da kum saati dursa ve öyle kalsa ben senin şarkını hep söylesem gözlerin gözlerimde ve o        adı geçen sözcük...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nereye-kadar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Şarkı', 'yalniz-sarki-tansel-yucelen-433in', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'düşünceler yorar beni gülemez olurum

sahneler alır beni yaşayamaz olurum

bir sen gelsen aklıma ruhuma girsen hiç çıkmasan

bir sen gelsen yanıma kollarıma girsen hiç kaçmasan

ellerini arar bedenim bulamaz dokunulamaz

gözlerini bakışlarını ararım bulamam

bir sen gelsen aklıma ruhuma girsen hiç çıkmasan

bir sen gelsen yanıma kollarıma girsen hiç kaçmasan', 'düşünceler yorar beni gülemez olurum sahneler alır beni yaşayamaz olurum bir sen gelsen aklıma ruhuma girsen hiç çıkmasan bir sen gelsen yan...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalniz-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlık', 'ciglik-vedat-selcuk-mm3zf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duydum gönlümdeki çığlığı

Bir sukut çöktü dilime

Sessizliğin dilini dillendirdim

Korkularım haykırdı; kilit vurdum dilime...

Korku; cımbız cımbız deldi yüreğimi

Cesaret; ey cesaret,nerdesin? 

Bir perde örtsün umut,derdime

Yıldırımlar parçalasın korkuyu,nerdesin? 

Nazar; ey tılsımlı fitnekar göz

Erittin bendeki beni,köz köz

İçimdeki canavar büyüdü

Öldürsün heyulamı,efsunlu söz...

Umut; sağanak yağan Rahmet

Allahım,sen bizlere merhamet et

Ruhuma vurulmasın hiç bir kement

Hakim Rabbim,sen bizleri iki cihanda aziz et...

                                                     01/06/2004

                                                        Erzurum', 'Duydum gönlümdeki çığlığı Bir sukut çöktü dilime Sessizliğin dilini dillendirdim Korkularım haykırdı; kilit vurdum dilime... Korku; cımbız c...', ARRAY['Türk Edebiyatı','Şiir','Vedat Selçuk']::text[], 8.5, '{"poet":"Vedat Selçuk","poet_slug":"vedat-selcuk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ciglik-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlık Duygular', 'anlik-duygular-cem-alaca-2u2eb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Baktığın zaman görebilmelisin,

Samanyolundaki parlak yıldızın ışığını

Dokunduğun zaman hissetmelisin,

Yakınındaki sıcaklığı

Ağladığın zaman anlamalısın,

Duygudan yoksun olmadığını

Bağardığın zaman bilmelisin,

Onu ne kadar yıprattığını

Hele öptüğün zaman işte,

Bilmiyorum ama; 

Ben hiç yaşamadım o anı', 'Baktığın zaman görebilmelisin, Samanyolundaki parlak yıldızın ışığını Dokunduğun zaman hissetmelisin, Yakınındaki sıcaklığı Ağladığın zaman ...', ARRAY['Türk Edebiyatı','Şiir','Cem Alaca']::text[], 8.5, '{"poet":"Cem Alaca","poet_slug":"cem-alaca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/anlik-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Satmışsın Kirazı', 'sen-satmissin-kirazi-i-smet-barlioglu-xu5pv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tek harfi tanımadan gelmişsin bu yaşlara,

Sen satmışsın kirazı, kalmış yalnız terazi.

Elbette vurmalısın o kafanı taşlara,

Sen satmışsın kirazı, kalmış yalnız terazi.

Dökmemişsin ömründe gözlerinden damla yaş,

Olmamış bedeninle ruhun içinde savaş,

Tembelce yaşayarak gelmişsin yavaş yavaş

Sen satmışsın kirazı, kalmış yalnız terazi.

Mum ışığı altında geçmemiş gecelerin,

Umut için göklere açılmamış ellerin,

Anında gerçek olmuş düşüncen, hayallerin,

Sen satmışsın kirazı, kalmış yalnız terazi.

Dememişsin acaba gökler nasıl gök olmuş,

Taşa niçin pamuğun yumşaklığı konulmuş,

Öz cevher kabukluyken kabuk nasıl soyulmuş,

Sen satmışsın kirazı, kalmış yalnız terazi.

Düşürmemişsin aklı en küçük sır peşine,

Dememişsin kervanın sonsuz çölde işi ne,

Yormamışsın bedeni hiç düşüne düşüne,

Sen satmışsın kirazı, kalmış yalnız terazi.

Çiçeklere bamış da dikene bakmamışsın,

Yalnız tarlaya bakmış, ekene bakmamışsın,

Evren dolusu yükü çekene bakmamışsın,

Sen satmışsın kirazı, kalmış yalnız terazi.

Akvaryuma bakarken görmedin balinayı,

Mehtap diye seyrettin muhteşem dolunayı,

Asla merak etmedin binbir sırlı olayı,

Sen satmışsın kirazı, kalmış yalnız terazi.

Yılanı gördün ama türlerini görmedin,

Altında yatan sırrı dürtmedin, ellemedin,

Şişede duran devin sırrını bilemedin,

Sen satmışsın kirazı, kalmış yalnız terazi.

Görmüyorsun ortada yaşarken devekuşu,

Aklın nice zorlansa çıkamıyor yokuşu,

Varlığın cehaletin bir zavallı sarhoşu,

Sen satmışsın kirazı, kalmış yalnız terazi.

Tek sineğin kanadı çekmedi tek ilgini,

Bağlayıp ziyan ettin tembelliğe sevgini,

Göremedin sınırdan ötedeki engini,

Sen satmışsın kirazı, kalmış yalnız terazi.

Fezadaki binlerce yıldılardan sana ne,

Zerrenin içindeki yıldızlardan sana ne,

İkizden, üçüzlerden, altızlardan sana ne,

Sen satmışsın kirazı, kalmış yalnız terazi.

Noktanın içindeki motor sana önemsiz,

Onun için varlığın noktadan da değersiz,

Sürdür yine ömrünü hem kalpsiz, hem ciğersiz,

Sen satmışsın kirazı, kalmış yalnız terazi.

Barlıoğlu diyor ki; benim senle işim yok,

Bir şeyi ele alıp düz görenle işim yok,

Cehaleti beğenip sürdürenle işim yok,

Sen satmışsın kirazı, kalmış yalnız terazi.

/MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 352-354/412)', 'Tek harfi tanımadan gelmişsin bu yaşlara, Sen satmışsın kirazı, kalmış yalnız terazi. Elbette vurmalısın o kafanı taşlara, Sen satmışsın kir...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/sen-satmissin-kirazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gibi', 'deli-gibi-ozgen-topcu-bdumf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni yıldız mehtap sanıp

İzliyorum deli gibi

Her saniye seni anıp

Özlüyorum deli gibi

Çıkmazdayım zor bilmece

Yokluğun aşka işkence

Yollarını gündüz gece

Gözlüyorum deli gibi

Sen düşürdün beni ağa

Sapladın derin batağa

Kendimi attım sokağa

Geziyorum deli gibi

Sitem ettirdin yıllara

Kapanmıyor derin yara

İsmini ben her duvara

Yazıyorum deli gibi

Konuşuyorum resminle

Avutsan bari sesinle

Şakalaşıp hayalinle

Gülüyorum deli gibi

Senin kalbin aşklara tok

Oysa benim başkası yok

Mecnun Kerem Ferhat''tan çok

Seviyorum deli gibi', 'Seni yıldız mehtap sanıp İzliyorum deli gibi Her saniye seni anıp Özlüyorum deli gibi Çıkmazdayım zor bilmece Yokluğun aşka işkence Yolların...', ARRAY['Türk Edebiyatı','Şiir','Özgen Topçu']::text[], 8.5, '{"poet":"Özgen Topçu","poet_slug":"ozgen-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/deli-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Kadıköy Vapuru', 'kadikoy-vapuru-nurten-altinok-dl0kr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadıköy vapuru dalga kokuyor

Dalga dalga anı kokuyor

Kadıköy vapuru kim bilir kaç kişinin

Yüreğindeki aşka dokunuyor

Atsam kendimi sulara

Kıyamam 

Bulanır dalgalar

Atmasam

İçim yanar

Kadıköy vapuru 

Kim bilir kaç yürekte

Bitmemiş bir sevdanın

Kilimini dokuyor', 'Kadıköy vapuru dalga kokuyor Dalga dalga anı kokuyor Kadıköy vapuru kim bilir kaç kişinin Yüreğindeki aşka dokunuyor Atsam kendimi sulara Kı...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kadikoy-vapuru-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mekruhtur', 'mekruhtur-i-smet-barlioglu-tu22y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimsanin gizlisine

Bakma oğul, mekruhtur.

Kötülüğü kafana

Takma ogul, mekruhtur.

El bilinir huyuyla,

Yaptığı hayhuyuyla,

Elalemin suyuyla

Akma oğul, mekruhtur.

İyi yolu bırakma,

Elin sözüne bakma,

Kendini nara yakma,

Yakma oğul, mekruhtur.

Ağu katma aşlara,

Yer verme telaşlara,

Yaptığını başlara

Kakme oğul, mekruhtur.

Sevgini ver iyiye,

Öğüt güzel hediye,

İyi sözü kötüye

Çekme oğul, mekruhtur.

Nur dökülsün yüzünden,

At kemliği gözünden,

Üstadının sözünden

Çıkma oğul, mekruhtur.

Tutkun olmasın uyku,

Oku, azalsın korku,

Bir, on oku, bin oku,

Bıkma oğul, mekruhtur.

Ağırlama safları,

Post edinme kofları,

Ağızlara lafları

Yıkma oğul, mekruhtur.

Alimlerle git tanış,

Müşkülünü de, danış,

Konuşunca az konuş,

Sıkma oğul, mekruhtur.

Hayırlı kıl gönlünü,

Sevegör bugününü,

Hikmet ''lerin gönlünü

Yıkma oğul, mekruhtur.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 355-357/412)', 'Kimsanin gizlisine Bakma oğul, mekruhtur. Kötülüğü kafana Takma ogul, mekruhtur. El bilinir huyuyla, Yaptığı hayhuyuyla, Elalemin suyuyla Ak...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/mekruhtur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyamda', 'ruyamda-hurol-yucel-2g5cs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-rüyamda-

üç gecedir kapını çalıyorum...

hiçbir bizanslı''ya rastlamadan...

hiçbiri başına külah takmıyor cücelerin...

hiçbiri alnımdan öpmüyor

iyi niyetli teyzelerin...

hiçbir bizanslı''ya rastlamıyorum

bu köyde,

geceleyin...

hangi birine anlatsam

ardına bakmadan kaçıyor devlerin....

üç gecedir kapını çalıyorum....', '-rüyamda- üç gecedir kapını çalıyorum... hiçbir bizanslı''ya rastlamadan... hiçbiri başına külah takmıyor cücelerin... hiçbiri alnımdan öpmüy...', ARRAY['Türk Edebiyatı','Şiir','Hürol Yücel']::text[], 8.5, '{"poet":"Hürol Yücel","poet_slug":"hurol-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruyamda-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Ben', 'yeni-ben-i-smet-barlioglu-vttsb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sanma ki unuttum eski gövdemi,

O bedene az-çok hasretlenmişim.

Başka ben içinde buldum benimi,

Ondan sızıldanmış, kasvetlenmişim.

Çektiği ne azmış bana nispetle,

Ondan ünlememiş aynı heybetle,

Yine tek işim yok gıyla, gıybetle,

Çağa uymak için kispetlenmişim.

Onda eksik idim, şimdi tamamım,

Daha da çoğaldı eski dermanım,

Ben yine dergaha odun kıranım,

Çünkü evvelimle nispetlenmişim.

Bu nice lütuftur, geldim yeniden,

Tartılıp denk gelip bir teraziden,

Çıktım gömüldüğüm o araziden,

Sanma ki boşuna heybetlenmişim.

Beni öldüm sanma; dirildim bende,

Beni gömmüşlerdi ben tam gelende,

Yine ağlıyorum yeni gövdemde,

Zira, yaptığıma çok imrenmişim.

Ferman aynı ferman, yenilenmedi,

Tek şey eklenmedi, eksiklenmedi,

Bakanlar baktı ya, pek göremedi,

Aslı gizlemeye gayretlenmişim.

Büyük kolaylıkla buldum yerimi,

Seyrettim eskimiş kemiklerimi,

Buldum tezgahımda mekiklerimi,

O yüzden çok yaman hayretlenmişim.

Barlıoğlu der ki; hikayet budur,

Bu ben o ben gibi tümden doludur,

Hükmünü sürdürmek benin huyudur,

Ondan cana gelmiş, kuvvetlenmişim.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 358-359/412)', 'Sanma ki unuttum eski gövdemi, O bedene az-çok hasretlenmişim. Başka ben içinde buldum benimi, Ondan sızıldanmış, kasvetlenmişim. Çektiği ne...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yeni-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram', 'haram-i-smet-barlioglu-31syv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haram simsiyah eder sütten beyaz yüreği,

Vicdan budur erenler, haram mala dokunma.

Gözleri kamaştırır bilekte halhal gibi,

Bileğe dahi dokun, o halhala dokunma.

Habbe kadar alırsan verirsin kubbe kadar,

Mendil kadar haramın vebali cübbe kadar,

Başka büyük azap yok kendinden şüphe kadar,

Çil gibi yavrulayan tek vebale dokunma.

Haram; kapı ardında sanırsın bir zerredir,

Oysa herbir zerresi bir demirden küredir,

Harama sırt çevirmek helallerden töredir,

Kapıya değsen bile hiç mandala dokunma.

Gönüller büyüleyen bir güleç yüze benzer,

Gittikçe gideceğin mavi denize benzer,

Haram; mangal içinde narlanmış köze benzer,

Değersen kavrulursun, o mangala dokunma.

Haram; kayıp düşeni tutan bir dal gibidir,

Güya abad edecek değerli mal gibidir,

Sapasağlam görünen delik sandal gibidir,

Sularda boğulsan da o sandala dokunma.

Ya yoksulun kanıdır, ya öksüzün irini,

Ondan koru, esirge elini, gözlerini,

Barlı her zaman söyler sözlerin güzelini,

Haram taşıyor görsen tek hammala dokunma.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 360-361/412)', 'Haram simsiyah eder sütten beyaz yüreği, Vicdan budur erenler, haram mala dokunma. Gözleri kamaştırır bilekte halhal gibi, Bileğe dahi dokun...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/haram-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-i-smet-barlioglu-l634f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen sırdan ne anlarsın,

Sırrı bilsen ağlarsın,

Şaşalar duralarsın

Aklın biraz tırmansa.

Sanırsın lafazanlık,

Şakadır Ramazanlık,

Tek bir anlık, bazanlık

Perdeler aralansa.

Nabzın nabzı kovalar,

Betin benzin hep solar,

Aklına sular dolar

Sır kapına dayansa.

Kalbin deprenip kalkar,

Aklın zarfından çıkar,

Ruhun engeli yıkar

Gücün öte uzansa.

Barlı der; hilaf sanma,

Ger inan, ger inanma,

Sır bir büyük muamma,

Ara, hünerin varsa.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 362-363/412)', 'Sen sırdan ne anlarsın, Sırrı bilsen ağlarsın, Şaşalar duralarsın Aklın biraz tırmansa. Sanırsın lafazanlık, Şakadır Ramazanlık, Tek bir anl...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sir-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerenden Tutsam Seni', 'nerenden-tutsam-seni-umut-yalim-x3j1z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nerenden tutsam seni yine kendim

Sanki kan üzre damlayan kan gibi

Kaybettiğimde anlayabildiğim kalp

Ocakta kaynay suya yağan kar gibi

Nerenden tutsam seni yine kendim

Buzul camlarda soyunana bakan gibi.

Nerenden tutsam seni yine kendim

Eskiden yediğim dayadığın tadı gibi

Dayaktan değil kırıklarım   tutma

Kırıkları kalbimden daha yürektir

Nerenden tutsam seni yine kendim

Gözlüğme miyop camlar takan gibi.', 'Nerenden tutsam seni yine kendim Sanki kan üzre damlayan kan gibi Kaybettiğimde anlayabildiğim kalp Ocakta kaynay suya yağan kar gibi Nerend...', ARRAY['Türk Edebiyatı','Şiir','Umut Yalım']::text[], 8.5, '{"poet":"Umut Yalım","poet_slug":"umut-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerenden-tutsam-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Divan', 'divan-i-smet-barlioglu-0cscz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya divanıdır Cenabı Hakk ''ın,

Divanda yüzleri buruşturmayın.

Hesap sorabilen bir tek Allah ''tır,

Herşeyi küstahça soruşturmayın.

Öyle yürüyün ki; adım denk olsun,

Bastığınız her yer rengarenk olsun,

Herbir sözünüzde bir ahenk olsun,

Çirkinle güzeli karıştırmayın.

Ummak isterseniz umdurun eli,

Çekin kötülükten tertemiz eli,

Yumruğun tekmedir ancak bedeli,

Yoksulu, öksüzü koğuşturmayın.

Kumarla içkiye giden barışık,

Herbir duygu ile beden barışık,

Hiyle ile hurda zaten barışık,

Öğüdü dinleyip savuşturmayın.

Kalbe korku düşer fazla şaşmaktan,

Bazan hayır gelir vedalaşmaktan,

Bazan bela doğar yakınlaşmaktan,

Mazlumu zalimle tanıştırmayın.

Çok insan felekten daha kamburdur,

Mayası bulaşık eski hamurdur,

Pisliğin her türü aynen çamurdur,

Çamuru vicdana bulaştırmayın.

Yüzsüz adam zamktır; değse yapışır,

Bin kere kovulsa yine yılışır,

Kovan kovmaz olur, çünkü alışır,

Yüzsüzü önceden yaklaştırmayın.

Bir söz söylerseniz dinlenir olsun,

Birçok noktaları mimlenir olsun,

Dinleyen hoşlansın, demlenir olsun,

Sözü tepelerden dolaştırmayın.

Duygular hor görür her zaman aklı,

Biri yalın ayak, biri çarıklı,

Biri hep haksızdır, obiri haklı,

Akılı duyguyla uğraştırmayın.

Barlıoğlu der ki; özellikler var,

Bedende benzersiz güzellikler var,

İnsanda ilaha benzerlikler var,

Onları boş yere yozlaştırmayın.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 364-366/412)', 'Dünya divanıdır Cenabı Hakk ''ın, Divanda yüzleri buruşturmayın. Hesap sorabilen bir tek Allah ''tır, Herşeyi küstahça soruşturmayın. Öyle yür...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/divan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birlikte', 'birlikte-i-smet-barlioglu-o75o1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ruhum şimdi tavafta

Yücelerle birlikte.

Gövdem durur sahafta

Hecelerle birlikte.

Bir hak yolda giderim,

Ayaktır zerrelerim,

Yanar yanar tüterim

Bacalarla birlikte.

Tanır giderim izi,

Guslettirdim her sözü,

Koydum secdeye yüzü

Hocalarla birlikte.

Hor gördüm yapıları,

Boşladım tapuları,

Kapattım kapıları

Kocalarla birlikte.

Yalvardım bezirgana,

Takıldım bir kervana,

Daldım toza, dumana,

İncelerle birlikte.

Bedenimi ufalttım,

Hırslarımı azalttım,

Gözyaşıma yaş kattım

Nicelerle birlikte.

Çekmiş Barlı elemler,

Dinle sözü erenler,

Çok sürünür bedenler

Cücelerle birlikte.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 367-368/412)', 'Ruhum şimdi tavafta Yücelerle birlikte. Gövdem durur sahafta Hecelerle birlikte. Bir hak yolda giderim, Ayaktır zerrelerim, Yanar yanar tüte...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/birlikte-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Sev', 'boyle-sev-i-smet-barlioglu-c6uav', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevince öyle sev ki; ruhun gelsin amana,

Yüreğin dudağında inim inim inlesin.

Etin, derin, kemiğin dönsün yanan külhana,

Kanın damarlarında sel gibi ipildesin.

Sanasın ip boynunda, zincir var ellerinde,

Çekildin gidiyorsun celladın kemendinde,

Kılıç yarası kaldı kanayan bedeninde,

Her soluk alışında nefesin hırıldasın.

Vursun nabzın her adım atışında,

Yastıklar diken olsun uykuya yatışında,

Mecnunlara dönesin adını anışında,

Hayalde dahi görsen gözlerin pırıldasın.

Unutasın yemeği, tadı, zevki, herşeyi,

Azap kapısı sansın ruhun herbir köşeyi,

Bedenin harap olsun her gün iyiden iyi,

Bir tek onu andıkça her zerren ışıldasın.

Barlıoğlu diyor ki; sevmek de ibadettir,

Sevgilinin varlığı gözde ayet ayettir,

Sevgiliye ihanet en büyük cinayettir,

Sevince öyle sev ki; her yanın hışıldasın.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 369-370/412)', 'Sevince öyle sev ki; ruhun gelsin amana, Yüreğin dudağında inim inim inlesin. Etin, derin, kemiğin dönsün yanan külhana, Kanın damarlarında ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/boyle-sev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak...', 'uzak-zubeyde-yilmaz-3hqcy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıldızlar uzak,

Yıldızlar çok parlak...

Ay yine çoşkulu,

Ay yine umut dolu,

AŞK dolu dolunayda bak....

Sen bitanem,

Sen ulaşılmaz aşkım....

Sen içimde ay gibi parlak

Ay gibi çoşkulu,aşk dolu

Ama bedenin yıldızlar kadar uzak....

Var olan benliğin.ruhun,aşkın

Benim benliğimde, kalbimde sanmaki uzak

Güneş gibi sıcak,sımsıcak......

                                                   Zübeyde Yılmaz

                                                               12/06/2004', 'Yıldızlar uzak, Yıldızlar çok parlak... Ay yine çoşkulu, Ay yine umut dolu, AŞK dolu dolunayda bak.... Sen bitanem, Sen ulaşılmaz aşkım.... ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uzak-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sala (Eskiden şapkalı ''a'' lar vardı...)', 'sala-eskiden-sapkali-a-lar-vardi-i-smet-barlioglu-q1tqn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hazin salayı dinle; 

Sala bir gün senindir.

Sakla bezi elinle; 

Giyecek kefenindir.

Tükenir cevapların,

Gerekmez sevapların,

İşlenmiş sevapların

Arkandan gelenindir.

Malı reddeyle demem,

Fakat sırrı çöz hemen,

Şu yoksul, garip beden

Uğrunda ölenindir.

Nefesin var sayısı,

Nasip olmaz gayrısı,

Dostlarının iyisi

Ölürken görenindir.

Dosttur yalnız yarayan,

Dar gününde arayan,

Sen ağlarken ağlayan,

Gülerken gülenindir.

Onlar götürür seni,

Vaktin, vaden geldimi,

Her çare tükendimi

Mezara gömenindir.

Barlı der ki; erenler,

Unutulmaz ölenler,

Sonsuz sürecek günler

Kendini bilenindir.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 371-372/412)', 'Hazin salayı dinle;  Sala bir gün senindir. Sakla bezi elinle;  Giyecek kefenindir. Tükenir cevapların, Gerekmez sevapların, İşlenmiş sevapl...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sala-eskiden-sapkali-a-lar-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuğum', 'konugum-i-smet-barlioglu-2xclj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Konuğum bana geldi, menzilden karşıladım,

Kendimi sunar oldum O ''na kurban yerine.

Açtım ardına kadar evimin kapısını,

Başım hazırlanmıştır O ''na divan yerine.

Felah ve salah bulup arındım dertlerimden,

Koydu da gururlandım beni insan yerine.

Secde edip yer öptüm önünde konuğumun,

Gözlerimden yaş döktüm binbir lisan yerine.

Coştum, koştum, fırlandım vermek için bin hizmet,

Nazarıyla kapandı yaram derman yerine.

Bir at sürdü altıma; cehdimi ölçmek için,

Şahlandırdım atımı merdi merdan yerine.

Şahin oldum batıya, kartal oldum doğuya,

Güneye ve kuzeye sürdüm meydan yerine.

Sıvazladı sırtımı o ulu keremiyle,

Şad oldum, mesrur oldum binbir şadan yerine.

Sığdırdı yüreğime dünyadaki dağları,

Tüm yalçın kayaları sağlam vicdan yerine.

Hürmetle uğurladım, O gitti, ben ağladım,

Sonra ardına düştüm yorgun kervan yerine.

Barlıoğlu der O ''ndan evrende yok başka şey,

Vukubulan O ''ndandır emir, ferman yerine.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 373-374/412)', 'Konuğum bana geldi, menzilden karşıladım, Kendimi sunar oldum O ''na kurban yerine. Açtım ardına kadar evimin kapısını, Başım hazırlanmıştır ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/konugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencerem', 'pencerem-cem-alaca-614t3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bekliyorum yine seni 

Belki gelirsin diye

Bir ümit var içimde

Acaba döner mi diye

Pencerem açık

Gecenin karanlığına rağmen

Gözüm arıyor

Bir kaç ışık oyununa karşı

Sesini duyar gibi oluyorum

Seslenişini,bana hitap edişini

Göremiyorum ama yüzünü

Matemli karanlık gecede

Yine oyun oynuyor bana

Sanki ders verirmiş gibi gece

Olsun,pes etmeyeceğim yine

Pencerem açık,bekleyeceğim seni', 'Bekliyorum yine seni  Belki gelirsin diye Bir ümit var içimde Acaba döner mi diye Pencerem açık Gecenin karanlığına rağmen Gözüm arıyor Bir ...', ARRAY['Türk Edebiyatı','Şiir','Cem Alaca']::text[], 8.5, '{"poet":"Cem Alaca","poet_slug":"cem-alaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pencerem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm', 'kucugum-hakan-alparslan-7idkt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küçüğüm, aksi havayla beraber geliyor hasretin.

Nitekim uzak, nitekim alabora.

Deniz mavisini  ala çalmış,

Bu akan hasret pınarı.

Küçüldükçe küçülüyor yerim,

Sığınmak belki mümkün, belki imkansız.

Üç duvar, bir ufacık pencere.

Üç paslı demir, çevresi ilel ebet küf, yeşil.

Bileklerimdeki yine pas lekesi,

Kim bilir ne ara, bir araya geldi... 

Kollarımda mapusluk, ciğerim kedilerin göz nuru,

Bitmek bilmezse bile, hasret denizlere yavuklu...

Denizi görür paslı pencere,

Küf kokusu, yosun lekesi, nedensiz.

Bak, kimi zaman vapur sanırsın,

Bu karşıdan gelen belki kaçıncı viranenin sebebi.

Özlemişim, insan gürültüsü,

O bulanık dumanı nerede.

Hepsi bir rüya, hepsi bir hayal belki de.

Kollarım hep mor, ayılmaya mecal nerede? 

Buralarda ekmek yok, dudaklarımda hasretin adı,

Türküsü ezgilerle ahenkli...

Soğuk, nitekim sessizlik dört nala.

Süvarilerin tozutmuşluğu nerede,

Nerede o çorak toprak kokusu.

Aksine yağmur yağan değil mi? 

bak aksine avuçlarım sırıl-sıklam.

Küçüğüm, gök, kubbeden ayrı,

Ben senden ayrı.

Küçüğüm ellerin nerede...

Küçüğüm, gökyüzü inadına mavi oluyor buralarda akşamları.

Yıldızsız ve bir buhran içinde.

Sana isimler söylesem,

Sana sadece seni söylesem.

Dilim adına dönüyor aksine.

Bak inadına kekemeyim,

Bak inadına suskun...

Kimi zaman da olsa sızlamaz pişmanlığım,

Ah o eski pişmanlığım.

Yolların aşınmaz elbet, buralarda, bilmem ki ne kadar uzak.

Bir şilep, bir gemi oysa ki,

Bir kayık hayalimdeki.

Yine yağmurlu bir hava,

Ansızın çiseleyen.

Yelken istemem, sadece ellerin,

Sadece bir de yıldızlar.

İkimiz için sadece,

Bir yanan bir sönen yıldızlar.

Dilekler sürekli, adın sürekli,

Sen sürekli...

Küçüğüm, bir başıma koyma beni,

Zindanlar seni sayıklar oldu,

Kör kuyular dipsiz.

Çilem kara, bahtım zifiriden yoksun.

Küçüğüm, yağmur inadına bizden yana.

Islanıyor yine ellerim.

Küçüğüm, ellerin nerede... 

Perde gerilmez, ışığım bir kibrit çöpü misali.

Aydınlıktan yana yoksunum, saklayamam.

Küçüğüm bir de bulutlar,

En karasında, en sevdalı bulutlar.

Fırtına, nedensiz savurmaz ki insanı,

Fırtına bu denli esmer.

Buraların adı bilinmez ki be küçüğüm,

İnsanlar unutulmuş, kimlikler firari.

Vuslatın adı bir adım ileri.

Sol sağ ayak sesleri, ve insan sesleri,

Kısık, ıslık modunda sanki.

Gri, kasvetli bir hava,

Işık yok, ses yok, hele sen küçüğüm.

Penceremde küf kokusu, inadına keskin.

İnadına hasretin...

Küçüğüm yağmur inadına bizden yana,

Avuçlarım yine sırıl-sıklam.

Küçüğüm ıslanıyor yine ellerim,

Küçüğüm ellerin nerede... 

 (10.06.04)', 'Küçüğüm, aksi havayla beraber geliyor hasretin. Nitekim uzak, nitekim alabora. Deniz mavisini  ala çalmış, Bu akan hasret pınarı. Küçüldükçe...', ARRAY['Türk Edebiyatı','Şiir','Hakan Alparslan']::text[], 8.5, '{"poet":"Hakan Alparslan","poet_slug":"hakan-alparslan","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/kucugum-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyidir', 'i-yidir-i-smet-barlioglu-zlu0v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birşeye peşinen inanan değil,

Arayan, tarayan, soran iyidir.

Menzili uzaktan seyreden kötü,

Ulaşıp yanına varan iyidir.

Küheylandan güçlü dizgini, gemi,

Aslana hükmeder ''Dizgin'' dendimi,

Bırak kolayından yol göstereni,

Yarayı eliyle saran iyidir.

Hastalık acizin damarlarında,

Bal yese boşadır herbir vaktinde,

Kelle soğanları yumruk altında

Kırarak ikiye yaran iyidir.

İlim güzel şeydir inancın varsa,

Korkusu azalır insan okursa,

Cehalet önünden kaçanlardansa

Önüne dikilip duran iyidir.

Yılmayan iyidir, yılanlar değil,

Bıkmayan iyidir, bıkanlar değil,

Bir büyük sarayı yıkanlar değil

Kerpiçten bir damı kuran iyidir.

İyi, dinleyince duyan kulaklar,

İyi, konuşurken gülen dudaklar,

İyi; doğru yola giden ayaklar,

Baktığı şeyleri gören iyidir.

Arsıza, gaddara acıyan kötü,

Yaralar içinde sancıyan kötü,

Hikmet der; vaktini harcayan kötü,

Bir hayırlı işe veren iyidir.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 375-376/412)', 'Birşeye peşinen inanan değil, Arayan, tarayan, soran iyidir. Menzili uzaktan seyreden kötü, Ulaşıp yanına varan iyidir. Küheylandan güçlü di...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/iyidir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zevkin Çilesi Olur', 'zevkin-cilesi-olur-i-smet-barlioglu-9pccj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dokurken bak tezgaha; 

Gözün dolası olur.

O beyaz bez sabaha

Kefen olası olur.

Bir gün kırılır dallar,

Biter bitmeyen yollar,

Güvenilen tüm mallar

Burda kalası olur.

Ko serveti, samanı,

Yok ecelin amanı,

O körpe, güzel canı

Çekip alası olur.

Ömür sudur ırmakta,

Kefen hazır tezgahta,

Sanma ölüm uzakta,

Bir gün gelesi olur.

Boşa geçmesin anın,

Tükenmeden dermanın,

Anadan her doğanın

Mutlak ölesi olur.

Yaşlılıktan iğrenme,

Gençliğine güvenme,

Zevklerine baş eğme; 

Zevkin çilesi olur.

Bozuldumu mayası

Kalmaz erin davası,

Önceden ağlayası,

Sonra silesi olur.

Hikmet söyler; el dinler,

Çok kutsaldır sevenler,

Yol yordamı bilenler

Aşkın kölesi olur.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 377-378/412)', 'Dokurken bak tezgaha;  Gözün dolası olur. O beyaz bez sabaha Kefen olası olur. Bir gün kırılır dallar, Biter bitmeyen yollar, Güvenilen tüm ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/zevkin-cilesi-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayağın Bir Kaydımı', 'ayagin-bir-kaydimi-i-smet-barlioglu-g3yli', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dikkatli ol, ayık ol, doğru yaşa hayatı,

Ayağın bir kaydımı sakın dost most arama.

Hiç kimse tercih etmez taze varken bayatı,

Ayağın bir kaydımı sakın dost most arama.

Namus asla değildir hayatta bir gün için,

Düşman insanı sever menfaya sürgün için,

Bütün ömrünü sarfet namusun, görgün için,

Ayağın bir kaydımı sakın dost most arama.

İşde demir değnek ol, hiylen, hurdan olmasın,

Arandımı tek zerre ayıbın bulunmasın,

İş işten bir geçtimi saç, sakal yolunmasın,

Ayağın bir kaydımı sakın dost most arama.

Herbir yakın utanır ayıplı yakınından,

İğrenip utanarak kaçar gider yanından,

Silip atman gerekir onları umudundan,

Ayağın bir kaydımı sakın dost most arama.

Terkeder anan baban, uzaklaşır evladın,

Beklersen yollarını gözde kalır muradın,

Tükenir yavaş yavaş her geçen gün takatın,

Ayağın bir kaydımı sakın dost most arama.

Dosdoğru git yolunda, eğriliğe özenme,

Düşersen koşar diye dostlarına güvenme,

Bugünkü kazancının hepsini bugün yeme,

Ayağın bir kaydımı sakın dost most arama.

Kaldıran sen olursun düştüğünde kendini,

Ayağını sağlam bas, düzenle ahengini,

Kulaç kulaç giderek öyle tuttur engini,

Ayağın bir kaydımı sakın dost most arama.

Dost bulunur varlıkta, el neylesin düşmüşü? 

Herkes birlikte ister fındık ile kişmişi,

Düşene hayal olur azametli geçmişi,

Ayağın bir kaydımı sakın dost most arama.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 379-380/412)', 'Dikkatli ol, ayık ol, doğru yaşa hayatı, Ayağın bir kaydımı sakın dost most arama. Hiç kimse tercih etmez taze varken bayatı, Ayağın bir kay...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ayagin-bir-kaydimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben sevgiyi yaşamak isterken', 'ben-sevgiyi-yasamak-isterken-ayten-ozlem-yesilcali-ah0me', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben sevgiyi yaşamak isterken  öldüm.

Yaşayamadım  bilemeden,gerçek sevilmenin; 

Ne olduğunu,ama sevmenin bedelinin ağır ödedim.

Acaba her sevgi,her sevda böylemiydi..

Hiç sanmam sadece bu benim kaderimdi.

Ben sevmeyi özlemeyi yaşamayı hep şiirlerimde yaşadım.

Yaşadımmı onuda bilemedim,sadece bahtsızlıgımın; 

Çok örneklerini gördüm.

Anladımki,hep kaçan kovalanır.

Ama gerçek sevgi kovalamak değilki.

Peşinden koşturmak aglamak aglatmak sevgibu degill.

Sen bulamamışsın gerçek seveni.

Sende ol aldatıcı sende ol degersizligin simgesi.

Ama biliyorum sen.

Sensizliginin bedelini çok agır ödedin.

Sevgi bedel ödemekse ben bunu çoktan ödedim be bebegim', 'Ben sevgiyi yaşamak isterken  öldüm. Yaşayamadım  bilemeden,gerçek sevilmenin;  Ne olduğunu,ama sevmenin bedelinin ağır ödedim. Acaba her se...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-sevgiyi-yasamak-isterken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal da Gör', 'kal-da-gor-i-smet-barlioglu-qf5o8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey erenler, anlamazsan halimden

Bedeninden dışarlarda kal da gör.

Aklım yorgun düştü kelam elinden,

Bu zorlukta, bu darlarda kal da gör.

Yüreğimde geziniyor ellerim,

Önümdeki izler benden evvelim,

Bu ruhuma gömlek oldu bedenim,

Ölü dolu mezarlarda kal da gör.

Varlığıma yaman kalıp aldandım,

Dürtüklenip gafletlerden uyandım,

Dilim dilim parçalandım, doğrandım,

Keskin keskin hızarlarda kal da gör.

Tad ve lezzet kalmadı tek işimde,

Ölüm emrim yüreğimin başında,

Köle oldum efendimin peşinde,

Yalın ayak pazarlarda kal da gör.

Ben kendime öz kendimi arattım,

Düşüncemi mızrak ettim, fırlattım,

Yine kendi bedenime saplattım,

Bir derinde nazarlarda kal da gör.

Hikmet diyor; kimse bilmez derdimi,

Arıyorum ben kendimde kendimi,

Ben olursun bu ben sana geldimi,

Bu ahlarda, bu zarlarda kal da gör.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 381-382/412)', 'Ey erenler, anlamazsan halimden Bedeninden dışarlarda kal da gör. Aklım yorgun düştü kelam elinden, Bu zorlukta, bu darlarda kal da gör. Yür...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kal-da-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hülyadan kocasına', 'hulyadan-kocasina-ayten-ozlem-yesilcali-u6326', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşte sen  bunu bilemedin,kanın kanım.

Canım canın.sen benim belelım degıll

Sen ben aynı kanın aynı atar damarın.

Kanlarıyız....

Ben bütün bunları dinledikce.sana hayran kalıyorum.

Nedenini bende bilemiyorum ama,gerçekleri seviyorum.

Bir ömür boyu.

Dogum günün kutlu olsun derim.

Nedenini ben de bilemiyorum.

Hayatın sana verdigi yükmü onuda çözemedim.

Ama,sensiz hayat anlamsız  bunuda bil...

Dogum günün kutlu olsun canım..

Sen 24 haziranın buyurduğusun.

Ve benim çocuklarımın babasısın.

İçimde ne kadarda yılların yorgunluğu olsa da.

Senin dogum günün kutlu olsun.', 'İşte sen  bunu bilemedin,kanın kanım. Canım canın.sen benim belelım degıll Sen ben aynı kanın aynı atar damarın. Kanlarıyız.... Ben bütün bu...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hulyadan-kocasina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçmalığa Övgüler-01', 'sacmaliga-ovguler-01-oguzkan-bolukbasi-ik5d1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen

hiçbir şey

yoksun

sen hiçbir şey

sen yoksun

benim işim

aşkla

hayatla falan

ben masumum

ben hayat

ben aşk

sen yoksun

tutuklusun

zincirin kendinsin

ben özgürüm

çünkü yokum

yok olmadan özgürlük yok

gökyüzüm uçtu

maviyi kurtaralım', 'sen hiçbir şey yoksun sen hiçbir şey sen yoksun benim işim aşkla hayatla falan ben masumum ben hayat ben aşk sen yoksun tutuklusun zincirin ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sacmaliga-ovguler-01-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Almaz Hayal de', 'seni-almaz-hayal-de-i-smet-barlioglu-1r6rm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine seni özledim,

Ruhumu alazladım,

Her yerde avazlandım,

Bende olduğun halde.

Baktım ellerimdesin,

Söyleyen dilimdesin,

En derin yerimdesin,

Her bir zerren bir belde.

Gözde yazılı izin,

Yürünmez görmeksizin,

Göze yerleşmiş gözün,

Her sıfatın bir dilde.

Sırrın keskin bir neşter,

Aklımı doğrar, biçer,

Sevgin işleyen hançer,

Saplı kalmış gönülde.

Çöllerde su gibisin,

Dilde ''Ya Hu'' gibisin,

Kumda ahu gibisin,

Zarafetsin sümbülde.

Benzerin yok, eşin yok,

Tek bir eksik işin yok,

Bakisin, gidişin yok,

Seni almaz hayal de.

Bir nursun aydınlatan,

Karanlıkları yırtan,

Yüreği sızıldatan,

Renk olmuşsun her gülde.

Seni sevmek san^''attır,

Unutmak kabahattır,

Hikmet bir tiz feryattır

Senle dolu evrende.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 383-384/412)', 'Yine seni özledim, Ruhumu alazladım, Her yerde avazlandım, Bende olduğun halde. Baktım ellerimdesin, Söyleyen dilimdesin, En derin yerimdesi...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/seni-almaz-hayal-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanal alemde aşk.', 'sanal-alemde-ask-ayten-ozlem-yesilcali-4d19n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sizi tanıdım hoşsohbet tavlada; 

Hepiniz birbirine aşık sevdalı ne güzel kardeşlik.

Ama bir ikiniz vardınızki,görmedim yaşadım.

Sizin gibi sevdayı yalnızlık.

Aşkın sanalı olmaz aşk aşktır.

Sevgi sevgidir.O senin nik in olmadan üzülüyorsa.

Sana sevgi mesajları yolluyorsa sanalda olsa.

Hala seni sevdiginin  kanıtıdır.

Sanalda degil sevmek yürektedir,bedendedir.

Sevmek sanalda yürektir görmeden hissetmektir.

Geçekte sevip aldatmak degil.

Ben gördüm sanalda gerçek sevenleri.

Aynı sahte aşklarıda gördüm,sevgiyi bilemeyeni.

Aldatmak için seviyorum diyeni,bir ufacık hata da

Sanki namus meselesi yapıp,aslında kendisini ifade edeni.

Neden sanalda yalan söylediginin  ispatına gidilmemesini.

Ama ben sanalda tanıdım 4 tanenin birbirini sevdigini.

Ne olursa olsun.

Sanalda olsa sevmenin çok bedel istedigini.', 'Sizi tanıdım hoşsohbet tavlada;  Hepiniz birbirine aşık sevdalı ne güzel kardeşlik. Ama bir ikiniz vardınızki,görmedim yaşadım. Sizin gibi s...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sanal-alemde-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni çok seviyoruz', 'seni-cok-seviyoruz-ayten-ozlem-yesilcali-fi7vg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Belki zaman geldi kendini çok yalnız hissettin beklide kaçmak kurtulmak istedin

Ama biliyomusun teyze bizler hep başkaları için yaşamak zorunda bırakıldık

Yeri geldi hüzünlerimizde bile sırf başkaları üzülmesin diye ağlayamadık 

Yinede gülmeyi başardık seninle

Çünkü gülmeyi sen öğrettin bize

Biliyomusun hayatta kaç tane kız erkek var senin gibi bir teyzesi olmayı isteyen

Ben hep şükrediyorum iyiki bizim teyzemiz oldun

Anneannem gitti ama senin kadar değerli birini bizlere bıraktı

Baştada söyledim ya başkaları için yaşıyoruz diye

Sende bizler için yaşamalısın

Bizler için kendine bakmalısın

İyiki varsın.

Kızımın teyzesine yazdıgı şiir benim degil bu

ama ondan izin alarak kayıt yaptım.', 'Belki zaman geldi kendini çok yalnız hissettin beklide kaçmak kurtulmak istedin Ama biliyomusun teyze bizler hep başkaları için yaşamak zoru...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-cok-seviyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Ana Anam Değil', 'o-ana-anam-degil-i-smet-barlioglu-6lpe4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uydum gerekçelere dünyaya dönmek için,

Bir anadan doğdum ki; o ana anam değil.

Uğraştım aileme aile demek için,

Bir anadan doğdum ki; o ana anam değil.

Anam sandı; o doğar beni binbir zahmetle,

Ben ise bekliyordum doğuşumu hasretle,

Böylece geri geldim üstümdeki rahmetle,

Bir anadan doğdum ki; o ana anam değil.

Dilim bebek diliydi, yetmedi meramıma,

Büyük sözler sığmadı yetersiz kelamıma,

Başka sebep buldular ahıma, feryedıma,

Bir anadan doğdum ki; o ana anam değil.

Doğruları gösterdim, parmağım ayıplandı,

Dinleyen meramımı başka türlü kullandı,

Defterler çiziktirdim, bakanlar anlamadı,

Bir anadan doğdum ki; o ana anam değil.

Tek gece uyumadım, sandılar ki hastayım,

Halbuki beden küçük, ben içinde yastayım,

Bir yetersiz bedende bin hünerli ustayım,

Bir anadan doğdum ki; o ana anam değil.

Secdelere kapandım, güldüler, okşadılar,

Kendimi reddeyledim, vurdular, haşladılar,

Beni el etmek için talime başladılar,

Bir anadan doğdum ki; o ana anam değil.

Eller kardeşim oldu; anamız aynı diye,

Ben ise bedenimde birleştim evvelime,

Fakat gövde yetmedi gerçeği göstermeye,

Bir anadan doğdum ki; o ana anam değil.

Büyüyünce gerçeği anlattım; deli oldum,

İnad edip direndim; ondan zırdeli oldum,

Gerçeksizler içinde gerçeğin dili oldum,

Bir anadan doğdum ki; o ana anam değil.

Bilenlerin gerçeği değil benim gerçeğim,

Gerçeklerden gelmişim, gerçeğe gideceğim,

Bir gelmiştim, bir daha, bir daha geleceğim,

Bir anadan doğdum ki; o ana anam değil.

Barlıoğlu diyor ki; değişen fazla şey yok,

Gerçekte doğu, batı ve kuzey ve güney yok,

Gelenler hep fanidir; tek ağa yok, tek bey yok,

Bir anadan doğdum ki; o ana anam değil.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 385-387/412)', 'Uydum gerekçelere dünyaya dönmek için, Bir anadan doğdum ki; o ana anam değil. Uğraştım aileme aile demek için, Bir anadan doğdum ki; o ana ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/o-ana-anam-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırlar Cenderede', 'sirlar-cenderede-i-smet-barlioglu-aff2y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmurlar altında bükmüş boynumu,

Ellerim, saçlarım sular içinde.

Yıkadım sularda kötü huyumu,

Tek işim kalmadı huylar içinde.

Dilim temizlendi rendelenerek,

Yüreğim düzeldi kündelenerek,

Sırra koşuyorum yelşem yelpirek,

Yıldızlara döndüm aylar içinde.

Esrarlar içinde ufandı fikrim.

Bitmez secde oldu gündelik zikrim,

Her nefes alışta çoğaldı şükrüm,

Bir şırıltı oldum çaylar içinde.

Aradığım sırdır sularda, taşta,

Aklım sırlar için yaman uğraşta,

Her adım başında ruhum telaşta,

Yüreğim vay vayda, vaylar içinde.

İçlerin içine sığamıyor dış,

İçler dışa karşı tutuyor alkış,

Bu yüzden dilimde bitmez haykırış,

Tükendim hay hayda, haylar içinde.

Barlıoğlu şimdi tek bir şey demez,

Görünen hiçbir köy rehbet istemez,

Sır olmayan sırrı kimse ellemez,

Sırlar cenderede, yaylar içinde.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 388-389/412)', 'Yağmurlar altında bükmüş boynumu, Ellerim, saçlarım sular içinde. Yıkadım sularda kötü huyumu, Tek işim kalmadı huylar içinde. Dilim temizle...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sirlar-cenderede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup / itiraf', 'mektup-itiraf-k-muran-esen-dgy7b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgili Çocuklar; 

            Emekli olalı, yani sizden ayrılalı  beş yıl oldu. Birlikte olduğumuz yıllar nasıl geçti, anlayamadım bile.Hani gördüğümüz kısacık rüyalar vardır ya; işte  öğretmenlik yıllarım, o rüyalar gibiydi. Çok uzun yıllar sürmesine karşın, bana bir gün gibi kısa gelmişti. Çünkü, mesleğimi ve sizleri çok seviyordum..   

Hiç unutmam:Mudurnu’nun Karataş Köyü İlkokulu’nda öğretmendim. Bir kış sabahı uyandığımda, yerde birikmiş yarım metreden fazla karı görünce telaşlandım. Ben şimdi okula nasıl gidecektim? 

             Binbir güçlükle okula gelebildik. Hepinizi, o soğukta, okulun önünde buldum.Omuz omuza vermiş,  yerdeki karları çiğniyordunuz. Hem de ayaklarınızdaki lastik ayakkabılarla. Arabamızın okulun önünde rahat dönebilmesi için, arabaya yol açıyordunuz. Ayakkabılarınızın içine karlar dolmuş, ayaklarınız ıslanmıştı. Hatırladınız mı? 

              Sevgili çocuklar! Birinci sınıfa başladığınız ilk günleri hatırlıyor musunuz? Bir çoğunuz, korkak ve ürkektiniz. Okuldan, benden korkardınız. Annenizden, babanızdan ayrılmak istemezdiniz. Bazılarınız annelerinizle beraber okula gelir, annenizin sınıfta durmasını isterdiniz.

              Sınıfımızın pencere önleri çiçeklerle dolu olurdu. Her gelen, sınıfımızı çok güzel, sıcak bulurdu. Bunun nedeni sadece çiçekler değildi tabi. Sınıf sizinle güzeldi... Her yer insanla güzeldir. Ben  dünyanın en güzel yerine gitsem, arkadaş ararım yanımda. Soluyan bir canlı olmalı yanı başımda. Severim başkaları ile bir şeyleri paylaşmayı. Gece, komşumuzun penceresinden sızan ışık bile, yalnızlığımı unutturur. Gece yolculuklarında ta uzaktan görünen ışıklarda, o ışığın aydınlattığı insanları gözümde canlandırmaya çalışırım, onların yüzünü görür gibi olurum. İnsanı sevmekle başlıyor her şey. Sevmek başarmanın ve mutlu olmanın yarısıdır, bana göre.  Size olan sevgim  vermedi mi bana çalışma azmini? Başarıya ulaşmamda, size olan sevgim etken olmadı mı?

            Bir gün bir arkadaşınıza ceza vermiştim. Suçu neydi, hatırlamıyorum. Birinci sınıftaydınız. Verdiğim ceza da, arkadaşınızın Beden Eğitimi dersinde sınıfta oturacak olması idi. O arkadaşınız bu dersi çok severdi. Ona verilecek en büyük ceza, kendisini bu dersten uzak tutmaktı. İlk derste olmuştu, ne olduysa. Arkadaşınıza  “Beden Eğitimi dersine katılmama” cezasını verdiğimi kendisine söyledim. Son dersti Beden Eğitimi. Ders saati gelince onu sınıfta bırakıp, bahçeye çıktık. Arkadaşınız sınıfta yalnız başına kalınca, içim burkuldu. Ancak, verdiğim cezayı geriye alamazdım, almamam gerekirdi. 

              Derse başladık. Bir ara unutmuştum cezalı arkadaşınızı. Birden aklıma geldi. Kendimi  üvey ana gibi hissettim...Verdiğim cezaya pişman olmuştum. Siz oyun oynarken, alt katta olan sınıfımızın penceresine geldim. Kendimi göstermeden, pencerenin dışından, cezalı arkadaşınızın yalnız başına sınıfta ne yaptığına bakmak istedim. Gördüğüm beni çok üzdü. O, öğle yemeğine gittiğinde bir bebek getirmişti oynamak için. Masanın üzerine bebeğini yatırmış, altına bez bağlıyordu. Kendini oyalayacak bir şey bulmuştu. Çok üzülmüştüm. Ancak yapacak bir şeyim yoktu. Verdiğim karardan – yanlış bile olsa -  geriye dönmemem gerekirdi. Sonra kızdım kendi kendime. Daha sabırlı davranabilir, arkadaşınıza daha hafif bir ceza verebilirdim. 

              Kısacası, zaman zaman yaptığım şeylerden pişmanlık duyduğum çok oldu. Pişmanlık duyduğum halde, devam ettirmek zorunda kaldığım davranışlarım da. Sizin iyi bir eğitim almanız içindi her şey. O an bana doğru gelen ne ise, onu uyguluyordum. Bazen ”Şimdiki aklım olsaydı! ” diyorum. 

               İlkokuldan mezun olup da, ortaokula başladığınızda, tenefüslerde beni ziyarete gelirdiniz. Neyse ki, gittiğiniz ortaokulla, ilkokul çok yakındı. O nedenle ders aralarında yanıma gelmeye zaman bulabiliyordunuz. Yeni öğrencilerime kıskanarak bakardınız. Küçümser bir tavır takınarak; ” Öğretmenim, ne kadar çirkin yazıyorlar.” ya da “ Bunlar nasıl okuma- yazma öğrenir! ” derdiniz. Onları şımarık, yaramaz bulurdunuz.Daha doğrusu kıskanırdınız. Sizi mi, yoksa yeni öğrencilerimi mi daha çok sevdiğimi sorardınız. 

               Ben; sınıfa her girişimde, yeni öğrencileri görünce tuhaf olurdum. Gözlerim hep sizi arardı. Bazen unuturdum yeni öğrencilerimi. Sınıfa girip, sizin yerinizde onları görünce, şaşırırdım birden. Sizin yerlerinizde başka öğrenciler oturuyorlardı. Yeni öğrencilerimi asla sizi sevdiğim kadar sevemeyeceğimi düşünürdüm.Ayrıca, bu öğrencilerin sizin bilgi düzeyinize   gelemeyecekleri endişesine kapılırdım. Emek verdiğim, yetiştirdiğim öğrencilerimin sınıfımdan uçup gitmesini; bana, her şeyden habersiz, hiç yazı yazılmamış beyaz bir kağıt gibi boş çocukların verilmesini kabul edemezdim. 

          Sizin ortaokuldaki öğretmenlerinizi kıskanırdım. Hani siz, benim yeni öğrencilerimi kıskanıyordunuz ya; ben de sizin yeni öğretmenlerinizi kıskanırdım. Ben eğitiyordum sizi, onlar alıyordu elimden. Bazı öğretmenler de sizi bana şikâyet ederlerdi. Yaramazlıklarınızı falan anlatırlardı. Sinirlenirdim onlara. Sizlerin kıymetinizin bilinmediği zannına kapılırdım.... Ama bunları size nasıl söyleyebilirdim ki! “Çocuklar ben, sizi seviyorum, yeni öğrencilerime alışamadım. Ortaokuldaki öğretmenlerinizi de sevmiyorum hiç. Size, benim kadar sevgiyle yaklaşacaklarından şüpheliyim.” diyebilir miydim? 

            Bir de, rahatsızlığım nedeniyle sizlerden aylarca ayrı kaldığım o yılı hiç unutmam:1995-96 Öğretim Yılında belimden rahatsızlandım.Yürüyemez hale geldim. Birinci dönemin son günlerinde, okula nasıl zor geldiğimi eminim hatırlarsınız.Dinlenme tatilinde de ikinci kez ameliyat olmuştum.Ve doktorum bana altı ay rapor vermişti. Düşünebiliyor musunuz, altı gün değil, altı hafta değil, tam altı ay. Bu altı ay nasıl geçecekti! Sizlerden ayrı kalmaya henüz hazır değildim. 

              Sizden ayrı geçirdiğim o altı ay içinde neler hissettiğimi, size bir an önce ve sağlıklı bir şekilde kavuşmak için nasıl gayret ettiğimi, içimden neler neler geçirdiğimi size anlatabilmeyi nasıl isterdim çocuklar! Hatırlıyor musunuz, bütün sınıf beni ziyarete geldiğiniz günü? Ameliyatımın üzerinden on gün falan geçmişti. Zorla yataktan kalkıp, giyinmek istemiştim geleceğinizi duyunca. Ama bunu başaramamıştım. Sadece saçlarımı tarayabilmiştim. Bir de solgun yüzüme biraz renk vermek için allık sürmüştüm. Size solgun görünmek istemiyordum. Buna rağmen yüzümde, geçirdiğim ağır ameliyatın ve ağrıların izleri olduğundan emindim... 

            Odama girdiğinizde hepinizin gözlerinde hüzün vardı. Bana, acıyarak ve üzülerek bakıyordunuz. Size söyleyecek öyle çok sözüm vardı ki! Acaba yokluğumda ne yapıyordunuz? Yeterli  sevgi ve ilgi görüyor muydunuz? Nasıl eğitiliyordunuz? Acaba bazı şeyler eksik mi kalıyordu? Ama konuşamıyordum,soramıyordum.Duygularıma yenilip, karşınızda ağlamaktan korkuyordum.Bir de, benim yerime geçici görevle verilen öğretmeni incitmek, ona güvenmediğim hissini uyandırmak istemiyordum. 

            Benim yerime geçici  olarak görevlendirilen öğretmeninizle birlikte  çekip gittiniz az sonra.... Nasıl oldum biliyor musunuz? Yavrularını bırakıp giden bir anne gibi gördüm kendimi.Aynı zamanda aciz, zavallı, işe yaramaz biri. Kendime olan güvenimi,cesaretimi yitirdim. Sanki uykum gelmiş gibi, evdekilere arkamı dönüp, gözlerimi kapadım. Sessiz sessiz ağladım yatağımda... 

           Siz gidince düşündüm hasta yatağımda.Acaba sağlığıma ve size yeniden kavuşabilecek miydim? Öğretmenliğe yeniden dönebilecek miydim? Her gün neredeyse bir avuç hap içmek zorunda olmam, beni çok üzüyordu. O küçücük şeylerin esiriydim,esiri olacaktım tam birbuçuk yıl boyunca. Beni onlar iyileştirecek, beni size onlar kavuşturabilecekti ancak. O küçücük şeyler. 

          Derken  öğretim yılı bitti, araya yaz tatili girdi. Okuldan böylece sekiz ay uzak kaldım, yaz tatili ile birlikte. Siz dinlenmek için belki de tatili dört gözle beklerken, okulların açılacağı günü iple çekebilmeyi istiyordum ben.Yeni öğretim yılını beklemekten başka yapacağım bir şey yoktu. 

            Yaz tatilinde, yeni öğretim yılının bütün hazırlıklarını tamamladım. Birkaç haftamı aldı bu çalışmalar.Nasıl özlemiştim çalışmayı, yorulmayı. Kalemim kâğıt üzerinde uçar gibi gidiyordu. Kalem tutabilmek, yazabilmek ne kadar güzeldi! Bu çalışmaların büyük bir kısmını,çok özlediğim okulda yaptım.Tatil bile olsa, okula gitmek, çalışmalarımı okulda yapmak bana iyi geliyordu. Orada içtiğim kahvenin tadı bile bir başkaydı. 

             Okulların açılmasına yakın; okula yeni başlayacak bir öğrencinin heyecanı sardı beni. Kendime yeni çantalar, ayakkabılar,  giysiler aldım, çocuklar gibi. Eksikliğini hissettiğim şeyleri, sanki bu şekilde telâfi ediyordum.  Okulun açılmasını beklemeye başladım. Sizleri ve okulu çok özlemiştim. Ama günler geçmek bilmiyordu. İşte o zaman, “Ben emekli olursam ne yaparım? ” diye sordum kendime. Emeklilik, işte o günden sonra  beni hep ürküttü, hep korkuttu. 

           Şimdi emekli bir öğretmenim artık.”Zaman en iyi bir öğretmendir.” derler ya; işte o öğretmen, bana çok şey öğretti. Okulsuz ve sizsiz yaşamayı bile.Okula gitmiyorum, “Öğretmenim! ” diyen sesinizi duymuyorum  ama halâ yaşıyorum.Bunu nasıl olup da başarabildiğime şaşıyorum. 

                Sizi çok seviyorum.Hepinizi öyle özledim ki!', 'Sevgili Çocuklar;              Emekli olalı, yani sizden ayrılalı  beş yıl oldu. Birlikte olduğumuz yıllar nasıl geçti, anlayamadım bile.Han...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mektup-itiraf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumartesi Mektupları 3', 'cumartesi-mektuplari-3-celal-sahin-6stzi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nerede? 

Güneş hüzünle eş doğuyor

Bir avuç grileşmiş gökyüzüne.

Kanadı kırık martıların.

Erguvan pembesinin üzerinde 

İs rengi beton bloklar

Ejderha gibi çökmede.

Sığınmışım yalnızlığımın gölgesine

Karanlıkları hapsederken yüreğime

Gelişini bekleyen gözlerle

Nerede benim umutlarım

Kaçıncı solgun baharım? 

                              12.06.2004', 'Nerede?  Güneş hüzünle eş doğuyor Bir avuç grileşmiş gökyüzüne. Kanadı kırık martıların. Erguvan pembesinin üzerinde  İs rengi beton bloklar...', ARRAY['Türk Edebiyatı','Şiir','Celal Şahin']::text[], 8.5, '{"poet":"Celal Şahin","poet_slug":"celal-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cumartesi-mektuplari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak Yolunu Ne Bilir?', 'hak-yolunu-ne-bilir-i-smet-barlioglu-xmnlc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kirpiği yaşsız olan

Hak yolunu ne bilir? 

Ruhu telaşsız olan

Hak yolunu ne bilir? 

Aç önünde aş yiyen,

Beden yiyeni baş yiyen,

Bir yeterken beş yiyen

Hak yolunu ne bilir? 

Yaşlılara hor bakan,

Yoksullara zor bakan,

Her bir şeye kör bakan

Hak yolunu ne bilir? 

Uykulara doymayan,

İlmi başa koymayan,

İniltiyi duymayan

Hak yolunu ne bilir? 

Mezardan yol geçiren,

Vurduğunu göçüren,

Haram ekmek devşiren

Hak yolunu ne bilir? 

Izdıraba gülenler,

Zor sadaka verenler,

Rızkı hakir görenler

Hak yolunu ne bilir? 

Hikmet der; has olmayan,

İçinde yas olmayan,

Kalbinde ses olmayan

Hak yolunu ne bilir? 

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 390-391/412)', 'Kirpiği yaşsız olan Hak yolunu ne bilir?  Ruhu telaşsız olan Hak yolunu ne bilir?  Aç önünde aş yiyen, Beden yiyeni baş yiyen, Bir yeterken ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hak-yolunu-ne-bilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl', 'akil-i-smet-barlioglu-r1ia1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akıllıyla akılsız birbirine eş değil,

Akıldan yaya olmak dayanılır iş değil.

İçerisi boş olan başlar asla baş değil,

Akıldan yaya olmak dayanılır iş değil.

Akıl gibi cevher yok en zengin hazinede,

Akılsız olan düşer kolaylıkla zillete,

Şükür et aklın varsa, o verilmiş nimete,

Akıldan yaya olmak dayanılır iş değil.

Yöneten salt akıldır bedeni maharetle,

Doğruyu eğrilerden ayırır dirayetle,

Yıprandıkça gelişir daha büyük gayretle,

Akıldan yaya olmak dayanılır iş değil.

Herbir türlü kararı kotarıp alan akıl,

Ayağın basmadığı yere uzanan akıl,

Sevgilisi uğruna tutuşan, yanan akıl,

Akıldan yaya olmak dayanılır iş değil.

Gülünce gülen odur, o ağlar ağlayınca,

Hasrete düşen odur yari bulamayınca,

Her işi o başarır karınca kararınca,

Akıldan yaya olmak dayanılır iş değil.

Keramet akıldadır şaha kalkınca yürek,

Korkunca korkan odur ürküp yelpirdeyerek,

Gaddar olan akıldır insafa gelmeyerek,

Akıldan yaya olmak dayanılır iş değil.

Ellerin ne iş görür aklın çalışmıyorsa? 

Cehdin nerden doğacak aklın savaşmıyorsa? 

Eli nasıl seversin aklın bağdaşmıyorsa? 

Akıldan yaya olmak dayanılır iş değil.

Barlıoğlu diyor ki; akıl bedenin şahı,

Bir değersiz ülkenin değerli padişahı,

Duygular aklın yalnız birer küçük meddahı,

Akıldan yaya olmak dayanılır iş değil.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 392-393/412)', 'Akıllıyla akılsız birbirine eş değil, Akıldan yaya olmak dayanılır iş değil. İçerisi boş olan başlar asla baş değil, Akıldan yaya olmak daya...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/akil-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tango Sevdalısı Babama (Babalar Günü Anısına) ....', 'tango-sevdalisi-babama-babalar-gunu-anisina-hulya-topcuoglu-xvhsj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün en özel günlerden biri, ama sen yoksun

Sensizliğin bilmem kaçıncı yılı

Kaç yıldır sensiz yaşıyorum, bilemiyorum

Sanki sen varmış gibi düşündüğümden olacak

Yılları saymıyorum, sayamıyorum....

Biliyorum, yalnız değilim babasızlıktan yana 

Bir çok evlat var bu günde benim gibi ağlayan 

Ama ben ağlamıyorum, ağlayamıyorum 

Matemi sevmediğini bildiğimden olacak 

Seni tangolarla hatırlıyorum....

''Papatya gibisin'' ve '' Sevdim bir genç kadını''

İşte bu tangolardı, ıslıkla hep çaldığın

Beni kucaklayıp havaya kaldırdığın,

Birlikte gülerek dans ettiğimz tangolar,

Senden sonra kavalyesiz kaldırlar...

Şimdi hayattaki babalara sesleniyorum 

''Babalar Gününüz Kutlu Olsun''

Erken göçen kadersiz babalar,

Sizlerin  de ruhu şad olsun,

Kabirleriniz nurlarla dolsun! 

(Tüm Babalara, Babalar Günü Anısına) 

2002/İstanbul...', 'Bugün en özel günlerden biri, ama sen yoksun Sensizliğin bilmem kaçıncı yılı Kaç yıldır sensiz yaşıyorum, bilemiyorum Sanki sen varmış gibi ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Topçuoğlu']::text[], 8.5, '{"poet":"Hülya Topçuoğlu","poet_slug":"hulya-topcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tango-sevdalisi-babama-babalar-gunu-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görüntüye sızan düş', 'goruntuye-sizan-dus-akin-akca-iozmn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İki kişi yaptı dağda odun evi, yani ordaki tekti; 

Konuştu gölgeler, susmadığında tek bir zafer.

Yağmur yağar, ilk damlası sel olanı iletir; 

Sel olansa göl, başlangıçta gelen sudur,

Görüntünün içine sızan düş,bu can yaprakları.

Sonbaharda sergilenmeyen bir düşüş,

Yüreğin izin vermediği aşka sanılır da; 

Müsaade edemeyiş değil bazen üzen,

Etmeyiş..En samimidir bu tür bir reddediş …

Kerelerce aslına sönüş, ama sevdiğini bırakmayış.

Bağlanmış uyağında, yılgın umursamazlıkta; 

Önemsiz diye kendini kandırdığını

Ya da kızdığını düşün sen yine

Ve hayatın kapısı zamanı eşikten atlatışında

Kendine sorarken az üzül, verme fire.

Ne dünler vardı ve ne bugünler,

Ve daha kocamandır ama yarınkiler

Zaman ne getirir bilinmez -

Fakat tutulması en muhtemel, elin kavradığı

İyi ya da kötü, ilginçtir: kapılmaz.

Üzülme ve ağlama, zamanı kedere harcama; 

Ama uyağı tasaya bağla, mutlu ol yarınlara.

Anlamazsın bazen olanı biteni,

En az senin kadar diğeri de üzülür de; 

Böyle olduğunda, ufacık bir rakım tazele

Ki sonbaharda sergilenemeyen değil

bu can yaprakları, sergilenmeyen düşüş

Görüntünün içine sızan bir düş.

Ahenk köpürür renklerde, renk tat vermediğinde; 

Çile dolduran bilir, ahenk köprüdür.

Köprüyü salla geçerken ki kararlılığı algılasın; 

Ya gedik versin veya sağlamlaşsın

Her daim ve her koşulda, seni harekete geçirsin.

Zaten güzelsin, duvak takmak da istersin; 

Bu esnada, bunu diyen sıfırı tüketir, varsın …

Kendini üzersin ve kendini suçlarsın

Ve bunu bilirsin, akıllısın ve duygulusun, ağlarsın.

Aslında kuantumun köpükleri gibidir

Geliş ve gidiş, sürünüş, yok edilemeyiş.', 'İki kişi yaptı dağda odun evi, yani ordaki tekti;  Konuştu gölgeler, susmadığında tek bir zafer. Yağmur yağar, ilk damlası sel olanı iletir;...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/goruntuye-sizan-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VUSLATTIR umut', 'vuslattir-umut-mehmet-kizilay-4ypxj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fethi yakındır umut istasyonunun

İnecek kadar yolcu var binecek

Lütfetmesin yıldızlar ışık verecem diye

İnci mercan yürekler ışıtacak bu mahseni

Zaman tükendi..bir bakıma dar vakitlerdeyiz..

Alacağın olsun ey gece

Tutup yalnızlığımın yakasından

Attığın düğümün var mı bir nedeni

Lakin yanılıyorsun..yalnızsın diyorsun

Artık çözsen diyorum

Nasılsa yalnız değilim..bir dost var

(Dost Şair Filiz Atalan''a İthaf Olunur..Saygılarımla..)

07.06.2004 – 03:06', 'Fethi yakındır umut istasyonunun İnecek kadar yolcu var binecek Lütfetmesin yıldızlar ışık verecem diye İnci mercan yürekler ışıtacak bu mah...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vuslattir-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğütname', 'ogutname-yusuf-koc-dtbla', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sakın ha yüzüme öfkeli bakma,

Gözyaşımı görür pişman olursun,

Gurur kolyesini boynuna takma,

Dost iken dünyaya düşman olursun.

Verdiğin sözde dur geriye kaçma,

Yalan muhabbeti meclise saçma,

Aşkın ölçüsünü mizansız biçme,

Susuz hamamlarda külhan olursun.

Sevdalar gönlüne girdiği zaman,

Zalimin elinden dersin el aman,

Arama yarana gurbette derman,

Tarladan kalkmayan harman olursun.

Yüzüne gülene dost diye kanma,

Zor gününde sana el verir sanma,

Cehennem ateşine dünyada yanma,

Kül olur bedenin destan olursun.

Eğilme kullara efendim diye,

Değmeyene aşkı veme hediye,

Eller sermayeni yükler kediye,

İmzası olmayan ferman olursun.

Yağmuru yağdıran bulutu gözle,

İnce kalbi kırma granit sözle,

Seni sevmeyenden aşkını gizle,

İhanete uğrar yardan olursun.

Gel Koç Ozan''ın dinle sözünü,

Çıkar için yere serme yüzünü,

EL etek öpene çalma sazını,

Sanma ki Mısır''a sultan olursun.', 'Sakın ha yüzüme öfkeli bakma, Gözyaşımı görür pişman olursun, Gurur kolyesini boynuna takma, Dost iken dünyaya düşman olursun. Verdiğin sözd...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ogutname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelaynak', 'kelaynak-yusuf-koc-zoze8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedir ki hayat,

üç beş lokma uğruna tükenmesi insanların..

aşklarla geçen zamanlar..ihanet.! 

sevgisizliğe inat..sevmek...tapınır gibi,

bir köşe kapmacadır gidiyor..

mini mini çıkarlar adına koca koca yalanlar söyleniyor...

        Ve bu panoramada ben oynuyorum kelaynağı,

         türünün son örneği..ve en salağı.! !', 'Nedir ki hayat, üç beş lokma uğruna tükenmesi insanların.. aşklarla geçen zamanlar..ihanet.!  sevgisizliğe inat..sevmek...tapınır gibi, bir ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kelaynak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nartanem', 'nartanem-cafer-tayyar-ozkan-odyi6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine seni y a z ı y o r u m tarifsizce dizelerimde,

Sonsuzluğa sünger ç e k e n hovarda düşlerimle,

Dilerim a s l a hüzün girmesin engin gönlümüze,

D i l i m d e hep adın var, sevdamız ise zikrimde,

Nartanem, sevdamızı meleklerden gizleyemedim...

Bu ölümsüz a ş k a ezan sesleri ş a h i t l i k etti, 

Yüreğimden titrercesine söyledim, ellerim yazdı,

Gönül pencerem b i l e kapanmadı, bize ağladı, 

İçim y a n a r k e n, tenimi şafağın a y a z ı sardı,

Nartanem, aşkımızı meleklerden gizleyemedim...

D a l uzaklara, bak m e l e k l e r i şahit yazdım,

Sana olan bitmeyecek s e v g i m i b i l s i n l e r,

Ben seni, t a t l ı sevdanı y ü r e ğ i m e kazıdım,

Silinmez de, silmek için k a l b i m i e z s i n l e r,

Nartanem, sözümüzü meleklerden gizleyemedim...

Yüreğimden esen sana h a s r e t i m i n yelidir,

Gözlerimde biriken aşkın vazgeçilmez nemidir,

Gel de gör, içimde kocaman bir hazine saklıdır,

Bak! S e n i son nefesime saklıyorum, bilsinler,

Nartanem, gönlümüzü meleklerden gizleyemedim...

Dönüşü belki hala yazılamayan, bir sözcüksem,

Yaşadığıma şahitlerim de m i n i k meleklerimiz,

Bir gün ilerde sana ve kendime ihanet edersem,

O gün geldiğinde haykırsın, s u s a n dillerimiz,

Nartanem,  içimizi meleklerden gizleyemedim...

Bozkırda tek ağacın gölgesinde c a n bulur gönüller,

Kıraç toprağın suyundan avuçla içer, yanan ciğerler,

Gökyüzü göle yatmış, sevgilinin sıcaklığını istercesine,

Bulutlar şahitlik yaparken, vuslata dayanamaz bedenler,

Nartanem, sırrımızı meleklerden gizleyemedim...

Hislerin galip, korkuların mağlup olduğu günleri,

Keşkelerin  yerine, iyi kilerin geldiği mevsimleri,

İmkansızlığın içinden koparak gelecek o rüyayı,

Gülen gözlerle, umudu yaşamak isteyen sevgilileri,

Nartanem, ukdemizi meleklerden gizleyemedim...

Ayrılırken gözlerde hep hüzün ve gözyaşı vardı,

Her vuslatta güneşimizi, yağmur bulutları sardı,

Sarılırken şarkılar bile alnımın yazısını yazarken,

Ardında busenin affını bekleyen g ö n ü l kaldı,

Nartanem, yerimizi meleklerden gizleyemedim...

05 Ekim 2002 İstanbul.', 'Yine seni y a z ı y o r u m tarifsizce dizelerimde, Sonsuzluğa sünger ç e k e n hovarda düşlerimle, Dilerim a s l a hüzün girmesin engin gön...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/nartanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Epigraf', 'epigraf-selim-aksan-o9pjq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çırpıda başlayan 

Yalnızlıklar ısınır bende 

Ömrümü kemirir 

Samankağıdında 

Kurşunkalemle gelişigüzel 

Bir yazıya dönüşür 

Daha ilk baskısında aşkım raflardan indirilir 

Bütün hayatım 

Ucuz bir romanın 

Son bölümüne 

Sadece 

Bir epigraf olur 

(Eylül 2000 ankara)', 'Bir çırpıda başlayan  Yalnızlıklar ısınır bende  Ömrümü kemirir  Samankağıdında  Kurşunkalemle gelişigüzel  Bir yazıya dönüşür  Daha ilk bas...', ARRAY['Türk Edebiyatı','Şiir','Selim Aksan']::text[], 8.5, '{"poet":"Selim Aksan","poet_slug":"selim-aksan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/epigraf-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Mevsimi', 'hazan-mevsimi-hazar-can-i33f8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sonbaharki hazan mevsimi demidir

Her gün her an bitmekteyim

Sanki ufukta kaybolan bir gemidir

Eyvahki hülyalarımın yeridir

Adım adım meçhule gitmekteyim

Sen baharım olurmusun?', 'Bir sonbaharki hazan mevsimi demidir Her gün her an bitmekteyim Sanki ufukta kaybolan bir gemidir Eyvahki hülyalarımın yeridir Adım adım meç...', ARRAY['Türk Edebiyatı','Şiir','Hazar Can']::text[], 8.5, '{"poet":"Hazar Can","poet_slug":"hazar-can","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hazan-mevsimi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Geceler', 'karanlik-geceler-hazar-can-uw45l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dolaşıyorum karanlık gecelerde

Biri var yanımda oda sensin

Tutmak istiyorum ellerini ellerimle

Ellerim boş kalıyor çünkü yanımda değilsin

Düşüyor gözlerimden ıslak kaldırımlara bir damla yaş

Geçiyor yanımdan düşe kalka bir ayyaş

Kimbilir ne derdi var unutacak kadar garibin

Olmak istiyorum bende kör kütük sorhoş...', 'Dolaşıyorum karanlık gecelerde Biri var yanımda oda sensin Tutmak istiyorum ellerini ellerimle Ellerim boş kalıyor çünkü yanımda değilsin Dü...', ARRAY['Türk Edebiyatı','Şiir','Hazar Can']::text[], 8.5, '{"poet":"Hazar Can","poet_slug":"hazar-can","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karanlik-geceler-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hıçkırık', 'hickirik-hazar-can-afbfm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerimde hüzün kalbim kırık

Boğazımda düğümlenen bir hıçkırık

Viran olmuş şu gönlümde yıkık

Geldi zaman çalıyor kapıyı ayrılık..', 'Gözlerimde hüzün kalbim kırık Boğazımda düğümlenen bir hıçkırık Viran olmuş şu gönlümde yıkık Geldi zaman çalıyor kapıyı ayrılık.....', ARRAY['Türk Edebiyatı','Şiir','Hazar Can']::text[], 8.5, '{"poet":"Hazar Can","poet_slug":"hazar-can","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hickirik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlız Adam', 'yanliz-adam-hazar-can-aho98', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dolaştım durdum gecenin karanlığında

Ümit aradım sokak lambalarında

Ağladım durdum karanlık sokaklarda

Seni aradım durdum ıslak kaldırımlarda

Seni sordum gözümdeki yaşlara 

Yaprak döken ağaçlara uyuklayan kuşlara

İsyan ettim kadere içimdemi hazlara

Vurdum başamı yosun tutan taşlara

Doğuyor güneş bak karanlık sokaklara

Vuruyor güneşin kızıl rengi işildayan taşlara

Gidiyor ağır ağır yanlız adam

Başka karanlık sokaklara..', 'Dolaştım durdum gecenin karanlığında Ümit aradım sokak lambalarında Ağladım durdum karanlık sokaklarda Seni aradım durdum ıslak kaldırımlard...', ARRAY['Türk Edebiyatı','Şiir','Hazar Can']::text[], 8.5, '{"poet":"Hazar Can","poet_slug":"hazar-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanliz-adam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile Rüzgarı', 'cile-ruzgari-hazar-can-yp80t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimdeki hasretin yakıyor bedenimi

Kızgın taşlar misali kevrulmuşum ben

Kimseler bilmez senden başka derdimi

Çile rüzgarında savrulmuşum ben..

Düşmüşüm düşkünüm muhtacım sana

Aşkını dilenen dilenciyim ben

Yıkılmış umutlarım baksam hangi yana

Anlayan yok halimi çaresizim ben.

Tutunacak bir dalım kalmadı artık

Yıkılmış bir viraneyim ben

Üstüne basılan toprak misali 

Savrulup yok olmuşum ben...', 'İçimdeki hasretin yakıyor bedenimi Kızgın taşlar misali kevrulmuşum ben Kimseler bilmez senden başka derdimi Çile rüzgarında savrulmuşum ben...', ARRAY['Türk Edebiyatı','Şiir','Hazar Can']::text[], 8.5, '{"poet":"Hazar Can","poet_slug":"hazar-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cile-ruzgari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeye Kıyamadığım', 'sevmeye-kiyamadigim-orhan-tuncay-j7bx6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Maviyi damıttım gözlerinden

Berrak denizlerin derinliğiydi geride kalan.

Salkımlar topladım sarı saçlarından.

Ekin tarlalarını gördüm rüzgarda salınan.

Resmettim hilali boyayla siyaha

İki adedini serptim gül yanak üstü

İndirdim mehtabı hüzünlü geceden

Düşündüm, yoksa ay yüzlüm küs mü? 

Güzel nazlı olur derdi bilenler

Gülücükler nakşettim ben yine de

Nazik yanak sararıp solmasın

Hüzne dalmasın, bu hüzünlü gecede.

Bal  damlası damlattım çiçek özlerinden

Meyvelerle donattım solgun dudağını

Baharın ılık meltemiyle uçurup  can kattım

İpekten öpücükle ördüm ruhunu saran kaftanını.

Özlemimle doyurdum doyumsuz ruhunu

Onu derin kuyularımda saklayıp korudum

Dört mevsim dudaklarda fısıldanacak olan

Buğulu adını, raks eden mısralarımda yoğurdum.', 'Maviyi damıttım gözlerinden Berrak denizlerin derinliğiydi geride kalan. Salkımlar topladım sarı saçlarından. Ekin tarlalarını gördüm rüzgar...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevmeye-kiyamadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gap turu esintileri', 'gap-turu-esintileri-fahrettin-selcik-n8guu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fahrettin anıları yaz günü gününe,

Güvenme yaşlanmış,okside beynine,

Bu gün(27.5.004)   Basmahaneden tanıdığım Mardin e

Gezildi  bir medrese,birde Zaferan kilise.

Yapıldı orada çarşı alışverişi,

Bayanlar çok sevdi gümüşlü işi,

Rekorla bitirdi Ali bey ve eşi,

Nesrine sordum bekliyordu finişi,

Ben de aldım ufak tefek dört parça,

Paketleri açmadan   Nesrin attı bir fırça,

Ne  zamanki kutular masaya açıldı

Gözlerinde mutlu ifade saçıldı.

Akşam yemeğinde istendi takı ile defile,

Bu  öneri tutmadı,uğraşmak nafile,

Akşam yemeğinde terasta müzik eğlence vardı,

Bizim Fatoş ve ekip oyun alanındaydı,

Bir yanımız Sivas lı mimarlardı,

Sanki sandalyeye mıhlanmışlardı,

Lobut bacaklı şantöz ile şantör programdaydı,

Sivaslıları kimse uyarıp canlandıramadı.

Fahrettin Selçik   27.5.2004  Mardin', 'Fahrettin anıları yaz günü gününe, Güvenme yaşlanmış,okside beynine, Bu gün(27.5.004)   Basmahaneden tanıdığım Mardin e Gezildi  bir medrese...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gap-turu-esintileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-i-smail-sahin-qx788', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Burası son geçittir

Sonu ölüme gider

(Şimdi geride ne''n var)

Döneceksen dön git

Yaşayabilirsen eğer

Yaşamanı isterim dee..! 

Aşk gibi sevgi de yoktur

İnsanı hep ihtiyacı çeker

(Ettin mi edildin mi bir yar)

Ama isterden sen de yit

Kendini kandırabilirsen eğer', 'Burası son geçittir Sonu ölüme gider (Şimdi geride ne''n var) Döneceksen dön git Yaşayabilirsen eğer Yaşamanı isterim dee..!  Aşk gibi sevgi ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/son-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebegim´e', 'bebegim-e-fulya-celikbilek-f7n5z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '......beni 

alıp götürüyorsun martıların ardından

geride ise yalnızlık kalan......

kıyamam sana

gecenin yalnızığında 

hanımelleri dallarına  küskünlüğüm

kayalara vurmuş 

martı gagasında sabahlar 

güneşe doğru yol aldılar   

ufkun cizgisinde sen vardın

çiy bahçelerinde

yaşanan aşklar mahküm

gökkuşağı kördüğüm olmuş

hapsedilmiş renklerde

güller dikenleriyle başbaşa

çaybahçesindeki güvercinler kadar yalnız

Yüregime kelepçe olmuş

agop un ellerinde 

hüzünlerle işlenmiş 

nadide yüzük

kürtaj gecelerde

ellerimi uzattım

tut verme geri

sakla ucuz şarap gibi

gözlerinde 

sev beni

s e v m e y i  b i l e m e d i ğ i m yerde

Kızım  Aylin   için

10.Haziran 20004', '......beni  alıp götürüyorsun martıların ardından geride ise yalnızlık kalan...... kıyamam sana gecenin yalnızığında  hanımelleri dallarına ...', ARRAY['Türk Edebiyatı','Şiir','Fulya Çelikbilek']::text[], 8.5, '{"poet":"Fulya Çelikbilek","poet_slug":"fulya-celikbilek","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bebegim-e-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmeyeceksin!', 'bilmeyeceksin-emre-ozoran-11vd4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tozların arasından kıvranarak çıktığım gün sana bakıp ağlayacağım.

Kavgalar silinmiş olacak yüreğinden,

Göreceğin gözlerimden damlayan yaşlar olacak.

Sarılacak mısın bilemem.

Ben sürekli ağlayacağım.

Öyle bir yerde ki büyü,

Rayların üzerindeki ışıltı gibi parıldıyor içimde

Yalanlanmamış bir gerçek mutluluk

Sende.

İnanmayacaksın kızaracak gözlerime, akacak burnuma.

İlk defa gördüğün için değil,

Son defa göreceğin için.

Senin için ağladığımı hiç bilmeyeceksin.

Karaltılar sakinleşir deniz kenarlarında,

Kumsalda oynaşırlar gece boyu.

Orada benimle sevişmeyeceksin.

Hiç bilmeyeceksin yaşadığımı,

Gözlerin beni hiç görmeyecek

Yaşlar süzülecek yanaklarımdan,

Silmeyeceksin.

Resmine bakıp ağladığımı bilmeyeceksin.', 'Tozların arasından kıvranarak çıktığım gün sana bakıp ağlayacağım. Kavgalar silinmiş olacak yüreğinden, Göreceğin gözlerimden damlayan yaşla...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bilmeyeceksin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-emre-ozoran-m42p8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Salınırken rüzgar beni hatırla.

Ufuktan yana bakarken.

Önündeki sokak lambasının yeşil direğine çarpmadan az önce..

Yerdeki su birikintisinden çamurlu su vücuduna yayılmadan.

Aşk acısı çekiyorsun, uzakta sevdiğin.

Tam önünde bir teyze, pazar çantasını sürüklüyor.

Alt geçitten geçerken kaldırım daralıyor.

Sen dahil kimse yol vermiyor.

Üzülme.

Sen de yaşayacaksın!', 'Salınırken rüzgar beni hatırla. Ufuktan yana bakarken. Önündeki sokak lambasının yeşil direğine çarpmadan az önce.. Yerdeki su birikintisind...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ozlem-167-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ArkadaŞlıK', 'arkadaslik-emre-ozoran-47ubn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sözlerin canımı acıttı bugün.

Arkadaşlığa inanıp ağlıyorken uyandım.

Tutmadın düşerken.', 'Sözlerin canımı acıttı bugün. Arkadaşlığa inanıp ağlıyorken uyandım. Tutmadın düşerken....', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/arkadaslik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavşak', 'kavsak-emre-ozoran-ga4wd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yollar mı bizden uzaklaştı biz mi yollardan uzaklaştık

kaygı ne zaman durdurdu gözlerimizi

gerçekten bakıştık mı

kulağıma beni sevdiğini hiç fısıldadın mı', 'yollar mı bizden uzaklaştı biz mi yollardan uzaklaştık kaygı ne zaman durdurdu gözlerimizi gerçekten bakıştık mı kulağıma beni sevdiğini hiç...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kavsak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'La Femme', 'la-femme-emre-ozoran-mgx0l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ve duman içini sarar kömürü yüzüne vuran gecede

Yağmurun ıslaklığı serinletir belki yanaklarındaki kırmızı sevinci

Işıklar lacivertin içinde birer sis bulutu

Lacivert dalgalanıyor deniz gibi

Hem karanlık, hem deniz, hem su, hem kaldırımdır lacivert.

Yerden seker mutluluk lacivertte

Ruhunu ezen bir rüzgar eser hissedersen

Bir kayık göreceksin

''Çıkıyor kayık iniyor kayık''

Laciverte bürünüyor kayık

Dalgalı saçı esmer bir fransız kadın siyah kadifeden yuvarlak şapkasının altında gülümseyecek.

O, kayığı hiç görmeyecek, laciverti de bilmeyecek.

Karşılıklı kadeh kaldıracaksınız kırmızı şaraba

Tozlu tahta masadan sekecek şarap damlaları,

Yapışkan bir alkol tortusu bırakacak.

Beraber yürüyeceksiniz.

Yol uzun.

Kusuruzca fransızca konuştuğunu farkedeceksin.

Siyah kadife şapkanı elleyeceksin.

Dalgalı saçların uçuşacak.

İstanbul’da yalnız bir Fransız kadın olduğunu anlayıp üzüleceksin.', 'Ve duman içini sarar kömürü yüzüne vuran gecede Yağmurun ıslaklığı serinletir belki yanaklarındaki kırmızı sevinci Işıklar lacivertin içinde...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/la-femme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyor Seni Çocuk!', 'ozluyor-seni-cocuk-ozkan-yildirim-81nmy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerini aç uykulardan, 

Sıyrılarak karanlıklardan

Işık ile yürüyor çocuk.

Karanlığın ağırlaştığı yerden,

Akkorlar bırakarak alaz`dan

Işığıyla koşuyor  çocuk.

Özlemler ıçınde yanıp,

Rüzgârlarla  yollara düşüp

Çekip gidiyor çocuk.

Kendi kullerinden alevlenip,

Bir çığ gibi büyüyüp,

Aşk`a düşüyor çocuk.

Gözlerinin aydınlığında,

Sevdasının sıcaklığında 

Özlüyor seni çocuk.', 'Gözlerini aç uykulardan,  Sıyrılarak karanlıklardan Işık ile yürüyor çocuk. Karanlığın ağırlaştığı yerden, Akkorlar bırakarak alaz`dan Işığı...', ARRAY['Türk Edebiyatı','Şiir','Özkan Yıldırım']::text[], 8.5, '{"poet":"Özkan Yıldırım","poet_slug":"ozkan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ozluyor-seni-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokun Bana', 'dokun-bana-emre-ozoran-urm6j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her dokunuş yeni bir başlangıçsa

Dokun bana.

Bir gece yarısı kadıköy rıhtımında tut elimi

Umarsızca yürüyelim

Bilmeyelim vaktin geceyarısı olduğunu

Haydarpaşa’dan kalkan umutlara karşı sevişelim

Raylarla uzansın gözler', 'Her dokunuş yeni bir başlangıçsa Dokun bana. Bir gece yarısı kadıköy rıhtımında tut elimi Umarsızca yürüyelim Bilmeyelim vaktin geceyarısı o...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dokun-bana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Halleri', 'askin-halleri-emre-ozoran-v0sy4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tuğlaların arasından sevmelisin beni 

Elin harca bulanmalı toz toprağın arasında

Dilinde terkediş bir türkü olmalı

Yanık yanık söylemelisin istediğinde

''Sen beni hiç sevmedin! ”

Yalan değildi sözlerin

Ellerin bu günahı işledi

Mermerden bir heykel saygısızlık,

Biz yonttuk hatırla burnunu.

Bir sen kırdın bir ben,

Bir sen bir de ben parçaladık ruhunu gölgenin.

Salıverdik kederleri.

Dalınır mı geceye düşünceden geçer gibi,

Sözler gözlerden çok yalan söyler mi? 

Şişenin mantarı dostumdur benim,

Tadarız zevki ama kavuşulmazlıktır aşkımız.

Kırmızılığa vurgunuz, kandır o, nefestir ağır ağır.

Üstüme örtüdür, sıcaklık insanı terletirken.

Sen hiç günah işlemedin mi? 

Hiç öpüşmedin mi sevmeden? 

Yalan da mı söylemedin? 

Yanlış vücutlara el sürmedin mi? 

Günahların seni kovalayacak

Kanatıncaya kadar...', 'Tuğlaların arasından sevmelisin beni  Elin harca bulanmalı toz toprağın arasında Dilinde terkediş bir türkü olmalı Yanık yanık söylemelisin ...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/askin-halleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadıköy, Beklemek', 'kadikoy-beklemek-emre-ozoran-c06ge', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haldun Taner’in önünde kalbim çarpıyor

“Gözlerimi kaparım, vazifemi yaparım.”

Bekliyorum

Gelişini görmemişim, çoktan geçip gitmişsin

Tanımıyorsun

Yoluna çıkıyorum

Susam taneleri saçmışım paltoma

Simit mi yedim? 

Yine geçtin farketmeden

Yarın beni sevecek misin?', 'Haldun Taner’in önünde kalbim çarpıyor “Gözlerimi kaparım, vazifemi yaparım.” Bekliyorum Gelişini görmemişim, çoktan geçip gitmişsin Tanımıy...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kadikoy-beklemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-emre-ozoran-x8iro', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uyurken yollar geçecek aklından hızlı hızlı...

Kanma, yollar yalan söylerler.

Kaldırım taşları hiç üzülmez...', 'Uyurken yollar geçecek aklından hızlı hızlı... Kanma, yollar yalan söylerler. Kaldırım taşları hiç üzülmez......', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yol-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-emre-ozoran-oizyq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İç sıkıntı artarken,

Gözlerin

Soğuğun içinde kor.

İlk kez karşılaşıyorum

Yüzümde kaygıyla.

Sen şaşkınsın.

Rüzgarın uğultusunda küçük damlalar

Saklı.

Senin içinde gizli var mı? 

Hiç anlatacak mısın?', 'İç sıkıntı artarken, Gözlerin Soğuğun içinde kor. İlk kez karşılaşıyorum Yüzümde kaygıyla. Sen şaşkınsın. Rüzgarın uğultusunda küçük damlala...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozlerin-107-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hareket Saati', 'hareket-saati-emre-ozoran-rv4ds', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaçırma treni sevdalara kalkarken,

Pencereden el sallayanlara bakma hiç,

Ayakkabılarına bak, ıslanmasın uçları

Aşk çarpsın vücuduna

Onun da gözleri ayaklarında olsun

Dokunmayı özler ellerin

Çarşafı okşarlarken,

Öpüşmeyi istersin yastık kılıfı dudaklarının mahremiyetini bozarken

Ulu orta sarılsan bir geceye

Gece bile bilmese aşık olduğunu

Şafak vakti kadar eskidir ruhundaki yara

Karlar üstündeki kızak gibi çizse ruhunu gündüze

Uyanışa

Sefil oluşa

Yalnızlığa', 'Kaçırma treni sevdalara kalkarken, Pencereden el sallayanlara bakma hiç, Ayakkabılarına bak, ıslanmasın uçları Aşk çarpsın vücuduna Onun da ...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hareket-saati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Törpülüyor Maksadları', 'zaman-torpuluyor-maksadlari-ahmet-aksoy-tyb1c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'akarken şelaleye doğru

zaman törpülüyor maksadları

bir kütüğe tutunmuş gidiyoruz

boylayana kadar suyun dibini

bir ülküdür tutturmuşuz

varolmak saki ona bağlı

kimimiz para kimimiz siyaset

kimimiz aşk kimimiz ideal

oysa ölüm yakın dostlar

hiç olmadığı kadar

bizi ne kurtarır fani dünyadan

boş boş yüzüyoruz', 'akarken şelaleye doğru zaman törpülüyor maksadları bir kütüğe tutunmuş gidiyoruz boylayana kadar suyun dibini bir ülküdür tutturmuşuz varolm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zaman-torpuluyor-maksadlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelinlik', 'gelinlik-reyhan-sur-tpeuj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir tıkırtı alacakaranlıkta

dinliyorum..

yüreğim

yüreğemde sen

bir avuç özlem alıyorum

en acısından

bastırıyorum göğsüme..

yanıyorum

dinmiyor tıkırtılar

aralıyorum kirpiklerimi

yamaçlarında nem

ıslanmış hem başımı gömdüğüm yastığım

boğuluyorum ilmeklerden

yağmur

cama vuruyor inceden

bulgur bulgur ter içinde pencerem

kalkıp camı açıyorum

toprak kokusu..

senin kokun

getirdiklerinde seni

ben sana hasretken

bir avuç toprak

ve çiçekler vardı üzerinde

tomurcuğa durdu hepsi

nasıl özledim bilsen

koşmak istiyorum

düğünümü görememiştin ya

işte gelinliğim hazır annem

gör istedim

hazır gelmişken', 'bir tıkırtı alacakaranlıkta dinliyorum.. yüreğim yüreğemde sen bir avuç özlem alıyorum en acısından bastırıyorum göğsüme.. yanıyorum dinmiyo...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gelinlik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümün beyaz sayfası', 'omrumun-beyaz-sayfasi-yusuf-koc-2ij6r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşam güzel ama beyaz sayfalar çabuk kararıyor...

                                 ve o zaman...

Ne zaman bir beyaz sayfa açsam ömrüme,

kara bulutlar yağmur getiriyor..

ne zaman bir sevda düşse gönlüme,

salyalı ağızlardan uğursuz sesler yükseliyor..! 

Ne zaman bir şans yakalasam sevgi adına,

taş duvarlarda buluyorum kendimi..

ne zaman yönelsem Tanrı katına,

yıkıyorlar barajımı bendimi...! 

Sözlerim duyulmuyor ne zaman haykırsam,

kalabalığa karışıyor sedalarım..

ve ne zaman gönlümce bir sevdaya kapılsam,

artık yarar getirmiyor dualarım..! 

Ve artık ne zaman ölümü düşünsem,

korkmuyorum onun soğuk yüzünden..

nasılsa bu can bir gün çıkacak bedenden,

ne sevdadan iz kalacak ne de benden..! 

Ne zaman bir beyaz sayfa açsam ömrümde,

                        seni,

                               beni,

                                      ve ölümü düşünüyorum.! !', 'Yaşam güzel ama beyaz sayfalar çabuk kararıyor...                                  ve o zaman... Ne zaman bir beyaz sayfa açsam ömrüme, kara...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/omrumun-beyaz-sayfasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harran', 'harran-fahrettin-selcik-xrv33', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'H A R R A N

Bu gün gezimiz Harran,

Üniversitesi yıkılmış,viran,

Kalan sadece rasat kulesi,

İş Moğolların halt etmesi.

Tekrarı Emevi lerce yapılmış,

Burada Araplar yaşamış,

Sıcağına ancak onlar dayanmış,

Evlerin tepesi koni ondanmış.

Fahro adında zaro ağa varmış,

Dokuz cariye 36 veledi ile yaşamış,

Nufus ondan dolayı kalabalık,

Dileriz olur burası Türkiye ye anbarlık.

Yerlisi kapkara sanırsınız zenci,

Olmuşlar avuç açan dilenci,

İstiyorlar ağzına hazır hap,

Nede olsa soyu tembel Arap.

Fahrettin Selçik 26.5.004  Harran', 'H A R R A N Bu gün gezimiz Harran, Üniversitesi yıkılmış,viran, Kalan sadece rasat kulesi, İş Moğolların halt etmesi. Tekrarı Emevi lerce ya...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/harran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karaköy Kadıköy Arası', 'karakoy-kadikoy-arasi-nurten-altinok-yovf4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karaköy-Kadıköy Arası

Karaköy-Kadıköy arası 

İstanbul Vapuru 

Bir var/mış bir yok/muş şimdi 

Bir adın vardı / senle bütün 

Desem

Dağlanır dilim 

Bir de aha bu can 

Kördüğüm 

Sana sevdalı 

Bir var bir yok / o zamanlar

Çok mu gençtik ne 

Çok mu eskidik şimdi

Karaköy-Kadıköy arası 

İki yakayı bir araya getiren(!) 

İstanbul Vapuru

Bin kez ölüyordum / yüreğimde vurgunlar

Ya yoksan iskelede! 

Bir kez uçuyordum / mesafesiz 

Ne bitmez bir yoldu bu

Bu ne işkence iş

Bir adın vardı 

Desem 

Keserler beni 

Demesem 

Bu dert  bitirir beni 

Çok sevmiştim seni 

Sevdayı ezberlettim martılara, susam susam

Her duaya, âmin’i 

/ Ki dualarımdın

Ve de sevdam 

Ve de sevdiğim 

Dinle şimdi; 

Dalgalar adın adın konuşuyor 

Rüzgâr sen sen 

Kokunu taşıyor

Karaköy - Kadıköy arası 

İstanbul Vapuru 

Çarp üçle parmaklarını 

Sonra ekle bizi 

Bunca yıl özlem

Bunca yıl sır 

Ne çok sevmiştim seni 

Çok mu gençtim ne 

Çok mu eskidim şimdi

Adını unuttum desem

İnanma

Yüzünü 

İnan 

Karaköy-Kadıköy arası 

İstanbul Vapuru 

Bir var/mış bir yok/muş şimdi

Evvel zaman içinde

Başlar bütün masallar

İntiharı yok duyguların

Gerçek olan bu

Bir de ölüm! 

Nurten Altinok

13.06.04



211006', 'Karaköy-Kadıköy Arası Karaköy-Kadıköy arası  İstanbul Vapuru  Bir var/mış bir yok/muş şimdi  Bir adın vardı / senle bütün  Desem Dağlanır di...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/karakoy-kadikoy-arasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıplak Gülüşler', 'ciplak-gulusler-ali-ceyhan-yechp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yersizdir dövünmelerim

Ve çıplaktır gülüşlerim

Kaç zamandır terkedilişlerim

Bir gam bırakmadı seyyah gönlümde

Ne dakikalar bilirim ömrün içinde

Sarılsam gırtlağına alsam aklımın canını

Katlayıp kaldırsam ömrü hayattan

Sürsem keşkeleri doludizgin kaf dağının inlerine

Naralar, kahkahalar salıverilmiş sokaklara

Bir çocuk en güzel kahkahasını atıyor  ömrün

Anne bir el at, uzat gölgeni üzerime

Bak üşüyorum, beynime üşüşüyor örümcek düşler

Ayaklarımın altından kayıp gidiyor toprak', 'Yersizdir dövünmelerim Ve çıplaktır gülüşlerim Kaç zamandır terkedilişlerim Bir gam bırakmadı seyyah gönlümde Ne dakikalar bilirim ömrün içi...', ARRAY['Türk Edebiyatı','Şiir','Ali Ceyhan']::text[], 8.5, '{"poet":"Ali Ceyhan","poet_slug":"ali-ceyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ciplak-gulusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek S e n', 'bir-tek-s-e-n-baykal-kaanalp-r19bl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir tek sen varsın

görüp de söyleyemediğim

umut ışığım söndüğünde

yeniden yakamadığım

gel dediğinde gelmediysem eğer

bunu benim cahilliğime ver

bir tek sen varsın

görmeden aşık olduğum

ulaşmak istediğim mutluluğu

yeniden yakalayamadığım

gel dediğinde gelmediysem eğer

bunu benim cahilliğime ver

bir tek sen varsın

sevip de okşayamadığım

adını yüreğime kazıyıp

şarkılarıma yazamadığım

gel dediğinde gelmediysem eğer

bunu benim cahilliğime ver', 'bir tek sen varsın görüp de söyleyemediğim umut ışığım söndüğünde yeniden yakamadığım gel dediğinde gelmediysem eğer bunu benim cahilliğime ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-tek-s-e-n-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir yıkılmaz saçlarına', 'sehir-yikilmaz-saclarina-zafer-zengin-etnika-a0afx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birazdan sen de anlarsın

Nasıl yanarmış meydanlar

Şehir konar yüzüne

Yalnızlık düşer peşine

Birazdan sen de anlarsın

Kim düşünür seni gece

Bak işte birazdan

Korkulan teklik

Düşer peşine

Kim düşünür seni

Öğreneceksin bu gece

Sehir  düşmeyecek gözlerine

Ellerim dokunacak kirpiğine

Sancı dizerler kaşlarıma

Ağrımı saklarım aynalara

Yüzümde gülücük

Sen geldikçe aklıma

İzin vermem

Sehir yıkılmaz saçlarına

Dokunmazsam sevdana

Birazdan anlarsın işte

Yüzüm neden gülüyormuş

Göreceksin sende

/Sevilen çocuk ellerin/Hep gülüm /ser

3 Haziran 2004 '' Ellerin gül rengi ''', 'Birazdan sen de anlarsın Nasıl yanarmış meydanlar Şehir konar yüzüne Yalnızlık düşer peşine Birazdan sen de anlarsın Kim düşünür seni gece B...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sehir-yikilmaz-saclarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmek Güzel', 'bilmek-guzel-baykal-kaanalp-w40r2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaşadığını bilmek güzel

kalplerde gönüllerde

sevildiğini bilmek güzel

günlerde gecelerde

aşıksam ben aşığım

hem sana hem yaradana

yazıldığını bilmek güzel

kitaplara sayfalara

görülmemiş senin huyun

söylüyorum beni duyun

içildiğini bilmek güzel 

iki gözden akan suyun

dünyalar tatlısı gözün

sağlam kalıptan özün

dinlendiğini bilmek güzel

söylediğin her sözün', 'yaşadığını bilmek güzel kalplerde gönüllerde sevildiğini bilmek güzel günlerde gecelerde aşıksam ben aşığım hem sana hem yaradana yazıldığın...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilmek-guzel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir dakika önce senleydim', 'bir-dakika-once-senleydim-muhsin-aktas-x7zwv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senle ayrılığımızdan                                                                

Çok zaman geçmedi

Ayrılık acısı saniyeler önceydi

Açan bahar çiçeklerinde

Yağmur sonrası buram buram kokan toprakta 

Esen imbat rüzgarlarında

Sararıp dökülen yaprakta

Çıplak kalan ağaçta

Toprağı örten bembeyaz karda

Hep senleydim

Ben sensizlik acısı çekmedim

Senle ayrılalı çok zaman geçmedi

Ben daha

Bir dakika önce senleydim', 'Senle ayrılığımızdan                                                                 Çok zaman geçmedi Ayrılık acısı saniyeler önceydi Açan ...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-dakika-once-senleydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaşık Bakışlar', 'sarmasik-bakislar-ali-ceyhan-r5s90', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kekeçliğe soyunuyor dilim

Kavgalardan çıkmış cılız bedenim

Dizginleniyor binlerce el tarafından

Yüreği ellerinde rana duruyor karşımda

Sarmaşık bakışlarında düşüyorum doğurgan boşluğa

Don tutuyor zaman, doğum sancıyla sahneleniyor

Dağılıyor rutin akışlı rikuş yaşam

Kurulu bomba gibi telaşlı yüreğim

İçimde dalga dalga  büyüyen o...

Uzansam şöyle bir dokunabilirmiyim

Gerçekmidir masallarda anlatılan aşklar', 'Kekeçliğe soyunuyor dilim Kavgalardan çıkmış cılız bedenim Dizginleniyor binlerce el tarafından Yüreği ellerinde rana duruyor karşımda Sarma...', ARRAY['Türk Edebiyatı','Şiir','Ali Ceyhan']::text[], 8.5, '{"poet":"Ali Ceyhan","poet_slug":"ali-ceyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sarmasik-bakislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Yüklü Bir Bulut', 'yagmur-yuklu-bir-bulut-baykal-kaanalp-vl9fq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yağmur yüklü bir bulutum

gökyüzünde dolaşırım

tüm gökyüzü benim değil ama

ıslatmak istediğim yerler senin 

yağmur yüklü bir bulutum

giderim dönülmezlere

tüm dünya benim değil ama

ıslanmak istediğim denizler senin

yağmur yüklü bir bulutum

gelirim gittiğim cennetten

tüm dönüşler bana değil ama

ıslanmasını istediğim gidişler senin', 'yağmur yüklü bir bulutum gökyüzünde dolaşırım tüm gökyüzü benim değil ama ıslatmak istediğim yerler senin  yağmur yüklü bir bulutum giderim ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagmur-yuklu-bir-bulut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekirdek Mısralar', 'cekirdek-misralar-ali-ceyhan-s7qii', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hüner Yok

Yüzlerde maske var, maske var yüzlerde

Maskede hüner yok, hüner insan olabilmekte 

Kulak Ver

Bilmez misin hayat kelebek mevsimi sarhoşluğunda

Atılan her adım son''a biraz daha yakınlaşma

Şekil

   

Telaş içerisinde geçip gidiyor yıllar

Her yıl yeniden kabuk değiştiriyor umutlar

Talan

Baharında soluyor güller dalında

Bahçelerde talan var bahçeler ablukada     

Kara Kutu

Doğrultusunda ilerlerken zaman

Tanıklık eder

Savaşlara, kargaşalara, darbelere

Umursamazdır hükmettiğinden

Başlangıç ve varış ondadır

Kara kutusudur insanlığın

Kalabalıklar

Boşlukları işgal eden kalabalıklar

Kalabalıkların oluşturduğu boşluklar

Zamanı geçirmekle yaşarım sanırlar

Yaşantı buğulanmıyorsa hayatın

İster nefes al, ister ver ne fark eder', 'Hüner Yok Yüzlerde maske var, maske var yüzlerde Maskede hüner yok, hüner insan olabilmekte  Kulak Ver Bilmez misin hayat kelebek mevsimi sa...', ARRAY['Türk Edebiyatı','Şiir','Ali Ceyhan']::text[], 8.5, '{"poet":"Ali Ceyhan","poet_slug":"ali-ceyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cekirdek-misralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Haber', 'bi-haber-ali-ceyhan-3usab', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bİ HABER 

İçsel yıkıntılar

Dilsiz, patırtısız

Bir hayel var

Şimdi bedensiz

Dudaklar birleşir

Zil zurna ellerimiz

Geceye uzanan eller

Tuzla buz

Uzadıkça yıllar

Ümitler takatsiz

Yaşantıdan bi haber

Kalmışız kimsesiz', 'Bİ HABER  İçsel yıkıntılar Dilsiz, patırtısız Bir hayel var Şimdi bedensiz Dudaklar birleşir Zil zurna ellerimiz Geceye uzanan eller Tuzla b...', ARRAY['Türk Edebiyatı','Şiir','Ali Ceyhan']::text[], 8.5, '{"poet":"Ali Ceyhan","poet_slug":"ali-ceyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bi-haber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maki', 'maki-baykal-kaanalp-2zqe8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hiç baharı beklemek

zorunda kalmayışına

hayranım makilerin', 'hiç baharı beklemek zorunda kalmayışına hayranım makilerin...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/maki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımadığım Şehirdin', 'tanimadigim-sehirdin-ali-ceyhan-wekkl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanımadığım Şehirdin

 

Zincirleme karmaşa tutumların

Çözülmezliğe büründürdü seni

Tanımadığım şehirdin

Sokaklarında kendimi yitirdiğim

Kendimi buldurmak için 

Tuttuğum dedektifleri

Hep şaşırttı kadın kurnazlığı

Adım bir o kadar yabancı şimdi

Gülüşlerim palyaço ruhlu serseri

Nur yüzlü kadın ''annenim'' diyor

Bu kelime tanıdık geliyor bir yerden 

Lakin hatırlamıyorum hiç kimsemi

Aklım sensin, yaşam denilen şeysin

Kandıramaz kimse beni

Ben senim gör(ün)  beni

Esirgeme aklımı bozduğum sevgini', 'Tanımadığım Şehirdin   Zincirleme karmaşa tutumların Çözülmezliğe büründürdü seni Tanımadığım şehirdin Sokaklarında kendimi yitirdiğim Kendi...', ARRAY['Türk Edebiyatı','Şiir','Ali Ceyhan']::text[], 8.5, '{"poet":"Ali Ceyhan","poet_slug":"ali-ceyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tanimadigim-sehirdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur olmak', 'yagmur-olmak-muhsin-aktas-e2tfy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece 

Yağmur yüklü bulutlar gibiyim

Yağmak

Puslu yürekleri yıkamak istiyorum

Sen yağmurdan kaçarken

Ben saçlarından damlamak

Kipriklerinden akmak istiyorum

Tenine geçercesine ıslatmak

Yavaşça ayaklarından akıp

Toprağın kucaklayan kollarına 

Kendimi bırakmak istiyorum

Her zaman sana

Camına kapına

Yürüdüğün sokağa yağmak

Sonsuzluk damlalarımla

Ayaklarının altında

Akmak istiyorum', 'Bu gece  Yağmur yüklü bulutlar gibiyim Yağmak Puslu yürekleri yıkamak istiyorum Sen yağmurdan kaçarken Ben saçlarından damlamak Kipriklerind...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yagmur-olmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırılçıplak Hayata', 'cirilciplak-hayata-ali-ceyhan-5lmwv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çırılçıplak Hayata

  

3747''e 

Boş bakıyorum boşluğuna 

Yalvaran dilsiz gözlerle 

Hoş yaşam sürüyor ama 

Yokluğunla çoktan 

Yaşam durdu bende 

Sevdiğim onca şeyden 

Koptum vuslatsız 

Sabah altı çayı yalnızlık tadında 

Sigara dumanları uzanıyor anılara 

Avuçlarımdaki nemli gözlerimi

Azad ediyorum anlamlardan 

Boş baksın diye 

Çırılçıplak hayata', 'Çırılçıplak Hayata    3747''e  Boş bakıyorum boşluğuna  Yalvaran dilsiz gözlerle  Hoş yaşam sürüyor ama  Yokluğunla çoktan  Yaşam durdu bende...', ARRAY['Türk Edebiyatı','Şiir','Ali Ceyhan']::text[], 8.5, '{"poet":"Ali Ceyhan","poet_slug":"ali-ceyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cirilciplak-hayata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük - 5', 'dortluk-5-ozkan-yildirim-vmfvf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geldim işte, uzaklardan,

Kar aydınlığında demlendim.

Çığ düşmüş ayrılıklardan,

Bahar yureğine geldim.', 'Geldim işte, uzaklardan, Kar aydınlığında demlendim. Çığ düşmüş ayrılıklardan, Bahar yureğine geldim....', ARRAY['Türk Edebiyatı','Şiir','Özkan Yıldırım']::text[], 8.5, '{"poet":"Özkan Yıldırım","poet_slug":"ozkan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-5-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük - 4', 'dortluk-4-ozkan-yildirim-s32dp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün mevsimler,

Beyaz mevsim olsa da

Mavi düşlerimle,

Düşer yollara gelirim.', 'Bütün mevsimler, Beyaz mevsim olsa da Mavi düşlerimle, Düşer yollara gelirim....', ARRAY['Türk Edebiyatı','Şiir','Özkan Yıldırım']::text[], 8.5, '{"poet":"Özkan Yıldırım","poet_slug":"ozkan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-4-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük - 3', 'dortluk-3-ozkan-yildirim-ox74z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hep o  sevdalı çocuk ile birlikteyim

‘acıyı bal – sıratı yol’eyleyenim.

Siyah – beyaz hayatı renk`leyenim.

Renkli hülyalarla gelirim.', 'Hep o  sevdalı çocuk ile birlikteyim ‘acıyı bal – sıratı yol’eyleyenim. Siyah – beyaz hayatı renk`leyenim. Renkli hülyalarla gelirim....', ARRAY['Türk Edebiyatı','Şiir','Özkan Yıldırım']::text[], 8.5, '{"poet":"Özkan Yıldırım","poet_slug":"ozkan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-3-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük - 2', 'dortluk-2-ozkan-yildirim-chiyb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdalım, sebebi ömrümün

Aç penceresini gönlünün.

Islığıyla dolsun rüzgârım:

Issızlığına yoldaş yüreğim.', 'Sevdalım, sebebi ömrümün Aç penceresini gönlünün. Islığıyla dolsun rüzgârım: Issızlığına yoldaş yüreğim....', ARRAY['Türk Edebiyatı','Şiir','Özkan Yıldırım']::text[], 8.5, '{"poet":"Özkan Yıldırım","poet_slug":"ozkan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-2-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük - 1', 'dortluk-1-ozkan-yildirim-y3whv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendi külünden alevlenip

Sızlanmadan düşerdi yollara.

Ilık seher yel`leriyle,

Ateş taşırdı üşümüşlere.', 'Kendi külünden alevlenip Sızlanmadan düşerdi yollara. Ilık seher yel`leriyle, Ateş taşırdı üşümüşlere....', ARRAY['Türk Edebiyatı','Şiir','Özkan Yıldırım']::text[], 8.5, '{"poet":"Özkan Yıldırım","poet_slug":"ozkan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-1-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütünlemeye Kalmış Aşklar', 'butunlemeye-kalmis-asklar-ahab-ahab-1jp1q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk bir sınavsa eğer,

Ben bu sınavdan,

Bütünlemeye kalmaktan,

Sıkıldım artık......', 'Aşk bir sınavsa eğer, Ben bu sınavdan, Bütünlemeye kalmaktan, Sıkıldım artık.........', ARRAY['Türk Edebiyatı','Şiir','Ahab Ahab']::text[], 8.5, '{"poet":"Ahab Ahab","poet_slug":"ahab-ahab","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/butunlemeye-kalmis-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleme Gözyaşı', 'bekleme-gozyasi-gulay-yildiz-ahp4m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mesafelere sakladığın gidişinde

Aradım gözyaşlarıyla hüznün mührünü.

Vicdanı olmayan nefes alışların

Verişlerini sorguladım 

Nedensiz...

Gidiyorsun! 

Peşinden geliyor -

Bugüne dek sessizlik oynayan küfürlerim

Helal mi edilirmiş hak? 

Bilmem öyle adetleri....

Bilsem de hatırlamam adın gibi

Bekleme! 

Sızılarla beslenen bir bebek oldu kalbim

Bebeğimin adımı; 

Her bir sancı vurgunu.

Aramıyorum koltuğunda sıcaklığını

Ve

Anmıyorum o aşk hikayesinin şarkısını! 

Kuruyan gözyaşı pınarları benim abidem

En büyük sırdaşım yastığım ve yanlız gecem

(Haziran 2004)', 'Mesafelere sakladığın gidişinde Aradım gözyaşlarıyla hüznün mührünü. Vicdanı olmayan nefes alışların Verişlerini sorguladım  Nedensiz... Gid...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bekleme-gozyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*~*~*~*~* BATAN GüN *~*~*~*~*', 'batan-gun-baki-son-eps4f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yürüyorum...

Her adımda,

Biraz daha takatim tükeniyor.

Her aştığım tepeden

Kaçıyorsun...! 

Ümit

Biraz daha ümit veriyor

Bakışların...! 

Yürüyorum tepelere

Adım,adım

Son aydınlığa.! 

Her saniye,

Biraz daha azalıyor ışıklar.

Her aştığım tepeden

Kaçıyorsun...! 

Durmaksızın,

Soğuk rüzgarlar esiyor

Yağmur,sicim çöküyor üzerime.

Çağıran bir hırs var içimde

Yürüyorum tepelere,

Yürüyorum,solan son aydınlığa.

Peşimi bırakmıyor karanlık.

Biliyorum...

Kaplıyacak korkunç gece üstümü

Kalacağım başbaşa,

Yalnızlığımla...! 

Belki bir sabah dönmeyeceksin.

Yürüyorum,kaybetme korkusuyla

Her adımda

Biraz daha takatim tükeniyor.

Her aştığım tepeden

Kaçıyorsun...!', 'Yürüyorum... Her adımda, Biraz daha takatim tükeniyor. Her aştığım tepeden Kaçıyorsun...!  Ümit Biraz daha ümit veriyor Bakışların...!  Yürü...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/batan-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gül Alır Rengini Acılarımızdan...', 'bir-gul-alir-rengini-acilarimizdan-canan-ucer-whfcj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Onlar ki aydınlık üzre

Ecel toprağına

Umut ektiler.Ay dolandı vay deli gönlüm

Ölüm şaşırdı menzilini......Refik DURBAŞ

Kurtlar oturmuş 

ala geyik bakışlarına.

Gözlerine kan dolmuş,

bir yanım da sızım

ağlıyor.

Mübarek olsun....

Etrafımda nara sesleri

Kaça bölsem gecemi, kaça......

Hangi kurşunun önünde dursam da

daha az öldürür, beni gidişin...

Bir yanım da sensizlik

bir yanım da foseptiğin pisliği

umacılar sarmış dört bir yanımı..

Kime dönsem, kime baksam

kime söylesem kendimi

uzaklaşır, yabancılaşırım kendime...

Bu ben değilim

Mübarek olsun,......

Koğucular sarmış 

yardakçılar alkış tutar olmuş duvarlarımda..

Nereye gitsem, nereye baksam

özümdem bir iplik çekilir,

közümde hasretindir

Sığınabildiğim......

Ah sancım, 

gül kırmızılığına yanar olmuş,

bu iş hayra değil, 

Hangi gerçeği yaşadık ki 

Yanıldıkça, kendimize yabancılaştık

Kirli anılarımızı atarken çukurlara

Yine de teslim olmadık mı, 

o, bayağı ağrılarımıza

hangi sevdaları harcamadık ki......

Ahh, güneşte yeşile çalan ela gözlü 

yedi beneklim

mükemmelliğin bozulmadı mı

aynaya bakıp kendini severken.........

Hani ya....yoksa kimseciğin

nasıl sarılmazsın, 

ala geyik gözlerine........

Nasıl vurulmazsın, 

tekrar tekrar tekrar

Nasıl yaşarsın.....

Delibozuk, yolmaz mısın saçlarını

Nasıl gıpta etmezsin, 

Bir çocuk bakışındaki gülüşe...

Bak tuvalimden kanlar akıyor

Çalmasın türküler......

Tenim küstü, dilim sustu

Yüreğim ağlıyor........

Ve bir gün duruluverirse hasretin

hani o ten uyuduğunda.....

Bana bir şiir yaz......

Hastane koridorları, serum tüpleri

Ve bileklerinden kan damlayan kelimeler olmadan

şizofren ayrıntılara takılmadan.

Bir çocuğun gülüşünü yaz

Belki o vakit 

Yeniden doğabilirim

Bir gül alır rengini acılarımdan

Toprağımın üzerinde açar

Yan gelir yatar bedenim de

Devriliverir güneşin turuncu rengi

Yorgunluğuma......', 'Onlar ki aydınlık üzre Ecel toprağına Umut ektiler.Ay dolandı vay deli gönlüm Ölüm şaşırdı menzilini......Refik DURBAŞ Kurtlar oturmuş  ala ...', ARRAY['Türk Edebiyatı','Şiir','Canan Üçer']::text[], 8.5, '{"poet":"Canan Üçer","poet_slug":"canan-ucer","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/bir-gul-alir-rengini-acilarimizdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Vasiyeti', 'gece-vasiyeti-emre-ozoran-hngf9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece yazdım vasiyetimi, kimseye bırakmadım ruhumu; 

Islak çoraplarımla yanıma aldım.

Kadehin içinde kırmızı şarap dansediyor, istenmese de alıveriyor insanın aklını gece yavaş Yavaş.

Ayaklarım büzüşüyor, toprak soğuk

Alkolün tadı yok dudaklarımda

Ayaklarım büzüştükçe özlüyorum, şöminenin alevine sarılmış yanıyorum

Saçlarım tutuşuyor sanki

Hiç üzülmeden eriyorum.

Taksinin içinde kıpırdaşan sarı ışığa dalıyorum

Daha önce bu sarılıkta bir ışık gördüm mü? 

Ve hüzün taksimetrede her düşünceyle artıyor

Taksici bilmediğim bir dilde duymadığım sözleri büyük bir iştahla yiyor

Gözlerim yoruluyor yanaklarımdan.

İşte böyle ayaklarımı büzüştürdüğüm bir gecede yazdım vasiyetimi,

Gece vasiyeti

Sakladım herşeyimi herkesten

Ruhumu bırakmadım kimseye

Islak çoraplarımı özenle çıkardım

Katladım, büzüşen ayaklarımın yanına koydum sessiz

İlk defa sebebini bilmeden ağladım

Kendime yalan söyledim, son günlerde çok kolay başarıyordum,

Bir nefeslik hava çektim ciğerlerime, yandı ciğerlerim

İtiraf zamanı gelmişti

Kendimi, kendime mi anlatayım? 

Nasıl? 

Bak ayaklarım büzüşüyor? Yokluğun mu büzüştürüyor varlığın mı? 

Kulaklarım kaşınıyor.

Gece henüz yaşamıyor içimizde.

Biz kim miyiz? 

Ben.

Nasıl mı?', 'Gece yazdım vasiyetimi, kimseye bırakmadım ruhumu;  Islak çoraplarımla yanıma aldım. Kadehin içinde kırmızı şarap dansediyor, istenmese de a...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gece-vasiyeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tecavüz', 'tecavuz-emre-ozoran-a61y8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kardan kaplanmış asfalt, dağlar boyun bükmüş rüzgara

Hırçın kanatları yarmış geceyi

Sabaha kadar vızıldamış uğultular

Uguldatmış gözlerini

Haykırışlarla yanmış geceye

Çığlıkları sarmış karları sabaha karşı

Beyazlıkta kan gibi sabır

Ağır ağır dökülüyor

Bilmeden ilerliyor gözler

Saflığı ağlatıyor.

Sular inançsızca akıyor.

Tahta sıralara batıyor özleri.

Pazar günü ayinden sonra günah çıkartıyorlar

Taşlara.

Zinadan kurtulmalılar

Vicdan bu, kanıyor canım.

Gelecekse işte böyle iğrenç bir günde gelmeli bahar

Sonra umduğunu bulamadan çekip gitmeli', 'Kardan kaplanmış asfalt, dağlar boyun bükmüş rüzgara Hırçın kanatları yarmış geceyi Sabaha kadar vızıldamış uğultular Uguldatmış gözlerini H...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tecavuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmer Gözlüm', 'esmer-gozlum-emre-ozoran-hx8a0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kara gözlerin tenimi deler gibi bakarken içime

Hep seni öpmüş olmayı istedim

Bir sonbahar günüydü ayrılığımız

Gözlerini kaçırmanı hiç sindiremedim

Teninin tuzu dilimi boyarken

Boynunu son kez öptüğümün farkındaydım', 'Kara gözlerin tenimi deler gibi bakarken içime Hep seni öpmüş olmayı istedim Bir sonbahar günüydü ayrılığımız Gözlerini kaçırmanı hiç sindir...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/esmer-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sonra-gel', 'sonra-gel-i-smet-barlioglu-svlfe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Erenler, sırlara imreniyorsan; 

Bir yırtık gömleğe gir de sonra gel.

Çöllerde ayağa güveniyorsan; 

Çarığı ellere ver de sonra gel.

Sırrın kervanında sultan kul gibi,

Altınlar, gümüşler, elmas pul gibi,

İpekler, samurlar, mallar çul gibi,

Malını son kere gör de sonra gel.

Kahra katlanmayan bütünlenemez,

Çile çekeceksin ister istemez,

Bizim zevklerimiz zevke benzemez,

Zevkini, sefanı sür de sonra gel.

Önce güreş eyle tamahlarınla,

Çullan üzerine silahlarınla,

Kapan gıybetlere kulaklarınla,

Hırsını yerlere ser de sonra gel.

Henüz var arada bir engin deniz,

Biz beride durmuş seni bekleriz,

Hünerin var mıdır merak ederiz; 

Köprüyü elinle kur da sonra gel.

Bu yola düşülmez kalpsiz, gönülsüz,

Kalbi sakat olan olur sevimsiz,

Barlıoğlu der ki; aolmaz habersiz; 

Gönlünü aklına sor da sonra gel.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 394-395/412)', 'Erenler, sırlara imreniyorsan;  Bir yırtık gömleğe gir de sonra gel. Çöllerde ayağa güveniyorsan;  Çarığı ellere ver de sonra gel. Sırrın ke...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sonra-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıtırdayan Yalnızlığım', 'citirdayan-yalnizligim-emre-ozoran-pyaf3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayattan düşleri olan bir çocuk tanıdım

Üsküdar’da mendil satıyordu elleri

Ve para doluyordu cepleri.

Büfenin birinde goralı yiyen bir liseli tanıdım

Jöleli saçları sevdiği kızın kahverengi gözleri kadar sertti.

Vapur gişesinden bir jeton aldım

Biletçi şiddetle bozuk para almayı arzulamaktaydı

Ve elleri demirden aşınmıştı

Vapurda en arkaya geçtim

Sigara yakmadım hava kirlenir diye

Soğuğu çektim içime derin derin

Beyaz bir duman üfledim.

Mısır Çarşısı’ndan bir avuç safran aldım sarılığı ruhumu büyüledi.

Pandeli’de zeytinyağlı fasulye yiyen, zeytinyağını sürekli üzerine döken bir çocuk gördüm.

Siyah saçları söyledi kokladığı havanın temizliğini.

Dudaklarının etrafındaki zeytinyağlarını siliyordu annesi

Güldü dişleri beni görünce

Güldüm.

Anlamsız bir şiiri hatırlamaya çalıştım kestane yerken

Ağzım doluyken mırıldandım

Sıcaklığın isi doldurdu ağzımı sis gibi.

Göremedim.

Harem’de gişe kuyruğunda bekledim.

Sıra bana gelince ayrıldım ayaklarımın şiştiği yerden.

Keşke beni ilk bu sırada görseydin diye geçirdim içimden, keşke bu sırada beklerken Öpseydim seni ilk.

Avucum paltomun sıcaklığında elleri yok diye martıları arayarak ağladı gözlerim.

Cebimdeki kestane kabuğu çıtırdadı yalnızlığımı.', 'Hayattan düşleri olan bir çocuk tanıdım Üsküdar’da mendil satıyordu elleri Ve para doluyordu cepleri. Büfenin birinde goralı yiyen bir lisel...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/citirdayan-yalnizligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Ekmek Arasına Sevda', 'yarim-ekmek-arasina-sevda-emre-ozoran-1ebqn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerin arkasında küçük bir sis

Yumuşaklığı damlıyor yanaklarına

Rüyalara daldırıyo sabah vakti

Zaman yok

Yaşayacaksan atlayacaksın hayata

Acıkmadın daha.

Kanını emer gibi saldıracaksın her dakikaya

Sebebsiz yere koşturacaksın sokaklarda koklamak için her yeri

Her an yeniden nefes almak için

Ciğerlerini yakacak temiz hava

Usanmadan devam edeceksin

Acıkmasan da

Köşedeki büfeden yarım ekmek arasına sevda alacaksın

1 liraya

Buldun mu fırsatı, karnını doyurman gerek

Yolda acıkmak en kötüsü

Önyargısız, terli hayalleri paylaşacaksınız büfede oturan genç kızla,

-Nasıl yediğine baksana şunun? 

Sevmezsen biraz ketçup koyacaksın,

-Tuzu verir misiniz? Hayır o değil diğer tuzu...

Yanmış bu, at çöpe! 

-Kardeşim neden yanmışları koyuyorsun,

bana taze sevdalar gerek

Yeni dipdiri.

Bittiğine sevineceksin

Bu sefer

İyi bitti

Sonraki büfeye kadar yürüyeceksin

Paran bitene kadar ekmek arası sevda yiyeceksin.

Aç olmadığını biliyorum,

Paran varken ye,

Sonra acıksan da yiyemezsin belki', 'Gözlerin arkasında küçük bir sis Yumuşaklığı damlıyor yanaklarına Rüyalara daldırıyo sabah vakti Zaman yok Yaşayacaksan atlayacaksın hayata ...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yarim-ekmek-arasina-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huy', 'huy-huseyin-cayikli-9swou', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben istemezmiydim hep yanımda olmanı

Havalimanı bizim eve çok uzaktı

nokta ve virgülü koyulmuş aşkımızda

sana bir satır yazmak istemiştim

sen ki kuş tüylüydün

bende parmaklığın önüne gelen kuşun üstüne özgürlük şiirleri yazan bir adamdım...

hiç hakkın yoktu 

bilirsin devrimciler patron çocuklarını sevmez

napıyım huyum kurusun...', 'ben istemezmiydim hep yanımda olmanı Havalimanı bizim eve çok uzaktı nokta ve virgülü koyulmuş aşkımızda sana bir satır yazmak istemiştim se...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/huy-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul’da Ayrılık', 'i-stanbul-da-ayrilik-emre-ozoran-pq4ur', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün güneşte hiç ışık yoktu

Ve nargile dumanı anlamsız bir mutluluktu.

Vapur esti denizde, vapur soludu.

Işıklar söndü gecede...

Ruh sallantılı bir yer, neredeyse...

Karıştı bekleşen martılara.

Bir şiir okudu:

“Uzakta gözlerin

Özleyen ve özleten,

Sonra saçlarin

Beklenen dudakların var...

Sen...

Dilinin ucunda söylenmeyecek bir hüzün var.”

Deniz uzun bir mavidir, gri olduğu kadar.

Ucuz bir serinliktir dalgaları izlemek.

Eski bir kordur ayrılık....

Hiç yandın mı?', 'Bugün güneşte hiç ışık yoktu Ve nargile dumanı anlamsız bir mutluluktu. Vapur esti denizde, vapur soludu. Işıklar söndü gecede... Ruh sallan...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istanbul-da-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haliç ve Kadın', 'halic-ve-kadin-emre-ozoran-x2jh9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Lanetin karşısında gül ve mum kokan kadın,

Gözlerin kalın camın arkasındaki su kadar berrak.

Asla yanılmadın kaldırımlara,

Sigarını söndürmeden hiç yere atmadın.

Sokaklarda dolaşmadın karlı günlerde,

Parke taşlarının yalnızlığını yaşamadın.

Sevmedin yıldırımları camları buğulu gecede.

Galata Köprüsü açılır Eminönü’nden Karaköy’e, yol boyu nargile ve balık kokuları ve turistlerin bira bardakları alır gözünü.

Bak bir olta atıldı, biri daha, ne kadar büyük balık çekiyor şu adam! 

Tömbeki mi içiyorsun gemilere bakarak? 

Yoksa hayallerin bulutlarla kuşlarda mı geziyor? 

Köz iste, sönüyor alev.

Duman azalıyor.

O duman benim aklımı çeliyor.

Köşeden içime çekiyorum seni o dumanla,

Rüyalara karışıyorum.', 'Lanetin karşısında gül ve mum kokan kadın, Gözlerin kalın camın arkasındaki su kadar berrak. Asla yanılmadın kaldırımlara, Sigarını söndürme...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/halic-ve-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değdi Geçti', 'degdi-gecti-fahrettin-selcik-lk0xw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gezdik 360 odalı İshak paşa sarayı,

 İnsan düşünüyor anlıyamıyor bu şaşayı,

Vergi veya haraç diye aldığı parayı,

Halktan almamıştır hayır ve duayı.

Kan ve irin var her taşında,

Sütler akmış iç avlu musluğunda,

Heybetli görünüyor tepe doruğunda,

Kanal ve kalorifer varmış yapısında.

Turumuz Kilis iline geldi geçti,

Yolda yedikleri etkiledi,serdi geçti, 

Öncelikle oyuncu Fatoş u seçti,

Kimine tam isabet,kimi diretti.

Fatoş hastanede serum ve iğne yedi,

Dr Aysel hanım. Bizleri tedavi ederdi,

Baktık ki oda hastalandı,vuslata erdi,

Kalmadı istisna turu kırdı geçti.

Söylentiye göre sebep kaburga etiymiş,

Sanki et değil ishal ilacı imiş,

Ekstra mığde bula D E Ğ D İ   G E Ç T İ

Gezdik 360 odalı İshak paşa sarayı,

 İnsan düşünüyor anlıyamıyor bu şaşayı,

Vergi veya haraç diye aldığı parayı,

Halktan almamıştır hayır ve duayı.

Kan ve irin var her taşında,

Sütler akmış iç avlu musluğunda,

Heybetli görünüyor tepe doruğunda,

Kanal ve kalorifer varmış yapısında.

Turumuz Kilis iline geldi geçti,

Yolda yedikleri etkiledi,serdi geçti, 

Öncelikle oyuncu Fatoş u seçti,

Kimine tam isabet,kimi diretti.

Fatoş hastanede serum ve iğne yedi,

Dr Aysel hanım. Bizleri tedavi ederdi,

Baktık ki oda hastalandı,vuslata erdi,

Kalmadı istisna turu kırdı geçti.

Söylentiye göre sebep kaburga etiymiş,

Sanki et değil ishal ilacı imiş,

Ekstra mığde bulantısı,kusma varmış,

Dostlar yolculukta hastalı ne zor ve acıymış.', 'Gezdik 360 odalı İshak paşa sarayı,  İnsan düşünüyor anlıyamıyor bu şaşayı, Vergi veya haraç diye aldığı parayı, Halktan almamıştır hayır ve...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/degdi-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1001 Parça', '1001-parca-huseyin-cayikli-ti5jl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbimi bin bir parçaya böldükten sonra gitmiştin sen

sen bir burjuvaydın fransız devrimini yaratanlardan filanda değildin...

bende özentiydim senin yaşamına 

ama ben biliyordum senin gibilerini pasaj kokan evlerden...

hataydın benim küçük hayatımda...

büyütmene gerek yoktu o yaşamı

unutma sakın küçük şeylerden mutlu olan insanların yanına yaklaşma

hiç hakkın yok onların yaşantısını 

bin bir parçaya bölmene...', 'Kalbimi bin bir parçaya böldükten sonra gitmiştin sen sen bir burjuvaydın fransız devrimini yaratanlardan filanda değildin... bende özentiyd...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/1001-parca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biter zaman', 'biter-zaman-i-brahim-atilmis-kaeaw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeşile bürünmüş sevdalarım

Türküler yakılmış hallarıma

Sinem daralır yollar uzar.

Bittikçe biter zaman 

bedenim tükenir.

Umut 

gün misali en tepede. 

Durur

Dururda alnımın şavkına vurur

Sen 

kim bilir şimdi nerelerde? 

Ben yine boynu bükük 

kaldim yollarda

Aradım seni yıllar boyu

En olmadık zamanlarda

En kuytuluk yerinde sinemin.', 'Yeşile bürünmüş sevdalarım Türküler yakılmış hallarıma Sinem daralır yollar uzar. Bittikçe biter zaman  bedenim tükenir. Umut  gün misali en...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biter-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birşey Yap', 'birsey-yap-i-smet-barlioglu-ktt9e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömrünün fazlası boşa gittiyse

Kalan da boş yere gidesi olur.

Ekme rüzgarları kutsal tarlaya; 

Bakarsın fırtına bitesi olur.

Alanlar öderler kılı kılına,

Aldığını geri gönderir ayna,

Ne kadar göz kulak olsan malına

Talep edecekler edesi olur.

Güvenme mallara, kalacak diye,

İnanma servete, duracak diye,

Bekleme seninle gelecek diye,

Yerlerinde duman tütesi olur.

Vade bir ok olup tahtı deldimi,

Tacın parıltısı sona erdimi,

Saltanat sürerken ölüm geldimi

Bir sonuncu nefes yetesi olur.

Harcansa yeridir ömür ilime,

Hiç geri istenmez bir tek kelime,

Ondan gayrısını versen eline

Ölürken elinden atası olur.

Kaçamaz ecelden ağalar, beyler,

Herkes bedenini bir gün terkeyler,

Can verirken dahi öğret birşeyler; 

Ola ki aklında tutası olur.

Kıldan medet umar o anda insan,

Herşeyini verir, meğer kurtarsan,

Değişecek bir tek nefes bulursan

Serveti nefese satası olur.

Hikmet der; birşey yap yürekten, candan,

El meyve toplasın sendeki daldan,

Yahut geçiversin açtığın yoldan,

Bakarsın, doğruyu bulası olur.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 396-397/412)', 'Ömrünün fazlası boşa gittiyse Kalan da boş yere gidesi olur. Ekme rüzgarları kutsal tarlaya;  Bakarsın fırtına bitesi olur. Alanlar öderler ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/birsey-yap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum', 'erzurum-fahrettin-selcik-qr7ow', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Erzurum kendine özgü dadaş şehri,

Bizim tur mensuplarına istirahat yeri,

Nedenini sorarsanız PALA oteli,

Otelin temizliği,servis ve hizmeti.

Görülmeye değer ulu camii,

Yanındaki Hatuniye medresesi,

Sevimli kümbetler ve mimarisi,

Ayrıca şahanedir taş işlemesi,

Götürdüler tur’u yön vererek Taş Han’ a,

İçine girince sempatik geliyor insana,

İçerde hakim olan gümüş ve oltu taşı,

Paran yoksa sadece seyret,biraz da başın kaşı,

Akşam oldu içtima, kristal  restoranda,

Girişte koku alınca fren kalmıyor insanda,

Gerçek Tur serbest  bıraktı şiş sayısında,

Garsonlar yetişemiyordu yemek yarışında.

Yarış da sonuçlar alındı,

Çıkan şişler tek, tek sayıldı,

Kaptan Hasan on sayıda kaldı,

Öncesinden daha iyi skoru vardı,

Meşhur olan Şıllık tatlısı,

Şekli parmak,kadayıf yapısı,

Ayrıca vardı cevizli inciri,

Böylece geçtik yemek zinciri, 

Tam üç ocak var restoranda,

Bir de çilekeş hane  arasında,

Çok yiyene,Ya sabır diyordu, levhasında

Yemekler yenildi böyle bir havada.

Polat Otel den hani ayrılamadık,

Yıldızlarına öylesine baktık,

İki yıldızına iki de biz taktık,

Huzuru  kalple  dedik Allahaısmarladık.

Fahrettin Selçik  30.5.2004  Erzurum', 'Erzurum kendine özgü dadaş şehri, Bizim tur mensuplarına istirahat yeri, Nedenini sorarsanız PALA oteli, Otelin temizliği,servis ve hizmeti....', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/erzurum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüş', 'donus-fahrettin-selcik-vlv3t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dönüş de son durak Yunus Emre

Herkes yüklenmiş sanki hamile,

Tuvalete  girenler bir kısım yük attı,

Bazıları benmari önünde tur attı,

Bende tuvalete ineyim dedim,

Nesrin den çimdik yedim,

Kızdım bir tas çorba içtim,

Dönüp selametle yerime geçtim.

Otobüse binilip su istenince,

Ben burası artık son durak deyince,

Kahkaha koptu,Ömer biraz sıkın,söyleyince,

Uykular ve gözler açıldı Salihli görününce.

Geçiyoruz  Kiremit ve tuğla fabrikalar,

On günlük seyahatte döküldü bütün kurtlar,

Güzel bir seyahat oldu sanırım dostlar,

Bazılarınca hayal ediliyor yeni Gerçek Turlar.

Ağzı açık uyuyanlar foto oldu,

Horlayanlar a kahkaha koptu,

Nesrin gülünce baklava sunuldu.

Gerçek Tur seyahati son buldu.

Fahrettin Selçuk 3.6.004', 'Dönüş de son durak Yunus Emre Herkes yüklenmiş sanki hamile, Tuvalete  girenler bir kısım yük attı, Bazıları benmari önünde tur attı, Bende ...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/donus-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kars Etabı', 'kars-etabi-fahrettin-selcik-xbo14', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün öğlen  boyladık Karsı,

Hiç sevmedim bozuk olan yolları,

Meşhurmuş uymuş peynir ve kaşarı,

Gördük ANİ harabeleri ve Ermenistanı,

Aç kurtlar gibi kristal restorana girdik,

Ağız tadıyla ve güvenle yemek yedik,

Tuvalet olarak alafrangayı gördük,

Nesrin dahil cümle rahata erdik.

Geçmemişti halen kaburga et etkisi,

Zamanla beliriyordu insanlarda tepkisi,

Beş numarada oturan Şener ve eşi,

Kars  hastanesinde yiyordu serum ve şişi,

Cüzdanı ağzını açan kaşarı kaptı,

Yönlendirmeyi HGerçek Tur yaptı,

Bölgedeki ikinci tercihli mal,

Arıların yayla çiçeğinden yaptığı bal.

Ani Harabelerinde M.Ö. yaşam başlamış,

Çok medeniyetler sıra ile kuşatmış,

Kimisi yakıp yıkmış,kimisi onarmış,

En son,Gerçek Turla bizimkiler ulaşmış.

Fahrettin Selçik  30.5.004 Kars', 'Bu gün öğlen  boyladık Karsı, Hiç sevmedim bozuk olan yolları, Meşhurmuş uymuş peynir ve kaşarı, Gördük ANİ harabeleri ve Ermenistanı, Aç ku...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kars-etabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Midyat', 'midyat-fahrettin-selcik-eoxf8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Midyat a girdik bugün sabah,

Bulgur bile kalmamış,dönmüş gümüşe,

Paraları israf etmek günah,

Dükkan açan esnaf bile şaştı bu işe,

Çıktık Hasan Keyif  yoluna,

Mağara evler göründü Dicle kıyısında,

Burada hayat taş devrinde başlamış,

Daha sonraları da her devire kucak açmış,

Malabadi köprüsü bir harika,

İşlevi bitmiş olmuş antika,

Buraya hayat veren nehir Dicle

Ülkeyi aydınlatıyor elektrik üretince.

Fahrettin Selçik  28.5.004', 'Midyat a girdik bugün sabah, Bulgur bile kalmamış,dönmüş gümüşe, Paraları israf etmek günah, Dükkan açan esnaf bile şaştı bu işe, Çıktık Has...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/midyat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuvalet Edebiyatı', 'tuvalet-edebiyati-fahrettin-selcik-6e8io', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çiçek toplamaktır çiş yapmanın parolası,

Geldik bir yere  gerekir buranın da sulaması,

Hasan kaptan vermelisin çiş molası,

Geliyor insanın içinden çiçek toplaması.

İki buçuk saat de bir mola verirler,

Sıkışanlar tuvalete koşarak giderler,

Yaş ortalama yüksek,alafrangayı tercih ederler,

Bulamazlarsa Resul ün çadırına razı idiler,

Çiçek toplamaktır çiş yapmanın parolası,

Geldik bir yere  gerekir buranın da sulaması,

Hasan kaptan vermelisin çiş molası,

Geliyor insanın içinden çiçek toplaması.

İki buçuk saat de bir mola verirler,

Sıkışanlar tuvalete koşarak giderler,

Yaş ortalama yüksek,alafranga tercih ederler,

Bulamazlarsa resul patentli çadıra da eh derler,

Önemlidir tuvalet edebiyatı,

Rahatlatır sağlık ve hayatı,

Buda  bedenin  normal ifrazatı,

Böyle geçti Gerçek Tur seyahati 

Neden ayırt etmişler cinsiyete göre tuvaleti,

Otobüste olunca23 bayan beş erkek milleti,

Bir yanı kuyruk,diğer yanı boş olacaktı,

Seyahatte bayanlarımız bozdu bu hikmeti.

Fahrettin Selçik   12.6.2004', 'Çiçek toplamaktır çiş yapmanın parolası, Geldik bir yere  gerekir buranın da sulaması, Hasan kaptan vermelisin çiş molası, Geliyor insanın i...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tuvalet-edebiyati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kaldı Elinde?', 'ne-kaldi-elinde-i-smet-barlioglu-s2xne', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne kaldı elinde bugüne kadar

Harcayıp gittiğin zaman içinde? 

Malın, mülkün varsa; o senin değil,

Onun tek sahibi devran içinde.

Saraylar yaptınsa; pıla gidecek,

Kasırlar kurdunsa yele gidecek,

Billur havuzların sele gidecek,

Çıplak gideceksin kervan içinde.

Kıskandığın mallar edilir talan,

Mala sahip olmak bir büyük yalan,

Senin sayılır mı arkanda kalan? 

Bir garip yoksulsun umman içinde.

Sımsıkı sarılma bomboş hayale,

Sonunda acırsın boş kalan ele,

Zira, gidiyorsun her gün ecele,

Hüsrana uğrarsın yalan içinde.

Bir hayır işle ki; birlikte gelsin,

Hayrın yaşadıkça adın söylensin,

Tek bir fidan dik de bir gölge versin,

Gezdir bir yoksulu mintan içinde.

Gücün yetiyorsa; yoksul evlendir,

Ya da bir ayağa bir pabuç giydir,

Düşküne, yaşlıya bir lokma yedir,

Fakiri gelin et fistan içinde.

Darda kalanların tut ellerini,

Dertli olanların dinle derdini,

Esirgeme sakın hamiyyetini,

Saklama gücünü cüzdan içinde.

Öğrenci olana koş, imdad eyle,

Bir mutsuz görürsen git de şad eyle,

Bilgisiz kalanı gör, irşad eyle,

Bekletme kudreti saman içinde.

Barlıoğlu der ki; dediğim haktır.

Sanki gelindeki teldir, duvaktır,

Aynen bal gibidir, aynen kaymaktır,

Ararsan bulursun vicdan içinde.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 398-400/412)', 'Ne kaldı elinde bugüne kadar Harcayıp gittiğin zaman içinde?  Malın, mülkün varsa; o senin değil, Onun tek sahibi devran içinde. Saraylar ya...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ne-kaldi-elinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığı Sen Çıkardın', 'ayriligi-sen-cikardin-arif-hikmet-basegmez-xn8c3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani dertler engel olsa,

Benden önce sen yıkardın.

Ben severdim bana kalsa; 

Ayrılığı sen çıkardın.

Son verdiysen bu sevgiye,

Bu sebepsiz ahın niye? 

Sevmiyorum diye diye,

Ayrılığı sen çıkardın.

Sen bana yar,ben sana yar,

Bizimleydi mutluluklar.

Kaderin ne günahı var? ..

Ayrılığı sen çıkardın.

              Yazan: (Arif Hikmet BAŞEĞMEZ(sivas/merkez)', 'Hani dertler engel olsa, Benden önce sen yıkardın. Ben severdim bana kalsa;  Ayrılığı sen çıkardın. Son verdiysen bu sevgiye, Bu sebepsiz ah...', ARRAY['Türk Edebiyatı','Şiir','Arif Hikmet Başeğmez']::text[], 8.5, '{"poet":"Arif Hikmet Başeğmez","poet_slug":"arif-hikmet-basegmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayriligi-sen-cikardin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrı Kaldık', 'ayri-kaldik-engin-namli-oq98t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki gönülü tanıştıran şarkı

Yıllarca kalbimize yaptı yankı

Yaşayamadık nağme kokan aşkı

Bir gün barışık bir gün ayrı kaldık

Bitmedi sevgiye,aşka borcumuz

Ödedikçe arttı kat kat hıncımız

Gönül almadan kabardı suçumuz

Bir gün barışık bir gün ayrı kaldık

Gün geldi hiç yoktan darıldın bana

Zaman zamanda ben kırıldım sana

El uzatıp gelemedik yan yana

Bir gün barışık bir gün ayrı kaldık

Büyük aşkın hakkını veremedik

İncinirken farkına varamadık

Bin anıya bir aşk sığdıramadık

Bir gün barışık bir gün ayrı kaldık

Engin NAMLI  15:23 13.06.2004', 'İki gönülü tanıştıran şarkı Yıllarca kalbimize yaptı yankı Yaşayamadık nağme kokan aşkı Bir gün barışık bir gün ayrı kaldık Bitmedi sevgiye,...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayri-kaldik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanan - Kanar', 'sanan-kanar-mehmet-fatin-baki-i7pfe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Isıramadığım eli

Öpeceğim, öpeceğim.

Diye sanan,

Yeremiyeceğim el’i

Öveceğim, öveceğim.

Diye kanar.

Mütefeilü feilün

.  .  .  .  .  .  .   /', 'Isıramadığım eli Öpeceğim, öpeceğim. Diye sanan, Yeremiyeceğim el’i Öveceğim, öveceğim. Diye kanar. Mütefeilü feilün .  .  .  .  .  .  .   /...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sanan-kanar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavileri Kestin Biçtin Mor Ettin', 'mavileri-kestin-bictin-mor-ettin-sadik-softa-utqbp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mecbur muydun yürekleri yakmaya? 

Hüner miydi umutları kör ettin? 

Damla damla eriyorsun bilirim; 

Kavuşmaya umut kestin zor ettin.

Buram buram tüttün durdun gözümde,

Karakış yaşattın gelen yazımda,

Hasretimden buza kesen sözümde,

Mavileri kestin, biçtin, mor ettin.

Umut kesti her kavuşma isteğim,

Engel mi ararsın, sensin kösteğim,

Sen gözüm nurusun,sevdam,bebeğim,

Yüreğimi  yangın  yeri  kor  ettin.

Yollarıma engel koydun dur diye,

Uzaklarda durdun, sanki sor diye,

Aşığın gözleri mutlak kör diye,

Yüreğe hükmedip sanki dur ettin.

Aylar geçti, saatlerle koşturdun,

Günler geçti vaatlerle coşturdun,

Çabasız seyredip sanki boş durdun,

Aramıza duvar çektin, sur ettin.', 'Mecbur muydun yürekleri yakmaya?  Hüner miydi umutları kör ettin?  Damla damla eriyorsun bilirim;  Kavuşmaya umut kestin zor ettin. Buram bu...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mavileri-kestin-bictin-mor-ettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adaşım Bardakçı’ya', 'adasim-bardakci-ya-mehmet-fatin-baki-729fx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hemen İMDÂD’a cevap, zevk-i zarâfetle geldi

Kısa  bir  sözdü  fakat  harfleri  âfâkı  deldi.

Sanırım, ben gibi gurbetçiye gönderdiğin lafz,

Vecîz olmakla berâber  dizelerden  ‘GÜZELDİ’

Feilâtün    feilâtün    feilâtün     feûlün 

.  .   /   /   .  .   /   /  .  .   /   /   .    /   /', 'Hemen İMDÂD’a cevap, zevk-i zarâfetle geldi Kısa  bir  sözdü  fakat  harfleri  âfâkı  deldi. Sanırım, ben gibi gurbetçiye gönderdiğin lafz, ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/adasim-bardakci-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen', 'bazen-tansel-yucelen-z392c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bazen

hatırlıyorum da sensizliğimi

	alkollü ellerle yazılmış intihar mektuplarımı

		ve onların her yeni bir günde çöpe gidişlerini

bazen

anımsıyorum da sensizliğimi

	hayatı isyanlarda kabullenmeyişlerimi

		çığlıklarımı, asi bakışlarımı, o sonbaharlarımı

bazen

görüyorum da sensizliğimi

	mevsimim geçince kendimi denize döküşlerimi

		sonra tatsız insanların arasında tekrar bulmalarımı

vardı

	arkadaşlarım

		dostlarım

			kendimi adadığım bir çok uğraşım

evet vardı

	gülüğüm o günler

		sapıttığım salak partiler

			denizde damarıma alkolleri boğultturmalarım

varmış

	bir sürü gereksiz anılarım

evet varmış

	değil mi

tüm gereksiz

	buruşturulmuş kağıtlar varmış ta

benliğime gerekli olan tek ruh neden yokmuş

	sen neden yoktun

işte bu yüzden

sırf bu yüzden

sadece bu yüzden

bazen

düşündüğümde yaşamımı

geçmişimi siliyorum

		düşünmeden

bazen

hatırlıyorum da sensizliği

hatırlamıyorum

hiç

bir

şey

çünkü 

yok-

mu-

şum

ben', 'bazen hatırlıyorum da sensizliğimi 	alkollü ellerle yazılmış intihar mektuplarımı 		ve onların her yeni bir günde çöpe gidişlerini bazen anı...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/bazen-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Sensiz Olmak', 'bu-gece-sensiz-olmak-tansel-yucelen-op3mi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'karanlık bir odada dururken kendimle

kokunu alıyorum hala tenimde

zor özlemek keşke yanımda olsan

yine konuşsan yine dokunsan yine seni sarsam

bebeğim her gece seni uyutmak isterim

ayrılık zor beklemek zor sensiz kalınca

elimde olsa içimden yaratırdım hep seni

sen yanımda kollarımda ruhun ruhumda

bu gece sensiz olmak

öldürüyor beni burda

aldığım nefes kadar benimsedim

verdiğim soluk kadar sardın sen beni

zor özlemek keşke yanımda olsan

yine konuşsan yine dokunsan yine seni sarsam

bu gece sensiz olmak

öldürüyor beni burda

şu an da yoksun sen yanımda

ama ruhun dört bir yanda

...', 'karanlık bir odada dururken kendimle kokunu alıyorum hala tenimde zor özlemek keşke yanımda olsan yine konuşsan yine dokunsan yine seni sars...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bu-gece-sensiz-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Vakti', 'ayrilik-vakti-tansel-yucelen-1u4ux', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bugün son

gidiyorum ben de

bu şehirden

çok uzaklara

bugün son

dönüşü yok belki

farklı bir zamanda

farklı bir mevsimde

vakit geldi

ayrılık vakti

bir tren ile

ağlarım belki

vakit geldi

yolculuk vakti

kalkıyor senden

sonsuz içine

kalbinden

zamansız

dönersem sana

sarıl boynuma

hiç beni bırakma

belki de o an

okursun bana

yazdıklarını

ben gittikten sonra

vakit geldi

ayrılık vakti

bir tren ile

ağlarım belki

vakit geldi

yolculuk vakti

kalkıyor senden

sonsuz içine

kalbinden

gitme kal deseydin bana

dönülmeyen o son akşamda

şimdi gözlerim kırmızı bir şarap misali

kafamsa çok dumanlı

vakit geldi

ayrılık

vakti

...', 'bugün son gidiyorum ben de bu şehirden çok uzaklara bugün son dönüşü yok belki farklı bir zamanda farklı bir mevsimde vakit geldi ayrılık va...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ayrilik-vakti-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkında Mısın', 'farkinda-misin-tansel-yucelen-udkfz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'farkında mısın

	sensizken çok özlüyorum seni

farkında mısın

	her zaman çok seviyorum seni

farkında mısın

	bir şiir değil bu

farkında mısın

	aslında sana yazılmış iki beyit bu

farkında mısın

	öyle birşey işte

seni seviyorum

	tek bildiğim bu

		farkında olduğum

			tek şey bu

iyi ki varsın

	farkında mısın', 'farkında mısın 	sensizken çok özlüyorum seni farkında mısın 	her zaman çok seviyorum seni farkında mısın 	bir şiir değil bu farkında mısın 	...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/farkinda-misin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama', 'aglama-banu-aka-jfw0x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlama anne

Dedi kızım

Minik elleri ile 

Gözyaşlarımı silerken

Ağlama anne

Hepsi geçecek

Bak ben yanındayım

Seni hiç bırakmam

Dedi kızım

Ben

Arkasından el sallarken...', 'Ağlama anne Dedi kızım Minik elleri ile  Gözyaşlarımı silerken Ağlama anne Hepsi geçecek Bak ben yanındayım Seni hiç bırakmam Dedi kızım Ben...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/aglama-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayra''ya', 'kayra-ya-banu-aka-yme3t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Donmasın gülüşün yüzünde

Gözyaşlarının tadını bilme 

Hep o çocuk heyecanıyla

Bak gök yüzüne 

Çizdiğin resimler 

Aynı kalsın 

Dünya sana hiç dokunmasın...', 'Donmasın gülüşün yüzünde Gözyaşlarının tadını bilme  Hep o çocuk heyecanıyla Bak gök yüzüne  Çizdiğin resimler  Aynı kalsın  Dünya sana hiç ...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kayra-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaptan', 'kaptan-banu-aka-n0zpc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani diyordum

Ne zamandan beri istediğim

Deniz kokulu o gece olsa

Gözlerin yakamozlansa yanı başımda

Yıldızlar düşse rakı bardağına 

Daha önce hiç söylemediğin

Kelimeler çıksa bayıldığım dudaklarından 

Sen bile şaşırsan.

Sana baksam 

Gözlerim kamaşsa 

Kavga etsek dümeni kim tutacak diye

Sen  kazansan

Mavi geceye daldırınca  gözlerimi

İster istemez dökülse yüreğimden  bir şarkı 

“   Çok yorgunum

     Beni bekleme kaptan....”', 'Hani diyordum Ne zamandan beri istediğim Deniz kokulu o gece olsa Gözlerin yakamozlansa yanı başımda Yıldızlar düşse rakı bardağına  Daha ön...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaptan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Hayat', 'ey-hayat-mehmet-seyidhasanoglu-9naz2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uçsuz bucaksız bir şehirdir hayat! 

Sokaklarına çıkmaya korktuğun,

Vangölü''nün kıyısında bir bankettir hayat,

Üzerinde otururken sigara içmeyi unuttuğun....

Hayat, gökyüzündeki milyonlarca yıldız gibidir,

Yetişemeyeceğini bile bile, anlamsızca uzandığın! 

Martıların kanatlarını suya değdirmesi,

Bir çift kanaryanın kafese kapatılmasıdır; hayat! ....

Hayat; 

İçtiğin her yudum suda, yediğin her lokma aşta,

Seni yaşamak, içinde yaşatabilmektir.....

hayat; sensizken bile seni yaşamaktır,

Gördüğün her düşü hayra yormak,

Her düşte, seni bulmaktır....

Hayat; sevdaya verilmiş bir söz,

Sevdayı bırakmamaya dair; 

Gecenin şahitliğinde, içilen and''dır! ...

Hayat; sensin, sen ise; benim bir parçam,

Şimdi söyle bana, ey hayat; 

Bir parçam eksikken nasıl yaşarım ben? 

Sen benim sevdamsın,

Yüreğimsin sen benim; 

Ey Hayat! ...

         21.06.2003 / Cumartesi', 'uçsuz bucaksız bir şehirdir hayat!  Sokaklarına çıkmaya korktuğun, Vangölü''nün kıyısında bir bankettir hayat, Üzerinde otururken sigara içme...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Seyidhasanoğlu']::text[], 8.5, '{"poet":"Mehmet Seyidhasanoğlu","poet_slug":"mehmet-seyidhasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ey-hayat-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tetik Soluğunda Zaman Senden Bana Kalan...', 'tetik-solugunda-zaman-senden-bana-kalan-tulay-eker-9utws', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeşildim 

Çağlayan altında filizlenmiş 

Gündoğumları ellerimde belenmiş. 

Faylar üstüne geldi cismim 

Kaya parçasına tutundum bedbin 

Tutunma sebebim:Yaşama dair 

Yaşam:Verdiklerim 

Camdım 

Işık geçirmeye adandım 

Güneşin altında yandım 

Ateşiyle parçalandım 

Hayatın saçağında asılı donakaldım. 

Donakalma sebebim:Suyum 

Suyum:Ahengim 

Saattim 

Akrepsiz,yelkovansız 

Koşmaya ayarlanmıştım aralıksız 

Boğazımda kement sayısı artmış 

Çırpınmalarımla dirildim 

Dirilme sebebim:Şiir 

Şiir:Benim 

______Şimdi 

Tetik soluğunda zaman 

Senden bana kalan. 

_______Söyle! 

Hangi zamana kurdun beni 

Tetikte asılı kalmış eli.', 'Yeşildim  Çağlayan altında filizlenmiş  Gündoğumları ellerimde belenmiş.  Faylar üstüne geldi cismim  Kaya parçasına tutundum bedbin  Tutunm...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/tetik-solugunda-zaman-senden-bana-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Batmamalı', 'gunes-batmamali-i-hsan-dinibutun-k9ymp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haydi kalk artık

İşim var

Zaman sermayemdir benim

Boş laflarla harcayamam

Belki zamanın çoktur,

Harcayacak saatlerin vardır senin

Ama benim böyle bir iüksüm yok

Hiç olmadı,

Belki olmayacak

Beni bırak, kalk ve git

Beni dinlersen hatta

Arkana bile bakma

Kalk git

Tüketme sermayemi benim

İşim çok

Ekmeğimi kazanmalıyım

Akşama elimboş dönemem

Gözlerine bakamam kadınımın

Çocuklarımı okşayamam

Zaman benim herşeyimdir

Güneş doğarken başlar kavgam

Erkenden

Sen uykunun üçüncü perdesindeyken

Ruyalarının ortasıdır

Oysa benim uykum,

Tek perdedir

Ruyalarım yoktur,

Düşlerimde

Haydi git artık

Git

Benim için

Bu gün güneş batmamalı', 'Haydi kalk artık İşim var Zaman sermayemdir benim Boş laflarla harcayamam Belki zamanın çoktur, Harcayacak saatlerin vardır senin Ama benim ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gunes-batmamali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Üstü Hüzün! ...', 'aksam-ustu-huzun-mehmet-seyidhasanoglu-2yk6i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün; yine akşam olmakta! 

Hüzünler bir bir yığılmakta, yüreğime,

Ben yine sensiz, bir başımayken; 

Yıldızlar yüreğime aşk''ı savurmakta,

Işığın ritmi; beni sarhoş eylemekte! .....', 'Gün; yine akşam olmakta!  Hüzünler bir bir yığılmakta, yüreğime, Ben yine sensiz, bir başımayken;  Yıldızlar yüreğime aşk''ı savurmakta, Işığ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Seyidhasanoğlu']::text[], 8.5, '{"poet":"Mehmet Seyidhasanoğlu","poet_slug":"mehmet-seyidhasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aksam-ustu-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Likya yollarına düşen', 'likya-yollarina-dusen-zafer-zengin-etnika-s6e3m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Likya yollarına düşen

Esir işçi sırtında mermerler

Akdenize düşen acı gibiler

Her yanan ten güzelken

Onlar tatil nedir bilmezler

Onlar mermeri işlerler

Dik gözlere sürülen çıban gibi

Kral tacları zeytin dalı

Bilmiyor hayatı

Hep esir likya''lı

/Koca şehirler bitirdik

Caddesinde koşmadan

Yolların görünmeyen yüzlerine

Terimizle bizi çizdik/

Yolun düşerse olimposa

Sor adresi likya yoluna

Portakal bahçelerine sakla

Kaçaçağın yer olmazsa

Aitdin işte güldüğün dağlara

Taş lahit üstünde

Bir el düşün ki gözünde

Mermer oyan

Taşa can katan

Emek nakışlarında gerçeği

/Duruş/Ürkekçe/

Duruş ki

Körpe tarihe kazınan

Adına heykeller yapılan

İnsan/aşk/a

/Sonradan anlaşılır

Başsız olan

Yarım kalan/

Ben sana sehirler kurdum

İsadan önceli yıllarda

Yıkamamıştı

Kaç vurgun

Kaç istila

Kale burçlarına kellemi astılar

Servetlerine servet kattılar

Gemilerimi yaktılar

Bu yüzden

İki yakası 

Bir araya gelmez denizimin

/Kuzey limanı /Duru tuzlu/

Ben sana tapınaklar yaptım

İsadan önceli

İsadan sonralı yıllarda

Yıktılar tanrıları

Kırdılar insanları

Deniz kana bulandı

Bir zaman memleket balıksız

Çocuklar aşsız susuz

Kıyılar martısız

Kadınlar kocasız kaldı

/Bir nesil kayboldu/Tuzunda /Çürümeden/

Son gün

Güç bağlar çözüldü

Bıraktım ardımda

Madem ki ölüm olacaktı

Önce deniz yanmalıydı

Çıra yaptım ellerimi

Tutuştum

Ben yanarken ateşten değil

En çok insandan korktum

/Güney limanı küstü yüzümüze/ Zinciri kesilmedi/

Ben insandan korktum/Dili ateş saçan

Akdenizi boydan boya yapan

O likyalı adam

Dönecek elbette

Umut düşürmedi aşk''tan

Girişinde şehrinin

Mermer bir heykel vardı

Giderken esir dağları ardına

Oraya mektup bıraktı

/Geri gelse 

Değişmezdi tarihde iz

Ne de değişirdi akdeniz/

27 Mayıs 2004', 'Likya yollarına düşen Esir işçi sırtında mermerler Akdenize düşen acı gibiler Her yanan ten güzelken Onlar tatil nedir bilmezler Onlar merme...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/likya-yollarina-dusen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gelince! ..', 'sen-gelince-ferit-teksoy-a9so9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen gelince..canımıza can geldi

Sen gelince..yüzümüze kan geldi

Sen gelince..gönlümüze heyecan geldi

Neşe geldi,gülüş geldi,şan geldi..sen gelince

Sen gelince..gözümüze renk geldi

Sen gelince..hayatımıza ahenk geldi

Sen gelince..kır çiçekli çelenk geldi

Bahar geldi,çiçek açtı,can geldi..sen gelince 

Sen gelince..duygumuza düzen geldi

Sen gelince..dünyamıza nizam geldi

Sen gelince..işimize intizam geldi

Sabah oldu,ışık geldi,gün geldi..sen gelince 

Sen gelince..sözümüze söz geldi

Sen gelince..yüreğimize köz geldi

Sen gelince..bir çift güzel göz geldi

Gül geldi,sevgi geldi,aşk geldi..sen gelince! ..', 'Sen gelince..canımıza can geldi Sen gelince..yüzümüze kan geldi Sen gelince..gönlümüze heyecan geldi Neşe geldi,gülüş geldi,şan geldi..sen g...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-gelince-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damlalardan Bir Yol', 'damlalardan-bir-yol-siyah-croft-2ypk3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gökyüzü grilere bezenmiş...

Tam solumda damlalardan bir yol,

Ağaçlara uzanan...uzandıkça kaybolan...

Ağaçlar soyunmuşlar...

Çırılçıplak dizilmişler sıraya...

Her rüzgarda eğilerek selam veriyorlar aşıklara,

Zamanla dökülen yapraklara...

Tam solumdaki damlalardan bir yola...

Ve arkasından toprağa...

Toprak sevdalanmış buluta...

Kokusu yeniden yayılmış...

Uzaklara kadar yol almış...

Tam solumdaki damlalardan bir yola varmış...

Çünkü özlenen yağmura sarılmış...

Bulutlar uzaklaşmakta...

Ağlaması gereken yere, yani; 

Tam solumdaki damlalardan bir yola gitmekte...

Çünkü yoldaki damlalar bitmekte...

Gökyüzü değişmekte...

Galiba bu sefer maviye bürünmekte...

 Siyah (croft)', 'Gökyüzü grilere bezenmiş... Tam solumda damlalardan bir yol, Ağaçlara uzanan...uzandıkça kaybolan... Ağaçlar soyunmuşlar... Çırılçıplak dizi...', ARRAY['Türk Edebiyatı','Şiir','Siyah (croft)']::text[], 8.5, '{"poet":"Siyah (croft)","poet_slug":"siyah-croft","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/damlalardan-bir-yol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aça-69 (Syk-5b) - Düş''e giriş', 'aca-69-syk-5b-dus-e-giris-akin-akca-v7ebl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SUYUN İZİNDE

Fazladan geldiğinde tanım; bu kule, su akıtmaya başladı 

Ve teleferik: yöneldi aşağıya, hızlı bir sapmayla! 

Sislerin içindeki görünmez kayaları kırmaya doğru! ...

: Bu ne sevgi! ne aşk! yürekten! …

Fark etmedik ‘böyle diri dostluk’ 

(Bakmadık: gördük! ! !) 

Böyle bir arı’lık! ..

Görmedik, içten.Döndük nice seferlerden; 

Batıdan doğarken, biz battık doğudan; 

Bilek şaşmadı, göz; hakikatten! 

Uçardı töz, köz olurdu; 

Bulutlardan inerdi faraş matkabı; 

Binerek, toprağın yeşerttiği

İlk çiy damlası-

   na! 

… Yine toprağa.

Ve böyle ortamda

Mor menekşeler bitti küçük papatyalar eşiğinde -

Daha gür, daha canlı, daha samimi.

Verimli:

Al! or’da işte! 

‘Yağmurun toprağa bereket verdiği’! ...

İçinde toprağın, beklemede; 

Ya (da)    nadas toprakta; 

Arılar! böcekler! 

Yıldızların tozu üzerinde serpiliyordu,

Yaşlı orman adım adım ilerliyordu; 

‘Sayısız kerelerce koşan; serpilen

Yeşillik’ iyice kök salmaya

Başladı ‘Yontma Taş Çağı’ndan; doğan ‘Dördüncü Zaman’dan; 

Bir buzul çağı mağrasından baş verdi “gökkuşağı

Neh’ri” mamutların gölgesinde 

Ve bir başka kovuğun göbeğine sokuldu -ormana,

(Çekirdeğine)    Hangi zamandan geldiği anlaşılmayan:

Kök salıyor ve artık, işte! 

Sarf ‘olmak’ için var olduğunu anlatan; 

(Kendisi kendisine, ayakta durmaya yeten) 

İhtiyaç, ölümü açıklamaya çekmeyeni; 

Yine de onu aradı ve sebep bulmadı: 

Ölümü buldu; Aradığını ve kendisi buldu onu:

Oraya böylece, ulaştı; 

Orası olmayandı, orası! 

-Yaşam orada kaynadı! 

(O adamın bulduğu yerdi orası, çabaların getirisi) 

: Karanlık yoktu içinde aydınlığın; 

(Kendi çabalayıp ulaştığına sevinemedi) 

Ne de sözü edildi 

Ferah’ın, 

Şer’ri amaçlamaya kanatlanan- şahlandı! 

Ve ne bir köprü vardı ikisinin arasında; 

Ve ikisine de tercüman olan,

Ne bir ‘yelken diriltilmez-enkaz’.

Yıldız tozlarının üzerinde dirilen ormanın içinde

İlerliyordu 11. gökyüzünde:

‘Patika-şeffaf yol’, doğmamıştı iyiyle kötü için

Ve doğmamıştı ‘ikisinin olmadığı bir vaha’ için! 

Garip yer denilebilirdi, burası

(Olduğu yer de değildi, onların) 

İki gövde kurmuştu başlangıçta bu ormanı -

Fark edilemeyen elle ya da göz ile:

İki kozmik sicim 

Ve minyatür yıldız tozlarından türeyen,

Kendini gerçekledi patika! 

‘Moonlight Sonata’ (Ay ışığı Sonatı)    yaşayan,

Onlar:

Şarkılar düzdüler:

Sözü olmayan bir melodi için…

Ki mantık yoktur ‘bu ‘uçmuş-dinleyen-kanatlılar’da da *

Ve hüzzamdı ‘klasik rock’ şakıyan kuşların ezgisi-

Yoktu ‘peynir ekmek-boşlamışlığı’! 

Değil serçeler onlara, güvercinler serçelere ders verdi:

Güvercinler, cama tos vuran: ıslak ekmeği cama sıçratan,

Yan yan baktı, korkudan -‘yengeç yürüdü’ gibi..

Ve yüreklendi serçeler:

*

SAHNEDEKİ ORKESTRA

Kel adam piyanoda, bu orkestrada

(Evrende bir yerde, bir çınar kovuğunun içinde) 

Ve şef: 

Deniz uyruğuyla ortaçağ savaş yelkenli gemilerinin –

(Toplarıyla döven denizleri, 

Üçgendir onların şapkaları, tokalıdır pabuçları) 

Kamarotlarının, tayfalarının 

Ve belki de zengin soylu azınlık sınıfının

-Toplamış o bu şekil, arkadan, saçlarını.

Şef, sıçrayıp duruyor her bir nağme geçişinde.

… On üç kadın:

Kısa saçlı birisi, yaşlıca ve genç (diğeri) ,

İki’deki ikinci (olan) : 

Erkek, dört; 

Kemanlarda hepsi, kadınlı erkekli:

Birden yayları gerildi bu ahşap çalgıların,

Ve görünür oldu kahramanlar:

“Kilise (korku)   -org’u olmayan”, org’dan beter oldu,

‘Sert piyano’ tuşları da; 

Kırılıyor onlar, bir fırtınada.

Siyah piyano ve onun siyah, küçük tuşları

Ve beyaz piyano tuşları; 

Siyah smokinler, papyonlar,

Çoraplar,ayakkabılar, mini etekler; 

Gömlekler beyaz; nota defteri, göze sokulmuş:

Beyaz o da; notalarsa yine siyah …

Onun (sayfaları)    dokusunda. 

Kahverengi kemanlar:

Teleferikte; simsiyah, en koyu; 

Değil hem de ama bazen, açık.

HORTUM AKROBATI

Açık havada, panayırdaydı kitleler, 

Ufak bir rock festivali bile tertiplenmişti

Yediler, içtiler; çimlere nakş oldular.

Ünlü sirk için gelmişti sırf, bazıları.

Onlar, çadıra girmeye başladılar.

Bu şenlik havasında, eğlence nidaları yükseldi

Binlerce kafa vardı, sandalyelere 

Sabitlenmiş, yükselen bacaklar üstünde.

Nereye bakacağını bilmez gibi şaşkın; 

Bir sağa, bir sola, gözler kaçkın.

Bir fırtına koptu dışarıda

Dışarıdaki insanlar koşuşmaya başladı

Topladılar yakınlarında ne varsa

Torun, torba …

Ve gökyüzü açıldı

Dört yönden birden yaklaştı

Dev bir tek hortum

Ve sirk çadırını içine aldı! 

Bir akrobat ip üzerindeydi.

Üç filin tek ayak üzerinde dört ayak durma

Gösterisi henüz bitmişti.

Düşerse ipten bu acrobat,

Düşecekti hortum çadıra! 

Bu adama yürümeyi bırakmama 

Görevi verilmişti.

Ve eğrilen geometride uzay kaydı

Sonsuz kereler bükülerek kendi çeperine,

Hortum buradan içeri kaçtı:

Kırk milyon yıl önceye gitti

(Ormanın adım adım yürümüş olduğu yere)

; Pireneler gibi dağ sistemleri oluşuyordu,

Dördüncü zaman başladı ve iki buçuk milyon yıl önce

Mamutlar koşturuyordu, onların birden soyu tükendi:

Adam gördü, bronz saçlı genç kızı izleyen adam:

Maymun gibi bir şeyler orta yerde, gölgeler gibi, vardı

Ot ve kök yiyordu bazıları, kimileriyse

Yabani meyva ile beslendi,

Gece oldu, ağaçlara çıktı onlardan bazıları,

Kimileriyse mağra kovuklarında

Soğuktan korundular.

Burası buzul devriydi.

Bir süre geçti; 

Ve buzlar ile kesilen onların yolları: 

Bir kısım yerleşti soğuk iklimlere

Ve yollarına devam etmediler

-Eteklerine kuruldular buz dağlarının.

Diğer bir kol ise

Sıcakça bölgelere yerleşti,

Tropikal meyvelere kucak açtı,

Yağışlı havayı sevdi.

Akan tek damlasında nilüferlerin-su ile özdeşik:

Dağ eteklerindekiler, Su Yer-kulesi adına çarpıştı, 

Su Buz-Kulesinde yaşarken; tropik mevki edinenler,

Yaşarken Su Yer-Kulesinde, Su Buz-Kulesine savaş açıp.

Böylece, taneler, akmayı Su-Yer-Kulesi’nden

Tatminkar öğrendiler, edinimi sürdürdüler …

-

açıklama:

Uçmuş dinleyen-kanatlılar: Ay Işığı Sonatı dinleyen sevgililer 

(Güvercinlerden serpilen serçeler)', 'SUYUN İZİNDE Fazladan geldiğinde tanım; bu kule, su akıtmaya başladı  Ve teleferik: yöneldi aşağıya, hızlı bir sapmayla!  Sislerin içindeki ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":168,"source_url":"https://www.antoloji.com/aca-69-syk-5b-dus-e-giris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dediler', 'dediler-mehmet-fatin-baki-56ee9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aradım dün gece tâ subha kadar köyde seni

Senelerdir o güzel kız köye girmez dediler.

Ararım haşre kadar var diye kendimde seni,

O güzel sendeki boş gövdeye girmez dediler.

Feilâtün    feilâtün     feilâtün     feilün

.  .   /   /   .  .   /   /   .  .  /   /   .  .   /', 'Aradım dün gece tâ subha kadar köyde seni Senelerdir o güzel kız köye girmez dediler. Ararım haşre kadar var diye kendimde seni, O güzel sen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dediler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimiz', 'i-kimiz-mehmet-fatin-baki-6f1ph', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Keyf ararken serde bulduk dinç hayâtın şevkini

Tatmış olduk yârelinden âb-ı hayvân zevkini.

Beklemezken başka yerden başa bir keyf sevkini

Güçtü lâkin kalpte bulduk can ve canân zevkini.

Son bahârdan sonra gördük, nevbahârın nevkini

En nihâyet kışta tattık vahşi hayvân zevkini.

Âb-ı hayvân = efsânevi ölümsüzlük suyu, âb-ı hayat

Nevkini = ucunu, sonunu 

Fâilâtun     fâilâtun     fâilâtun     fâilun

/  .   /   /    /  .   /   /    /  .   /   /    /  .   /', 'Keyf ararken serde bulduk dinç hayâtın şevkini Tatmış olduk yârelinden âb-ı hayvân zevkini. Beklemezken başka yerden başa bir keyf sevkini G...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ikimiz-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yagmur Dinince', 'yagmur-dinince-adem-kunt-gy2a1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmur güzel yağıyor,hava serince,

İçimde bir his doğar yağmur dinince…

Buram buram,misk gibi bir koku,

Bir iklim yayılır içime yağmur dinince…

Temizlenir kainat,güneşin pusu gider,

Hayat yeniden başlar yağmur dinince…

Çiçek açar,kuşlar uçar,dağların sisi gider,

Neşe gelir,hüzün gider yağmur dinince…

İki ezeli aşık erer vuslata,

Bakışlar dile gelir yağmur dinince…

Damlalar zincir vurur zalim hasrete,

Gözler pınar olur yağmur dinince…

Gönülden gönüle dereler çağlar,

Kalplere su serpilir yağmur dinince…

Gözler vuslatın deminde biteviye ağlar,

Eller kenetlenir yağmur dinince…

Seninle yaşanacak bir aşkın öyküsünü,

Bülbül güle anlattı yağmur dinince…

Unuttu o zaman verdiği sözü,

Gül bülbülü aldattı yağmur dinince…

Yağmur yağıyor bugün kaldırımlar ıslanmış,

Nerde şimdi seninle o mehtaplı akşamlar…

Nerede o kokun,nerde o dokunuş,

Ne mehtap,ne koku senden eser kalmamış…', 'Yağmur güzel yağıyor,hava serince, İçimde bir his doğar yağmur dinince… Buram buram,misk gibi bir koku, Bir iklim yayılır içime yağmur dinin...', ARRAY['Türk Edebiyatı','Şiir','Adem Kunt']::text[], 8.5, '{"poet":"Adem Kunt","poet_slug":"adem-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yagmur-dinince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Köşelerde', 'bos-koselerde-mehmet-fatin-baki-0w2mc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel göstereyim gel sana zevk bahçesi nerde

Dün baktığımız pencereler durduğu yerde

Bir kez daha  hiç bilmediğin zevki hayelle

Meçhulleri ilk tattığımız pencerelerde.

İçten gelen ilk söz bile her derde devâdır

Gel gör güzelim burdaki bir başka hevâdır

Kalbim bu muhabbetler için kuytu  mevâdır

Gel bir daha hemkeyf olalım boş köşelerde.

Hevâ = tutkunluk hoşlanma

mevâ = mekan,  mevki, yer

Pencereler = hayata bakış açıları

Boş köşelerde = fırsat buldukça tenha yerlerde 

Mefûlü   mefâilü   mefailü   feûlün

/   / .  .   /   / . .   /   / . .   /   /', 'Gel göstereyim gel sana zevk bahçesi nerde Dün baktığımız pencereler durduğu yerde Bir kez daha  hiç bilmediğin zevki hayelle Meçhulleri ilk...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bos-koselerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdedir', 'nerdedir-mehmet-fatin-baki-7lt9p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Varsa kulüp başkanı  gurbette, imâm nerdedir.

Geçti mübârek Ramazan, bizde siyâm nerdedir.

Saklı durur  rafta,  lûğatlarla berâber, temiz

Bir iki Kur’ân  cüzü, furkânı kelâm nerdedir.

Âlem-i fânîdeki insanda hasâil gibi

Olsa bir aşk tutkusu, Allâha garâm nerdedir.

Köyler uzaklaştı da gündüz gece hep yoldayız

Camiye vakt kalmadı, salâta kıyâm nerdedir.

Çarşıda ahlâka  riâyet bile kaybolmada,

Şimdiki gençlerde edep nerde, zimâm nerdedir.

İnsanı çok yordu hayât kaygısı, hiç şüphesiz

Lûtfile göster bana dünyâda arâm  nerdedir.

Siyâm = oruç

Furkânı kelâm = âyetler

Hasâil = hasletler, huylar, tabiatlar

Garâm = olağan üstü düşkünlük, sevda 

Salâta kıyam = namaza durma

Zimâm = ar,  nâmus

Arâm = rahatlık, dinlenme

Müfteilün   müfteilün   müfteilün   failün

/  .  .   /      /  .  .   /     /  .  .   /     /  .   /', 'Varsa kulüp başkanı  gurbette, imâm nerdedir. Geçti mübârek Ramazan, bizde siyâm nerdedir. Saklı durur  rafta,  lûğatlarla berâber, temiz Bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nerdedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk İşte Bu Benimki', 'cocukluk-i-ste-bu-benimki-derin-oger-ckad7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sesin kulağımda çınlardı

Sevgin kovaladıkça masum gülüşlerimi

Sanki yüreğim ocağın üstüne düşmüşcesine

Yana yakıla  aramak isterdi de seni

Çocukluk işte bu benim ki

Bazen kötü günlerime karlar yağardı

Bazen gözlerim güneşin batışını sen sanırdı

Sonra gece sonra gün örterdi üstünü

Bir yürek taşıyamazdım ya seni

Çocukluk işte bu benim ki

Kimi soğuk toplayıp rüzgâr eserdim

Kimi yıldız yıldız uzaklara düşerdim

Ayın etrafına  kurulup hayale daldığımda

Çok mu düşünürdüm ne seni ki

Çocukluk işte bu benim ki

Yalanlarım da olurdu kış soğukluğunda

Seni unutmak için el sohbetlerine daldığım da

Çaresizliği görüp içimin acısıyla ağladığımda

Sağdan soldan sen toplarmışım da off

Çocukluk işte bu benim ki

Durgun bir suydu adım

Hani göğsünde nilüferler buğulanan

Sen konuşmazdın ben de susardım

Bazı çayımın yudumu haşlayınca nefesimi

Yangının suya kavuşmayı özlediği gibi

Özlerdim özlerdim de  seni

Çocukluk işte.....................................', 'Sesin kulağımda çınlardı Sevgin kovaladıkça masum gülüşlerimi Sanki yüreğim ocağın üstüne düşmüşcesine Yana yakıla  aramak isterdi de seni Ç...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cocukluk-iste-bu-benimki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce', 'dusunce-adem-kunt-jdudf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölüm,

çok yakın…

Elimde,

avucumda..

 takiptedir daim,

gölgem gibi…

taşıyorum onu,

omuzlarımda…

Yok olmak,

nasıl şey? 

Hepten,

aniden…

Bir daha,

yürüyememek,

yollarda…

Bakamamak,

uzaklara…

Seni görememek,

nasıl? 

Kaleme,

kağıda,veda…

Şiire,

Şarkıya,

aşka,

yaşama…

Nasıldır veda,

sahiden? ..', 'Ölüm, çok yakın… Elimde, avucumda..  takiptedir daim, gölgem gibi… taşıyorum onu, omuzlarımda… Yok olmak, nasıl şey?  Hepten, aniden… Bir da...', ARRAY['Türk Edebiyatı','Şiir','Adem Kunt']::text[], 8.5, '{"poet":"Adem Kunt","poet_slug":"adem-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dusunce-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır Tutalım', 'sir-tutalim-mehmet-fatin-baki-kg08a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bûse-i leb çıktı dehândan dü-lisân olmadan

Gel bunu nîhân tutalım halka iyân olmadan.

Nefs-i revânın kısa nalânı figân olmadan

Gel bunu bir sır tutalım halka iyân olmadan.

Buse-i leb = dudaktan öpme 

Dehân = ağız

Dü-lisan = iki dil

Nihân = gizli

İyân = açık, belli

Nefs-i revân = rûh

Nalân = inleme 

Figân = bağırarak ağlama

Müfteilün    müfteilün   müfteilün   fâilün

/   .   .    /   /   .   .    /   /   .   .    /   /  .   /', 'Bûse-i leb çıktı dehândan dü-lisân olmadan Gel bunu nîhân tutalım halka iyân olmadan. Nefs-i revânın kısa nalânı figân olmadan Gel bunu bir ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sir-tutalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utandım', 'utandim-mehmet-fatin-baki-d8kmo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Utanmak iyi hasletse, bu dünyâdan utandım

Dünen yaptığımız herze için nâ’dan utandım. 

Ya bir sürçü lisandan kime ettikse eziyet

Edebsiz söz için yâr ile gavgâdan utandım.

İlaçsız bazı köylerde kadınlarla çocuklar

Düşüp hastalanırken, tüm ettibbâdan utandım.

Siyâsetçilerin kasd ederek meclis önünde

Vatandaşları haksız yere şekvâdan utandım.

Ezelden beri var banka soyanlar ammâ ve lâkin

Bu hortumcuların yaptığı yağmâdan utandım.

                       

Haslet = huy, karakter

Herze = boş laf

Nâ = ney

Etibbâ = doktorlar

Şekvâ = şikayet

Mefâîlü      mefâîlü      mefâîlü      feûlün

.   /   /  .   .   /   /  .     .   /   /  .     .   /   /', 'Utanmak iyi hasletse, bu dünyâdan utandım Dünen yaptığımız herze için nâ’dan utandım.  Ya bir sürçü lisandan kime ettikse eziyet Edebsiz söz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/utandim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep mi?', 'hep-mi-seref-yildirim-r3t8s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1

hep mi kaybedecek dürüstler

altta kalacak namuslular

kahrolacak yoksullar 

ağlayacak mazlumlar

kandırılacak saflar

kalleşçe vurulacak yiğitler

aldatılacak aydınlık beyinler

kanayacak temiz yürekler

parçalanacak umut dolu duygular

ezilecek emeklerin de emekçiler

işkence görecek düşüncelerinde devrimciler

sömürülecek vurdum duymazlıkla halkım

hep mi? hep mi? hep mi? .....................

2

hep mi kazanacak sahtekarlar

üste çıkacak namussuzlar

kahredecek zenginler

ağlatacak zalimler

kandıracak kurnazlar

ödüllendirilecek korkaklar

aldatacak karanlık beyinsizler 

kanatacak kirli yüreksizler

parçalayacak duygusuzlar

ezecek tüketici ağalar

işkence yapacak düşüncelere büyük patronlar 

sömürecek gönül rahatlığıyla komprador aristokratlar

hep mi? hep mi? hep mi? ..............

3

hayır! ......hayır……..hayır…….

çıkacak birileri yeter artık diyecek zulmedenlere

yarınlarda mutluluklar getirecek uluslara

hep mi sorusu kalacak çok gerilerde

ta ki bir daha hatırlanmamacasına……………..

13.06.2004', '1 hep mi kaybedecek dürüstler altta kalacak namuslular kahrolacak yoksullar  ağlayacak mazlumlar kandırılacak saflar kalleşçe vurulacak yiği...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yıldırım']::text[], 8.5, '{"poet":"Şeref Yıldırım","poet_slug":"seref-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hep-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece.!', 'bu-gece-akin-samiloglu-ilqjs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün biraz duygusalım..Aslında herzamanki gibi. 

Fakat bugün apayrı içimdeki hüzün... 

Belki yalnızlığımın sesi yüreğimde..Aslında herzamanki gibi.

Fakat bugün apayrı gözlerimin yalnızlığı.. 

Haykırmak istedim,haykıramadım.! 

Şaşırdım.! Şaşkınlığım kendimemi yoksa hayatamı anlayamadım.... 

Paylaşmak istedim.Bir an olsun sıcak bir merhaba ile... 

Hava çok sıcak ve boguk.. 

Duvarlar üzerime üzerime geliyor... 

Ne oturasım var saatlerce burada,nede yürüyesim bu tozlu dar koridorda.. 

Tüm kapıları açtım..

Sanki biri gelecekmiş gibi. 

Neden gözlerim bir arayış içerisinde..? 

Yüregime soruyorum,ruhuna sor diyor...Bir çıkmazdayım.

Ellerim nereye giyor? 

Parmaklarımı kırmam mı gerek? 

Yoksa düşüncelerimi yok mu saymalıyım.? 

İçim daralıyor.. 

Bir damla ile akacakmış gibi hayatım.

Kendime acımaktan utanıyorum.... 

Yaz yaza bildiğin kadar. 

Yolum üzeri zaman taşlarıyla dolu... 

Kollarımı savursam kime deyecek acaba? ... 

Ne yapmalı bilmiyorum.

Tüm anılar üzerime üzerime geliyor..Eziliyorum.! 

Kurtuluşum yüregimdeki gözdemi acaba..

yoksa bir avuç..sadece bir avuç papatya kurusundamı.? 

Dar ve tozlu bir yoldayım bu gece...

Dar ve tozlu...', 'Bugün biraz duygusalım..Aslında herzamanki gibi.  Fakat bugün apayrı içimdeki hüzün...  Belki yalnızlığımın sesi yüreğimde..Aslında herzaman...', ARRAY['Türk Edebiyatı','Şiir','Akın Şamiloğlu']::text[], 8.5, '{"poet":"Akın Şamiloğlu","poet_slug":"akin-samiloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bu-gece-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiğ Tanem', 'cig-tanem-adem-kunt-317vw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yediveren baharı konuyor pencereme,

kuşlar söylüyor şarkımızı her sabah,

uyandırıyor beni…

Ne zaman yağmur yağsa,

her damla sen oluyorsun…

Ama düşüp yere hep,

kayboluyorsun…

Bir sabah olsa,

seni arıyorum yanımda,

yoksun…

Perdemi aralayıp,

açıyorum penceremi,

baharı müjdeleyen yaprakların üzerinde,

bana gülümsüyorsun…

Çiğ olmuşsun yapraklarda…

Güneşle buhar olup sonra,

kayboluyorsun…

Bu aşkın en zalim yanıdır yalnızlığım…

Ama aşk değil bu,

aşık değilim ki ben,

seni hiç sevmedim ki…

Sen de beni,

öyle değil mi,çiğ tanesi? ..

Ama nereye baksam sen…

Sen ve sensizlik…

Bir varsın,bir yokluk…

Allah’ım bu çılgınlık…

Bu kaçıncı bahardır sensiz,

akasyaların bu kaçıncı açışı? ..

Kaç yağmur damlası düştü buralara sensiz,

kaç çiğ tanesi? ...

Kaç yıldız kaydı biliyor musun,

kaç dilek tuttum? ...

Birinin yıldızı kayıyor,

göçüyor dünyadan,

ben dileği,yani seni tutuyorum…

Yıldızlar çok,

bitmez ki kaya kaya…

Okyanuslarda bilir misin,

kaç damla yağmur var,

kaç çiğ tanesi? ...

Ben seni öyle sevdim ki,

biliyorum sen de beni,

yıldızlar kadar çok,

derin okyanuslar gibi…', 'Yediveren baharı konuyor pencereme, kuşlar söylüyor şarkımızı her sabah, uyandırıyor beni… Ne zaman yağmur yağsa, her damla sen oluyorsun… A...', ARRAY['Türk Edebiyatı','Şiir','Adem Kunt']::text[], 8.5, '{"poet":"Adem Kunt","poet_slug":"adem-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/cig-tanem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum', 'sustum-tansel-yegen-cmk3s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'güzel zamanlardı burada geçirdiğim 

eleştirdiğinizde hatalarımı anlayıp gülüp geçtiğim 

bazen kızıp kapının eşiğine geldiğim 

birkaç sıcak el yardımıyla gözyaşımı sildiğim 

ama bir türlü gidemediğim.. 

sen.. 

okudukça bir öne geçtiğim 

okudukça gerilediğim 

yüreğimde hissettiğim 

hüzünlü zamanlarımdı 

yüzdüm dün gece denizinde 

her kulaçta battım nefessiz kaldım 

indim diplerine 

işte orada gördüm 

yüreğinde sakladığn insanları 

kaç kadının vardı sayamadım 

kimlere nelere kahretmedin 

lanetler yağdırmışsın kadere 

damgasını vurmuş yüreğine belki de 

sadece birkaçı batmış denizinde 

ben ise kaybolmuş ruhunu bulamayan 

küçücük bir balıktım sadece 

büyüksün 

çok büyüdün yüreğimde 

sustum...', 'güzel zamanlardı burada geçirdiğim  eleştirdiğinizde hatalarımı anlayıp gülüp geçtiğim  bazen kızıp kapının eşiğine geldiğim  birkaç sıcak e...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yegen']::text[], 8.5, '{"poet":"Tansel Yegen","poet_slug":"tansel-yegen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sustum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkardım', 'korkardim-banu-aka-bagoc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uçup gidersin diye korkardım

Bir nefeslik konduğun avuçlarımdan

Gülüşün solar mı diye korkardım

Yüzüme baktığında

Gelmezsin diye korkardım

Çaresiz çağırdığımda

	

                Karanlıktan da çok  korkardım ben

	Şimdi karanlıklarda kaldım.', 'Uçup gidersin diye korkardım Bir nefeslik konduğun avuçlarımdan Gülüşün solar mı diye korkardım Yüzüme baktığında Gelmezsin diye korkardım Ç...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/korkardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meleklerle', 'meleklerle-banu-aka-j39lp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeşil bir bahar akşamı

Gitmiştin

Beyaz bir kış akşamı

Döndün

İçimdeki kelebeklerle gitmiştin

Kolunda meleklerle

Döndün', 'Yeşil bir bahar akşamı Gitmiştin Beyaz bir kış akşamı Döndün İçimdeki kelebeklerle gitmiştin Kolunda meleklerle Döndün...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/meleklerle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Geleceksin...', 'geri-geleceksin-i-brahim-ethem-bingul-14f01', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdanın dipsiz kuyularına attın

Hem beni hem hayatımı yıktın

Gönlüme,gözüme ışıktın

Çektin gittin dünyamı kararttın.

Yalnız seni sevdim

Sevmekten başka ne yaptım

Bir tek sevgilim demeni bekledim

Yusuf değilim kuyuda kaldım.

Bunun hesabını vereceksin

Nefretimden titreyeceksin

Pişman olup geri geleceksin

İşte o zaman zindanlara gireceksin.



www.iebingul.com', 'Sevdanın dipsiz kuyularına attın Hem beni hem hayatımı yıktın Gönlüme,gözüme ışıktın Çektin gittin dünyamı kararttın. Yalnız seni sevdim Sev...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/geri-geleceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Sonra Gitseydin..!', 'sonra-gitseydin-hasan-basri-kale-uszti', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çocuksu bir mutluluktu 

gelişin..

ağlamaklı bir tebessümle

gittin

sadece...

keşke

önce

yüreğime assaydın da

ayrılığın hüznünü

sonra gitseydin

istediğin yere...

.....

...........

................

...................ne olurdu sanki..!', 'çocuksu bir mutluluktu  gelişin.. ağlamaklı bir tebessümle gittin sadece... keşke önce yüreğime assaydın da ayrılığın hüznünü sonra gitseydi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sonra-gitseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğmalı Bu Sensizlik...!', 'dogmali-bu-sensizlik-gulay-morgul-afzbp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüzünlerim

Yalnızlığımın ikiz kardeşi

Yokluğunsa acılara gebe

Doğmalıydı bu sensizlik 

Sancısız bir operasyon olmalı

Genel, lokal yada epidural

Seni bulmalıydım doğum sonrası

Ve bir daha sensizliğe gebe kalmamak için

Bağlatmalıydım tüm kordonları...', 'Hüzünlerim Yalnızlığımın ikiz kardeşi Yokluğunsa acılara gebe Doğmalıydı bu sensizlik  Sancısız bir operasyon olmalı Genel, lokal yada epidu...', ARRAY['Türk Edebiyatı','Şiir','Gülay Morgül']::text[], 8.5, '{"poet":"Gülay Morgül","poet_slug":"gulay-morgul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dogmali-bu-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğinde ki Damlada İstanbul Gözyaşı', 'yureginde-ki-damlada-i-stanbul-gozyasi-atakan-aktas-vxof0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamın her köşesinde,

Üzengeç göz yaşları saklıyoruz hep. 

Hikayeler biriktiriyoruz zulamızda.

Hüzün tohumları atıyoruz ömür bahçemize, 

Bize kalansa yağmur gibi gözyaşları oluyor biraz... 

Ordaki orda kalsın.

Yüreğindeki damlaları sil ve ekrana bakarak gülümsemeyi dene 

Bak küçük de olsa birşeyler değişmiş olacak.

Yüreğini ferah tutmayı dene,

Gecenin seyrine bırak gözyaşlarını.

Yaşamın içindekiler  24 ten öncesinde kalsın.

Hayatı bugünde yaşamayı dene

Unutulacak o kadar çok şey var ki...

Yarınlar hep meşgul ediyor bizleri.

Yaşam keşke bukadar zamanla düşman olmasaydı 

Herşeyin tadını keyfiyle çıkarabilseydik 

Ama yarına kaç var bilmiyoruz...

Paylaşılmamış tadları hep yarınlar çalıyor

Hayat kimbilir ne zaman istanbula düşürür 

Ben kaç yağmur damlası asılmam lazım

Kaç rüzgarla barışmam lazım bilinirmi', 'Yaşamın her köşesinde, Üzengeç göz yaşları saklıyoruz hep.  Hikayeler biriktiriyoruz zulamızda. Hüzün tohumları atıyoruz ömür bahçemize,  Bi...', ARRAY['Türk Edebiyatı','Şiir','Atakan Aktaş']::text[], 8.5, '{"poet":"Atakan Aktaş","poet_slug":"atakan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yureginde-ki-damlada-istanbul-gozyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevap,düşününce..', 'cevap-dusununce-akin-akca-7n4yi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dalgalar gelirken konuşur kurulmuş set’ler; 

Bahar gelip çiçek, doğa, verince kuşlar öter.

Yine de tartışılmaz ondan, bundan ya

da zevkler: Bir havada korku var, o bekler.

Lafın fakat dönersek baş yerine:

Bekleyen bekler, kurulur duvarlar; 

Sadece dalgalar gelirken

Konuşur onlar.

Bir mermiyi bekleyen mermidir duran; 

tepkideki korkudur, hareket etmeyen; 

Coşkuya kavga giden, kanamaya meyillidir:

Aynaya bakar, camda kan izi bırakır

Ayna kırılmayan, darılır: yoktur geriye kalan, 

or’daki tek şey, oradaki; durup düşünen, kalbur üstü; 

Elek tutmayan, eli -onun hatta gerisinde

De kendisi …', 'Dalgalar gelirken konuşur kurulmuş set’ler;  Bahar gelip çiçek, doğa, verince kuşlar öter. Yine de tartışılmaz ondan, bundan ya da zevkler: ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cevap-dusununce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın Öncü Depremleri', 'sevdanin-oncu-depremleri-nesrin-gocmen-gsegl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkın altın vuruşu

Günbatımı günâhları

Ya seher vakti

Uykusuz geceler

Kızıldeniz ikindisi? 

Ya her gün doğan güneşin

İlk kez gülümsemesi

Ve de duyulmak istenenin

Söylenmemesi

Mi

Sevdanın

Öncü depremleri? 

14 Haziran 2004', 'Aşkın altın vuruşu Günbatımı günâhları Ya seher vakti Uykusuz geceler Kızıldeniz ikindisi?  Ya her gün doğan güneşin İlk kez gülümsemesi Ve ...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdanin-oncu-depremleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüme', 'gulume-burhan-kucuk-goa53', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülüme

Sadece yazın mı açıyorum sanıyorsun? 

Sen benim çiçeğim değil misin? 

Kokun,sadece güneşten mi biliyorsun? 

Ya güneş açmaz ise 

Ya caddeler hep karla kaplı olsa

Bu şehri puslu duman sarsa

Sen benim çiçeğim değil misin? 

Kanma sahte güneşlere

Kanma sahte yağmurlara

Ben pervasız bahçevan

Dikenlerin bile olsa

Sen benim çiçeğim değil misin? 

Burhan KÜÇÜK

Kdz.Ereğli-14.06.2004', 'Gülüme Sadece yazın mı açıyorum sanıyorsun?  Sen benim çiçeğim değil misin?  Kokun,sadece güneşten mi biliyorsun?  Ya güneş açmaz ise  Ya ca...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gulume-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçmalığa Övgüler-02', 'sacmaliga-ovguler-02-oguzkan-bolukbasi-qzlor', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir kırılmış yanı var

bu aşkın penceresinde güneş arayan yüreğin

tümsekler mi sarsan duygularımı

bilmediğim bu yolda

gözlerinden geçtim 

başka bir sahneye

ne kadar bilinmezlik varsa

ya da acı dedikleri 

yakıcı bir sıcaktan boşalan

tasallutlar

çekildi sineye

ne kaldıysa yaşamamızı sağlayan

kırıntılarda 

dikkatle topla avuç içinde

sakla

yüreğinin bir yerinde

seni sevmeye gelmediğim bir günde

toprağımın üzerine serp

hoşça kal yalnızlığım', 'bir kırılmış yanı var bu aşkın penceresinde güneş arayan yüreğin tümsekler mi sarsan duygularımı bilmediğim bu yolda gözlerinden geçtim  baş...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sacmaliga-ovguler-02-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyümün yoluna', 'koyumun-yoluna-can-i-rfan-ab1hg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Köyümün yoluna 

asılı kaldı kuşlar.

Ecelerim emmilerim kaldı gözlerimde.

Şimdi öcüler şimdi viraneler,

  çalakaşık giden bu evler…

Ötleğengiller kurmuşlar

    harmanlara,tarlalara,bağa bahçeye

                    tekkelerini.

Tambura eşliğinde yapıyorlar ibadetlerini.

Köyümün yoluna asılı kaldı kuşlar.

     

 Kalmamış pulluğun izleri

 İmeceler çekilmiş pazarlara saatlik

 Sucuk fabrikalarını beklemekte.

 Düvenler asılı,

         kerpiçten örülü duvarları işlemekte.

         Akmaz oldu çeşmeler,

         Börtüböcekler türkü söyler

         Antika oldu testiler 

         Sıra,sıra raflara dizildiler.

   İneklerin bile dolaşır ayakları,

   neredeyse süt içecekler

Yerden verilen selam

 oldu köyümde dolar.

Kolalar doldurdu her yanı

 yumurtası hayal.

Kolalar,kolalılar….

Köyüme girdi Amerikalılar.

Terk etti alnı ter

Göbekten akar artık ter.

Ecelerim emmilerim kaldı gözlerimde.

Şimdi öcüler,şimdi viraneler,

                  çalakaşık giden bu evler.

Köyümün yoluna,

          asılı kaldı kuşlar.', 'Köyümün yoluna  asılı kaldı kuşlar. Ecelerim emmilerim kaldı gözlerimde. Şimdi öcüler şimdi viraneler,   çalakaşık giden bu evler… Ötleğengi...', ARRAY['Türk Edebiyatı','Şiir','Can İrfan']::text[], 8.5, '{"poet":"Can İrfan","poet_slug":"can-i-rfan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/koyumun-yoluna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah De de, Bekle Gör', 'allah-de-de-bekle-gor-i-smet-barlioglu-tzmxy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derdin varsa üzülme; 

Allah de de, bekle, gör.

Dert altında ezilme; 

Allah de de, bekle, gör.

İşlerin ters gidince; 

Dermanların bitince; 

Kabin yanıp tütünce; 

Allah de de, bekle, gör.

İstedinmi verilir,

Tez elden gönderilir,

Ölmüş olan dirilir,

Allah de de, bekle, gör.

Çözülür müşküllerin,

Doldurulur ellerin,

Bülbül olur dillerin,

Allah de de, bekle, gör.

O kulunu terketmez,

Bekledinmi bekletmez,

Tek saniye gecikmez,

Allah de de, bekle, gör.

Hikmet diyor; sen iste,

Yollanır tek nefeste,

Öten kuş ol kafeste,

Allah de de, bekle, gör.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 401-402/412)', 'Derdin varsa üzülme;  Allah de de, bekle, gör. Dert altında ezilme;  Allah de de, bekle, gör. İşlerin ters gidince;  Dermanların bitince;  K...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/allah-de-de-bekle-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler Armonisi 14', 'guzel-sozler-armonisi-14-bayram-tunca-wgt9d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşünmek madem biz kullara mahsus

Ben de hep O’nu düşünürüm bahusus

ADEMOĞLU/23.10.2003-10.23

İçimdeki aşk ateşin, tam demir tavında

Ne olur bugünkü gibi bekletme yarında

B. Tunca/01.07.2003-01.07

Yediğim darbelerin hiç haddi hesabı yok

Tuzu kuru dostların çilemden haberi yok

ADEMOĞLU/23.10.2003-10.23

Güneş ışığını gören karlar, ılgıt ılgıt eridi

Leyla’sını görenlerin içindeki buzlar eridi

ADEMOĞLU/03.07.2003-11.07

Bugün giydiğim pantolonun da cebi delik

Daha aybaşı metelik arıyorum fellik fellik

ADEMOĞLU/01.07.2003-01.07

Sevilmek istiyorsan, sevmesini bileceksin

Yaratılanları sev ki, sahibi de seni sevsin

B. Tunca/06.06.2003/16.16

Kuzu postuna bürünüp ayı rolünü oynadın

Bürütüs gibi arkamdan vurmayı doymadın

ADEMOĞLU/23.10.2003-10.23

Gece/gündüz aşk imtihanındayım her lahsa

Her an kaybetme riskim var Allah muhafaza

B. Tunca/06.06.2003/16.16

Her akşam, imtihanla yatıp, imtihanla kalkarız

Her an imtihan stresinden ecel terleri dökeriz

B. Tunca/04.09.2002/10.54

Olmasaydı

Bayram der olmasaydı kadın, hiç olur muydu tadın

Nebimize sevdirilenlerden üçten birisi olmuş kadın

B. Tunca/01.10.2001-13.30

İnan ki hayal kırıklığım cam kırıklarından daha çoktur

Teselli edecek senden başka da vefalı bir dost yoktur

ADEMOĞLU/23.10.2003-10.23', 'Düşünmek madem biz kullara mahsus Ben de hep O’nu düşünürüm bahusus ADEMOĞLU/23.10.2003-10.23 İçimdeki aşk ateşin, tam demir tavında Ne olur...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/guzel-sozler-armonisi-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikmetler', 'hikmetler-i-smet-barlioglu-6zgn6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Pamuk neden yumuşak, demir neden çok serttir? 

Sırları çözebilmek nice büyük devlettir.

Herşey yaratılmıştır en güzel biçimiyle,

Yaratılmak, var olmak; bu ne büyük hikmettir.

Karıncayı incele mikroskopun altında,

Gör ki karıncadaki ne benzersiz haşmettir.

Nefes diye alınan hava işler demire,

Bir nefeslik havada bu ne korkunç kuvvettir.

İçilen su kudursa dayanmaz vapur, mapur,

Bu zerreye saklanmış nasıl garip heybettir.

Bir küçük böcek bile dayanır ne şartlara,

Ömrü sürdürmek için bu nasıl bir gayrettir.

Balık bile bir başka balık ile çiftleşmez,

Bu cinsler arasında ne sınırlı iffettir.

Tavuk civcivi için karşı gelir aslana,

Bu şefkate gizlenmiş ne anlamlı hiddettir.

Sinek bile sinekle çiftleşir mevsiminde,

Nesli sürdürmek için ne zorlanmış şehvettir.

Zalim ile mazlumu yaşatır ayni güneş,

Bu nasıl adaletli, ne cömertçe rahmettir.

Damlardan düşen bebek salimen iner yere,

Bu alınyazısına ne güzel riayettir.

Bir yıldaki dört mevsim hiç olmuyor üç ya beş,

Bu hükümran olmakta ne eşsiz dirayettir.

Aslan hamleden önce ihtar eder kükreyip

Bu bir vahşi kavgada düpedüz adalettir.

Barlıoğlu diyor ki; sözlerimde hilaf yok,

Her sözümde yer alan mıtlaka bir hikmettir.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 403-405/412)', 'Pamuk neden yumuşak, demir neden çok serttir?  Sırları çözebilmek nice büyük devlettir. Herşey yaratılmıştır en güzel biçimiyle, Yaratılmak,...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hikmetler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Düğüm', 'bes-dugum-zulfikar-yapar-kaleli-v8im5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

En büyük sevdayı zincirle, gemle,

Günü düğümledim, tam beş düğümle,

Gözümden beslenen çayı güğümle,

Buluta yükledim, nemi gizledim.

Gönlümün sultanı seni özledim.

Zirvelerin tutkunuyum inemem,

Kuru kavak gölgesine sinemem,

Bir büyük savaşa girdim, dönemem,

Yara bere aldım, emi gizledim.

Gönlümün sultanı seni özledim.

Gönül sevdalanmış, neylesin ünü,

Dere kenarında yitirdim günü,

Bulutta gözyaşı, sahrada yönü,

Kuşun kursağında yemi gizledim,

Gönlümün sultanı seni özledim.

Mazluma kol kanat olamıyorum,

Denizlere daldım, dolamıyorum,

Bayramlarda bayram, bulamıyorum,

Eğlenceyi toyu, demi gizledim.

Gönlümün sultanı seni özledim.

Geceler kaybolur, gün mutlak doğar,

Hakikat yeşerir, zulmeti boğar,

Alemi kuşatır, her gönle sığar,

Hem güneşi, hem gölgemi gizledim.

Gönlümün sultanı seni özledim.

Amel işle, gönül aşkla beslenir,

Koç vatana kurban için süslenir,

Gün buluta, bulut dağa yaslanır,

Şu küçük yüreğe gemi gizledim.

Gönlümün sultanı seni özledim.

Hevesim kalmadı yeşilde, akta,

Tüm hayalim saklı sarı yaprakta,

Kara gün içinde, kara toprakta,

Karanlık gecede cemi gizledim.

Gönlümün sultanı seni özledim.', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' En büyük sevdayı zincirle, gemle, Günü düğümledim, tam beş düğümle, Gözümden beslenen çay...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bes-dugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama Yıkıldım..!', 'ama-yikildim-i-brahim-dikmen-2-06cso', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mutluluk................! 

peşinden koşturdum,

mutluluk senin.

özlemlerimi,

yüreğimde gizledim.

Aradım....................! 

kaf dağında,

aradım seni.

zümrütü anka,

misali.

Buldum.......................! 

aradığım aşkı,

buldum sonunda.

bedenimi yakan,

o''sıcaklığında.

Yaşadım....................! 

her zerresini,

yaşadım doyasıya.

alev alev,

yandım kollarında.

Tattım.........................! 

adam gibi sevdim,

tattım ben aşkı.

senin için yazdım,

tüm şarkıları.

Kırıldım......................! 

sebebini sorma,

kırıldım aşka.

yenik düştüm yarim,

çaresizim sorma.

Ama yıkıldım...............! 

hep sevdim,

sevdim ama yıkıldım.

ölesiye aşkla,bağlandım,

lakin sarsıldım.', 'Mutluluk................!  peşinden koşturdum, mutluluk senin. özlemlerimi, yüreğimde gizledim. Aradım....................!  kaf dağında, ar...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ama-yikildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nurten Altınok ve Şiirsel Dünyası', 'nurten-altinok-ve-siirsel-dunyasi-nurten-altinok-oz0wm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'TAHLİL: 1 Nurten Altınok ve Şiirsel Dünyası 

Kayıt Tarihi: 12.06.2004; Ekleyen: Mustafa Ceylan 

''Huzur Limanı'' kitabı üzerine bir ''tahlil'' 

Irmak Şairi 

Nurten Altınok (0536 563 82 22 Kitap isteme GSM)

Ve 

“Huzur Limanı” 

Mustafa CEYLAN 

17 veya 20 bin civarında şairin ve şiirin “tozu dumana kattığı” bir sanal ortamda tanıştım Nurten ALTINOK’ la… Bilgisayar ortamında tanışmak nasılsa öyle işte… “Huzur Limanı” isimli bir kitap yayınladığını öğrenmiştim. Adresimi verdim, istedim “Huzur Limanı” nı. Bir de baktım ki ertesi gün kitap kargodan elime tutuşturuldu. Hemen telefonuna mesaj attım.Dedim (dost, “HUZUR LİMANI” kitabınızı aldım.)

Nurten Altınok’ u yemin ederim ki, tanımam! Ne sesini duydum, ne tokalaştım; kimdir, necidir, nasıldır inanın bilmem…Bana gönderdiği kitabını okuyunca sanki onunla yıllarca tanışıyormuşum gibi geldi bana… 

Nasıl olur dedim? Bu şair kim? Bugüne kadar neden farkına varamadım diye de kendimi sorguladım. 

Kitabını bir çırpıda okudum. Anladım ki o bir “IRMAK ŞAİRİ…” 

“Irmak Şairi” de nedir diye sorarsanız, “şiirleri-mısraları su gibi akan”, “bir çırpıda okunan” demek oluyor. Sakın ola, “Allah, Allah; böyle bir şiir akımı mı var ki? ” diye sormayın bana. Bana göre var. İşte, o “bana göre” isimlendirdiğim akımın mensuplarından birisi Altınok… “IRMAK ŞAİRİ…” 

Eserinin ve eserindeki şiirlerinin analizine geçmeden peşinen şunu söylemeliyim: Ben bir Tv veya radyo program yapımcısı yada DJ olsam, Nurten Altınok’ un bu kitabını elimden düşürmem. Maşallah o işleri yapanlar Ümit Yaşar Oğuzcan, Nazım Hikmet vb ustaların eserlerinden başkasını görmüyorlar ya; neyse… Varsınlar, bir de “Huzur Limanı” nı okusunlar diyeceğim. 

Kimdir bu eseri yazan? Yaşam öyküsü nedir? 

Eserin arka kapağında “şiirsel bir söylem” den öğrendim merak ettiklerimi. Eserin arka kapağında yazılanlar “net” ortamındaki tanıtım yazısıyla aynıydı ve şöyle diyordu: 

“BU BENİM İŞTE 

Yunanistan’ ın Gümülcine kasabasında doğmuşum 

Yıl 1950 günlerden hıdrellezin 76’ sı Cumartesi 

Öyle kaydetmiş babam 

Hasan, babamın adı 

Ucu katlanmış, sararmış bir kitap kokusu 

Temmuzun 22’si… 

Bizim soyadımız yok ki! 

Bu da azınlık olmanın kaderi…” 

İşte bu noktada biraz durdum.” 22 Temmuz 1950 Gümülcine doğumlu Nurten Hasan, baba adı Hasan…Çünkü “azınlık” olmanın kaderini yaşadığını açıkça ifade ediyor” dedim. Yanımda, yakınımda olsaydı Nurten Altınok, “Asla azınlık değilsiniz. Oralar bizim! Bizim eller! ! ” der ve ağlardım mazlum millet olmanın kaderi üstüne… 

Ağladım da… 

Sonra… 

Sonrası şu, okudum o şiirsel söylemi, öğrendim nerede okumuş, ilk şiir ödülünü nerede almış, şiirleri nerede yayınlanmış ve hangi rumuzla? … 

Ardından, 

1970’ de Türkiye’ye geldiğini İTÜ Mimarlık Fakültesi’nden mezun olduğunu, evlendiğini, “Özlem ve Onur” adında iki evladının olduğunu, İstanbul Avcılar’ da (Şu depremin vurduğu can evimizde)  oturduğunu, şimdilerdeyse serbest “mimarlık” yapıp benim gibi şiir işçiliği yaptığını bir güzelce öğrendim… 

Ve girdim “Huzur Limanı” na… 

Serde “huzur” aramak var ya…Girdiğime pişman oldum desem yeri… Benim gibi limanı “deli fişek” bulutlarla dopdolu bir şairdi karşımdaki… Okudum şiirlerini, çevirdim kitabın arka kapağını resmine baktım. 

Okudum ve baktım… Haberi bile yoktu… Okudukça konuştum onunla… Konuştum sayın Nurten Altınok’ la… 

Dedim ki: 

Önce “negatiften” başladım. 

Dedim ona, “keşke şu şiirlerin altına “tarih” yazmasaydın! Yazmasaydın be dost! Gözüm kaçıyor işte… Aynı gün mü yazmış diye sorguluyor aklım… Madem tarih düşeceksin, kendi “cönk”ünde- kendi yazdığın defterde-çok özelinde- bulunsaydı ve okuyucu bilmeseydi… 

Şiirinin ağırlığı o tarihlerle kayboluyor. Evet, yürek gümbürtünü duyuyorum, ama şiir bir günde “birkaç tane yazılacak” kadar “kolay” olmamalı. Dostlarımdan birisi Ankara’ da çok ünlü bir “prof” u anlatmıştı, Keçiören’ den Kızılay’a gelene dek otobüste üç-dört şiir yazarmış diye.. O geldi aklıma… 

Var sen ne yap biliyor musun, o tarihleri alt alta yaz ve şiirin ana “tema” sına bir göz at hele… 

Zira “şiir “ başka, bana göre, “manzume” başka… 

Hadi seninkiler ölçülü-uyaklı-ayaklı değil, yani “manzume” değil diyelim, sonra; 

İngiltere’ de dost bir şair kardeşim var, adı Bülent Özcan, geçen gün telefonla konuştuk. Dedi ki. “İngiltere’ de şiir okulları açıldı. Adamlar gazetelere ilanlar veriyorlar. Şiir nasıl yazılır, ünlü bir şair olmak ister misiniz? ” diye dedi Ve ekledi, “burada, adam cebine yığınlarca “imge”, cümle, mısra, sözcük doldurmuş, “şans-talih-kısmet” gibi çekiyor ve arkasına tümceyi ekliyor, ona da şiir diyorlar” dedi. 

Senin tarih yazmandan “negatif” bakışımla bu geldi aklıma, “Hayır! Olamaz! Olmamalı! ” dedim. İyi ki demişim. “Huzur Limanı” nı okumaya devam ettim. Okudukça “Has Şiirin” limanına demir attığımı anladım. 

Tamam “samimi” olmak ve “doğru” olmak adına tarih yazmış olabilirsiniz, lâkin, “bir kelime kuyumculuğu olan şiir” i “gönül hazinenizde biraz mayalandırıp” öyle sunmanız, o’ nun üzerinde hassasiyetle durmanız gerekmez mi? Sanki Özlem ve Onur hemen mi büyüdüler? Neler çektiniz onların elinden, neler; düşünün hele… Şiir de şairin çocukları değil mi? ... Şair, en büyük ve en kutsal doğurganlardan birisi değil mi? Anadır şair. Evlatlarını kollayıp gözetmek ve onları beslemek, giydirmek, giyindirmek, aç-açıkta bırakmamak mecburiyetindedir. Siz bunu benden daha iyi bilirsiniz… 

Ancak, bugüne dek tanıdığım tüm “IRMAK ŞAİRLERİ” nde aynı özelliği gördüm…. 

Tıpkı bizim “OZAN” lar gibi. Sazın ile çal ve söyle… 

Ben de sıklıkla yapıyorum onu ya, neyse… 

N’olur bir daha tarih yazmayın kitaplarda şiir altlarına. O size “özel” kalsın… 

Hakkınızda bir araştırma yapan kişi olursa ona verin “cönk”leri-el yazmalarını,; Tarihleri o bilsin ki, ne gibi “duygu fırtınalarını yaşadığınızı” yorumlasın, yazsın… 

İkinci, üçüncü konular çok basit. 

Bunlar “fiziksel inceleme” sadece. 

Unutmayın dost, matbaada her forma 16 sayfadır. Matbaalar “forma üzerine iş yaparlar, ona göre fiyat verirler.” Huzur Limanı 146 sayfa… Bir forma matbaacılıkta 16 sayfadır. 146 bölü 16 eşittir 9 forma artı 2 sayfa yapar. Bu da kitabı pahalıya “mal ettiğinizin” ilanıdır. Demem o ki, “ikinci emekliliği” düşünmeden, şu “forma” işini göz önünde tutsanız bir daha ki kitapta… 16 ile bölünen sayfalarla kitabınızı oluştursanız. 

Önsöz yok… İçindekiler yok… 

Kendi kendime de “Ya senin ilk kitabın nasıldı be adam? ” diye soramadan da edemiyorum. Bunlar, maalesef “dumanı üstünde ilk kitap heyecanı” ile yapılan “ihmaller.” Zaten ünlü şairlerimizden çoğu da ilk yayınladıkları kitapları “benim değil” diye “inkâr” etmediler mi? 

Ancak, sizin böyle bir yolu tercih etmenize gerek yok, “ırmak şairi” dostum… Şiirleriniz çoğunluğu “hakiki şiir”… 

Şiirlerinizin analizine gelince dost, şiirin şair sayısı kadar, hattâ yer yüzündeki insan sayısı kadar tarifi vardır. Sen şiire nereden ve nasıl bakarsan, şiirde sana oradan, o şekilde bakar. “Irmak Şairi”siniz dedim, dedim ya birazcık da bu “ekol” ün yapısına değindikten sonra, sizin şiirlerinizin ruh kökünü değerlendirmeye çalışalım, olmaz mı? 

Günümüz Türk Şiirinde herhangi bir ölçü veya vezne bağlı kalmadan, mısraları, suyun dalgaları gibi, suyun – ırmağın kendi mecrasında doğal akışı gibi dokuyan, asla bir duraksama ve zorlama-akışta bir mania ile karşılaşması bulunmayan, adeta “sözcük sihirbazlığı” yapan şairlerin izlediği yola ve metoda bu ismi koydum ben. Dış alemi kendi iç alemine doldurup, yerinde yaptığı muhteşem teşbihler ve iç ahenkle süsledikten sonra güzelim şiiri doğuranlar, işte “ırmak şairleri” onlar. Bazen de iç dünyalarını dış dünyanın sırtına yüklerler acımasızca. Bölüm başlarında veya sonlarında “şah beyit-en büyük vurgulamalardan” asla kaçınmazlar. Şiir örgülerinin can damarıdır oraları. Gizli ses benzeşimlerini orada sergilerler. Sade ve yalın, fakat sihirli bir söylemleri vardır. Sanki, söylenmemişi söylemek için bir koşuda gibidirler. Sanatkârlıkları söylenmemişi söylemedeki becerileriyle özdeştir. Bu “ekol”e mensup şairlerin bir bölümü de sadece bölüm başlarında büyük harf kullanırlar, mısra başlarında büyük harf kullanmazlar. Kimileri de dilimizdeki “inceltme” işaretleriyle, noktalama işaretlerine bile karşı durmuşlardır. “garip üçlüsü”nden bu yana gelişen şiir kuşağımızın yeni renkleridir onlar. 

Bu akımın bazı vazgeçilmezlerini şahsen ben tasvip etmiyorum. Noktalama işaretleri ve büyük harf gibi konularda ki tutumlarını mesela…Ama olsun, gene de onları okuyor, yakından da izlemeye çalışıyorum. 

“Huzur Limanı” kitabında şair Nurten ALTINOK, ırmak şairleri arasında bana en yakını diyebilirim. 

İnce bir hüzün, gecenin efsunkâr kara gözleri, yalnızlığın fırtınalı girdabı ve ölümüne, inadına sevda… Sabahtan akşama dek bir koşturmaca içinde çırpınan şair ruhu, kendi sığınağı olan şiirinin limanına girince, bulutun ağlaması benzeri sarılır mısralara, atar kendini iç dehlizlerinin dönüp duran uçurumlarına. Kendinde kendi olunca da yazmaya başlar kalemi. Altınok bu işte… “beynimdeki kalabalığı sabahtan kiraladım” der “kirli bir çıkın gibi zaman sandıkta naftalin kokan” dediğinde de sevgisini-aşkını-bitimsiz tutkusunu özler ve ona, “unutma beni göz yaşın olayım” diye de seslenir. “Saatler yine dört sıfır” olmuştur ve bu saatlerde “geçmişe açılan kapılar aralandıkça, sessizce bir şair can verir” onda…Zira, “özel rüyalar gibi gelen, gönlüne akran, gözüne yaşıt, sevdasına eşit, yalan içinde yalanı” olan, “başının en büyük belâsı” sevdiğiyle baş başadır o saatlerde. Sevdiği dağlar ardında, ötelerin ötesinde olsa da; can evinin içindedir şairin. Konuşur, dertleşir bir güzel… 

Altınok’ un şiirinin değişmezlerine gelince: İnce bir hüzün, gecenin efsunkâr kara gözleri, yalnızlığın fırtınalı girdabı ve ölümüne, inadına sevdadır demiştik. Baştan, bazı örnekler verelim: 

“Neden Gittin” şiirinde: 

“Öyle olsun, hadi git… 

Korkular pes etti zavallı karanlığımda 

Mum ışığında 

Kanadı kırık bir pervane 

Yalnızlığımı yazıyor gözyaşlarıyla..” 

…….. 

“Bekçi ağzında düdük 

Sesi gecede büyük bir delik 

….her düdük sesinde balkona çıkıyorum 

sen mi geldin? ” 

……………………… 

“Yıldızlardan utanıyorum 

Sessiz tanık 

Göz kırpmalarından 

Karanlık ayıbımı örtüyor” 

…………………….. 

“Ellerimde çaresizliğin teri 

Birden susuverdi karanlığın elleri 

Karanlığın elleri yağmur kadar küçük değil 

Gelemezdim” 

“Geceler Kurşun” şiirinde: 

“Gecelerin kurşun sağnağında 

Korumasız 

Sarmaş dolaş yaşadın mı yalnızlığı” 

…………………….. 

“Geceler hüzün ebesi 

Kan emici sülük misali 

Kırçıl saçlarda öfke geceler 

Göz altında mor halkaların belgesi 

Geceler… 

Günahların sis perdesi 

Geceler… ah geceler, ah…” 

“Böyle Sevda” şiirinde 

“…………………… 

Uykusuz geceler 

Yağmur yağıyor 

Kapımda sen 

Canımda sen” 

“Gidiyor musun? ” şiirinde: 

“……………………… 

Sıcaklığını kundakladığım sabah ezanlarında… KAL 

Gidiyor musun? 

Sensizliğin asılı bir gerdanlık gibi boynumda… KAL 

………………………. 

Ve karanlığın iki eli boynumda 

Boğdu boğacak 

Kocaman gözlerimde korkular çaresiz 

Titreyen ellerimde yüreğim 

Kapım ağlıyor 

Çalınmayan 

……………………….” 

“Yalnız Geceler” şiirinde: 

“Yine yalnız geceleri oynuyorum kaderimle baş başa 

Yine sessizliği / parçalarcasına / bu kaçıncı 

Yine sen-siz-liği… ah! tutamadığım 

……………………….. 

Zaman oyunu bizden yana kullanır 

Amorti gibi sığındığımız mutluluk 

……………………….. 

Suskunluğum alabora 

Sabahlara sürgün gözlerimde 

Kör olmuşum 

Bulutlar ağlıyor bak yıldız kaymalarında 

……………………….” 

Sanırım bu birkaç örnek yeterlidir düşüncelerimizi sunmaya. 

Ahmet Haşim kişiliğinin gecede sancılanarak şiirsel hıçkırık ve iç çağrılarının iz düşümü yok mu bu okuduklarımızda? Var elbette. İşte “Irmak şairleri” nin çıkış noktalarından birisi bu nokta. Altınok’ da aynı yolu izlemekte. Haşim, kendince “çirkin ve kara” saydığı yüzü sebebiyle alaca karanlıktan itibaren tüm geceyi limanı sayardı. Kaçışlarının son noktası gecenin kara- zifiri örtüsüydü. 

Kardelenler ve günaydınlarla, eşine-işine ve yavrularına bağlı bir şair yüreği de o ışıltılı- pırıltılı-sevinçli vede bir o kadar da yorgunluk dolu saatler sonrasında kendi tüneline girivermektedir. O tünel, çağrılarla ve haykırışlarla dopdoludur Nurten’ de…O tünelde yapayalnızdır. Zaman, elbette geçecektir ama, yüreği rüzgârlara takılmıştır uçup gitmededir. 

Dilinden ses çıkmaz, suskundur fakat, canhıraş feryatlar içindedir. 

“Ayaz gecelerde üstümde gök ölüyor 

Yalnızlığım yağıyor ayaklarıma 

Kapatıp ellerimle yüzümü geceye inat 

Karanlıktan korkmuyorum / ağlamıyorum 

Ölüm kolay ayrılıktan” 

Diyen Altınok, ağlamıyorum dese de öyle güzel ağlayan bir şair ki… Çocuklar gibi ağlıyor hem de… Oyuncağı elinden alınmış bir çocuk benzeri yani… Hasretin şairi olan bir gönül bu tür kıvranır ikilemlerde… Ruhunun gel-gitlerini geceye inat elleriyle yüzünü kapatarak gizlemeye çalışır. Çünkü ağlıyordur, için için ağlıyordur… 

Esasında ağlayan-acı çeken yüreklerden fışkırır şiirin hası… Bal-kaymak tasında eli olanın kaleminden ne mısralar dökülür ki diye düşünmüşümdür hep…Çile içten arıtır mısra kuyumcusunu. Gözyaşı rahatlığıdır. Göz bulutları yanaklarından aşağıya damla damla süzüldüğünde, içi ve dışı ışıltılarla dolar… 

“Hep çoğul yaşadım seninle 

Bir gözümde ben baktım, diğerinde sen 

Ben yattım karanlıklarda, uyandım büsbütün sen 

Bir gün ben yaşadım bedenimde 

Bir gün sen attın yüreğimde 

Nasıl kıyarım sana söylesene 

Seni nasıl sürüklerim bitmeyen gecelere 

Dedim ya, tek olsam iş kolay 

Ölmek işten bile değil 

Ah! İçimde sen varsın 

Sen varsın… 

Sen…” 

Diyerek şahane bir “altın vuruş” yapar Altınok… 

Gecelerde bilemezsiniz suyun feryadını. Bir fotoğraf seyreder gibi bakmayın sulara. İnin ırmak kıyısına yada deniz kıyısına, duyun çağrısını suyun, işitin kumsallara yapışan figanını. Korkmayın o size sizden yakındır. Hem o boynunuza taktığınız en güzel incilerin de su diplerinden çıkarıldığını bilin. Gecelerin şairi Nurten Altınok, “altın vuruş” şiirinde de bu tutkularından kurtulamıyor bir türlü… Ve ekliyor: 

“Çeker giderim gecenin bir kuytusunda 

Ölüm kolay ayrılıktan 

………………………” 

Geceler, yalnızlığın emzirildiği zaman anası… Ölümün usul usul ıslık çalarak geldiği zaman dilimleridir. Karanlık hep ölümü anımsatır şaire… Ölüm ise ayrılıktan kolay. Ölmek basit, ayrılık zor… Ölmek, son nefesi vermekle, ayrılık ise araya zaman ve mesafe koymakla oluşur. Ölüm, tasavvuf şiirimizin ana teması. Ayrılık, halk şiirimizin temeli. Yunus Emre, ölümle ahirete ve ezel-ebed sevgiliye kavuşacağını söylerdi. Mevlâna, ölümü “şeb-i arus yani düğün gecesi olarak tariflerdi. Abdülhak Hamit’in “Makber” iyle ölüme isyan başlamıştır diyebiliriz. Peyami Safa, Necip Fazıl ve Ahmet Hamdi Tanpınar, insanı ve ölümü metafizik açıdan yorumlamışlardır. Cahit Sıtkı ve Orhan Veli, ölümü düşünmek yerine “yaşanılan an” dan faydalanmayı yeğlemişlerdi. Ölüme bir çare bulanamayacağına göre, yaşama zevkini doya doya tatmak gerekirdi. 

Huzur Limanı şairi Nurten Altınok, çaresi bulunmayan ölümün son bir nefesi vermekle kolay olacağını, (çaresizliğin kolay olduğunu)  bilmekte ve ayrılığın ölümden zor, fakat bir çaresinin olduğunu, o çarenin de sevgilinin gelmesiyle- hasretin sona ermesiyle oluşacağının farkındadır. 

Cahit Sıtkı ve Orhan Veli son derece açık, sade ve yalın üslupla şiirlerini kaleme almışlardır. Yaşanılan hayatın net bir fotoğrafını çekip sunmuşlardır. Sunumlarını teşbih, istiare ve mecaz gibi edebi sanatlarla süsleyip değiştirmemişlerdir. Yaşadıkları dünyayı pek sevmeyen Divan Edebiyatı şairlerimiz ise, yaşantılarını baş vurdukları edebi sanatlarla masal haline getirmişlerdir. Teşbih sanatının pırlanta kelimesi “gibi-kadar” kelimeleridir. Benim “ırmak şairleri” adını verdiğim, günümüz Türk Edebiyatındaki şairler, “gibi ve kadar” kelimelerini kaldırmışlar, iç alemleriyle dış evreni harmanlamışlar, birbiri üzerine bindirmişlerdir. 

Nurten Altınok’un iki şiiri dikkatimi çekti. Bunlardan birisi ayrılığı anlatan ve Ankara Diyarbakır seferini yaparken şehit düşen 34 erimizin anısına yazdığı “Analar Ağlamasın” başlıklı şiiri, ötekisi de gene bir ayrılığın sonucuna nokta koyan rahmetli babasına “Babam Ben Geldim” diye seslendiği şiiri. Her ikisinde de Altınok, yüreğini konuşturmuş. Öyle samimi ve öyle sıcak ki… Babasının kabrini ziyaretinde; 

“……………………… 

Babam, ben geldim 

Erik ağacının altındayım 

Burası çok kalabalık be babam 

Bir o kadar da sessiz 

Yaban otlarını ayıkladım 

Güllerin çiçek açmamış 

Belki zamanı değil 

Biraz su döktüm 

Mezar taşını okşadım 

Saçın gibi bembeyaz 

Biliyor musun 

…………………… 

Ben seni çok özledim be babam” der. 

“Cennet mekânın olsun” dediği babasıyla arasında geçen tatlı zamanları anımsar önce. Şakalaşmalarını, “Kocaman kızım” deyişini, kahvenin önünde sandalyede oturuşunu, peynirle karışık lehim kokusunu, deri kasketini bir bir hatırlar. Babasına “anam iyi merak etme, kardeşimle kalıyor” der ve kendi çocukları olan Özlem ve Onur’ dan haber verir. Sonra da şair, “bu aralar kafam karışık biraz” baba, dedikten sonra, kendi iç dünyasına sarılır. Rahmetli babasına benzeyen, aynı kasketi giyen, iki elinde iki poşet olan bir adamın peşinden koştuğunu, yolunu kesip yüzüne baktığını belirtir. Ne yazık ki babası kabirdedir. Ve “hastanede olduğu gibi kuru ekmekleri ıslatır balkona koyar ve kuşlarla konuşur. Kuşların “çoktandır gözükmüyor, nerede” sorusuna cevap veremez, hiçbir şey diyemez. Bir torba yem alır çınar altındaki kumrulara-güvercinlere döker. Bayram şekeri almaya gelen çocukların sorusu karşısında suskundur.. Özetle şair, babasına bırakıp gittiği çevrenin fotoğrafını ince bir elemle takdim eder… Elemi, babasını çok özlemesinden kaynaklanır. Geri dönülmez ayrılıktan… 

Mistik şiirde “fanilik gömleği” insan ve doğanın üzerinde sürekli durur. Ve “fani, fenadır.” Bu alem geçicidir. Dünya misafirhane, insan baş koltukta, ölümü bekleyen konuktur. Huzur Limanı şairinde, ölüm bir gerçektir, ancak, hayat devam etmektedir. Kuşuyla, ağacıyla, çocuğuyla… 

Nurten Altınok, “Analar Ağlamasın” şiirinde, “En büyük asker bizim asker / Asker gidecek geri gelecek” diye davullu zurnalı alaylarla “asker uğurlama” geleneğimizle söze çok güzel girmiş. Gözlerinden kor bir ateşin, bağrının ortasına kor alev olarak çöreklendiği suskun bir ananın, askere uğurlanan oğlunun boynuna sarılırken; 

“-Aman ha oğul 

Sakın üşütme 

Sırtın açık kalmasın 

Ayağın yalın-“ şeklinde fısıldamasını, “genizlerine kadar çektiği, halâ / Dünkü bebeğinin kokusu / Mis kokusu..” söylemiyle doruk noktaya çıkarır. Ana ile oğulun bu esnada konuşmalarını sıralar şair. İçi titreyen, avuçları terleyen, yiğidim, canım diyerek, dualarla oğluna sarılan anasına oğlun üzme kendini, vatan borcudur bu, şunun şurası nedir ki, gider gelirim deyişini anlatır ve oğulun içini bulut gibi boşaltır mısralara: 

“Sen değil miydin şarkılarında çoğu zaman 

Asker yolu beklediğin 

Günü güne eklediğin 

Sen değil miydin 

Vatan borcu can borcu dediğin 

Sen değil miydin ta ninnilerimde 

Asker oğlum diye sevdiğin 

Hudut kapılarını sen öğretmedin mi bana 

Sen öğretmedin mi bana 

Şehit düşecek kadar bu vatanı sevmeyi 

Bilirim hasret yakıyor içini 

Resimler gönderirim anam 

Selama durmuş askerin 

Çakı gibi 

Gururla duvarına asacağın 

Bağrına basacağın…” 

Ve oğul askerdedir, nöbettedir. Özlemiştir anasını, sıcak çorbasını. Babasını, kardeşlerini, yeğenlerini; tabii ki nazlısını da… Terhis vaktidir. “Terhis oldum anam / Geliyorum / Geliyorum / Boynuna sarılmaya” diye Mehmetçik, “Bu gün çok kalabalık olmalı evimiz / özlemlerle düştüm yollara / özlemlerimi yükledim de demir kanatlara / Geliyorum / Uçuyorum / Uçuyorum anam..” der. Ne yazık ki, özlemlerini yüklediği çelik kanatlar, onları taşıyamamıştır ve Mehmetçiklerin tabutlarını götürmüştür evlerine. Asker, anasına; 

“………………………… 

Son mektupta kendimi postaladım sana 

Çivilenmiş bir tabutta 

Bedenim 

Özlemlerim 

Söyleyemediğim şarkılarımla… 

Çivilediler beni ana 

Sonra, bir al bayrağa sardılar 

Allı pullu bir yazma almıştım sana 

Her saçını bağladığında 

Her özlem çöktüğünde bağrına 

Silersin diye gözyaşlarını bir ucuyla 

Bugün onu bağla saçına ana 

Kusura bakma 

Ne bilirdim ben olacağımı yazmana 

İlk düşecek acı damla 

Ağlama anam 

Anam ağlama 

Özlemlerim bulutlara takıldı 

Ellerim yıldızlara 

Yüreğim, 

Ah, 

Yüreğim 

Yüreğim rüzgarlara takıldı…” diye seslenir. Nurten Altınok’ un bu şiirini kime okudumsa yüzü- gözü ağlamaklı oldu, tutamadı göz yaşlarını. Sanki ben okurken, tutabildim mi ki? ... Ben de ağladım, ağladım… 

Kimileri, şiirin asli görevinin göz yaşı ve hıçkırık taşımak olduğunu söyler. Gurbet ve hüzün, bizim Anadolu insanının bitimsiz beslenme kaynağıdır. Kimileri de, mısra işçisi olan şairin, şiirinde misal olarak, bir elmanın yenilişini mi anlatıyor, şiiri okuyan dişlerini geçirdiğini hissetmeli der. Nurten Altınok, ruh girdabındaki hüznü, dış dünyanın unsurlarıyla boyar sanki… Önce ana tema’nın etrafında birkaç tur atar, sonra, bir şahin edasıyla-hızla kendi yüreğini avuçlarına alarak, tema’nın ortasına dalar. Yüreğini teninden çıkarmakta zorlanırsa, çoğu şiirlerinde olduğu gibi parmak uçlarını ve tırnaklarını geçirir yüreğine ve öyle alır avuçlarına. Bu hareketi, acıyı önce kendi can evinde çiçeklendirmek, hissetmek için yapar.. 

Huzur Limanı kitabında şair, gece, yıldızlar, kor ateş, bulutlar, deniz, kapı, zaman, ayrılık elinden yanıktır ve kimi zaman da dertlenip içki içer. Sarılır kadehlere… Bir “sevda depremi” yaşayan gönül düşer yollara…Fırtına, lodos ve yağmurlu yolculukları sever. Kanadı kırık martılarla ağıt yakar kaderine. Kalbiyle beyninin savaşının arasında kalır. 

Irmak Şairi Nurten Altınok’ u bu güzel eserinden dolayı kutluyorum. O, şiir dünAmızda parlayan bir yıldızdır. Şiir dünyamızı “Kurtlar Sofrası” na benzetir ve; 

“Bir nefeslik satır ayırın bana da 

Bir diz bükümü oturmalık yer 

Geliyorum, ister; 

Tanrı misafiri deyin, ister; 

Kul hakkım 

Kalemime düştü duygularım 

Ben, sevdayım 

Ben, şiirim 

Ben, şarkıyım 

Kurtlar sofrasında ben de varım…” deyiverir. O, gelmiş ve gönül meclisinde, mısra ustalığı masasında yerini almış bir şairdir. Her ne kadar; 

“Boş ver… bu BEN’ im 

Bu kavga benim… 

Kimse okumasa da yazdıklarımı 

Eşe, dosta veririm…” diyerek, şiirinin ve kitabının kaderini çizmeye çalışsa da, bu mısralar artık o’ nun değil, bütün duygu dünyasının, edebiyat aleminin malıdır. Evet, imza o’ nun, ancak, şiiri görevini yapacak ve nice yüreklerde gümbürdeyecek, gözlerden yaş akıtacak, hasret trenlerinde okunacaktır. 

Temmuz 2001’ de İstanbul’ da yayınlanan Huzur Limanı isimli bu eseri, bütün dostlara tavsiye ediyorum. Kitap isteme adresi şöyle: 

“Belediye Cad. 21 / 38 

Avcılar / İSTANBUL 

Kaynak: Mustafa Ceylan', 'TAHLİL: 1 Nurten Altınok ve Şiirsel Dünyası  Kayıt Tarihi: 12.06.2004; Ekleyen: Mustafa Ceylan  ''Huzur Limanı'' kitabı üzerine bir ''tahlil''  ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":241,"source_url":"https://www.antoloji.com/nurten-altinok-ve-siirsel-dunyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oku, Oku, Oku...', 'oku-oku-oku-i-smet-barlioglu-m9256', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sakın yoksulluğu bahane etme,

Yalın ayağınla simit sat, oku.

Binbir mazereti bahane etme,

Taşlara demirden tohum at, oku.

Okuyorsan oku, yoruldum deme,

Gam bulursan gam ye, aş-ekmek yeme,

Hasta bile düşsen; oku, inleme,

Tabutu döşek et, uzan, yat, oku.

Öyle bir oku ki; candan, yürekten,

Aklına, ruhuna güvenerekten,

Yoruldum, usandım demeyerekten,

Gücünü gücüne ekle, kat, oku.

Ertele uykuyu, sonra uyursun,

Rahatı seversen yolda kalırsın,

Hele başla yola, yürü, varırsın,

Gününü gün kadar çek, uzat oku.

İlimi nefes et ciğerlerine,

Kitaptan başka şey alma eline,

Nefsinden çok önce yer ver ilime,

Rahatı bir yana at, fırlat, oku.

Boş vakit geçirme; tez basar tipi,

Öyle bir oku ki; zikreder gibi,

Topla sokaklardan dökülmüş çöpü,

Götür bir ehline ızat sat, oku.

Hikmet der; oku ki; Hakk ''ı bilesin,

Toplumun içinde rağbet bulasın,

Belki bir yaraya merhem olasın,

Aklını fikrine daya, çat, oku.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 406*407/412)', 'Sakın yoksulluğu bahane etme, Yalın ayağınla simit sat, oku. Binbir mazereti bahane etme, Taşlara demirden tohum at, oku. Okuyorsan oku, yor...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/oku-oku-oku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düngece Sen Vardın', 'dungece-sen-vardin-i-brahim-dikmen-2-8fosq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün gece sen vardın,

düşlerimde.

çok güzeldin,melek gibi,

beyazlar içinde.

                                       

                                         Dün gece sen vardın,

                                         özlemlerimde.

                                         yarim,hasretin zor bana,

                                         gidişlerinde.

Nezaman geleceksin,

bir daha,

nezaman göreceğim,

yakından,

seni bir daha.

gitme,gitme kal,

yanımda,

ben,sensiz yaşayamam.

gitme,gitme meleğim,

hep burda kal,

yanıbaşımda.

çok güzelsin,melek gibi,

sen düşlerimde.

beyazlar içinde,

gitme kal canım,

dönme,

düşler ülkesine.', 'Dün gece sen vardın, düşlerimde. çok güzeldin,melek gibi, beyazlar içinde.                                                                  ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dungece-sen-vardin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek Daha İyi', 'olmek-daha-i-yi-caner-kuru-b87z1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölmek daha iyi, yaşamaktansa

Hep böyle acı, dert çekemem ki ben.

Birkaç damla yaş farketmez ama,

Bir derya dolusu dökemem ki ben.

Ben yeter dedikçe artıyor kat kat,

Duyan mı oluyor etsem bin feryat

Çekilir mi dostlar,böyle bir hayat? 

Hep böyle boynumu bükemem ki ben.

Gençliğime yazık, ömrüme yazık

Karanlık tün dünyam, yok tek bir ışık.

Yalvara yalvara tükendim artık,

Her zaman yere diz çökemem ki ben.', 'Ölmek daha iyi, yaşamaktansa Hep böyle acı, dert çekemem ki ben. Birkaç damla yaş farketmez ama, Bir derya dolusu dökemem ki ben. Ben yeter ...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olmek-daha-iyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hışımla', 'hisimla-i-smet-barlioglu-7ss22', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu devre, devrana bir bak, erenler,

Herkes kuyusunu kazar hışımla.

Alınyazıları Allah ''a mahsus,

Kulsa günahını yazar hışımla.

Her gün başka yöne döner insanlar,

Zira, lafta kalmış artık vicdanlar,

Dün bir anlaşmada yemin yapanlar,

Bugün anlaşmayı bozar hışımla.

Yüz verdimi talih, var bin isteyen,

Yarınki vurgunu dünden peyleyen,

Yavuz hırsız gibi haksız gürleyen

İşi rastgittikçe azar hışımla.

Soysuzun tekeri aşar dağlardan,

Hem de yaylalardan, hem de bağlardan,

Mazlum yol bulamaz dümdüz ovadan; 

Hangi yola girse tozar hışımla.

Arsızın elleri kasırga, tipi,

Tuttumu paröalar halatı, ipi,

Çifte su verilmiş bir pala gibi

Arlının başında gezer hışımla.

Namus ve doğruluk kalmış kitapta,

Ahlakın varlığı sadece lafta,

Hırsız bir girdimi toz koymaz rafta,

Bir tek pire bulsa ezer hışımla.

Kalkmış dürbünlerle aranır Hikmet,

Kalmış mı diyerek toplumda iffet,

Sen bunu böyle duy, böyle kabul et; 

Yıllardır gayreti uzar hışımla.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 408-409/412)', 'Şu devre, devrana bir bak, erenler, Herkes kuyusunu kazar hışımla. Alınyazıları Allah ''a mahsus, Kulsa günahını yazar hışımla. Her gün başka...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hisimla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esnaf Berati', 'esnaf-berati-i-smet-barlioglu-5rawa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her sabah bismillahla esnafın dükkanını

Süpürüp temizleyip açması ne güzeldir.

Ne güzeldir silmesi camını, tezgahını,

İlk çayını helalden içmesi ne güzeldir.

Gelene güven veren ta gönülden bakışı,

Elinin, önlüğünün o gül gibi kokuşu,

Raflara, çuvallara özenle dokunuşu,

Malın sağlamlarını seçmesi ne güzeldir.

Zerre kadar hiyleyi bilmeyen terazisi,

Sattığı baldan tatlı, kaymaktan güzel sözü,

Müşteri güvendiren nurla süslenmiş yüzü,

Vitrini bismillahla açması ne güzeldir.

Pirinci taşsız, beyaz, bulgurları kehribar,

Şekerleri bembeyaz, unu kardan daha kar,

Tarçında, karanfilde bin baharın tadı var,

Baldan gül kokusunun uçması ne güzeldir.

Neye baksan helaldir, zerresi yok haramın,

Zira, künhüne varmış bu geçici dünyanın,

Sadeyağ Trabzon ''un, makarna Ankara ''nın,

Peyniri kıldan ince biçmesi ne güzeldir.

Ne güzeldir parayı kazanması helalden,

Haramın geçmemesi etinden, kemiğinden,

Ne güzel çıkmaması Rabb ''inin dediğinden,

Helalinden alması, satması ne güzeldir.

Ne güzeldir akması terinin damla damla,

Ne güzeldir tartması malı gram gramla,

İşinin olmaması ne güzeldir yalanla,

Çürükleri hep çöpe atması ne güzeldir.

Barlıoğlu diyor ki; vicdan güzel birşeydir,

Hiyleyle kazananlar ne ağadır, ne beydir,

Esnafın doğrusuna gülden önlük dik, giydir,

Geceleri vebalsiz yatması ne güzeldir.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerden > 410-411/412)', 'Her sabah bismillahla esnafın dükkanını Süpürüp temizleyip açması ne güzeldir. Ne güzeldir silmesi camını, tezgahını, İlk çayını helalden iç...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/esnaf-berati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayınvalidem - 5 / anı', 'kayinvalidem-5-ani-k-muran-esen-h65j0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sıcak bir yaz günüydü.Arabamız, Ankara’daki bir nikâha yetişmek için, adeta bizi uçuruyordu.Direksiyonda eşim,  eşimin yanında kızım oturuyordu. Arkada da kayınvalidemle ben.

Virajlarda araba savruluyor, zaman zaman kayınvalidemle ben, birbirimizin üzerine devriliyorduk. Bir ara kızımın, babasını daha yavaş gitmesi konusunda, ses tonunu yükselterek uyardığını duydum. Adeta azarlıyordu babasını. Kayınvalidem, kızıma söylenmeye başladı:

-	“Sus! Çemkirip durma. Babalara karşı gelinmez.Hem ayıp, hem günah.”

Kızım da, arabanın  hız göstergesini işaret ederek:

-	“Ama babanne, 250’yle gidiyor,” dedi.

Kayınvalidem bana eğilerek ve usulca:

-“250 çok mu? Kaçla gitmesi lâzım? ” diye sordu. Ben de kendisine, onun anlayabileceği şekilde izah ettim.

Bir müddet sonra, iniş aşağı bir yola girince arabamız daha da hızlandı. Uçar gibi gidiyoruz. Bu kez  eşime kızma sırası kayınvalideme geldi.Eşime  şöyle dedi:

-“Aaaaaa! Acık yavaş. Hadi 250’ye bi şey demedim. Emme (ama)   bu sefer 600 oldu menemme(galiba) .', 'Sıcak bir yaz günüydü.Arabamız, Ankara’daki bir nikâha yetişmek için, adeta bizi uçuruyordu.Direksiyonda eşim,  eşimin yanında kızım oturuyo...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kayinvalidem-5-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükür', 'sukur-i-smet-barlioglu-rt2gh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rab beni güvendirdi,

Lütfedip sevindirdi,

Böyle bir görev verdi,

Nice şükretsem azdır.

Ekmeğim var, aşım var,

Görevim var, işim var,

Bir düşünen başım var,

Nice şükretsem azdır.

Hikmet diyor; O ''nu sev,

Ben sevdim alev alev,

Bitti verdiği görev,

Nice şükretsem azdır.

(MÜHÜRLÜ KİLİT ismi altında toplanmış felsefi şiirlerinin sonuncusudur.

Bu 412 sayfalık kitaptaki şiirlerin tamamı Rahmetli babası Hüseyin Bey ''e ve rahmetli anası Naime Hanım ''a ithaf edilmiştir.)', 'Rab beni güvendirdi, Lütfedip sevindirdi, Böyle bir görev verdi, Nice şükretsem azdır. Ekmeğim var, aşım var, Görevim var, işim var, Bir düş...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sukur-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Sokak Sevişmeleri', 'cikmaz-sokak-sevismeleri-emir-kemal-c7zjx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaklaş! 

Dokun! 

Uzat ellerini, 

Sarıl sarılabildiğince... 

Her kıvrımını hissetmek istiyorum bedeninin... 

Uzat ellerini, 

Havada kalmasın ellerim. 

Ve soyun! 

Unutma! 

Aşk; çırılçıplak kalmaktır, 

Çıkmaz bir sokağın, tam ortasında... 

Acık benim gibi, 

Yada susa... 

Uzan yanıma, 

Tenimizde doyuşalım. 

Hissetmek istiyorum, 

Tuz ne kadar tuzlu, 

Ekşi ne kadar ekşi? 

Dudakburkan koyalım adını... 

Gel! 

Dağıt saçlarımı; ister yol.. 

Bir makas al, 

İstediğince kes sakalımı. 

Bağla elimi kolumu, 

Gariban bir karyolanın başucuna... 

Unutma! 

Aşk; tutuklanmaktır bazen, 

Çıkmaz bir sokağın, tam ortasında... 

İstediğin düğmeden başla çözmeye. 

Ağır ol. 

Biliyorsun, 

Çözdüğün kadar göreceksin beni... 

Öğren! 

Aşk; çıkar bir yol aramaktır bazen, 

Çıkmaz bir sokağın, tam ortasında. 

Getir yüzünü... 

Daya kulağını göğsüme. 

Dinle kalbimi. 

Duy! 

Ve yaklaş! 

Hırçın bir çekişle sendele, 

Abartılı ol, 

Darmadağın bırakılmış bir yatağın, tam ortasında... 

Korunmasız ol! 

Ben gibi... 

Neyi kimden gizliyorsun? 

''Hissetmek, yaşamanın yarısıysa; 

Yarım adımla hislerini yaşa... 

Hissettiğin kadar çılgın, 

Hissetmediğin kadar masum ol...'' 

Kendini oyna. 

Unutma! 

Aşk; bir oyundur bazen, 

Çıkmaz bir sokağın, tam ortasında. 

Aç gözlerini! 

Gözlerime bak! 

Kaçırma ateşini... 

Umursama! 

Kalbini tenine taşı, 

Teninde hissetmeliyim tüm çırpınışlarını... 

Toprak gibi susuz, 

Yağmur kadar ıslak ol! 

Tut nefesini, 

Soluksuz bekle, 

-Vazgeçişlerin olayım...- 

Ve dokun! 

Uzat ellerini... 

Sarıl sarılabildiğince.. 

Uzat ellerini, 

Havada kalmasın ellerim... 

Ve giyin! 

Unutma! 

Aşk; üşümektir bazen, 

Çıkmaz bir sokağın, tam ortasında... 

Emir Kemal Süme / 2004', 'Yaklaş!  Dokun!  Uzat ellerini,  Sarıl sarılabildiğince...  Her kıvrımını hissetmek istiyorum bedeninin...  Uzat ellerini,  Havada kalmasın ...', ARRAY['Türk Edebiyatı','Şiir','Emir Kemal']::text[], 8.5, '{"poet":"Emir Kemal","poet_slug":"emir-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/cikmaz-sokak-sevismeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşilden Maviye Yolculuk', 'yesilden-maviye-yolculuk-i-brahim-dikmen-2-ag4qz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeşilden maviye yolculuk var,

Aydın''dan Muğla''ya her gidişimde.

Sakardan süzülüp gökovaya,

indiğimde.

Bir tatlı huzur dolar,

çocuksu yüreğime.

Buram buram reçine kokar,

mavinin serinliğinde.

yolboyunca asırlık çam ağaçları,

birbaşka güzel derinliğinde.

o''çakıl taşları.

Marmarisin yeşiline doyum olmaz,

hele mavi denizine hiç doyulmaz.

sıcaktır insanları,bir soluk gibi,

yaşamak gerek neme lazım,

nefes gibi.

Köyceğiz''in gölüne hayranım,

peşpeşe içerim akşam çayını.

şırak şırak,sahile vuran,

dalga sesleriyle.

kara gölün içimde birbaşka,

bağımlılığı.

Ortaca birbaşka güzel,

ve çok özel,olanca özelliğiyle,

dalyanda tekneyle dolaşmak,

denizin yosun kokusunu çekmek,

ta! içerilerime nefes nefes.

insanı büyüleyen görüntüsüyle,

kral mezarlarının önünden geçip,

carettalara doğru yol almak,

boğazdan süzülüp iztuzunu görmek.

sıcakla soğuğun birleştiği yerde,

var olmak.

tarifsiz birtat hislerimde.

Göcekte çam ağaçlarının,

koyu gölgesinde yatmak.

sere serpe.

uzanmak gölgesine,

dalmak derinliklerine,

mavinin en serinliğinde.

Aşı koyu birbaşka güzel,

bakir kadın edasında.

saf ve doyumsuz güzellikte.

el değmemiş ormanlarından,

nazlı kız gibi denizinden,

çıkmak istemezsin yeşilinden.

çıkaramazsın günlerce,

kendi benliğinden.

sarı germe uzunca plaj,

azgın dalgaları var devasa.

kayalıklara bakan martı bakışlarıyla.

ve çam sakızı kokusunda,

serin rüzğarlı akşamlarıyla,

uzanmak altın gibi,

sarı kumlarında.

Bodrum bodrum,

bir aşk halikarnasta.

bir akşam,

bir başka sarhoşluk,

bir roman tek başına.

aşklara yelken açan sıcaklıkta,

derin mavi,

eşsiz güzel bardakçı koyunda.

Buraya kadar gelmişken,

balık yemeden gidilirmi.

ortaca''^nın ortasında,

yuvarlak çayında.

sakardan süzülüp gelen,

buz gibi.

günlük ağaçlarının arasından,

nefes nefes,süzülerek gelen,

paçanı sıvayıpta,içine daldırıp,

ayaklarını.

buz gibi rakını yudumladığın,

sazanların enfes ızgara tadında,

adı gibi yuvarlak çayında.

bir bağımlılıktır akşamlar,

fasıllı rakı sofralarında.

akdenizin yeşil cenneti,

mavi derinliği muğla''da.', 'Yeşilden maviye yolculuk var, Aydın''dan Muğla''ya her gidişimde. Sakardan süzülüp gökovaya, indiğimde. Bir tatlı huzur dolar, çocuksu yüreğim...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/yesilden-maviye-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahmak', 'ahmak-ozan-ozel-wa5tk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'derinden gelen bir çığlık

tüm dünyayı sardığında

her yeri sular kaplayacak

depremler olacak

dağlar patlayacak

yaşamlar son bulacak...

işte insan! 

hırslarının sonunu göremeyen

kendi sonunu hazırlayan

ahmak, ahmak, ahmak...', 'derinden gelen bir çığlık tüm dünyayı sardığında her yeri sular kaplayacak depremler olacak dağlar patlayacak yaşamlar son bulacak... işte i...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ahmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile Deryası', 'cile-deryasi-zulfikar-yapar-kaleli-9acgp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülmek için zaman mı var? 

Çile derya, gayret oktur.

Ağlamaya vakit çok dar,

Koşmalıyım, yolum çoktur.

Ağır gelir götüremem,

Menziline yetiremem,

Gider gider bitiremem,

Yollar ki omzuma yüktür.

Zehir olur tatlı aşım,

Beladan kurtulmaz başım,

Olsun üzülme kardaşım,

Allah yücedir, büyüktür.

Başı sonu Hak katına,

Var Kaleli Hak katına,

Arzuhalim Hak katına,

Başka sığınağım yoktur.', 'Gülmek için zaman mı var?  Çile derya, gayret oktur. Ağlamaya vakit çok dar, Koşmalıyım, yolum çoktur. Ağır gelir götüremem, Menziline yetir...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cile-deryasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-hakan-arikan-xxp5n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok korkuyorum.

Yalnızlığın için de,

Bir nokta gibi kaybolmaktan,

Korkuyorum.

Yüreğimdeki yaralar kanarken,

İçim acırken,

Gözlerimin bir damla yaş dökmemesinden,

Korkuyorum.

Sensiz bir hayat düşünemezken,

Bir sabah yalnız uyandığımda,

Yüzümde bir tebessüm olmasından,

Korkuyorum.

Korkuyorum.

Bütün bunların gerçekleşme ihtimalinden,

Artık korkularımdan,

Korkuyorum.

Ankara Aralık 2002', 'Çok korkuyorum. Yalnızlığın için de, Bir nokta gibi kaybolmaktan, Korkuyorum. Yüreğimdeki yaralar kanarken, İçim acırken, Gözlerimin bir dam...', ARRAY['Türk Edebiyatı','Şiir','Hakan Arıkan']::text[], 8.5, '{"poet":"Hakan Arıkan","poet_slug":"hakan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/korku-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstek', 'i-stek-hakan-arikan-fz59g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğim,

Ruhum,

Ve aklım,

Geçmişi hiç hatırlamasa.

Ben gene; 

Sokağın karşısındaki adam olsam,

Güneşi hiç görmesem,

Uzayan gölgeleri hiç takip etmesem,

Hatta; 

En iyi işi hiç yapmamış

Seni sevmemiş olsam.

Gene karanlık sokakta,

Evime girsem.

Sokaklar,caddeler boyu,

Küçücük olsa gölgeler,

Ve ben; 

O küçücük gölgelerde kaybolup gitsem.

Ama ne yazık ki,

Artık uzadı sokakta gölgeler,

Ve ben

Hiç vazgeçmedim seni sevmekten.

Ankara Kasım 2002', 'Yüreğim, Ruhum, Ve aklım, Geçmişi hiç hatırlamasa. Ben gene;  Sokağın karşısındaki adam olsam, Güneşi hiç görmesem, Uzayan gölgeleri hiç tak...', ARRAY['Türk Edebiyatı','Şiir','Hakan Arıkan']::text[], 8.5, '{"poet":"Hakan Arıkan","poet_slug":"hakan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/istek-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Bu Canımı', 'al-bu-canimi-caner-kuru-tnv1l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaplıyor arzular dört bir yanımı,

Durdurmak öyle zor deli kanımı.

İyisi mi Tanrım al bu canımı,

Günahıma günah katmadan önce.

Çevrildi gözlerim haramdan yana,

Ne de hoş geliyor her şey insana.

Sığınırım belki senin affına,

En derin azabı tatmadan önce.

Azabın şiddeti arttıkça artar,

Sonunda şu ruhum bedeni yırtar.

Beni hayat denen deryadan kurtar,

Daha da derine batmadan önce.', 'Kaplıyor arzular dört bir yanımı, Durdurmak öyle zor deli kanımı. İyisi mi Tanrım al bu canımı, Günahıma günah katmadan önce. Çevrildi gözle...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/al-bu-canimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Elinde Üç Parmak Bir elinde Altı', 'bir-elinde-uc-parmak-bir-elinde-alti-cumhur-boratav-pvkji', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kolaylıkla geldi aramıza

zorla ve zorlanmadan

bir elinde üç parmağı vardı

diğerinde altı

birini kurşun parçalamıştı

diğeri doğuştan

açtı ama 

duvarlardan sızan sudan

başka bir şey sunamadım ona

acı kımıldanıyordu karnında

açlık değil, ve su yüreğine iyi geldi

ısındı ve gece 

uykusunun sıcaklığını paylaştı benimle

gözlerinde haz değil acıydı parlayan

onun şiirini yazarken

parmaklarını tam çizmemi istedi

ben de onun şiirini şöyle bitirdim

bir elinde beş parmak vardı

diğerinde altı

ikisi de doğuştan

ama doğuştan değildi acısı', 'kolaylıkla geldi aramıza zorla ve zorlanmadan bir elinde üç parmağı vardı diğerinde altı birini kurşun parçalamıştı diğeri doğuştan açtı ama...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-elinde-uc-parmak-bir-elinde-alti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz', 'soz-evrim-nisan-ark5c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'rüzgarın savurduğu poşetlerden söz edelim seninle 

yılanın kumda bıraktığı alfabeden 

bir çocukla süt arasındaki ilişkiden 

dilenciye allah rızası için para veren bir ateistten söz edelim 

verilmiş sadakası olsun 

yağmurun belleğinden söz edelim bulutlar toplanınca 

newton''un bir ağaçta yerçekimine rastlamasından 

ki ademle havva da aynı ağaçtan değişik sonuçlar çıkarmışlardı 

aşkla yaklaşıp düşlerle uzaklaşmalardan söz edelim 

sözlerden söz edelim belki uzun belki kısa 

ama anlamlarının kesintisizliğinden 

burada olmak zorunda değiliz başka coğrafyalar 

başka iklimler hatta dünyalardan... 

her dünyaya bir bakış açılır sonsuz bekleyişte 

gecelerden söz edelim biz kapanan bakışlardan 

olmayanlardan söz edelim buna rağmen ölmeyenlerden 

dişlerin vücutta gezişi gibi yine adem ile havva 

yani yine yasak elmalardan söz edelim golden olanlardan 

sözün dönüp dolaşıp gelip ayni kapıyı çaldığı 

ve kim o demeyen seslerden söz edelim 

üzerini çizdiğimiz karaladığımız hatta 

güvenlik gerekçesiyle yırttığımız dizelerden söz edelim 

yoo! yasak değil! utanmayalım aşktan söz edelim 

tamam tamam baştan beri bundan söz edelim her cümlenin gizlisinde 

bira şişesinde keman çalan aşktan söz edelim 

cumartesiyi pazara bağlayan geceden gecenin içindeyken 

sessizliğin dudak sesleriyle bombalandığı 

mumun kendini neden yaktığını bilmediği geceden 

jean luc goddard''ın çektiği bir filmde dublör olduğumuzdan 

yoksa kim sarışın anılarına kilometreleri ekler ki bir otobüsün 

yalnızlık kokan penceresinden? 

halının altına süpürdüğün yaşamından söz edelim 

sonra siyahı daha yoğun beyaz bir resim olarak çıkardığın 

sözleri nasıl da bir bıçakla kesiyor gözler kısılıyor ses 

gece bitecek bitecek gece gece bitecek 

cemal süreya''dan söz edelim gecenin kısalığı hakkında 

şiirdir yalnız başladığı gibi biter son satırında 

söz...', 'rüzgarın savurduğu poşetlerden söz edelim seninle  yılanın kumda bıraktığı alfabeden  bir çocukla süt arasındaki ilişkiden  dilenciye allah ...', ARRAY['Türk Edebiyatı','Şiir','Evrim Nisan']::text[], 8.5, '{"poet":"Evrim Nisan","poet_slug":"evrim-nisan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/soz-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Sürü Noktalama İşareti Hayatımız', 'bi-suru-noktalama-i-sareti-hayatimiz-evrim-nisan-u6bc4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bi sürü noktalama işareti hayatımız, işte ondan belgesel

çekimi için imlanın örtülü ödeneğinden pay aldığımız  bir yalan

her birini kan revan içinde yazıyoruz her bir dize konsantre

bir yazı bir kışı özetliyor bir dize, kem gözlerden saklanan bir dize

noktalar koyuyoruz ah büyük başlıyoruz yeniden küçük harflere

bir demet harf atıyorsun bana Japon tarzında düzenlenmiş

seni saat üçte bekliyorum gecenin en olmadık yerinde

bu virgül zaten ne işe yarar dur biraz soluklan demekten başka

ziller çalıyor ve öğrenciler kapıları kapıyor hırsla

sen beni noktalama istiyorum anlarken beni yaşam dersinde

sana uygun bir fotoğraf aradım albümümde seninle nokta yanyana

pek te güzel çıkmışsınız  senin yüzünde belli belirsiz bir gülümseme

belli belirsiz bir hüzün virgül virgül çiselemekte

soru işaretlerine dayanmışsınız belki de o çekmiş gölgesi düşmüş yüzüne

saçlarımı saymıyorum ama onlar arap harfleri kufi biçimde dizilmiş

seninkiler bağırıyor ya her biri ondan ünlem dümdüz

sonra tırnakların bir işaret yüzümü avuçlarına aldığında

iki tırnak arasında vurgu yapılmış düş meyvesi kalıyorum

ben seni nasıl yaşıyorum sığınak parantezlerinde ben seni

bi sürü noktalama işareti hayatımız, işte ondan belgesel', 'bi sürü noktalama işareti hayatımız, işte ondan belgesel çekimi için imlanın örtülü ödeneğinden pay aldığımız  bir yalan her birini kan reva...', ARRAY['Türk Edebiyatı','Şiir','Evrim Nisan']::text[], 8.5, '{"poet":"Evrim Nisan","poet_slug":"evrim-nisan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bi-suru-noktalama-isareti-hayatimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düet', 'duet-evrim-nisan-c2nca', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'herkesten başka bir ben oluyorum öylece

yüzünde göremediğim o kıyıyla

  

                             dalgalar

öğrendim kendimle aramdaki kilometreleri

bir çocuğum senin birinci tekil şahısında

  

                               hâlâ

işte geziyorum içinde kör rüzgârlarınla

uzak ki böyle bir mumdan damladı

                               ayak izlerim

hangi oyunu oynasak başka kapı açılıyor

çünkü mızıkçı bir kaçak oluyor ellerinde

                                elektrik

o gündü ellerinden çıkan o imzalı itiraf

sabah kendini güneş hissettiğin o gün

                                 ikimiz', 'herkesten başka bir ben oluyorum öylece yüzünde göremediğim o kıyıyla                                 dalgalar öğrendim kendimle aramdaki ki...', ARRAY['Türk Edebiyatı','Şiir','Evrim Nisan']::text[], 8.5, '{"poet":"Evrim Nisan","poet_slug":"evrim-nisan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/duet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm...', 'kucugum-aynur-uluc-xieub', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küçüğüm… 

Sadece şeker isterdin 

Mermi yerleşti yüreğine

Sadece sevgiydi derdin 

Acı bulaştı terine

Sadece barıştı adını bilmediğin 

Özlediğin 

İstediğin

Beklediğin

Ölüm geldi bedenine', 'Küçüğüm…  Sadece şeker isterdin  Mermi yerleşti yüreğine Sadece sevgiydi derdin  Acı bulaştı terine Sadece barıştı adını bilmediğin  Özlediğ...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kucugum-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Karıştı Sıvısına Dünyanın / 1.', 'kan-karisti-sivisina-dunyanin-1-aynur-uluc-jfzj1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırmızıya boyandı çocuklar

Parçalanırken insanlık

İnlerken bir adam, tecavüzde

İnlerken bir kadın, askerin gölgesinde

İnlerken dünya, yalanın pençesinde

Yavaşca  çöktü utanç sahip çıkmayana 

Göz görmeyince gönül katlanıyordu

Ama göz gördü resimleri

Yüreklere dokundu parçalı bedenler

Yaşanan, ışıklı gösteri değildi ekrandaki

Ahenkli sorti dansı hiç değildi

Cesetler yığıldı meydan yerine

Kan karıştı sıvısına dünyanın

Yalan karıştı bile bile 

Para sırıttı yeşil yeşil

İnsan utandı ince ince

Direndi lanetledi  haykırdı

Savaşlar olmasın dendi

Barışcıl dünya düşlendi 

Mümkündü çünkü…

(haziran 2004)', 'Kırmızıya boyandı çocuklar Parçalanırken insanlık İnlerken bir adam, tecavüzde İnlerken bir kadın, askerin gölgesinde İnlerken dünya, yalanı...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kan-karisti-sivisina-dunyanin-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gök', 'gok-naime-erlacin-1pq94', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gürlüyor yukarısı

göğün kölesi oluyorum

sağanak oluyor 

toprak oluyor 

suyla büyüyor

suyu kucaklıyorum

bilirsin severim puslu havaları:

aşkın hayatiyetini saklarlar

kokusu çarpar ruhuma ıslaklığın

dolar kuyular

ırmak olup taşarım 

bir çift yağmur damlasından yaratıldık biz

sevdanın kızıl yaprağına düşen

al karanfilin esrarlı gölgesinde

al tut ellerimi korkma! 

hızla akıyorum yağmur damlacığına

gürlüyor gök yine

durma yaslan... sarıl boynuma 

(14 Haziran 2004)', 'gürlüyor yukarısı göğün kölesi oluyorum sağanak oluyor  toprak oluyor  suyla büyüyor suyu kucaklıyorum bilirsin severim puslu havaları: aşkı...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gok-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakasım Gelir', 'yakasim-gelir-caner-kuru-16g7r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En muhtaç anımda kaçtın yanımdan,

Ne istedin bilmem dertli canımdan.

Günlerce sızladı diye aşkından,

Kalbimi söküp de atasım gelir.

Seni sevdi, sana bağlandı diye,

Senle coştu, senle dağlandı diye,

Aşkından sel olup çağlandı diye,

Gönlümü ateşte yakasım gelir.

Seni hep kıymetli bir yar bilerek,

Ne hallere düştüm seni severek.

Yüzüne dokundu diye öperek,

Dudağımı zehir edesim gelir.', 'En muhtaç anımda kaçtın yanımdan, Ne istedin bilmem dertli canımdan. Günlerce sızladı diye aşkından, Kalbimi söküp de atasım gelir. Seni sev...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yakasim-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklıbahçem', 'saklibahcem-i-hsan-dinibutun-fr1j5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senden kaçtığımda

Sırtımı yere getireceğini anladığımda

Saklıbahçeme sığınırım

Beni bulamazsın

Hep orada  saklanırım

Orada kendimle kalırım

Ben, beni korur orada

Beni, ben yenerim ancak

Ben, masallar anlatır bana

O zaman ben çocuk olurum

Masallar bitsin istemem

Hep yeni bir masal isterim benden

Bu akşam yine bahçemdeyim

Saklanmışım senden

Ben, bana şarkılar söylüyor

Şiirler okuyor senden

Hiç duymadığım

Tanrım! ..

Bu şarkıları duymamıştım

Şarkılarda sevdan,

Şiirlerde gözlerin var

Bu kez kaçamıyacağım

Anladım

Ben bile sana gelmemi istiyor

Çıktım saklıbahçemden

Beni dinledim

Sana geliyorum

Bir daha anladım ki

Seni hala seviyorum.', 'Senden kaçtığımda Sırtımı yere getireceğini anladığımda Saklıbahçeme sığınırım Beni bulamazsın Hep orada  saklanırım Orada kendimle kalırım ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/saklibahcem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fezana Düştüğümden Beri', 'fezana-dustugumden-beri-necmi-unsal-66vxv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güllerin  üstündekini  sanma,

Sabah  çiğidir   diye! 

Her  seherde  damla-damla,

Dökülen  gözyaşımdır  biteviye.

Dolunay  gecelerimin  feneri,

Yıldızları  bahçeme  serptim.

Fezana  düştüğümden  beri,

Dünyayı  kara  deliklere  teptim.

24 Şubat 2004 Salı, Danimarka-Køge  23.20', 'Güllerin  üstündekini  sanma, Sabah  çiğidir   diye!  Her  seherde  damla-damla, Dökülen  gözyaşımdır  biteviye. Dolunay  gecelerimin  fener...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/fezana-dustugumden-beri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Gidişinin ardından', 'gidisinin-ardindan-i-lkgul-celebioglu-fq5x0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir çiçek açtı mevsimsiz

Ve mevsimsiz soldu gidişinin ardından.

Bir yağmur yağdı güneşin alnından

Ve düştü gözlerimden gidişinin ardından

Seni pamuklara sardım yüreğimde

Dokunamazlar sen kanayan bir yaramsın

Bir tebessüm ve  buseler kayboldu sensizken

Akrepler yelkovanlar kovaladı birbirini

gidişinin ardından

Ve zaman durmadı duramadı

Dursaydı zaman çiçekleri açtıracaktım

Ve bu gelişinin ilk adımları olacaktı

Güneşi öpecektim alnından 

Gözlerime tebessümünü hapsedecektim

Buseler bizim olacaktı; yaratacaklardı yeniden sevgiyi

...........................

..........................

Her mevsim  seni yaşatacağım yüreğim de

titreyen yüreğimde

sen tek güneşimsin', 'Bir çiçek açtı mevsimsiz Ve mevsimsiz soldu gidişinin ardından. Bir yağmur yağdı güneşin alnından Ve düştü gözlerimden gidişinin ardından Se...', ARRAY['Türk Edebiyatı','Şiir','İlkgül Çelebioğlu']::text[], 8.5, '{"poet":"İlkgül Çelebioğlu","poet_slug":"i-lkgul-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gidisinin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümün Gamzeleri', 'gonlumun-gamzeleri-i-brahim-bayraktar-70wkd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aramızdaki farkı biliyor musun? 

İkimizde aynı havayı soluyoruz.

Sen, nefes alıp, veriyorsun; 

Ben, burnumdan soluyorum.

Sonrasını hiç sorma; 

Gönlümün gamzelerini,

Seninle dolduruyorum.

14.06.2004', 'Aramızdaki farkı biliyor musun?  İkimizde aynı havayı soluyoruz. Sen, nefes alıp, veriyorsun;  Ben, burnumdan soluyorum. Sonrasını hiç sorma...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gonlumun-gamzeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** ßekLenen **', 'eklenen-gulay-yildiz-4vpwj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden içimdeki bu karanlık? Neden / se gidişinde arıyorum hep cevabı¿ Bir varolup sonra kaybolan, içimde ki tüm bu kelimelere sığmayan duyguları yaza yaza anlatamayacağım hissi neden gitmiyor? 

Oysa tek özlediğim mutluluk. Senden gelecek olan, yılların perdeleri altında ezilmiş ve sadece uzaktan açık gözlerini görebildiğim mutluluk. Yaşıyor mu yoksa sadece aklına takılanlarla mı ruhu göğe yükselmiş, onu bile ayırt edemiyorum. Seni anımsıyorum anahtarımla kapıyı açarken dahi. Hani kilit ve anahtar ilişkisi vardı, birbirini tamamlayan, ve ''biz buyuz'' derdik. Şimdi biliyorum ki bu kadar uyumlu olan başka bir  kavram yok.

Ağlamaklı kelimelerle, çığlıklı haykırmalarla dolu bir yazı yazıp, sonra kahrolası uykuya dalıp ve günlerce bilinçsizlikle arkadaş olup, adını bilmediğim bir öte de kalmak dileğim. Bunu bile yapamıyorum gibi...

Herşey senden uzakta ve tabi ki kararsızlıkta... Oysa, gülüşlerimi adadığım, geleceğimi ipotek ettiğim ve karşılığında onlu günleri satın aldığım bir mutluluğum vardı benim.

Gitti ve Bitti...

Haziran - 2004', 'Neden içimdeki bu karanlık? Neden / se gidişinde arıyorum hep cevabı¿ Bir varolup sonra kaybolan, içimde ki tüm bu kelimelere sığmayan duygu...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/eklenen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Kalemini', 'kir-kalemini-meral-yagcioglu-g0c04', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suçluyum biliyorum

Bastım tetiğe

Tek kurşunla

gönlümü mıhladım duvara

Sedef kakmalı kabzasına

Koca bir çentik attım

Bitirdim aşkı

Bir daha mı asla

Asla sevmeyecek bu beden

Ne seni nede bir başkasını

Sadece doğayla aşk yaşayacak

Çiçeği sevecek, kurdu, kuşu besleyecek

Denizi kucaklayacak, yağmurda yıkanacak

Biliyorum suçluyum

Tek suçlusu benim bu finalin

Yargısız olmasın infazın

Gece arşa kurulsun mahkeme

Dolunay ağlamaklı tanık

Hakim olsun hislerin

Savcıda gözlerin 

Mübaşir fersiz bir yıldız

Lal olsun dili sessiz çağırsın

Uyandırmasın uykumdan

Yorgun, kırgın bedenim dinlenmekte

İstemem avukat 

Savunmam yok ki

Ne duruyorsun

Aşk katilini cezalandır

Kır kalemini

Kur darağacını

Yüreğinin tam ortasına

Bırak sallanayım ipin ucunda

Biliyorum suçluyum 

Suçluyum 

14/06/2004', 'Suçluyum biliyorum Bastım tetiğe Tek kurşunla gönlümü mıhladım duvara Sedef kakmalı kabzasına Koca bir çentik attım Bitirdim aşkı Bir daha m...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kir-kalemini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Aşk', 'yalniz-ask-gulay-yildiz-7a7kr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beklenen

Ve

Beklendikçe yalnızlığa eklenen

Sanadır yazılan tüm çığlıklar! 

Çizilmez deme; 

Çizdim bütün haykırışlarını harf harf,

Geceyi tütsüleyen bir anne mırıltısında

Ve 

Yeni uykuya dalmış bir bebek büyüsünde

İçimdeki AŞK! 

Derin bir ışığın ardındaki fener kadar heybetli

Benden yayılıyor, benden yansıyor engine

Gittiği yer? 

Belirsiz...

Ucu yok, gözünün alabildiğine

Birileri kesse başının dönmesini

Sığınsa ılık bir koyna, uyusa...

/

Aşkıma ve kimsesizliğime acım

/

İkimiz bir depremin içinde,

Kırıldıkça büyüyen bir gürültünün

Sağır edişlerinde

Yapayalnızız...', 'Beklenen Ve Beklendikçe yalnızlığa eklenen Sanadır yazılan tüm çığlıklar!  Çizilmez deme;  Çizdim bütün haykırışlarını harf harf, Geceyi tüt...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalniz-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Davetsiz Misafir', 'i-ki-davetsiz-misafir-ozgur-aysun-beksari-wk98n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki tane misafirim vardır benim

Hani gelmeden önce haber veren ve

Bir fincan kahve içenlerden değil onlar...

Kendimi bildim bileli beklerim.

İkiside arada bir görünür

Yada  gördüğümü zannederim.

Biri hastalanınca görünür bana

Arkası kapkaranlık bir yıldız gibidir

Elinin birinde sevdiklerime acı...

Diğer elinde  bana huzur getirir.

Ölüm demişler ona,

Ben sonsuzluk diyorum.

Tek bir zamanı var onun

Davetsiz bir misafir o

Gelecek biliyorum.....

Diğeri umutlanınca görünür bana

Arkası acı dolu bir sahil gibidir..

Elinin birinde sevdiklerime huzur,

Diğer elinde  bana acı getirir.

Aşk demişler ona

Ben sonsuzluk diyorum.

Tek bir zamanı var onun

Davetsiz bir misafir o

Gelecekmi  bilmiyorum.....

Umarım ikisi ayrı zamanlarda gelir

Ama beraberde gelseler

Olsun...

Askta; ölümde, ömrüme

Sefa gelir 

Hos gelir.... 

Ve her ikisinede 

Boynum kildan incedir.....', 'İki tane misafirim vardır benim Hani gelmeden önce haber veren ve Bir fincan kahve içenlerden değil onlar... Kendimi bildim bileli beklerim....', ARRAY['Türk Edebiyatı','Şiir','Özgür Aysun Beksarı']::text[], 8.5, '{"poet":"Özgür Aysun Beksarı","poet_slug":"ozgur-aysun-beksari","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/iki-davetsiz-misafir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece...', 'gece-avni-aydin-as83z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sakindi gece...

yeni çıktım meyhaneden

ıslak kaldırımlarında şehrin

dolaşıyorum sessiz...

sensiz...

son demleri gecenin

birkaç sarhoş, şehrin sakini...

istanbulu selamlıyor yıldızlar...

usul usul bir yağmur yağıyor

sensiz kollarıma...

sahile iniyorum

gündüz inemem çünkü...

dayanamam aşıkları görmeye

boyle salaş gezmeye...

sensiz...

bahardayız...

bir türlü sevemediğim mevsimde

yalan aşkların mevsimi bu

ilk ayrılıkların mevsimi

kıyamadığım...

tüketim çağındayız dünyanın

herşeyi tükettiğimiz gibi

sevgiyi de

aşkı da tüketiyoruz...

duymaz...

ellerim cebimde 

yürüyorum bilinmeze

deniz sütliman...

akşamdan kalanlar sızmış kenarda

son sigaramı arıyorum...

yorgun yıllarıma inat 

içime çekiyorum mereti...

bir kaç uykusuz benim gibi

yollardalar

çehrelerine bakıyorum uzun

seni arıyorum

yoksun

utanıyorum....', 'sakindi gece... yeni çıktım meyhaneden ıslak kaldırımlarında şehrin dolaşıyorum sessiz... sensiz... son demleri gecenin birkaç sarhoş, şehri...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/gece-107-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Yaşama', 'benden-yasama-sirma-mersin-vdxsj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beklemekle geçmezmiş ömür

Mutluluk kapının dışındaymış,

Görmezmiş gözüm...

Söylenenlerle avunmazmış, ruhum...

Sevmekle değil, sevilmekle yaşanırmış,aşk.

Hayatı tanıdıkca öğrenirim,

Çekilen acıları 

Ve dertleri...

Sevenlerimin seslenişi ile çoğalırım, yüreklerde.

Dağıtırım  tüm yalnızlığımı

Birden bire 

Gelen şansım ile

Değişen  dünyada soluk alırım 

Yeterki...

Umudu almayın benden.

10.6.04', 'Beklemekle geçmezmiş ömür Mutluluk kapının dışındaymış, Görmezmiş gözüm... Söylenenlerle avunmazmış, ruhum... Sevmekle değil, sevilmekle yaş...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benden-yasama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabataş', 'kabatas-avni-aydin-9zzb5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kabataştayım

gözlerim denizde 

sanki birşeyleri bekler gibiyim...

amma da soğuksun hava

içimi titretiyorsun...

bugün dalgalar bozuk istanbul''a

her fırsatta dövüyorlar rıhtımı

kış ne güzel,

sulu gözlü istanbul...', 'kabataştayım gözlerim denizde  sanki birşeyleri bekler gibiyim... amma da soğuksun hava içimi titretiyorsun... bugün dalgalar bozuk istanbul...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kabatas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liman', 'liman-avni-aydin-enjk4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çok çabuk geçti zaman

ne de hızlısın

yetişemiyorum sana...

tutamıyorum...

gelsen

çıkıp gelsen

denizden

rüzgarlarla gelsen...

akıp gitse zaman

hatırlamasam hiçbirşeyi

yıllar geçse üstünden

acılarımın...

uğramıyor ama bu limana

mevsimin ilk rüzgarları,

bu şehirde zaman durmuş

her yeni acı yüreğimde,

sızısı...', 'çok çabuk geçti zaman ne de hızlısın yetişemiyorum sana... tutamıyorum... gelsen çıkıp gelsen denizden rüzgarlarla gelsen... akıp gitse zama...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/liman-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş', 'sarhos-avni-aydin-ue240', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir garibim bu akşam

biraz sarhoş,

kalem zor

kelimeler anlamsız

neredesin

nerede? 

özledim seni sevgilim

yoksun...

ellerim

ah ellerim boşluğu sarıyor

son bir söz daha 

özledim seni

başağrısı...

birden usuma giren

belki aşk belki hüzün

bir ayrılık bu baharın

son esintisi...', 'bir garibim bu akşam biraz sarhoş, kalem zor kelimeler anlamsız neredesin nerede?  özledim seni sevgilim yoksun... ellerim ah ellerim boşluğ...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sarhos-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-gok-tengri-mbf27', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalgalar dedi ki; ''gelmeyecek''

Rüzgar dedi ki; ''hiç bekleme''

Kaldırdım başımı göğe baktım:

''Üzgünüm'' dedi

Döküldü yağmurlar damla damla

Yine de umutluyum be gülüm

Serde Türklük var ya

Yine de umutluyum bi tanem

Benim nar tanem, nur tanem

Şimdi ne alaka deme

Çünkü Türk''ün umudu

Ekmeği ya!', 'Dalgalar dedi ki; ''gelmeyecek'' Rüzgar dedi ki; ''hiç bekleme'' Kaldırdım başımı göğe baktım: ''Üzgünüm'' dedi Döküldü yağmurlar damla damla Yine...', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umut-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susmaya Mahkum', 'susmaya-mahkum-i-smail-baharsen-iihtd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gümüşten bir kilit ardındayım

sokaklar yasak gökyüzü yasak

ıslak camlarda şefkati ararım

gülmek yasak ağlamak yasak

ne çiçek kokusunu bilirim

nede ışıl ışıl bir denizin

hazandı benim her mevsimim

yağmurlar yasak baharlar yasak

susmaktı yapabildiğim tek şey

bozuyordu beni böyle bırakan şey

bana yabancı dünya denen şey

sevdalar yasak  aşklar yasak

ihtimal olsa yıkarım duvarları

mümkün olsa yakarım rüyaları

tanımak isterdim insanları

dostlar yasak yaşamak yasak', 'gümüşten bir kilit ardındayım sokaklar yasak gökyüzü yasak ıslak camlarda şefkati ararım gülmek yasak ağlamak yasak ne çiçek kokusunu biliri...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/susmaya-mahkum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ciceklerin Dili', 'ciceklerin-dili-fatma-ay-hwtnm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir  beyaz  gül  gördüm. Sordum: Rengin neden beyaz  diye? 

Ben  yeni  dogdum,sabii,günahsizim, dedi.

Güldüm  ve  gectim.

Bir  pembe  gül  gördüm.

Sordum: Rengin  neden pembe? Diye.

Baksana,gökyüzü, bulutlar, toprak, heryer  pembe.

Ve  ben  cok  mutluyum.

Güldüm  ve  gectim.

Bir  kirmizi  gül  gördüm.

Sordum:Rengin  neden  kirmizi? 

Baksana:Seviyorum, seviliyorum

Coook,cook  mutluyum.

Güldüm  ve  gectim.

Bir  sari  gül  gördüm.

Sordum: Rengin  neden  sari? 

Baksana: Ayriyim,ayriyim.

Sevdiklerimden,sevenlerimden.

Gülümsedim  ve  gectim.

Ici  sari  cevresi  mor  menekse  gördüm.

Sordum: Rengin  neden  böyle? 

Baksana:Ayriyim, dünyam  kararmak  üzere.

Cok  mutsuz  ve  bedbahtim.

Dudagimda''ki  gülümseme  dondu  kaldi.

Gectim  ve  gittim.

Siyah  bir  gül  gördüm.

Sordum:Rengin  neden  siyah? 

Dünyam  karardi,heryer  kara, dag, tas, gökyüzü, toprak...

Hele  topragin  alti... Daha''da  kara.

Söyle  baktim  etrafa  ve...

Dedimki: Simdi  girdin  kara  topraga.

Eger  yasarken  yakin  isen  Allah''a...

Gül  kendin  icin  gül.

Ama...Hak  yiyenler, zalimler,hainler  icin  agla.

Bagira,  bagira ,kana , kana  agla.', 'Bir  beyaz  gül  gördüm. Sordum: Rengin neden beyaz  diye?  Ben  yeni  dogdum,sabii,günahsizim, dedi. Güldüm  ve  gectim. Bir  pembe  gül  g...', ARRAY['Türk Edebiyatı','Şiir','Fatma Ay']::text[], 8.5, '{"poet":"Fatma Ay","poet_slug":"fatma-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ciceklerin-dili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağlıcakla Kal', 'saglicakla-kal-i-smail-baharsen-l3t4p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu aşk burada bitsin demiştin 

kırmadım gönlünü bitirdim işte

bana gitmek düşer bende giderim

hadi hoşçakal, sağlıcakla kal..

dertlere çarpıp yıprandı mutluluk

hani o aşktıya tek gururluk

giderim yüzümü sarsada mutsuzluk

hadi hoşçakal,sağlıcakla kal..

istediğini bulursun başkalarında

unuturum senide  yokluğunda 

hatıralarıda koyuver bavuluma 

hadi hoşçakal,sağlıcakla kal..

son dileğim ardımdan el salla

üzül yokluğuma bir günde olsa

bunları yapman belkide zorsa 

hadi hoşçakal, sağlıcakla kal..', 'bu aşk burada bitsin demiştin  kırmadım gönlünü bitirdim işte bana gitmek düşer bende giderim hadi hoşçakal, sağlıcakla kal.. dertlere çarpı...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/saglicakla-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonrası', 'senden-sonrasi-i-smail-baharsen-zapv9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen benim dünyaya gelişim 

ne olabilirki daha başkası

sen ilk seviyorum deyişim

olmayacak senden sonrası

sevgi verdin kucak kucak

bilki gönlün mezarım olacak

sensin aşkıma en son durak

olmayacak senden sonrası

ahretim cennetim ateşimsin

yüreğim kalbim nefesimsin

candan ötede servetimsin

olmayacak senden sonrası

bahar gelir çiçeklerde

bir ümitsin gelecekte

gündüzlerde gecelerde

olmayacak senden sonrası..', 'sen benim dünyaya gelişim  ne olabilirki daha başkası sen ilk seviyorum deyişim olmayacak senden sonrası sevgi verdin kucak kucak bilki gönl...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-sonrasi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-meral-balci-tanis-hzs1o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok özledim

Bunu sana yazmayı çok istedim.

Nasıl tüttüğümü,

Nasıl özlem koktuğumu duymanı çok istedim

Ellerim defalarca gitti telefona

Ne hasretini dindirebildim,

Nede telefonla olan kavgamı bitirebildim

Seni çok özledim.

Garip bir duygu benimkisi.

Belki hiç anlamayacaksın beni

Sevgimi bil istedim.

Yazamadım, çizemedim,

Yanına koşamadım.

Seni unutamadım.', 'Çok özledim Bunu sana yazmayı çok istedim. Nasıl tüttüğümü, Nasıl özlem koktuğumu duymanı çok istedim Ellerim defalarca gitti telefona Ne ha...', ARRAY['Türk Edebiyatı','Şiir','Meral Balcı Tanış']::text[], 8.5, '{"poet":"Meral Balcı Tanış","poet_slug":"meral-balci-tanis","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ozledim-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bellimi Olur', 'bellimi-olur-i-smail-baharsen-3ssmo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir gece ansızın kapı çalarsa 

bir çırpıda açıver ne olur

belki bıkmışımdır sensizlikten

gelen benimdir bellimi olur

kulaklarıma ulaşıverir feryatların

olurya bana çıkar rüyaların

açık kalsın lamban ışığın

gelen benimdir bellimi olur

sensiz kalıverirse bizim oralar

dilime takılırsa hüsran şarkılar

azarsa içimdeki derin yaralar

gelen benimdir bellimi olur

hasta isen yarı ayık yarı baygın

sorulmaz ise sualin hatrın 

zor gelirse geceden sabahın

gelen benimdir bellimi olur..', 'bir gece ansızın kapı çalarsa  bir çırpıda açıver ne olur belki bıkmışımdır sensizlikten gelen benimdir bellimi olur kulaklarıma ulaşıverir ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bellimi-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayboluş', 'kaybolus-emirhan-bala-znm17', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'buralarda olmayışım, 

içimi yer tükenirim, 

sılaya, satırlara hasretim. 

yüreğimin kavalyesi, 

saklı nefesim, 

varoluşumun zerresi 

ılık ılık akar tükenirim...', 'buralarda olmayışım,  içimi yer tükenirim,  sılaya, satırlara hasretim.  yüreğimin kavalyesi,  saklı nefesim,  varoluşumun zerresi  ılık ılı...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kaybolus-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai barbar putlar', 'rubai-barbar-putlar-emirhan-bala-20jp0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'barbar putlar ne bilir ibadetin kıymetini 

ruhları kançanağı olmuş kulları, 

kara tahtadan silinmez isimleri, 

unuttum cehennem sıcağı sokakları...', 'barbar putlar ne bilir ibadetin kıymetini  ruhları kançanağı olmuş kulları,  kara tahtadan silinmez isimleri,  unuttum cehennem sıcağı sokak...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-barbar-putlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kuşu', 'ask-kusu-i-smail-baharsen-d17ps', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kalbimde hissettim ilk defa

aşk denen kuşun çırpınışını

gönlümde inler heyecanı hala

çaresiz yüreğim ona kanmıştı

hayatıma sessiz bir şahit gibi

sanki hep bana ait gibi

gözlerime yabancı bir kilit gibi

kapatıyor ömrüme kanatlarını

acı çekmek bile tatlı oldu

giden hayat onda son buldu

sevgim sanki büyüyle korundu

hissettim aşkın saf kutsallığını

en büyük yanlızlığımdı belkide

bu ayrılık yazan kara bahtım

bilmeden düşündüm terketmeyi

şimdi beynime vuruyor hatalarımı...', 'kalbimde hissettim ilk defa aşk denen kuşun çırpınışını gönlümde inler heyecanı hala çaresiz yüreğim ona kanmıştı hayatıma sessiz bir şahit ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-kusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telesekreter', 'telesekreter-baykal-kaanalp-le0vb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aranılmanın dayanılmaz

çekiciliği

sardığında yüreğimi(benliğimi) 

telesekretere koşarım

belki yüz kere dinlediğim

mesajını tekrar dinlerim

tekrar dinlerim

sanki ilk kez

duyuyormuşum gibi

kulaklarım açılırda açılr

sesini bir kez daha

duyabilmenin mutluluğudur

damarlarımda dolaşan

belki ayrılmışızdır

belki unutmuşsundur beni

yok yok olamaz

beni unutmuş olamazsın

sevmedim bu kurguyu

senin beni unutmuş olman

kurgusunu

düşüncesi bile itici

banal, sıkıcı

sıkıntı verici

iyi şeyler düşünmeliyim

diye geçirdim içimden

mesela şu an senin

beni düşündüğünü

gözlerinin içinin güldüğünü

hatta adımı 

duvarına yazıp

sık sık tekrar ettiğini

düşünmek

ne hoş değil mi? 

seni düşünmek kadar hoş

senin beni düşündüğünü

düşünmek

biraz daha yazmak 

istiyorum ama

telefon çalıyor

belki de sensin

beni arayan

belki de...

ben öyle olsun 

istiyorum

yine sardı benliğimi

aranılmanın dayanılmaz

çekiciliği', 'aranılmanın dayanılmaz çekiciliği sardığında yüreğimi(benliğimi)  telesekretere koşarım belki yüz kere dinlediğim mesajını tekrar dinlerim t...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/telesekreter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerin Sevgilisi…', 'askerin-sevgilisi-halit-demir-fkit2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonsuzdu hani sevgin, bitmeyecek demiştin

Ne büyük hisle beni, sevdiğini söylerdin

Gamzeler kaybolunca, hüzüne kilitlendin

Perişan bir haldeyim, Askerin sevgilisi….

Ben senin hasretinden, alaz alaz yanarım

Burası asker kaynar, düşüncemi yoklarım

Unuttun hanii diye, kendimi sorgularım

Bu sorgum doğrumudur, Askerin sevgilisi….

Dün gibi şu sözlerin, hâla kulaklarımda 

Seni çok seviyorum, seveceğim unutma

Sevgiden kastın buysa, bu dünyada yaşama

Sözün sözmüdür senin, Askerin sevgilisi….

Daha kaç ay oldu ki, böyle yapar mı insan

Sana insan demeye, varmıyor dilim inan

Sevgiler böyle ucuz, bende bitmez bu hüsran

Hazana döndüm şimdi, Askerin sevgilisi….

Bu sevgin üç aylıkmış, ayrılıktan uzakta

Sevene bu yapılmaz, yazıklar olsun sana

Beddua etsem bile, yürek dayanmaz buna

İki elim yakanda, Askerin sevgilisi….

Bu aşka çizik attım, bu defteri kapattım

Sen bana yaramazsın, bunu yeni anladım

Üç aylık ayrılıkta, sevgimi kaça sattın

Aşkı satan sendin be, Askerin sevgilisi….

Ben sana ne edeyim, ne ceza vereyim ki

Kolum bilekten değil, omuzdan kırık şimdi

Alem-i cihan olsan, bu kalbim sürgün şimdi

Sever mi artık seni, Askerin sevgilisi….

Halit Demir –11.06.2004/ERZİNCAN', 'Sonsuzdu hani sevgin, bitmeyecek demiştin Ne büyük hisle beni, sevdiğini söylerdin Gamzeler kaybolunca, hüzüne kilitlendin Perişan bir halde...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/askerin-sevgilisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin', 'sensin-baykal-kaanalp-jeigc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'soğukta üşüdüğünü 

hissetmeyesin diye 

bir yudumda içtim 

donuk bakışlarını 

sensin gönül penceremdeki 

yeşil kuş 

salıverdiğimde 

kaçıp gitmeyen 

sensin yağmur bakışlı 

ağıt yüklü benimle 

sadece benimle 

dolup taşan 

gönül verdiğinde 

geri istemeyen 

kendisiyle birlikte 

gömen acılarını', 'soğukta üşüdüğünü  hissetmeyesin diye  bir yudumda içtim  donuk bakışlarını  sensin gönül penceremdeki  yeşil kuş  salıverdiğimde  kaçıp git...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensin-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazırım', 'hazirim-i-smail-baharsen-j8pyn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bekletme dilinde son sözünü

kötü söyle istersen hazırım

çekinirsen öne eğ yüzünü

hadi gönlümü yıkıver hazırım

benki çileli bir ömür sahibi

benki yaralı bir gönül sahibi

benki bu aşkın en son şahidi

hadi boynumu büküver hazırım

nice rüzgarlara dayanmışım

ben ne yalnızlıklar yaşamışım

dert yağmurunda ıslanmışım

hadi umudumu kırıver hazırım

geceler dost meyler sırdaşım

yokki başka kavim kardaşım

gezerim eğik olsada başım

hadi son kurşunu sıkıver hazırım....', 'bekletme dilinde son sözünü kötü söyle istersen hazırım çekinirsen öne eğ yüzünü hadi gönlümü yıkıver hazırım benki çileli bir ömür sahibi b...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hazirim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onsuz', 'onsuz-baykal-kaanalp-92amt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 've düşün

düştüğün

düşkünlüğü

onun uğruna

ve buyur et

karalama defterlerini

gecenin ortasına

düşünde

onun için

ve ağla

ulaşmak istemediğin

geleceğine

onsuz', 've düşün düştüğün düşkünlüğü onun uğruna ve buyur et karalama defterlerini gecenin ortasına düşünde onun için ve ağla ulaşmak istemediğin ge...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/onsuz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Doğmalı', 'gun-dogmali-baykal-kaanalp-8t454', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gün doğmalı

üstüne çalınmış aşkların

vurgun yese bile

gün doğmalı

üstüne küçücük taşların

ama sabretmeli doğarken', 'gün doğmalı üstüne çalınmış aşkların vurgun yese bile gün doğmalı üstüne küçücük taşların ama sabretmeli doğarken...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gun-dogmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulunur Elbet', 'bulunur-elbet-i-smail-baharsen-nyn14', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'nasıl ve neden gittinde sanki

mutlumu edecek seni gurbet

her derde derman vardırki

gönlümüde avutan bulunur elbet

nede gözüm olsun dünyada

bak aşkımda kaldı yarımda

sende çekip gittin sonunda

halimi anlayan bulunur elbet

nice dertli insanlar var

hayat dediğin zalim gaddar

bitirmeden beni sensiz yıllar

derdimi paylaşan bulunur elbet

belki bir şiir belki bir şarkı

bir şişe şarap belkide rakı

düşürmem elimden sigaramı 

seni unutturan bulunur elbet...', 'nasıl ve neden gittinde sanki mutlumu edecek seni gurbet her derde derman vardırki gönlümüde avutan bulunur elbet nede gözüm olsun dünyada b...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bulunur-elbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte Gözlüm', 'sahte-gozlum-i-smail-baharsen-840oz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'huzur arayan şu gönlüme

bir peri kızı gibi güldün

kanmışım yalan maskene 

kanmışım be sahte gözlüm

utanırda yerlere bakardın

yalandan yalandan ağlardın

her zaman sen haklıydın 

haklıydın be sahte gözlüm

bekletmek en büyük zevkindi

hani sen gerçekçi sevdindi

yalandın,ayrılığın gerçekti

yalandın be sahte gözlüm

bilmeliydim zamansız gitmenden

vedasız hoşçakalsız terketmenden

sevdim seni bir şey beklemeden

sevdim be sahte gözlüm...', 'huzur arayan şu gönlüme bir peri kızı gibi güldün kanmışım yalan maskene  kanmışım be sahte gözlüm utanırda yerlere bakardın yalandan yaland...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sahte-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sevgim Asude', 'bu-sevgim-asude-halit-demir-qla7b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu Sevgim Asude

Bu sevgim Asudedir, yanar tutuşur

Gönlümdeki ateşin, bak hâla durur

Sıcağın damarımda, kanım  kurutur

İliğimi erittin, be vicdansız ……

Avare dolaşırım, gönlümde yaran

Kendimi bırakırım, bir gün yarlardan

Günlere set vurulmaz, artık aylardan

Yıllarımı mahvettin, be vicdansız…

Ben ki seni ömrüme, sokmamalıydım

Bu ömrü tüketmezdim, zaman koyardım

Gündüzleri hep gece, gibi yaşadım

Günlerimi zehrettin, be vicdansız…

Saçımda siyahım yok, sütten de beyaz

Gamzelerim çöküşmüş, gülüşüm ayaz

Çıkmaz ömrüm bahara, belki de bu yaz

Hayatıma tehrettim, be vicdansız…

Bu ayaklar taşımıyor, artık bedeni

Bir ayağım çukurda, belli değil mi? 

Bu zulmü ben çektim, haberin ne ki? 

Gençliğimi mahvettin, be vicdansız…

Omuzlar düşmüş yana, gözler çukurda

İki dişim kalmıştı, şimdi ağzımda

İki elim kalsın be, senin yakanda

Bedenimi çürüttün, be vicdansız…

14.06.2004-Halit Demir / ERZİNCAN', 'Bu Sevgim Asude Bu sevgim Asudedir, yanar tutuşur Gönlümdeki ateşin, bak hâla durur Sıcağın damarımda, kanım  kurutur İliğimi erittin, be vi...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bu-sevgim-asude-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Cezir''leri de Severim.', 'ben-cezir-leri-de-severim-mine-ozdemirtas-muv38', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akdeniz’in Okyanus tan ayrılışı gibi........ çizgi nin iki yanında

ikiye bölünüyor ve   bir türlü bütünleşemiyor değil mi yüreğin? 

Birinden bir diğerine geçirmeyi asla beceremediğin

O bir tek damla içindeki kristal zerrenin

hasretiyle;  yok olurken, mercan kümelerim

bütün  kıymetli batıkları çamurla örtüyorsa derinlerim

Suçlusu ben değilim.

Eğer,

ıstırabını duyabilseydin İncisini kaybeden istiridyelerin

neden çığlık atıp kabuk kararttığını da anlayabilirdin midyelerin.

Madem ki,saçını ıslatmaya bile yetmeyecekti nefesin

o halde,bu  derin sularda işin ne senin? 

keşke, Deniz Kızı öyküleriyle bulanmadan önce düşüncelerin

rehberlik etmeleri  için yunuslarıma tutunabilseydi ellerin.

Şimdi....... gittikçe kaybolurken ufuk çizgin

kayalıkların da... tek tek sönecek olan fenerlerin

Suçlusu ben değilim.

Cebeli Tarık ta ki o görünmeyen ve aşılamaz perdede

Bir ömrü tüketmeye

Zar tutuyorsa elin...  yani.. buysa niyetin...beni düşünme hiç

bütün okyanusları gözlerime koyar.... usulca giderim.

Gelişim med di ya...olsun.... ben cezir''leri de severim.

Bir sabah kalktığında; 

kıyılarını tuza bulamış olursa köpüklerim.

ve kumsalda terkedilmiş haldeyse küreklerin

O sabah; kararacak olan göklerin 

Suçlusu ben değilim.

13/06/2004 çamlıca..23.40', 'Akdeniz’in Okyanus tan ayrılışı gibi........ çizgi nin iki yanında ikiye bölünüyor ve   bir türlü bütünleşemiyor değil mi yüreğin?  Birinden...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-cezir-leri-de-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Böyle Kal', 'hep-boyle-kal-i-smail-baharsen-x4s0b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bitmesin bu hayal bitmesin bu rüya

gitme hiç bir  yere yanımda kal

geçmesin zaman dönmesin dünya

sen değişme hep böylece kal

ne ağlasın siyah gözün ne üzülsün

mutluluk hep yüzünü güldürsün

bu masal gibi yıllarca sürsün

sen değişme hep böylece kal

bahçelerinden eksik olmasın sevgi

sende biriksin dünyanın sevinci

hayatta göresin gerçek cenneti

sen değişme hep böylece kal

ağarmasın bir tek saçın bile

kırılmasın kalbin bir dert ile

yaşa doyasıya hayatı gönlünce

sen değişme hep böylece kal...', 'bitmesin bu hayal bitmesin bu rüya gitme hiç bir  yere yanımda kal geçmesin zaman dönmesin dünya sen değişme hep böylece kal ne ağlasın siya...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hep-boyle-kal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Bakalım', 'git-bakalim-i-smail-baharsen-meoa3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'git bakalım  vefasızım git,

ardında koca bir hüzün bırakıp

taşlar gibi sertleşen duygularını

kalbimi parçalayarak söküp

git bakalım hayırsızım git...

ağlayan geceleri susturmadan

git bakalım vicdansızım git..

son bir defa sarılmadan

git bakalım vedasızım git..

git bakalım kalp sızım git...

gözü körüm kulağı duymazım

yüreği taşım bakışı belalım

teni sarı yüzü beyazım

sırtımdan bağrımdan vuranım

git bakalım insafsızım git

git bakalım gönül sızım git....', 'git bakalım  vefasızım git, ardında koca bir hüzün bırakıp taşlar gibi sertleşen duygularını kalbimi parçalayarak söküp git bakalım hayırsız...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/git-bakalim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedi...', 'dedi-melek-midikoglu-ohn2w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiyi suya anlattım

Üzerinde seni gördüm

Durmadım kaçtım

Birde baktım içimdesin

Yüzümdeki 

Gülücük ele verdi seni

Dile geldi kalemim

Ve dedi; 

''Sevdim''...', 'Sevgiyi suya anlattım Üzerinde seni gördüm Durmadım kaçtım Birde baktım içimdesin Yüzümdeki  Gülücük ele verdi seni Dile geldi kalemim Ve de...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dedi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai 3', 'rubai-3-emirhan-bala-eik83', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'öfke dilimde kapkara,

esiyor bezirgan fırtına,

hergele duygularım yalınayak,

sevdim mi severim delikanlıca...', 'öfke dilimde kapkara, esiyor bezirgan fırtına, hergele duygularım yalınayak, sevdim mi severim delikanlıca......', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-3-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şekil yanıltır bizi', 'sekil-yaniltir-bizi-metin-kose-m8azw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aynı dereden içer 

İkisi de iyi mi

Aynı çayırda gezer

İkisi de kötü mü

Ankara

(14 haziran 2004)', 'Aynı dereden içer  İkisi de iyi mi Aynı çayırda gezer İkisi de kötü mü Ankara (14 haziran 2004)...', ARRAY['Türk Edebiyatı','Şiir','Metin Köse']::text[], 8.5, '{"poet":"Metin Köse","poet_slug":"metin-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sekil-yaniltir-bizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değiştir Beni Değiştirebilirsen', 'degistir-beni-degistirebilirsen-ozgur-aysun-beksari-4gpsw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hadi değiştir beni değiştirebilirsen

Sevgilerim var benim. 

İstesem bir hamamböceğini bile

Sevebilirim.

Eğer yargılanacaksam sevgi suçundan

Ve mahkum edilirsem müebbet sevgisizliğe

İstemem....

İpi boynuma kendim geçirebilirim.

Hadi değiştir beni değiştirebilirsen,

Öfkelerim var benim...

İstesem bir çocuk katilini

Tek kurşunla öldürebilirim.

Eğer yargılanacaksam öfkem için

Ve mahkum edilirsem müebbet duyarsızlığa...

İstemem....

İpi boynuma kendim geçirebilirim.

Hadi değiştir beni değiştirebilirsen

İnançlarım var benim. 

İstesem yepyeni bir dini

Savunabilirim.

Eğer yargılanacaksam düşünce suçundan

Ve mahkum edilirsem müebbet inançsızlığa

İstemem....

İpi boynuma kendim geçirebilirim.

Hadi değiştir beni değiştirebilirsen

Hırsızlığım  var benim.

İstesem gökyüzünü soyup 

Yıldızları körlere dağıtabilirim.

Eğer yargılanacaksam hırsızlık suçundan

Ve mahkum edilirsem müebbet bir hücreye

İstemem....

İpi boynuma kendim geçirebilirim.

İsterlerse

İp te vermesinler bana

Kendimi yakıp

Küllerimi havaya savurabilirim......

Hadi değiştir beni değiştirebilirsen! ! !', 'Hadi değiştir beni değiştirebilirsen Sevgilerim var benim.  İstesem bir hamamböceğini bile Sevebilirim. Eğer yargılanacaksam sevgi suçundan ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Aysun Beksarı']::text[], 8.5, '{"poet":"Özgür Aysun Beksarı","poet_slug":"ozgur-aysun-beksari","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/degistir-beni-degistirebilirsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mitil Osman', 'mitil-osman-i-smet-barlioglu-yxe49', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen bir öğrencisin Mitil Osman,

Okuyup durursun A ''lardan Z ''lere

Ne idüğü belli olmayan bir gelecek için

Güzel kızlar dolu bir kentin üniversitesinde,

Bense; bir askerim Mitil Osman,

Polatlı ''nın kıraç bir tepesinde.

Ben askerim Mitil Osman,

Postallarım güllerden hafif kutsal topraklarda,

Başım ak-pak sarhoşluğunda bulutların,

Burcu burcu Mehmetçik kokar başım, yüreğim,

Ayaklarım, ellerim,

Ürperen hücrelerim,

Bu vatanı sen beklemezsin sonsuzluğa inat,

Ben beklerim.

Ben askerim mitil Osman,

Senin çulun-çaputun yok, benim üniformam var,

Benim kokartım, apoletlerim, demirlerim var,

Nice bir bakışlar düğümlenip duruuor

Apoletlerime, demirlerime, yüzüme,

Körpe fidanları kıskandıran boyuma,

Saba Melikesi Belkıs ''a bile tepeden bakmıyorsam; 

Günahın boynuma.

Ben askerim Mitil Osman,

Ne yağmura başeğerim, ne kara, ne tipiye,

Ne kışın üşürüm, ne yazın terlerim,

Körpe sabahları ben indiririm senin dünyana

Geceleri tespihler gibi çekerek teker teker

Kıraç tepelerdeki gümüşten aylar altında,

Hayallerim kurşun gibi giden atların sırtında

Sen her gece sınav sınav sayıklayarak dönüp dururken

Uykunda.

Ben askerim Mitil Osman,

Ben vatanım, ben bayrağım, ben namusum,

Bedenimi mızrak gibi saplamışım tepelere,

Kollarımı Edirne ''den Ardahan ''a kadar açarak

Ve Sinop ''tan Antakya ''ya uzanarak

Kucaklamışım tüm vatanı.

Kanımı peşinen helal etmiş,

Canımı peşinen bağışlamışım

Ve sıra sana gelinceye kadar Mitil Osman,

Bayraklaşmışım.

(MİTİL OSMAN ismi altında toplanmış serbest şiirlerinden > 7-8/100)', 'Sen bir öğrencisin Mitil Osman, Okuyup durursun A ''lardan Z ''lere Ne idüğü belli olmayan bir gelecek için Güzel kızlar dolu bir kentin ünive...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/mitil-osman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin kırık ayna...', 'bin-kirik-ayna-omer-faruk-girgin-h45hd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'soğuk bir gece! 

deniz buz tutmuş 

üstü cam gibi

yürüyorum üstünde

altı balık dolu

gümüş renginde…

üstüm parlak bir lacivert

altım dökük yaldızlı eski bir ayna

aynaya bakıyorum

sanki yüzü 

biraz benziyor sana..

ileride biri var

sen sanıyorum 

koşuyorum

olmuyor! 

fakat gittikçe gidiyorum

yüzüm

gittikçe denize benziyor…', 'soğuk bir gece!  deniz buz tutmuş  üstü cam gibi yürüyorum üstünde altı balık dolu gümüş renginde… üstüm parlak bir lacivert altım dökük yal...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bin-kirik-ayna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmez misin?', 'olmez-misin-i-smet-barlioglu-n3ewx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kafası dolu olmak ne demek, bilmez misin? 

Düşün ki; 

Sen de benim gibi, mermer bir masadasın,

Kafan dolu.

Sigara dumanları arasında

Bulut bulut sevdiğin,

Silinip gitmiş dünyalardan.

Ölmez misin? 

Boşuna mı vuruyorum kafamı duvarlara? 

Duvarlar boşuna mı davul, kafam boşuna mı tokmak? 

Sanıyor musun ki; yüreğim sızlayıp acıyacak? 

Bilemedim değerini bir gerçek sevgilinin,

Dağıtma dumanlarımı, bırak; 

Hayali yanımda duracak.

Öperdim saçlarını, ağlardı,

Dudaklarını, parmaklarını öperdim, ağlardı,

Ağlardı, şansımız az-biraz yolunda gitse.

Denizden almıştı yaşlarını,

Rüzgarlardan, sonbahar yağmurlarından,

Gözyaşı olup dökülürdüm ben bile

Yanaklarından.

Bunlar onun gözyaşlarıdır kadehlerimde,

Şu ıslaklıklar bu kuruyası ellerimde,

Şu bulutlar,

Şu sırılsıklam olmuş rüzgar,

Şu nur,

Şu görünüp görünüp kaybolan ay,

Şu pencerelerde türküleşen yağmur.

Kafası dolu olmak ne demek, bilmez misin? 

Düşün ki; 

Sen de benim gibi, mermer bir masadasın,

Kafan dolu.

Sigara dumanları arasında bulut bulut sevdiğin,

Silinip gitmiş dünyalardan,

Ölmez misin? 

Kafası dolu olmak ne demek, bilmez misin? 

(Hikmet BARLIOĞLU (1933-2003)   ''nun

MİTİL OSMAN ismi altında toplanmış Serbest Şiirler ''inden > 9-10/100)', 'Kafası dolu olmak ne demek, bilmez misin?  Düşün ki;  Sen de benim gibi, mermer bir masadasın, Kafan dolu. Sigara dumanları arasında Bulut b...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/olmez-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçip Geçip Gidivermek', 'gecip-gecip-gidivermek-i-smet-barlioglu-gbtt6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu akıp giden su benim,

Sularıyla kayaları yalayan ırmak,

Kanatlarını sularda çırpıp duran kuş,

Bu yokolup gidiş,

Şu savruluş,

Şu bir an sonra bir anı olan zaman,

Şu yangın,

Şu alev,

Şu kül,

Şu duman.

Anı olup kaldım kendime, yıllar yılı,

Geçen her anımı gözyaşlarımla arayarak,

En durgun hayalimi

En durgun sularda bulamayarak.

Ne sesim bir sığınak bulabildi kendine,

Ne bir durakta kalabildi hayalim,

Ne tozlu-tozaklı yerlerde çıplak izi ayaklarımın,

Ne saçlarımın yorgunluğu durabildi yerli yerinde,

Ne şakaklarımın.

Ne bir dal bulabiliyorum tutabilecek,

Ne dayanabilecek bir zemin,

Ne yüreğimde takat var, ne elimde olanak,

Seyredip duruyorum andan ana eridiğimi,

Kendimden eksiltip kendimden verdiğimi,

Akıp akıp gittiğimi billur gibi sularca

Ve sularca

Kirlendiğimi.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

MİTİL OSMAN ismi altında toplanmış Serbest Şiirler ''inden > 11-12/100)', 'Bu akıp giden su benim, Sularıyla kayaları yalayan ırmak, Kanatlarını sularda çırpıp duran kuş, Bu yokolup gidiş, Şu savruluş, Şu bir an son...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gecip-gecip-gidivermek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Başak saçlı**', 'basak-sacli-kubilay-enginol-yu8ws', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir günlük aşk yaşamak istedi

Parası,buna yeterdi

Yapmacıkta olsa,aşktı yaşanan

Birazda sevgi filizi,yüreklere uzanan

Sarı,başak sarıssı saçları vardı

Masumiyet ötesi yüzü

Biraz uğraşsalar,fedakarlık olsa

Olurdu belki,harika bir aşk öyküsü

Uzun,uzun kokladı hasretini

Pembe bulutlarda yumdu gözlerini

Yudum,yudum içemedi aşk suyunu

Kıyamadı,yüreğini ekmek etti,bandı

Güneş gelecek diye yüreği sızladı

Teskin etti kendini,sabaha vardı

Göğsünü yastık etti başına

Mutluluk türküleri dudağında', 'Bir günlük aşk yaşamak istedi Parası,buna yeterdi Yapmacıkta olsa,aşktı yaşanan Birazda sevgi filizi,yüreklere uzanan Sarı,başak sarıssı saç...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/basak-sacli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parkta Çocuk', 'parkta-cocuk-yusuf-ter-gqi5a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mehtap için

I

oturmuş  bir bank üzerinde 

karşımda oynayan çocuğa bakıyorum

masum,küçük,bilgisiz

dünyadan ilgisiz

koş küçüğüm oyna

büyüyüp serpilene dek,

hiçbir şeyi aklına koyma

dünyanın pisliklerinden

düzenin çirkefliğinden habersiz

oyna

   hayat senin küçüğüm! ! ....

coşku,sevinç,heyecan

dünya senin küçüğüm

hakimi senmişsin gibisarıl ona

bir gün son bulacak

hayatın  mücadeleyle  sorunlarla dolacak

hangi yöne gideceğin bilinmez

belki sana  seçenek sunulacak

çizdiğin yol

ömrünün sonuna dek yürüdüğün iz olacak

öyle bir yaşaki

oynadığın oyun gibi heyecanlı....

öyle bir ömür sürki

sevgi ve sevecenlık  dolu

onur ve gurur anahtarın olsun

onunla her kapıyı acacaksın

sevgini, şefkatini rehberin yapacaksın,

ama asla benım gibi yanılmayacaksın...

yol gösterenin olsun

nasihat edenlerin iyilikten yana olsun

öyle kararlar verki

sonunda  pişmanlık olmasın

öyle hatalar yapki

geri dönüşü  mümkün olsun

küçüğüm! ! ! ! ! ......

113

II

hayat  dolu  çocuğum oyna  doya doya

tadını çıkar  bu çocukluğun geri dönüşü olmayacak.....

öyle bir oyun oynaki

bir önceki günü aratmayacak

çocukluk her insana bahşedilen kutsal  bir armağan

ne yaparsan yap çocuktur  bu  denilip  hiç bakılmayacak

ömrünün sonuna dek  edindiğin en temiz hatıralar 

çocukluğundan kalacak......

oyna küçüğüm 

doya doya 

doy oyuna......







114', 'Mehtap için I oturmuş  bir bank üzerinde  karşımda oynayan çocuğa bakıyorum masum,küçük,bilgisiz dünyadan ilgisiz koş küçüğüm oyna büyüyüp s...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/parkta-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mucizeler doğuran-‘sislerden çıkan-kor ışığı’', 'mucizeler-doguran-sislerden-cikan-kor-isigi-akin-akca-r7nv1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '… Rasputin’in gözleri koskoca bir çarlığı büyüledi-solucan dilli

Ve çar ve ailesini bir bodrum katında felakete sürükledi:

Kendi amaçları adına, Çar’a duymasını istediğini söylemişti.

Zaman geçti devrim yükselirken, kendi halkı ondan nefret ederken; 

Haberi fakat yoktu onun bundan- bir aile, hunharca katledilirken.

Gerektiğinde savaşmak, var olana sahip olmak için:

Yoko, bir cadı lanse edilen; ama başkasıydı John Lennon’ı vuran

Hayal etmek yaratmaktır, olması istenene yıkılmaz temeller hazırlamaktır:

1415’te dikildi altı, yedi bin asker; yirmi yedi bin kişilik

Bir ordu karşısında; nehrin ötesindeki Fransızlara karşı, V. Henry- 

Hemen hemen olanaksızdı ufukta zafer, Kurtuluş Savaşı gibi.

‘Giderek buz veren’ havada, yağmur geliyordu.

V. Henry, bitik askerlere, Shakespeare’nin ağzından -bilindik- haykırdı:

“Avın üzerine atlayacak birer tazı gibisiniz.Görüyorum! 

Yerinizde duramıyorsunuz! az kaldı! başlıyor oyun! 

Ruhunuzu izleyin! ve saldırırken haykırın Tanrı’ya! …”

Sıradan insanlardı gökyüzünü oklarıyla bulutlar halinde donatan,

Usta bir zekaydı, çökertemediği yürek, bilgi ediniminin-

Kendiyle çarpışan yeknesak bir vücutta

Gandalf, Mryddin ve Aragorn; tozlu efsanelerden günümüze ulaşan

Beklendiği üzere: tabi ki Mustafa Kemal, Wallace ile Franklin,Benjamin; 

Vesaire: ilerliyordu idealler, düşünen ama sorgulayan! …

Ford nehri üzerinde, çömelmez bir orduydu bozguna uğrayan.

Şan, şöhren gölgen bile olamadı, bir çan çaldın

Ve ardından sürükledin Wallace -düzensiz kalabalıkları

-Direnmeye, kırmızı urbalı’ya, aynı I. Elizabeth gibi-

Halkını kendinden sayan bir kraliçe-kumandan.

Özgürlük istedin, özgürlük aldın; sökerek aldın, kendi ellerinle.

Mevcudiyetin ispatı ve geçmişe duyulan saygının canlanışı,

Sterling Köprüsü Muharebesi: Özgürlük! Bağımsızlık:

Mutlu etmeye yönelik, halkları, ‘kudret gözlemleyişleri; 

Bir kral yapmadı onları, bencil çıkarlar peşinde koşmayanları

(Tüm bu uğraşıyı sergileyenleri)     Ve herkes, onlardan:

 Bildiler, bilerek ilerlediler -çok önceden bunu.

-

Wallace: İskoç kahramanı (cesur yürek)', '… Rasputin’in gözleri koskoca bir çarlığı büyüledi-solucan dilli Ve çar ve ailesini bir bodrum katında felakete sürükledi: Kendi amaçları ad...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mucizeler-doguran-sislerden-cikan-kor-isigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Üstünde Ateş İzleri 2', 'deniz-ustunde-ates-i-zleri-2-derin-deniz-019ss', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatı az göremediğin halde

üç adımda sokuldun düşülkelerime

akşama çok vardı

kalabalık bir sabahtı

avcuma terini akıtıp

yüreğimin paslı damarlarını yağladın

Aydınlıklarla dolu bak düşlenirken

kirli sayfaların arasından

güneşi özlet bana

sen güneş ol geceleri oturduğun evlere

gezdiğin patikalara

söyleştiğin insanlara

ekmeği umut gibi sunan

gecekondulu gözlere güneş ol...

Aşklara güneş ol,tutkulara...

gözlerinde hüzün durgunluğu taşıyan insanlara

ak gelinlikleri tabut içinde titreyen

kekik kokulu sevişmelere...

Güneş ol,

tank paletleri altında terkedilen

erken hayat izlerine

elinde bir tek keder kalan ülkere,

sınırından taşan düşlere

greve güneş

kaybedilen canlara

ve gülen bir kavganın aşkına

Karlar güneşe dayanmaz unutma

Bir sevdanın kırmalı tüfeğidir aşk...

GüL ol bir de,GüL

bir tek GüL direnir çünkü

kendi doğurduğu dikeniyle

Ben bu asilikleri senden öğrendim,

dur kaçma,kirli sularda yıkanma

kapama gözlrini çocukluğuna

çocukluğunu yağmalama.

Salıncaklara ihanet etme,dönme dolap sevinçlerine,

dur kaçma.

Açma albümdeki solgun resimleri,

çırılçıplak günlerin masumiyetini...

Suları öyle dökme,dur gitme.

Çölü var bu hayatın,geç kalmışlığı var.

Bir de saatin durmuşluğu.

Gözlerine sıkışan rüzgar,yapışan yağmur.

Bir de yengeç kıskacı acısı sözlerin var.

Dur.

Kaçırılmış gemi telaşı ömrüne kaçma

Ben bu asilikleri senden doğurdum

çocukluğumu cenazelerde yoğurdum sonra

erken büyüdüm,hemen terkedildim.

Bu yüzden bir göze çarptığında gözlerim,

kapanacağı saati bilirim.

Dur.

Ben bu asilikleri senden çaldım

sonra sevenlerin aklını çeldim

Dur.

Sana düştüm...

Elini sür,günüm sarsılsın

istersen yarışırım,en çok kim yıkılır

en çok kim ölürse umut ona çoğalır.

Elini sür.

El değmemiş aşk aşk unutulur.

Yoksa ülkesiz kalınır,yalnızlığa kaçılır.

Adımıza ad katılır,ardımıza kurşun...

Sen hiç yüzünce koştun mu? 

Sırtını bu güne dönüp yüzünce koşmaktır aşk

Sen hiç ekmek oldun mu? 

Açlık giderdin mi hiç,mis gibi koktunmu sevdaya...

Aşk bir itirazdır

ve itirazımız sürmektedir

elini sür,iki ülke kardeşlensin; 

önce güneşlensin ve temizlensin...

Bir tetik düşümü zamana sığar aşk,

firar sabrına.

Esir düşenin işidir firar 

duvardan,

demirden,

topraktan...

Örümcek gibi sessiz ve çaktırmadandır

aşk bir firardır...

Yollar firarları koynuna almaktadır

Şükür ki koynunda ne çok yer vardır.

Sonra giden gemilerin ardından bakakalırsın; 

bukağılanır ve buğulanırsın.

Ağlamak sana düşer,uğurlamak da.

Ve hep kalan olursun:

Limanda yalnız,

filikalarda küreksiz,

oltada iğnesiz,

iğnede yemsiz...

Hiç özlem kokmaz olur avuçların.

Ağların balıksız,

hayatın gayretsiz...

Sonra boş bekler kucağın.

Salıncakda sırtın elsiz,

yelkensiz,

rüzgarsız...

Kentlerde bıkkınlaşır

Caddelerde sıkışırsın...

Hiç bir çiçeğin kokusu cezbetmez seni,

hiç bir umut kıyına düşmez.

Cenazene maskeli yüzler

hayali dualarla bekler...

O eski sandıkda unutulmuş bir yükse cesaret

sonra inanç

küflü bir ekmek gibi çöpe atılmışsa

kesin ki

yitiren

hep

sen olursun.Ve gemiler gider,sana aldırmadan.

Şükür ki o gemiler halatını aşka bağlar...

Bana,bin şarkı bilsen birini söyle,

armağan olsun.

Diyarbakır dan olsun Mardin den göçsün

sonra ülkenin orta yerine bağdaş kurup

yeniçağın rüyasını yatalım.

Sen sessiz ol,ihtilali ben anlatırım.

Kesintisiz bir devrim gibi

Seni sevmek

Aşkın,Devrim...

Ağzında ki alevi boynuma bırak

müebbete değen,idamı düşündüren ağzında ki...

Sonra göç bana.

Her gece göç.

Duvarlara umudu bezeyen

ve ölümü kınından çekili taşıyan çocuklara

imrendiğim gibi göç.

Adını bu yüzden kirpiklerime işledim

işlediğim suçlara göç.

Garlarda firar türküsünü gizliden dillendiren

askerlere hüzünlediğim gibi göç...

Bana bir şarkı söyle; sazsız,öylece yüzümü yıkasın.

Yüzümün aynası dağlarda yankılansın...

Orda buluşacağız,

güneşin kenarında ikindi vakti.

Ateş izlerini Deniz üstünden sektireceğiz

çoğrafyası sınırından taşmış

Ateş İzlerini Deniz Üstünde...

                                              

                                                  (Radikal bir aşkın izdüşümünde

                                                               yol zamanı

                                                        od giden bir otobüsün 34 numaralı

                                                         koltuğuna bıraktım aşkı...

                                                        Bir sana bir bana gidip geliyor...)', 'Hayatı az göremediğin halde üç adımda sokuldun düşülkelerime akşama çok vardı kalabalık bir sabahtı avcuma terini akıtıp yüreğimin paslı dam...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":142,"source_url":"https://www.antoloji.com/deniz-ustunde-ates-izleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yildizlarda kayar', 'yildizlarda-kayar-i-brahim-atilmis-or6ky', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cancagizim; 

oturmus yildizlari seyretmektesin,

dayamissin sirtini beton duvara

kayan mazlum yildizlara üzülmektesin.

hayat bu cigerim! 

yildizlarda tipki insanlar gibi

biri kaymaliki,

saglam kalabilsin oteki', 'Cancagizim;  oturmus yildizlari seyretmektesin, dayamissin sirtini beton duvara kayan mazlum yildizlara üzülmektesin. hayat bu cigerim!  yil...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yildizlarda-kayar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S li siir', 's-li-siir-i-brahim-atilmis-lirod', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sev!    (beni) 

sevgi.

sevgili,

sevgilim

sevgilim; 

sevgili,

sevgi.

sev!    (beni) 

''sevgi adinda hic sevgilim olmadi..''', 'Sev!    (beni)  sevgi. sevgili, sevgilim sevgilim;  sevgili, sevgi. sev!    (beni)  ''sevgi adinda hic sevgilim olmadi..''...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/s-li-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeşiz Biz', 'kardesiz-biz-husamettin-gunacti-4cxm8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'herkes herkesin kardeşi

alevisi,sünnisi

kucaklaşmalılar sevgi ile

anadolusu ve egelisi

lâzı çerkezi kürdü

geçmişte dünya gördü

söyleyin kin ve nefret ile 

bizi böyle kim böldü

doğu batı farketmez

kötü kaderi haketmez

emin olun ezanı ile

albayrağı terketmez...', 'herkes herkesin kardeşi alevisi,sünnisi kucaklaşmalılar sevgi ile anadolusu ve egelisi lâzı çerkezi kürdü geçmişte dünya gördü söyleyin kin ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kardesiz-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Leylî Sevdiğim', 'leyl-sevdigim-metin-eser-pnhdp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyku mahmurluğudur gündüz,

Güneş dünyanı karartır oysa,

Gecelerin fatihi, sessizliğin hakimi,

Yıldızların tüm şahidisin sen.

Bir yıldız binler umman sana,

Dolunay, mehtabın tarifsiz tadı,

''Sema'' sırlar ülkesi, uçsuz bucaksız,

Özlem geceyedir sende,

Hasret geceye.

Buram buram tütersin,

Gözlerini açarsın,

Herkes sokulurken gecenin koynuna.

Sevgin çağlar,

Yüreğin tarifsizce ağlar gecede.

Sen, geceyi seversin, gece de seversin,

Bilmezler seni, uyku aşıkları,

Anlamazlar, o has dünyanın tatlarını,

Göremezler karanlıktaki aydınlığı,

O nasıl bir ummandır,

O ne tarifsiz andır, ne geniş zamandır.

Ben seni bilirim de,

Ya Sen bilir misin beni,

Leyl var Leylî var özlemimde,

Geceye aşığım, sana aşığım... 

Leylî sevdiğim,

Seni düşünmek gecede,

Kimsesiz sahillerde denize girmek gibi…

Bak güneş kayboluyor ufukta,

Uzun bir Leyl, bizi bekliyor,

Şuracıkta…

14.06.04 / Frankfurt', 'Uyku mahmurluğudur gündüz, Güneş dünyanı karartır oysa, Gecelerin fatihi, sessizliğin hakimi, Yıldızların tüm şahidisin sen. Bir yıldız binl...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/leyli-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtuluş', 'kurtulus-husamettin-gunacti-ligfo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'biraz tiner,biraz bally,

yok mu bu çocuğun sahibi.

gündüzleri dilenir,

köprü altında demlenir.

her sabah uyandığında

yeni umutlara gebedir.

her çamura battığında 

kurtulmak için debelenir.

gece uzun,soğuk,tehlikeli.

gözlerini kapattığında

umursamaz hiçbir şeyi.

ne üvey ana dayağı,

ne de babanın devirdiği üç-beş şişeyi.

gece sırdaşı,yıldızlar can yoldaşı olur.

soğuktan donan ellerini ovarken

bir nefes daha çeker bally''den.

bir nefes,bir daha derken,

yığılıverir ana diye sarıldığı geceye.

can yoldaşı yıldızlardan başka

üzülen olmaz bu haline.

çığlık çığlığa martılar seherde,

çöplükten kurtulan çocuğu

uğurlarlar gideceği yere...', 'biraz tiner,biraz bally, yok mu bu çocuğun sahibi. gündüzleri dilenir, köprü altında demlenir. her sabah uyandığında yeni umutlara gebedir. ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kurtulus-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm İstanbul Kıskandı.', 'tum-i-stanbul-kiskandi-meral-balci-tanis-r1dge', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün gece,

Dudaklarıma uzanan kirpiklerini,

Üzüm karası gözlerin kıskandı bence.

Oysa kirpiklerinle konuştuğumuz:

Gözlerinde yaşamanın nasıl bir

mutluluk olduğu üzerineydi sadece.

O gecenin kıskananlar listesinin en popüleri

ellerindi kanımca.

Kimselerle paylaşmadığın, dokunmaya kıyamadığın

Her tesadüfi temasında özür dilediğin

Anlayacağın,

Aylardır benden tunnuk tunnuk sakladığın ellerin.

Sonra, nasıl olduysa (bende anlamadım.) 

Tenime dokunuverdi avuçların.

Avuçların o kadar arzuluydu ki; 

Omuz başlarım da kaldı parmakların.

Gözlerini bilmem ama kıskaçlık yapmakta

haklıydı ellerin.

Sonra saçların vardı birde, 

Siyahıyla geceyi vuran, 

Parlaklığıyla Yıldızları kıskandıran saçların, 

Yalnızlığın kıskanmasın diye dokunmadığım

Lüle, lüle perçemlerinse gecenin asıydı

laf aramızda kalsın.

Velhasıl kelam,

Anı olarak geçmişe teslim ettiğimiz dünü,

Yüzünü çok yakışan küçücük burnunu,

İnce dudaklarında yarım kalan sıfatlı ismimi,

Hasretime dokunan koca yüreğini,

Şaraptan kızaran yanaklarıma 

inatla kondurmadığın öpücüğü,

Seni, beni ve

bir türlü biz olmayı beceremeyen ikimizi,

Kısacası; 

Bizden daha mutlusunun olmadığı dün geceyi

Nedense tüm İstanbul kıskandı.', 'Dün gece, Dudaklarıma uzanan kirpiklerini, Üzüm karası gözlerin kıskandı bence. Oysa kirpiklerinle konuştuğumuz: Gözlerinde yaşamanın nasıl ...', ARRAY['Türk Edebiyatı','Şiir','Meral Balcı Tanış']::text[], 8.5, '{"poet":"Meral Balcı Tanış","poet_slug":"meral-balci-tanis","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/tum-istanbul-kiskandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimdesin', 'yuregimdesin-cahit-ozcan-rew93', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'her yerde sen; 

her nefesimde sen olsan. 

her ana seni görsem, 

her an seni koklasam,

sanma ki bıkarım 

dahada özlerim...

dahada severim seni...tam aksine', 'her yerde sen;  her nefesimde sen olsan.  her ana seni görsem,  her an seni koklasam, sanma ki bıkarım  dahada özlerim... dahada severim sen...', ARRAY['Türk Edebiyatı','Şiir','Cahit Özcan']::text[], 8.5, '{"poet":"Cahit Özcan","poet_slug":"cahit-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yuregimdesin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahmet Efendi', 'ahmet-efendi-husamettin-gunacti-j9t0v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kimi gün kumar oynar kahvede,

kimi gün sızar kalır meyhanede.

herkesin sabrı tükendi,

çizmeyi aştın Ahmet Efendi.

arkadaşların da senden beter,

eve toplarsın üçer beşer.

sanki karın hizmetçindi,

çok ayıp ettin Ahmet Efendi.

evde karın,üç çocuk,bir de dede,

para getireceksin diye beklemede.

sen at yarışındasındır garanti,

hayalleri yıktın Ahmet Efendi.

karın on yıldır çile çeker,

yeni almaz yamar,diker.

konu komşu hep söylendi,

hiç umursamadın Ahmet Efendi.

kitap okumadan tek bir hece,

aylak gezersin gündüz gece.

alacaklılar kapıya yüklendi,

artık çok oldun Ahmet Efendi...', 'kimi gün kumar oynar kahvede, kimi gün sızar kalır meyhanede. herkesin sabrı tükendi, çizmeyi aştın Ahmet Efendi. arkadaşların da senden bet...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ahmet-efendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değiştir', 'degistir-husamettin-gunacti-crky7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'takma kafanı,

boşa üzme kendini,

değiştiremezsin nasılsa

dünyanın düzenini.

kaçaklar saklanır,

alçaklar aklanır,

değiştiremezsin nasılsa

deliler akıllanır.

fakirler ezilir,

zenginler serpilir,

değiştiremezsin nasılsa

elinden ne gelir.

hayali satışlar,

bire on katışlar,

değiştiremezsin nasılsa

herkes onları alkışlar...', 'takma kafanı, boşa üzme kendini, değiştiremezsin nasılsa dünyanın düzenini. kaçaklar saklanır, alçaklar aklanır, değiştiremezsin nasılsa del...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/degistir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim bilir', 'kim-bilir-husamettin-gunacti-mwjor', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'insanlar neden

kendilerine fısıldamaktan

korktukları şeyleri

dünyaya haykırmak isterler...', 'insanlar neden kendilerine fısıldamaktan korktukları şeyleri dünyaya haykırmak isterler......', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kim-bilir-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '5. Şubat', '5-subat-aytekin-arik-q7k09', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sal gitsin dertlerin yakasını

kaldıkca sende arsızca ürer

çekinme makasla makasını

kesip atarsın yapmadığımı

günler aylar yıllar geçer gider

tatlı tadını tadmadığımı

yıllarım beklenmiş sarap içer

kaburgalarını kırdığımda

kapardın gözünü kedi gibi

sönmüş ışıldardın ışığımda

5', 'sal gitsin dertlerin yakasını kaldıkca sende arsızca ürer çekinme makasla makasını kesip atarsın yapmadığımı günler aylar yıllar geçer gider...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/5-subat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '6. Şubat', '6-subat-aytekin-arik-y2rbr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nedense kolay olur kurutmak

her türlü yeşilim yaprakları

en önemlisi kuru yeşertmek

sevdiğimin gözü mavi deniz

balıklarına sahip cık bari

sen eger kalabilirsen semiz

barındır icinde öteberi

kabarsın göğsün şu ürünününle

üstünde olsun mutlu bulutlar

martıların övünsün dününle

6', 'nedense kolay olur kurutmak her türlü yeşilim yaprakları en önemlisi kuru yeşertmek sevdiğimin gözü mavi deniz balıklarına sahip cık bari se...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/6-subat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '13. Şubat', '13-subat-aytekin-arik-qdr7h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'koyu karlı dağın havasına 

benzerse kızınca güzellıği

yat kalk dua et kız anasına

eşsiz yüzü gün aydınlığından

karalama hakkı kime düser

yorgun dustü batgınlığından

ay güneşe gün buluta küser

zorlama kesebildiğini kes

iki yüzlü olsa bile bıçak

çalar çalmaz tüketmez nefes

13', 'koyu karlı dağın havasına  benzerse kızınca güzellıği yat kalk dua et kız anasına eşsiz yüzü gün aydınlığından karalama hakkı kime düser yor...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/13-subat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Xxx Sitem', 'xxx-sitem-zeki-ergin-yf2ix', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'vurgun yemiş gibiyim

onlarca metre derinlerde

ya da sudan çıkmış balık 

ey dostlar

ya da dost bildiklerim

nerelerdeydiniz

günlerden 12 haziran 2004

30 yıllık beklentim 

emeğim 40 yıllık

yalnızlığımla başbaşaydım yine 

gözlerim yollarda sizi aradı

direndi yüreğim 

direndim ama

derinden bir sızı

akşam üstü dağladı her yanımı

_kadıköy 14haziran2004', 'vurgun yemiş gibiyim onlarca metre derinlerde ya da sudan çıkmış balık  ey dostlar ya da dost bildiklerim nerelerdeydiniz günlerden 12 hazir...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sitem-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baktığın Yüz', 'baktigin-yuz-suskun-resital-87abb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşamak seninle! ..

Hiç kimsenin bilmediği,

Issız,saklı bir koyda buluşmak...

Hayatın bütün mutluluklarını süzüp

Gül yüzünde,kalıcı bir  tebessüm olmak.

Usulca gülümseyip gökkuşağına,

O eşsiz,renk cümbüşü altında,

Kadife kanatlı kelebekler gibi,

Bir öyküyü paylaşmak.

Aşk gibi,sevda gibi,

Masal gibi güzel olurdu! 

Resmine bakılan yüzde olmasaydı! ...

Bir başkasını ummak! ....', 'Yaşamak seninle! .. Hiç kimsenin bilmediği, Issız,saklı bir koyda buluşmak... Hayatın bütün mutluluklarını süzüp Gül yüzünde,kalıcı bir  teb...', ARRAY['Türk Edebiyatı','Şiir','Suskun Resital']::text[], 8.5, '{"poet":"Suskun Resital","poet_slug":"suskun-resital","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/baktigin-yuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorumculuk Oyunu', 'seviyorumculuk-oyunu-hurrem-yalcin-ddope', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum

Biliyor musun? 

Ama ben çok iyi biliyorum...

Seviyorumculuk oyununu...

En iyi sen oynuyorsun! ...

12 Haziran 2004', 'Bilmiyorum Biliyor musun?  Ama ben çok iyi biliyorum... Seviyorumculuk oyununu... En iyi sen oynuyorsun! ... 12 Haziran 2004...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seviyorumculuk-oyunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönülden Bakıyorum', 'gonulden-bakiyorum-sadik-softa-rlldh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaynağı gürül gürül durmak,dinlemek bilmez,

Gönül zenginliğinden hep sana akıyorum.

Susturmak mümkün değil, çelik gibi eğilmez,

Ne kale dinler ne set, hep sana akıyorum.

Aklı kenarda tuttum, gönülden bakıyorum.

Bir sır oldu uzandı, gönülde saplı ucu,

Kalesi fethedildi, düştü kalan son burcu,

Düşünmekle olmuyor,merak etme sonucu,

Düşünsem de düşlerde hep sana akıyorum.

Gönülden yürüyorum, gönülden bakıyorum.

Gönlümdeki ışığı, gözlerinden almışım,

Sütun sütun eylemiş,yüreğime salmışım,

Alev alev yanarım,  alevinde kalmışım,

Fırtınayla  borayla, hep  sana  akıyorum.

Depreştikçe yüreğim, gönülden bakıyorum.

Sevdan içime doğar ve büyür, benlik erir,

Rahmet gibi yağarsın, duygularım yeşerir,

Bereketlenir sevda sanki bire kırk verir,

Altın başakta duygu, hep sana akıyorum.

Gözlerim üzerinde, gönülden bakıyorum.

Bahar yeli nefesin, bu bağrıma sarmışım,

İçten içe yandıkça,  kül olup kararmışım,

Galü beladan beri,   ben seni ararmışım,

Yollarım sana çıkar, hep sana akıyorum.

Umut meşalem oldu, gönülden bakıyorum. 

Çankırı-14.06.2004', 'Kaynağı gürül gürül durmak,dinlemek bilmez, Gönül zenginliğinden hep sana akıyorum. Susturmak mümkün değil, çelik gibi eğilmez, Ne kale dinl...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gonulden-bakiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manası Adının', 'manasi-adinin-erol-dal-tsv8w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sakladığın rüzgarlarında 

Ilık esen dağların eteğinden akan 

Köpüklerinde bulurum hüznümü

Manastır kapılarında gezen fırtınanın sesi 

Yılgın ağaçların çığlığı da kulaklarımda.

Bir tutam toprak kokar; 

Teninden dem der çekerim. 

Bulutlarında ararım, 

Yalnızlığımın ürkekliğini; 

Saklarım yüreğimde, manasını adının; 

Gizlice ağlarım. 

ed/04', 'Sakladığın rüzgarlarında  Ilık esen dağların eteğinden akan  Köpüklerinde bulurum hüznümü Manastır kapılarında gezen fırtınanın sesi  Yılgın...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/manasi-adinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm var aklımda', 'olum-var-aklimda-gencay-coskun-ackcv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölüm var aklımda 

Belli belirsiz 

Yakın yada uzak ufuklar değildi 

Karlı bir yolda 

Her adımda sana gelmek için

Düştüm yürek acıtan yollara 

Nereye gitsem seni 

Nereye gitsem beni

Bulmak imkansız gibiydi

Göz gözü 

Kalp kalbi görmüyor

Bazı iklimsel tabiatlarda

Beklemek yada beklememek 

İşte bütün mesele bu değildi 

Zamanından önce de öldürüyor insanı

Gömülmen gerekmiyordu 

Bu ölümlerden sonra

Yalnızca bir kerede ölmüyordun aslında 

Ne zaman sana uzansam 

Uzakların korkusu var aklımda 

Sarıyor sarmalıyor bedenimi

Kendi kendime 

Duygusal kızamıklar çıkarıp 

Kıp Kırmızı Kızıyordum 

Ateşten korkan kim ki

Yokluktu aslı 

Beni hunharca öldüren 

Birde oldu bitti bir zamandı 

Sığınacağım tek liman ki

Yüzme asla bilmezken 

Tehlikeliydi deniz yolculuğu

Senin rüzgarlarında 

Vurulduğum limandı 

Henüz daha adı da yoktu 

Ölüm var aklımda 

Nefes almak 

Boşuna mıydı aslında

Çarçur etmeden hayatı 

İade etmek lazımdı bedeni 

Ne yazık ki kullanma tarihi dolmadan 

İşe yaramayan bedenleri 

Cezasız iade alınmazdı 

İşin garibi 

Son kullanma tarihi 

Hiçbir bedende yazılmazdı 

Ölüm vardı aklımda

İzinden bir dünyayı 

İzlemeye bile değerdi 

Yalnızlık oldu belki sonunda

Yaklaşımlar 

Bana hiç yaklaşmadı

Yaklaşanlar ancak aldandı

Ölene kadar söz verilmezdi

Bana yakışan 

Sonsuza kadar verilen sözdü 

Benimse 

Başımda ve sonumda 

Sadece 

Sen vardın aklımda', 'Ölüm var aklımda  Belli belirsiz  Yakın yada uzak ufuklar değildi  Karlı bir yolda  Her adımda sana gelmek için Düştüm yürek acıtan yollara ...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/olum-var-aklimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim Ütopya', 'zalim-utopya-nurhan-ulku-407ti', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neden kızılca kıyamet kopuyor,bugün bakışlarında? 

Neden siyah perdelerini çektin gözlerine? 

Islak kirpiklerini kurutmak için,sererek

gecenin karanlığına..

Neden en hain tebessümleri sakladın gamzelerine? ? 

Dikenler serptin sana ulaşmaya çabalarken, yollarıma

Oysa sevda sokağının yoksul dilencisiydim

Meczup nehirler gibi başı boş akan

Yalancı şafaklardan usanıp umutsuzluğa bakan

Yarı aralıktı gözlerim, acımadın...bir de sen vurdun

Mahzeninde tutsağım tuzlu kirpiklerinin

salıver gitsin

Hasretin biriktiği hüzün kanyonlarına

Zalim bir ütopya değil mi nasılsa senden kalan geriye? 

Yasını tutarım halâ çaresiz, karartma gecelerde.

Bir bir söküp güllerimi,

Zakkumlar dikmedin mi yerlerine? 

Kahır paletleriyle ezerken sevda bahçelerimi...

Ya git benim ülkemden

Ya da kapat gidiş yollarını,sonu hasrete varan..

Adı ceninken konulan bir çocuk,

Usumun rahminden doğarken çığlık çığlık

Pervasız gidişlere sürgün ettin beni

Yetim bir sevdaya bağladığın yüreğimle

Mutsuzluğu alnıma yazdın.

Ağlayarak ayak bastığım dünyada ağlamak kaderim oldu.

Gûlyabaniler gülleri koklarken,

Bana da yaralayan dikenleri düştü', 'Neden kızılca kıyamet kopuyor,bugün bakışlarında?  Neden siyah perdelerini çektin gözlerine?  Islak kirpiklerini kurutmak için,sererek gecen...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Ülkü']::text[], 8.5, '{"poet":"Nurhan Ülkü","poet_slug":"nurhan-ulku","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/zalim-utopya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Aşk''ım', 'ben-ask-im-i-hsan-dinibutun-uor45', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben su''yum

İçmek istersen eğer

Çöl ortasında bir vahadayım

Ben su''yum

İç beni

İçebildiğin kadar

Ben su''yum

Ben ateş''im

Yanmak istersen eğer

Kalbindeyim

Ben ateş''im

Yak kendini

Yakabildiğin kadar

Ben ateş''im

Ben rüzgar''ım

Savrulmak istersen eğer

Yüreğindeyim

Ben rüzgar''ım

Bırak kendini

Bırakabildiğin kadar

Ben rüzgar''ım

Ben aşk''ım

Yaşamak istersen eğer

İçindeyim

Ben aşk''ım

Yaşa beni 

Yaşayabildiğin kadar

Ben aşk''ım', 'Ben su''yum İçmek istersen eğer Çöl ortasında bir vahadayım Ben su''yum İç beni İçebildiğin kadar Ben su''yum Ben ateş''im Yanmak istersen eğer ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-ask-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zemheri', 'zemheri-ozgen-turan-9j5c3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bırakmadı yakamı zemheri

Düşmedi cemre; gelmedi newroz

Duldasında direnmeler vardı

Ala  çiçek dağlarımın

Engel oldu güz...

Şimdi dört yanımı saran

Buzul dağları/köpüren

Zemheri ve ayaz

Ama bilirsiniz

Boyun eğmez

Bozguna, ihanete

kararlıysa sevdalar

Bilirim can, bilirim göz

Öfkemin memesinden emzirip

Düşümün kundağında büyüttüğüm köz

Ergeç baskın gelir zemheriye', 'Bırakmadı yakamı zemheri Düşmedi cemre; gelmedi newroz Duldasında direnmeler vardı Ala  çiçek dağlarımın Engel oldu güz... Şimdi dört yanımı...', ARRAY['Türk Edebiyatı','Şiir','Özgen Turan']::text[], 8.5, '{"poet":"Özgen Turan","poet_slug":"ozgen-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zemheri-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamlara Kızamam', 'aksamlara-kizamam-emin-baydil-ry9uk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu akşam yine gönlüm, sanki mahkûm, müebbed

Bu akşam yine gönlüm, sızlıyor növbet növbet.

Çekiyor, ümitsizce. Bir hayatın yasını

Gün doğarken tutuyor, maziye aynasını.

Bir sonbahar yağmuru yağarken ince ince

Birer birer kırmıştı dallarını eğince.

İnanınız a dostlar! İşte o günden beri, 

Gönlüm karanlıklara, sessiz girmiş içeri.

Sığmıyorum bu yüzden, inan sığamıyorum

Bunalmışım kendimden, artık yağamıyorum.

Ah gönlüm! Gönlüm benim! 

Yetmez mi, küstüğün bunca zaman? 

Çünkü sensiz olmuyor, geçmiyor sensiz zaman.

Diyorum ki: Yalnızım, bu boşluk neden dolmaz? 

Diyorum ki: İmkânsız, bir taşla duvar olmaz...

Bu akşam gönlüm benim, aklım gibi galiba

Çıkıp yuvalarından, girmişler bir kalıba.

Belki zaman vuruyor, ellerime kelepçe,

Bu akşam da dolandım, dünya kazan ben kepçe...

.................................,

Mazide; Yemen''de mi, Kafkasya''da mı, nerde? 

Kapanan yavaş yavaş gördüğüm en son perde.

Bir ara Sakarya''da, Dumlupınar''daydı O

İlk hedefti duyduğum, gerilmiş bir yaydı O! ..

Hatırlarım her akşam, rüzgâr gibi kanatlı,

Geçen alp-erenleri, hepsi de beyaz atlı...

Dur durak, hiç olmadı, ezelden ebede dek

Olmadı, olmayacak! Çünkü, düşman uyumaz.

Yine sath-ı müdafaa, şimdi de hemen gerek 

Bir baksana koynumda, beslediğim engerek...

Ahhh! Ah! ! ! ...

Anlamak mümkün değil! Bir muamma, bir esrar

Yaptığı şu gönlümün, aynı makamda ısrar...

İçiyor, tam aksine, çekiyor derinine

Bir gurbet cellâdının önünde başım yine:

Vur, haydi şu palayı! .. Bu baş, artık fazladır,

Şimdi zaman değişti, gönüller ayazdadır...

Akşamlar girdabımdır, düştüğüm zaman zaman,

Akşamlar kaderimdir, akşamlara kızamam...', 'Bu akşam yine gönlüm, sanki mahkûm, müebbed Bu akşam yine gönlüm, sızlıyor növbet növbet. Çekiyor, ümitsizce. Bir hayatın yasını Gün doğarke...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/aksamlara-kizamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Şişelere sığmayan sevgi...', 'siselere-sigmayan-sevgi-erdal-asik-4toe7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yine kederliyim elimde şişeler 

sahile vurdu gönlüm 

yolumu şaşırmış değilim; 

içten ve samimi 

özlemle arzuladım geçmişimi

kadehlerde değil 

şişelerde bu kez aradım seni

belki bir yerlerde 

duymasanda sesimi

şişelere doldurdum sevgimi

içtikçe sende anla, 

herkes gibi

seni ne çok sevdiğimi! ..', 'yine kederliyim elimde şişeler  sahile vurdu gönlüm  yolumu şaşırmış değilim;  içten ve samimi  özlemle arzuladım geçmişimi kadehlerde değil...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siselere-sigmayan-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkyaz', 'i-lkyaz-ozgen-turan-qck57', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bulvarlardaki ulu çınarlar

Hüzünlü ve sırıl-sıklam

Sevda dolu günlerimin dostudur

Nereden bileceksiniz

Bazen ağlamanın da az olduğunu

En haklı olduğum zamanlar bile

Yenik düşmenin bilenmişliğini

Elde mi anlatmak

Verirse şu dökülen yapraklar 

Haber verir

Gelenin güz olduğunu

Kupkuru kaldı diye dalar

Bir ölüm mü aklınıza gelen

Muştularsa şu gördüğünüz 

Çırıl-çıplak ağaçlar muştular

Gelecek olanınn ilkyaz olduğunu...', 'Bulvarlardaki ulu çınarlar Hüzünlü ve sırıl-sıklam Sevda dolu günlerimin dostudur Nereden bileceksiniz Bazen ağlamanın da az olduğunu En hak...', ARRAY['Türk Edebiyatı','Şiir','Özgen Turan']::text[], 8.5, '{"poet":"Özgen Turan","poet_slug":"ozgen-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ilkyaz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyunlar', 'oyunlar-zafer-zengin-etnika-s1li1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah 

şu

oyunlar

Hep 

çocuklara

yakışıyorlar

Büyükler

Savaşıyorlar

14 Haziran '' Ellerin renksiz ''', 'Ah  şu oyunlar Hep  çocuklara yakışıyorlar Büyükler Savaşıyorlar 14 Haziran '' Ellerin renksiz ''...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/oyunlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem', 'i-stemem-ferit-teksoy-45sb8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben kendimi çok şey bilir sanırdım

Herşeyi bilmekle gururlanırdım

Ne acı ki,her konuda yanıldım

Böyle bir talihi asla istemem.

Kaleleri hep dalgaya kurmuşum

Saadeti hayallerde bulmuşum

Olmayan sevgiyle mutlu olmuşum

Böyle bir talihi asla istemem.

Hep sevgiye açık yaşadı gönlüm

Tokat yedim yine en başa döndüm

Daha kısasına razıydım ömrün

Böyle bir talihi asla istemem.

Her uzandığım dal elimde kalmış

Her diktiğim çiçek açmadan solmuş

Kime canım desem arkamdan gülmüş

Böyle bir talihi asla istemem.

Çok yanlış şeylere kanmışım meğer

Boşa ağlamışım,yanmışım meğer

Yeniden dünyaya gelseydim eğer

Böyle bir talihi asla istemem.

Çilelere bu yaşımda doymuşum

Yaptığım yıkılmış yine koymuşum

Ya bu dünya boş,ya ben boşmuşum

Böyle bir talihi asla istemem.', 'Ben kendimi çok şey bilir sanırdım Herşeyi bilmekle gururlanırdım Ne acı ki,her konuda yanıldım Böyle bir talihi asla istemem. Kaleleri hep ...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/istemem-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma...', 'unutma-umut-gul-d2rr8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün olur da ayrılık gelirse başa

Üzülüp kendini verme telaşa

Ne olursa olsun vedasız gitme

Gidip de dönmemek var sakın unutma

İhtiyacın olduğunda bir dost eline

Usulca dokunurum omuzlarına

Ne olursa olsun dostunu kırma

Gelip de bulmamak var sakın unutma

Simsiyah saçlarına düşünce aklar

Gözünde canlanır eski hatıralar

Süzülür yanağından  sıcacık yaşlar

Bulup da görmemek  var sakın unutma

''Dostluğu, sevgiyi ve dostça paylaşmayı bilen tüm güzel yürekli insanlara...''', 'Gün olur da ayrılık gelirse başa Üzülüp kendini verme telaşa Ne olursa olsun vedasız gitme Gidip de dönmemek var sakın unutma İhtiyacın oldu...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutma-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Gezmiş''e', 'deniz-gezmis-e-mehmet-sari-9di4x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşmeden rahimde can pazarına 

Doğduğun şehirde dağlar olsun mu

Yusuf’suz, Sinan’sız, Hüseyin’siz

Çocuk senin adın Deniz olsun mu.

Nehirlerin coşmuş, denizler için

Bulutların gezmiş yağmurlar için

Bu gün değil amma yarınlar için

Çocuk senin adın Deniz olsun mu.', 'Düşmeden rahimde can pazarına  Doğduğun şehirde dağlar olsun mu Yusuf’suz, Sinan’sız, Hüseyin’siz Çocuk senin adın Deniz olsun mu. Nehirleri...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sarı']::text[], 8.5, '{"poet":"Mehmet Sarı","poet_slug":"mehmet-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/deniz-gezmis-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur...', 'yagmur-zubeyde-yilmaz-dj5ns', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece yağmur yağıyor

Antalya''da...

Caddeler ıslak,

Caddeler kaygan...

Arabalar geçiyor peşisıra

Ardından bir ambulans

Hangi canı kurtarmak adına....

Bu gece yağmur yağıyor

Antalya''da...

Yüreğim ıslak,

Yüreğim sevdalı.

Sana koşmak,sana sarılmak

Seni doyasıya sarmak amacı...

Bu gece yağmur yağıyor

Antalya''da...

Senden ayrı

Senden uzak

Ama sağnak yağmura inat

Uzayan acımasız yollara inat

Sen hep ruhumda,

Sen hep yanıbaşımda

Nasıl olsa yaşadığımız aynı dünya......

                        

                                  14/06/2004', 'Bu gece yağmur yağıyor Antalya''da... Caddeler ıslak, Caddeler kaygan... Arabalar geçiyor peşisıra Ardından bir ambulans Hangi canı kurtarmak...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yagmur-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylemek Yerine', 'soylemek-yerine-mehmet-sari-0t2ob', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne de çabuk geldi güz

Ne de karanlık oldu gecelerim benim

Değil yıllar önce; 

		daha dün

Bir kırmızı gül kopardım senin için

Tüm acemi yürek atışları adına

Ve söylenemeyen her cümle için

Tutuşturdum avuçlarına.

Bilmezsin sen

Ben bütün şarkıları sana dinlerim

Bütün dökülmüş yaprakları toplarım

				görme diye

Ve! ..

Hiçbir ağacı yaralamadım adının baş harfiyle

Ve kaçırmadım ayaklarımı,

		gülüşünün orta yerinde

Çünkü deniz gibi gülersin sen dalga dalga,

Cadde gibi gülersin, aydınlık, ışıl ışıl

(yarim)

Söyle şu gözlerine

Alsın dilsizliğimi benden.

Kalmadı tadım tuzum

Onca şey varken söylenecek

Oturup sana şiir yazdım.', 'Ne de çabuk geldi güz Ne de karanlık oldu gecelerim benim Değil yıllar önce;  		daha dün Bir kırmızı gül kopardım senin için Tüm acemi yürek...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sarı']::text[], 8.5, '{"poet":"Mehmet Sarı","poet_slug":"mehmet-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/soylemek-yerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan', 'uyan-fatih-mehmet-karaca-chq1t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyan ey ecdadı şanlı torun! 

Deden, Atan neydi sen ne oldun! 

Böyle durmak yakışır mı? 

Hiç Atandan utanmaz mısın? 

	

Sabah horoz öter sen uyursun

	Öğleye doğru uyanırsın

	Öğle yemeği kahvaltı yaparsın

	Akşam olur tekrar uyursun,

Sabah olur horoz öter 

Böyle nereye kadar gider

Zamanın uykuda biter

Zihninde uyumaya geçer

	

Su uyur düşman uyumaz

	Sen uyursun düşman durmaz

	Bu kervan böyle yürümez

	Uyan kardeşim uyan

Fatih, derki Allah’tan ümit kesilmez

Allah, inanan kulunu darda komaz

Sanma dualar kabul olunmaz,

Allah yardımcımızdır yardımcımız', 'Uyan ey ecdadı şanlı torun!  Deden, Atan neydi sen ne oldun!  Böyle durmak yakışır mı?  Hiç Atandan utanmaz mısın?  	 Sabah horoz öter sen u...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uyan-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm acıdır', 'olum-acidir-ayten-ozlem-yesilcali-a0acn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi gittin sanal dost gidiş haberini de; 

Yine bir sanal dosttan aldım.

Hançer gibi saplandı yüreğime senin ebedi gidişin.

İnanamadım inanmak mümkün de degildi zaten.

Sen sanalda tanıdığım mert dürüst dostum.

Yaşça daha çok gençtin neden felek seni seçti.

Neden trafik canavarına yenildin,30 yaşın baharındaydın.

Bu gün 14.Haziran senin ölüm günün degil; 

Benim için doğum günündür.

Ne vardı be dost gidecek tavlada bizi yetim koyacak.

İnat etin dimi gitmek için çokmu ugraştın.

Daha  kaç saat önce  seninle selamlaştık kızdık güldük ağladık.

Yani daha senin o asaletli nickin olmayacakmı.

SEFA 78 sanalda herkesi kardeş bacı abla gören.

İnsanlara insan olduğu için değer veren saygılı dostum

Sanalda bile gerçek hayat dostu oldun her zaman.

Ne çok sevenin varmış be dost.

Yalan hayattan gerçek hayata hoş geldin sefalar getirdin.

Bu dünya yalancı gerçek dünyada yerini buldun.

Ordada bizleri unutma dost.

Mekanın cennet ola biz seni unutmayacagız.', 'Şimdi gittin sanal dost gidiş haberini de;  Yine bir sanal dosttan aldım. Hançer gibi saplandı yüreğime senin ebedi gidişin. İnanamadım inan...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olum-acidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Malı', 'dunya-mali-fatih-mehmet-karaca-bsw5j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Allah, akıl vermiş, fikir vermiş 

Can vermiş, duygu, düşünce vermiş

Bu nimetleri doğru dürüst kullan demiş,

Allah’a kul ol yaşa demiş.

	

Sen, biraz daha kazanayım diye 

	Biraz daha büyük olayım diye

	Sağı çarptın, solu çarptın! 

	Can yaktın, ocak yıktın, kalp kırdın! 

Bu dünyada böyle bittin

Vay haline, tüh haline 

Şimdimi aklın geldi başına! 

Dua et seni yaradana 

	

Zararın neresinden dönersen

	Yinede kardır bilesin

	Pişman olup doğruyu bulasın

      Bundan sonra geri dönmeyesin

Fatih, derki ben nasılım? 

Bilmeyerek düşmüş isem 

Pişman olup düzeyelim

Allah, pişman etmesin,pişman.', 'Allah, akıl vermiş, fikir vermiş  Can vermiş, duygu, düşünce vermiş Bu nimetleri doğru dürüst kullan demiş, Allah’a kul ol yaşa demiş. 	 Sen...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dunya-mali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-mehmet-sari-iyz4f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Amca! ..

	Diyarbakır otobüsü geldi mi

	Babam olacak içinde

	Uzun boylu, elleri nasırlı

	Bakışları sert ama yüzü güleç

Askere diye gitti gelmedi

Bekliyorum,

	          gelecek 

Amca, Diyarbakır otobüsü geldi mi

	Babam olacak içinde

	Nic’olmuş özlemişim kokusunu

Hem, O beni özlememiş midir dersin

Hadi göster şu otobüsü, babam insin

Amca Diyarbakır otobüsü geldi mi

	Babam olacak içinde

Bisiklet demişti giderken

Oyuncak demişti; bir kucak alayım

İstemem artık hiç birisini

		Kucağında ben olayım

Amca! ... amca söyle bana

Bu Diyarbakır 

		kaç can uzakta.', 'Amca! .. 	Diyarbakır otobüsü geldi mi 	Babam olacak içinde 	Uzun boylu, elleri nasırlı 	Bakışları sert ama yüzü güleç Askere diye gitti gelm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sarı']::text[], 8.5, '{"poet":"Mehmet Sarı","poet_slug":"mehmet-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bekleyis-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aciz Kul', 'aciz-kul-fatih-mehmet-karaca-i3c7q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben, aciz kulum

Yaradanım var benim

Kadere iman ederim

Allah’a elimi açarım

	

              

                Yardımsız yaşayamam

	Hareket bile edemem

	Hayırda şerde...

	Allah’a elimi açarım

Gece gündüz anarım

Kuran-ı Kerim okurum

Aklımdan hiç çıkarmam

Allah’a elimi açarım

	

İnsan hiçbir zaman

	Çıkarmamalı aklından

       Daima Allah Allah...

	Allah’a elimi açarım.

Allahü Telaya elini açan 

Kul, darda kalmaz, 

Fatih’te darda kalmaz,

Allah’a elimi açarım.', 'Ben, aciz kulum Yaradanım var benim Kadere iman ederim Allah’a elimi açarım 	                                Yardımsız yaşayamam 	Hareket bi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aciz-kul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benlik', 'benlik-fatih-mehmet-karaca-asjve', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“Geçmişine taş atanın

Geleceğine gülle atarlar”

Çok doğru söylemişler

Benliklerini kaybetmesin demişler

	

Şuursuz yaşayan insan

	Rotasını şaşırmış kaptansız

                Gemidir her an

	Yolunu şaşırmış insan

İnsan ne olduğunu bilmeli

Türk oğlu türküm demeli

Türk-İslamım demeli

Yolun şaşırmamalı

	

Fatih’te benliğini bilmeli 

	Ne olduğunu unutmamalı

	Yolunu şaşırmamalı

	Şuursuz yaşamamalı.', '“Geçmişine taş atanın Geleceğine gülle atarlar” Çok doğru söylemişler Benliklerini kaybetmesin demişler 	 Şuursuz yaşayan insan 	Rotasını şa...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benlik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
