INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Yol Göründü', 'yine-yol-gorundu-baykal-kaanalp-s5rig', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yine yol göründü

aşkımıza

gidecek bir yeri

var mı? bilmem', 'yine yol göründü aşkımıza gidecek bir yeri var mı? bilmem...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yine-yol-gorundu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldürecek Değil ya', 'oldurecek-degil-ya-arif-hikmet-basegmez-6s11s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her dem sevda açacağım solmadan; 

Aşkın beni öldürecek değil ya! 

Bu uğurda dertten nasüb almadan,

HAK yüzümü güldürecek değil ya! 

Aşktır adı,yürek ister,can ister; 

Kerem gibi Aslı''sına yan ister.

Yüreğimde bir ömürlük han ister,

Boş mekanı dolduracak değil ya! 

Gönlüm hasret.sevda teri dökmeye; 

Ben hazırım aşk yükünü çekmeye.

Baştan sona binbir çile var diye,

Felek beni yıldıracak değil ya! 

Sensiz bana ne güneş var ne ışık...

Günüm sana gecem sana dolaşık.

Seviyorsa,gelip sana bu aşık,

Elden haber bildirecek değil ya!', 'Her dem sevda açacağım solmadan;  Aşkın beni öldürecek değil ya!  Bu uğurda dertten nasüb almadan, HAK yüzümü güldürecek değil ya!  Aşktır a...', ARRAY['Türk Edebiyatı','Şiir','Arif Hikmet Başeğmez']::text[], 8.5, '{"poet":"Arif Hikmet Başeğmez","poet_slug":"arif-hikmet-basegmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oldurecek-degil-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceviz', 'ceviz-baykal-kaanalp-1ze7y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ardından  bakakaldım

