INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrostiş', 'akrostis-ahmet-aksoy-tsi7o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şamanım en iyi sen bilirsin

avuçlar geceği ölüler

izler izleğinde sözcükler

Ra o esinler tanrısı', 'şamanım en iyi sen bilirsin avuçlar geceği ölüler izler izleğinde sözcükler Ra o esinler tanrısı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/akrostis-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-reside-sarikavak-2jhe4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'babalar günün kutlu olsun....', 'babalar günün kutlu olsun.......', ARRAY['Türk Edebiyatı','Şiir','Reşide Sarıkavak']::text[], 8.5, '{"poet":"Reşide Sarıkavak","poet_slug":"reside-sarikavak","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/anne-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Babam Ak Gözlü', 'benim-babam-ak-gozlu-celal-sahin-kndc9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bölük pörçük değil asla anıların. 

Şubat on sekiz karlı bir sabahı Uşakın 

Artçısı hiç bitmeyen, Sessiz bir deprem yaşattın

Geciktim, biliyorum bunu hiç sevmezsin 

Cevabı geçmişte bir soru içimi kemiren

Acabalara acabaları çuval eyleyen ….

Ali mektebini okumuştun 

İnançlı,orta yolluydun 

Kapın hiç kapanmadı 

Ramazanda gizlice çok dağıttım; zekatını

Okuttun öğretmen ettin Üç evladını 

Üçü birden zekatın kadar olamadı. 

Susmanın gerektiği zamanı 

Tek başına haykırmayı, karşı çıkmayı 

Hırslı olmamayı, tuttuğunu koparmayı 

Sade, sessiz, ilkeli ve farklı olmayı 

Akıl defteri tutmayı, 

İnsanları sevmeyi, gözlerimi ağartmayı, 

Sözünde durmayı, 

Yerleştirdin benliğime öğüt vermeden. 

Erken kapattın günlüğünü, farkında mısın? 

Sözün senet olduğu deviri de giderken yanında götürdün. 

Davudi sesinden masal dinlemek,

Dizlerinde uyumak nasip olmasa da 

Nasrettin Hoca’yla paylaştığın toprağında 

Hüzün yedi renkli dişini batırdığı gecelerde, 

Nefesini arayıp göz pınarlarımı kuruttuğumu 

Bir sen bir Allah şahit oldu.. 

                                         Bu gün babalar günü  Haziran 2004', 'Bölük pörçük değil asla anıların.  Şubat on sekiz karlı bir sabahı Uşakın  Artçısı hiç bitmeyen, Sessiz bir deprem yaşattın Geciktim, biliyo...', ARRAY['Türk Edebiyatı','Şiir','Celal Şahin']::text[], 8.5, '{"poet":"Celal Şahin","poet_slug":"celal-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/benim-babam-ak-gozlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çayın dumanı serin artık...', 'cayin-dumani-serin-artik-lzcramcil-ceyhun-erdem-hcb3k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle unutp gitmişim ocakta çaydanlığı,

kaynayıp durmuş kanıp ki rahat koymamışım seni gece yarısı.

bardağımda çayın dumanı serin serin tütüvermiş,

taze nane yaprağı atıvermişsin ya içine,

mis gibi, senin gibi kokuvermiş...

Püfür eserken balkon kapısından gecenin esintisi,

gül düşen, gümüş düşen şarkılar unutuluvermiş.

hem sen gecenin bir saati, çakır keyif uyuya kalmaya niyetli,

çayımın dumanı ılıya dursun, gözlerinin parıltısı içime akıvermiş.

Şimdi sen orada, ve ben yazarken niyetlerimi,

iki gözün uykuda olsa, ben seni sevmez miyim?', 'Öyle unutp gitmişim ocakta çaydanlığı, kaynayıp durmuş kanıp ki rahat koymamışım seni gece yarısı. bardağımda çayın dumanı serin serin tütüv...', ARRAY['Türk Edebiyatı','Şiir','Lzcramcil Ceyhun Erdem']::text[], 8.5, '{"poet":"Lzcramcil Ceyhun Erdem","poet_slug":"lzcramcil-ceyhun-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cayin-dumani-serin-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolağzı', 'yolagzi-nilay-aksu-l0i0w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yordum yoruldum sana geldim

ey hayat beni de diğerleri gibi yargıla! 

kumsalda kıvranan bir balık kadar

yanlışım sana! 

yanıldım, yenildim,al beni

sakla koynuna

bu deli sancının tam ortasında

beni öp, beni erit

dök kalıplara

dilinin ucunda bir sövgü gibi

ey hayat beni tükür, savur rüzgara!', 'yordum yoruldum sana geldim ey hayat beni de diğerleri gibi yargıla!  kumsalda kıvranan bir balık kadar yanlışım sana!  yanıldım, yenildim,a...', ARRAY['Türk Edebiyatı','Şiir','Nilay Aksu']::text[], 8.5, '{"poet":"Nilay Aksu","poet_slug":"nilay-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yolagzi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İHANET...LEZZETLERİ ACILAŞTIRAN TAT/sızlık**', 'i-hanet-lezzetleri-acilastiran-tat-sizlik-mehmet-kizilay-vdbs0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İHANET

LEZZETLERİ ACILAŞTIRAN TAT/sızlık

İhanetin vakti gecikmiş

ama asla geçmemiş

horon teper başaklar tepesinde

halay çeker gül dalında

vals yapar 

çocukların parmakları üzerinde

umuda açılan yelkeni

hayınlıkla bilenmiş

bıçağıyla kesiverir..

yavrusuna bakan kuşun 

yuvasını bozar

her insanın yüzünde bir çizgisi vardır

hayatı boyunca ihanet etmeyen var mıdır? 

Kendine ihanet eden isyankar mıdır? 

                 

(ihanete ihanet etmeyi başardığımız sürece hayın değiliz...)', 'İHANET LEZZETLERİ ACILAŞTIRAN TAT/sızlık İhanetin vakti gecikmiş ama asla geçmemiş horon teper başaklar tepesinde halay çeker gül dalında va...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ihanet-lezzetleri-acilastiran-tat-sizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Slagon', 'slagon-yusuf-ter-20xgg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiir mi slogan mı 

Slogan şiir

Şiir olmayan 

Şiirsel  anlatımı bulunmayan

Şiir gibi gösterip

Şiir yalakalığı yapanlar

''Ben anlamam anladıklarımı

Şiir gibi yazarım'' mantığı 

Şiirlerden konu açılmışken

Şiir  insan yapısının aynasını

Karakter ve çizgisini gösterir

Düşüncelerini ortaya koyar

Giyim sektöründe moda dediğiniz

Bikiniler vardır ve birde normal

Sade kıyafetler vardır 

Şiir yazmak, yazmak isteyenlerin

En doğal haklarıdır buna kimse

Yanlış ve ters tepki veremez

Şiir’i bir slogann gibi şiir sayfalarında

Şiirin güzelliğini ırkçı şövenist yaklaşımlara

Getirmekte ne oluyor buna? 

alkış, bravo

Diyen sözde şiir yazan şiir dilinde şiire

Emek verenleri anlamıyorum.

Genç, iyi yürekli, şiir yazan  arkadaşlar

Halkı aydınlatacak, halka ışık verecek

Şiirler yazmalarını tavsiye ederim

Belden aşağı ya da ırkçılığı ön plana

Çıkarak sloganlar kullanmak

Emperyalizmin istediği gibi mi

Şiir yazmak sizce şiir oluyor? 



Sivrisinek  evin içinde dolandı zaman

Onu yakalarsın ve  kanatları halen canlı

Yelpaze gibi açılır kapanır  dışarı bıraksan

Geri gelir öldürsen vicdan azabı çekersin

Şiiri de kimileri sivrisinek misali kullanıyor

Şiir dilinden anlayanlarda arı misali….



Yusuf Ter 19.06.04

Saat 01:16 İsviçre', 'Şiir mi slogan mı  Slogan şiir Şiir olmayan  Şiirsel  anlatımı bulunmayan Şiir gibi gösterip Şiir yalakalığı yapanlar ''Ben anlamam anladıkla...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/slagon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şenlik bebeği', 'senlik-bebegi-akin-akca-1jyey', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Avuçlar içinde

Gülerek doğdu,

Büyüdü gülerek:

Güldü,oynadı,

Kurdu bağdaş,

Geviş getirdi,

Sonra ağustos

Böceğini öğrendi.

Dediler ona

“Sen karakterlisin”

Ama zarf yetmedi:

Kumbarayı kurdular; 

Şenlik bebeği,

Kendini geliştirdi; 

Taksiye binerdi,

Yürür oldu.

Atılım’a sinerdi,

Taştı, doldu; 

Sonunda doğmuştu

Hayat kurdu.

Ve kendini kattı

Kendine, kişilikle

Ölçülemeyecek

Deneyim ölçütünde.', 'Avuçlar içinde Gülerek doğdu, Büyüdü gülerek: Güldü,oynadı, Kurdu bağdaş, Geviş getirdi, Sonra ağustos Böceğini öğrendi. Dediler ona “Sen ka...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/senlik-bebegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Yok Bize', 'ayrilik-yok-bize-derin-oger-vw6vi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gökyüzüne baktıkça

siyahlar biriktiririm her akşam

gözlerin koşa koşa gelsin 

gözlerime avuç avuç yıldız boşaltsın diye

gözlerindir siyah ışıklı bir tablo gecenin içinde

öyle mahzun parlarsın gözlerimde

manzaran ağardıkça

kuşlar gibi kanat silkeler kirpiklerim uykuya

mavi yüzlü bulutlar bizi görmesin diye

başımda yastığım göğsümde emanetimle

sokaklara gün inerken perde perde 

sessizce çekiliriz gölgelere

ayrılık yok bize ey sevgili

ayrılık yok bize..................', 'gökyüzüne baktıkça siyahlar biriktiririm her akşam gözlerin koşa koşa gelsin  gözlerime avuç avuç yıldız boşaltsın diye gözlerindir siyah ış...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayrilik-yok-bize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllara Dikilen Ağaçlar Gibi', 'yillara-dikilen-agaclar-gibi-derin-oger-p73y7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'mutluluk dediğin acının hücrede beklemesi

kara zindanlara dalmış olsa da uykusu kelepçeli

uyandıracak dudaklarımdaki gülümsemenin cazibesi

ağaçların toprakta dört mevsim yeşil durmadığı gibi

bir dünya güzeliyken bir hazana döküleceğiz kuşlar misali..', 'mutluluk dediğin acının hücrede beklemesi kara zindanlara dalmış olsa da uykusu kelepçeli uyandıracak dudaklarımdaki gülümsemenin cazibesi a...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yillara-dikilen-agaclar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuş', 'olmus-cengiz-oyke-h6sr5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep deriz ki; ‘Boşver işte olmuş’ 

Her olmuşun ardında 

Ya doğmuş vardır 

Ya da ölmüş.', 'Hep deriz ki; ‘Boşver işte olmuş’  Her olmuşun ardında  Ya doğmuş vardır  Ya da ölmüş....', ARRAY['Türk Edebiyatı','Şiir','Cengiz Öyke']::text[], 8.5, '{"poet":"Cengiz Öyke","poet_slug":"cengiz-oyke","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olmus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Puslu Hayat', 'puslu-hayat-cihan-firat-dpq00', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneşin göz yaşlarına

Şahidim denize saçılan

Avuçlarımdaki sıcaklık

Yüreğimden taşan	

Dudaklarından sızan nameler

Dosluğu sevdiren

Derin duygulara hükümlüyüm

Yüreğime hükmeden', 'Güneşin göz yaşlarına Şahidim denize saçılan Avuçlarımdaki sıcaklık Yüreğimden taşan	 Dudaklarından sızan nameler Dosluğu sevdiren Derin duy...', ARRAY['Türk Edebiyatı','Şiir','Cihan Fırat']::text[], 8.5, '{"poet":"Cihan Fırat","poet_slug":"cihan-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/puslu-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-cihan-firat-wu24n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Damarımda akan kan sana

Aklımda sayılamayan hayallerim sana 

Ufukta görünen batıdaki güneş bana

Denize fırlattığın her taş bana 

Denizde derinlerde kaybolan hayaller bana 

Her gün doğan güneş sana 

Her doğan ay içime düşen karanlıkta

Bir ümit parçası bir ümitte sana 

Kaderimden bir ak parçası sana 

Aşkımda yaşadığım hayal kırıklığı 

Ümitsizlik karanlığın vazgeçilmez sayıldığı

Geceler  bana kalbimde yaşayan güneş sana

           Aydınlatmasını bir türlü başaramadığım sana', 'Damarımda akan kan sana Aklımda sayılamayan hayallerim sana  Ufukta görünen batıdaki güneş bana Denize fırlattığın her taş bana  Denizde der...', ARRAY['Türk Edebiyatı','Şiir','Cihan Fırat']::text[], 8.5, '{"poet":"Cihan Fırat","poet_slug":"cihan-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sana-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Benim İşte', 'o-benim-i-ste-cihan-firat-bewpt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kayıp dünyaların karanlığı gibiyim 

Karanlığı hüküm giymişte

Güneş nedir bilmez gibiyim

Kaderi gülmezlerden biride benim 

Karamsarlığı kardeş gibi severim 

Sevgiyi hiç doyasıya tatmasam da

Tanımını az çok bilirim 

Yalnızlığın tek adresi gibiyim 

Yalnızlığın belalısı belanın derdi benim

Ben niyemi böyleyim 

Karamsarlığı kardeş diye sen sevdirdin 

Kaderimi yüreğime deştin o sözlerinle

Ne çabukta unuttun beni hiç beni tatmamış gibi

Senden sonra ne yıllanmış aşklar devirdim

Hiç birini de sevmedim sigaramdaki duman gibi 

Ben seni hiç sevmedim ya gönül

Ben senin bana gülen yalancı gözlerini sevdim

Eğer bir gün beni soracak olursan kalbimin en derin

En soğuk köşesindeyim karanlık her yanımda

Yanım da emanetin karamsarlık kardeşim değil

Ben ta kendisiyim..', 'Kayıp dünyaların karanlığı gibiyim  Karanlığı hüküm giymişte Güneş nedir bilmez gibiyim Kaderi gülmezlerden biride benim  Karamsarlığı karde...', ARRAY['Türk Edebiyatı','Şiir','Cihan Fırat']::text[], 8.5, '{"poet":"Cihan Fırat","poet_slug":"cihan-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/o-benim-iste-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuru Gül', 'kuru-gul-cihan-firat-0ctgo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimde bir nefestin

Dışa vuramadığım

Yalnızlığımın sesiydin

Haykıramadığım

Kaderimin fani bekçisi

Sevginin aşkın eseri

Hayallerimin anlamı

Kalbimde yaşayan 

Hayal gibi anılarım 

Yoldaşım kuru bir 

Gül elimde solan

Amansız bir aşkın 

Elimde kalan fani

Bir hediyesi', 'İçimde bir nefestin Dışa vuramadığım Yalnızlığımın sesiydin Haykıramadığım Kaderimin fani bekçisi Sevginin aşkın eseri Hayallerimin anlamı K...', ARRAY['Türk Edebiyatı','Şiir','Cihan Fırat']::text[], 8.5, '{"poet":"Cihan Fırat","poet_slug":"cihan-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kuru-gul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükenmeden', 'tukenmeden-yusuf-koc-8ecnf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çalsam ben kapını içeri girsem,

Söylesem derdimi söz tükenmeden,

Huzuruna varsam eteğin öpsem,

Çöksem taht önüne diz tükenmeden.

Yazdırdım katibe arzuhalimi,

Bilmeden yüklendim yar vebalini,

Dedim uzat bana narin elini,

Sevdayı bulalım biz tükenmeden.

Akşam da sabah ta gönlüm duada,

Sorarım hangi dert vardır sırada,

Yarim gurbet elde bende sılada,

Yokuşlara vardım düz tükenmeden.

Yavaş yavaş kararıyor ortalık,

Ümidim kalmadı yarınım buruk,

Gönül pınarımın suları duruk,

Kışımı yaşadım güz tükenmeden

En sonunda buldum büyük kapıyı,

Son durağım olan taştan yapıyı,

Kapatırlar orda hepten çatıyı,

Koç Ozan tükenir siz tükenmeden.', 'Çalsam ben kapını içeri girsem, Söylesem derdimi söz tükenmeden, Huzuruna varsam eteğin öpsem, Çöksem taht önüne diz tükenmeden. Yazdırdım k...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tukenmeden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başka Güzelsin', 'bir-baska-guzelsin-i-smet-barlioglu-upuru', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sesin bir çağlayan güller içinde,

Dilin en güzel dil diller içinde,

Gözlerin derin göl göller içinde,

Şarkın yağmur gibi rüzgar altında.

Tutup öpmek gerek parmaklarını,

Sedef rengindeki yanaklarını,

Alıştır gülmeye dudaklarını,

Ne kadar mahzunsun bu genç yaşında.

Bir başka güzelsin; menekşe kokan,

Bir başka ateşsin; değmeden yakan,

Sulak bir vahada dinlenen kervan,

Tatlı bir serapsın sanki karşımda.

Sen bulduğum değil, aradığımsın,

Bir ömür peşinden ağladığımsın,

Her soluk alışta uğradığımsın,

Her an yaşıyorsun yanıbaşımda.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 25-26/100)', 'Sesin bir çağlayan güller içinde, Dilin en güzel dil diller içinde, Gözlerin derin göl göller içinde, Şarkın yağmur gibi rüzgar altında. Tut...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-baska-guzelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçum', 'sucum-i-smet-barlioglu-42bd9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dertsiz başım dertlerde,

Yakam zalim ellerde,

Tad kalmadı gecemde,

Suçum seni sevmekmiş.

Sabahsız gecelerim,

Her an ağlar inlerim,

Meğer benim kaderim

Boşuna dövünmekmiş.

Özlem sevdanın yası,

Vuslat müjdenin hası,

Sevenlerin hatası

Sevmiyor görünmekmiş.

Kalp kaldırmaz kederi,

Yaralanır her yeri,

Sevenlerin kaderi

Yaslara bürünmekmiş.

Kimseye meyletmedim,

Sadece seni sevdim,

Meğerse akibetim

Bir ömür sürünmekmiş.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden)', 'Dertsiz başım dertlerde, Yakam zalim ellerde, Tad kalmadı gecemde, Suçum seni sevmekmiş. Sabahsız gecelerim, Her an ağlar inlerim, Meğer ben...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sucum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma ki', 'sanma-ki-i-smet-barlioglu-3y51x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanma ki yeni çıktım bu kapının önüne,

Yıllardır eşiklerde böyle geçiyor ömrüm.

Benzetiyorum seni her bakıp gördüğüme,

Yıllardır eşiklerde böyle geçiyor ömrüm.

Dönersen bulma diye kapımı duvar gibi

Hep açık tutuyorum, bir ahdi tutar gibi,

Yağmurunu bekleyen bir susuz bahar gibi

Yıllardır eşiklerde böyle geçiyor ömrüm.

Ne zaman gelirsen gel, ben yerli yerimdeyim,

Bir senin umudunda, bir senin derdindeyim,

Derdimin ya birinde, ya da öbüründeyim,

Yıllardır eşiklerde böyle geçiyor ömrüm.

Bekliyorum yıllardır yağmurda, fırtınada,

Belki bir gün gelirsin benim için imdada,

Eskimiş eşiklerde güneş boşa doğmakta,

Yıllardır eşiklerde böyle geçiyor ömrüm.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 29-30)', 'Sanma ki yeni çıktım bu kapının önüne, Yıllardır eşiklerde böyle geçiyor ömrüm. Benzetiyorum seni her bakıp gördüğüme, Yıllardır eşiklerde b...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sanma-ki-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anma Beni', 'anma-beni-i-smet-barlioglu-vl58k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anma beni, hayalime ilişme,

Bu yorulmuş yüreğimle güreşme,

Beni yine kazanmaya girişme,

Vah vah bana, eyvah bana, ah bana.

Gençliğimi kavraladın ağ gibi,

Çile yığdın tam önüme dağ gibi,

Gönlüm oldu bir bozulmuş bağ gibi,

Vah vah bana, eyvah bana, ah bana.

Yaralandım tek bir selam beklerken,

Lanetlendim günahımdan çok erken,

Neler buldum kalkıp neler dilerken,

Vah vah bana, eyvah bana, ah bana.

Suçum aşık olmak imiş güneşe,

Meğer canım düşecekmiş ateşe,

Nasıl döndüm zindanlara düşmüşe,

Vah vah bana, eyvah bana, ah bana.

Şimdi artık tutar yerim kalmadı,

Söz vermiştin, söz yerini bulmadı,

Ne yazık ki henüz çilem dolmadı,

Vah vah bana, eyvah bana, ah bana.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 31-32/100)', 'Anma beni, hayalime ilişme, Bu yorulmuş yüreğimle güreşme, Beni yine kazanmaya girişme, Vah vah bana, eyvah bana, ah bana. Gençliğimi kavral...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anma-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Buğusu', 'can-bugusu-oguzkan-bolukbasi-xe0t8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendime kötülük eder yüreğim

Biçimsiz şekillerde görünüyor aşk

Gözlerim umutsuz

Yolları gözlüyor

Serin meltem rüzgarlarında

Bir yaz akşamının

Viranelerde ıslık çalıyorum

Yoksul sevdaların kapısındayım

Gözlerinde yanan ışık

Ben

Karanlıktayım

Neden sesim kayboluyor bir büyük boşlukta

Oysa son nefesimi bırakmıştım

Dudaklarının yangın yeri ıslaklığına

Can buğusu

Görüşümü engelliyor

Özlem yeşerirdi bir cümlenin sıcaklığında

Bırakmadın ki boğulayım

Yağmur sonrası

O selin sularında

Kendime kötülük ediyor yüreğim

Dağlarda eşkıya yalnızlığı yaşıyor

Son baskın

Senin baskının

En savunmasız anımda

Yani severken

Sorgusuz sualsiz vuruyor

Bir ağaç dibine düşüyorum

Öldüğüm aşikar

Can buğusu gibi

Yapışıp kalıyorum dağlara

Karlar yağıyor

Silahlar susuyor

Sessizliğin içinde kayboluyorum

Gözün aydın dünya

Ölüme aşık oluyorum

Can buğusu çıkmıyor nefesimden', 'Kendime kötülük eder yüreğim Biçimsiz şekillerde görünüyor aşk Gözlerim umutsuz Yolları gözlüyor Serin meltem rüzgarlarında Bir yaz akşamını...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/can-bugusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-duygu-i-demen-catac', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geniş zamanlarda dar cümlelerimiz oldu bizim

yüreğimizin sesi kısıldı gözlerimizdeki çığlıklardan

Oysa bir dolu kelimem var senin için 

acılarım,sorularım biriktirdiklerim var.

Ne akmak biliyorlar sessiz sakince ne çağlamak

bir yol çiz benim için yüreğinden yüreğime

bir ses ver yankısı olsun

bir nehir akıt gözlerinden gözlerime

yoluna girmişken ben

sesine kelimelerimi

nehrine gözyaşlarımı akıtacağım

sen bir yol çiz..

Beyaz bir kuş

Yorgun bir ağaç

kırılgan bir menekşe

çılgın bir akarsu

kör eden bir güneş olsun içinde

huzur olduğunu bildiğimde

ölmek bile güzel olacak yolun son adımında..', 'Geniş zamanlarda dar cümlelerimiz oldu bizim yüreğimizin sesi kısıldı gözlerimizdeki çığlıklardan Oysa bir dolu kelimem var senin için  acıl...', ARRAY['Türk Edebiyatı','Şiir','Duygu İdemen']::text[], 8.5, '{"poet":"Duygu İdemen","poet_slug":"duygu-i-demen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yol-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yaslar Tutayım', 'ben-yaslar-tutayim-i-smet-barlioglu-tfbmi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben yaslar tutayım, sen hep bayram yap,

Ömrünce mutlu ol, hiç keder görme.

Ben kışa razıyım, yazı sen yaşa,

Ömrünce mutlu ol, hiç keder görme.

Ömrün sular gibi upuzun olsun,

Denizli, güneşli bir yazın olsun,

Ayın, yıldızların, mehtabın olsun,

Ömrünce mutlu ol, hiç keder görme.

Kahrı ben çekerim, sen çekemezsin,

Yaşı ben dökerim, sen dökemezsin,

Sen hiçbir acıya baş eğemezsin,

Ömrünce mutlu ol, hiç keder görme.

Zaten katar katar dertler bendedir,

Ben derde alıştım nice senedir,

Çilem, elemlerim hep sayendedir,

Ömrünce mutlu ol, hiç keder görme.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 33-34/100)', 'Ben yaslar tutayım, sen hep bayram yap, Ömrünce mutlu ol, hiç keder görme. Ben kışa razıyım, yazı sen yaşa, Ömrünce mutlu ol, hiç keder görm...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-yaslar-tutayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık', 'yazik-tabir-gokce-18wty', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne çileler çektik (!) 

Uzattık duvarları göğe

Boyadık ala, yeşile, maviye

Bacalar yükselttik

Makineler kurduk

Vardiyalar düzdük

Dişimizden tırnağımızdan ürettik

Ürettiklerimizle aştık okyanusları

Tel örgülü, tel örgüsüz sınırları 

Kamyonlar, şilepler, uçaklarla

Ektik, biçtik, yükledik neyimiz varsa

Banka hesaplar

Çek karneleri

Poliçeler 

Paralar, her türlü çehreleri olandan

Aldık verdik, verdik aldık

Yazık...

Unuttuk çıplak ayakları,

Unuttuk sıska bacakları,

Unuttuk aç uyuyanları

Ve

Unuttuk

İnsanca yaşamayı

Sevgiyi sakladığınız yerden çıkarın... lütfen...', 'Ne çileler çektik (!)  Uzattık duvarları göğe Boyadık ala, yeşile, maviye Bacalar yükselttik Makineler kurduk Vardiyalar düzdük Dişimizden t...', ARRAY['Türk Edebiyatı','Şiir','Tabir Gökçe']::text[], 8.5, '{"poet":"Tabir Gökçe","poet_slug":"tabir-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yazik-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seresri', 'seresri-halil-kalay-ac09h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamanın tuzağına düşünce

geçmişimde peşimden geliyor

sırtımdaki yükle beraber geleceğime

ben doğmamış fetuslar gibi doğmayı

gün yüzünü bekleyen

acımasız çarklardan kaçan

hayata sırtını dönüp

münzevikler gibi

gürültüden,

zevkten,

var oluştan kaçan

başı boş bir serseriyim', 'Zamanın tuzağına düşünce geçmişimde peşimden geliyor sırtımdaki yükle beraber geleceğime ben doğmamış fetuslar gibi doğmayı gün yüzünü bekle...', ARRAY['Türk Edebiyatı','Şiir','Halil Kalay']::text[], 8.5, '{"poet":"Halil Kalay","poet_slug":"halil-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seresri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun Yanımda', 'yoksun-yanimda-mehmet-ozkilinc-lciqq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yoksun yanımda 

Ben yine hayaller aleminde

Kafam karışık düşüncelerde

Kızgınlık bir yanda biraz da küskünlük

Soranım yok ne de olsa

Derdim çok, derdimin fermanı yok

Günler geçip gitmek bilmiyor 

Sabır taşı oldum. Halim perişan...

Yoksun yanımda 

Yine sensiz yürüyorum dar sokaklarda

Sensiz nefes alıyorum yeşil çayırlarda

Bir yanım hep eksik sanki

Seni düşündüğüm ıssız gecelerde

Gözülerimden iki damla yaş dökülür

Seni yazdığım her sayfanın üstüne

Yoksun yanımda

Korkuyorum sensiz olan, güneşin her doğuşunda

Üşüyorum sensiz, kovurucu yaz sıcaklığında

Kalbim daralıyor her gün yokluğunda

Her gün bir haller oluyor bana

Hıçkıra hıçkıra ağlıyasım geliyor

Başım alıp buradan gidesim geliyor

Yoksun yanımda

Bir daha hiç olmayacağını bile bile

Bahçemde iki gül yetiştirdim sana

Biri kırmızı diğeri de beyaz

Solmasın diye her gün suluyorum 

Düşlerimde büyütüyorum onları

Hasretinle böyle avunuyorum

Anlayacağın seni hala çok, çok seviyorum

Ve bütün umutlarımı sana adıyorum

Umarım her zaman mutlu kalırsın

GÜLE GÜLE...GÜLE GÜLE......', 'Yoksun yanımda  Ben yine hayaller aleminde Kafam karışık düşüncelerde Kızgınlık bir yanda biraz da küskünlük Soranım yok ne de olsa Derdim ç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özkılınç']::text[], 8.5, '{"poet":"Mehmet Özkılınç","poet_slug":"mehmet-ozkilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yoksun-yanimda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Monolog', 'monolog-tabir-gokce-90co8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine orada mısın? 

Eskiyen saatlerin durup

Üşüdüğü gölgede

Yani

Yaşlanmış çınarın saklanıp

Utandığı bahçede

Öylemi

Bekle

Rüzgar bıraktı yaprakları

Elleri boş

İki elinde iki gözüm

Yüzüm mü? 

O bende

Yıllanmış çizgilerle

Yol olmuş 

Mor bulutun bıraktığı

Özlemlere

Yüreğimi isteme

O yorgun 

O bitap, sevgilere

Al ruhumu, hala genç

Ve hala senin', 'Yine orada mısın?  Eskiyen saatlerin durup Üşüdüğü gölgede Yani Yaşlanmış çınarın saklanıp Utandığı bahçede Öylemi Bekle Rüzgar bıraktı yapr...', ARRAY['Türk Edebiyatı','Şiir','Tabir Gökçe']::text[], 8.5, '{"poet":"Tabir Gökçe","poet_slug":"tabir-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/monolog-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Bir Yarısı', 'gecenin-bir-yarisi-necmi-unsal-p2p76', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin  bir  yarısı,

Elektrikler   kesik! 

Yağmur  yağıyor.

Canımın  bir  yarısı,

İnliyor  kesik kesik.

Yaram  kanıyor.

Mazi  buruşuk.

Gurbetle  uyuşuk.

Gönlümde  bir  yangın. 

Ruhum  bana  kiracı.

Umutlar  düşlere  dargın.

Kalbimde  bir  acı,

Keder  hüzünle  barışık.

17  Mart 2004 Çarşamba, Danimarka-Køge  22.47', 'Gecenin  bir  yarısı, Elektrikler   kesik!  Yağmur  yağıyor. Canımın  bir  yarısı, İnliyor  kesik kesik. Yaram  kanıyor. Mazi  buruşuk. Gurb...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gecenin-bir-yarisi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairim Bugün', 'sairim-bugun-yasar-pullu-t472m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bayram günüydü o gün

yüreğim düğün

bir seni sevmiştim

birde  kızıl gülleri

engerek gözünde açan gülleri

Gencim

ha desem

kaçarım her damlasından

bu hüzün yağmurunun

Bu gecede sensiz uyayabilirmiyim bilmiyorum

Şairim bugün

Yangin güllerine hasretim

Nesimi yim

Bu gece kim susturacak beni

İdamın müebbetiydi

-------müebbetin hücresi

gelmelerin

Böyle anıden mi gidecektin

bu ömür sensiz bitecekti

Filistinli çocuk için neyse ülkesi

---------ellerin o

tohum için neyse su

-------gözlerin o

Sensiz  podyumdaki bu hayat

güldürürmü yüzümü

Kayboluyorum gülüm

milyonlarin içinden 

seçebilmem için kendi gölgemi

seni düşünmeliyim

Varolmaya başladığımdan beri

ölmemek için

yaşamak için

seni düşünmeliyim

ki hep yenilgidir ölüm

ben çaresiz değilim.', 'Bayram günüydü o gün yüreğim düğün bir seni sevmiştim birde  kızıl gülleri engerek gözünde açan gülleri Gencim ha desem kaçarım her damlasın...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sairim-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi Senin Olsun', 'hepsi-senin-olsun-ali-kilic-kakiz-4cvv7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İster ipek giy ister şal

Bana teneşir tahtası sal,

Zil tak oyna hal hal,

Gözün aydın olsun tek kal.

Sarmaşık sarmış dal dal

Kase dolu şerbet bal

Sen konuş ben lal,

Her şeyim senin şimdi al.

İstemem ne servet ne mal

Eşeğe katıra dayanmaz nal.

Aç köpekler uğulduyor ister yal,

Şimdi bırakıyorum hepsini al.

Lessines / 1989

Ali Kılıç Kakiz', 'İster ipek giy ister şal Bana teneşir tahtası sal, Zil tak oyna hal hal, Gözün aydın olsun tek kal. Sarmaşık sarmış dal dal Kase dolu şerbet...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hepsi-senin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnada Bindi', 'i-nada-bindi-halil-kesken-5j377', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Köprüde karşılaşan, iki keçi gibiyiz

Bu saatten sonra da, geriye dönemeyiz

Fırtınaya yol veren, yağmur şimdilik dindi

Düşmeyi aldık göze, herşey inada bindi…

Sanki eklem yerlerim, ayrıldı teker teker

Yüreğim sana doğru, beynim geriye çeker

Sözde çok uzaktaydı, hasret bize de geldi

Ne sen gelirsin ne ben, herşey inada bindi…

Bu düğümler çözülmez, biz feragat etmeden

Kırdık birbirimizi, hemde hiç haketmeden

Büyük aşk ateşimiz, yangındı, muma döndü

Nasıl özür dileriz, herşey inada bindi…

Daha dün geziyorduk, mutluluk yamacında

Sallanan sevgimizdir, şimdi darağacında

Aşkımızı ben tuttum, sen geçirdin kemendi

Ayrılık dün yayaydı, bu gün inada bindi…', 'Köprüde karşılaşan, iki keçi gibiyiz Bu saatten sonra da, geriye dönemeyiz Fırtınaya yol veren, yağmur şimdilik dindi Düşmeyi aldık göze, he...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/inada-bindi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin, Gece ve Ben', 'hasretin-gece-ve-ben-safak-ozdemir-wtkba', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yokluğunun birinci akşamı.

İlk gözlerin düştü aklıma.

Hani o çok sevdiğim,ela gözlerin.

Artık ne İstanbul avutur beni ne deniz.

Evet,ilk gecemde gözlerin yaktı beni.

Masamda bir mum,

Resimlerin ağlattı beni. 

Yokluğunun ikinci akşamı.

Hava henüz kararmış.

Gökyüzünde ne bir yıldız,ne de Ay  var.

Yalnızlık kapıya gelmiş dayanmış.

Açsam olmaz,açmasam olmaz.

Bir yandan özlemin,bir yandan gece,

Sararken beni esmer, soğuk tenine,

Bir teselli arıyor şimdi gözlerim,

Bende kalan yasak resimlerinde.

Yokluğunun üçüncü akşamı.

Fena sıkıştırdı hasretin yine.

Karşı koymak imkansız hatıralara.

Biliyorum birazdan birkaç ıslak dize,

Dökülecek gecenin gözlerinden,kirpiklerime.

Ve belkide bir sevda şiirine  iki mısra düşecek.

Biri senin biri benim için.

İnan canım,

Seni sevmek kadar,hasretinide çekmekte güzel.

Yalnız üç günü geçirme yeter.

Şimdi bir mum alevinde,sabahlarken gözlerim.

Dudağımda, seni seviyorum demenin o çocuksu utancıyla.

En çok sevdiğim resmine sarılıp, uykuya dalmışım.', 'Yokluğunun birinci akşamı. İlk gözlerin düştü aklıma. Hani o çok sevdiğim,ela gözlerin. Artık ne İstanbul avutur beni ne deniz. Evet,ilk gec...', ARRAY['Türk Edebiyatı','Şiir','Şafak Özdemir']::text[], 8.5, '{"poet":"Şafak Özdemir","poet_slug":"safak-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hasretin-gece-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kara Sevda', 'bir-kara-sevda-muslum-cagli-mx79b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'önceleri renk renk açan çiçekten habersizdim

yoktu derdim, neşeliydim, tasasız, kedersizdim

gülerdim aşıkların döktüğü göz yaşına

şimdi benim de geldi kara sevda başıma

fakat yine mutluyum:bir bilinmez mutluluk

yüreğimden bir sevda akıyor oluk oluk

hayatım anlam buldu bir dilberin sözünde

ben dünyayı keşfettim O`nun iki gözünde

vücudumu birdenbire çılgın alevler sardı

gözüm görmez, dizim tutmaz, saçlar ise ağardı

şimdi bana sorsunlar sevmek nasıl bir şeydir

sevgi bir aşık için dünyadaki her şeydir

benim için:koskoca dünyada yalnız

bir ben varım,bir aşkımız, bir de süt benizli kız', 'önceleri renk renk açan çiçekten habersizdim yoktu derdim, neşeliydim, tasasız, kedersizdim gülerdim aşıkların döktüğü göz yaşına şimdi beni...', ARRAY['Türk Edebiyatı','Şiir','Müslüm Çağlı']::text[], 8.5, '{"poet":"Müslüm Çağlı","poet_slug":"muslum-cagli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-kara-sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-deli-firari-uwe74', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum neyim nerdeyim

sen yoksun ya 

bilinmezlerdeyim

sensizlerdeyim yine bu gecelerde

bu geceler geğilmiydi seni benden ayıran

koparan 

çalan 

sende sevmiştin ya beni 

o yüzden bakamadın gözlerime 

ayrılığı isterken

tutamadın ellerimden 

konuşamadın benimle

bu yüzden yaptın en kolay işini 

sonunu düşünmeden bitirişini

arkana bakmadan ŞEREFSİZCE TERKEDİP GİDİŞİNİ', 'Bilmiyorum neyim nerdeyim sen yoksun ya  bilinmezlerdeyim sensizlerdeyim yine bu gecelerde bu geceler geğilmiydi seni benden ayıran koparan ...', ARRAY['Türk Edebiyatı','Şiir','Deli Firari']::text[], 8.5, '{"poet":"Deli Firari","poet_slug":"deli-firari","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gece-109-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuk Oda', 'soguk-oda-deli-firari-mp13g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soğuk odamda yanlızım

yokluğunla ısınıyorum

içimdeki bitmez sızım 

belki biter sanıyorum

bilmem ki niye bu kadar 

alev alev yanıyorum

söylenilen her söze çabucak kanıyorum

seni hala bu kadar

acaba niye anıyorum 

gel artık galiba

SENİ ÇOK SEVİYORUM', 'Soğuk odamda yanlızım yokluğunla ısınıyorum içimdeki bitmez sızım  belki biter sanıyorum bilmem ki niye bu kadar  alev alev yanıyorum söylen...', ARRAY['Türk Edebiyatı','Şiir','Deli Firari']::text[], 8.5, '{"poet":"Deli Firari","poet_slug":"deli-firari","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/soguk-oda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Aşktır', 'ask-asktir-ayfer-ersoy-lxtsh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk dibi görünmeyen göl

Aşk kıpır, kıpır akan dere

Aşk coştukça coşan çağlayan

Aşk başını suya soktuğunda yalnızlık

Aşk ılık bir meltem

Aşk deniz kıyısında imbat

Aşk deli gibi fırtına 

Aşk fırtına öncesi sessizlik

Aşk rüzgarın içine girdiğinde yalnızlık

Aşk alaca karanlıkta ki gökyüzünde parlayan yıldız

Aşk gün ağarırken tan yeri

Aşk gün batımı sessizliği

Aşk bir uzaklaşıp küçülen, bir yaklaşıp büyüyen dolunay 

Aşk alacakaranlığın içine girdiğinde yalnızlık

Aşk alev, alev yangın

Aşk duman, duman kor

Aşk patlayan yanardağ 

Aşk eriten lav

Aşk ateşe girdiğinde  yalnızlık

	İşte aşk böyle hepsi var hepsi yaşanır sonunda hep yalnız kalınır...

Söylenecek daha ne vardır...

İçtiğin kahve gibi böler uykunu

İçtiğin sigara gibi öksürtür seni

İçtiğin alkol gibi gevşetir seni

Ve elinde avucunda ne varsa alır kumar gibi

Ya vazgeçersin 

               Yada yakındır ölümün...

Aşkın ne adı konur ne de sana yaşattıkları anlatılır...

Aşk aşktır.......

08/06/2004', 'Aşk dibi görünmeyen göl Aşk kıpır, kıpır akan dere Aşk coştukça coşan çağlayan Aşk başını suya soktuğunda yalnızlık Aşk ılık bir meltem Aşk ...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ask-asktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Utansın...', 'ask-utansin-canan-ucer-t3s6k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağılıverdin, 

dağıtıverdin.....

Tapınağında gizlediğin çocukluğundu, 

infazını vacip kılan.

Konuşurken leş kargaları,

uyluğumdaki utançtan erdemimi çalan

şeytanın ta kendisi, değil miydi.....

Ben de günahkarım bildiğin gibi,

buruşulmuş 

atılmış ruhunun acılarını

ser göz çukurlarıma,

öyle sev ki beni

aşk utansın......

Tut ki avuçlarımdan

çığlıklarımız uyansın geceye

mabedimizde ilahiler okunsun....

Bırak şeytan cirit atsın

kuytuluklarımızda..

Sevdalar vardır, bir tuhaftır

yaralı güvercin bakışı saklar

avuçlarında.......

Tut ki ben de çürüdüm

kim sevecekti seni...

Güvercinler ağlayınca,

zaten ölmez mi..

Bir şey söyle kulağıma

De ki, sevişmezsek zaten

öleceğiz............

Sus, konuşma

Hadi, şimdi...................', 'Dağılıverdin,  dağıtıverdin..... Tapınağında gizlediğin çocukluğundu,  infazını vacip kılan. Konuşurken leş kargaları, uyluğumdaki utançtan ...', ARRAY['Türk Edebiyatı','Şiir','Canan Üçer']::text[], 8.5, '{"poet":"Canan Üçer","poet_slug":"canan-ucer","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ask-utansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Sarı gül**', 'sari-gul-kubilay-enginol-6am1j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşi katladım,kıvırdım,kestim

Sarı bir gül yaptım gönül bahçeme

Gönlümün sıcaklığını verdim

Gözlerimden parıltı

Serpildi büyüdü

Ulaştı yıldızlara

Yıldızlardanda ışık aldı,dahada bir parladı

Sevgiyide aldı

Şımarmadı

Birbirinden güzel sarı güller verdi

O güller hep sevenleri,sevindirdi

Bu şiir Necmiye Akdemir''e ithaf edilmiştir', 'Güneşi katladım,kıvırdım,kestim Sarı bir gül yaptım gönül bahçeme Gönlümün sıcaklığını verdim Gözlerimden parıltı Serpildi büyüdü Ulaştı yıl...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sari-gul-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deydimi hiç arkadaş', 'deydimi-hic-arkadas-devran-ekmekcioglu-zwshx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kara sevdaya düştün

Aşkından mecnun misali her gece tutuştun

Ağıt yaktın karaları bağladın

Her gece onun için ağladın deydi mi hiç arkadaş? 

Onun için hazırdın her şeye 

Ömrünü verebilirdin tek bir şeye 

Seviyor diye boş verdiklerine 

Deydi mi hiç arkadaş? 

İçin giderdi sevmekten bahsettiğinde

Ben varım diyemezdin buruk gecelerinde

Aşığım diye katlandığın her derde

Deydi mi hiç arkadaş? 

Her gece ismiyle kalkardın yataktan

Her an hayalini kurardın gözlerini bile kırpmadan

Bu kadar düşünmene

Deydi mi hiç arkadaş? 

Bekledin onu her gece 

Yağmur altında, karanlıkta ve ıslak sokaklarda

Bir damla bile ıslandığına 

Deydi mi hiç arkadaş? 

Kıymetini bildi mi? 

Sana değer verdi mi? 

Bir an olsun seni sevdi mi? 

Onun için sabahladığına deydi mi hiç arkadaş? 

Biliyordun ki seni sevmediğini

Bir an olsun aklına gelip de önemsemediğini

Bunca zaman karşılıksızca sevdiğine 

Deydi mi hiç arkadaş? 

Oda nankör çıktı

Oda onlardan çıktı

Farkı yoktu diğerlerinden

Seviyormuş gibi gözükenlerden

Canından çok sevdiğine 

İsmini bile anmana

Deydi mi hiç arkadaş? 

Ömrünü aldı götürdü

Bu sevda başını döndürdü

Sendeki eşsiz alevi söndürdü

Hayatını vermeye 

Onun için ölmeye

Deydi mi hiç arkadaş...?', 'Bir kara sevdaya düştün Aşkından mecnun misali her gece tutuştun Ağıt yaktın karaları bağladın Her gece onun için ağladın deydi mi hiç arkad...', ARRAY['Türk Edebiyatı','Şiir','Devran Ekmekçioğlu']::text[], 8.5, '{"poet":"Devran Ekmekçioğlu","poet_slug":"devran-ekmekcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/deydimi-hic-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-devran-ekmekcioglu-hz97u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sırtında bohçası çıktın yola be yolcu

Bu yollar sana dar gelir 

Sen neleri aştın be yolcu

Ne oldu yolcu gözünden bir damla yaş süzülüyor

Yoksa aklına eski anılar mı geldi? 

Hey be erkek adam yüreğin mi sızladı? 

Vicdan azabımı çekiyorsun yoksa? 

Üzülme be yolcu hata sende değildi ki

Sen istemedin ki sevmek 

Sen istemedin ki aşık olmak

Ve tek çare olarak çekip gitmek

Artık bana ne oldu böyle diye

Bir çatı altında sabahlara kadar ağıt mı yakıyorsun? 

Yoksa yoksa o suskun yüzünü bozup

Bir bardak içkinin arkasına mı gizleniyorsun? 

Sen yol yorgunusun

Sen bağrı yanık bir yolcusun

Üzülme be yolcu

Bu da geçer bu da....', 'Sırtında bohçası çıktın yola be yolcu Bu yollar sana dar gelir  Sen neleri aştın be yolcu Ne oldu yolcu gözünden bir damla yaş süzülüyor Yok...', ARRAY['Türk Edebiyatı','Şiir','Devran Ekmekçioğlu']::text[], 8.5, '{"poet":"Devran Ekmekçioğlu","poet_slug":"devran-ekmekcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yolcu-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki varsınız', 'i-yi-ki-varsiniz-sule-aydemir-xjlj9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Merhaba, 

Hayatımızda üç kişiyi asla değiştiremeyiz:

Annemizi, babamız ve çocuğumuzu….Hepsinin acısı en ağrılısı..hepsinin sevigilerinin büyüklüğü gibi..

Dargın isek, af edelim, af dileyelim. Değilsek koşup kocaman sevgimizle  sarmaş dolaş bir gün daha geçirelim..Bunun için illaki tescilli bir gün olması gerekmiyor, ama iletişimde aramızı daha da kuvetlendirmek için bir fırsat, bir neden… En son ne zaman oturup birlikte konuştuğumuzu ya da  ne zaman bir paylaşımda bulunduğumuzu düşünelim…Bu günden bir daha olmayacak aynı benden bir tane daha olmadığı gibi…

Bu akşam Antalya ‘ya gidiyorum yine. :)     Yarın buralarda olup internete giremeyeceğimden dolayı şimdiden bütün babaların, tüm bayanların, bayların babalarının, baba adaylarının, babalar gününü kutluyorum ….

Sımsıcak güven duygusu taşıyan babalarımızın sımsıcak kucakları olmasa ne yapardık! 

İyi ki varsınız…‘’Cancemrem’’ babama  ithaf ettiğim şiiri tüm babalara ve baba adaylarına armağan etmek istiyorum ….Sizleri seviyorum… 

Dününüz bu gününüzü hep kıskansın :))   

Sevgiyle, esen kalın daima, 

Şule Aydemir



Dağ ''CanCemremsin''

-Ey dünyamın 

en yalçın dağı 

çiçeklere bezeli 

adımı koyduğun 

‘CanCemrem’ 

-ah içim kaynar 

ateşim akar fikri yakar 

işittim de bakamadım yaralım 

delik deşik etmişler sırtını 

düşünürüm 

kesilir nefesim 

sen gibi 

su toplar gözlerim 

karasu bulutlarını tutup öpmek 

öperek yok etmek isterim 

ve yüzümü sürmek delice 

kırağı düşmüş çimenlerine 

yamacına almadığın 

yaban otlarına 

beslemediğin dikenler adına 

yaşanacak çok baharlar var daha 

kuzey yıldızına sessizce 

nice nisanlar diledim 

öyle bir ilk 

öyle bir sessiz 

–ahh demişsin ki 

ayaklanır yuvamın güvercinleri 

kanatlarında koca denizler 

damla damla düşerler 

kursağımda tüm dizeler 

anlatırdın ‘CemreCanım’ 

çoban yıldızından hikayeler: 

-bir başka olur çoban çocukları 

ölmesin diye göçmen kuşlar 

misketlerinden vazgeçtiler 

şah damarımda çoban çocukları 

ve ben bir inat çoban çakmağı 

daha nelerden 

dahası kavalları 

baba yadigarı 

sisli bir kasım şimdi 

taslağındayız hayatın 

goncada çiğ 

tanesinde ölüm

ölürüm de 

kapamam gözlerimi', 'Merhaba,  Hayatımızda üç kişiyi asla değiştiremeyiz: Annemizi, babamız ve çocuğumuzu….Hepsinin acısı en ağrılısı..hepsinin sevigilerinin büy...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/iyi-ki-varsiniz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babaları Anlamak...', 'babalari-anlamak-i-brahim-ethem-bingul-b22gu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evladıma baktım babayım dedim,

Babamı düşündüm sağlık diledim

Beni bu günlere taşıyan oydu

Babamın hakkını nasıl öderim..

Ağlarken babalar gözyaşı dökmez

Babalar üzülür, hiç belli etmez

Onlar yaşlarını içe dökerler

Babalar dert çeker kimseler bilmez..

Dünü değil, yarınları görürler

Kaygı çeker, evlat için ölürler

Baba yüreği atılmaz yabana

Çok severler de sevmez görünürler..

Baba olmak zordur, çile işidir

Evlat ne söylese baba işitir

Bütün çalışması, derdi, emeği

Bir babanın evlatları içindir..

Babaya saygıda yarışabilsek

Sevgiler içinde yaklaşabilsek

Gülüşünde gizlediği acıyı

Ah.. Bir duyabilsek, anlayabilsek..

Evladıma baktım, babayım dedim

Babamı düşündüm, ömür diledim

Hayat sebebimsin, sen sevenimsin

Ey babam, aşkı ben senden öğrendim...

www.iebingul.com', 'Evladıma baktım babayım dedim, Babamı düşündüm sağlık diledim Beni bu günlere taşıyan oydu Babamın hakkını nasıl öderim.. Ağlarken babalar g...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/babalari-anlamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*...Çaresiz Aşk...*', 'caresiz-ask-erdal-asik-xpx9o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarınları olmayan bu aşk bizi

Umutsuz yolculuklar içinde

Nereye gittiğini bilmeden

Sürüklüyor gittiği yere

Sonu yok sonsuzluğun

Yaşıyoruz her an acılarla

Sonumuzun olmadığı bu

Sonsuz aşk yolculuğunda

Ümitsiz aşklar için 

Ne bir han, ne de durak

Olmadı olmayacak 

Bu dünyada! ..', 'Yarınları olmayan bu aşk bizi Umutsuz yolculuklar içinde Nereye gittiğini bilmeden Sürüklüyor gittiği yere Sonu yok sonsuzluğun Yaşıyoruz he...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/caresiz-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıklı sevgili', 'isikli-sevgili-halil-kalay-nlsxs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hey  yüzünü gözlerimden esirgeyen

bütün kapıları yüzüme kapatan

ışıklı sevdiğim

ruhunu karanlık ruhuma sızdırmayan

kalpsiz zalim sevgili

nezaman döneceksin

yanlızlaşan aşkıma

Sen varlığımı hatırlatan

güneşe gülümseyen çiçekler gibi

ıssızlaşan gözlerime

gülücük

ve ışık saçan tek sevgilimsin..', 'Hey  yüzünü gözlerimden esirgeyen bütün kapıları yüzüme kapatan ışıklı sevdiğim ruhunu karanlık ruhuma sızdırmayan kalpsiz zalim sevgili nez...', ARRAY['Türk Edebiyatı','Şiir','Halil Kalay']::text[], 8.5, '{"poet":"Halil Kalay","poet_slug":"halil-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isikli-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Dersleri', 'sevmek-dersleri-i-smail-sahin-r0lpd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ufuklarda ararken 

kokuşur dağ gibi sevgiler 

ayaklarının dibinde

telaş içinde koşuşup 

kaldırırken taşların altını

farketmezsin; aradığın elinde

sevgi köpek kadar sadıktır 

sevgi keklik kadar ürkek

gururunu kırma geri çevirme 

bir gecede dağlar kurur dalında

yemeyeceksen soyma meyveyi 

ekmeyeceksen sürme tarlayı

başkasını yaklaştırsın tanrıya 

sevmeyeceksen bırak bu dağları', 'Ufuklarda ararken  kokuşur dağ gibi sevgiler  ayaklarının dibinde telaş içinde koşuşup  kaldırırken taşların altını farketmezsin; aradığın e...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevmek-dersleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoktan Gitmişsin', 'coktan-gitmissin-i-smail-sahin-c53zz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kulağımda ayak seslerin 

yüzümde bakışlarının yarası

aynada dolu dolu gözlerin 

karasız utancım, kızgınlığım

kime sorsam 

çoktan gitmişsin

haritada işaretli bir şehir

- ah o şehir- 

yollarında bir pabuçsuz gezginim

cebimde kurumuş kır çiçekleri 

kurulukarında aynı bahar 

kime sorsam 

çoktan gitmişsin

bardağımda parmağının izi

- hiç yıkamadım o bardağı-

oturduğun koltukta sıcaklığın 

yankılanırken dillerin odamda 

bilmiyorum sensiz miyim 

kime sorsam 

çoktan gitmişsin', 'kulağımda ayak seslerin  yüzümde bakışlarının yarası aynada dolu dolu gözlerin  karasız utancım, kızgınlığım kime sorsam  çoktan gitmişsin h...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/coktan-gitmissin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yer değiştirsin hazan', 'yer-degistirsin-hazan-aysenur-yazici-v1rqq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen,

henüz içmediğim suda 

bir yudum,

yazmadığım kitaptaki 

kahramanımsın...

bıraktım

hayat sığıntı çalılarda yansın! 

yan komşu ''zavallı kadın'' desin,

ya da dedikoducular

 ''de'' yip, '' ko'' sunlar..! 

bugün avucumla tenini kokluyorsam,

ister yarın takvimden çıkarılsın

ister baharla yer değiştirsin hazan

aynen böyle...

namerdim korkuyorsam! 

         19.05.2004

          Maçka köşkü

          Yıldız parkı', 'Sen, henüz içmediğim suda  bir yudum, yazmadığım kitaptaki  kahramanımsın... bıraktım hayat sığıntı çalılarda yansın!  yan komşu ''zavallı ka...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yer-degistirsin-hazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok gibi olmuş biri', 'yok-gibi-olmus-biri-nil-canan-l3o51', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kurudu topraklar

En derin yağmurlarla birlikte

Son bir bakış değdirdim göklere

Bulutlardan şeklini aldım yüzünün

Gündüzleri yas tutup geceleri ağladım

Bir mavi düş yorgunu oldu bedenim

En derin köşesine sakladım yüreğimin

En büyük acılar denizini

Bir uçurtma saldım göklere uçan balonlarla

Sevilmeyi uçurdum tepelerden

Sadece sevmeyi sakladım kendime

Umutsuz bir hayatın çırpınışlarına astım boynumu

İpini birazdaha sıkıştırıyor zorlukların dengesizliği

Belki yarına daha sıkı olacak ve yok olmaya alışacağım

Bir hiçliğin çarpışmasını taşıyor sırtım

Yükümü hafifletecek sebebimde yok gibi

Ben acılar denizinde diplere dalıyorum

Bu zaferi kutluyor aynada ki aksim

Bile bile bunalımları taşıyor beynim

Son defa  gülmeyi bekliyor yüzüm

Ağlamadan ama..', 'Kurudu topraklar En derin yağmurlarla birlikte Son bir bakış değdirdim göklere Bulutlardan şeklini aldım yüzünün Gündüzleri yas tutup gecele...', ARRAY['Türk Edebiyatı','Şiir','Nil Canan']::text[], 8.5, '{"poet":"Nil Canan","poet_slug":"nil-canan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yok-gibi-olmus-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Su', 'su-nurten-altinok-91idm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'olsan da

pişmiş aşa su

son damla

bardağı taşıran

kalburla taşıdığım

çok susadım', 'olsan da pişmiş aşa su son damla bardağı taşıran kalburla taşıdığım çok susadım...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/su-261-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkmüş,Doğruymuş?', 'turkmus-dogruymus-ramazan-aydin-yo6e4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Türkmüş,doğruymuş,çalışkanmış,

Bir Türk dünyaya bedelmiş,

Seksenbir yıldır hep aynı masal,

Bizden geride ülke kalmamış.

..

Ne tarım,ne sanayi ülkesi olduk,

Mükemmel tüketim ülkesi olduk,

Her türlü imkanlar bulunur amma; 

Dünyanın en enayi ülkesi olduk.

..

İMF ye her türlü taviz verildi,

Kaynaklar onlara teslim edildi,

Madem olacaktık onlara teslim,

Niye bu kadar Şehit verildi? 

..

Artmıyor bir türlü üretimimiz,

Dışa bağlıyız,herşeyimizle biz,

Tüketim,ithalat gırla gidiyor,

Avrupadan besleniyor itimiz! .

..

Demokrasi nedir bilmeyen ülkem,

Seksen yıl yenilen,bitmeyen ülkem,

Yağmalanan sanki kendisi değil,

Hala televole izleyen ülkem! .

..

Perişan ettiler bu memleketi,

Bilmem hangi ülkeye alsak bileti,

Halk baştakilere güvenebilse,

Ölüyü diriltir bu Türk milleti.

..

Yıldık,yıkıldık artık yeter bıktık! 

Aydın''i de umut kalmadı artık.

Türk çocuklarının bayramı var ama,

Geleceklerinden ümidi kestik.', 'Türkmüş,doğruymuş,çalışkanmış, Bir Türk dünyaya bedelmiş, Seksenbir yıldır hep aynı masal, Bizden geride ülke kalmamış. .. Ne tarım,ne sanay...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Aydın']::text[], 8.5, '{"poet":"Ramazan Aydın","poet_slug":"ramazan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/turkmus-dogruymus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trafik', 'trafik-ramazan-aydin-uqtcj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kamyonları koçlar gibi çarpışır,

Otobusler birbiriyle yarışır,

Kaptan şöfer uyuyarak çalışır,

Neden az olur bizde kazalar? 

..

İneklerde otobanlara inmiş,

Tabelalar kurşunlarla delinmiş,

Trafik ışığı; o da neymiş? 

Neden az olur bizde kazalar? 

..

Geçitden geçilmez candan geçilir,

Bizde adet olmuş sağdan geçilir,

Bazen fren patlar üstten geçilir,

Neden az olur bizde kazalar? 

..

Alır güçlü olan geçiş hakkını,

Haksız haklı olur varsa yakını,

Düşer yola içince rakısını,

Neden az olur bizde kazalar? 

..

Bizim şöför kahramandır yorulmaz,

Tabelalar canavarı durdurmaz,

Kaza olur can kurtaran bulunmaz,

Neden az olur bizde kazalar? 

..

Aydın''i der,yeter bu kadar benden,

Nice canlar ayrılıyor bedenden,

Eser yok hoşgörüden sevgiden,

Neden az olur bizde kazalar?', 'Kamyonları koçlar gibi çarpışır, Otobusler birbiriyle yarışır, Kaptan şöfer uyuyarak çalışır, Neden az olur bizde kazalar?  .. İneklerde oto...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Aydın']::text[], 8.5, '{"poet":"Ramazan Aydın","poet_slug":"ramazan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/trafik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özal', 'ozal-ramazan-aydin-607gu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Samanyolu aşklarının marşıdır,

Semra hanım papatyalar başıdır,

Rüşvet sisteminin temel taşıdır,

Memura iş bildirdi Özal dönemi.

..

Avakado,ananas,kivi,muz,

Gitti dışarıya her türlü döviz,

Hayali ihracat ne bilirdik biz? 

Hepten hayali Özal dönemi.

..

Davulcu Asım damat olurdu,

Yılın olayı: Zeynep doğurdu! 

Efe borsadan küpü doldurdu,

Birbaşka alemdi Özal dönemi.

..

Onunla başladı yalan ve talan,

İtibar görürdü hep çalan çırpan,

Ne hizmetler yaptı şu Engin Civan,

Prensler getirdi Özal dönemi.

..

Otobanda ibreyi sona vurdurdu,

Oğlu Ahmet''e tv kurdurdu,

Elin parasıyla yollar vurdurdu,

Çok yanlış bilindi Özal dönemi.

..

Bir parmak bal çaldın halkın ağzına,

Geldin Bush puştunun Musul gazına,

Bastılar Saddam''ın tam boğazına,

Ambargo getirdi Özal dönemi.

..

Hani bir koyup beş alacaktık,

Bir gitti üstelik beşte kaybettik,

Ambargo kalkacak diye bekledik,

Çok şey kaybettirdi Özal dönemi.', 'Samanyolu aşklarının marşıdır, Semra hanım papatyalar başıdır, Rüşvet sisteminin temel taşıdır, Memura iş bildirdi Özal dönemi. .. Avakado,a...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Aydın']::text[], 8.5, '{"poet":"Ramazan Aydın","poet_slug":"ramazan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ozal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter!', 'yeter-ramazan-aydin-0h84y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Malum güçler kışkırtıyor,

Ülkemde kan akıtıyor,

Kadeş kardeşi vuruyor,

Artık dursun akan kanlar.

..

Mehmetçik sını gözler,

Parçalanır kafa gözler,

Kanlı yaş akıtır gözler,

Yeter kurusun bu gözler.

..

Paramparça üstü başı,

Kuşun delmiş geçmiş başı,

Henuz daha yirmi yaşı

Artık kurusun göz yaşı.

..

Birdi bizim kaderimiz,

Sevincimiz kederimiz,

Bir cephedeydik hepimiz,

Artık duyulsun sesimiz.

..

Kanlı savaş artık dursun,

Yeter artık bu son olsun,

Siyasiler çözüm bulsun,

Artık akan kanlar dursun.

..

Eskiden nede mutluyduk,

Birden nasıl kandırıldık,

Bıktık,yıldık ve yıkıldık,

Artık bitsin bu karanlık.', 'Malum güçler kışkırtıyor, Ülkemde kan akıtıyor, Kadeş kardeşi vuruyor, Artık dursun akan kanlar. .. Mehmetçik sını gözler, Parçalanır kafa g...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Aydın']::text[], 8.5, '{"poet":"Ramazan Aydın","poet_slug":"ramazan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yeter-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-ramazan-aydin-gm6pn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hakkın yolu olsun yolun,

Alma ahını mazlumun,

Bak,kara topraktır sonun,

Kurtuluş yoktur ölümden.

..

Topla aklın başa hemen,

Daha geri gelmez giden,

Olsanda Batman,superman,

Kurtuluş yoktur ölümden.

..

Astronot olsan uzayda,

Dolaşsan Merihte Ayda,

Olmasanda bu dünyada,

Kurtuluş yoktur ölümden.

..

Katın olsa yatın olsa,

Tacın olsa tahtın olsa,

Bu dünyalar senin olsa,

Kurtuluş yoktur ölümden.

..

Aydıni''yim bile bile,

Kimseye düşünme hile,

Güç yetmezki Azrail''e,

Kurtuluş yoktur ölümden.', 'Hakkın yolu olsun yolun, Alma ahını mazlumun, Bak,kara topraktır sonun, Kurtuluş yoktur ölümden. .. Topla aklın başa hemen, Daha geri gelmez...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Aydın']::text[], 8.5, '{"poet":"Ramazan Aydın","poet_slug":"ramazan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/olum-123-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkbahar', 'i-lkbahar-fatih-mehmet-karaca-82k6d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlkbahar geldi, geldi, geldi

Her tarafta neşelendi

Kuşlar öttü, kuzular meledi

Her taraf yeşillendi

	

Ağaçlar çiçek açtı

	Dereler doldu taştı

	Sular şırıl şırıl aktı

	Her taraf yeşillendi

İnsanlar kırlara çıktı

Kelebekler böcekler uçuştu

Göçmen kuşlar yuva yaptı

Her taraf yeşillendi

	

Her mevsim bir başka

	İlkbaharda kendince başka

	Her şeyin ortası varsa

	Mevsimlerin ortasıdır ilkbahar.

	

												(12.04.1999)', 'İlkbahar geldi, geldi, geldi Her tarafta neşelendi Kuşlar öttü, kuzular meledi Her taraf yeşillendi 	 Ağaçlar çiçek açtı 	Dereler doldu taşt...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ilkbahar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şalı Ataların', 'sali-atalarin-ramazan-aydin-mfay0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'At sırtında doğdu öldü,

Senin şanlı ataların,

Çin''e bile diz çöktürdü,

Senin şanlı ataların.

..

Korkmadılar hiç bir kuldan,

Çıktılar Ergenekondan,

Kurdun gösterdiği yoldan,

Senin Şanlı ataların.

..

Diyojen kazdı kuyuyu,

Alparslan aldı tapuyu,

Türklere açtı kapıyı,

Senin Şanlı ataların.

..

Anadolu yurt olmuştur,

Selçuklu devlet olmuştur,

Bizansada dert olmuştur,

Senin Şanlı ataların.

..

Söğütteydi kayı boyu,

Oğuzdandı onun soyu,

Ertuğrul gazinin oğlu,

Senin Şanlı ataların.

..

Osmanlı doğdu büyüdü,

Yedi cihana yürüdü,

Karadan gemi yüzdürdü,

Senin Şanlı ataların.

..

Çağ kapadı çağı açtı,

Düşman ondan korktu kaçtı,

Rönesans yolunu açtı,

Senin Şanlı ataların.

..

Mekke''yide feth eyledi,

Kral,şahlar boyun eğdi,

Padişahlar halifeydi,

Senin Şanlı ataların.

..

Fatih mübarek komutan,

Büyük dahi Mimar Sinan,

Hele muhteşem Süleyman,

Senin Şanlı ataların.

..

Tarihini biraz tanı,

Aktı şehitlerin kanı,

Bıraktı Cennet Vatanı,

Senin Şanlı ataların.

..

Yürü gösterilen izden,

Derman kesildimi dizden,

Bir fatiha bekler sizden,

Senin Şanlı ataların.', 'At sırtında doğdu öldü, Senin şanlı ataların, Çin''e bile diz çöktürdü, Senin şanlı ataların. .. Korkmadılar hiç bir kuldan, Çıktılar Ergenek...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Aydın']::text[], 8.5, '{"poet":"Ramazan Aydın","poet_slug":"ramazan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/sali-atalarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Araştırma', 'arastirma-nil-canan-fga8p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'tarih: 15 mayıs 1992

  olay:genç kız sevdiği delikanlı ile babasının tayini nedeni ile yarılmak durumunda kalacağını düşündükçe çıldırıyor du.Erkek arkadaşı bu duruma pek aldırış eder gözükmüyordu.ayrılığın son haftası genç kız hamile olduğunu öğrenir hemen sevdiği erkeğe koşar erkek umursamaz davranır kız kendini denize atarak hayatına son verir.

tarih:13 mart 1994

  olay: genç kız ve genç delikanlı birbirlerini çılgın gibi sevmektedirler.Ancak delikanlı henüz bir iş bulamadığını kıza bir türlü anlatamaz ve sürekli yalan söyleyerek kızı oyalamayı birşekilde başarır,kız bu duruma daha fazla dayanamaz ailem beni başkasıyla evlendirecek demeyi tercih eder ancak durum değişmemiştir.sonunda erkek çaresiz açıklar bütün gerçekleri genç kıza kız neye uğradığını şaşırır ailesine bu durumun izahına çalışır.ailesi kızı oğlana vermez.oğlan daha fazla dayanamayıp şehri terkeder.Genç kız dayanamaz ayrılığa ailesi kızlarını  odasında asılı bulur.

Tarih:11 temmuz 1994 

   tatildeyken tanışır iki genç kız çok sever delikanlıyı delikanlı hayatın eğlencesinde belliki ancak ne varki genç kız hamiledir ve yapılabilecek pek birşey yok gibidir.genç delikanlı bu mecburiyeti bir türlü kabullenemez ve kayıkla denize açılduığı bir gün kızı denize atar.Genç kız boğularak can verir

Tarih:15 mayıs 1998 

      Genç delikanlı ailesinin ısrarlarına dayanamayıp evlenir akrabasıyla.ancak ne varki sevememiştir bir türlü evlendiği karısını.gönlü hala eski sevdiğindedir delikanlının.birgün sevdiği o kızın evlendiğini öğrenir ve artık ümidini tam anlamıyla kaybetmiş bir şekilde hayatına son verir.

Tarih:22 şubat 2000

     İki sevgili gayet mutlulardır evlilik düşünceleri vardır.genç kız hayatının en büyük mutluluğunu yaşamakta olduğunu düşünür.ancak ne varki bir müddet sonra delikanlının annem istemiyor kendi memleketlimiz olacakmış serzenişiyle karşılaşan genç kız ne yapacağını ne düşüneceğini bilemez.yalan ve aldatılmış olduğunu düşünür bu acıyı yüreği kaldıramaz.ve bir gece odasında ölü bulunur.

tarih:25 nisan 2004 

     önceleri yeni tanışmış iki arkadaştırlar.sonra genç delikanlı duygularına açar genç kıza kız heyecanlanır ilk defa aşkın ne demek olduğunu tatmaktadır.duygusallık ilerler ve evlilik düşünülmeye başlanır.Delikanlı genç kıza birgün ailem seni istemese de benimle evlenirmisin der.kız hiç düşünmeden kabul eder.Ancak ne var ki delikanlının düüşüncesi ayırlıktır.çünkü gerçekten sevememiştir genç kızı.Delikanlı sessizliğe gömülür kaybolup gider,ayrılığı genç kızın arkadaşına bildirir.genç kız haberi aldığında büyük bir şok geçirir.ve birdaha kendine gelemez.hala delikanlıya sevdalı bir şekilde olduğu bilinmektedir.genç delikanlı yeni bir aşkın peşine düşmüşür belki de.........

  (Bu olayın sonunu tam olarak bilemiyorum.araştırmalarıa göre genç kız herşeyden kendini çekmiş,yalnızlığı ercih etmiş,genç delikanlıyı defalarca aramasına rağmen bir sonuç elde edememiş,delikanlı hayatında başka biri olduğunu söylemiş) 

      AÇIKLAMA

  Neden bu olayları sıraladım ard arda....! ! ! ! ! 

Günümüz de ne yazık ki gerçek sevgi ve AŞK''a sahip çıkılmıyor hep bir kaybediliş öyküsü daha dinliyoruz televizyonlarda,haberlerde..

okuduğumuz gazetelerde yeni bir sevda acısı daha...

Neden insanlar bukadar cahil yada neden bukadar bencil..

Kimsenin kimseye güveni kalmadı,bugün ben bir erkek arkadaşımla konuştuğum zaman bayanlara güvenim kalmadı diyor,benim de erkeklere güvenim yok peki sevgi olmadan bir insan nasıl yaşar birde bunun cevabını bilmek gerekiyor,,,

     Yoksa şansımıza ne çıkarsa diyip öylemi gönül vereceğiz birilerine,kaderimiz yukarıda yaşanmış hikayeler gibi olamsın diye ne yapacağız,

    Suçu annemize babamıza mı yükleyeceğiz? ? ? 

Hayır tabii ki hayır.

Ben sadece insan neden sevgi ile seven insan ile bukadar oyun oynayabiliyor...

        Gerçekten sevda savaşı veripte kazanan çiftleri ayakta alkışlıyorum......

      Yalan sevgi gerçekten sevenin sonu oluyor....

Bu konu hakkında görüşleriniz varsa herzaman beklerim....

e mail :[email protected]', 'tarih: 15 mayıs 1992   olay:genç kız sevdiği delikanlı ile babasının tayini nedeni ile yarılmak durumunda kalacağını düşündükçe çıldırıyor d...', ARRAY['Türk Edebiyatı','Şiir','Nil Canan']::text[], 8.5, '{"poet":"Nil Canan","poet_slug":"nil-canan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/arastirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asker', 'asker-ramazan-aydin-po1zn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gücü yeter her çatana,

Kahraman Türk askerinin,

Canı fedadır Vatana,

Kahraman Türk askerinin.

..

Allah Allah diye kükrer,

Düşman ona boyun büker,

Sanki başı göğe değer,

Kahraman Türk askerinin.

..

Her şeyden üstün sancağı,

Kopsada kolu bacağı,

Düşmez yere Al bayragı,

Kahraman Türk askerinin.

..

Savaşa hazırdır her gün,

Ölürse savaşta birgün,

Üstüne örtülür o gün,

Bayrağı Türk askerinin.

..

Aydıni sözlerin bitmez,

Bu bayrak Gönderden inmez,

Çünkü sırtın yere gelmez

Kahraman Türk askerinin.', 'Gücü yeter her çatana, Kahraman Türk askerinin, Canı fedadır Vatana, Kahraman Türk askerinin. .. Allah Allah diye kükrer, Düşman ona boyun b...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Aydın']::text[], 8.5, '{"poet":"Ramazan Aydın","poet_slug":"ramazan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/asker-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlahi Düzen', 'i-lahi-duzen-ramazan-aydin-6lwzk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dışarıda en güzeli ararlar,

Çiçeklerden nektar toplar arılar,

Şaşırmazlar kovanını bulurlar,

Kovandaki petekte bir düzen var.

..

Tavuk yada kuş,yılan yumurtası,

Yumurtadır hepisinin atası,

Bir mükemmel fabrikadır burası,

O küçük yumurtada bir düzen var.

..

Tohumlardan ürün,üründen tohum,

Herşeyde varolan mükemmel uyum,

Bu ahange,ihtişama vurgunum,

Tabiatta ne güzel bir düzen var.

..

Yıldızları gökyüzüne dizen var,

Hepisinde intizam var nizam var,

Tesadüfen olması mümkünmüdür? 

Bu sistemi elbette bir düzen var! 

..

Düzen olmazdı akbaba olmadan,

Yaratmaz hiçbirşeyi boşa, Yaradan,

Bir damlacık sudan oldun Ramazan,

O damla suda büyük düzen var.', 'Dışarıda en güzeli ararlar, Çiçeklerden nektar toplar arılar, Şaşırmazlar kovanını bulurlar, Kovandaki petekte bir düzen var. .. Tavuk yada ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Aydın']::text[], 8.5, '{"poet":"Ramazan Aydın","poet_slug":"ramazan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ilahi-duzen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile Köşk', 'cile-kosk-mustafa-celebi-cetinkaya-spp0n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günler geçmiyorken dertle yas ile 

Sığınmış gönlüme bir umut dağı

Zulume dur diye ölsem nafile

Kara bir talih ki yakıyor bağı

Yüzüme yansımış çaresiz çilem

Ben hep bu aşkla ağlar dururum

Haziran ayında meyvalar olur

Bense kendi dalımda solar kururum.

Öfkedir gözümden gönlüme kadar

Sarıp her yanımı eyleyip düçar

Sevda ortasına düşüp ansızın 

Gencecik yaşlarda olmuşum naçar 

Canımdan çok sevip kendime ettim

Umut bana kaldı aşk bana kaldı 

Gitti sevdiklerim gitti yarınlar

Çileyle yüklenmiş köşk bana kaldı. 

Mustafa Çelebi ÇETİNKAYA 

16 Haziran 2004 Çarşamba  16:50

Cebeci', 'Günler geçmiyorken dertle yas ile  Sığınmış gönlüme bir umut dağı Zulume dur diye ölsem nafile Kara bir talih ki yakıyor bağı Yüzüme yansımı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çelebi Çetinkaya']::text[], 8.5, '{"poet":"Mustafa Çelebi Çetinkaya","poet_slug":"mustafa-celebi-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cile-kosk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Araştırma ile ilgili', 'arastirma-ile-ilgili-nil-canan-g5p57', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'e mail adresim yanlış yazdığım için düzeltiyorum

 email: [email protected]', 'e mail adresim yanlış yazdığım için düzeltiyorum  email: [email protected]...', ARRAY['Türk Edebiyatı','Şiir','Nil Canan']::text[], 8.5, '{"poet":"Nil Canan","poet_slug":"nil-canan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/arastirma-ile-ilgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-ramazan-aydin-0p68q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Altın dediler her taşı,

Maddiyat herşeyin başı,

Kardeş tanımaz kardeşi,

Para her şey İstanbul''da.

..

Kesilir atlar,katırlar,

Suya biraz süt katarlar,

Boku poşetler satarlar,

O da para İstanbul''da.

..

İşe gidip gelmek çile,

Katlanırız bile bile,

Artık dolmaz oldu file,

Yaşamak zor İstanbul''da.

..

Sözde hepimiz şehirli,

Suyu pis havası kirli,

Sokaklar kaynıyor zilli,

Uçkur tutmaz İstanbul''da.

..

Yaşa doya doya yaşa,

Yazılanlar gelir başa,

Bomba düşebilir başa,

Yaşamak şans İstanbul''da.

..

Özledin belli köyünü,

Üzme Aydıni kendini,

Gel hazırla kefenini,

Ölüm yakın İstanbul''da', 'Altın dediler her taşı, Maddiyat herşeyin başı, Kardeş tanımaz kardeşi, Para her şey İstanbul''da. .. Kesilir atlar,katırlar, Suya biraz süt ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Aydın']::text[], 8.5, '{"poet":"Ramazan Aydın","poet_slug":"ramazan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/istanbul-134-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu kadar mı...', 'bu-kadar-mi-muammer-celik-ptqlz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '...çekici olur 

ruhunun güzelliği ile 

bu kadar mı gül açar 

tebessümleriyle...

Bu kadar mi yürek yakar 

yaktıkca çağlayanlar

gözlerimden

şarkılar dudaklarımdan 

şiirler dillerimden akar...

Ellerimde sana merhabalar...

Bu kadar mı güzel olur 

bir kadın sözleriyle 

bu kadar mı güzel 

ve derinden bakar gözleriyle...

Ya o yumuşacık elleriyle 

bu kadar mı sıcak olur 

Allahim! 

Bu kadar mı ilgi doludur! ? 

BirDeli

19.06.2004', '...çekici olur  ruhunun güzelliği ile  bu kadar mı gül açar  tebessümleriyle... Bu kadar mi yürek yakar  yaktıkca çağlayanlar gözlerimden şa...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-kadar-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana', 'ana-ramazan-aydin-9sr4m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Süt verdin mama yedirdin,

Hayatını bize verdin,

Üstümüze kanat gerdir,

Çoktur bizde hakkın ana.

..

Uzaklaşsak beş dakika,

Arardın sen yana yana,

Bizi doyurduktan sonra,

Artanları yerdin ana.

..

Gözünde daha çocuğuz,

Sevgine hala muhtacız,

Sağlığına duacıyız,

Ömrün uzun olsun ana.

..

Bazan üzdük kırdık seni,

Affet nolur sen bizi,

Azaltmadın hiç sevgini,

Yine şefkat duydun ana.

..

Aydıni derki; ne yapsak? 

Sırta alıpta taşısak,

Ödenmez hakkın ne yapsak,

Cennet yolu sensin ana.', 'Süt verdin mama yedirdin, Hayatını bize verdin, Üstümüze kanat gerdir, Çoktur bizde hakkın ana. .. Uzaklaşsak beş dakika, Arardın sen yana y...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Aydın']::text[], 8.5, '{"poet":"Ramazan Aydın","poet_slug":"ramazan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ana-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nenni Türk milleti', 'nenni-turk-milleti-ramazan-aydin-0vlse', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğuştan fanatik taraftardırlar,

Fotospor,fotomaç alır okurlar,

Futbolla yatar,topla kalkarlar,

Uyu Türk milleti,Nennide nenni.

..

Takım taklavatsız maça gidilmez,

Tv lerde proğramdan geçilmez,

Maçlar bitse bile yorumlar bitmez,

Uyu Türk milleti,Nennide nenni.

..

Uğruna kavga ettiğin futbolcu,

Olabilir başka takıma oyuncu,

Kritikler değiştirmez sonucu,

Uyu Türk milleti,Nennide nenni.

..

Hangi futbolcu nerde ne yapmış? 

Kim topu ayağında kaç dakka tutmuş,

Beyinler futbolla uyuşturulmuş,

Uyu Türk milleti,Nennide nenni.

..

Yenilirse takımı durmaz kudurur,

Gerekirse adam bile öldürür,

popla futbolla uyuşturulur,

Uyu Türk milleti,Nennide nenni.', 'Doğuştan fanatik taraftardırlar, Fotospor,fotomaç alır okurlar, Futbolla yatar,topla kalkarlar, Uyu Türk milleti,Nennide nenni. .. Takım tak...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Aydın']::text[], 8.5, '{"poet":"Ramazan Aydın","poet_slug":"ramazan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nenni-turk-milleti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiye''m', 'turkiye-m-ramazan-aydin-hzscq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her karış toprağın şehitlerle doludur,

Şanlı tarihin seferlerle doludur,

Seferlerki,zaferlerle doludur,

Türkiye''m,memleketim,Cennet vatanım.

Akdeniz,kara deniz,ege,marmara,

Üç taraf denizdir bir taraf kara,

Uygarlıklar beşiği bir yarım ada,

Türkiye''m,memleketim,Cennet vatanım.

..

Bereketler taşıyan ırmakların var,

Koyun,kuzu yayılan otlakların var,

Bir alıp bin veren toprakların var,

Türkiye''m,memleketim,Cennet vatanım.

..

Her tarafında zengin bitki örtüsü,

Ormanlarki yurdumun biricik süsü,

Başka başkadır her mevsim görüntüsü,

Türkiye''m,memleketim,Cennet vatanım.

..

Engin nehirlerin dumanlı dağların,

Sınırsız ovaların,yeşil bağların,

Ekmegin,soğuk suyun,tuzsuz yağların,

Türkiye''m,memleketim,Cennet vatanım.

..

Her karış toprağın şehitlerle doludur,

Şalı tarihin seferlerle doludur,

Seferlerki,zaferlerle doludur,

Türkiye''m,memleketim,Cennet vatanım.

..

En ücra köşedeki köyün,kasaban,

İstanbul,Rize,Konya,Başkent Ankara''n,

Tutkundur,sevdalıdır sana Ramazan,

Türkiye''m,memleketim,Cennet vatanım.', 'Her karış toprağın şehitlerle doludur, Şanlı tarihin seferlerle doludur, Seferlerki,zaferlerle doludur, Türkiye''m,memleketim,Cennet vatanım....', ARRAY['Türk Edebiyatı','Şiir','Ramazan Aydın']::text[], 8.5, '{"poet":"Ramazan Aydın","poet_slug":"ramazan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/turkiye-m-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Armağan', 'armagan-cengiz-oyke-5j5qz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünya dediğin üç beş günlük olay 

Kimisi zor yaşar kimisi kolay 

En yakın dostların etsede alay 

Sev birini kardeş daha varken zaman 

Sevgi mevladan en güzel armağan', 'Dünya dediğin üç beş günlük olay  Kimisi zor yaşar kimisi kolay  En yakın dostların etsede alay  Sev birini kardeş daha varken zaman  Sevgi ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Öyke']::text[], 8.5, '{"poet":"Cengiz Öyke","poet_slug":"cengiz-oyke","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/armagan-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '80.Yıl', '80-yil-cengiz-oyke-xm75q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bundan Seksen yıl evvel

Bir imkansız gerçekleşti.

Ulu önder Atatürk 

Kurdu Cumhuriyeti.

Sevgi ile yaşattık

Bu günlere getirdik

Seksen sene boyunca

Mutlu günler geçirdik

Kan kırmızı bayrağım

Daha dalgalanacak

Nice seksen yıllara

Türkiyem ulaşacak

Atamızdan armağan

Yüce Cumhuriyeti

Cumhuriyet çocuğu

Yaşat Cumhuriyeti

Yaşasın Türk Milleti

Cengiz ÖYKE', 'Bundan Seksen yıl evvel Bir imkansız gerçekleşti. Ulu önder Atatürk  Kurdu Cumhuriyeti. Sevgi ile yaşattık Bu günlere getirdik Seksen sene b...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Öyke']::text[], 8.5, '{"poet":"Cengiz Öyke","poet_slug":"cengiz-oyke","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/80-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmam Katipler Kapansın!', 'i-mam-katipler-kapansin-ramazan-aydin-vc8as', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cumhuriyete düşmanlar bunlar,

Kalelerimizi alıyorlar,bağrımıza hançer saplıyorlar,

Daraltıp,bunaltıyorlar,

Pıtrak gibi çoğalıp her yanı kaplıyorlar.

..

Kapattık olmuyor,böldük parçaladık ölmüyorlar,

Ölünün küllerinden yeniden doğuyorlar,

Belediye başkanı,mebus hatta başbakan oluyorlar,

Sindiremiyoruz,midemize oturuyorlar.

..

Bugün başbakan,yarın cumhurbaşkanıda olurlar,

Aman Tanrım! bunlar pilot,paşa bile olurlar,

İlerici! çağdaş! kesimler eridikçe eriyor,

Arkadan nal topluyor.

..

Artık fayda etmiyor yirmisekiz şubatlar,marşlar

Yürüyen tanklar,yapılan ayarlar,koktu bu ayaklar,

Hortumlamak,malı götürmek,halkı söğüşlemek zorlaşıyor,

Döviz çıkmıyor,krizde olmuyor,enflasyon bile düşüyor.

..

Bu böyle olmamalı,durdurulmalı,düğmeye basılmalı,

Rektörler yürümeli,bu hareket engellenmeli,

Yılanın başı küçükken ezilmeli! 

Bunu herkes böyle bilmeli.

..

Eskiden pek uysaldılar vede tepkisiz,

Şu avrupa birliğide nerden çıktı zamansız? 

İmam hatip konusuna nasıl kakalım sessiz? 

Dana yediği taşı bilir,siz bilmezsiniz', 'Cumhuriyete düşmanlar bunlar, Kalelerimizi alıyorlar,bağrımıza hançer saplıyorlar, Daraltıp,bunaltıyorlar, Pıtrak gibi çoğalıp her yanı kapl...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Aydın']::text[], 8.5, '{"poet":"Ramazan Aydın","poet_slug":"ramazan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/imam-katipler-kapansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara Rüzgârı', 'ankara-ruzg-ri-nevin-kurular-cnr5o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ankara rüzgarları karıştı nağmelere

Yürek sazım telleri bir hüzzam makam seçti

Vakur güzellikleri muammada ararken

Bir çiçek dermek için, gördüm ki bahar geçti

Bağırdı avaz avaz tanyeri vakitlere

Ölüm sessizliğince uyuyan şu şehire

Nur muydu, serap mıydı anlamadan ne diye 

Gökleri yarar gibi bir yıldız kayıp geçti.

Bilmem nasıl etmeli ya da ne dilemeli

Şafaklar kızılına sevinç mi  işlemeli

Bir resim mi yapmalı, bin resmimi silmeli

Hayallerin içinden bir hülyalı yar geçti.', 'Ankara rüzgarları karıştı nağmelere Yürek sazım telleri bir hüzzam makam seçti Vakur güzellikleri muammada ararken Bir çiçek dermek için, gö...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ankara-ruzgari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Ve Issız', 'beyaz-ve-issiz-ahmet-haluk-unal-2vdyf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sabaha karşı yazıyorum bunları sana

koca köyü yutmuş çığ gibi

önümde uzanan kağıda 

martı sesleri düşüyor büyük harflerle

yetmiyor dindirmeye korkumu

''mumu yak'' diyor içimdeki ses, yakıyorum

ışık 

yorgun bir tutku gibi dökülüyor üzerine kağıdın

şimdi adım daha iyi okunuyor

az sonra o da çekip gidecek gürültüsüzce

gün 

suskunluğum gibi çoğalırken yeniden

beyaz ve daha ıssız

(2003)', 'sabaha karşı yazıyorum bunları sana koca köyü yutmuş çığ gibi önümde uzanan kağıda  martı sesleri düşüyor büyük harflerle yetmiyor dindirmey...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Haluk Ünal']::text[], 8.5, '{"poet":"Ahmet Haluk Ünal","poet_slug":"ahmet-haluk-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/beyaz-ve-issiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrımsın Mutluluğum', 'cagrimsin-mutlulugum-nevin-kurular-3opz2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her günüme

Bir yudumluk seni istiyorum

Bir yudum

Doyumluk değil

Tadımlıkdır yudum.

Seni,

Deniz deniz içmek isterdim oysa

Sonra,

Yine doyumsuzluğunu hissederdim arzularımda

Bir yudumluk seni istiyorum diyorsam

Merhamet et  beni anla.

Bazen,Ses ol gel diyorum

Bazen,Bir bakış

Bir yudumluk diyorum ya..Unutma.

Sarman zor 

Kalman imkansızsa durma 

Ama beni 

Tamamen de sensiz bırakma.

Öyle alıştım ki sana mutluluğum

Tutku de, tiryakilik de, sevda de

Ne dersen de adına

Bir yudumluk gel

Gel de bana

İster gündüzüme iste akşamıma

Doyumluk değil 

Tadımlık bir tat ver bana

Oysa,deniz deniz içmek isterdim seni 

İmkan olsa', 'Her günüme Bir yudumluk seni istiyorum Bir yudum Doyumluk değil Tadımlıkdır yudum. Seni, Deniz deniz içmek isterdim oysa Sonra, Yine doyumsu...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cagrimsin-mutlulugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelam Vücut Bulur', 'kelam-vucut-bulur-ahmet-haluk-unal-t4hhy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendinden başka kimsen yoksa 

dönemezsin kendine zaman zaman

Hiçbir bilgi saklamaz sana ebediyen, 

birini bilmenin yakıcı kokusunu

Hatırlatmaz sendeki kırılan siyahı, 

çoğalan morları, kızaran yeşili; beni

kelam vücut bulur biliyorsun

bir tende aşk, bir tende ölüm

bir anda yarın, bir anda dün

(12.04.2003 – 24. 05.2004)', 'Kendinden başka kimsen yoksa  dönemezsin kendine zaman zaman Hiçbir bilgi saklamaz sana ebediyen,  birini bilmenin yakıcı kokusunu Hatırlatm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Haluk Ünal']::text[], 8.5, '{"poet":"Ahmet Haluk Ünal","poet_slug":"ahmet-haluk-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kelam-vucut-bulur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönülden Gönüle Aşk...', 'gonulden-gonule-ask-i-brahim-ethem-bingul-lemop', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamayan elbet bilmez hayatı,

Yorulmayan nerden bilsin rahatı

Aşka uğramayan yolcu değildir

Sevgisi sözdedir,bilmez o tadı...

Sevdiğine doyasıya bakana

Ne mutlu,güzele gönül açana,

Güzeli görmeyen beyhude yaşar,

Yardım etsin Mevlâ aşksız kalana...

Yârimin can katar cana bakışı

Aşk oduyla ciğerimi yakışı

O endamdan aşk süzülür kalbime

Gönlünden gönlüme aşktır akışı...

www.iebingul.com', 'Yaşamayan elbet bilmez hayatı, Yorulmayan nerden bilsin rahatı Aşka uğramayan yolcu değildir Sevgisi sözdedir,bilmez o tadı... Sevdiğine doy...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gonulden-gonule-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm Sevgilere Yabancıyım Artık Sevemem', 'tum-sevgilere-yabanciyim-artik-sevemem-murat-nail-guney-jpcb1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzat deme ellerini,  uzatamam artık,

Bir zamanlar el ele idik deme.

Öylesine yıktın ki gururumu,

Öylesine uzak çarpıyor ki artık senden kalbim,

Ellerim yanıma düştü uzatamam...

Yine senin şarkılarını duymak istiyorum deme,

Artık kimse duyamayacak...

Bir zamanlar beraber söylemiş olsak ta,

Öylesine küstü ki bana şarkılar,

Öylesine sus-pus oldu ki dudaklarım,

Şarkılarım dillere düştü, söyleyemem...

Sana İstanbul geceleri getiremem artık,

Bir zamanlr gece yarıları gelmiş olsam da,

Güneşin doğuşunu beraber görmüşsek te,

En güzel duyguları tatmışsam da sayende,

En güzel çağlarımı yitirdim gecelerde,

Sana geceleri getiremem...

Beni yine sım-sıcak öp deme,

Yüzlerce kez öpüşmüş olsak da, 

Dudaklarımız kavruluncaya dek,

O dudaklar buz gibi soğumuş,

O dudaklardan nefret dökülmüş yazık,

O dudaklar kilitlenmiş ne çare,

Öpemem...

Beni eskisi gibi sev yine deme,

Aylar yıllar saçlarıma ak döktü,

Kalbim tutsak oldu geçmişimize,

Tüm sevgilere yabancıyım artık,

S e v e m e m...

murat nail güney', 'Uzat deme ellerini,  uzatamam artık, Bir zamanlar el ele idik deme. Öylesine yıktın ki gururumu, Öylesine uzak çarpıyor ki artık senden kalb...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tum-sevgilere-yabanciyim-artik-sevemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Gibi Biri', 'herkes-gibi-biri-mehmet-koyuncu-vpx86', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Niye yalnız dolaşır yollarda

Özellikle de kimsenin olmadığı

Issız zamanlarda

Kaçmayı kurtulmayı ister belki

Gırtlağına yapışmış gibi

Kendisini sıkan insanlardan

Aslında sıkıldığı insanlar değil

Boğazına kadar gömüldüğü derteleridir

Üstüne üstüne geldikçe bu dertler

Kimseye anlatamamanın ezikliği içinde

Boş yolları seçer yürümek için

Sokulmak ister bazen birisine

Anlatabilmek için dertlerini

Fakat dinletemeyecektir

Duman Duman içine çektiği

Sigarasından başka hiçkimseye

Ayı yılı bırakın 

Ne gecesi kalmıştır bilindik

Ne de gündüzü

Koca bir okyanusun ortasında

Kuru bir salla 

Dalgalara bırakmıştır geleceğini

Yolun sonunu düşünür bazen

Bilir gerekenin ne olduğunu

Fakat cesaret edemez 

Herzaman ki gibi

Ciğerlerini kemiren tek dostuna

Sığınmakta bulur son çareyi

Bir sülük gibidir dertleri

Karanlık bir mağara gibidir

Kanı bitmiş

Ve bir çıkış yolu bulamamıştır

Yorulmuştur artık

Yapması gerekeni yapmalıdır

Son bir kez haykırmak ister

Fakat yine duyuramadan kimseye

Bırakır çileli ve yalnız başladığı

Yolun ortasına cansız bedenini', 'Niye yalnız dolaşır yollarda Özellikle de kimsenin olmadığı Issız zamanlarda Kaçmayı kurtulmayı ister belki Gırtlağına yapışmış gibi Kendisi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Koyuncu']::text[], 8.5, '{"poet":"Mehmet Koyuncu","poet_slug":"mehmet-koyuncu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/herkes-gibi-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama..!', 'babama-musfik-saltik-x9luv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çocukken çok kızardım sana 

Vakit ayırmıyorsun diye bana

Anlam veremiyordum 

Gece gündüz çalışmana

Genç oldum bozulmaya başladım

Akıl vermene bana 

Ben de biliyordum, anlıyordum

İyiyi, kötüyü yanlışı,doğruyu

Devir senin devrin değildi 

Gençler artık senin gençliğindeki gibi

Cahil ve saf değildi 

Benim için bu kadar kaygı duyman

Hiç de mantıklı değildi

Sıkıyordu ön görülerin, nasihatlerin 

Seni hep ayıp olmasın diye dinledim.

Yıllar geçti yaşım ilerledi

Dediklerinin hepsi bir bir başıma geldi

Önceleri tesadüftür dedim gülüp geçtim

Sonra haklı olduğunu kabullendim

Hele baba olunca iyice sana benzedim

Devir bizim devrimiz gibi değil baba

Aklım gidiyor zarar gelecek diye yavruma

Karşıma alıp nasihat ediyorum 

Aman yavrum dikkatli ol diyorum

Benim sana baktığım gibi bakıyor yüzüme

Kulak asmıyor hiçbir sözüme

Ben doğruyu yanlışı biliyorum baba diyor

Laflarımı kulak arkası ediyor

Devir değişti baba şimdiki gençler hiç söz  dinlemiyor.

Ne yapacağımı bilemiyorum,  çok korkuyorum

Tam ihtiyacım olduğunda sana 

Yoksun yanımda, 

Ne olurdu biraz daha yaşasaydın 

Yol gösterseydin bana.

Yaşarken bilemedim kıymetini

Eğer duyabiliyorsan sesimi

Babalar günü hatırına 

Ne olur affet beni baba.

                                                22 Haziran 2004', 'Çocukken çok kızardım sana  Vakit ayırmıyorsun diye bana Anlam veremiyordum  Gece gündüz çalışmana Genç oldum bozulmaya başladım Akıl vermen...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/babama-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz', 'olmaz-ahmet-agdere-hj1ga', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her şarkıcıdan sanatçı olmaz,

Her mankenden de şarkıcı olmaz.

Bakma onun boyuna posuna,

Her yakışıklıdan manken olmaz..', 'Her şarkıcıdan sanatçı olmaz, Her mankenden de şarkıcı olmaz. Bakma onun boyuna posuna, Her yakışıklıdan manken olmaz.....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olmaz-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzuhal ve Talep', 'arzuhal-ve-talep-sinan-ercan-exhd8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fidanlar kelime selviler satır

Orman mazi anılar kesilmekte

Atölye zihin kereste duygular

Parmaklar marangoz kalem testere

Sayfalar kor kızıl harflerim çıra

Ruhum kıvılcım alfabem ateşte

Karanlık alev salmakta semaya 

Yıldızlar tutuşuyor hece hece

Kalbimde okyanus gözlerimde ay

Sahillerimi yutuyor dalgalar

Avucumda geçmişten bir bardak çay

İçimde yine korkunç gel-gitler var

Beden kader mahkumu zaman cellat

Soruldu vicdana en son isteği

Allahım beni cümle cümle dirilt

Boğulsun kanımda kulaç atan deli', 'Fidanlar kelime selviler satır Orman mazi anılar kesilmekte Atölye zihin kereste duygular Parmaklar marangoz kalem testere Sayfalar kor kızı...', ARRAY['Türk Edebiyatı','Şiir','Sinan Ercan']::text[], 8.5, '{"poet":"Sinan Ercan","poet_slug":"sinan-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/arzuhal-ve-talep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delirdi Kalemim', 'delirdi-kalemim-sinan-ercan-ovhy3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine saplandı kalemim

Sol göğsümün üstüne

Anılarımı çıkarıyorum yine

Hey gidi günlerle

Her cümlede soluyor

Mahsun bir fotoğrafım

Yaptıklarım yapmadıklarım

Ve arafta kaldıklarım

Kelime yontuyorum zihnimden

Ah şu kafama taktıklarım

Allahım nasıl oyuncak bu

Ne yapsam aklımı bozamıyorum

Delirdi yine kalemim

Akıllı tek satır yazamıyorum', 'Yine saplandı kalemim Sol göğsümün üstüne Anılarımı çıkarıyorum yine Hey gidi günlerle Her cümlede soluyor Mahsun bir fotoğrafım Yaptıklarım...', ARRAY['Türk Edebiyatı','Şiir','Sinan Ercan']::text[], 8.5, '{"poet":"Sinan Ercan","poet_slug":"sinan-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/delirdi-kalemim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakalıma', 'sakalima-sinan-ercan-0alhn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sakalım değil 

Derdim gür benim

Suratımda 

Derdimin müridi çok benim

Bin olur biri

Güçlenirler her seferinde

Kâr etmez 

Kellesini kessen her birinin

Her biri acı bir nameyle sayıklar

Kıl değil 

Kuldur yüzümdeki siyahlar', 'Sakalım değil  Derdim gür benim Suratımda  Derdimin müridi çok benim Bin olur biri Güçlenirler her seferinde Kâr etmez  Kellesini kessen her...', ARRAY['Türk Edebiyatı','Şiir','Sinan Ercan']::text[], 8.5, '{"poet":"Sinan Ercan","poet_slug":"sinan-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sakalima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Bilmedin Be Gülüm..', 'hic-bilmedin-be-gulum-cemil-akkaya-z7s37', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bilmedin sana olan aşkın değerini

anlamadın sana olan sevginin değerini

ölümüne sevmiştim bilmedin değerini

hiç bilmedin gülüm sen bu sevdanın değerini

her sözün ardında bir damla göz yaşı vardı

her ahı sonunda sevgin vardı

her zorlukta aşkın vardı

ah anlamadın be gülüm...

göz yaşları silinir ama

söylenen sözler asla

bunu hiç anlamadın be gülüm

sen bana yalnış yaptın be gülüm

bilmedin sen bu aşkın değerini', 'bilmedin sana olan aşkın değerini anlamadın sana olan sevginin değerini ölümüne sevmiştim bilmedin değerini hiç bilmedin gülüm sen bu sevdan...', ARRAY['Türk Edebiyatı','Şiir','Cemil Akkaya']::text[], 8.5, '{"poet":"Cemil Akkaya","poet_slug":"cemil-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hic-bilmedin-be-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyorum', 'ozluyorum-baykal-kaanalp-hg4lg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalnızca bakışlarının arkasına gizlediğin

doyumsuz su damlacıklarını

dokunmama izin vermediğin

acımasız sızı taneciklerini

saklamaya doyamadığın mutsuzluğunu

belki şimdi daha çok özlüyorum', 'yalnızca bakışlarının arkasına gizlediğin doyumsuz su damlacıklarını dokunmama izin vermediğin acımasız sızı taneciklerini saklamaya doyamad...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ozluyorum-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hücre', 'hucre-baykal-kaanalp-y389k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hücre

bir damla kan

bembeyaz bir kuzucuk

yapılması gerekenler yapılamayınca

dönemeçler ortadan kalkmış

yol dümdüz

git gidebildiğin kadar

ister ye

istersen yeme de

yanında yat

boşluğun 

ulaşılmazın

hedefsizliğin', 'hücre bir damla kan bembeyaz bir kuzucuk yapılması gerekenler yapılamayınca dönemeçler ortadan kalkmış yol dümdüz git gidebildiğin kadar ist...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hucre-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumaş Bebek', 'kumas-bebek-baykal-kaanalp-2mc17', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ağlayan kumaş bebek

aşk hüzün demek

ayrılık demek

ağlasanda gülsende

yıldızları topla öbek öbek

ağlayan kumaş bebek

acın bitse gerek

aşk düşlerle gezinmek

sevmeyi bilmesende

sevilmeyi topla öbek öbek

ağlayan kumaş bebek

gülüşün artsa gerek

aşk mutluluk demek

her evde her telde

gönülleri topla öbek öbek', 'ağlayan kumaş bebek aşk hüzün demek ayrılık demek ağlasanda gülsende yıldızları topla öbek öbek ağlayan kumaş bebek acın bitse gerek aşk düş...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kumas-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..İsyanlardayım..!', 'i-syanlardayim-hasan-basri-kale-ap2xf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'koruyla yandı /aşıklar

aşkın

korktuk yanmaktan / şimdi

küllerdeyim...

sıcak / gündüz

soğuk / gece

kum taneleri / gözlerimde

çöllerdeyim...

doğruya / doğru

eğriye / eğri

denmez bu alemde / unutmuşuz

dillerdeyim...

göğsümüz / siperdi

dosta giden taşlara / baktık

sırtımız / delik deşik

feyâdlardayım...

kâlp mi mühürlü 

neden dilimiz dönmez

yâr neden sesimiz duymaz..? 

hergün bin kez ölürüz / kimse bilmez

maksat / bir gönüle girmek / ama

onu da Hasan beceremez..

isyanlardayım...!', 'koruyla yandı /aşıklar aşkın korktuk yanmaktan / şimdi küllerdeyim... sıcak / gündüz soğuk / gece kum taneleri / gözlerimde çöllerdeyim... d...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/isyanlardayim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peri Bacaları', 'peri-bacalari-baykal-kaanalp-1tsfm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'peri bacalarının altındaki çeşmeden bir tas su iç

oynayacağın oyunun yerini zamanını kendin seç

ulaş varabileceğin noktaya sen kendin

bulaş alabileceğin kadar,hokkaya sen kendin

idamını isteme ateş böceklerinin sakın

gelir üstüne kalan böcekler akın akın

gitme ardından bulamayacağın herşeyin

üzülürsün oturamayınca otağında beyin

verme kalbini boş yere kıymet bilmeyene

kanma sana,her seni seviyorum diyene

bulursun başka dünyalarda bir tas çorba

giyeceğin altı üstü,eski,yırtık bir urba

kaldır gözündeki kara izbelikleri

temizle duvarındaki bütün örümcekleri

dön aramıza sevda yüklü bulutlarla

taşı geleceğe,kendini büyük umutlarla', 'peri bacalarının altındaki çeşmeden bir tas su iç oynayacağın oyunun yerini zamanını kendin seç ulaş varabileceğin noktaya sen kendin bulaş ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/peri-bacalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm', 'kucugum-guler-ilgaz-qhr0x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden küçüğüm

Bilmesen de görmesen de

Cihan susmuş şu anda

Bekliyor gelişini

Patlamaya hazır volkan gibi

Bekletmeden gel

Sen bekleme gel

Sev beklemeden

Düşünme sev düşünmeden

Küçüğüm

Cihan sessiz şu anda

Bekliyor gelişini

Nabız nabız yeniden

Atabilmek akabilmek artabilmek için

Yüreğinle cihanın içinde

Sevgiyle

Kutlansın kutsansın kutlasın diye cihan

Gelişini

Patlamaya hazırlanırken

Bir dilek tuttum ki

Gelişinle

Şenlensin doğsun diye

Sevginle cihan

Biliyorum şu an küçüğüm

Senden

Gelmeden

Tüm babaların, baba adaylarının gününün aynı heyecanla 

süregitmesi dileğiyle', 'Senden küçüğüm Bilmesen de görmesen de Cihan susmuş şu anda Bekliyor gelişini Patlamaya hazır volkan gibi Bekletmeden gel Sen bekleme gel Se...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kucugum-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Benim Babam Yok ki', 'benim-babam-yok-ki-nurten-altinok-j2ls9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Reklâmlarda alt yazı geçiyor

 (babanızı sevindirmek için ona çiçek alın)  

Babam, bu, 5. yıl senden uzak kalışım 

Gönderemediğim çiçeklerim yüreğimde soluyor

Mezarına bile gelemedim sınırlar var aramızda ama eminim 

Sen bir yerlerden alnıma düşen teri siliyorsundur

Ben, her gün sana Kuran’dan solmayan güller gönderiyorum

Cennet mekânın olsun BABAM.

Bugün babalar günü

Tüm babaları kutluyorum.', 'Reklâmlarda alt yazı geçiyor  (babanızı sevindirmek için ona çiçek alın)   Babam, bu, 5. yıl senden uzak kalışım  Gönderemediğim çiçeklerim ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/benim-babam-yok-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Babalar', 'sevgili-babalar-yusuf-ziyaeddin-sivaslioglu-whvbl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yarın bizim günümüz

Şen olsun gönüllerimiz

Yılda bir gün yetmez

Babaların hakkı ödenmez

Yıllardır taşırız sırtımızda

En büyük sorumlulukları

Adem''den beri babalar

Yaşatır eş ve çocukları

Haydi eşler, çocuklar

Kucaklayın emektar babaları

Unutsun bu savaşçılar

Zorlu, çileli yılları

(İstanbul,19 Haziran 2004)', 'Yarın bizim günümüz Şen olsun gönüllerimiz Yılda bir gün yetmez Babaların hakkı ödenmez Yıllardır taşırız sırtımızda En büyük sorumlulukları...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgili-babalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''a,', 'ask-a-hasan-sakman-i7i8j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani diyorum 

uçup gitsem bu memleketten,

ayrılsam taşından toprağından

doğduğum yerin.

Yeni bir hayat kursam

üzüntüden yoksun.

Hep mutlu olsam,

ağlayınca mutluluktan desem gönülden.

Hani diyorum

bir de sen olsan

bir tek sen olsan

yanımda olsan

hiç ayrılmasan.

(18 Mayıs 2001)', 'Hani diyorum  uçup gitsem bu memleketten, ayrılsam taşından toprağından doğduğum yerin. Yeni bir hayat kursam üzüntüden yoksun. Hep mutlu ol...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ask-a-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Gülün Dostlar', 'siz-gulun-dostlar-hasan-sakman-sg9lj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen yitik bir mayıs sabahı 

etekleri kızıl gökyüzü,

benim gözlerim uykusuzluktan.

Öldüğümü sandığım sabahlarda 

doğarım yeniden,

güldükçe sanarlar ağladığımı.

Siz gülün dostlar,

size gülmeler yakışır.

Bana yitik bir mayıs sabahında ölmeler.

Söyle kaç mevsimin yağmuru

yıkar günahlarımızı,

Kaç gezegenin okyanusları.

Beynimde çakan bu şimşekler,

yüreğimdeki bu sızı...

Söyle ne kadar ilaç deva olur bu yaraya

hangi doktor anlar acımı

kesip biçmeden göğüs kafesimi.

Açık bir kapı bırakmıştık arkamızda

kapıyı açıp gördük ki masada 

kırık bir kalem,

yarım kalmış şiirler,

rutubet kokuyor papatyalar.

Tadı kalmadı artık hiç bir şeyin,

her seferinde fazla gelir oldu 

çayıma şeker,

bu yüreğe fazla gelir oldu bu acı.

Sen yitik bir mayıs sabahı 

etekleri kızıl gökyüzü,

benim gözlerim uykusuzluktan.

Yüreğim kilitli,anahtarını denize attım

yutup uzaklara götürsün diye  balıklar.

En usta çilingir açamaz kapıyı bilesin.

Silin gözyaşlarınızı, yakışmıyor...

Siz gülün dostlar,

size gülmeler yakışır.

Bana yitik bir mayıs sabahında ölmeler.

(20 Mayıs 2004)', 'Sen yitik bir mayıs sabahı  etekleri kızıl gökyüzü, benim gözlerim uykusuzluktan. Öldüğümü sandığım sabahlarda  doğarım yeniden, güldükçe sa...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/siz-gulun-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Verdim vereli', 'verdim-vereli-ferit-teksoy-e45at', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her an aklımdasın atamıyorum

Yastığım taş oldu yatamıyorum

Günlük işlerimi tutamıyorum

Sana yüreğimi verdim vereli

Uykular sancılı,kötü düşlerim

Sıka sıka ağrı doldu dişlerim

Çeşmeler bozuldu akar yaşlarım

Sesinden daveti aldım alalı

Hasret bıçak oldu,özlemin satır

Üstüme yorgan ol,kolunda yatır

Şu garip gönlümde çağrıyı bitir

Yokluğun kor oldu sevdim seveli

Başka soranım yok,sen de sormazsan

Gönlüme bir su serp,tasta vermezsen

Bu yangın söner mi sen söndürmezsen? 

İçim ateş oldu gördüm göreli

Sensiz tüm hayatım çok boşmuş meğer

Karşımda duruşun dünyaya değer

Bu yürek bu aşka boynunu eğer

Seni beklermişim bildim bileli.', 'Her an aklımdasın atamıyorum Yastığım taş oldu yatamıyorum Günlük işlerimi tutamıyorum Sana yüreğimi verdim vereli Uykular sancılı,kötü düşl...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/verdim-vereli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnfaz', 'i-nfaz-hasan-sakman-7muth', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İdam sehpalarını kurdum.

Sırası gelen buyursun,

itirazı olan sıkıysa karşı koysun.

(28 Mart 2002)', 'İdam sehpalarını kurdum. Sırası gelen buyursun, itirazı olan sıkıysa karşı koysun. (28 Mart 2002)...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/infaz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız Şiir', 'adsiz-siir-zeki-ergin-8lx3p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'balıkların peşine takılıp

gitmek isterim hep

yedi iklim

sınırları yok onların

tel örgüleri

mayınları da yok

pasaportsuz

dolaşırlar dünyayı 

karınları tok

_erenköy 19haz04

_birgün 6eki05

_dağlara ver sırtını yt:haz09', 'balıkların peşine takılıp gitmek isterim hep yedi iklim sınırları yok onların tel örgüleri mayınları da yok pasaportsuz dolaşırlar dünyayı  ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adsiz-siir-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslı''ya I,', 'asli-ya-i-hasan-sakman-ni0pz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kapkara bulutlarla kaplı bir gece,

acımasızca çakan şimşekler

ve inadına parlayan bir yıldız...

Sabah ayazında iki sevgili,

kumsalda ışıl ışıl bir güneş...

Uçsuz bucaksız okyanuslar...

Sabah güneşiyle açılan bir gül,

kapanan perdelerin arkasında,

iki sıcak ve mutlu yüz...

Uzanan bir ele dokunan 

ince, narin parmaklar...

Bir kır pikniğinde 

ya da pencerenin buğulu camlarından

izlenen rengarenk bir kelebek...

Koca bir buğday tarlasının sarılığında 

bir başak tanesinin toprağa uzanışı...

İçtenlikle söylenen iki küçük söz...

Ardınsıra tekrarlanan ve sanki

hiç bitmeyecekmişcesine duyulan özlem...

Mutlulukta ve sağlıkta,

hep birlikte...

Oda duvarlarına asılan tatlı,

küçük resimler...

Bir radyo frekansından ya da

yürekten söylenen aşk şarkıları...

Her anı seni sevmekle geçen,

bir ömür uzunluğunda

bir kalp atışı yakınlığında,

gözlerimden dökülen yaşların 

içtenliği kadar,

hiç kimseyi sevmediğim 

ya da sevemeyeceğim kadar...

ve üç noktanın doldurulamayan boşluğunda,

şimdi seni benden, senden, bizden

bir gülden, evrenden ve de ömrümden

daha çok seviyorum...

(1 Nisan 2001)', 'Kapkara bulutlarla kaplı bir gece, acımasızca çakan şimşekler ve inadına parlayan bir yıldız... Sabah ayazında iki sevgili, kumsalda ışıl ış...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/asli-ya-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aykırı', 'aykiri-salih-ozalasan-22a2h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Değişmiş zaman ile mekan

Aykırılık olmuş ilke

Cümleler kurulur olmuş bam telinden

İnsanlar yönelmiş seks ile şirke

Tecrit edilir olmuş yaşayanlar sade

Bakılır olmuş kıyafette ilk kürke

Şiirlerde şarkılarda kalmamış güfte

Aykırı sazlar aykırı sözler girmiş ilke

Aykırı kelamlar alır olmuş paye

Lügat parçalamak layık ödüle

Sanatı çevirmişiz kıyısından köşesinden

Kemire, kemire bir hödüğe

Renkler bile pespaye kalmamış natüre

Yolumuz pür karanlık hak getire

Aykırılık rüzgarına kapılmışız

Yol alır olmuşuz ha/bire

Sanatın koltukları dağıtılmış birer, birer

Çok yakında kalacağız muhtaç sedire

Aykırı sazlar, aykırı sesler, aykırı bizler

Bakacağız ayna yerine yakındır birbirimize

Y.Tarihi 03-06-04 

Salih ÖZALAŞAN', 'Değişmiş zaman ile mekan Aykırılık olmuş ilke Cümleler kurulur olmuş bam telinden İnsanlar yönelmiş seks ile şirke Tecrit edilir olmuş yaşay...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aykiri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*~*~*~*~* CANlM BABAM *~*~*~*~*', 'canlm-babam-baki-son-ceylq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BABAM....

Sana olan sevgim satırlara sığmaz ki...

Hiç bir cümle bu minnetimi anlatamaz ki...

Bilsen seni öylesine seviyorum ki...

Bilsen seni öylesine özledim ki...

..........................................................(Suskun Satırlar) 

“Ana da baba da başta taç, 

Her derde deva imişler, 

Her çocuk hangi mertebede olurlarsa olsun; 

ANA, BABA’ya muhtaç imiş” 

Gerçeğini bir an bile unutmayarak, 

Anneler ve Babalar Günü’nde; 

Onlara olan sevgi ve saygımızı perçinleştirmek için gönüllerini alalım. 

Güzel bir çift söz, bir demet çiçekle.... 

Yeter ki hatırlayalım. 

Onları kaybettikten sonra, 

‘Gölgeleri bile yeterdi’, demeyip... 

Hayattayken değerlerini bilelim..! 

*~*~*~*~*  KUCAK DOLUSU SEVGİLERİMİ SUNAR *~*~*~*~* 

*~*~*~*~*  BABALAR GÜNÜNÜNÜZÜ KUTLARIM.....*~*~*~*~* 

Sude Son', 'BABAM.... Sana olan sevgim satırlara sığmaz ki... Hiç bir cümle bu minnetimi anlatamaz ki... Bilsen seni öylesine seviyorum ki... Bilsen sen...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/canlm-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Hiç....', 'siz-hic-baris-guc-2fb2h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kim bilebilir, gecenin bu suskun yalnizligini 

Kim susturabilir, hiçkira hiçkira aglayan bu karanligin acisini

Kim durdurabilir, içimdeki bu dinmek bilmeyen firtinayi 

Sizin hiç bombos hayalleriniz oldumu

Siz hiç cam kiriklari üzerinde aglayarak yürüdünüzmü

Siz hiç sevilmeden sevdinizmi? 

19.06.2004    sda ozlt      msn:  [email protected]', 'Kim bilebilir, gecenin bu suskun yalnizligini  Kim susturabilir, hiçkira hiçkira aglayan bu karanligin acisini Kim durdurabilir, içimdeki bu...', ARRAY['Türk Edebiyatı','Şiir','Barış Güç']::text[], 8.5, '{"poet":"Barış Güç","poet_slug":"baris-guc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/siz-hic-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam Icin', 'babam-icin-dilek-farhood-ohqxn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana dair ve seni anlatan,

Bir seyler yazmak istedim, 

Bilemem ne kadar anlatabilirim,

Ama yuregimi dokmek istedim...

Senin sicakligini hissederek,

Duygularim tasiyor.

Bir gun gelecegimi bilerek,

Gonlum durmak bilmiyor...

Sadece bugun degil,

Her an kutlarim seni! 

Benim babam oldugun icin,

Sansli sayarim kendimi...

Sozlerin kulagimda,

Yumusacik sessizce.

Gozlerin aynen bende,

Sana bakarim kendimce...

Babalar gunun icin,

Varligin sevgin icin,

Bende var olan sen icin,

Mutlu sayarim kendimi...', 'Sana dair ve seni anlatan, Bir seyler yazmak istedim,  Bilemem ne kadar anlatabilirim, Ama yuregimi dokmek istedim... Senin sicakligini hiss...', ARRAY['Türk Edebiyatı','Şiir','Dilek Farhood']::text[], 8.5, '{"poet":"Dilek Farhood","poet_slug":"dilek-farhood","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/babam-icin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüm dünyayı', 'gordum-dunyayi-yusuf-koc-c37lc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Batacak bilirim doğan şu güneş,

Onda ısınmayan bedenler gördüm,

Yaban oldu bana bacı,dost, kardeş,

Aldırmadan geçip gidenler gördüm.

Yağan yağmur iliğime işledi,

Sanki gönül haram meyva dişledi,

Sıcak yaz gününde mevsim kışladı,

Çölde sevdasından bitenler gördüm.

Yola çıktım dedim başım selamet,

 Yarısında bittim koptu kıyamet,

Gönül dedi..haydi durma devam et,

Bu yolda yakılıp tütenler gördüm.

Kimisi tapıyor paraya pula,

Kimi esir olmuş değersiz kula,

Kimi hasret kalmış gönlünde sıla,

İpek diye satılan ketenler gördüm.

Cahil sözlerine mesel demişler,

Beşe alıp üç kuruşa satmışlar,

Doğru söyleyeni haça çakmışlar,

Buz üstüne çilek ekenler gördüm.

Dünya hali böyle şaşırdım kaldım,

Görmesin gözlerim uykuya daldım,

Koç Ozan der gerçeği şiirde buldum,

Gönül yarasını dikenler gördüm.', 'Batacak bilirim doğan şu güneş, Onda ısınmayan bedenler gördüm, Yaban oldu bana bacı,dost, kardeş, Aldırmadan geçip gidenler gördüm. Yağan y...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gordum-dunyayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin derdi', 'sairin-derdi-yusuf-koc-uz3z7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çağırıyor beni uzaktan bir ses,

Varayım diyorum varamıyorum,

Sevdamı koymak için altından kafes,

Alayım diyorum alamıyorum.

Aşkım için yola düştüm yoruldum,

Ne garipten ne alimden soruldum,

Bir söz etti güzelime darıldım,

Sorayım diyorum soramıyorum.

Kozasından çıktı hemen uçacak

Dolanır dağlarda kelebek böcek,

Ağacım..baharda rengarenk çiçek,

Açayım diyorum açamıyorum.

Deselerki bana kalemin var mı,? 

Hasretini çektiğin seni sarar mı,? 

Şair dediğin kişi işe yarar mı,? 

Yazayım diyorum yazamıyorum.

Dosta anlatmaya dilim yetmiyor,

Dünyanın çilesi derdi bitmiyor,

Sazı aldım teli düzen tutmuyor,

Çalayım diyorum çalamıyorum.

Şair Koç Ozan''ım dedim halimi,

Divanda veririm her vebalimi,

Kimseye kalmasın ben mezarımı,

Kazayım diyorum kazamıyorum.', 'Çağırıyor beni uzaktan bir ses, Varayım diyorum varamıyorum, Sevdamı koymak için altından kafes, Alayım diyorum alamıyorum. Aşkım için yola ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sairin-derdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Beraat...(Manzum Öykü)', 'ask-beraat-manzum-oyku-naime-erlacin-7gklx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'karmaşa şölenlerin bezgin dervişi

paslı gemiler yaktı bir gece vakti

savurdu tenine biriken hırpani döşeği

papatya ekti zarflara

eskimiş adaklar ödendi ruh tutsaklığında

kim bilir kaç kerre yazıldı diller! 

gecenin koynuna kaç damla yaş indi

kaç kerre sil baştan edildi kader

yol yorgunuydu derviş

aşk yorgunu

doğmayan şafaklar emzirir hüznünde

zemheride bir kardelen özlerdi

usuldan bir isyan 

tutkulu ve dik başlı

acının içinden yükseldi sessizce

gurup vakti canlandı ateş

‘sevda’ya yazıldı yeniden hüviyet 

bilmezdi oysa 

vadesi yetmemiş doğum sancılarında solarken yürek

dayancın müminleri semaha durur da içinde

sadakat bekçisi bir kadın 

onu zindanda beklerdi

an geldi 

bir kıvılcım çaktı gök tanrı

çekildi ağır perde 

kamaştı gözler

dolunay indi kadının dizlerine

gece kendine gitti

sanık: aşk

davacı:kayıp

tanık: namevcut

aşk: beraat! 

dosya kapandı 

duruşma bitti

(20 Haziran 2004)', 'karmaşa şölenlerin bezgin dervişi paslı gemiler yaktı bir gece vakti savurdu tenine biriken hırpani döşeği papatya ekti zarflara eskimiş ada...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ask-beraat-manzum-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat', 'anlat-huseyin-demirbilek-ce529', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bana bende ki seni anlat,

yüzünün güzelliğini,

sesinin dinginliğini değil; 

yüreğimde ki seni anlat...

içimde ki sızımı

uzakta ki ağrımı 

sessiz çığlıklarımı

bitmeyen yolumu anlat...

anlat  bana  sevgili,

yüreğimde ki seni anlat.

anlat ki gözümümün yaşını sileyim

yüreğimin acısını hafifleteyim...

(İstanbul 17/06/2004)', 'bana bende ki seni anlat, yüzünün güzelliğini, sesinin dinginliğini değil;  yüreğimde ki seni anlat... içimde ki sızımı uzakta ki ağrımı  se...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Demirbilek']::text[], 8.5, '{"poet":"Hüseyin Demirbilek","poet_slug":"huseyin-demirbilek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anlat-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-hikmet-yakisir-fc5ow', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlkyazın ilk günlerinden biri.

Fırtınalı bir gün,

Lodos deli esiyor.

Kırıyor, deviriyor

Uçuruyor, savuruyor,

İnsanları, aşkları sevgileri,

Ağaçları, dalları yaprakları,

Gülleri, dikenleri.

Katmış önüne sürüklüyor

Dünyanın sonu gelmiş sanki.

Ardından bulutlar başlıyor ağlamaya

Kırılıp devrilen çınarlara

Yürekleri parçalanmış sevdalara

Batsa da dikenleri, gonca güllere

Hüzünlü bir yağmur yağıyor

Yürekleri dağlıyor

Gözler görmüyor perdeler inmiş.

Deli lodos suskun fırtına dinmiş

Ama dinmeyen bir fırtına var ki 

İçimde sana karşı

Ne deli lodosa, 

Ne tayfuna benzer.

Bu fırtına koparsa eyer

Her şeyi ezerde geçer

Söyle gözlerine can, sevecen baksın

Bakışların üzerime aksın

Gözbebeklerinde dinsin

İçimdeki fırtına.

18 Haziran 2004', 'İlkyazın ilk günlerinden biri. Fırtınalı bir gün, Lodos deli esiyor. Kırıyor, deviriyor Uçuruyor, savuruyor, İnsanları, aşkları sevgileri, A...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/firtina-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Gaziantepli bestekar-şair Erol Güngör şiiri', 'su-gaziantepli-bestekar-sair-erol-gungor-siiri-erol-gungor-hb3g9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen sevgi denizinde, beni dolaştıran su

En temiz ırmaklardan, okyanusa akan su

Kana kana içtiğim, pınar başındaki su

Her sabah kahvaltıda, demli çayımdaki su.

Sen yağan yağmurdaki, çöle hayat veren su

Yaz ve kış meyvelerde, vitaminli tatlı su

Her yerde ateşleri, yangını söndüren su

Yüzümü serinleten, saçımı ıslatan su.

Sen her gün bana yeten, güzelim bir içim su

Sesinde yaşadığım, sevindiğim eşsiz su

Çatlayan dudağıma, dokunmadan geçen su

Gözlerimden düşmeyen, bir damla gözyaşı, su...', 'Sen sevgi denizinde, beni dolaştıran su En temiz ırmaklardan, okyanusa akan su Kana kana içtiğim, pınar başındaki su Her sabah kahvaltıda, d...', ARRAY['Türk Edebiyatı','Şiir','Erol Güngör']::text[], 8.5, '{"poet":"Erol Güngör","poet_slug":"erol-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/su-gaziantepli-bestekar-sair-erol-gungor-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-yusuf-koc-b5ofm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kocaman sevdalara kocaman yürekler gereklidir..

Gece rüyamda gördüm ben seni,

o gurur elbisesine bürünmüştün..

Süleyman''ın tacı vardı başında,

kraliçe edasıyla tahta,

hükümler verir gibi oturmuştun..! 

     ama neden gözlerinde yaş vardı,

     belki de eceliğin bana kadardı..! 

Gece seni izledim yakamozlarda,

yarı insan..yarı balık..başın dikti...

o parlak ışıkların üzerindeydin,

bilmem hangi sevdalarda.. nerelerdeydin..! 

     ama neden hüzünle bakıyordu gözlerin,

     hazan mı geldi..? bitti mi yazların...

Gece pencerende gördüm ben seni,

yıldızlarla konuşuyordun sanki...

duaya kalkmış gibiydi ellerin,

soğuk üşütemiyordu seni,

bir şey arar gibiydi gözlerin..! 

     ama neden büzülmüştü dudağın,

     dikendi değil mi..? .. bensiz yatağın..! 

Gece gördüm ben seni,

rüyamda  yakamozlarda pencerende,,,

her gece gördüğüm gibi.! !', 'Kocaman sevdalara kocaman yürekler gereklidir.. Gece rüyamda gördüm ben seni, o gurur elbisesine bürünmüştün.. Süleyman''ın tacı vardı başınd...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gece-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara', 'yara-bunyamin-aslan-q9kkh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir bahar arefesinde 

Yitirdiğim umutları topluyorken

Şafağa kan değdi

Bir yaralı serçe sığındı yüreğime

Sahralarda yorulmuş

Sahralarda vurulmuş

Kırıktı kanadı

Kırk yerinden bölük

Gözlerinde korku

Serçe dünyadan habersiz,masum

Ellerinde silah

Yüzlerce el

Yeni bir dünya kurmak adına

Koca bir yalan

Namluda adalet

Namluda sefalet

Bu nasıl tezat

Sefaletin asaleti

Asaletin sefaleti

Hangi dala onayım

Kime sığınayım

Her yanı alev aldı

Göçe durayım

Yaşamak ölmekten zor

Gitmek kalmaktan zor

Öyle bir zordayım ki

Zoru tarif etmek zor

Kerbelada kan var

Kerbelada talan

Hasanlar masum,Hüseyinler

Yezidlere kaldı meydan

Nerdesin Uluçınar

Nerdesin Genç Osman

Kanatlarımda yük ağır

Yüreğimde yara ağır

Sesime ses verenim yok

Yer sağır gök sağır

Varsın sağır olsun yer gök

Varsın sağır olsun insan 

Ebabillerin isyanın çağır', 'Bir bahar arefesinde  Yitirdiğim umutları topluyorken Şafağa kan değdi Bir yaralı serçe sığındı yüreğime Sahralarda yorulmuş Sahralarda vuru...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yara-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağır Dünya', 'sagir-dunya-bunyamin-aslan-e8qol', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüzüne baktığım aynalar kırk	

Derdimi yandığım duvarlar sağır

Ruhunu ruhuma vurmuş yalnızlık

Ağlasam sesimi duyarlar sağır

Yer sağır,gök sağır,yarda dil sağır

Kalem yazmaz oldu yazan el sağır

Boşuna konuşma bülbül gül sağır

Mevsimler hazan baharlar sağır

Nereye gidersen kader seninle

Sükutun sesini ruhumda dile

Felek kaderinle,yüzleş kendinle

Gurbet mi sıla mı diyarlar sağır', 'Yüzüne baktığım aynalar kırk	 Derdimi yandığım duvarlar sağır Ruhunu ruhuma vurmuş yalnızlık Ağlasam sesimi duyarlar sağır Yer sağır,gök sağ...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Aslan']::text[], 8.5, '{"poet":"Bünyamin Aslan","poet_slug":"bunyamin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sagir-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşlendin', 'i-slendin-halil-kalay-5p4xn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kayalara işlenen tarihi sözler gibi,

Yada çinilere işlenmiş karmaşık desenler gibi,

İşledim, sonsuzca yüreğime

Aşkın yüceliğini,

Yeterli mi SEVĞİLİM!', 'Kayalara işlenen tarihi sözler gibi, Yada çinilere işlenmiş karmaşık desenler gibi, İşledim, sonsuzca yüreğime Aşkın yüceliğini, Yeterli mi ...', ARRAY['Türk Edebiyatı','Şiir','Halil Kalay']::text[], 8.5, '{"poet":"Halil Kalay","poet_slug":"halil-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/islendin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadın Tanıdım', 'bir-kadin-tanidim-halil-kalay-kv9pq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kadın tanıdım 

Tanıdıkça sevmeye başladım

Sevilmesi gerektiği o

	sevimli ruhunu.

Onu düşündüm

Gece ve gündüz

Arasındaki zamanlarda.

Oda beni düşündü

Onu düşündüğüm kadar

Sevdi bu yalnız adamın 

Boşlukta gezen varlığını.', 'Bir kadın tanıdım  Tanıdıkça sevmeye başladım Sevilmesi gerektiği o 	sevimli ruhunu. Onu düşündüm Gece ve gündüz Arasındaki zamanlarda. Oda ...', ARRAY['Türk Edebiyatı','Şiir','Halil Kalay']::text[], 8.5, '{"poet":"Halil Kalay","poet_slug":"halil-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-kadin-tanidim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülmeyi Unuttum', 'gulmeyi-unuttum-halil-kalay-gbc83', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçmişteki sırlarım gün yüzüne

Vurunca 

Kaçışan bulutlar gibi

Koşan rüzgarlar gibi 

Yürüyen ay gibi

Doğan güneş gibi

Doğmadım doğan herkes gibi

Geleceğin düşlerinde.', 'Geçmişteki sırlarım gün yüzüne Vurunca  Kaçışan bulutlar gibi Koşan rüzgarlar gibi  Yürüyen ay gibi Doğan güneş gibi Doğmadım doğan herkes g...', ARRAY['Türk Edebiyatı','Şiir','Halil Kalay']::text[], 8.5, '{"poet":"Halil Kalay","poet_slug":"halil-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gulmeyi-unuttum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamam', 'anlatamam-huseyin-demirbilek-9m9zo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'paramparça olmuş bir bütündür

bedenim,

gözüm dalar,yüreğim yanar.

hıncahıç dolar taşar içim...

bir türlü anlatamam yalnızlığımı

yani sensizliğimi..

hayatta ki tek itirazımdır sensizlik

volkan misali sarar

bütün bedenimi,

kavrulur kavrulur kavrulurm...

ama,

bir türlü anlatamaz olurum yalnızlığımı,

yani sensizliğimi...', 'paramparça olmuş bir bütündür bedenim, gözüm dalar,yüreğim yanar. hıncahıç dolar taşar içim... bir türlü anlatamam yalnızlığımı yani sensizl...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Demirbilek']::text[], 8.5, '{"poet":"Hüseyin Demirbilek","poet_slug":"huseyin-demirbilek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anlatamam-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlara Bir Gülüş Kat Turuncu', 'umutlara-bir-gulus-kat-turuncu-adnan-durmaz-fct7x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'afrodit köpüklü tül kıyılarda

ay çıldırtan şarkılar söylerdi denizkızları

ah ömrünün savrulan yazları

bombalar-katliamlar

tarumar güllerin tarihi yazılmış yüreğine

ömrünün özeti dikenli teller

bütün işgallerden sonra

örerek gergefinde gülümsemeyi

yine de yürümek

düşe kalka kanlı bir patikada

ve gülüşünde tomur tomur

bir şafak söktürmek yeniden

tepeden tırnağa turuncu

ah her yerde

bir gurbet olmuş da yaşam

gönlüne bukağılar vurmuşsun

katran karanlığı basmış içini

bir tek mumla avunmuşsun

bırakmışsın beklemeyi

vazgeçmişsin özlemekten

kapatmışsın sevdalara kapını

kimi zaman

gizli bir çay akmış 

yaralı düşlerinden

gönlünün tek avuncu

yalnızlığa diz çökmüşsün

nice yapraklar dökmüşsün

turuncu

sizin oralarda da yalnızlık

benzer mi al güllere

aşksız gece daralır mı 

içinin çöllerinde rahvan kederler

umut kervanları yağmalanır mı

alıcı kuşlar parçalar mı serçe sevinçlerini

gözlerin yurtsuz dalar mı

ellerin kalakalır mı

gülüşün yamalanır mı

içinden uzaklara kaçmak gelir mi

derdini kimse bilir mi

bütün bunlar

çekilir mi

turuncu

ne zaman ipekten dalgalarda

kuğu süzülüşlü bir kayık görsen

kıyıya atılmış eski bir kayık

gibi yorgun

gibi kırgın

umutsuz

bulur musun kendini yaşamın ortasında

hep kırılmış fırtınada

ve artık sevdalar

olmayacak hayatında

yaşamak bir

çürüyüşler denizi

ve silinir gül gülüşün

turuncu

ıslak çimenler üzerinde

koşan taylar gibi

ayışığında yayılan

ırgat şarkıları gibi sevdalı şeyler düşünmek

uyumak başak kokan bir gecede yıldızları örtünerek

düşler

ki acı bir gülüştür yürekte

yalan bir öpüştür

oysa bilmelisin dikenli teller

paslanıp kırılır zamanda

ve şimdi fırtınalar 

ömrünü yağmalamakta

ama bir yerlerde

gülşafaklar doğmakta

uyan acıların dikenli uykusundan

ne varsa hayatında pas tutan

kopart ve fırlat

kalk ayağa

umutlara

bir gülüş kat

turuncu

								Aralık 2001

adnan durmaz,bilirsin aşk da serseri,art yay,ank,2003', 'afrodit köpüklü tül kıyılarda ay çıldırtan şarkılar söylerdi denizkızları ah ömrünün savrulan yazları bombalar-katliamlar tarumar güllerin t...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/umutlara-bir-gulus-kat-turuncu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuk', 'konuk-yavuz-turhan-3yz7f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akşam yeliydin,

Mazgal aralarından saçlarımı okşayan.

Uykumda sarıldığım yastığımdın.

Düşlerimi böldürmedim saatlere.

Ve sabahları uyanmadım.

Kısa sürmememliydi konukluğun,

Sevgini ağırladığım yüreğimde...', 'Akşam yeliydin, Mazgal aralarından saçlarımı okşayan. Uykumda sarıldığım yastığımdın. Düşlerimi böldürmedim saatlere. Ve sabahları uyanmadım...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/konuk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tırnak İçinde', 'tirnak-i-cinde-aynur-uluc-b4ksz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akar hayattan süzme

Kareler kalır bazen

Görünmez bir kalem geçirir

Sevdanın paklığını

Kâğıdın aklığına 

İki tel arasında

Sihir olur sözcükler

Fincan okyanus olur 

Her kulaca bir harf düşer 

Zıt yönlere uçar zaman 

Alır başını gidersin 

Yazdığın masallara', 'Akar hayattan süzme Kareler kalır bazen Görünmez bir kalem geçirir Sevdanın paklığını Kâğıdın aklığına  İki tel arasında Sihir olur sözcükle...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tirnak-icinde-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelirim Sana', 'gelirim-sana-ozkan-yildirim-hr6gc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günün yorgunluğundan bakarım.

Gecede, resimler çizerim.

Bir şehir uykuya dalar...

Rüyada dost`lar görülür

El-ayak çekilmiş geceden,

/bir adam uyanır…

Gözlerine yıldızlar  düşer.

Sabırla, tan atımı  beklerim.

Gün, ışın`larıyla  ten de yanmadan,

ilk ışıklarıyla gün`e dalarım.

Bir şehir uyanmadan,

Uyku gözlerinden uçmadan,

Gece`den resimleri,

Rüya`dan dost`ları,

Şiir`den dizeleri,

Gün`den ışıkları,

alırim yanıma

Gelirim sana, 

Merhaba, sevgili.

Sevgili, merhaba

……………………………….

……………………………..', 'Günün yorgunluğundan bakarım. Gecede, resimler çizerim. Bir şehir uykuya dalar... Rüyada dost`lar görülür El-ayak çekilmiş geceden, /bir ada...', ARRAY['Türk Edebiyatı','Şiir','Özkan Yıldırım']::text[], 8.5, '{"poet":"Özkan Yıldırım","poet_slug":"ozkan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gelirim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Aşka Düşünce', 'gonul-aska-dusunce-i-smet-barlioglu-z0i2o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdalar çelenk çelenk,

Buseler ahenk ahenk,

Tüm rüyalar rengarenk

Gönül aşka düşünce.

Kesilir akan sular,

Kırılır yende kollar,

Haram olur uykular,

Gönül aşka düşünce.

Dolar bomboş çerçeve,

Hayal üşüşür eve,

Düşer yürek aleve

Gönül aşka düşünce.

Mal mülk olur bir para,

Dert olur sıra sıra,

Azap döner yağmura

Gönül aşka düşünce.

Balla zehir eş olur,

Tüm gerçekler düş olur,

Yanaklar yaş yaş olur

Gönül aşka düşünce.

Ateş düşer ocağa,

Yakın gider ırağa,

Yastık batar yanağa

Gönül aşka düşünce.

Geceler sabahsızdır,

Mahşer bile ıssızdır,

Yürekler uykusuzdur

Gönül aşka düşünce.

Özlemler kaderleşir,

Üzüntü katmerleşir,

Vuslatlar tembelleşir

Gönül aşka düşünce.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 35-36/100)', 'Sevdalar çelenk çelenk, Buseler ahenk ahenk, Tüm rüyalar rengarenk Gönül aşka düşünce. Kesilir akan sular, Kırılır yende kollar, Haram olur ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gonul-aska-dusunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var mı?', 'var-mi-i-smet-barlioglu-ju8bf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boş çerçeve önünde hüngür hüngür ağlayıp

Benim gibi uykusuz sabah ettiğin var mı? 

Yaşları damla damla birbirine bağlayıp

Benim gibi uykusuz sabah ettiğin var mı? 

Boş odalar içinde hayallerle buluşup

Bir yürekten dost gibi yalnızlıkla kaynaşıp

Karanlıkla, soğukla, duvarlarla konuşup

Benim gibi uykusuz sabah ettiğin var mı? 

İsyan etti mi elin en sevdiğin işinde? 

Yoruldu mu kalbin hiç bir hayalin peşinde? 

Ipıslak gözlerinle bir masanın başında

Benim gibi uykusuz sabah ettiğin var mı? 

Oldu mu hiç ettiğin her solukta bir yemin? 

Yarin için kalktı mı duaya hiç ellerin? 

Seni yerden yerlere hiç vurdu mu kaderin? 

Benim gibi uykusuz sabah ettiğin var mı? 

Gece boyu sadece sevgilini anarak

Sönmeyen külhan gibi alev alev yanarak,

Çilelerle, azapla sarmaş dolaş olarak

Benim gibi uykusuz sabah ettiğin var mı? 

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 37-38/100)', 'Boş çerçeve önünde hüngür hüngür ağlayıp Benim gibi uykusuz sabah ettiğin var mı?  Yaşları damla damla birbirine bağlayıp Benim gibi uykusuz...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/var-mi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çileler Kervanı', 'cileler-kervani-i-smet-barlioglu-txvya', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelme dedin, gelmedim,

Görme dedin, görmedim,

Sabretmeyi öğrendim

Çileler kervanında.

Geceler görünmedi,

Gündüzler tükenmedi,

Yürüdüm, yol bitmedi

Çileler kervanında.

Varlığım seraplaştı,

Özlemim şaraplaştı,

Kalbim kumla savaştı

Çileler kervanında.

Çırpındım umutsuzca,

Yol teptim hudutsuzca,

Ağladım şuursuzca

Çileler kervanında.

Bir kaybolan mendilsin,

Sönmeyen bir kandilsin,

Varılmayan menzilsin

Çileler kervanında.

(MELEKLEŞMİR MERMERLER isimli hece şiirlerinden > 39-40/100)', 'Gelme dedin, gelmedim, Görme dedin, görmedim, Sabretmeyi öğrendim Çileler kervanında. Geceler görünmedi, Gündüzler tükenmedi, Yürüdüm, yol b...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cileler-kervani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Bana Güneşle', 'gel-bana-gunesle-i-smet-barlioglu-00ahp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel bana güneşle, yağmurla gelme,

Çünkü gözyaşların gizli yağmurda.

Bekle, gözündeki yaşların dinsin,

Sen sonra yola çık, şimdilik dur da.

Ben seni çileler için sevmedim,

Sırf gülesin diye ömrümü verdim,

Ben seni gülerken görüp beğendim,

Yine gülümsersin zaman olur da.

Gülümse içinden, ta yüreğinden,

Gülümse gönlünün derinliğinden,

İnan ki volkanlar kaynar içinden

Rüzgar gibi geçen zaman durur da.

Gül, sular içinde nilüfer gibi,

Gül, bir bağ içinden yel eser gibi,

Gül, bir mutluluğu çok ister gibi,

İnsan mutluluğu öyle bulur da.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 41-42/100)', 'Gel bana güneşle, yağmurla gelme, Çünkü gözyaşların gizli yağmurda. Bekle, gözündeki yaşların dinsin, Sen sonra yola çık, şimdilik dur da. B...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-bana-gunesle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kerecik Söyle', 'bir-kerecik-soyle-gokhan-karaduman-1me45', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidiyorum bu gece

Geri dönmeyebilirim

İstersen yine kız sen

Son kez söyleyeceğim.

Otobüsüm kalkıyor Beş de

Yüreğim senin ellerinde

Biliyorum seviyorsun

Hadi bir kerecik söyle.

Seviyorum bak seni

Hem deli, divane gibi

Bir kerecik söylesen

Coşacağım seller gibi

Gidiyorum bu gece

Seni alarak içime

Bak kanıyor yüreğim

Hadi bir kerecik söyle', 'Gidiyorum bu gece Geri dönmeyebilirim İstersen yine kız sen Son kez söyleyeceğim. Otobüsüm kalkıyor Beş de Yüreğim senin ellerinde Biliyorum...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-kerecik-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yayla Ağası Babam', 'yayla-agasi-babam-ali-kilic-kakiz-ol3hx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'azi Osman paşa erenler yurdu.

Babam yaylara azmı çadır kurdu.

Uğradıkça Ali paşada namaza durdu.

Patlıcan kebabı meşhur güzel Tokat.



Yakın mı yakın çal yaylası, girap obası.

Gürgen ağacından kara çadır kapısı.

Altı direk tek göz, yoktur hayatı odası.

Çadırlar altında çileler çeken anam.



Geçip gitti yıllar sen hep ağladın.

Derdine derman aradın bulamadın.

Islak çadırlar altında ağardı sacın.

Yaylaların nazlı çiceği canım anam.



Keçi kılından beyaz maşlak abam.

Yokmudur benim gayret ve çabam.

Yayla ağası benim canım babam

Boyralı pınardan az mı soğuk su içtin.



Amasya / Aydınca 1971', 'azi Osman paşa erenler yurdu. Babam yaylara azmı çadır kurdu. Uğradıkça Ali paşada namaza durdu. Patlıcan kebabı meşhur güzel Tokat. Yakın m...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yayla-agasi-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Gönülden Yâre', 'gonulden-y-re-sair-ahrazi-jcibx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün haber gelmezse,benim mecnûn hâlimden

Bil ki hâlâ mecnûnum henüz geçtim ölümden.

***', 'Bir gün haber gelmezse,benim mecnûn hâlimden Bil ki hâlâ mecnûnum henüz geçtim ölümden. ***...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gonulden-yare-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-mehmet-luciin-3dydi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gündüzlerim gece oldu gülüm. 

Ölümüm, sevdâm ölünce oldu.

Sana, dünü düşünüp de anmak, 

bana aşk, sevdânla yanmak oldu. 

Fikirlerim, ince oldu gülüm. 

Sensizliğim bana düşünce oldu. 

En mutlu günüm, sen gülünce oldu. 

Sen gülünce ay oldu, yıldız oldu, gün oldu. 

Zülfün, gönlüme kement, gözlerim hasrete sürgün oldu. 

Yıllar, muallakta kaybolup tek gün oldu. 

Bana anlamak düştü gülümmmm! 

Dudaklarım dudaklarınla nasıl öpüştü. 

Yüreğime sorsan, bir yerlerde kuşlar havalanıp ötüştü. 

Aklıma sorsan,yalnızca bir anlık bir düştü! 

Yazgımızı hasret bölüştü gülümmm! 

Katre deyince, sinemize bir sızı düştü! 

Gönlümüze hüzünler hazzı düştü. 

Kurşun, en ince yerden vurdu sineyi; Ozan düştü, sazı düştü! 

Dertler bile eğlence oldu gülüm. 

Sensizlik, gönlüme kara bir pençe oldu. 

Düğün oldu, meclis oldu, ölüm oldu. 

Bir kerecik aklım almadı gülüm,

Etrâfımda dönen dünyâ, yaşadığın gönlüme sığmadı! 

Göz pınarlarımı sele verdiğinde, gayrı aleme başka yağmur yağmadı. 

Bir yan bakışınla, ne silaha itibar kaldı ne dar ağacına bir lüzum... 

Adın türkülerde ah le yâr kaldı. 

Bu yürek, senle olmaktan bahtiyâr kaldı. 

Sanma sevdâm hiç söndü gülümmm, sanma bir tel bile eksildi hasretinden! 

Saçlarıma aksi karlar düşünce oldu. 

Zaman, çizgisini yitirdi gülümmm; ne sonra, ne önce oldu. 

An bitti, hicrân bitmedi! 

Bütün güller soldu da şu gönlümdeki o gül hiç solmadı. 

Hüznüm, bahâra dönüştü gülümmm, kuşlar öttü bağımda, 

yemyeşil çimenleri papatyalar örttü. 

Bembeyaz atlar salındı vadime. 

Ne vaadine bir sitem, ne bir vuslat hayâline. 

Beni bir mecnûn hâline bir öpüşün itti gülümmmm! 

Kahkaha demlerinde kalbime bir dolu kân düştü. 

Râkîbe gül vuslatın, bana görgüsüz bir hicrân düştü. 

Bülbüle gurbeti kendi özü âşiyân düştü. 

Hancı düştü han düştü. 

Yeminlerimiz, yazgıya neden yalancı düştü! ! ! 

Dün tek yürek iki sevgili, bugün nasıl iki yabancı düştü? ? 

Sitem değil hâl yâr. Kelam değil kâl yâr. 

Kalemimi kırsan ne var; merhametin gönlüme savcı düştü! 

Bu aşk vadisinde, Ceylan vurdu avcı düştü

Sormayana ne bir tek taş

Sorana vuslatın bin dârağacı düştü gülümmm! 

Vuslat hânemize sen öldün, binnn acı düştü', 'Gündüzlerim gece oldu gülüm.  Ölümüm, sevdâm ölünce oldu. Sana, dünü düşünüp de anmak,  bana aşk, sevdânla yanmak oldu.  Fikirlerim, ince ol...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Luciin']::text[], 8.5, '{"poet":"Mehmet Luciin","poet_slug":"mehmet-luciin","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/gulum-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkında Olmamak...!', 'farkinda-olmamak-serkan-aslan-d85vz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen yıldızları süpürürsün farkında olmadan,

Koca bir orkestra kuruludur kucağında,

Duymazsın...

Bir çocuk gözlerinin içine bakar,

Arkan dönüktür....

Yalnızlıktır yaşamakta olduğun,

Farkında olmazsın...!', 'Bazen yıldızları süpürürsün farkında olmadan, Koca bir orkestra kuruludur kucağında, Duymazsın... Bir çocuk gözlerinin içine bakar, Arkan dö...', ARRAY['Türk Edebiyatı','Şiir','Serkan Aslan']::text[], 8.5, '{"poet":"Serkan Aslan","poet_slug":"serkan-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/farkinda-olmamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğin ertesinde....', 'sensizligin-ertesinde-serkan-aslan-q0mzb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Böyle deli güldüğüme bakma,

Kokunun huzurunda olsa da yüreğim,

Korkusu hiç bitmiyor; 

Ellerini ellerimden, gözlerini gözlerimden 

Amansızca ayıran gidişinin....

Ne zaman dalsam gözlerinin derinliğine,

Mabedim oluyor.

Sonrasında duygularımın aynası,

Şiirler.....

Yine sensizliğin ertesindeyim,

Yine mübtelasındayım gözlerinin....', 'Böyle deli güldüğüme bakma, Kokunun huzurunda olsa da yüreğim, Korkusu hiç bitmiyor;  Ellerini ellerimden, gözlerini gözlerimden  Amansızca ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Aslan']::text[], 8.5, '{"poet":"Serkan Aslan","poet_slug":"serkan-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensizligin-ertesinde-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Gözlerimi', 'al-gozlerimi-ayca-tekin-denp9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen sazımın tellerinden süzülüp uçuşan sevgili,

al gözlerimi,yağmurlu sabahlara bırak..

koşarak geçsin bulutları bir anda sesim,

yenik düşmeyecek bu sefer, devrilmeyecek nefesim! ..

bu benim gölgelenen elim, 

kentin yüreğine çarpıp susacak..

bakacak susmadan önce çöken evlerine günlerinin..

eriyen bahçesine  düşen,

kanı donmuş küçük bir dal; 

yolunu çizip gülecek,

geceyi yaran o sımsıcak hayal...

al gözlerimi,yağmurlu duraklara bırak.

bir yer olacak bu son otobüste..

bulamaz beni artık,

saçlarımı çeken rüzgar...

sokak lambaları konuşmaz bu deniz akşamında,

kaçar tüm kıyılar konuşmaz... 

ateşler saçarak aydınlığa uçuşan sevgili,

al gözlerimi bırakma,

sakın bırakma...

(alanya haziran 2004)', 'sen sazımın tellerinden süzülüp uçuşan sevgili, al gözlerimi,yağmurlu sabahlara bırak.. koşarak geçsin bulutları bir anda sesim, yenik düşme...', ARRAY['Türk Edebiyatı','Şiir','Ayça Tekin']::text[], 8.5, '{"poet":"Ayça Tekin","poet_slug":"ayca-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/al-gozlerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-ahmet-aksoy-u61ex', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'avazı çıktığı kadar bağıran gün

.......gül ortasında sevişen arılar

kimbilir kaç koza yarılmıştır 

..........................bugün

tabiatın iç huzuru bahar', 'avazı çıktığı kadar bağıran gün .......gül ortasında sevişen arılar kimbilir kaç koza yarılmıştır  ..........................bugün tabiatın ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bahar-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlaya..bilene! ..', 'anlaya-bilene-bulend-b-ki-yjgl3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mürüvvet gösterse zalimin zulmü,

Yalana baş eğer alimin ilmi.

Şu susan bülbül mü, ağlayan gülmü? 

Anlayamadım! .. 

Dilden kalbe geçmez Hakk`ın kelamı, 

Dostluğa yetişmez kulun selamı,

Ölüm kurtuluş mu, yoksa bela`mı? 

Anlayamadım! .. 

Sözler yalan dolu, namazlar riya,

Batıya satılır ar, namus, haya,

Yıllarla boğuştum anlarım diye! 

Anlayamadım! .. 

Bir başıma koşsam yolum bağlıdır, 

Mürşidsiz kanadım kolum bağlıdır,

Her zerre HAKK der de dilim bağlıdır,

Anlayamadım! .. 

Bir daha dünyaya gelmeyi umma,

Yaşamak kördüğüm, Ölmek muamma. 

Bu işin içinde, bir iş var amma! 

Anlayamadım! ..', 'Mürüvvet gösterse zalimin zulmü, Yalana baş eğer alimin ilmi. Şu susan bülbül mü, ağlayan gülmü?  Anlayamadım! ..  Dilden kalbe geçmez Hakk`...', ARRAY['Türk Edebiyatı','Şiir','Bülend Bâki']::text[], 8.5, '{"poet":"Bülend Bâki","poet_slug":"bulend-b-ki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anlaya-bilene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '~~DEMİR BEYiNLİ ÇOCUKLAR~~', 'demi-r-beyinli-cocuklar-mehmet-kizilay-z4bz2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vurup zamanı 

alnının ortayerinden

atmalıyım..bir meçhule

dingin bedenini.

nikah tazelemeyeceğim onunla

acı adında, gurbet gurbet bakışlı,

kısık gözlü ve de 

demir beyinli çocuklar

doğurmasın diye.

sarmayıp, sarmalamayıp

tek talakla boşayacağım O''nu.

Ağlamayı da boşayacağım..

nafaka diye vicdan ödeyerek

Artık.. almayacağım koynuma

öpmeyeceğim

gece renkli dudaklarından.

Kimseye öptürmesin,

kimsenin koynuna girip

yakmasın diye,

yüreğimden aldığım kuvveti

vererek yumruğuma..

göstreceğim

sıkıca sıkılmış yumruğumu.

zorlayacağım O''nu

....intihara../..ölüme.', 'Vurup zamanı  alnının ortayerinden atmalıyım..bir meçhule dingin bedenini. nikah tazelemeyeceğim onunla acı adında, gurbet gurbet bakışlı, k...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/demir-beyinli-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-i-hsan-dinibutun-d20pi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Başladı yine sessiz senfonisi hüznün

Duymuyor şarkısını güller Bülbül''ün

Eserken usulca rüzgarı sonbaharın

Kutluyor yapraklar gelişini Eylül''ün', 'Başladı yine sessiz senfonisi hüznün Duymuyor şarkısını güller Bülbül''ün Eserken usulca rüzgarı sonbaharın Kutluyor yapraklar gelişini Eylül...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/eylul-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdaya dair', 'sevdaya-dair-mehmet-fatih-px0hm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''''Hayat bir sınavdır zaten - dediler

birini açıp diğerini kapadığın muamma...''''

ve yemin olsun / and olsun

bir sevda

binbir eziyetten evladır

öyle ya! 

kaç umudun yakasında gül vardır...', '''''Hayat bir sınavdır zaten - dediler birini açıp diğerini kapadığın muamma...'''' ve yemin olsun / and olsun bir sevda binbir eziyetten evladı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevdaya-dair-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Si Bemol', 'si-bemol-mehmet-fatih-3ud51', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1

Si Bemol

Hayat

ucu kırılmış yarım vuruşluk bir sestir

incinen yakınan ağlayan

ve duyulmayan ve

onursuzca bir sefalete mahkum bırakılan ses...

si bemol

noktasına, virgülüne dek süreğen ırmaklar

yolculuklara hasret yolculardır

/yolculara hasret yolculuklardır/

-bir bilet lütfen... uzağa olsun

evet evet doğru anlıyorsunuz

uzağa/anlatılması çok güç yanlarıyla

/bu şehirden.../

2 nakarat

si bemol tekrar

/ve tekrar hayat../

-orası uzak mıydı çok? 

-burası sonsuzluğa gülümseyen

bir nakarat

3

si bemol

mıntıka temizliği, eylül, bu bahar

''''-ne var? 

-hayır biryerlerde rastladınız mı hayata diye sorarlar''''

öyleyse

la minör, la minör

ve si bemol tekrar', '1 Si Bemol Hayat ucu kırılmış yarım vuruşluk bir sestir incinen yakınan ağlayan ve duyulmayan ve onursuzca bir sefalete mahkum bırakılan ses...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/si-bemol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrık II', 'ayrik-ii-ahmet-aksoy-4badc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gençliğin dimağında hayal meyal hatıra/lar

kollarında taşınmazları hayatın

boş bir vagon gibi sallanan yol/lar

..........avuçlarında zamanın dikenleri

yedeğinde başkalarının hayatlarının beyannamesi

sınırın kıyısındaki gümrük evi var/dın

........yok edercesine kendini', 'gençliğin dimağında hayal meyal hatıra/lar kollarında taşınmazları hayatın boş bir vagon gibi sallanan yol/lar ..........avuçlarında zamanın...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ayrik-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümitsiz Aşk...', 'umitsiz-ask-i-brahim-ethem-bingul-qeixc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ümidim yok senin aşkından

Hiç bir şey anlamadım bu sevdadan

Bir varsın,bir yoksun neredesin...

Zaten çok şey beklemiyorum senin aşkından

Çocukça kaprisler,kıskanmalar

Biz delikanlıyız anlamaz insanlar

Söz ağızdan çıkar geri dönmeyiz

Gönlümüze başka sevda sokmayız

Bitti dersen seni anlarım

Başımı alır giderim

Yazık olur senli anlarıma

Seni senle bırakır çeker giderim

www.iebingul.com', 'Ümidim yok senin aşkından Hiç bir şey anlamadım bu sevdadan Bir varsın,bir yoksun neredesin... Zaten çok şey beklemiyorum senin aşkından Çoc...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umitsiz-ask-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşün Ruhuma Çiçek Açtırdı', 'gulusun-ruhuma-cicek-actirdi-sadik-softa-c7j5v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sesin kulağıma geldiği zaman,

Gülüşün ruhuma çiçek açtırdı.

Öyle bir sardı ki kalbe uzanan,

Gülüşün ruhuma çiçek açtırdı.

Duyarak öylece tüm nefesini,

Toplamışken özlemlerin hepsini

Dinledim çınlayan narin sesini,

Gülüşün ruhuma çiçek açtırdı.

Sesin ne kadar da gelse uzaktan 

Ahu gözlerinden,gülen yanaktan 

Gül gül açıldıkça,gülen dudaktan

Gülüşün ruhuma çiçek açtırdı.

Vuslat mesafeye  yenik düşeli,

Yüreğim kavrulup,yanıp pişeli,

Hasret kucağıma  gelip düşeli,

Gülüşün ruhuma çiçek açtırdı.

Ruha ilaç olup  yaradığısın,

Gönlümün ısrarla aradığısın,

Cihan cihan gezip taradığısın,

Gülüşün ruhuma çiçek açtırdı.

Çankırı-18.06.2004', 'Sesin kulağıma geldiği zaman, Gülüşün ruhuma çiçek açtırdı. Öyle bir sardı ki kalbe uzanan, Gülüşün ruhuma çiçek açtırdı. Duyarak öylece tüm...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gulusun-ruhuma-cicek-actirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir GICIK Olarak! ....', 'bir-gicik-olarak-mehmet-seyidhasanoglu-mhk9g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tarihin çıldırmışılığına aldırmadan, sevdim seni! 

Coğrafyanın farklılığını görmezden gelip,

İklimlerin uzamışlığıyla uğraşmadan,

İnsan kanı emen insanlara inat! 

Şiirlerin, yalınlığını bakış açısı belirleyerek,

Şarkıların; hayatın ritmine ayak uydurmasıyla özenerek,

Bencilce değil! Dostça, paylaşarak,

Dar bir pencereden değil! 

Şiirlerin gözüyle; 

Hayata, aşka ve dünyaya bakarak; sevdim seni! ....

Yani; 

Tembel - çalışkan bir öğrenci edasıyla; 

Logaritma, geometri, toprak bilgisi ve fizyoloji''yi...v.s. bir kenara bırakıp! ...

Felsefe ile, resim, müzik ve edebiyat''la; Sevdim seni! ....

Kafa kurcalayan dersleri belleğimden silip; 

Hayatın özü olan dersleri seçerek; 

Sevdim seni! ....

Kanımın her zerresine portreni çizerek, sevdim resim dersini! 

Senin sesinle, duyduktan sonra,

Şarkı sözleri ve melodiler anlamlı kıldı bana müzik dersini! 

Senin, hayata ve insanlara bakış açınla değişti; 

Benim felsefe anlayışım! ...

Toprak Bilgisi''ni ise neden yazdığımı bilmiyorum; 

Bilal hoca''yı sevmediğim gerçeğinden, herhalde! ...

Yalnız! Şu nu iyi biliyorum; 

Sana maddi gücümü sunarak değil! 

Özümü, benliğimi, aşkımı, sevdamı, umutlarımı, hayallerimi.....

Kısaca, kendimi sunarak; Sevdim Seni! .....

Senin istediğin gibi; 

''Bir GICIK olarak.....''

                          14.11.2003', 'Tarihin çıldırmışılığına aldırmadan, sevdim seni!  Coğrafyanın farklılığını görmezden gelip, İklimlerin uzamışlığıyla uğraşmadan, İnsan kanı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Seyidhasanoğlu']::text[], 8.5, '{"poet":"Mehmet Seyidhasanoğlu","poet_slug":"mehmet-seyidhasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-gicik-olarak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutamam', 'seni-unutamam-mustafa-sari-ik7x7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen unutulacak kadınmısın? 

kuru ayazlarda,bir kadeh içkide..

sen akıldan çıkarılacak kadınmısın? 

eskimiş bir yalnızlıkta,yaşanacak yeni bir aşkta...

yollar bitip,sonu okyanuslar olsa da! 

baharlar geçip,tüm tabiat solsa da...

yıllar geçip,dünlerimi unutsam bile,

sen unutulacak kadınmısın? 

kadınıma 2004/izmir 

                                  Mustafa SARI

seni asla unutamam..', 'sen unutulacak kadınmısın?  kuru ayazlarda,bir kadeh içkide.. sen akıldan çıkarılacak kadınmısın?  eskimiş bir yalnızlıkta,yaşanacak yeni bi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarı']::text[], 8.5, '{"poet":"Mustafa Sarı","poet_slug":"mustafa-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seni-unutamam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçmem...', 'vazgecmem-i-brahim-ethem-bingul-gmoa6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölüm korksun ölmekten

Vazgeçmem inan seni sevmekten

Zaman sussun zamansızlıktan

Ulaşabilsem sana sonsuzluktan...

www.iebingul.com', 'Ölüm korksun ölmekten Vazgeçmem inan seni sevmekten Zaman sussun zamansızlıktan Ulaşabilsem sana sonsuzluktan... www.iebingul.com...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/vazgecmem-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmasaydı', 'olmasaydi-jale-ozler-eboy4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllarla gidenler dönmüyor geri

Bari kaderdeki naz olmasaydı

Başka yol tutardım yıllardan beri

Yeni bekleyişte haz olmasaydı

Bu heves gönlümü hayale iter

Baharın hasreti ruhunda tüter

Ne güller açardı ne bülbül öter

Hayatın mevsimi yaz olmasaydı

Gönlüm her gün senden bir haber bekler

Gelmez de kalbime saplanır oklar

Mevsim yaz her yanda renk renk çiçekler

Ağlayan gönülde güz olmasaydı

Can bulsun sözünde efsane gülü

Sevindir hasretle yanan bülbülü

Sukuta varırdı gönlümün teli

Sesimi duyuran saz olmasaydı

Sensiz geçen hayat sıfırdı hiçti

Gönlüm yudum yudum bu hüznü içti

Yıllar vagon önümden geçti

Keşke zamandaki hız olmasaydı

Çiçekte mehtapta gözüm olmazdı

Sözüne benzeyen sözüm olmazdı

Kağıda yazacak yazım olmazdı

Gönülde sevgiden iz olmasaydı

Fidanım büyüdü her mevsim dal dal

Ömrümce sürer mi bilmem bu hayal

Sevgimiz dillerde olurdu masal

Yıllarla bağlanan öz olmasaydı', 'Yıllarla gidenler dönmüyor geri Bari kaderdeki naz olmasaydı Başka yol tutardım yıllardan beri Yeni bekleyişte haz olmasaydı Bu heves gönlüm...', ARRAY['Türk Edebiyatı','Şiir','Jale Özler']::text[], 8.5, '{"poet":"Jale Özler","poet_slug":"jale-ozler","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/olmasaydi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karabük', 'karabuk-jale-ozler-rv063', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sızı duyarım içimde ince ince

Dostluk ahbaplık kardeşlik gelir aklıma

Gençlik güzellik gelir

Karabük denince

Kalbimizin sıcağında erirdi

Kutladığımız yeni yıllar

İskambiller tombalalar derken

Anılarda kaldı merdivenli sokaklar

Asfalt yollar

Dostlar ahbaplar kardeşler içinde

Bir Neriman vardı

Talihsiz dertli mahzun

Kalbinin güzelliği yüzüne aksetmiş

Öylesine içli candan duygulu

Ve kibardı

Annelerimiz kardeşten ileri

Bizler kardeş

Bir büyük mutluluğum olmalıydı

Dörtte üçünü ona vermeliydim

Dertlerini tek tek paylaşabilmeliydim

O günlerin çiçekleri soldu dağıldı

Aynı tip evlerin çiçekli bahçeleri

Yenişehir’in lüks binaları

Piknik yaptığımız çamlık

Hayallerde kaldı

Bir sızı duyarım ince ince Dostluk ahbaplık kardeşlik gelir aklıma

Gençlik güzellik gelir

Karabük denince', 'Bir sızı duyarım içimde ince ince Dostluk ahbaplık kardeşlik gelir aklıma Gençlik güzellik gelir Karabük denince Kalbimizin sıcağında erirdi...', ARRAY['Türk Edebiyatı','Şiir','Jale Özler']::text[], 8.5, '{"poet":"Jale Özler","poet_slug":"jale-ozler","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/karabuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İki Diye', 'bir-i-ki-diye-jale-ozler-1dvxu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Andırır yaprağın dökülüşünü

Günleri sayarım bir iki diye

Yılların maziye gömülüşünü

Gönülden duyarım bir iki diye

Her akşam bülbülün gamlı dilleri

Hasretle soldurur pembe gülleri

Fala bakmak için iskambilleri

Yan yana koyarım bir iki diye', 'Andırır yaprağın dökülüşünü Günleri sayarım bir iki diye Yılların maziye gömülüşünü Gönülden duyarım bir iki diye Her akşam bülbülün gamlı d...', ARRAY['Türk Edebiyatı','Şiir','Jale Özler']::text[], 8.5, '{"poet":"Jale Özler","poet_slug":"jale-ozler","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-iki-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi Zaman', 'hangi-zaman-ahmet-capa-fkxnu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ömrümün dar ağacına,

günlerimi birer birer astım.

Üfledim ölümün kavalını

doğar doğmaz gırtlağımda ki feryatlarla.

Her gidişin ardından dönüp de bakar gibi,

koştum durmadan acılar mağmasında,

Yanmış ayak izlerimden başka

ne kaldı şimdi ömrümün uçurumlarında.

Hangi ses şimdi kuytularımda yankılanan,

ve pişmanlık notalarının üstüne basa basa,

hangi hazin bir keman sesi sızlatır ruhumu.

İstilacı düşünceler ortasında,

bütün vücuduma yapışan bu kara duman,

hangi yönden doğacak güneşi bekler durur.

Pervasızca yırttığım ömrümün sayfaları,

hangi ‘vade’de ölümün gülüşü ile

saçlarıma düşüp, aklara dönüşecek…

Bir yanlış denizde forsa gibiyim,

boynuma asılan hangi sahilin rıhtımıdır.

Ve hangi sürgün marşıdır şu dilimi parçalayan,

ağzımı kanla dolduran bu şarkılar,

bir kıymık gibi gözlerime batan bu göz yaşları,

bilmem ki hangi aşkın emanetidir.

Serçelerin göz yaşları timsahinkine benzemiyor işte,

Çünkü onlar öleceğine yakın ağlarlar,

Bilinmez ki şimdi,

Ben mi ağlıyorum,

yoksa…

sen mi ağlıyorsun? 

(Haziran 2004 İst.)', 'Ömrümün dar ağacına, günlerimi birer birer astım. Üfledim ölümün kavalını doğar doğmaz gırtlağımda ki feryatlarla. Her gidişin ardından dönü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çapa']::text[], 8.5, '{"poet":"Ahmet Çapa","poet_slug":"ahmet-capa","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hangi-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AÇILmaLISIN', 'acilmalisin-hasan-yasar-pumhv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'eğerahatsızlığı

nınedeniçindek

siltemediklerin

sevekmekarpu

zunutuyorsak

lınedeniçinasıllar

lağrıtıyorsanazika

fanısrarlaçılmalı

sınazmicimutla

kaçılmalısınere

deysenazlandığın...

şiirin çözümlemesi

eğer rahatsızlığının nedeni

içinde

eksiltemediklerinse

eve ekmek karpuzu unutuyorsa aklın

neden niçin nasıllarla 

ağrıtıyorsan nazik kafanı

ısrarla

açılmalısın nazmicim

mutlaka açılmalısın

neredeyse

en nazlandığın.', 'eğerahatsızlığı nınedeniçindek siltemediklerin sevekmekarpu zunutuyorsak lınedeniçinasıllar lağrıtıyorsanazika fanısrarlaçılmalı sınazmicimu...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yaşar']::text[], 8.5, '{"poet":"Hasan Yaşar","poet_slug":"hasan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/acilmalisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BEKLENTİ ''Can Baba'' ya', 'beklenti-can-baba-ya-hasan-yasar-3rw46', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''can baba'' ya



            ben sana 

                  küstüm işte! 

            ''_ can babaaaa! ''

            ''_ can babaaaaa! '' 

                  diye bağırdım 

                          durdum da 

            sabahın ayazında 

                  soluyarak götümden

            keçileri kaçırmış bu deli adama 

            '' yine ne var be yaarraaam! '' 

                            demedin 

            hatır için de olsa kalkıp yerinden...', '''can baba'' ya             ben sana                    küstüm işte!              ''_ can babaaaa! ''             ''_ can babaaaaa! ''            ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yaşar']::text[], 8.5, '{"poet":"Hasan Yaşar","poet_slug":"hasan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beklenti-can-baba-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay''a Sitem', 'ay-a-sitem-kemal-sarialioglu-507wx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gördüğün bu gülen yüzler cürmümüze mahzen; 

Böyleyken yüz çevirmek sana mı düştü bizden?', 'Gördüğün bu gülen yüzler cürmümüze mahzen;  Böyleyken yüz çevirmek sana mı düştü bizden?...', ARRAY['Türk Edebiyatı','Şiir','Kemal Sarıalioğlu']::text[], 8.5, '{"poet":"Kemal Sarıalioğlu","poet_slug":"kemal-sarialioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ay-a-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'gönlüm GÖRÜŞMEYELİM', 'gonlum-gorusmeyeli-m-hasan-yasar-t6hsj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'fırından yeni çıkmış 

           taze bi ekmek gibi

                  yaklaşıyor şubat

bi muziplik yapıcak

karı

mart getiricek kesin

şu kazma kürek yaktıran

                    ocak yıkan 

kötü adam rolündeki erol taş yüzlü mart

yanlış sevmelerden

         yüreği burkulmuş

diz boyu kardan çok

             hasrete batmış

                     bi adamım ben

noktalı virgülsüz

iki nokta üstüstesiz

                 yaşamalı

yeni aşklar giyinmek için henüz erken

kaçmak lazım şimdi

kaçmalı sıcak bakışlardan

soru işaretli yerlerden

meraksıyan kimselerden

dur yüreğim 

sevdasadın biliyorum

ama şimdi dur

       sırası değil

                tuzlu çileğin

sırası değil kış kapıdayken

aşka düşmeyelim

şartlı refleks gibi hemen.

hatta gönlüm be 

         istersen 

        görüşmeyelim ha.

evet

evet görüşmeyelim.

görüşmeyelim

dünya bahara yüzünü dönmeden.', 'fırından yeni çıkmış             taze bi ekmek gibi                   yaklaşıyor şubat bi muziplik yapıcak karı mart getiricek kesin şu kazm...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yaşar']::text[], 8.5, '{"poet":"Hasan Yaşar","poet_slug":"hasan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gonlum-gorusmeyelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybettim', 'kaybettim-baykal-kaanalp-s8tex', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dün gece yağmurlu sokaklarda

dolaşırken kaybettim,neşemi

senin bana sakla diye 

verdiğin,ömür boyu

sen gidince önemi kalmadı

sevinç ya da hüznün

istemenin ya da istenmenin

yalnız dolaşıyorum

yürüdüğümüz sahili

balık kokulu,badem dokulu

palmiye ağaçlı,mermer taşlı

hiç aldatma yoktu gözlerinde

o taşların,senin de sözlerinde

gittin ve de götürdün

benliğimi,sevgimi,aşkımı

umut umut taşımıştım

onları senden bana', 'dün gece yağmurlu sokaklarda dolaşırken kaybettim,neşemi senin bana sakla diye  verdiğin,ömür boyu sen gidince önemi kalmadı sevinç ya da hü...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kaybettim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biber Tohumları', 'biber-tohumlari-baykal-kaanalp-56aoc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'büyütürüm sevdamı

biber tohumlarında

içinden acıda çıkabilir

tatlı da', 'büyütürüm sevdamı biber tohumlarında içinden acıda çıkabilir tatlı da...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/biber-tohumlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter mi?', 'yeter-mi-baykal-kaanalp-1d2ni', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bize verilenlerle mi? yetinsek

öküz altında buzağı mı? arasak

geceleri mışıl mışıl uyuyup

gündüzleri hayallere mi? dalsak', 'bize verilenlerle mi? yetinsek öküz altında buzağı mı? arasak geceleri mışıl mışıl uyuyup gündüzleri hayallere mi? dalsak...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yeter-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Bitti', 'her-sey-bitti-baykal-kaanalp-nd02t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yalnızca geçip gitti

hiç bakmadı yüzüme

benim için herşey bitti

kavuşmadı çözüme

uğruna inanmadığım

bütün nalları attım

yokluğuna yanmadığım

hasretleri tattım

yalnızca geçip gitti

hiç bakmadı gözüme

beni değil onu seçti

inanmadı sözüme', 'yalnızca geçip gitti hiç bakmadı yüzüme benim için herşey bitti kavuşmadı çözüme uğruna inanmadığım bütün nalları attım yokluğuna yanmadığım...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-sey-bitti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşmusun? ? ?', 'bosmusun-baykal-kaanalp-ui9ln', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her zaman böyle güzel,böyle hoşmusun? 

hayatının sonuna kadar boşmusun?', 'her zaman böyle güzel,böyle hoşmusun?  hayatının sonuna kadar boşmusun?...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bosmusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Benmiyim Günahkar...', 'benmiyim-gunahkar-erdal-asik-cm6zq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günahlarımı ödeyemem aşka 

Aşık edip ayrıldığım aşklarıma

Ne umutlarla bağlandılar bana

Unuttular sevgiyi yanında

Sindiremezsin aşkı kuru kuruya 

Sevgide olmazsa yanında

Benmi günahsız onlarmı günahkar

Varın şımdi siz bunun kararına', 'Günahlarımı ödeyemem aşka  Aşık edip ayrıldığım aşklarıma Ne umutlarla bağlandılar bana Unuttular sevgiyi yanında Sindiremezsin aşkı kuru ku...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benmiyim-gunahkar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzümlü:Bir Cimin Hikayesi', 'uzumlu-bir-cimin-hikayesi-hasan-akin-td64c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bildim...

..................Kuytusunda dalbastı

......................

Ahhh...

Yine kirazlandı gönlüm

.....

Baranların derin oyuklarında

Üzüm asmasına salınır gölgeliğim

Yaslanır babam hugul tumbuna

yoncalanır gözümün yağmurları

Usulca akar...

Gördüm...

Terkedilmiş bir kuş yuvası yalnızlığını

.............

Komlar''ın yokuşunda terleyen

Kurumuş ceviz yapraklarını

...........Aluçalar sarar etrafımı

Hüzne boğar...

Nasırlaşan ellerini anam.

.........

Dur...

Taş ocakta pişe dursun eşgili...

.............Gitme

Oğul gitme...

............

Lahana yaprağında salatam kalır...

..........

Babannemden kalan...

Duydum! ! ! 

.............Bu yemeğin üstüne iyide çay gider! ! ! 

Çay gider oğul...

.....Seslenişi babamın

Ve üzüm ortudunun ateşinde

Ağlar göze suyu...

Kara demliğin çığlıklarını işitir dağlar...

Yıkılan bağ duvarlarını tamir ederken hayat

Başında emanet pörküyle

........ahhh

Sallar tırpanı ekine

Soytarı hüseyinden kalan...

Işgın tadında geçer gözümden

Bir gün batımı tepeboynu...

Açılır kanatlının kapısı

Ayvanın serinliğine...

Fesaldan su alır yüzüm...

Kuruyan yanlarıma...

Gurbette....

Sakallarım batar çehreme

Ağlardım...

 (98-Aralık....Libadiye)', 'Bildim... ..................Kuytusunda dalbastı ...................... Ahhh... Yine kirazlandı gönlüm ..... Baranların derin oyuklarında Üzü...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akın']::text[], 8.5, '{"poet":"Hasan Akın","poet_slug":"hasan-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/uzumlu-bir-cimin-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Şefkat...', 'mavi-sefkat-hurrem-yalcin-29mq1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'güneş bile bırakır cızırtısını

batarken gönül rızasıyla

Maviye...

kumların üstüne sepelediği

garip sıcaklığı cömertçe

martının kanadındaki

beyaz tüyün rüzgarı

hep maviye sevdalı

ıslak kumların nemi

ürperten minik ayakları

dalganın beyaz köpüğü

dağıtan sarı saçları

denizin mavisi

okşayan çocuksu başı

işte

Mavinin 

budur

sessiz

ama

sıcacık

Şefkati..

23 Nisan 2004', 'güneş bile bırakır cızırtısını batarken gönül rızasıyla Maviye... kumların üstüne sepelediği garip sıcaklığı cömertçe martının kanadındaki b...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mavi-sefkat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babil Kulesi ''Barış Aluk ve Mutlu Ayar''a''', 'babil-kulesi-baris-aluk-ve-mutlu-ayar-a-ahmet-aksoy-2rybv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '................''Sevgili dostlarım Mutlu Ayar ve Barış Aluk''a''

bir çağ düşer tarihin saçaklarından

.....elimizde avucumuzda yalan

dostlar toplanalım

.......yakalım zihinlerde

..................söz odunu

parıldasın ve beyaza boyansın

.............insanın kara yolu

uyansın şeytanın uyuttuğu bilinçler

...inşa edelim babil kulesini

çalışkan ve sabırlı örümcekler gibi

...ama bu kez

..........olmasın kötüler', '................''Sevgili dostlarım Mutlu Ayar ve Barış Aluk''a'' bir çağ düşer tarihin saçaklarından .....elimizde avucumuzda yalan dostlar to...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/babil-kulesi-baris-aluk-ve-mutlu-ayar-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Geleceksen eğer...**', 'geleceksen-eger-hulya-simsek-84h05', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'geleceksen eğer sevda...

gel! ama olabildiğine sade

yüreğine hiçbir şey giyme

gururunu bir eldiven gibi

kibrini elbise gibi fırlat at

yanına tek -mız ekini al

kendini benimle çoğulla gel! 

geleceksen eğer sevda...

yanına yastığını alma

bende bir ömür baş koyacağımız

düşünce var

gelirken sevda...

yüzünü bırak aynalarda

bende yüzünün ömürlük düşü var

gel sevda! 

geçmişini bırak en tozlu raflarda

bana geleceğini 

bana gönlünü 

al da gel!', 'geleceksen eğer sevda... gel! ama olabildiğine sade yüreğine hiçbir şey giyme gururunu bir eldiven gibi kibrini elbise gibi fırlat at yanına...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/geleceksen-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlık yokluğu beklemez', 'varlik-yoklugu-beklemez-sair-ahrazi-qdqfy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim bir adım var,bir de miadım,

Hangisine varsam öbürü bekler.

Derdim lisan olmuş mevzu feryadım,

Ah’tan arta kalan tabiri bekler.

Bu nasıl cihan ki attığım adım,

Dolandığı yerde kabiri bekler.

Riyadan ayrılan ahrazi yadım,

Adına kavuşan haberi bekler', 'Benim bir adım var,bir de miadım, Hangisine varsam öbürü bekler. Derdim lisan olmuş mevzu feryadım, Ah’tan arta kalan tabiri bekler. Bu nası...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/varlik-yoklugu-beklemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadıkça', 'yasadikca-derin-oger-9ify3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dudaklarında ki yangının rüzgarı beni arar

yanıma sokulur  yüzüme dokunur elimi tutar

estikçe kestikçe yollarımı seni bana müjdeler

bir yanımı serinliğin bir yanımı ateşlerin basar

bir yanıma yağmur yağar bir yanıma güneş doğar

sen alırım soluk soluk sana yağarım oluk oluk

kalbimde aşksın herbir azamın ben olduğu kadar

adımlarımda düşlerimde gezdiğim yollar kadar

yaşadıkça bu sevdanın masalı bu dünyayı kaplar..', 'dudaklarında ki yangının rüzgarı beni arar yanıma sokulur  yüzüme dokunur elimi tutar estikçe kestikçe yollarımı seni bana müjdeler bir yanı...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasadikca-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunmak', 'yunmak-erdal-sayil-nri9d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Naz mı, oyun mu, şaka mı bunlar...? 

Benim bildiğim seven, çekmez kendini sunar...

Her güçlüğü yenmeye böyledir taze kuvvet; 

Bu bağlılık suyunda, temiz olan da yunar...', 'Naz mı, oyun mu, şaka mı bunlar...?  Benim bildiğim seven, çekmez kendini sunar... Her güçlüğü yenmeye böyledir taze kuvvet;  Bu bağlılık su...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sayıl']::text[], 8.5, '{"poet":"Erdal Sayıl","poet_slug":"erdal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yunmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpüşünü Esirgeme Sevdama', 'opusunu-esirgeme-sevdama-yuksel-ozbek-jiwei', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şimdi nerdesin.

ve

 kim bilir nerelerdesin 

düşlerinin.......ve

 kiminle konuşuyor

gözlerin..

 konuşmak, bir nevi

 paylaşmaktır yaşamı...

şu an 

sendeyim ben 

oysa....

sende takılı değerlerim.....

.ve sende son buluyor isteklerim...

..gidiyorum yalnız düşler ülkesine....

öpüşünü esirgeme sevdama,

 yeter.....', 'şimdi nerdesin. ve  kim bilir nerelerdesin  düşlerinin.......ve  kiminle konuşuyor gözlerin..  konuşmak, bir nevi  paylaşmaktır yaşamı... şu...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Özbek']::text[], 8.5, '{"poet":"Yüksel Özbek","poet_slug":"yuksel-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/opusunu-esirgeme-sevdama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mynet sürprizi', 'mynet-surprizi-akin-akca-0ro2v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '…,, Koşturmakta Goyathlay (Geronimo)

,, … ‘Appalachia Dağlarının-Apache halkı’nın şefi

…,, Ve sakin hayata zorlanıyor, altın yolunda! 

Beyazlar içinde koşturuyor ve akrep

Cv’sini, çeyizini toparlayıp; 

.. Yelkovan; yelkovan ise, ak 

Mintanlar kuşanmış o da; 

Titreşiyor (o ise)  piti piti.

Koç’um çarpışıyor bir boğa 

Ya da kızıl gergedanla

‘Oynaş-gölge-caddesi’ buffalo meydanında.

*

…,, Tut bıçağı ağzında Apaçi:

Mızıka çalar gibi, Bremenli birileri.

İpe çekenler güneşi, bilirler elbet direği:

Bu direktir, olacak o sancak; kanlı

, Ancak: Tan ağarmaz oldu

*

Şafakla da doğdu

Ya, gün, kendiyle -

Sahilin tekinde, gün batımında? 

İpi akrep çekti,sandalye düştü.

Bir bedendi sallanan havada

Seyirciler alkışladılar,

Kenarda kalanlardan; 

Anlam veremedi bazı

Sessiz kalanlar -

Gölgeliktekilerden:

Bir tiyatro kuruldu, bir saniyede; 

Bir gece kondu, olur da

Bir de betonarme? 

Hele! 

Aydınlık mı, o nerede? 

Gecenin içinde ne var,

Sabaha koşturan? 

Nasıl cellat bunlar,

Hiç mi insaf yok:

(Ezip geçen bizon-musalla’sı) 

Bunca yıllık; 

Sevgi mi, bir anlık? 

Ne kadar üzgünüm; 

İşte, o kadar üzgünüm.

Nerdeydik, ya da neredeydi:

Nerede? Orada

İşte, orada

Karanlık orada.

Uzun bir gecenin kımıltısı

Yaklaşan sessizliğinin

Terör, öncesinde; 

Kan akıtışının koncaların.

Rapunzel indi kuleden aşağı; 

Ama kesmişti cadı saçlarını onun.

Kuleden sarkıtamadı beyaz atlı’yı.

Külkedisi kötü kızdı,

Üvey onun kardeşleri

İyi insanlardı:

Gece ak, karaydı gündüz; 

Karanlık huzur bahşediciydi.

Ve zaman böyle aktı.

*

Bu aldığın bedel ne için,

Hiçbir şey yokken,

Hiçbir şey var oldu:

Buna giden yol, uzundu.

…,, 1835 ‘Gözyaşı yolu’

…,, Cherokee’lerin -‘üç aylık sürülme’:

…,, Doğa için yaşayıp

…,, Kendisi sürgün yollar’da

,, … Dört bin’i için onlardan; 

…,, Yollarda -açlık,soğuk ve hastalık

…,, -Telef olma! 

Tutkunun yanı başında

‘En ayrımsanır-ayrılıklar’

Gerçek olur birkaç saat içinde

Ya -

Farklılkaşır durumlar tamamen

-Garip? 

‘Olmayan bir şeyden oluşma’-‘açtıran çiçek’

-‘Bir varlık bulan’- sunabilir mi

Kendisini arz eden; bir şey ki

, Baştaki ‘olmayan’ gibi? 

Ki, başlangıcını barındırmayan kendi içinde,

Böyle başlayan bir zaman; 

Hiç taşır mı ‘su-dopdolu hörgüçleri’nde, son’u

? Kırılıp da içine kalan -sadece

Üzüntüsü de kendisi onun olur,

‘Ters yüz-eğri’sinde, hayattan ziyade.', '…,, Koşturmakta Goyathlay (Geronimo) ,, … ‘Appalachia Dağlarının-Apache halkı’nın şefi …,, Ve sakin hayata zorlanıyor, altın yolunda!  Beyaz...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/mynet-surprizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Sestim', 'ben-bir-sestim-yusuf-ter-ft2o1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bir sestim 

Çığlık  yankılandı

Dalgalar arasında

Yıldız kaydı

Ben bir sestim

Ölüm ziline bağlı

Toprak için, için ağlı

Ay yarım kaldı

Ben bir sestim

Sesim çoğalsın istedim

Kısılmadan çölde

Bağra bilirdim

Rüzgâr aldı

Babamda bir sesti

Öğütleri altındı

Yaşam içinde seslendi

Haklı haksız yere

Sözlerine kulak verdik

Ben bir sestim

Gözü körlere yol göster

Yusuf’um taşlar kırılır

Çığlıklar kırılmaz gider

Ata izleri kolay silinmez

Yusuf Ter 20.06.04

Saat 21:53 İsviçre', 'Ben bir sestim  Çığlık  yankılandı Dalgalar arasında Yıldız kaydı Ben bir sestim Ölüm ziline bağlı Toprak için, için ağlı Ay yarım kaldı Ben...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-bir-sestim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Adam (Tabut)', 'dort-adam-tabut-halit-demir-huqdi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gençliğin tükenip de,  gidermiş bir gün,

Boşa geçen zamanına, ağlarsın her gün,

Dünyada ne ektiysen, mahşerde o gün

Sen onu biçeceksin, bilesin ki o gün

Dört adamın omzunda, kabre gidersin,

Yüce Mevlâm sonumuzu, hayır eylesin

Yalan söyleyen kul,doğru yola varamaz

Asr-ı hâzırda yaşar, doğrusunu bulamaz

Hep kendini kandırır, Ol Var’a kul olamaz

Gözyaşı döksen de,  bu cana faydası olmaz

Dört adamın omzunda, kabre gidersin,

Yüce Mevlâm sevilen, kullarından eylesin

Kim dünyada kalmış, hele bir göstersene

İki metre kefen bez, biçmişlerse üstüne

Bedenini yıkarlar,  bir teneşir üstünde

Cenazemiz kılınır, bir musalla üstünde

Dört adamın omzunda, kabre gidersin,

Yüce Mevlâm mekânını, cennet eylesin

Halit DEMİR-27.04.2004', 'Gençliğin tükenip de,  gidermiş bir gün, Boşa geçen zamanına, ağlarsın her gün, Dünyada ne ektiysen, mahşerde o gün Sen onu biçeceksin, bile...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dort-adam-tabut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Açtım Sensiz Zamana', 'ates-actim-sensiz-zamana-nevin-kurular-y80k2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutma; 

Gözlerim yeşilini sana gönderdi

Kalınca yaşı bana..

Unutma…

Düşünce yollara….

Açıldı kollarım 

Muamma bir heyecanla

Koşarsın diye bekledi…

Değişirdi  yolların   belki ama…

Özlemimi  bilemedi.

Unutma, 

Yarınım var…

Yanında, yada kuytusunda

Vebal boynunda

Aşkım koynunda…

Bu Sevda boş yere

O Yüreği… seçmedi

Unutma…

UMUT la

Yaylım ateşi açtım

Sensiz Zamana…

Gözlerim izinde

Yüreğim mahzeninde

Ellerim…..

Düşlediğin her yerde

Seninle.

Unutma …..

Umutla…...', 'Unutma;  Gözlerim yeşilini sana gönderdi Kalınca yaşı bana.. Unutma… Düşünce yollara…. Açıldı kollarım  Muamma bir heyecanla Koşarsın diye b...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ates-actim-sensiz-zamana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firari Bir Özgürlük Tadında', 'firari-bir-ozgurluk-tadinda-derin-oger-9g7eg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerimde soyunuyor takvim yaprakları

sayfalarında gezindiğim ağır bir roman gibi

hayallerime uzanan dili esrar ile sır dolu

acıları unutturmaya çalışan bir melek sanki

bilsen ne çok isterdim çocukça sevinmeyi

gamsızca savrulup sen gibi geçip gitmeyi

farketmezdi atlı yaya kuşların kanatlarınca

payıma düşen günleri çocukça yaşamaya

açmak istemediğim yaralar gibi açılışına

ellerimi yakıp ağır aksak saatlere akışınla

acısını ve keyfini çıkar başbaşa olmamızın

sel götürecek beni firari bir özgürlük tadında..', 'gözlerimde soyunuyor takvim yaprakları sayfalarında gezindiğim ağır bir roman gibi hayallerime uzanan dili esrar ile sır dolu acıları unuttu...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/firari-bir-ozgurluk-tadinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dangles of a core-angle-divine', 'dangles-of-a-core-angle-divine-akin-akca-zvkn6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'In MELE-İ A''LÂ,she prepared a contest: 

One winged-‘fur-cut’-‘jur-jog’.

See thou thy small daughter hands 

And hold ‘em.Under prehistoric lights: 

( Aurora Borealis or Ecuador..)

’What else? ’ or ‘for all’; 

Do embrace! spring ‘n summer 

(Orbit’s a mirror of another orbit..)

And the winter fall, ye call: 

So -tall- let the woods hug! 

Cry, on your own: Cry and think! 

Whilst teardrops fallin’, for the leaves; 

(Dew, first!)

‘Just a praise’ ha, thru the nite? 

(His praises thru the dark 

Was ebbin’, almost - 

O’ the best, these are the costs..)

In the rain: 

Thy honour, capable-self-portrait... 

Please keep the same angle: 

Whatta dangle! 

These’re the days o’ angle-divine: 

Coz, heartbreak’s a cell membrane; 

Courtesy! fed-thin-argue-cored-sin! 

We’re the ants of this jury: 

We should be in hurry, but not fury. 

And in bumerang; one, thinketh! 

(Emeroopth! 

Emero’pth!)

: On the moon, merit-depth-toot in the lee 

Leen! Le’n! 

(Leen-merit-depth-toot!)

Pain is a laugh 

Thru the waves of abstract colours 

Or whatever -thee, angrily 

-As a bee, consciously standing! … 

TÜRKÇESİ: 

Tuttu bir ucundan, yarışmada; 

Huzurunda MELE-İ A''LÂ’nın, 

Tertip etti yarışmayı. 

Tek kanatlı-‘post(u)  kırpılmış’ ’muhakeme-zinde kalma dengeli koşusu’! 

Sen, küçük kızının ellerini gör 

Ve tut onları 

Tarih öncesi ışıltısı altında: 

( Aurora Borealis ya da Ekvator..)

( ‘Başkaca ne? ’ veya ‘hepsi için’… )

Bahar ve yaz kavuşup da 

Kucaklaşıverir, sarmalandığında 

(Yörüngedir en iyi, uydu 

Ve uydu ayna olur kendisine, 

Yansıtır yörüngeyi: 

Hemcinsine tamamlar daireyi.)

Ve kış düşü’nü çağırır; 

Sırf, kar lapa lapa döküldüğünde. 

Öyleyse, odun ve kütükler, yetişin! 

Yapışıp kendinize; kendinizce, ağlayın! 

: Ağlayın ve düşünün; 

Yapraklar için, gözyaşlarında düşen; 

(Kırağısında, ilk çiy’inde..)

Olup yağmur, gökyüzünden! 

‘Tek bir dua’, 

Gecenin içinden …

Ha? 

[:Onun duaları karanlığı yararak, 

Yavaştan gücünü kaybediyor olan; 

Diyeyim       (değil ama o bile)  sanki eskiden - 

Bunlar en iyi’nin bedelleri.] 

Yağmurda! … 

Sevgilim! Şerefiniz! .. 

: Muktedir-kendi portreniz!       (Kendine yeterli-kendi resminiz!)

Ne oynatış ama! 

: Açıları kor’u, tek’liğin! 

Bu günler kutsal günler, 

Çünkü yürek kırıklığı ince bir zar tabakası: 

Nezaket! Beslenen-ince-tartışma, çapsız-merkezli! 

Bu jurinin karıncaları, insanlar biziz! 

Acele de etmeliyiz, fakat hiddetsiz! 

Kişi ki, düşünmeli 

Ve       (düşündüğünün)  akabinde (de)        hissedebilmeli – 

Kabzasında bumerangın. 

Emeroopth! Emero’pth! 

: On the moon, merit-depth-toot in the lee:

Leen! Le’n! 

(Leen-merit-depth-toot!)

; Ay’ın rüzgar almayan tarafındaki meziyet derinliği-gemi sesi (düdüğü) ! 

: Acıdır, bir kahkaha; 

Abstrakt renklerinde dalgaların içinden veya böyle bir şey … 

-Sen, kızgıncasına-

Dikiliyor iken ayakta, en bilinçli şekilde; 

Çalışkan, arı gibi! ... 

Açıklamalar: 

Ebb: azalmak yavaş yavaş gücünü kaybetmek 

MELE-İ A''LÂ: Melekler kurulu 

Aurora Borealis: Kuzey ışıkları 

Divine:kutsal 

KENDİ TÜRETTİĞİM KELİME YA DA KELİME ÖBEKLERİ: 

Emeroopth:Leen-merit-depth toot 

Leen-merit-depth toot: Ay’ın rüzgar almayan tarafındaki meziyet derinliği-gemi sesi (düdüğü)

Lee:Rüzgar almayan taraf 

Leen! Le’n! : In the lee of the moon 

One winged-‘fur-cut’-‘jur-jog’: ‘Post(u)  kırpılmış’ ’muhakeme-zinde kalma dengeli koşusu’ 

Capable-self-portrait: Muktedir-kendi portre, (kendine yeterli-kendi resmi)', 'In MELE-İ A''LÂ,she prepared a contest:  One winged-‘fur-cut’-‘jur-jog’. See thou thy small daughter hands  And hold ‘em.Under prehistoric li...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":102,"source_url":"https://www.antoloji.com/dangles-of-a-core-angle-divine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilin anlatısı', 'dilin-anlatisi-akin-akca-6ua8p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her dilin anlatısı 

Ve bir kömürlük, 

Kapıcının odası: 

Bir bakış, 

Geçmişi endüstrinin 

Ve hem açan çiçeği 

Hala doğanın. 

Bir köprücük kemiği, 

Kim dedi onun için, 

O oldu diye köprü? 

: Çıktığında kavga, 

Gürültü; 

Gerçek olur mucize, 

Ayrılık vuku bulur.

Dönüş varsa, bilinir: 

(O zaman yukarıdan, 

Izgaralardan, güneş; 

Ateş! kömür parelerine 

Işıldamaya başlar.)

(Belki)

Güzel olan budur.', 'Her dilin anlatısı  Ve bir kömürlük,  Kapıcının odası:  Bir bakış,  Geçmişi endüstrinin  Ve hem açan çiçeği  Hala doğanın.  Bir köprücük kem...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dilin-anlatisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayan Beyan', 'ayan-beyan-bayram-tunca-zo3ef', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah çilekeşlikte daima baş roldeydim

İtikadımca her an imtihan içindeydim

İnan şu kirpiklerimi hiç kurutamadım

Yapılan vefasızlıkları hiç unutamadım

Bilmem ki bu derdimi nasıl etseydim beyan

Aslında, her şey görülmektedir ayan beyan

Derdimi derman olurlar mı ki, etsem beyan

Zannetmem olsunlar, dayan dizlerim dayan

Bu hususta yazdığım dilekçelerim katar oldu

Ne hikmettir bilinmez, hepsi sümen altı oldu

Her defasında yaralı kalbim biraz daha soldu

Çünkü tuzu kuruları dert anlatmak çok zordu

B. Tunca/20.06.2004-06.20', 'Ah çilekeşlikte daima baş roldeydim İtikadımca her an imtihan içindeydim İnan şu kirpiklerimi hiç kurutamadım Yapılan vefasızlıkları hiç unu...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayan-beyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayınvalidem- 8 / anı', 'kayinvalidem-8-ani-k-muran-esen-87ngr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep söylerim, çok şeker bir kayınvalidem var. Aşağıdaki yazıyı okuyunca, eminim bana hak vereceksiniz.

Ne zamandı, hatırlamıyorum. Kapı çalındı; baktım, bizim yan komşunun çocuğu.Gülümseyerek; 

” Kâmuran Teyze, Messur’anım Teyze (kayınvalidem  yani)  uzadıcıyı istiyor,''” dedi....Allahallah! Uzadıcı ne ola ki? .......Çocuk işte, yanlış anlamış olmalı.

“Tamam,  sen git, ben götürürüm,” dedim.Çünkü, kayınvalidemin ne istediğini anlayamadım. 

Sonra kapıya çıkıp, seslendim kayınvalideme.Zaten hemen bitişiğimde. 

”Anne! Ne istiyorsunuz? “

” Uzadıcıııı Kemraan(bana böyle der) , uzadıcıııııı.”......Uzata uzata istiyor uzatıcıyı. Hem de bağıra bağıra.Bütün mahalleye canlı yayın.

Hıııııım! ...... Bu uzadıcı  acaba ne? Kayınvalidemin sözlüğünü çok iyi bilirim de, bunu çıkartamadım. Elektrik faturasının adının, onun dilinde  “ışık kâadı” , su faturasının da  “su kâadı”  olduğunu biliyorum ama, uzadıcıyı bilmiyorum...İkide bir söylenir durur; “su kâadı gene çok geldi, ışık kâadı gene çok geldi,” diye. Bu “uzadıcı” uzun bir şey  olmalı...Çamaşır ipi gibi örneğin ya da lâstik falan....İstediğinin ne olduğunu anlayabilmek için; 

” Ne yapacaksınız uzadıcıyı? ''” deyince; 

Kayınvalidem: 

” Ütü yapmaya kadın gelecek.Ütünün kordonu kısa,” dedi. 

Birden jeton düştü. “ Uzatma kablosu mu? “ deyince, Kayınvalidem: 

” He he! Uzadıcı işte,” diye yanıtladı. 

Ah benim şeker kayınvalideciğim! Senin kullandığın dili seveyim ben!', 'Hep söylerim, çok şeker bir kayınvalidem var. Aşağıdaki yazıyı okuyunca, eminim bana hak vereceksiniz. Ne zamandı, hatırlamıyorum. Kapı çalı...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kayinvalidem-8-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık ki Bahçeler Bizsiz Kalacak', 'yazik-ki-bahceler-bizsiz-kalacak-i-smet-barlioglu-l8hgx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazık ki bahçeler bizsiz kalacak,

Güneş denizlere bizsiz doğacak,

Sular sahillere bizsiz vuracak,

Gel bu gün bitmeden, tükenmeden gel.

On onbeş yıl sonra kim bilir bizi? 

Mehtapta kimbilir kimlerin gözü,

Kimler taşatacak baharı, güzü? 

Gel bu gün bitmeden, tükenmeden gel.

Bilmezler başbaşa kıyılardaydık,

Aşkı oyun sandık, uykulardaydık,

Eller ne bilsin ki; şuralardaydık,

Gel bu gün bitmeden, tükenmeden gel.

Ne gölde şarkımız, suda aksimiz,

Ne ıslak jumsalda ayak izimiz,

Ne bir kahkahamız, ne gözyaşımız,

Gel bu gün bitmeden, tükenmeden gel.

Güller gül kokacak, ama ellere,

Başka sevgililer çökecek yere,

Bir gün eller için akar bu dere,

Gel bu gün bitmeden, tükenmeden gel.

Gel de sımsıkı tut benimle günü,

Hissetsin kumsallar yürüdüğünü,

Gel bu gün bitmeden, tükenmeden gel.

Unutma yaşarken çürüdüğünü,

(MELEKLEŞMİR MERMERLER isimli hece şiirlerinden > 43-44/100)', 'Yazık ki bahçeler bizsiz kalacak, Güneş denizlere bizsiz doğacak, Sular sahillere bizsiz vuracak, Gel bu gün bitmeden, tükenmeden gel. On on...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yazik-ki-bahceler-bizsiz-kalacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Laftan Anlamıyor', 'gonul-laftan-anlamiyor-i-smet-barlioglu-ji3mi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben zalime tutuldum da

Gönül laftan anlamıyor.

Yalanlara aldanmam da

Gönül laftan anlamıyor.

Biliyorum; cefa eder,

İnlettikçe sefa eder,

Ahdı birçok defa eder,

Gönül laftan anlamıyor.

Sevdası kar etti cana,

Gelen yoktur imdadıma,

Terkederim onu amma

Gönül laftan anlamıyor.

Öyle eşsiz bir zalim ki; 

Yüreğimi yaktı sanki,

Ağlıyorum her an çünkü; 

Gönül laftan anlamıyor.

Cayıp gittim bedenimden,

İnliyorum kederimden,

Ne gelir ki ellerimden

Gönül laftan anlamıyor.

Zehir oldu herbir nefes,

Nerde artık bende heves,

Çektiğimi anlar herkes

Gönül laftan anlamıyor.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 45-46/100)', 'Ben zalime tutuldum da Gönül laftan anlamıyor. Yalanlara aldanmam da Gönül laftan anlamıyor. Biliyorum; cefa eder, İnlettikçe sefa eder, Ahd...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gonul-laftan-anlamiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlüğe bir iki...', 'ozgurluge-bir-iki-duygu-i-demen-tanik', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özgürlüğe kaç kaldı dersiniz? 

3 yıl daha çalışma hayatı mı? 

15 Milyar ikramiye ya da oynadığınız lotodan para? 

5 yıl daha büyümesi mi çocuklarınızın? 

Doğacak torunlarınızın yürüme yaşı mı? 

Denizi görmek

Bir balıkçı evine misafir olmak

dağlarda ilk kez nefes almak

ya da eskittiğiniz çiçek tohumlarını ekmek için..

Özgürlüğünüze kaç rakam kaldı? 

Kendiniz olmaya kendinizi keşfetmeye kaç sene kaldı? 

Bu yazıda uzar gider soru işaretleri..

Ben uzattıkça kalem biter..

Siz uzattıkça ömür..', 'Özgürlüğe kaç kaldı dersiniz?  3 yıl daha çalışma hayatı mı?  15 Milyar ikramiye ya da oynadığınız lotodan para?  5 yıl daha büyümesi mi çoc...', ARRAY['Türk Edebiyatı','Şiir','Duygu İdemen']::text[], 8.5, '{"poet":"Duygu İdemen","poet_slug":"duygu-i-demen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ozgurluge-bir-iki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum..', 'gidiyorum-ceyda-ayfer-oz-b7cgl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hüznün tomurcuklarını topluyorum

Dizi dizi kırlangıçlar süzülüyor yüreğimden

Etrafta çam kokusu

Alabildiğince sarıyor çehremi

Üşüyorum…

Maviyi buluyorum tüm tonlara

Ellerimin çatlaklarını beziyorum

Dilim boylu boyunca uyumuş

Bir ses arıyorum

Tutunuyorum bahar dallarına

Susuyorum……

Unutmayı deniyorum derin izleri

Sarmalıyorum kendimi yalnızlığımla

Koynuna giriyorum gecenin

Bir başka ben çıkarıyorum gündüze

Düşüyorum…….

Siz kazandınız! ! ! 

Gidiyorum...', 'Hüznün tomurcuklarını topluyorum Dizi dizi kırlangıçlar süzülüyor yüreğimden Etrafta çam kokusu Alabildiğince sarıyor çehremi Üşüyorum… Mavi...', ARRAY['Türk Edebiyatı','Şiir','Ceyda Ayfer Öz']::text[], 8.5, '{"poet":"Ceyda Ayfer Öz","poet_slug":"ceyda-ayfer-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gidiyorum-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azap', 'azap-i-smet-barlioglu-eihbb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özlem arkamdan vurdu günlük güneşlik günde,

Umut dolu ellerim kaldı iki böğrümde,

Yanmamıştım bu kadar terkedip gittiğinde,

Böyle mi gösterirmiş azap birden kendini? 

Ancak böyle anladım acısını vedaın,

Kopmuş bir tesbih gibi yüreğim darmadağın,

Dağ yıkıldı, altında kaldım koca bir dağın,

Böyle mi gösterirmiş azap birden kendini? 

Sanıyorum yeniden göreceğim nasılsa,

Sen benim, ben de senin, dünya bile yıkılsa,

Aklıma gelmedi ki dönmezsin bana asla,

Böyle mi gösterirmiş azap birden kendini? 

Beklediğim kalmadı artık tozlu yollardan,

Kesildi umutlarım kışlardan, baharlardan,

Kim dönmüş ki dönesin dönülmez diyarlardan,

Böyle mi gösterirmiş azap birden kendini? 

(MELEKLEŞMİR MERMERLER isimli hece şiirlerinden > 47-48/100)', 'Özlem arkamdan vurdu günlük güneşlik günde, Umut dolu ellerim kaldı iki böğrümde, Yanmamıştım bu kadar terkedip gittiğinde, Böyle mi gösteri...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/azap-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanmış..', 'zamanmis-baris-pinar-tumer-jkt76', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamanmış...

Hani şu

Unutturur dedikleri....

Yalanmış....

Zamanın koridorlarından

Sırf unutmak için

daha çabuk 

unutmak için

herkesten hızlı geçtim....

Yoruldum...

Unuttum da

yani sandım...

Şimdi bu kadar

uzakken sen zamanlarıma

aklıma damlaman

nedendir? ...

Zamanmış....

Hani şu unutturan...

Yalanmış...', 'Zamanmış... Hani şu Unutturur dedikleri.... Yalanmış.... Zamanın koridorlarından Sırf unutmak için daha çabuk  unutmak için herkesten hızlı ...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zamanmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Bahçede İşim Ne?', 'bos-bahcede-i-sim-ne-i-smet-barlioglu-9xr9h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilir misin, gece niçin ağladım? 

Sana nasıl ayla selam yolladım,

Hayatımı yollarına adadım,

Sen bir gülsün, gül bunları ne bilsin.

Bir bilsen ki boş bahçede işim ne? 

Bir bilsen ki ekmeğim ne, aşım ne? 

Bu başıma her gün yağan hışım ne? 

Sen bir gülsün, gül bunları ne bilsin.

Yastığım yok, yatağım yok, uykum yok,

Elemlerden, çilelerden korkum yok,

Yıllar yılı delilerden farkım yok,

Sen bir gülsün, gül bunları ne bilsin.

Odam dolu hayalinle, şeklinle,

Saçlarımı okşuyorsun elinle,

Yanımdasın o her günkü halinle,

Sen bir gülsün, gül bunları ne bilsin.

Yüreğimin bir ağlayan dili var,

Bedenimin bir kırılmış beli var,

Şu gönlümün bir mahvolmuş hali var,

Sen bir gülsün, gül bunları ne bilsin.

Canım her an sehpalarda, iplerde,

Mahzun yüzüm sürünüyor yerlerde,

Tad kalmadı şu güzelim günlerde,

Sen bir gülsün, gül bunları ne bilsin.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 49-50/100)', 'Bilir misin, gece niçin ağladım?  Sana nasıl ayla selam yolladım, Hayatımı yollarına adadım, Sen bir gülsün, gül bunları ne bilsin. Bir bils...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bos-bahcede-isim-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şartlı salıverilmiş dostluk', 'sartli-saliverilmis-dostluk-murat-tali-ykebt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'günaydın 

şartlı 

salıverilmiş 

dostluğum

kaçıncı badireden çıkışımdır sensiz biliyor musun

kaçıncı tek başına güneşe varışım

hangi şarta bağladın kendini ses vermiyorsun

dost dediğin 

aynı yağmuru paylaşmalıdır derlerdi.

Islansa da 

Kaçsa da bir saçak dibine

birlikte olmaktı dostluk

oysa

bir şarkının

şartlı salıverilmiş nakaratları gibiydik

aramıza uzun dizeleri olan bir dörtlük girdi

bu yüzden midir uzaklığın? 

şimdi bir nakarat sen diğer nakarat ben

aramızda 

hasreti anlatan bir dörtlük

ve 

uzunca bir keman taksimi', 'günaydın  şartlı  salıverilmiş  dostluğum kaçıncı badireden çıkışımdır sensiz biliyor musun kaçıncı tek başına güneşe varışım hangi şarta ba...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sartli-saliverilmis-dostluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Çizgi', 'i-nce-cizgi-reyhan-sur-ksnmk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'öyle durma uzakta yanıma uzan

saçını okşayan anneyim bugün

ağaçtan ağaca sekip oynaşan

kuş cıvıltılarına yuvayım bugün

nazara karşı okunmuş duan

göğsünde taşıdığın cevşenim bugün

dağılmış saçlarımın serenadında

renk ve notalara soluğum bugün

çevrende fırdöndü topaçlar gibi

saçımdan tırnağa geyşayım bugün

bin bir çiçek özlü arı kovanın

petekten sızdırılmış damlayım bugün

yüreğine her dem sevdayla akıp

başını döndüren suyunum bugün

ve can tanem her gün sen

sen her gün

tükenmeyen kıvancım

hep büyüyen dal ucum

çayımda tatlı buhar

uzaklarda sesimsin

sen

yürek atışımdaki ince çizgimsin', 'öyle durma uzakta yanıma uzan saçını okşayan anneyim bugün ağaçtan ağaca sekip oynaşan kuş cıvıltılarına yuvayım bugün nazara karşı okunmuş ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ince-cizgi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül''de Kalacaksın', 'eylul-de-kalacaksin-i-hsan-dinibutun-7u9b8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben yaşlı bir adam

Sen liseli bir kızsın

Ömrümde Yaşadığım 

İkinci baharımsın

Seni çok sevsem, istesemde

Sen her zaman

Eylül''de kalacaksın', 'Ben yaşlı bir adam Sen liseli bir kızsın Ömrümde Yaşadığım  İkinci baharımsın Seni çok sevsem, istesemde Sen her zaman Eylül''de kalacaksın...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/eylul-de-kalacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ancak O Zaman', 'ancak-o-zaman-reyhan-sur-81jd5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hissettiğim sadece

sadece.. kırmızı bir uğultu

istediğim

çok derin

karlar üzerinde

bembeyaz..

çok derince bir uyku', 'hissettiğim sadece sadece.. kırmızı bir uğultu istediğim çok derin karlar üzerinde bembeyaz.. çok derince bir uyku...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ancak-o-zaman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hümanistim...', 'humanistim-yusuf-ziya-leblebici-j59gt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim doğrum beynimdedir

Yıkılamaz benim sevgim 

Aşkım dinim kalbimdedir

Hü de hü de hümanistim

İnsanları ben bilmişim

Gönlüme tesbih dizmişim

Dost dost diye inlemişim

Hü de hü de hümanistim

Gül dururken dikenleri

Göndermeyin üzerime

Bizi düşman görenleri

Güldürmeyin yüzümüze

İnsanları insan bilmek

Maske değil içten sevmek

Boynumuzun borcu olsun

Adım adım dosta gitmek

Kol kanadı size gerdim

Yüreğimi yola serdim

Gelin canlar, gelin dostlar

Hü de hü de hümanistim', 'Benim doğrum beynimdedir Yıkılamaz benim sevgim  Aşkım dinim kalbimdedir Hü de hü de hümanistim İnsanları ben bilmişim Gönlüme tesbih dizmiş...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/humanistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Önemli Şey', 'i-ki-onemli-sey-melek-anne-gcp0n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgili,

İnsanın hep karşı cinsten  beğendiği, sevdiği hatta aşık olduğu insan değildir...

Aşık olmak,

İnsanın karşı cinsten birini beğenmesi,sevmesi değildir...

Ve...

Size son bir şey:

BEN SANA AŞIĞIM SEVGİLİ ANNECİĞİM! 

BEN SANA AŞIĞIM SEVGİLİ BABACIĞIM!', 'Sevgili, İnsanın hep karşı cinsten  beğendiği, sevdiği hatta aşık olduğu insan değildir... Aşık olmak, İnsanın karşı cinsten birini beğenmes...', ARRAY['Türk Edebiyatı','Şiir','Melek Anne']::text[], 8.5, '{"poet":"Melek Anne","poet_slug":"melek-anne","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/iki-onemli-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eh', 'eh-huseyin-burak-us-goqwf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tanrım ellerim ne kadar küçük

bu kız biraz daha sarılamaz mı bana', 'tanrım ellerim ne kadar küçük bu kız biraz daha sarılamaz mı bana...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Burak Us']::text[], 8.5, '{"poet":"Hüseyin Burak Us","poet_slug":"huseyin-burak-us","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/eh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tokluk hissi', 'tokluk-hissi-murat-tali-e3mlz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'domates ekmek ve peynir 

sonra ekmeği bir banacan domatesin suyuna 

kızıllaşacak ekmek 

üzerine beyaz lor peyniri tuzlu tuzlu

güneşin batışı ufuktan

ve

tokluk hissi 

düşüncelerimin', 'domates ekmek ve peynir  sonra ekmeği bir banacan domatesin suyuna  kızıllaşacak ekmek  üzerine beyaz lor peyniri tuzlu tuzlu güneşin batışı...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tokluk-hissi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sil Baştan', 'sil-bastan-emel-manav-4nb2e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herkesin derdi de kederi de kendine. 

Edemez bir ordu insanın ettiğini kendine 

Problemleri büyütüp getirdin yumak haline 

Hüzünler yarattın, dünyanı kararttın 

Geçtiğin yolu hep uzattın. 

Unutma çocuklarda basacak o taşlara 

Aklını başına toplayacaksan topla 

Yoksa ters dönersin atarsın takla 

Aç mezarı yok, genç mezarı var. 

Sen ara Rabbim verir her rızkı 

Yeter ki hayata sarıl sımsıkı 

Acıma kendine şükret haline. 

Ümitsiz hastalarla dolu hastane 

Bak sağlıklısın işte, koç gibi 

‘Geç kaldım deme’ bunlar bahane 

Bak güneş yine doğdu,şahane 

Sarıl hayata, koş, dene 

Sil baştan!', 'Herkesin derdi de kederi de kendine.  Edemez bir ordu insanın ettiğini kendine  Problemleri büyütüp getirdin yumak haline  Hüzünler yarattın...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sil-bastan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurun Beni Yerden Yere', 'vurun-beni-yerden-yere-emel-manav-toize', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tahsil... hak getire 

boyalı laflar da bilmem, 

arama bende. 

dümdüz yazarım 

aklıma geleni sadece 

alınmayın şair dostlarım, 

yarışım olmaz sizinle 

konuşamadıklarımı dökerim 

kara kaplı deftere 

haddimi aşmak mı asla! 

okuyun yazdıklarımı 

ne olur, yalvarırım 

eleştirin, yerden yere vurun 

isterseniz. 

bende mangal gibi yürek var 

elinizi de öper, af da dilerim 

gerekirse. 

üstat sizsiniz, 

destek verin bana, 

bırakmayın yalnız. 

hepimiz etten, kemikteniz nihayet 

bir kul var mı,yaşamış mı hatasız? 

benim size sevgimde, 

saygımda sonsuz.', 'tahsil... hak getire  boyalı laflar da bilmem,  arama bende.  dümdüz yazarım  aklıma geleni sadece  alınmayın şair dostlarım,  yarışım olmaz...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vurun-beni-yerden-yere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahrol Sevda Kahrol', 'kahrol-sevda-kahrol-murat-demir-watac', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Varlığı esaret yokluğu hasret

Ne yapsan içini yaralıyor dert

Her gün diye diye ya gönül sabret

Bak gönlüm taş oldu ben tele döndüm

Kara gün derlerya bu imiş meğer 

Eriterek yiyor düşersen eğer

Bu nasıl kıymetmiş bu nasıl değer

Bak gözüm yaş oldu ben sele döndüm! 

Yollarına bakan durmadan benken

Kavuşurum diye hayal ederken

Kahrol sevda kahrol bu kadar erken

Bak eller yar oldu ben ele döndüm', 'Varlığı esaret yokluğu hasret Ne yapsan içini yaralıyor dert Her gün diye diye ya gönül sabret Bak gönlüm taş oldu ben tele döndüm Kara gün ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kahrol-sevda-kahrol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygularım Hüzün Kokar', 'duygularim-huzun-kokar-emel-manav-yakyk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duygularım Hüzün Kokar 

Hey! Dostlarım, dostluklarım 

Geçip gider de beyhude yıllar 

Duygularım hüzün kokar 

Yanarım. 

Hep sitem,hep kahır, hep isyan 

Dayan ah! Allah’ım dayan 

Biz anamızdan sevgisiz mi doğduk 

Yoksa, yoksa sonradan mı unuttuk? 

Yar diyarının güzel insanı 

Yaşamadı hiç, 

Korkmadı da yoksulluktan... 

Karının kocaya, evladın babaya 

Sevgiye saygıya,ihtiyacı var, 

Adetlerimize sahip çıkmalı 

Gitti gidiyor diye 

Seyirci kalmamalı... 

Bize kalanı kurtaralım, 

Sözümüz yazıda kalmasın dostlar! 

Etrafta kurtlar var,aç kurtlar. 

Kovalım gitsin. 

Gün bu gün, birlik olma günü 

Sofradaki ekmeğimizi çalan 

Günahtır, haramdır demeden talan 

Ettiler. 

O hain,aç gözlü kurtlar! !', 'Duygularım Hüzün Kokar  Hey! Dostlarım, dostluklarım  Geçip gider de beyhude yıllar  Duygularım hüzün kokar  Yanarım.  Hep sitem,hep kahır, ...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/duygularim-huzun-kokar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizem büyüsü', 'gizem-buyusu-sedat-tuvar-k2wut', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep gözlerimin önündeydin

hep yöremde,

hep yanımda.

Kim yapmış

niye yapmış

bilemem ama...

Büyü olmalı bu

gizem büyüsü,

benle sana...

Aşk olsun bana,

aşık olamadım sana,

büyüyede inanmam ama...', 'Hep gözlerimin önündeydin hep yöremde, hep yanımda. Kim yapmış niye yapmış bilemem ama... Büyü olmalı bu gizem büyüsü, benle sana... Aşk ols...', ARRAY['Türk Edebiyatı','Şiir','Sedat Tüvar']::text[], 8.5, '{"poet":"Sedat Tüvar","poet_slug":"sedat-tuvar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gizem-buyusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmansız', 'i-mansiz-murat-demir-q9yko', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne oldu sana ki gidiyor muşsun

Daha kavramadan yar sarmasını

Benim için artık yok diyor muşsun

Sen kimden öğrendin ayrılmasını

İmansız vicdansız soysuz kitapsız

Demek ben diline bal olamadım

Ne yaptım ki sana söyle allahsız

Dikenli gülüne dal olamadım! 

Topla ne var ne yok koy bir yanına

Benden aldıkların nafakam olsun

Demek biz de geldik yol ayrımına

Neyleyim yine de canın sağ olsun

İmansız vicdansız soysuz kitapsız

Demek ben diline bal olamadım

Ne yaptım ki sana söyle allahsız

Dikenli gülüne dal olamadım', 'Ne oldu sana ki gidiyor muşsun Daha kavramadan yar sarmasını Benim için artık yok diyor muşsun Sen kimden öğrendin ayrılmasını İmansız vicda...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/imansiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne gerek', 'ne-gerek-sedat-tuvar-ql3rx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elimi tuttuğunda 

Beni de tuttun sandım

Niye

Sürüklendik ıssız yollara

Dar ve karanlık sokaklara

Neden

Mermilerle dans ettik

Şakağımızı dayadık kimi zaman silahlara

Gel dedin en tepeye

Çiyanlar dolaştı ayaklarımıza

Ne gerek vardı

Göstereceğin bumuydu

Gök yüzünde hepsi hepsi birkaç kuru yıldız

Hani tek tek düşüp yok olan

Ben onların en güzellerini

Ben onların en parlaklarını

Şehrin göbeğinde kimi zaman 

Işıldayan gecelerde

Gün ışığında güneş in en acımasız parladığında

Sıradan bir günde mesela

Sıradan zamanlarda

Senin hiç haberin yokken

Ben o yıldızları senin gözlerinde hep saydım

Hani hiç düşmeyen

Hani hep parlayan', 'Elimi tuttuğunda  Beni de tuttun sandım Niye Sürüklendik ıssız yollara Dar ve karanlık sokaklara Neden Mermilerle dans ettik Şakağımızı daya...', ARRAY['Türk Edebiyatı','Şiir','Sedat Tüvar']::text[], 8.5, '{"poet":"Sedat Tüvar","poet_slug":"sedat-tuvar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ne-gerek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Yetiyor', 'bana-yetiyor-caner-kuru-715uw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne umdum, ne buldum, bu genç yaşımdan,

Hiç dert eksilmiyor garip başımdan,

Uzak dur ne olur, çekil karşımdan,

Benim acım zaten bana yetiyor.

Dertler sarartmasın güzel yüzünü,

Yaşlar karartmasın iki gözünü,

Seviyorum deme duymam sözünü,

Benim acılarım bana yetiyor.

Gülmüyor yüzüme ne şans ne kader,

Bulaşmasın benden sana gam keder,

Gitmezsen seni de perişan eder

Benim acılarım bana yetiyor.', 'Ne umdum, ne buldum, bu genç yaşımdan, Hiç dert eksilmiyor garip başımdan, Uzak dur ne olur, çekil karşımdan, Benim acım zaten bana yetiyor....', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bana-yetiyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keyiflen', 'keyiflen-hurrem-yalcin-gzdp9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Keyiflen haydi durma

Yak sigarayı

Çek ciğerine dumanı

Aç birayı

Soğukta olmalı

Bardağın dışı buğulu

Çal sevda türkülerini

Sil yüreğinin pasını

Kavuştur sevenleri

Şimdi kavuş zamanı

Haydi durma

Keyiflen artık ama! ...

18.06.2004', 'Keyiflen haydi durma Yak sigarayı Çek ciğerine dumanı Aç birayı Soğukta olmalı Bardağın dışı buğulu Çal sevda türkülerini Sil yüreğinin pası...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/keyiflen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanacaksam Yanayım', 'yanacaksam-yanayim-caner-kuru-i880d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yanacaksam yanayım uzat elini,

Kanacaksam kanayım ver de sevgini,

Onca naz, onca cilve, kaprisler yeter,

Saracaksam sarayım, ince belini.

Bu zavallı yüreğim çok mu şey ister? 

Kırma ne olur beni, vefanı göster.

Hiç düşünme sen onu, elalem ne der? 

Tutacaksam tutayım, uzat elini.

Yapayalnız bırakma beni burada,

Ya canımı al götür, gönlümü ya da,

Dert verirmiş diyorlar, her büyük sevda,

Çekeceksem çekeyim senin derdini.', 'Yanacaksam yanayım uzat elini, Kanacaksam kanayım ver de sevgini, Onca naz, onca cilve, kaprisler yeter, Saracaksam sarayım, ince belini. Bu...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanacaksam-yanayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkıl Karşımdan', 'yikil-karsimdan-caner-kuru-krhr4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geldiğin gün başladı,

Ah çekmeye şu gönlüm,

Geldiğin gün ağladı,

Sel oldu iki gözüm.

Sen benim bu gönlümü,

Ağlatmaya mı geldin? 

Sen benim gözyaşımı

Çağlatmaya mı geldin? 

Yıkıl karşımdan, yıkıl karşımdan,

Çekil başımdan, git ne olursun.

Bir hayal gibi başlamıştın ya,

Bir hayal gibi, bit ne olursun.', 'Geldiğin gün başladı, Ah çekmeye şu gönlüm, Geldiğin gün ağladı, Sel oldu iki gözüm. Sen benim bu gönlümü, Ağlatmaya mı geldin?  Sen benim g...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yikil-karsimdan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzlerde Kaybolmak', 'yuzlerde-kaybolmak-bahri-karaduman-hvrup', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'özlem aşk ister sevgili

aşk büyütür özleyişleri

yürek borcu kan damlası

yoğrulursun kendi kederinle

ıssızlaşır yaşamın

yaşadığın yalnızlığındır

yorgun düşersin düşlemekten

geceler karanlığın gözleridir senin için

sabah yeli yeni sancılar üfler yüzüne

gün yeni doğumlarıdır yaşlı yüzlerin

yüreğin

yeşerme umudunu yitirmiş boz topraklar gibidir

yazgı değişmez bir türlü

özlem büyür yalnızca

aşkın seninledir

çoğalmıştır kan damlaları

yankısı bile kalmaz sesinin

tükenir yok olursun kendi içinde

yürür gidersin sen de

zamana karışmış tüm insanlar içinde', 'özlem aşk ister sevgili aşk büyütür özleyişleri yürek borcu kan damlası yoğrulursun kendi kederinle ıssızlaşır yaşamın yaşadığın yalnızlığın...', ARRAY['Türk Edebiyatı','Şiir','Bahri Karaduman']::text[], 8.5, '{"poet":"Bahri Karaduman","poet_slug":"bahri-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yuzlerde-kaybolmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Düşmüş', 'bana-dusmus-mumtaz-begen-ulez7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kul için ne varsa pay eylemişler,

Arsızlık ellere, ar bana düşmüş…

Arsızlık edenler hâlin demişler,

Ar eyledim diye, dar bana düşmüş…

Gülmesin kimseler, aman ha aman! 

Ne tende can koydu, ne canda iman.

Yaz olsun, kış olsun başımda duman,

Var eyledim diye, kar bana düşmüş…

Kiminin gönlünü taş eylemişler,

Kiminin gözünü yaş eylemişler,

Gülü Bülbül’ünen eş eylemişler,

Zâr eyledim diye, yâr bana düşmüş…

Ağza göre lokma yutmak yerine,

Yan gelip keyifle yatmak yerine,

Sabredip dilimi tutmak yerine,

Car eyledim diye, nar bana düşmüş…

Mamur olan gönlüm virane gibi,

Dolaşmışım deli, divane gibi,

Narın etrafında pervane gibi,

Tur eyledim diye, har bana düşmüş…', 'Kul için ne varsa pay eylemişler, Arsızlık ellere, ar bana düşmüş… Arsızlık edenler hâlin demişler, Ar eyledim diye, dar bana düşmüş… Gülmes...', ARRAY['Türk Edebiyatı','Şiir','Mümtaz Beğen']::text[], 8.5, '{"poet":"Mümtaz Beğen","poet_slug":"mumtaz-begen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bana-dusmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Hesapta Yoktun', 'hic-hesapta-yoktun-can-ceylan-ns2mk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç hesapta yokken çıktın karşıma

Çember daralırken girdin kanıma

Tanıyor gibiydim maziden seni

Öylesi yakındın sıcaktın bana

İçimdeki tabu yıkılmaz derdim

Sevginle arama set koyamadım

Günleri sıradan farksız bilirdim

Seninle geçene hiç doyamadım

Gönlümde tomurcuk bir gül gibisin

O mahsun gülüşün hiç solmayacak

Ruhuma işleyen nehir gibisin

O nazlı akışın son bulmayacak

İnan ki ömrümce hep seveceğim

Karşıma çıkmanı şans bileceğim

Gitmeliyim dersen eğer ki bir gün 

Ne yazık yaşanan düş diyeceğim', 'Hiç hesapta yokken çıktın karşıma Çember daralırken girdin kanıma Tanıyor gibiydim maziden seni Öylesi yakındın sıcaktın bana İçimdeki tabu ...', ARRAY['Türk Edebiyatı','Şiir','Can Ceylan']::text[], 8.5, '{"poet":"Can Ceylan","poet_slug":"can-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hic-hesapta-yoktun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni', 'bekle-beni-abdullah-atay-zpfbg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzel martı.

Yükseklerde süzüm süzüm süzülüp

Ne olur bana tepeden bakma! ...

Alıcı kuşlar gibi

Bağrışıp çağrışıp

Nafile yere hava atma.

Biz zaten

Milletçe feryat, figan

Kuru gürültülerden bıktık

Derdime dert katma! ..

Sevdigim gelince  bak simdi

Ben de bulutlardayım artik.

Sakın bunu unutma...', 'Güzel martı. Yükseklerde süzüm süzüm süzülüp Ne olur bana tepeden bakma! ... Alıcı kuşlar gibi Bağrışıp çağrışıp Nafile yere hava atma. Biz ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bekle-beni-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fingridek Kız', 'fingridek-kiz-sirma-mersin-knz0f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eteğini belinden kıvırmış

Gömleğin bikaç düğmesini açmış

Sallana sallana yürüyordu

Ağzında sakız

Boyalı dudakları ile

Saçlarını savuruyordu

Mahallenin tüm erkekleri peşinde dolanıyor

Kadınları ise şaşırıyordu

Her gün daldan dala  konuyor

Hayalleri için herkesi kullanıyordu

Para amaç  olmuş

Lüks yaşantı için kendini düşünüyordu  sadece

..............................................................................

..............................................................................

Bugünü yaşıyordu

Sonunda bir zenginin yüreğini çaldı

Ve

Mutluluğunu sahte gösterişli bi yaşama bıraktı kendini

Derken 

Sabahın ışıkları ile uyandı

O 

Hala mahallenin fingridek kızı...

Yeni güne kalmış hayalleri ile

Dolanacaktı kaldırımlarda....

18.06.04

................................. Fahriye Abla''dan esinlenerek yazılmış bi şiir......', 'Eteğini belinden kıvırmış Gömleğin bikaç düğmesini açmış Sallana sallana yürüyordu Ağzında sakız Boyalı dudakları ile Saçlarını savuruyordu ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/fingridek-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım', 'asigim-zeliha-ural-iu6xp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sevene aşığım

Sevilene değil

Ben öğretene aşığım

Öğrenene değil

Ben Dostluğa aşığım

Göz boyamaya değil

Ben kalbine, yüreğine aşığım

kendine değil', 'Ben sevene aşığım Sevilene değil Ben öğretene aşığım Öğrenene değil Ben Dostluğa aşığım Göz boyamaya değil Ben kalbine, yüreğine aşığım kend...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Ural']::text[], 8.5, '{"poet":"Zeliha Ural","poet_slug":"zeliha-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/asigim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-ozan-olgac-oq0ri', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin yüreğin soğudu sadece

Hiçbir şey kaybetmedin kendinden.

İçindeki ateş, hiçbir zaman sönmeyecek,

Bir gün yeniden ısıtacak seni...

Soğuk havalarda dolaşma fazla,

Baktın rahatsız oluyorsun

Çek git, göçmen kuş misali.

Ruhun hep sıcak kalsın içinde...

Rüzgarda durma fazla

Baktın  bir ürperti geldi içine,

Kapat kapını pencereni, kal biraz öylece,

İçerde, kendinle...

Hadi... Üzerine birşeyler ört.

Ayağını koma açıkta...

Kıvrıl iyice yorganının içine,

Başını göğsüme yasla.

Senin yüreğin soğudu sadece

Hiçbir şey kaybetmedin kendinden.

İçindeki ateş, hiçbir zaman sönmeyecek,

Bir gün yeniden, ısınacaksın...', 'Senin yüreğin soğudu sadece Hiçbir şey kaybetmedin kendinden. İçindeki ateş, hiçbir zaman sönmeyecek, Bir gün yeniden ısıtacak seni... Soğuk...', ARRAY['Türk Edebiyatı','Şiir','Ozan Olgaç']::text[], 8.5, '{"poet":"Ozan Olgaç","poet_slug":"ozan-olgac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/umut-122-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessss', 'sessss-hurrem-yalcin-pqbqr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elde sessizdik

Dilde sessizdik

Gözde sessizdik

Yürekte sessizdik

Sessizliğin sesine 

Birlikte kulak verdik! ....

21.06.2004', 'Elde sessizdik Dilde sessizdik Gözde sessizdik Yürekte sessizdik Sessizliğin sesine  Birlikte kulak verdik! .... 21.06.2004...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sessss-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı söyledim bütün dillerde', 'aski-soyledim-butun-dillerde-zeliha-ural-hkuox', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkı söyledim bütün dillerde

Aradım durdum nice gönüllerde

Seni bahane ettim de her yerde

Arsıza döndürdü bu yürek beni

Susmayı bilmedi ah edip durdu

Bahane aşkı, hep onu sordu

Yılmadı  hayalinle, oyalanıp durdu

Arsıza döndürdü bu yürek beni

Kah kerem oldu

Buldu sandı sevdayı

Kah mecnun oldu 

Buldu sandı Leylayı

Arsıza döndürdü bu yürek beni

Sanmasınlar aşkının esiri 

bu sevdanın yok ki, hiçbir iksiri

Müebbete çevirirken o garibi

Arsıza döndürdü bu yürek beni', 'Aşkı söyledim bütün dillerde Aradım durdum nice gönüllerde Seni bahane ettim de her yerde Arsıza döndürdü bu yürek beni Susmayı bilmedi ah e...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Ural']::text[], 8.5, '{"poet":"Zeliha Ural","poet_slug":"zeliha-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aski-soyledim-butun-dillerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Kalan Sevda', 'senden-kalan-sevda-zeliha-ural-plv7m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sendan kalan sevdayı,

Herdem artan bir özlem,

Bir hayal olarak,

Bırak, öyle hatırlayayım

Saçların siyah, yada sarı,

Bende mi kalmıştı, Yoksa! 

Sende mi bir yarı.

İçim acıyor.

Hep sensiz, sessizdir çığlıklarım.

Utanıyordu,adını anmaktan; 

Bu dudaklar.

Gözyaşlarım utanıyordu

Ve kimse anlamadı

Ve yine ben senin için ağladım

Ve biliyormusunki ölenedek..

Ağlayacağım.

Dedilerki çok sevmenin nazarıymış bu 

Ben seni öyle sevdim ki.......', 'Sendan kalan sevdayı, Herdem artan bir özlem, Bir hayal olarak, Bırak, öyle hatırlayayım Saçların siyah, yada sarı, Bende mi kalmıştı, Yoksa...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Ural']::text[], 8.5, '{"poet":"Zeliha Ural","poet_slug":"zeliha-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/senden-kalan-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın Davet Ederse', 'kadin-davet-ederse-ahmet-turan-altunsu-242cc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(arada bir duygulara takılır oltalar / ne zararı var bunun? 

  / en nihayet; günahsız ve sıradan voltalar…) 

kadın davet ederse yer gök tir tir titreyecek,

can ve canan birleşip, arslanca kükreyecek! 

birlikte sevişmenin

…dayanılmaz arzusu

……hiddetlendirir birden; 

ve can… ve canan aşkı

…ilham alır şiirden:

……sevişme terkîbine

………döner aşık duygusu! ...

kadın davet ederse,

hayata davet çıkar

…o ölümcül zehirden! 

           19.06.2004 / Ankara', '(arada bir duygulara takılır oltalar / ne zararı var bunun?    / en nihayet; günahsız ve sıradan voltalar…)  kadın davet ederse yer gök tir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kadin-davet-ederse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir', 'zincir-reyhan-sur-xbboj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'adam gibi adam bizlersek eğer 

elbet öyledir

öyleyse sen 

ko ortaya yüreğini 

sırt sırta ver

işte bilek 

işte yürek

dik gözlerini inatla güneşin 

sarı beneklerine 

örgütlen emeğinle

görsün ki ışık neymiş 

yedi düvel... 

boş davalarla uğraşmayıp,milli değerlerimize ve ulusal onurumuza sahip çıkan sevgili halkıma...', 'adam gibi adam bizlersek eğer  elbet öyledir öyleyse sen  ko ortaya yüreğini  sırt sırta ver işte bilek  işte yürek dik gözlerini inatla gün...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zincir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses', 'ses-ozan-olgac-2ijzc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sadece, kuşların sesini duymak istiyorum,

Gökyüzünden üzerime...

Ne ışık istiyorum, ne de yıldız,

Sadece, kuş sesi...

-Hayatımda değişmeyen tek şey-

Ne kadar hüzünlü olsam da,

Ne kadar gülüyor olsam da,

Değişmeyen o sesi...

Ama...

Şimdi bir ses daha var kulaklarımda,

Değişmeyen bir ses daha,

Bilinmeyenden, yüreğime...

Artık...

Hem ışık olsun istiyorum,

Hem de yıldız...

Ve o ses,

Hayatımda değişen tek şey...

Ne kadar kirli olsam da yaşam yüzünden,

Ne kadar sıradanlaşsam da zaman yüzünden,

Her gün değişen,

Senin yüreğinden, benim yüreğime,

Bir ses daha var kulaklarımda,

Değişik bir ses daha...', 'Sadece, kuşların sesini duymak istiyorum, Gökyüzünden üzerime... Ne ışık istiyorum, ne de yıldız, Sadece, kuş sesi... -Hayatımda değişmeyen ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Olgaç']::text[], 8.5, '{"poet":"Ozan Olgaç","poet_slug":"ozan-olgac","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ses-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında', 'aslinda-bekir-mutlu-gokcesu-unrmu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Delilik bu 

Görünmeyen yıldızlara

Sunmak gibi

Gözlerinin geceyi

Kadehlerce içen ferini...

Dolu dizgin bir yüreğin

Yaşanmıştan öte

Yaşanmamışlıklarıdır

Aslında tüketemediği...

Ve kimi

Birden algılaman gibi

Aslında

Hiç gelmeyeceğini...

O an

Işıklarını yitirir gece

Gözlerinde... 

Ve karışmak istersin

Görünmezlere...', 'Delilik bu  Görünmeyen yıldızlara Sunmak gibi Gözlerinin geceyi Kadehlerce içen ferini... Dolu dizgin bir yüreğin Yaşanmıştan öte Yaşanmamış...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aslinda-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir', 'bu-sehir-i-smail-baharsen-1ftrw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu şehrin sokaklarında hatıraların

her köşe başında hayalin var

dolaşsam şehri adım adım

yerlerde dökülen yaşların var

bu şehrin armağanısın bana sen

bitmeyen bir gecenin sonunda gelen

her geçtiğimde yüzüme gülen

kaldırımlarda saklı izlerin var

bu şehrin ağaçlarında ismin kazılı

hala aklımda bakışın tatlı

biten bir aşkın tüter dumanı

yollarda bana gelen gidişin var...', 'bu şehrin sokaklarında hatıraların her köşe başında hayalin var dolaşsam şehri adım adım yerlerde dökülen yaşların var bu şehrin armağanısın...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-sehir-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı''nın Çektiği Acı', 'aci-nin-cektigi-aci-i-smail-baharsen-sfweh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sorun bir acı denen zavallıya

kaç mevsim kışladı gönlümde

sorun beni çile''ye derde gam''a

acı benden bıktı ben acıdan

bazen hatıra deyip bastım bağrıma

bazen kan oldu doldu avcuma

köşe başlarından çıktı karşıma

acı benden kaçtı ben acıdan

isyan ettim gelmesin diye

bana bir hüzün vermesin diye

gönlüme kimse girmesin diye

acı benden acı ben acıdan

döktüm sayfalara kurtulamadım

yüzünden rahat bulamadım

hicrana mahkum kaldım

acı benden davacı ben acıdan', 'sorun bir acı denen zavallıya kaç mevsim kışladı gönlümde sorun beni çile''ye derde gam''a acı benden bıktı ben acıdan bazen hatıra deyip bast...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aci-nin-cektigi-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve...', 've-tansel-yucelen-sreop', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '...

sonu olmayan bir film

                 izlemek

ya da hiç bitmeyen bir şarkıya 

                         dokunmak

bitmeyen bir hikayeyi

                   okumak

ya da uçsuz satırlar

                  yazmak

deniz kenarında durmadan

                     yürümek

ya da gökyüzünün derinliklerini

                           izlemek

uçurumdaki tükenmeyen rüzgar

                         olmak

ya da seninle sonsuzlukta

                      kaybolmak

her an

   her saniye

      seni duymak

            seni solumak

      sana dokunmak

            seni sarmak

her an

   seninle olmak

          ruhuna bakmak

          kalbinde durmak

her an

benliğinle sonsuzluktaki iki yıldız

                                olmak

ve... 

seninle o sonsuzlukta

                        kaybolmak

sadece seninle

...', '... sonu olmayan bir film                  izlemek ya da hiç bitmeyen bir şarkıya                           dokunmak bitmeyen bir hikayeyi  ...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ve-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan,Ömür,Ve Gerçekler', 'i-nsan-omur-ve-gercekler-i-smail-baharsen-qsxjt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gönül vardır gönülden üstün

insan vardır insandan üstün

herşeyiyle dünya bir bütün

sevgi vardır sevgiden üstün

koca bir aşk sığar kimisine

her mevsim kar yağar kimisine

bir eser bırakmışsa gerisine

ömür vardır ömürden üstün

kalleşi doymaz dedikoduya

bir söz üstüne söz koymaya

kıyamayan bir kalbi kırmaya

dil vardır dilden üstün

kiminde hayaldir şan şöhret

kiminde rüyadır bir lokma ekmek

kimince riyadır sevmek sevilmek

ümit vardır ümitten üstün

yanar gurbette gönül evi

yakar gurbette aşk ateşi

arar gönül sevgi vereni

yangın vardır yangından üstün

evlat der yar der yürek 

bu düzene sabır gerek

boşa gider onca emek

yara vardır yaradan üstün

ömrü kısadır yalan ise 

kimisi gerçek kimi sahte

gizlidir gözde gönüllerde

sevda vardır sevdadan üstün

sevda koyar adamı dara

mahkum eder dört duvara

gönül gurbetçidir sılada

zindan vardır zindandan üstün

her kalpte saplı bir hançer

insanı yok eder bu mahşer

gün geçer devran döner

zaman vardır zamandan üstün

geceyi bekler yaralı yaralı

içinde binbir derdi sıralı

bahtı ezelden beri karalı

adam  vardır adamdan üstün

kaybolur beden varlar içinde

yokolur beden aşklar içinde

neler var bak yeryüzünde

yalnız vardır yalnızdan üstün

köşe başında yığılan kimsesiz

kimisi ölür gider çilesiz dertsiz

biri taşa muhtaç birisi geniş

ölüm vardır ölümden üstün...', 'gönül vardır gönülden üstün insan vardır insandan üstün herşeyiyle dünya bir bütün sevgi vardır sevgiden üstün koca bir aşk sığar kimisine h...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/insan-omur-ve-gercekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığımın Şiiri', 'yalnizligimin-siiri-safak-ozdemir-s2m6d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unutmak kolay demiştin! 

Çekerken gözlerini,gözlerimden,

Unutursun demiştin.

Bırakırken ellerimi, usulca ellerinden.

An gelirde, gülersin demiştin duygularına.

Yalanmış hepsi yalan! 

Bak hala titriyor nefesim, adını andıkça.

Hala buğulanıyor gözlerim,resimlerine baktıkça.

Ah! Ne ben seni unutabildim,

Ne deniz! 

Ne martılar! 

Ne İzmir...

Unutmak mümkünmü sevgilim seni bu şehirde.

Kokun sinmiş bir kere denize.

Kahkahaların,çığlık çığlık martıların kanatlarında.

Dolaşıyor ayak seslerin,

Islak loş kaldırımlarda.

Sıcaklığın sıcaklığın,hala avuçlarımda.

Bu gün dolaştım yine o yerleri bir bir.

Sensiz! 

YapayalnızA! 

Ağlamaklı...

Gökyüzünde bakır rengi bulutlar,

Kül rengi deniz, bir kaç yorgun martı.

Ufukta kaybolan güneş, yok olan umutlar,

Yalnızlık yalnızlığım.

Sensiz bir akşamı daha yaşıyor İzmir.

Soluk soluğa, gül kurusu, sevda karası.

Ağlıyor uzaklarda,hıçkıra hıçkıra vapurlar.

Ben ise bekliyorum hala seni,

Bekliyorum Kordon''da.

Gözlerim nemli, duygularım öylesine karmaşık.

Saat onikiyi vurduğunda,

Bir ben kalmıştım sahilde,

Birde şarkılar mırıldanan ihtiyar dilenci.

O da uzandı az sonra bir banka,

Çekti üzerine iki sayfalık yorganını,

Dikti iri gözlerini,umutla ufuklara,

Daldı daldı gitti karanlıklara.

Yine kalmıştım,anılarımla,gözyaşlarımla,

Çoban Yıldızıyla baş başa.

Derken bir rüzgar esti Yunan adalarından.

Sildi gözyaşlarımı ak mendiliyle,

Eğildi birşeyler fısıldadı kulağıma,

Beni teselli edercesine.

Yook yok! 

Seni istiyor bedenim,

Ruhum seni istiyor.

Seni istiyor,ellerim, gözlerim, dudaklarım...

Seni istiyor,deniz, martılar, vapurlar...

Seni seni istiyor Şafaklar.

Seni seni istiyorum! ..', 'Unutmak kolay demiştin!  Çekerken gözlerini,gözlerimden, Unutursun demiştin. Bırakırken ellerimi, usulca ellerinden. An gelirde, gülersin de...', ARRAY['Türk Edebiyatı','Şiir','Şafak Özdemir']::text[], 8.5, '{"poet":"Şafak Özdemir","poet_slug":"safak-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/yalnizligimin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Nedir Anne', 'sevgi-nedir-anne-i-smail-baharsen-win1v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sevgi nedir anne,bilmiyorum ben

bir kardelen kokusumu soğukta donan

sevgi nedir anne..

gökyüzünde asi bir bulutmudur yoksa

günden güne yağamayan kararan

sevgi nedir anne..

bir ıslak yaz gecesimi seninle olduğum

başımı yaslayıp dizlerine koyduğum

sevgi nedir anne..

şiirlerde arayıp şarkılara sorduğum

en sonunda sende bulduğum

sevgi nedir anne...

yıldızlarca rüyamı,hayalmi uçsuz bucaksız

bir gülmü titrek su damlalarıyla bezenmiş

sevgi nedir enne...

karanlık karanlık büyüyen gecelerde 

gözüm kapalı arayıp bulamadığım

sevgi nedir anne...

bir bağmı böylesine bağlayan gönülden gönüle

bir aşkmı hasretine ağlatan gözden göze

yoksa bir yalanmı düşen dilden dile

anlat bana sevgiyi anne.. 

anlatki anlayayım bütün herşeyi

anlayayımki sevgi denen nesneyi

bende seveyim seni anne....', 'sevgi nedir anne,bilmiyorum ben bir kardelen kokusumu soğukta donan sevgi nedir anne.. gökyüzünde asi bir bulutmudur yoksa günden güne yağam...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevgi-nedir-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Diyemedim', 'elveda-diyemedim-i-smail-baharsen-a3482', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''aşk beni terketti ama ben seni...''

çok düşündüm kendi kendime 

belki gecelerce belki günlerce

her köşe başından döndükçe

sana kıyıp elveda diyemedim

keşke buraya kadar gelmeseydi

gönlümüz muradına eremedi

o üç hece dilime  geldi geldi gitti

sana kıyıp elveda diyemedim

kaç kez yırttım yazdığım mektupları

kaç kez dolaştım sizin sokakları

biri mühürlemiş bu dudakları

sana kıyıp elveda diyemedim

silinmeyen kadersin alnımdan

çok sevdiğimsin canımdan

sallayıp elimi sevdanın ardından

sana kıyıp elveda diyemedim

belki gönlümün gülüsün diyerek

ömrümün en mutlu günüsün diyerek

hayata bağlayan büyüsün diyerek

sana kıyıp elveda diyemedim

sana kıyıp bu şehirden gidemedim...', '''aşk beni terketti ama ben seni...'' çok düşündüm kendi kendime  belki gecelerce belki günlerce her köşe başından döndükçe sana kıyıp elveda ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/elveda-diyemedim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saftirik', 'saftirik-nusret-turan-kl2ho', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rüyamda çıktım kürsüye bağırdım dünyaya

Atın silahları dedim,attılar

Bundan sonra silah milah yok! ....

Tamam mı,tamam mı? ”tamam”dediler

Gemiler çiçek taşıyacak,

İnsanlar binip gezecek,sınır da yok, mınır da! ...

Silah atmak yok,adam vurmak yok

Kin yok,nefret yok! . tamam mı? ”tamam”dediler

Askerdeki silahlar, kazma kürek olacak! ...

Ağaç dikilecek,ev yapılacak,baraj yapılacak.! ..

Bundan sonra vatana böyle hizmet verilecek! ..

Tamam mı! ..tamam mı “tamam” dediler..

Büyük adamlara büyük arabalar verilecek,

Diğerlerine de birer küçük araba! ..

Kimse işsiz kalmayacak, mağdur olmayacak! ...

Tamam mı! ..tamam mı? ”tamam” dediler.

Herkes fabrika yapıp,ekecek biçecek,

Torpili morpili kaldırıyorum,herkes eşit olacak! ...

Yollarda trafik canavarı yok,karınca ezilmeyecek! ..

Tamam mı! ..tamam mı? ”tamam” dediler.

Tüm darphaneleri kaldırıyorum para ticareti yok.

Birbirimize elma armut verip,nar alacağız! ..

Almanlar,İspanyollar,İngilizler bize gelecekler,

Amerika’ya,Japonya’ya gidilecek tamam mı”tamam” dediler.

“Yaşa,varol,sen nerdeydin? nerdeydin? 

Seni Allah gönderdi,yaşa,varol”dediler,,,

Böbürlendim aşka geldim,konuştukça konuştum,

Sizi ben kurtarıyorum,ben kurtarıyorum! ...

Zırt-pırt benzine zam yapılmayacak,

Herkes arabasına binip,dünyaları gezecek! ..

Hormonlu yiyecek yok,ekip  biçeni keserim! ..

Tamam mı! ..tamam mı? ”tamam” dediler

Analar babalar ağlamayacak,onlar yol gösterecek! ..

Ağaçlar yakılmayacak,yenileri dikilecek! ..

Büyük binaların pislikleri denizlere akmayacak,

Tamam mı! ..tamam mı? ”tamam” dediler.

Pasaport masaport yok,sınırları kaldırıyorum! ..

Hepimizi de tek yüce Allah yaratmadı mı? 

Diller öğreneceğiz,birbirimizi hep seveceğiz,

Tamam mı! ..tamam mı? ”tamam” dediler..

Birden burnum sızladı,yumruğu vuran bir deli! ..

Geçmiş karşıma gülüyor”neler anlatıyordun” diyor

“Ben seni akıllı bilirdim, bunlar olur mu saftirik! ..”

Tamam mı! ..tamam mı? ”tamam” diyorum...', 'Rüyamda çıktım kürsüye bağırdım dünyaya Atın silahları dedim,attılar Bundan sonra silah milah yok! .... Tamam mı,tamam mı? ”tamam”dediler Ge...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/saftirik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gururluk Aşk', 'bir-gururluk-ask-i-smail-baharsen-36s0i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çok şeymi istedim ben senden

dileğimdi bir yudumluk aşk

bunu beklemedim ben senden

seninki bir gururluk aşk

temeli sağlam değil yapısı bozuk 

hiç bir anlamı yok sıcağı soğuk

gülüşü sahte sevinci buruk

seninki bir gururluk aşk

sevene ne verirsin sorsam

ben isterdim benim olsan

ah o gururu bir unutsan

seninki bir gururluk aşk

yemin etme ayrılmam diye

sevgi koymalısın kibir yerine

öyle suçlarcasına bakma yüzüme

seninki bir gururluk aşk

ne kadar yalvarsam olamayız

yeniden birleşip kavuşamayız

biz bu aşkı unutmalıyız

seninki bir gururluk aşk..', 'çok şeymi istedim ben senden dileğimdi bir yudumluk aşk bunu beklemedim ben senden seninki bir gururluk aşk temeli sağlam değil yapısı bozuk...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-gururluk-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemiyorum', 'bilemiyorum-nusret-turan-42w61', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Koltuğu masaya doğru çektim

Aldım kağıdı kalemi elime

Bir şeyler yazmak istiyorum

Fakat ne yazacağımı bilemiyorum

Yüzde otuzbeş zammı alınca

Herkes gibi bende sevindim

Ertesi günü hemencecik zam

Ağlasam mı gülsem mi bilemiyorum

Sibel”Kimse Padişah Değil”diyor

Genç kız diyor Antalya FM 105’e

Bunu çal falancaya gelsin filancaya gelsin

Kral var tatlı kızım kral var

Sevgiler dönüşmüş paraya pula

Kim dost kim düşman belli değil

Konular o kadar çok ince ki

Hangisini yazsam bilemiyorum

Cennet gibi yurdumuz var

Niçin yakar kirletir berbat ederiz

Allah isteseydi büyük mide verirdi

Neden dünyaları isteriz bilemiyorum

Kafasını camdan yana eğdi

Bastı,bastı bir güzel gaza

Araba bir sola yattı bir de sağa

Araba böyle mi kullanılır? Bilemiyorum

Geldi oturdu şemsiyesinin altına

Denize girecek belli ki birazdan

Pantolon sıyrıldı,mayo yerine kirli don

Nasıl etsek,nasıl eğitsek? Bilemiyorum

Dağların Ardından’ı yazdın

Kaç kişi okudu kaç kişi aldı? 

Bacak gösterip,gerdan kıramam

Şimdi ne yazacağım bilemiyorum

Lanetler yağdırsam yalan dünyaya

Dünyanın ne suçu var? 

Onu bozan biziz.Padişah-Kral biziz

Neyle düzelir? Nasıl düzelir? Bilemiyorum

Sormuşlar bizim vatandaşa

“Ula gardaş ne bilirsen dünyada? ”

“Valla çok şey bilirem,hiçbir şey bilmirem”demiş

iyi mi demiş? Kötü mü demiş? Onu da bilemiyorum', 'Koltuğu masaya doğru çektim Aldım kağıdı kalemi elime Bir şeyler yazmak istiyorum Fakat ne yazacağımı bilemiyorum Yüzde otuzbeş zammı alınca...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bilemiyorum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazan Gitmek Gerekir', 'bazan-gitmek-gerekir-i-smail-sahin-a1lum', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bazan yar sevmez seni

seviyor olmak yeter,

sevilmemeye...

bazan gitmek sevilir

sevmek istemesen de...

sen gibi...

bazan gitmek gerekir

gitmediğin kadar...

sevsen de...', 'bazan yar sevmez seni seviyor olmak yeter, sevilmemeye... bazan gitmek sevilir sevmek istemesen de... sen gibi... bazan gitmek gerekir gitme...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bazan-gitmek-gerekir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçip İçip Yazacağım', 'i-cip-i-cip-yazacagim-nusret-turan-2jy0n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalk git oğlum Şirince''ye

Bolca şarap al getir,

İçip içip zom olacağım,

Kalemi alıp,yazacağım...

Söz verip yerine getirmeyenleri

Yetim hakkı yiyenleri

Riyakarları, yalakaları

İçip içip yazacağım.! ...

Müdür olup,adam olmayanları,

Zengin olup insanlıktan anlamayanları,

Kızını eğitmeyip dizini dövenleri

İçip içip yazacağım.! ...

Yüze bakıp gülenleri,

Arkadan küfür edenleri,

Dalgacıları dubaracıları,

İçip içip yazacağım.! ...

Gösterişten hoşlananları,

Kendini padişah zannedenleri,,

Kanı beş para etmeyenleri,

İçip içip yazacağım.! ...

Bakışında sevgi olmayanları

Dünya malına tapanları

Çalım atıp gezenleri

İçip içip  yazacağım.

Haram lokma yiyenleri

Aklı Kaf Dağında olanları

Bilgi alıp takdir etmeyenleri,

İçip içip  yazacağım.! ...

Yaş-baş kesenleri

Merhameti elden bırakanları

Küçüğü-büyüğü bilmeyenleri

İçip içip yazacağım.

Yere tüküren densizleri

İnsan yüzüne hapşıranları

Donuyla denize girenleri

İçip içip yazacağım.! ...

Ağacı çiçeği sevmeyenleri

Dağa çıkıp gezmeyenleri

Akan suya çiş edenleri

İçip içip yazacağım.

Sevenleri hor görenleri

Başlık parası ile yakanları

Ne olursa kim olursa olsun

İçip içip  yazacağım.

Ekmek parasını kumara verenleri

Para için kendini satanları

Köpek kadar değeri olmayanları

İçip içip yazacağım.

Eşeği bize çok görenleri

Kendin yarış atına binenleri

Sözde hanımefendileri beyleri

İçip içip yazacağım.

Bilgisiz becerisiz torpillileri

Haksız kazanç edinenleri

Dünyayı ben yarattım diyenleri

İçip içip yazacağım.! ...

Yurdumuza fitneliği sokanları,

Türk-Kürt-Alevi ayrımı yapanları,

Türklüğümüze laf edenleri,

İçip içip yazacağım.! ...

Ömrüm yetmezse ne olur? 

Devam edenler elbet bulunur

Varsın desinler”bu enayi ne diyor”

İçip içip yazacağım.

Nusret Turan / ANKARA', 'Kalk git oğlum Şirince''ye Bolca şarap al getir, İçip içip zom olacağım, Kalemi alıp,yazacağım... Söz verip yerine getirmeyenleri Yetim hakkı...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/icip-icip-yazacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni Öp Ben De Seni', 'sen-beni-op-ben-de-seni-nusret-turan-e8jug', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kainatın en güzeli

 Seni öyle özledim ki

Gel gidelim mor dağlara

Sen beni öp,bende seni

Gel tutuşalım el ele

Koşalım tepedeki çiçeklere

Oturalım diz dize

Sen beni öp,bende seni

Açılalım nehirlere denizlere

Kuşlar,martılar setimiz

Gökyüzü olsun yorganımız

Sen beni öp,bende seni

Gir koynuma hasret bitsin

Garipler malı netsin

Dudağında aklım gitsin

Sen beni öp,bende seni

Dünya malı dünyada kalsın

Aşkın ile canım yansın

Dolaşalım diyar diyar

Sen beni öp,bende seni

Ateşinle kül olayım

Rüzgarınla savrulayım

Uğruna kurban olayım

Sen beni öp,bende seni

Bak yeşil gözlerime

Sıkı sıkı sarıl ellerime

Başını yasla garip göğsüme

Sen beni öp,bende seni

Düşümüz sadelik olsun

Dağlar çiçekler çayırlar

Kuşlar uçuşurken etrafımızda

Sen beni öp,bende seni

Tenin alev alev yaksın

Dağlar çöksün ırmak aksın

Gönlümdeki son bayraksın

Sen beni öp,bende seni

Gel çıkalım dağlara

Gök gürlesin şimşekler çaksın

Yağmur ıslatırken bizi

Sen beni öp,bende seni

Sevdiceğim melek yüzlüm

Can çiçeğim,şirin sözlüm

A sultanım iki gözüm

Sen beni öp,bende seni

Tenhalarda köşelerde

Hüzünlerde neşelerde

Ne olursun haydi öp de

Sen beni öp,bende seni

Rüzgarım ol bağrımda es

Canda nefes dilimde ses

Şaşırmalı gören herkes

Sen beni öp,bende seni

Yağ sineme yağmur gibi

Sar bağrına sar garibi

Gönül köşkümün tek sahibi

Sen beni öp,bende seni

Ver elini tut elimden

Korkmam billahi ölümden

Bekleme ne olur hemen

Sen beni öp,bende seni

Bir gün gelir ölürsek

Kabrimiz bitişik olsun

Çiçekler ekilirken üstümüze

Sen beni öp,bende seni', 'Kainatın en güzeli  Seni öyle özledim ki Gel gidelim mor dağlara Sen beni öp,bende seni Gel tutuşalım el ele Koşalım tepedeki çiçeklere Otur...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/sen-beni-op-ben-de-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saç', 'sac-nusret-turan-p0tqb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tam baharı yaşarken ben

Aaa aaaa oda ne oda ne

Saçlarım dökülüyor herhalde

Hemen doktora hemen doktora

Gittim hemen hastaneye

Verdim parayı aldım fişimi

Girdim sıraya doktoru bekliyorum

Alacağım ilacı bitecek dert

Aaa aaaa oda ne oda ne

Cildiyeci doktor kel mi kel

Ata sözü geldi birden aklıma

“Kelin merhemi olsa kendi başına”

Kapıyı açıp kaçacaktım ki odadan

Doktor yanıma geldi neyin var? 

“Efendim dedim saçlarım,saçlarım! ..”

Baktı baktı güldü nedense...

Hak verdim cildiyeci doktora

Takmadım artık saçı kafama

Dökülürse dökülsün dedim

Doktor doğru söylüyor

       

Yıllar geçti doktora iyice hak verdim

Üzülecek dert tasa değilmiş

Ve bu zamanda bir şeyi daha anladım

Paran varsa güçlü ve yakışıklısın', 'Tam baharı yaşarken ben Aaa aaaa oda ne oda ne Saçlarım dökülüyor herhalde Hemen doktora hemen doktora Gittim hemen hastaneye Verdim parayı ...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sac-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herneyse', 'herneyse-barbaros-dagci-5h9y5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Herneyse senle yaşanan bitti. 

Öyle kolay olmadı. 

Ağır ağır anlamsızlaşarak. 

herneyse; 

unutmayı unutturan bişeydi. 

Herneyse bitti, 

öyle kolay olmadı.', 'Herneyse senle yaşanan bitti.  Öyle kolay olmadı.  Ağır ağır anlamsızlaşarak.  herneyse;  unutmayı unutturan bişeydi.  Herneyse bitti,  öyle...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Dağcı']::text[], 8.5, '{"poet":"Barbaros Dağcı","poet_slug":"barbaros-dagci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/herneyse-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir'' den Kaçış', 'i-zmir-den-kacis-i-smail-sahin-urshr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hava kararmadan

kurtlar gibi etime

saldırmadan yokluğun

ben de gidiyorum arkandan

senden kalan bu şehrin

hucum etmeden kalbime

anılarınla sensiz boşluğu

ısındığın son güneş batmadan

ben de gidiyorum', 'hava kararmadan kurtlar gibi etime saldırmadan yokluğun ben de gidiyorum arkandan senden kalan bu şehrin hucum etmeden kalbime anılarınla se...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/izmir-den-kacis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dip Not', 'dip-not-meral-yagcioglu-q3l9o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ilişikte olan 

Hüzün savaşından yara almış

Gazi yüreğimi 

Ellerine emanet ediyorum

Şefkatine muhtaç, merhemi yüreğin

Eğer geç kalınmışsa

Cevap vermiyorsa tedaviye

Son arzusuysa yanında ölmek

Kızıl şerbetini dudaklarından içir 

Aşkın zehri dindirsin ıstırabını 

Bırak soluğu nihayete ersin

Yanında şehit olsa ne çıkar

		27/10/2003', 'ilişikte olan  Hüzün savaşından yara almış Gazi yüreğimi  Ellerine emanet ediyorum Şefkatine muhtaç, merhemi yüreğin Eğer geç kalınmışsa Cev...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dip-not-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmaki', 'sanmaki-i-smail-baharsen-qsinm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''hep sanmaktan kaybettin sen..''

hep bir gönülde gül olamazsın

seninde rengin solar elbet

sanmaki hiç bir gün unutulmazsın

seninde vaden dolar elbet

sanmaki kahrın bıkılmadan çekilir

o gururun yıkılmadan yükselir

artık dayanılmaz candan bezilir

seninde ismin silinir elbet

düşmeyeki göresin ayrılığı

olmayaki göresin karanlığı

hesapta yokken düşmanlığı

seninde kalbin yaşar elbet..', '''hep sanmaktan kaybettin sen..'' hep bir gönülde gül olamazsın seninde rengin solar elbet sanmaki hiç bir gün unutulmazsın seninde vaden dola...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sanmaki-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem Özleminde Seni', 'i-stemem-ozleminde-seni-i-smail-sahin-1pz2e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne severim daha senden başkasını

ne de unuturum seni

nefesimle nefes alacaksın

Torosların havasından

ellerimle tutup

gözlerimle göreceksin

Seyhan'' ın akışını

anne gibi taşıyacağım seni

anne gibi içimde

ama; 

ne olur doğma

nefesin nefesime karışmasın

gözlerin gözlerime

saçların omzuma

kokun kokuma bulaşmasın', 'ne severim daha senden başkasını ne de unuturum seni nefesimle nefes alacaksın Torosların havasından ellerimle tutup gözlerimle göreceksin S...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istemem-ozleminde-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmeden Önce', 'gitmeden-once-i-smail-baharsen-mt6q5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'son kez otur bir köşeye

bir daha düşün gitmeden önce

ben bu aşkı nasıl yıkarım diye

bir daha düşün gitmeden önce

bana bu ümidi veren sendin

yoluna ömrünü seren bendim

ben seni öyle çok sevdim

bir daha düşün gitmeden önce

son günüm olur inanki bu gün

sensizlik kalbimde bir kördüğüm

hatıran olur sessiz bir ölüm

bir daha düşün gitmeden önce

hayatın yüküyle ezilirim ben

hasretin derdiyle üzülürüm ben

acından gün güne süzülürüm ben

bir daha düşün gitmeden önce', 'son kez otur bir köşeye bir daha düşün gitmeden önce ben bu aşkı nasıl yıkarım diye bir daha düşün gitmeden önce bana bu ümidi veren sendin ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gitmeden-once-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emek İnşaat', 'emek-i-nsaat-nusret-turan-bemp8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gençliğimi ömrümü verdim

Canım kadar sevdiğim

Eşine ender rastladığım

Emek İnşaat ve İşletme AŞ

Herkesin hakkını verdin

Haksızlığa hiç sapmadın

Demiri çimentoyu çalmadın

Emek İnşaat ve İşletme AŞ

Türkiye’nin çehresini değiştirdin

Güzellik kalite kazandırdın

Vergiye,sigortaya öncelik verdin

Emek İnşaat ve İşletme AŞ

İsteseydin köşe olurdun

Sesin duyulurdu fizandan

Hakkı-hukuku bildin

Emek İnşaat ve İşletme AŞ

Allah’tan tek dileğim

Asırlar boyu yaşaman

Hep ruhumda içimdesin

Emek İnşaat ve İşletme AŞ', 'Gençliğimi ömrümü verdim Canım kadar sevdiğim Eşine ender rastladığım Emek İnşaat ve İşletme AŞ Herkesin hakkını verdin Haksızlığa hiç sapma...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/emek-insaat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Coşmayı Çok Severim', 'cosmayi-cok-severim-necmi-unsal-mqmvh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaprak yaprak  baharlarla,

Çiçek çiçek  bozkırlarla,

Cıvıl cıvıl  çocuklarla,

Mavi mavi  boncuklarla,

Ben  coşmayı  çok  severim! 

Coşkun coşkun  sevinçlerle,

Övgün övgün  övünçlerle,

Dalga dalga  denizlerle,

Güleç güleç   benizlerle,

Ben  coşmayı  çok  severim! 

Kanat kanat  şahinlerle,

Kumlu kumlu  sahillerle,

Kıvrım kıvrım  nehirlerle,

Koca koca  şehirlerle,

Ben  coşmayı  çok  severim! 

Yaprak yaprak ağaçlarla,

Sarı sarı turunçlarla,

Salkım salkım üzümlerle,

Dolu dolu güğümlerle,

Ben  coşmayı  çok  severim! 

16 Mart 2004 Salı, Danimarka-Køge  22.18

4+4', 'Yaprak yaprak  baharlarla, Çiçek çiçek  bozkırlarla, Cıvıl cıvıl  çocuklarla, Mavi mavi  boncuklarla, Ben  coşmayı  çok  severim!  Coşkun co...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cosmayi-cok-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayarım', 'sayarim-hifzi-ozbekmez-b8rvf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgilim zehiri versen elinle

Reddetmem içerim ben bal sayarım

Gönlünden çıkarsan atsan dilinle

Kırılmam çıkarım ben kal sayarım

İstersen dikeni gönlüme batır

İstersen yazma hiçbir gün bir satır

İstersen çağır da koluna yatır

Kolunu gül dolu bir dal sayarım

Sevdanla gönlüme hasret dolsa da

Latifi gurbette hasret kalsa da

Seninle arada dağlar olsa da

Dağları aşarım düz yol sayarım', 'Sevgilim zehiri versen elinle Reddetmem içerim ben bal sayarım Gönlünden çıkarsan atsan dilinle Kırılmam çıkarım ben kal sayarım İstersen di...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sayarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyenim Var', 'bekleyenim-var-i-smail-baharsen-l8l9p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''bir kırık İzmir şiiri..''

öyle manalı bakma gözlerime

benim sılamda sevenim var

giremezsin yasaklı gönlüme

benim yuvamda bekleyenim var

güzelsin hoşsun nazlısın belkide

ikiye bir durupta yolumu kesme

sevemem deyince darılıp küsme

benim uzaklarda bekleyenim var

şu kalbim önceden sahipli benim

gönlümün nikahı var şahitli benim

yüreğim aşkıma senetli benim

benim yurdumda bekleyenim var

ben şiirlerimi hep ona yazarım

kimseye geçmez benim nazarım

dilimde hayrınadır dualarım

benim ardımda bekelyenim var

sende vazgeç bu sevdadan

vazgeç senin olmayan yardan

alıkoyma beni yolumdan

benim yollarda bekleyenim var', '''bir kırık İzmir şiiri..'' öyle manalı bakma gözlerime benim sılamda sevenim var giremezsin yasaklı gönlüme benim yuvamda bekleyenim var güze...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bekleyenim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehirde Son Gecem', 'bu-sehirde-son-gecem-i-smail-baharsen-2o92n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uslu puslu oldu sonuncusu 

bu gece bu şehirde son gecem

gözümde yolların korkusu

bu gece bu şehirde seon gecem

neler yaşadım kitaba sığmaz

neler yaşattın hitaba sığmaz

mazimi gömsem mezara sığmaz

bu gece bu şehirde son gecem

gönlümde kalacak anılar anlar

özletecek seni bana yıllar

kalkıyor bak son vapurlar

bu gece bu şehirde son gecem', 'uslu puslu oldu sonuncusu  bu gece bu şehirde son gecem gözümde yolların korkusu bu gece bu şehirde seon gecem neler yaşadım kitaba sığmaz n...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-sehirde-son-gecem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgin Beni Bulmadı...', 'sevgin-beni-bulmadi-i-brahim-ethem-bingul-cwivk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu kadar kolay olmamalıydı

Aşkımız böyle bitmemeliydi

Nasıl gittin,yüreğinde yok muydum

Ayrılık beni buldu,sevgin bulmadı...

Verdiğin umutlar yalandan mıydı

Göz yaşların akıyordu yalan mıydı

Seviyorum diyordun yalan mıydı

Ayrılık beni buldu,sevgin bulmadı...

Artık hiçbir şeyin kiymeti yok

Gittin ya sevdalara artık yürek tok

İster sevin,ister bensizlikten kork

Ama unutma,benden sana fayda yok

Ayrılık beni buldu,sevgin bulmadı...

www.iebingul.com', 'Bu kadar kolay olmamalıydı Aşkımız böyle bitmemeliydi Nasıl gittin,yüreğinde yok muydum Ayrılık beni buldu,sevgin bulmadı... Verdiğin umutla...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgin-beni-bulmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Haber...', 'gizli-haber-i-brahim-ethem-bingul-pcup5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Usulca yaklaşıp

Yavaşça dedi ki

Bir sır söyleyeceğim kulağına,

Bekle,unutma...

----------

----------

----------

----------

----------

Sırsa sır kalmalı,

