INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-baykal-kaanalp-rxoed', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'düşünürüm

seni

geceyi

karanlıkla örtülmüş geceyi

yıldızlarla ayın

birbirleriyle oynaşışlarını

okurum

seni

heceyi

çiçeklerle bezenmiş heceyi

isminle güllerin

birbirleriyle oynaşışlarını

dinlerim

seni

sesini

bülbülü kıskandıran sesini

şiirlerle, türkülerin

birbirleriyle oynaşışlarını

severim

seni

gözlerini

ipek atlas gibi gözlerini

sevdayla,sevdalının

birbirleriyle oynaşışlarını', 'düşünürüm seni geceyi karanlıkla örtülmüş geceyi yıldızlarla ayın birbirleriyle oynaşışlarını okurum seni heceyi çiçeklerle bezenmiş heceyi ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
