INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Ey Sevda Git Başımdan', 'ey-sevda-git-basimdan-metin-eser-mmxk2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey sevda git başımdan, git sahilimden şimdi,

Ne dalganı isterim, ne de mavilik şimdi,

Gecelerim geri ver, artık uzak dur benden,

Sokulma hiç yanıma, çekil git hayalimden.

Uzaklaş şu kalbimin, küllü yangınlarından,

Henüz kapanmamış o, taze yaralarımdan,

Kanatma yüreğimi, zaten kırılmış dalsın,

Bırak kırılan dalım, yenin içinde kalsın,

Yıkık hatıraların, döküğü benim olsun,

Çekil git artık şurdan, bırak n''olursa olsun,

Yitik yangınlarımı, hatırlatma hiç bana,

Çekil git hayatımdan, hayalim kalsın bana,

Bıktırdın sızı gibi, gece gündüz her daim,

Şu zavallı bedenim, değil seninle kaim,

Zehrin en büyüğünü, saldın bir de içime,

Çekil git hayatımdan, alışmam bu biçime.

Bu nasıl birşey söyle, yada ebediyyen sus,

Saçımdaki beyazlar, senin suçun değil mi? 

Artık konuşma sevda, kapat çeneni ve sus,

Çekil git hayatımdan, duyuyorsun değil mi? 

İçimdeki acılar, seni sorumlu bilir,

Harabemin sıkleti, seni zararlı bilir,

Birkaç gülüş kahkaham, vardı ki dudağımda,

Şimdiyse hüzün olmuş, yatıyor kucağımda,

Al artık bunları da, topla pılın pırtını,

Daha ne bekliyorsun, dön artık şu sırtını,

Her nefes alışımda, canımdan bezdin beni,

Çekil git hayatımdan, istemiyorum seni.

Kelebek kanatlıydı, sevgim ömre bedeldi,

Ama ne zaman sorsam, bana yalan söylerdi,

Doğru diye yapışıp, sana sarıldım sandı,

Ama git hayatımdan, gönül saf sana kandı.

Her gülüşünü alıp, sevinçle kapışırdım, 

Gözlerimi yumunca, seninle sarışırdım,

Tebessümdün içimde, yüzbinlerce düğündün,

Şimdi git hayatımdan, yeterince süründüm.

Ne güzel mutluluktu, tatlıydı güzel sözün,

Ama gel de gör şimdi, hepsinin sonu hüzün,

Ne olursun git artık, çek ellerini benden,

Bırak yansın yüreğim, medet istemem senden.

Uzak dur benden şimdi, çek sahte gülüşünü,

Tamam sen kazandın ya, zalim kör döğüşünü,

Ama yoruldum sevda, bıkmışım hayatımda, 

Bırak kanasın yürek, sensin her damlasında.

Nasıl olsa bitecek, son damla ile ömür,

Yeter çek git başımdan, hemen şimdi bu emir,

Bu son vasiyetimdir, sakın bana sokulma,

Çekil git hayatımdan, cansız isem dokunma.

24.06.04 / Frankfurt', 'Ey sevda git başımdan, git sahilimden şimdi, Ne dalganı isterim, ne de mavilik şimdi, Gecelerim geri ver, artık uzak dur benden, Sokulma hiç...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/ey-sevda-git-basimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buğulu Gözlerde Yine Özlem Var', 'bugulu-gozlerde-yine-ozlem-var-sadik-softa-y1ytu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Buğulu gözlerde yine özlem var,

Gecelerde hasret kokuyor yine,

Aynalarda görüyorum her sabah,

Taşlar oturmamış yerli yerine.

Ertelerim  günü,  geceye  varır,

Gündüzümü sorma,o hep kararır,

Gözlerim kan dolar,acı bağarır,

Yaşlar  oturuyor,  gönül  yerine.

Suratımdan ağu düşer kalbime,

Sorular sorarım kendi kendime,

Hergün biraz daha ekler derdime,

Kaşlar yine çatık, gülmek yerine.

İstek, ellerimden  tutmadı  gitti,

Sevda,çemberinden atmadı gitti,

Diken, güllerinden katmadı gitti,

Dikeninde kaldım güller yerine.

Yüreğim durmuyor seni sormadan,

Uzanıp  ellerim  arar  durmadan,

Yarım bir canlıyım seni görmeden,

Gönül tortu bağlar seller yerine.

Çankırı-30.05.2004', 'Buğulu gözlerde yine özlem var, Gecelerde hasret kokuyor yine, Aynalarda görüyorum her sabah, Taşlar oturmamış yerli yerine. Ertelerim  günü...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bugulu-gozlerde-yine-ozlem-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ses', 'bir-ses-emin-baydil-uabbu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ses gelir derinden,

Bu ses ki, Fâtihlerin

En büyük seferinden.

Haykırıyor:

Haydi! Ya Allah! 

Büyük-küçük demeden

Gâzaya çağırıyor.

İşte, bak! 

Malazgirt ovasında,

Alparslan bu / Ellibin

Askerle duâsında.

Bir kartal,

Uzanır tâ...

Başı dimdik / Elleri

Haliç’in yakasında.

Ve, şimdi de duyulur nefesleri

Üç kıtada / Altın

Tarihin nal sesleri...', 'Bir ses gelir derinden, Bu ses ki, Fâtihlerin En büyük seferinden. Haykırıyor: Haydi! Ya Allah!  Büyük-küçük demeden Gâzaya çağırıyor. İşte,...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-ses-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var...(deneme)', 'var-deneme-nedim-saatcioglu-9xgk6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“var”sın ve yoksun. yazmak ne kadar kolay değil mi? “var” olmak, içinde milyonlarca “var” barındırır aslında. tek “var” da neleri paylaşır insan yüreğiyle bilir misin? sen kendi “var”ında nerdesin şimdi, hangi hayal denizinin hangi rotasına kilitlenmiş düşüncelerin, hangi tutsak rüyaya ortak düş yorgunu gözlerin. seven, sızlayan bazen en olmadık zamanda, en olmadık insanın tek sözüyle yıkılan yüreğin. kim için ne adına atıyor şu an.

Ben dağların ötesi bir İstanbul macerası. sen soğuk ve ayaz bir iklimin en sarhoş aymazı. sen gurbet yolcusu,sen yasak aşkın hancısı  hangi anı paylaşmak istersin benimle veya hangi “var”ı.hadi anlat bana, “var”ını anlat bana. bırak bütün yoklar yerde kalsın. tut ellerinden kaldır göklere, ayakların kaldırım taşlarını sökercesine vursun yere ve gel gönlümün gözü, neye hasretsen ve ne kaldıysa içinde keşke adına paylaş benimle.

Umut duvarımdan bir tuğlada sen sök ve hadi dök hasretin en koyu gözyaşlarını avuçlarıma bırak ellerimle sileyim camların buğusuna çizdiğin oklanmış bu boş kalbi. artık ben “var”ım yanında ve benim “var”larım.

Bütün yoklar yerde kalsın, “var”ını anlat bana. gecelerin ayazından, gündüzlerin alazından şarkıların hicazından,duyguların çıkmazından  ve içindeki en büyük yalnızlıktan, sıyrıl. en güzel rüyanı dizimde gör diye buradayım. artık-artık ben “var”ım.

Üzülme ve yakınma hayata karşı “var”say sen bir alıcısın, hayatsa çarşı. beğenmediğini geç, dilediğini seç ve kuşan mutluluğun zırhını. deli bir tay yarat hayal aleminde ve koş. gideceğin ülkenin adı bahar, tayının adı “var” olsun. dünü düşünme ve endişe duyma yarından çünkü “var”sın.

Kendini bir uçurumdan atmak için önce “var” olman gerekir bilirsin. 

Bırak bütün yoklar yerde kalsın. hadi “var”ını anlat bana. yokluğumda göz yaşların nasıl dökülür kırmızı yastıklara, yokluğumda gözlerin nasıl takılır duvardaki yazılara ve titrek ışıklı fotoğraflara… nasıl gömersin çığlıklarını  katlanan kırmızı desenlere. 

Düşler düşleri kovalar kimi geceler. sınırı yoktur uykuların. bir “var”mış bir yokmuş diyen masallara inat, bir “var”ım hep “var”ım diyen bir masal uydur kendine. yüreğinde yeni bir “var” yarat. sakın unutma sen soyut bir kavramsın aslında dünya yüzünde. ve bilmeden yaşıyorsun yüreğinde “var” olan somut “var”ın  içinde.', '“var”sın ve yoksun. yazmak ne kadar kolay değil mi? “var” olmak, içinde milyonlarca “var” barındırır aslında. tek “var” da neleri paylaşır i...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/var-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Göğe Martı Olsun', 'adim-goge-marti-olsun-derin-oger-7v7np', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu tutku

göğsümün sol feryadı

taş olup kamçı kamçı kırılır

yığılır dağılır kum taneleri misali

kimi derinlere çöker kimi karalara vurur

isyan yüklü bir gemi ki

iğne iğne çivi çivi kalbimin tam orta yerinde

mavi bir sancıya oturur

aşk nerede güzelliğin

hüznün deniz nedir bu derdin

sükun bulmaz coştukça koşar dalgaların

bir borç sanki öde öde bitmez

içimde güneşi batırıp binlerce ben vuruşun

vur kapın da mülk bulmuşken

korkma bırak yayını atsın şafak

adım adım,adım göğe martı olsun........', 'bu tutku göğsümün sol feryadı taş olup kamçı kamçı kırılır yığılır dağılır kum taneleri misali kimi derinlere çöker kimi karalara vurur isya...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adim-goge-marti-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akasyaların Dansı', 'akasyalarin-dansi-esat-ergun-xtk38', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hayallerde elini tutmak bile 

heyecanlandırırken beni

kollarımdaydın işte..

ve senin gecende,

seninleydim..

zamanın başka bi yerindeydik

ve burada kelimeler

anlamsız kalıyordu..

yalnızca gözlerin konuşuyordu..

gözlerin gözlerime her değdiğinde

dizlerim tir tir

titriyordu..

gece saçların ellerimdeydi..

yüreğim kelepçelerde..

sen yanımdaydın ama 

gözlerin hasretle başka yerlerde..

bundan sonrası için attığımız

ilk imzaydı aslında..herhangi bir dans değildi kesinlikle..

-yepyeni bir sayfa açtıktan sonra

yaptığımız-

akasyaların(*)  dansıydı..

o son şarkının nakaratında dediği gibi şairin: ''Seviyorum Seni.. ''

-

(*) 

Kırmızı akasyalar; güzelliği,zarafeti,inceliği temsil eder.

Sarı akasyalar; platonik aşık,isimsiz aşık anlamına gelir.

Beyaz akasyalar; dostluğu,adı konamamış arkadaşlıkları karşılar.

O geceki dans,akasyaların dansıydı.. Senin rengin kırmızıydı.. Benim rengim sarı.. Aramızdaki ilişki ise bembeyazdı..', 'hayallerde elini tutmak bile  heyecanlandırırken beni kollarımdaydın işte.. ve senin gecende, seninleydim.. zamanın başka bi yerindeydik ve ...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/akasyalarin-dansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlarsın', 'anlarsin-esat-ergun-ro1rr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gün gelirde anlarsan

sevginin ne demek olduğunu

senin de yanarsa için

benim gibi..

ve unutulmayacak bir aşka

kitlenirsen..

bir gün göz yaşı dökerken gizlersen yüzünü

utanırsan gözyaşlarından..

sevmeyi günah bellersen,

sevmekten korkarsan artık..

gitmek isteyip de gidemezsen,

çaresizliğin dolanırsa boynuna..

sen de anlarsın..

anlarsın...!', 'gün gelirde anlarsan sevginin ne demek olduğunu senin de yanarsa için benim gibi.. ve unutulmayacak bir aşka kitlenirsen.. bir gün göz yaşı ...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anlarsin-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasan Da Geç Artık', 'anlasan-da-gec-artik-esat-ergun-0su1s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bütün şarkılarda hala sen varsın,

gözlerim hala yolunu beklemekte..

bir gün anlarsın diye

sevmelerden vazgeçmedi yüreğim..

hala sana çarpmakta..

uykular gözlerimden kaçak,

seni konu alan rüyaları özlüyorum..

boğuluyorum sessizliğinde gecenin

sigara sığınabileceğim tek liman

ve gözlerin

yaşamak için tek sebebim..! 

'' senle ilgili bir şiire mısra şimdi yine gözlerin..

ve fotoğrafların ellerimde

üzülüyorum.

çok şey vardı yaşanacak..

bitmeyecek sandığım her şey bir gecede bitti benim için..

umarım senin de hayatında bir gece olur ki; 

anlarsın ne demek istediğimi..! ''', 'bütün şarkılarda hala sen varsın, gözlerim hala yolunu beklemekte.. bir gün anlarsın diye sevmelerden vazgeçmedi yüreğim.. hala sana çarpmak...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anlasan-da-gec-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece, Deniz ve Karanlık.', 'gece-deniz-ve-karanlik-musfik-saltik-onm44', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sahilde yürüyorum

Gecenin bir yarısı

Deniz kapkara

Ay yok yıldız yok

Zifiri karanlık gökyüzü

Bütün hüzünlerimi emiyor

Karanlık sular

Sıkıntılarım gökyüzünde

Uçup kayboluyorlar

Hafifliyor yüreğim

Rahatlıyor bedenim

Boşlukta uçan bir tüy gibiyim

İşte ben bu yüzden

Geceyi, denizi ve karanlığı 

Çok severim.

                              Haziran 2004', 'Sahilde yürüyorum Gecenin bir yarısı Deniz kapkara Ay yok yıldız yok Zifiri karanlık gökyüzü Bütün hüzünlerimi emiyor Karanlık sular Sıkıntı...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gece-deniz-ve-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Şarkısı', 'ask-sarkisi-esat-ergun-nosyk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bilmesek de söylemeye çalıştığımız

şarkılar vardır ya..

bilmediğim ve söylemek istediğim

tek şarkımdın..

her sonbahar vurunca yüreğimin küllerine

içimde alevlenen aşkı

söndürmek için ağlardım..

ve bir şarkı seçerdim aşk üzerine..

söyleyemezdim..

hep bir yerlerde yanlış yapardım..

sen gelince aklıma susardım..

sessizliğini dinlerdim..

beklerdim hayalin uzaklaşsın diye..

sonra geceleri yazardım sana

mısra mısra..', 'bilmesek de söylemeye çalıştığımız şarkılar vardır ya.. bilmediğim ve söylemek istediğim tek şarkımdın.. her sonbahar vurunca yüreğimin küll...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-sarkisi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığa...', 'ayriliga-esat-ergun-obw7u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bırak, fırtınalar kopsun,

bırak, depremler olsun,

yüreğinde...

bir çift gözyaşı eşlik etsin gidenlere...

göm yalnızlığını kederine

ve sil tüm yaşananları

bir kalemde...

geriye dönmemek üzere...', 'bırak, fırtınalar kopsun, bırak, depremler olsun, yüreğinde... bir çift gözyaşı eşlik etsin gidenlere... göm yalnızlığını kederine ve sil tü...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayriliga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlamadan Bitene..', 'baslamadan-bitene-esat-ergun-yc4h2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir güz esintisinden kopmuştun sanki..

ve savrulan bir yaprak gibi düşmüştün yüreğime..

acı ve mutluluğu hiç kol kola görmemişti bu yürek 

senden önce..

gözlerim acı damlatıyordu,

sigaramın küllerinin üzerine..

sensizliğin acısını en derinlerde yaşarken,

ve uçurumun kenarında tutanacak tek dalım yokken..

tutundum gözlerine..

yoksun yanımda ya şimdi..

hasretin de yakıyor ya içimi

gitmek kolay geliyor ya sana güzelim..

ben gidemedim güzelim,

o güzel gözlerini bırakıp,

düşemedim gecelerin içine.. 

ölemedim işte.. hala bekliyorumm...', 'bir güz esintisinden kopmuştun sanki.. ve savrulan bir yaprak gibi düşmüştün yüreğime.. acı ve mutluluğu hiç kol kola görmemişti bu yürek  s...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/baslamadan-bitene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalkantı', 'calkanti-esat-ergun-zwv75', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'senden uzaklaşmak için attığım her adım

yanlış bir yöne doğru oluyor..

gözlerini bir gölge gibi

peşimden sürüklüyorum..

kaçamıyorum..

öylesine bendesin ki

kopartıp atamıyorum içimden seni..

dedim ya esmer kız,

gözlerin gölge misali,

her vakit takipte..! 

evet..

ışığı görüyorum..ilerde bir yerlerde..

çok uzakta..

erişmek zor.. yol uzun..

ancak yol bir..

arkamda bir gölge olduğunu hep bilerek

ilerliyorum artık..

kopmak için gözlerinden,

sigaraya sarılmıyorum..

yalnızca ilerliyorum,beklemeden..

ışığın sonunda

gözlerin olduğunu düşünerek ilerliyorum..

yaşamak için hep bir umut şart..!', 'senden uzaklaşmak için attığım her adım yanlış bir yöne doğru oluyor.. gözlerini bir gölge gibi peşimden sürüklüyorum.. kaçamıyorum.. öylesi...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/calkanti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü', 'dogum-gunu-esat-ergun-3fci4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'herkesin içinde bir yerlerde

hep bir hüzün vardır..

önemli olan üzerini örtebilmektir

hüzünlerin,

bir parça tebessümle..

ve bir tek tebessümle, bir yüreğe

hayat verebilmektir..

yepyeni bir sayfa açabilmektir,

her parlak sabahla birlikte..

nice senelere..! 

''gece saçlı kız,doğum gününde vermek isterdim sana bu şiiri ancak öylesine büyüsündesin ki sevilmenin, beğenilmenin.. korkuyorum.. ayaklarının yere basması için her şeyi zamana bırakıyorum..bende olan herşeyi bitiriyorum.. ve yavaş yavaş yayınlanmaya korktuğum bütün şiirlerimi yayınlıyorum..! 

bu da onlardan birisi.. 08.12.2003 tarihli bir şiir..''', 'herkesin içinde bir yerlerde hep bir hüzün vardır.. önemli olan üzerini örtebilmektir hüzünlerin, bir parça tebessümle.. ve bir tek tebessüm...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dogum-gunu-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durup Beklediğim Yerden...', 'durup-bekledigim-yerden-esat-ergun-94mja', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gözlerin dolanıyor yüreğime

sarıyor,sarmalıyor,sıkıyor..

nefesim kesiliyor,

aklıma her düştüğünde

yüreğime hatıraların vuruyor..

canım yanıyor..

seni düşünmek acıların en dayanılmazı..

her gece unutmak için siliyorum

hatıramdan

bakışlarındaki gizemi..

olmuyor..

zamanın bir yerinde kitlemişsin beni..

ne ileri ne geri..

çok farklı bi yerdeyim,

yıldız gözlerine tutunamıyorum..

sana ulaşmak için

yürümenin çaresiz olduğunu anladım..

duruyorum o yüzden,

kitlediğin yerde..

beklerken daha iyi anlıyorum:

yıldızlara erişilmiyor..! 

''hayatımızdan kayıp giden ve sönen bütün yıldızlara..''', 'gözlerin dolanıyor yüreğime sarıyor,sarmalıyor,sıkıyor.. nefesim kesiliyor, aklıma her düştüğünde yüreğime hatıraların vuruyor.. canım yanıy...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/durup-bekledigim-yerden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşününce...', 'dusununce-esat-ergun-7qq7i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'saat sabahın üçü..

sokaklar yine seni soruyor bana

titrek bir lamba

hüzünlendiriyor beni

ve bir sokak köpeği

ıssız bir köşeye tünemiş

yakıyor içimi..

hava soğuk..

neden bilmem,

üşeyemiyorum..

saat sabahın üçü..

kaldırıma oturuyorum..

elimde sona kalan bir tek sigara..

sigara paketini buruşturuyorum elimde..

sen geliyosun aklıma..

sonra bir nefes çekiyorum..

dumanında yine sen..

sen gelince aklıma içemiyorum nedense..

atıyorum elimden sigarayı..

sen istemiyosun diye içmiyorum..

bu gece bi şeyler farklı sanki..

gözlerin o eski gözlerin değil,

ve hayalimdeki yüz senin değil..

utanıyorum kendimden bi an..

sonra geçiyor..

yüreğin geliyor aklıma..

somutlaştıramadığım hayalini

yaşıyorum damla damla içimde..

zaman duruyor bi yerlerde

ve bi şeyler kopuyor içimde

seni her düşündüğümde..

güneş doğuyor uzaklarda..

ufak ufak huzmesi vuruyor gözlerime..

geceden kalma hüzün var hala yüreğimde

ve bir burukluk senden kalma..

hayalinde büyüttüğün resme asla 

ulaşamazsın..

ne kadar seversen sev 

zaman ve kader istemezse

kavuşamazsın..', 'saat sabahın üçü.. sokaklar yine seni soruyor bana titrek bir lamba hüzünlendiriyor beni ve bir sokak köpeği ıssız bir köşeye tünemiş yakıyo...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/dusununce-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Saçlı Kıza(1)', 'gece-sacli-kiza-1-esat-ergun-pxin4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözlerin geliyor gözlerimin önüne..

uykularım kaçıyor..

hıçkırıklarımın ortak oluyor kederime..

ve bir eylül hüznü çöküp oturuyor,

derinlere..

zifir karanlığa dalıyor gözlerim

düşünüyorum geçen günleri,

ansızın hatırlıyorum

o ilk ''seni seviyorum'' deyişini..

düğümleniyor bi şeyler boğazıma..

ıslanıyor yanaklarım..

ayrılık ateşi tutuşuyor içimde yine..

eylül körüklüyor,

gözyaşlarım söndürmeye yetmiyor..

özlem bir hançer gibi

o hala izi duran yere,

yüreğimin tam orta yerine saplanıyor..

unutamıyorum..

onsuz geçen her güne yemin ederim ki..

o gece saclı kızı unutamıyorum..', 'gözlerin geliyor gözlerimin önüne.. uykularım kaçıyor.. hıçkırıklarımın ortak oluyor kederime.. ve bir eylül hüznü çöküp oturuyor, derinlere...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gece-sacli-kiza-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aça-69 (Syk-6a) - Düş', 'aca-69-syk-6a-dus-akin-akca-8v7vy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'TOR KAPISI

I.

Sayfalarından -tozlu- zamanın, ilerliyor! ilerliyor: Arthur! 

Çamurlarda ‘ağzına kadar’ baldır: Sisler bataklığında! 

 Sen, durdur -adaletsizliği: İşte! budur! 

Dönüyor artık (Avalon’dan yerküreye dönüyor) ,

Onun yolculuğu dünyaya sürüyor! Sislerden çıktı,

 Avalon’dan ve is’in içindeki, (kartal gibi)     Kesti çatışmayı! *

Bir pagan rahibinden de öteydi, Kral tacına yükselten Druid - *

Çıkarttıran Ecalibur’u, sağlam kayadan 

(Düzen sağlamak ile kutsanmış)     -

(Merlin’di uzatan kılıcı ve onun sağ kolu)     Arthur’u

II.

Dört tepeli Glastonbury’de: bir kule var tekinin üzerinde *

Yağmacılardan kurtardı Tor kulesi

Kaçanları- anlamsız kin kusanlardan.

Az öncesine kadar hava, güneşlikti:

Karardı şimdi ve zorlayıp kapıyı

Yumrukluyorlar, kafalarıyla

Vücutlarıyla, anlamsız birer düşünce

(Yığını)     Olup da onların taşıdıkları büstlerinde -

Düştüklerinde: insanca da değil bu aslında! ..

Ulaştıklarının neticesi, şu an onların yaptıkları.

Havayı kararttılar ve damarlanan

Gök altında, som altın

Kuleyi aşındırıyorlar -

Suçsuzlardan, sormak için hesabı.

Ne varsa iyi’den, geldiler buraya

Sığındılar Avrupa’dan, Asya’dan

Vesaire, kutup buzullarından …

(Çok kişi yerleşmişti oraya

Yaşanabilir kaldığından)  

Yürüten onları, havadaymışçasına; 

Bir gökkuşağı ulaştırdı

Avalon’a uzanan bu ‘dört tepeli mekan’a.

Ve ‘büyük kısım-nefret öbekleri’

Tabi durmadı yerinde: peşlerinden onların geldi, 

‘Ebemkuşağının getirdikleri’nin -

Onlara fakat saldırmak adına! 

… Fabrika elçileri vardı, 

Amazon diyarlarında yaşamayan:

Sürdüren varlığını sırça köşklerde,

Bindiği dalı kesen, sormayı unutmuş

Ve işte, kapının dışında onlar -

Tor’u zorluyorlar- tütün dinamoları, üreticileri:

Hırsızlar yoktu, onlar hala evlerinde:

Korkularından çıkmadılar; ürktüler,

Kuleden ve hem de bu zebanilerden; 

Özellikle, bu zebanilerden! 

Onların gözleri akıyor alınlarından:

Bu dışarıdaki adamların; 

Şakaklarından doğru, çıkarak saç tellerine.

*

Kıyıdaki el Excalibur’a uzandı bir kayık üzerinde:

(Gölün ortasından yükselen kılıca doğru hamle yapan -

kıyıdan doğru gölün hacmine sıçrayan

-Onu tutmak için hem de …

Arthur, 

Üzerinde gölün)  

(Arthur’un eli! dünyaya dönüş yolunda!)  

Ve bu el bu kılıcı kavramazdan 

Çok önce yükselmeye başlamıştı ‘Tor’.

Bir kama gibi saplanan -tasaya, en kararlı! 

Gökkuşağı tüm dışarıda kalanların üzerine

(Denize göçtü)     Büyüyen bir gölge oldu! 

Bu karabasan, müjdeliyordu götürdüğü’nü:

Kapıyı yumruklayanları: 

(Kuledekileri)     Getirisi olarak getirişin:

Götürdüğü Tor’a, huzuru getiriyordu.

…..Bazı yüzler oluştu bulutların bile üstünde:

…..Yetişemedi kötülük ancak! 

…..Ve şanlı sancak -zor gelen, tüm asıldı; 

…..‘İki mislinde ötesi olan’ için bulutların! 

…..(Kararlı olan düşünce benzer, duyguya)  

…..Hızlı giderek ışıktan bile.

*

…Mavi göl önünde sütunlar baş verdi, yapı yükselten,

Sardığı envai çiçeklerin ve ay belli belirsiz gökyüzünde:

Az (daha)     var geceye ve beyaz ufuk, sınırdan yücelen,

Saydam belirlenemeyene karışmaya hazır, siperde,

Rüzgar ötesi bekleyişinde gerginliğinin sessizliğin,

Ki yapraklar kıpırdadı kıpırdayacak neredeyse,

Salmak için saydam Ay’ı ‘ak ufuk çizgisi’nde! 

…Gece oldu ve Güneş çöktü, kulenin tepesinde,

Ürkünç bir manzara Ay’ın olmadığı ecedeki

Ay’ı göremeyen için, karanlıkta saklayan kendisini! 

Ve güneş haricinde kalan alanlar gökada’nın merkeziydi; 

Çok fazla yıldızı çarpıştırıp, boş uzayı 

Azaltan barındırmayı, düğününde taç yapraklarının

Bir ağacın: girmiş ha dallar güneşin yüzünde! 

…Kule sislere büründü sonra yine, tamah etmeye

Beşeri zamana,salladı kılıç ona, üç belli başlı burç altında:

Görürken zor, olası toprağı; is oldu sonrasında

Kendi toprağın ve hayaletler çıktı yer altının sakladığı,

Şu ana dek, çalı çıpı ve var yeşillik bu sisin öbeğinde,

Seçiliyor açık seçik, nasıl oldu bu olanlar böyle? 

…Bahçe-çayır bir oba döşeğin, kel tasması yeni doğmuş bebeğin; 

Veriyor salyangoz, bir deli fişek! 

Gökkuşağı ilham yardı,

Henüz emekleyen! 

Ve sisler içinden tozlar toplaştı, bir araya geldi:

Yıldız falan da patlamamıştı, çok fazla birey oldu tek.

…Beşik umuda köz alametleri tatlı huzurun:

Bir fırtına öncesi, sessizliği damızlık miğferinin

Savaşçının çeliğidir kırar atar en güzide zerafeti

Ve gururdur: parçalayarak kendisini, parçalar bir diğerini

Baktığında aynaya, aslında tanımak için kendisini

“Hangi aynaya bakacaktım? ” diye (de)     sorar

*

Entropik bir meze: öyle ki, bir düzensizlik, ışınlanamayan,

Kırılan vazoların kendi toplaştığı: kuantum köpüğünde değil bir düzen

Ve bir gerçeklik için bir istikbal; 

Kanaatkar bir bekleyiş, artısı ve eksisi seziş,

Selamlama, eğilip de öne referans durma:

Merhaba demeyende (zaten)     iç çekiş! samur, o kürkler giydi

Kentucky tavuğunda yeşilin dalları ağaç büker yaş çimenlere

Ve körpe ağıtlar boy verir ölü buzağılarda

(Sanki inmiş de yakın çevreye bir UFO, ondan ölmüşler!)  

-Yalvaran, katışıksız süt için! Gökkuşağının –yol gözleyen- renklerinde; 

‘Başak yükleyen izbandut benzin depolarında’ ozon tabakasına! 

Ve nobran ötesi şekiller, geviş getiren her katrede, soluklanma amaçlı; 

Dedesidir bir bebenin, üç solukta ‘öğrenen gülmeyi- katışıksız ağlayan’! 

Umut tıngırdatan, ah geviş getiren: semiren ve onu da tüküren:

Bak or’da değil yıldızlar, burada; canavarsın sen! 

Lanet olsun sana! lanet bana olsun! 

İşte saldın bir ruhunu koyunun, kurban bayram için edilen! …

Top oyna, uçursana bir şimdi uçurtma: işte böyle; 

Belli, ordasın; belli değilsin burada şimdi

Kör tutkular için, olmasın senin saçların uçuşan:

Dua ederim, bilinir ya; etmezdim dua, sen olmasan silinir

Bakmamak önüne, arkasına; istektir, nankörcesine kotarılan! 

Zar! (Gün eden gününü, ağaç köklerine kadar)  

Evrenin sonuna devrilen bir kar: evrenin sonunda bir başlangıç var! 

Anne ya da baba, bir dost belki eli, e hadi: ah sevgili! …

Senin, termodinamik musluk içinde mi alaşımın? 

Akar akan: var olan duran ve bir ırmak nefeste ‘soran olan’! 

Kendiceğine; enine, boyuna, turşusuna, ‘masalların balkabağı’na

Oradadır! Bilinir! Nefistir! 

Belki (lezzetli olan onun)     nefsidir

Yine de kendisidir! 

Kumdur cam, kumdur, kumdur, cam kumdur! 

‘Denizim içinde’ sevdiğine ulaşan şişedir! 

Odun veya: bir yaprak; şişe içinde iki kanat; o, fora; bir yelken! 

Yeşilken taşır bir direği: beklemeler’e, hayalet! 

Sulu sepken! (‘Lanete ev sahibi’ ıslanmış bir sıçan’! şaşkın!)  

Ve sen verirken: aldığını, zerkeden, şırınga kendine ederken! 

Bir Mesih: uzaktaysa aklın senin:

Ötedelerde-bucak bucak seni aradık! 

Fakat, bir damla: damlanın içindeki öz, hatta; 

Bir karış, sevgili, sen! 

Her zamanki gibi bir berraklığın ya da berrak bir huzursuz yalınlığın

Farklı oluşu’nda debelendi güdü-inanç ile özgür-enerji,

Açılan mağaradaki açmaz kovuklarının bağrında! 

III.

‘İntikamın fani-dili-eti-ölümsüz-kemiği’nde

İndi gürzler kafalara, kafalara ve vücutlara

Ve oklar dile gelmez türde

Büyük bulut, şarapneldi dört bir taraftan! 

Ve mızraklar, onlar da bu bulutun sancakları! 

Kahverengi kucaklandı açık gri ile! 

Ne, zaman; mekan, ne de: başka birileri var arada! 

Sarmalayan çünkü sizi acılar, yeğdir: 

Uğruna katlanılan bir nüve-nefes, ‘bir feryat’: canlı! 

… Bir yaşam’ın içinde; onlar, çekilen.

IŞIK KONİSİ

Çarşaf gibi kabarıyor ve gerili-büzüşmüş, deniz 

Ve biliyorum, kabarık, yaprak yaprak kan, damardaki; 

(Devşiriyor kendini, harmanlayan, burgaçlardan 

Varılıyor tek bir hortuma, eden yeryüzünü talan)   

Biziz dökülen sonbahar ağaçları gibi. 

Yetkin bir orak, öyleyse, getiriniz! 

Hasat mevsimi için değil -değil ya da sırf dağıtmak 

Adına kendi karanlıklarımızı -yeniden başlamak için değil: 

Bulunan ‘tek’ eminlik, ‘iki-arpa boyu’nda. 

Senin arkandan yaklaşan hayalet şehir, 

Bir başkalaşım’da, kasaba cafe’sinde otururken sen: 

Yaş yerine yaş var senin gözbebeklerinde; 

Mutluluk gibi, uçurtma gibi; acıyı da tattın, hüznü de. 

Kanattır senin büyülü peri -olup rüzgar- sürükleyicin 

Ama unutma göze alamadığını düşünmeye - 

Ki bir düşüncedir, bir an''lık verilir 

-Gotik kıvrımlardadır, yine, karanlığı kabul etmeyişin. 

 İşte bu ışık konisinin içinde her bir şey 

Her olay, mutlak geçmişten; 

An’ını etkileyen, olay’ın 

Ve geleceğe ileten kendisini, 

(Yürü, tay tay)     Berduşluk, an’lık. 

Uzay-zaman, dört boyutlu, 

Üç boyutlu’da ifadesini buluyor. 

Fakat anti madde’den sağlanan, 

Duvarlarını uzayın daha bir bükerek 

Işık hızını geçmemizi sağladı bize. 

Sonsuz’du, içine ve dışına yumurtlatan, 

Kabarcıkları; kuantum havuzunda. 

Ve artık bu kum saatini andırır 

Işık konisi dağıldı. 

Geçmiş, gelecek ile hür artık - 

Kuantum köpüğü, birbirinden bağımsız 

Evrenler oluşturmayacak artık 

(Enerji debeleniyor inanç ile bu ışık konisinde)  

-Bu koninin içine dahil, öte yer de.

GÜNBATIMI-YAKUT’U BİR ŞAFAĞA …

Karakterden bile fazla yol alması deneyimin, gariptir! 

Var olansa vardır diğer yandan! 

: İlerliyor deneyimse, sabittir kişilik belki bundan! 

Kişiye gören değişen kişilik, çok da dayanıksızdır bazısı:

Ölçülemeyecek deneyim ölçütünde! 

Deneyimler, karakteri belirleyen dayanıklılık ölçüsünde

Hayat için var edinilenler, yaşamalıyız bu yüzden hayatı; 

Çünkü yaşamda: durup da taşlar -kömür- dikiliyor elde edilenler

Herkes için sorun, bunu kabul etmekte! 

Kişiliğe bakar bu ve karakter bakar deneyime! 

Ve bitmeyecek bu döngü; ne var ötesinde ‘eline doğan-karakter’in? 

Kısırlığı döngünün gerçekten kısırsa, değer mi hiç ha korkmaya! 

Ürkekçe yalpa atmalıyız ama, bu sıradan bir kısırlıksa! 

Ve önlem alırız o vakit ve biz deriz benliğe: böyle savuştururuz:

Ölümdür zor olan tek şey! Belki de bulunamayacak çaresi! 

Fakat bilirsin ya sen, bir şeyi bilmen gerektiğini

Ve eşeler ve kurcalar bazıları ya toprak ananın miğferini:

Kudretidir karakterin, bu gider deneyime! 

İşte yücelen sen, eşeledikçe! ..

Kendisi korksun cesaretin insanoğlundan, kendisi? 

: Sezgi işi belki, insanlar susabilir ölüme giderken! 

Düzeltmeye kalkışmadık: başından sonuna karşı çıktık! 

Yetersiz kalır düzeltmeler! 

Oynattınsa bir sefer taşı, onlar, temelden düzeltilmeliler! 

Ama bu demek değil, sen yeniden oluştur kendini! 

: Deneyimde bulduğunu bir de katarsan karaktere, sürer en güzele! 

Sezgileri hayata bulduk, ama olmasın senin bilincine kendi sezgilerin! 

Bilme! yap sadece! ihtiyacın olmasın bilmeye! Giden yolda detaylara; 

‘Hiçbir zaman bulunmayan’-bir olmayan, sırıtırken içinden yaşamın; 

İşte bak yanında senin, her zaman orada bulunan: güven ayrıntıya!', 'TOR KAPISI I. Sayfalarından -tozlu- zamanın, ilerliyor! ilerliyor: Arthur!  Çamurlarda ‘ağzına kadar’ baldır: Sisler bataklığında!   Sen, du...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":232,"source_url":"https://www.antoloji.com/aca-69-syk-6a-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Saçlı Kıza(2)', 'gece-sacli-kiza-2-esat-ergun-b9t85', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'üzülme sen gece saçlı kız..

bu yürek bıraktığın her acıya dayanıyor da

seni üzgün görmeye dayanamıyor..

bir tebessümünün ne yangınlar

harladığını bilsen

o yaşlarını giydirmezdin

güzel gözlerine ya..

madem ıslandı bir kere yanakların

elinin tersiyle al nemini gözlerinin..

sen herşeye rağmen üzülme

gece saçlı kız..

bırak hüzünlerini,

aksınlar içime içime..

ve ben yanayım 

senin derdine..

nasıl olsa alışkın bu yürek 

senin derdinle terbiye edilmeye!', 'üzülme sen gece saçlı kız.. bu yürek bıraktığın her acıya dayanıyor da seni üzgün görmeye dayanamıyor.. bir tebessümünün ne yangınlar harlad...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gece-sacli-kiza-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Hüzün Damlatıyordu...', 'gozlerim-huzun-damlatiyordu-esat-ergun-i92mn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sesinde tereddüt vardı,

dudaklarında zoraki bir gülüş..

tükenmiştim..tükenmiştin..

bi şeyler yanlıştı..

yanlış olan her şeye,

adını koyamadığımız şeye,

yaşamın ta kendisine

öfkeliydim..

beklemek diyordum kendi kendime

o son sözlerin ardından çekip giderken

beklemek,yaşamı kaçırmak mıdır? 

eğer yaşam sensiz devam edecekse

tutan yok kaçsın gitsin..', 'sesinde tereddüt vardı, dudaklarında zoraki bir gülüş.. tükenmiştim..tükenmiştin.. bi şeyler yanlıştı.. yanlış olan her şeye, adını koyamadı...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozlerim-huzun-damlatiyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Bekleyiş Biraz Ölüm Kokar..', 'her-bekleyis-biraz-olum-kokar-esat-ergun-8pcxf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'savruluyor gecenin hüznü yüreğime..

herşeyin üzerinde bi duygu bu..

sevmek ve beklemek..

sonunu düşünmeden beklemek..

düşlerinde geçmişi düşünmek..

ve ölümle dans etmek..

umutlarına inat ölmek..

yaşamaktan korkup

ölümü seçmek..

giderken son bir söz söylemek..

mezarına yazılacak..

ölmek cesaret ister..

beklemekse sabır..', 'savruluyor gecenin hüznü yüreğime.. herşeyin üzerinde bi duygu bu.. sevmek ve beklemek.. sonunu düşünmeden beklemek.. düşlerinde geçmişi düş...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/her-bekleyis-biraz-olum-kokar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Mısrası Yazılmamış Şiir', 'son-misrasi-yazilmamis-siir-esat-ergun-h6u4x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kentin ışıkları söndü önce bir bir..

gecenin üzerine karanlık bir hüzün çöktü..

titreyen ellerim tutamadı çiçeğini..

sonra kederli bir bekleyiş sardı yüreğimi..

koptu içimden bir şeyler..

tutamadım gidenleri..

haberini aldığımda

bir uğurlama türküsü vardı radyoda..

inanamadım..

sana ölümü yakıştıramadım..

gözlerim bir umut aradı uzaklarda..

bilmediğim birine,bir şeye 

göz yaşı döktüm ilk defa..

içimden dualar gönderdim sana..

ıslak bir sızı vurdu yüreğimi

kederine inat..

sana dair herşey dizildi hatırama..

tüm yazılar,şiirler,şarkılar...vs

her darbede daha çok sendeledim..

senin şiirinin son mısrası daha yazılmadı..

gitmek için bu mücadelen niye...? 

''son nefesinden biraz önce yazdığım bir şiirdi.. kime olduğu bende saklı kalsın..''', 'kentin ışıkları söndü önce bir bir.. gecenin üzerine karanlık bir hüzün çöktü.. titreyen ellerim tutamadı çiçeğini.. sonra kederli bir bekle...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/son-misrasi-yazilmamis-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-derin-oger-ircw5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sevgili sana benden sana senden söz ederken

göğüne gözlerimin buğusundan kara güvercinler uçururdum 

saçlarıma her yağmur düşüşünde sana filizlenip kanatlanırdım

suları arşınlayan ay ışığı tıkanırdı da rehin kalırdım desem

belirsiz bir bulut yağmuruyla üstümden geçip giderken 

bazen kara gözlerinde beni içine alan bir ateş yanardı 

gecenin siyahını  üstüme çeker küllerini yüzüme savururdu 

seni seven bu yürek gün dediğin saatlerde seni düşünür düşünür

anlıyacağın kimsesizliğe irkilirdi de sevildiğini de bilirdi desem

hüznümdü dağlara taşlara küs sevdan ise kederli bir ödüldü.........', 'sevgili sana benden sana senden söz ederken göğüne gözlerimin buğusundan kara güvercinler uçururdum  saçlarıma her yağmur düşüşünde sana fil...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mektup-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybedilenlere..', 'kaybedilenlere-esat-ergun-chsvf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bazılarını çok erken alır yanına...

yaşadığının farkına varamadan ölümünü haber alırsın..

sıcaklığı içini yakarken,tek bir kare resim gelir gözlerinin önüne...

ıslanır gözlerin..

titrersin..ağlayamazsın..ve bir umut o lanet olası umut daha çok acıtır içini..

acaba yaşıyor mu diye..düşünürsün..

sonra sonra gözyaşları akıverir göz pınarlarından..hıçkırırsın..

inanmak istemedigin gercek tam karsındadır..

ve ölümüne sevdiğin insanın ölümüne ağlamaktasındır..', 'bazılarını çok erken alır yanına... yaşadığının farkına varamadan ölümünü haber alırsın.. sıcaklığı içini yakarken,tek bir kare resim gelir ...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kaybedilenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız-1', 'adsiz-1-esat-ergun-him4i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gitmek en doğru olansa

durmak; 

kendini inkardır.

umut her vakit beslediğin

tesellinse yüreğine,

beklemek ahmaklıktır...', 'gitmek en doğru olansa durmak;  kendini inkardır. umut her vakit beslediğin tesellinse yüreğine, beklemek ahmaklıktır......', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/adsiz-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız-2', 'adsiz-2-esat-ergun-l0pt1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir mısra yazmak istedim ayrılık üzerine..

sadece bir tek mısra..

dökülmedi sözcükler,tıkandı bi yerlerde..

bekleyiş tüketti beni..

kendimi bilemiyorum artık..

sigaraya lanet ediyorum her bırakışımın ardından

sonra sen geliyosun aklıma

ve hüzün doluyor gözlerime..

her nefeste seni hatırlatıyor bana

şu lanet sigara..

sabırlı bekleyişlerden sonra kavuşanlara..', 'bir mısra yazmak istedim ayrılık üzerine.. sadece bir tek mısra.. dökülmedi sözcükler,tıkandı bi yerlerde.. bekleyiş tüketti beni.. kendimi ...', ARRAY['Türk Edebiyatı','Şiir','Esat Ergun']::text[], 8.5, '{"poet":"Esat Ergun","poet_slug":"esat-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/adsiz-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resmedilen resimlerde yazılan kirpikler, uzayan', 'resmedilen-resimlerde-yazilan-kirpikler-uzayan-akin-akca-y18w7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Resmedilen resimlerde yazılan, uzayan kirpikler …

Resimlere bakan, çiz gördüklerini:

Uzadı kirpiklerin.

Ve/ ama senin uzundu kirpiklerin:

Banyo mu yapmalısın öyleyse; 

Daralmak, çekmek için?', 'Resmedilen resimlerde yazılan, uzayan kirpikler … Resimlere bakan, çiz gördüklerini: Uzadı kirpiklerin. Ve/ ama senin uzundu kirpiklerin: Ba...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/resmedilen-resimlerde-yazilan-kirpikler-uzayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Sallanan Koltuk.', 'eski-sallanan-koltuk-musfik-saltik-uke37', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eskicinin vitrininde bir sallanan koltuk ilişiyor gözüme.

Hasırları yırtılmış, boyaları sıyrılmış yorgun bir koltuk.

Geriye doğru yatmış  gövdesi, adeta dinleniyormuş gibi

Donup kaldım  önünde, yardım ister gibi bakıyordu gözlerime

Çocukluğumdan beri hep bir sallanan koltuğum olsun isterdim

Nedendir bilemem, hiçbir zaman edinemedim.

Şimdi duruyor karşımda sımsıcak gülümsüyor bana

Çağırıyor  beni, hadi diyor beni buradan kurtarsana

Giriyorum dükkandan içeri hiç pazarlık etmeden alıyorum

Bu kadar  yaşlı  bir koltuk için pazarlık etmek gelmiyor içimden

Onu inciteceğimden  korkuyorum, ona fark ettirmeden parayı ödeyip

Kucaklayıp sevinçle yola koyuluyorum, koltukta ben de çok mutluyum

Benim çocukluk hayalim gerçek oldu, 

Asil, mağrur ve yorgun  sallanan koltuk

Köhne ve tozlu eskici dükkanından kurtuldu.

Eve varıyoruz,  odamın en güzel yerine koyuyorum

Önce tozunu alıyorum, yavaş yavaş sallanıyor keyifle

Yırtık hasırlarını düzeltiyorum dikkatlice

Güzelliğini bozmadan güçlendiriyorum yorgun bedenini

Arkasına gerdiğim birkaç sıra keten iple.

Sıyrılmış boyalarına hiç dokunmuyorum 

Çünkü  çirkin  durmuyor, tam aksine 

Yaşlı bir adamın yüzündeki çizgiler gibi

Onun meydan okuduğu yılları simgeliyor

Yavaşça oturuyorum sallanan koltuğuma

Kucaklıyor beni sanki teşekkür eder gibi

Yavaş yavaş sallanıyor, fısıldarcasına  gıcırdayarak

Bana hazin öyküsünü anlatıyor.

Gözlerimi huzurla kapatıyorum 

Bir masal dinler gibi onu dinliyorum

İyi bir usta onu özene bezene yapmış

Bir hasır ustası dantel gibi örmüş hasırlarını

Sonra Kanlıca’da bir yalının sahibi satın almış

O yalının en değerli mobilyalarından biri olmuş

Tam  otuz  yıl denize karşı keyifle sefa sürmüş.

Yalının sahipleri ondan bıkınca ve epeyi yaşlanınca

Saltanatı sona ermiş, evin beyi onu bahçıvana  vermiş.

Yalının salonundan bahçıvanın kulübesine taşınmış

Çok hor kullanılmış, hırpalanmış,yıpranmış, iyice aşınmış

Beş yıl sonra kapıdan geçen bir eskiciye üç milyona satılmış, 

Rutubetli, tozlu, karanlık bir depoya fırlatıp atmışlar 

Yılmamış,usanmamış,  direnmiş, pes etmemiş, dağılmamış

Aylarca sabırla beklemiş, umudunu hiç yitirmemiş

Dükkanda mal azalınca, depodan alınmış camın önüne konmuş

Güneş ısıtmış içini, kurutmuş rutubetten şişen bedenini

Kendini toparlamış, umutla, beklemeye başlamış

Birkaç gün kimse yüzüne bile bakmamış, tam umutları tükenirken

Birden bana rastlamış, onu kurtaracağımı bakışımdan anlamış

Benim ona onun bana daha anlatacak çok şeyimiz var

Bakalım ikimize de neler gösterecek gelecek yıllar.

Ben onun kurtarıcısıyım, O benim çocukluk hayalim,

İçin rahat olsun  artık hiç korkma  çilen bitti

Yaşlı  ve  yorgun   sallanan koltuğum benim.

                                                                    Haziran 2004', 'Eskicinin vitrininde bir sallanan koltuk ilişiyor gözüme. Hasırları yırtılmış, boyaları sıyrılmış yorgun bir koltuk. Geriye doğru yatmış  gö...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/eski-sallanan-koltuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Ömrün En Güzel Gecesi', 'her-omrun-en-guzel-gecesi-adnan-durmaz-dej57', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'söğüt yaprağı kapını aç bana

tomurcuğunu arala

gülünün kalbine al da arındır

bir yanın var ki

kelebek kanadından ince

dokunmaya kıyamam

içimde aygırlar azdıran bakışın başka

bungun çağlayanlar çıldırır içimde

çılgın göğün pençesidir ellerim

dağların yerle bir olur

	devrilir ormanların

seninle sürüklenir boz bulanık sellerim

her ömrün bir

	en müthiş gecesi vardır

akıl arınır beyin kıvrımlarından

yaban soluyuşu kalır som bir yüreğin

seni buldukça ölür

sana vardıkça dirilir gövdem

dudaklarında yanar bütün kurallar

ahlakın giysisini yırtar ellerin

demse işte dem... 

izin ver sularım aç kıraçlarına girsin

uçurumlarına dolayım

bir ömür saklanan gizlerini ser

gözbebeklerinde boğulayım

o zaman yıldırımlar doğurur gövdenin göğü

depremlerle sarılır kolların yangınıma

şimdi ağaçları söken parmakların senin

oysa dokunmaya kıyamazdım onlara

demdir bu

verirsin kendini bütün susuzluklarına ömrümün

vurursun yangınıma kutuplarını

söğüt yaprağı bir kapı aralanır

tomurcuğunun rahmine düşerim can gibi

demdir bu

ancak buna denir aşkın düğünü

ilk o şafak anlarız dünyanın döndüğünü

								Kasım 2001

adnan durmaz,bilirsin aşk da serseri,art yay,ank,2003', 'söğüt yaprağı kapını aç bana tomurcuğunu arala gülünün kalbine al da arındır bir yanın var ki kelebek kanadından ince dokunmaya kıyamam içim...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/her-omrun-en-guzel-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Depeç', 'depec-akin-akca-cn2jr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Başladı hemen yansıyan dört kafadardan, 

Tırmanmaya doruklarına karlı dağın! 

Çanakkale yollarından doruğuna çıktı bir katrede dağın! .. 

Ve zümrüt yeşil ve ağaçlar sapan birer! 

Taşıdığı oturağı elinde orada kurdu, ona oturdu 

Başında var tacı... 

Derin maviler anlamsızdı kızaran, 

Dalgalarında denizin kıyıya vuran! 

Kat karlı ufuksuzluğu ediyor, bırakarak iz’ini! 

Olduğu yere mavinin, kar; şimdi ulaştı; 

Tentesini oraya kurdu, 

Tekinden ampulün sarkan - 

Nağmelerin ışın güftesi altı’nda! 

Her balık bilir bilinci, öğrenemez her denizci seferi! 

   (Akrep sokar, sokamaz hepsi 

      Her birini bulamaz, koç bilir her birini..)

Okyanusun aşamaz her kendi dalgasını 

…  Bilemez her bir tonunu atmosfer basıncının; 

Gökyüzüne bakan her mağara adamı - 

Geliştiren muhakeme! 

Bir sorgu zamana, aczimendi gibi döner, 

Sakal, saç karışımı zemberek: 

Affedilmiş adımları umudun: 

Siyahlar içinde, mabedine tutunan siyahların: 

[ Kol, dalgalanan; vakumda duran! 

Hipnotize olan, karavanın önünde: 

Tatminkar eşcinsel zenci! 

   (Kıvrılan ve beyaz giysili topuz saçlar..)

      Mavi-dere-gökler’in in, beyaz süt yolundan! 

Bufallo kızıl’ı, ışıtılmış onun yüzü; 

Arka plan ışımasıyla geçmişinin ancak evrenin! 

           : C’mon! ! 

      (Haydi’ceyin!)

                        Ama mevlevi 

Bir serenat, yıldız etrafında, gezegenlerin! 

… Zamana bir sorgu! 

   (Soyunmandan sen sonra)

      Giyin! 

Köşede dur! Senin bir rahip tacı kafanda: 

Baksana, hele: Copernicus! 

Mükemmeliyet için mi durmuyorsun orada? 

pabuçların içinde? … 

: Walk, thru in my shoes! ] 

Yapışan cama surat, çanta senin için kolay –

            Keklik: 

      Durumunu taşı, 

                        Sen! 

İçinde adımlarının 

  Rendezvous! … 

El ele tutuşan mor’un içindekiler: 

Meksika için! 

   (Ölümü mor’un!)

      Bedenler, yaşadığınca-

Çıplak grup; 

Şurup içenler, yapışmış cama şırınga ile 

Ki yüzleri düzgün; 

Açılan göz, tek’i granitlerde; 

Camda diğeri -gördüğü, kendi gözbebeğini 

- Yapışan cama, burnunda; 

Soluk terleri için burun deliklerinin! ... 

Kıpkırmızı gök ve morlar içinde iki penguen 

Ve biri siyah, beyaz diğeri mor’ların; 

Uzun boyunlu, 

Kıkırdadı kükreyen şişko, soluk suratlı cüce! 

(Geriye yalpa verenler, patenler içindekiler 

Ve morlarla sarınmış bulunanlar…)

Kollar yanlara, el açar: 

Ve huzur ve sükun: 

Patlıcan burun, kamerada yüzün 

Küçük-yitik, gider, cüce; 

Seğirtir önünden,

Sıska-şişko uzun-duvara-yapışmış’ın! 

Ve huzur, sükun: 

Kamerada yüzün, 

  patlıcan burun! 

15’lik küçük: 

Kahvede kaşık, takvim yaprakları

çöp sepetine: 

 köprü altı betonarme aralığından geçen taşıtın ön camı! 

Denesen, 

Basamaklardan tünel-geçişi kolaydır: 

Channel Tunnel’ı mı kat ettin? 

  (!)

Gülümseyiş an’lık, bir; 

            tüm! 

Şey’ler düz geçişlidir, 

Evren eğridir! 

Yine de bak 

   (Sen)

      Saate 

Araba gidiyor yoldan ve kendini savunuyor: 

Yaprak düştü ızgaraya hava’dan! ... 

- 

Depeche Mode’un ‘ Enjoy the silence, A quest for time’, When i lose myself, ‘Walking in my shoes’ & ‘Little 15’ şarkılarının klipleri üzerine doğaçlama', 'Başladı hemen yansıyan dört kafadardan,  Tırmanmaya doruklarına karlı dağın!  Çanakkale yollarından doruğuna çıktı bir katrede dağın! ..  Ve...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/depec-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tomurcuk', 'tomurcuk-cengiz-oyke-295s1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir tomurcuksun daha

Açma ne olursun benim güzel tomurcuğum

Bir gül olursan çok canlar yakacaksın

Başında bekleyen şark bülbülüyle

Bizi kanlı düşman yapacaksın.', 'Bir tomurcuksun daha Açma ne olursun benim güzel tomurcuğum Bir gül olursan çok canlar yakacaksın Başında bekleyen şark bülbülüyle Bizi kanl...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Öyke']::text[], 8.5, '{"poet":"Cengiz Öyke","poet_slug":"cengiz-oyke","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tomurcuk-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cenksiz Kalmış Erlere Ağıt', 'cenksiz-kalmis-erlere-agit-hakan-sarkdemir-yd06b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bekleme artık bekleme

Beklesen de bir çünkü beklemesen de

Bu bekleyişte hiçbir denge yok

Bekleyen denk değil beklenene

Beklerdik kapılarında bir aralık beklerdik

Bir demli çay beklerdik bir demli kış sabahında

Gözlerimiz bir hizada ufukta gezinirdi

Sapanca’da bir göl bir su terazisi bir parka

Omuzlarımızı çeke çeke beklerdik

Bir tay, kendi soyunun dengesini bulup doğrulsun

Derme çatma bir yol açıldığında, 

Bir müfreze ilerlesin ağır ağır,

Çatlasın bir at

Ve boy versin bir fidan

Kutlu sabahların ardından

Kötü geçmiş gecelerin bütün dığdığı sussun

	Bilsem bu dığdığı nedir bir kuş mudur bir bilsem

İstisnasız her kuş bir duyuşla bütünleşir

Çünkü ötmese de

Beklenir

Boyuna beklenir bilmem neden

Bir acılık katar dilimize

Çatılmış tüfekler gibi hep beraber

Söylenirdik iç çeke çeke

Söylenirdik, ey geri dönmeyen erler,

Arkadaş, bu çukurlar niye

Bir tay doğsun, kendi suyunun doğrusunda kavrulsun aptallık

Beklerdik ve 

Erkenden çıkardık yola işimiz olduğunda

Katılarak aksak adımlarla bir mutluluğa

	Bilsek bu mutluluk nedir bir dığdığı mıdır bi’ bilsek

Bir baş dönmesiyle bütünleşir

Dönüşüyle kendi etrafında

Hiçbir yere varmamakla bütünleşir

Bir akın 

Bir akın istikamet levhası gibi aldırışsız

Ve ne yöne konacağı kestirilemeyen

Ey Çadırlarını Bozmuş Koca Ordu

Beklediğin bir işaret

Bir işaret midir beklediğin 

Bir işaret, acaba bi’ işaret mi beklersin

	Bilsem bu acaba nedir bi’ bilsem

Beni alıkoyan ve

Kırçıl iskeletini dolanan şehrin

Surlarında bir yıkıntı

Ya da bir işaret gibi durur parmağımda

Ya da yanmış bir karakol gibi bir kuşatmada

Ya da aydır ya da güneş

Ama bir adım değildir mutluluklara

Aşkta Savaşta Uzatmalarda

Olsa da olmasa da yenilgiler

Her mutluluk biraz iğretidir

Yoksa

Orda yoksa hiç yoksa 

Katlanırız, ey benim kavgalarım,

Katlanırız, aşkta aşkız savaşta mühimmatsız kalsak da

Katlanmak en güzelidir bekleyişlerin 

Kökü ulu bir ağaçla bütünleşir

Bilsem bu aşk nedir bir bilsem 

Hiç ilgisi yok ellerimle

Bir şeyi bir şeye ekler gibi 

Gözlerimle bütünleşir en çok neden 

Söylenirdik, boş yere hep uzatırdık söyleşiyi

Söylenirdik, ama bi’ ilgisi yoktu söylenenle

Söylesek de birdi çünkü söylemesek de

Söylenen denk değildi hiç söyleyene

Ey Çadırlarını Bozmuş Koca Ordu, 

Arkadaş, geç kalanlar var geride', 'Bekleme artık bekleme Beklesen de bir çünkü beklemesen de Bu bekleyişte hiçbir denge yok Bekleyen denk değil beklenene Beklerdik kapılarında...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şarkdemir']::text[], 8.5, '{"poet":"Hakan Şarkdemir","poet_slug":"hakan-sarkdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/cenksiz-kalmis-erlere-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-melek-midikoglu-wsfmh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eline aldığında kalemini

Yazdıkların

Aslında hiç bilmediklerindi

Okyanusa açılamamış balığın

Düşlerini okuyabildin mi hiç

Öyle ise sende ağlayacaksın

Ben kırlangıçların göç mevsiminde

Çocuk kalbimdeki kanat çırpışlarımı

Islak bir ağacın gölgesinde kaybettim

Neyse ki toprağın yeşerdiğini

Yoktan var olunanı seyreylemiştim ki

Ölü aşkın canlı şairi olmayı yeğledim

Kaybettin

Senin göç mevsiminde

Ben çoktan gitmiştim', 'Eline aldığında kalemini Yazdıkların Aslında hiç bilmediklerindi Okyanusa açılamamış balığın Düşlerini okuyabildin mi hiç Öyle ise sende ağl...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/elveda-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak İzleri', 'ayak-i-zleri-ali-osman-akca-czfz4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayak izlerin eskidi

Kokun çoktan silindi odamdan

Sen

Gelmedin

Yağmurlara yaslayıp yüzümü

Gözlerimi saldım karanlığa

Bekledim

Gelmedin

Hüznün ve umudun orta yerinde

Ellerimde yalvarışlar

Özledim

Gelmedin

Sevilere banıp yüreğimi

Geleceksin sandım

Oysa şimdi sen

Döönüşsüz yürüyüşlerdeymişsin

Tek bir anı kaldı senden bana

Adına yalnızlık dedim', 'Ayak izlerin eskidi Kokun çoktan silindi odamdan Sen Gelmedin Yağmurlara yaslayıp yüzümü Gözlerimi saldım karanlığa Bekledim Gelmedin Hüznün...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Akca']::text[], 8.5, '{"poet":"Ali Osman Akca","poet_slug":"ali-osman-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayak-izleri-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O zaman ölürüm', 'o-zaman-olurum-arslan-arslan-p5oto', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni her zaman kıskanmamı yanlış anlama,

Seni çok seviyorum deyişime,

Dilde sevgi olma deme,

Yaşadığımız o güzel anılarımızı sen unuttuğunda

İşte ben o zaman ölürüm.

Sana olan aşkımdan asla etme şüphe,

Varoluşumuzun kanıtıdır; bu hayat bu sevda

Bir gün olur çekip giderim sanma

İşte ben o zaman ölürüm.

Varlığımız zaten bize emanet

Tanrıkatında bir sen,bir ben,bir allah şahit,

Nikahımızı da bir kenara atıp gidersen,

İşte ben o zaman ölürüm.

02.06.2004', 'Seni her zaman kıskanmamı yanlış anlama, Seni çok seviyorum deyişime, Dilde sevgi olma deme, Yaşadığımız o güzel anılarımızı sen unuttuğunda...', ARRAY['Türk Edebiyatı','Şiir','Arslan Arslan']::text[], 8.5, '{"poet":"Arslan Arslan","poet_slug":"arslan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/o-zaman-olurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay mı sanıyorsun', 'kolay-mi-saniyorsun-arslan-arslan-kzdf1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gündüzün gecen onunla doldu mu hiç

Onu düşünürken ansızın rüyan oldu mu hiç

Onsuz olamayacağını düşündüğünde kahroldun mu hiç

Kolay mı sanıyorsun aşkı,sevdayı.

Ruhunu bedenini kendinde hissettin mi 

İliklerine kadar onunla doldun mu

Beynini kemiren onsuzluğu yaşadın mı

Kolay mı sanıyorsun aşkı,sevdayı

Yüreğini alıp uzaklara götürdü mü

Bedeninle başbaşa kalıp düşündün mü

Sokakta ona benzeyen birine baktın mı

Kolay mı sanıyorsun aşkı,sevdayı

Kolay mı sanıyorsun sensizliği

Kolay mı sanıyorsun aşkı sevdayı sensiz olmayı

Sevmeyi sevilmeyi

Önce yürek gerekli kolay mı sanıyorsun aşkı sevdayı

Kolay mı sanıyorsun dünyamdan

Çekip gitmeyi......

Beni böyle yaralı bırakıp terketmeyi

Terk etmek için bile yürek gerekli yürek.

02.06.2004', 'Gündüzün gecen onunla doldu mu hiç Onu düşünürken ansızın rüyan oldu mu hiç Onsuz olamayacağını düşündüğünde kahroldun mu hiç Kolay mı sanıy...', ARRAY['Türk Edebiyatı','Şiir','Arslan Arslan']::text[], 8.5, '{"poet":"Arslan Arslan","poet_slug":"arslan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kolay-mi-saniyorsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Işığım Nerdesin', 'kar-isigim-nerdesin-murat-demir-fxk6g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni her gün fırınında kavuran

Har içimde, çöl aşığım nerdesin

Poyrazıyla tipi gibi savuran

Karanlıkta kar ışığım nerdesin

Ben aşkının yanağından ter gibi

Damla damla düşüyorum nerdesin

Alev alev sıcağında el gibi

Kalakaldım üşüyorum nerdesin

Dün sevdamın çınarında dal iken

Sen gideli budak oldum nerdesin

Bir zamanlar ağzında ki bal iken

Şimdi balsız dudak oldum nerdesin', 'Beni her gün fırınında kavuran Har içimde, çöl aşığım nerdesin Poyrazıyla tipi gibi savuran Karanlıkta kar ışığım nerdesin Ben aşkının yanağ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kar-isigim-nerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında Yoktu Kastım', 'aslinda-yoktu-kastim-bayram-tunca-pnu5v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Felek yaşken eğdi boynumu

Doyamadım bozdu oyunumu

Kurda kuşa kaptırdım malımı

Kimseye anlatamadım hâlimi

Aslen, kimseyi üzmek değildi kastım

Kanayan yaralarımıza parmak bastım

Beş duyumla ortaklaşa şiirler yazdım

Belki de ibret olur diye panoya astım

Eğer ki ağlıyorsam, elbet bir ağlatan vardır

Eğer gülüyorsam, elbet bir güldüren vardır

Ne ağladığımı gören/ne gözyaşımı silen var

Ne feryadımı duyan/ne imdadıma koşan var

O’ndan başka da ne kimim ne de kimsem var

Ne malım ne mülküm ne de kalın kürküm var

Yürekten yazıp söylediğim, böyle türküm var

Kıyamet kopacak olsa da O’ndan ümidim var

B. Tunca/24.06.2004-06.24', 'Felek yaşken eğdi boynumu Doyamadım bozdu oyunumu Kurda kuşa kaptırdım malımı Kimseye anlatamadım hâlimi Aslen, kimseyi üzmek değildi kastım...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aslinda-yoktu-kastim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Olamadım', 'ben-olamadim-caner-kuru-ys6ck', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilmem ne yaparım sensiz ben burda,

Zaten yıkık dökük bu gönlüm hurda,

Sımsıkı saracak bir yuva kur da,

Bari sen mutlu ol, ben olamadım.

Bir ukde kalmıştı, hep içimdeydi

Acı, yüreğimde her biçimdeydi

Böylesi ne aklım, ne fikrimdeydi

Bari sen aynı kal ben kalamadım.

Hayat adil değil  herkese aynı,

Dosdoğru gidersin, uçurum yanı,

Dostun kim, düşman kim çok iyi tanı,

Bari sen bil canım, ben bilemedim.', 'Bilmem ne yaparım sensiz ben burda, Zaten yıkık dökük bu gönlüm hurda, Sımsıkı saracak bir yuva kur da, Bari sen mutlu ol, ben olamadım. Bir...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-olamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Suyu Bedenim', 'kar-suyu-bedenim-ethem-vayvayli-iw8yh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tutsam içime atsam denizleri,

Deniz kabuklarını, yosunları,

Şeftali çekirdeği büyüklüğünde

Çatlamış sedef parçacıklarını

Toplayıp içime atsam,

sonra taşsam! 

Çılgınca vursam kanatlarımı

Dik kayalı dudak uçlarına

Mermer bedenine, sert bakışlarına

Bir alev gibi sokulsam

Salkım söğütlerle örtülü

Nilüfer kaplı durgun gözlerine

Bir inanç gibi yayılsam

Bir medeniyet gibi benimsensem! 

İçimde deniz dolu, senin gölgen üstünde

Kısrak yelesi gibi savrulan

Dik başlı kayalardan aşıp intihar eden

Bir avuç kar suyu bedenim

Sana kavuşma arzusundan öte

Başka sultanlık değil beni yurdumdan koparan

Denizler kızı; ben bir ağuş kar suyu! 

Tut ki gözlerindir eriten beni

Ellerindir dudağına götüren beni

Aşağı Ayrancı, 01 Ocak 2004/21.28', 'Tutsam içime atsam denizleri, Deniz kabuklarını, yosunları, Şeftali çekirdeği büyüklüğünde Çatlamış sedef parçacıklarını Toplayıp içime atsa...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kar-suyu-bedenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-ethem-vayvayli-pdqlz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'solsa gündüz

sonra ne düşünsem sen,

otursam sen, kalksam sen.

o gece ki içindeki gizem

sen, inceden kesilen çiğdem

sen, solsa gün ışıkları

ortalığa ilk bastıran sen.

çığlıkların ünlemiyle

acıların çiyleriyle her gece

bir dağ gövdesi gibi

göğsüme yaslanan sen.

nerden türemiş belirsiz

birinden diğerine geçen uçurumlarınla

derin akıntıların, çarpık kentlerin

ve rüzgârlı camlarınla

bir kışa dönüşe sen.

yalnızlık!', 'solsa gündüz sonra ne düşünsem sen, otursam sen, kalksam sen. o gece ki içindeki gizem sen, inceden kesilen çiğdem sen, solsa gün ışıkları o...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizlik-171-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut, Bir Yolcu', 'umut-bir-yolcu-serap-demirturk-txcjk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yollar sonsuza kıvrılır,

Umut  bir yolcu.

Tükenir sabırlar bir gün,

Gözyaşında yıkanır sevgiler,

Hayata dair ne varsa

Bir bir erir gözlerinde.

Düne dönüş yok,

Gözler hep ufukta.

Menzil uzak olsa da

Gözler seçemese de hedefi

Umut  bir yolcu...

Serpiliverdi yeşerenler,

Hazana teslim edilenler,

Mahzenlerde saklananlar,

Yılların özlemiydi.

Kıvrılan, yollar mıydı? 

Verilen,sözler miydi? 

Hayat mı bir çiçekti,

Solmamaya yemin eden? 

Bıkkınlıktan yorulmuş,

Gözlerinde feri çökmüş,

Gelmiş de önüne durmuş

Umut sonsuz bir yolcu...', 'Yollar sonsuza kıvrılır, Umut  bir yolcu. Tükenir sabırlar bir gün, Gözyaşında yıkanır sevgiler, Hayata dair ne varsa Bir bir erir gözlerind...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/umut-bir-yolcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiş', 'gidis-turkan-sevinc-zu0ok', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmeler tutsaktı bütün yaşanmamışlıklara.

Bildiğim ne kadar hüzün varsa,

Adı konulamamış hayat hikayelerinde gizliyordu kendini.

Özlemek ve özlenebilmek adına basılıyordu, sonu hazin bütün kitaplar.

Oysa güneşin bu kadar çoğalmışken içinde

Ve her küçük zerreden büyük ummanlar yaratabiliyorken 

Korkuna yenik düşmeden; 

Öyleyse bu gidiş kandırıyordu kendini.

Ya da yeniktin bütün mesafelerime...', 'Sevmeler tutsaktı bütün yaşanmamışlıklara. Bildiğim ne kadar hüzün varsa, Adı konulamamış hayat hikayelerinde gizliyordu kendini. Özlemek ve...', ARRAY['Türk Edebiyatı','Şiir','Türkan Sevinç']::text[], 8.5, '{"poet":"Türkan Sevinç","poet_slug":"turkan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gidis-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-vedat-koseoglu-uaox3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tek bir gerçek var,

Yalanlanması mümkün değil

Bildiğim.

O; 

Seni sonsuzluk kadar çok

Sevdiğim,

Seveceğim...', 'Tek bir gerçek var, Yalanlanması mümkün değil Bildiğim. O;  Seni sonsuzluk kadar çok Sevdiğim, Seveceğim......', ARRAY['Türk Edebiyatı','Şiir','Vedat Köseoğlu']::text[], 8.5, '{"poet":"Vedat Köseoğlu","poet_slug":"vedat-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gercek-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-vedat-koseoglu-tblds', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kırmızı 

Güldü o,

Bir sabah

Kırmızısını çaldılar,

Boynu bükük

Öldü o...', 'Bir kırmızı  Güldü o, Bir sabah Kırmızısını çaldılar, Boynu bükük Öldü o......', ARRAY['Türk Edebiyatı','Şiir','Vedat Köseoğlu']::text[], 8.5, '{"poet":"Vedat Köseoğlu","poet_slug":"vedat-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gul-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesapsız', 'hesapsiz-can-ceylan-60tpz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu son şahlanışım deyip

Son kez tükendiğim yerde

Her kıvılcım ertesine 

Karabasan bindiğinde

Ümitlerim hüsran olup

Çıkmazlara girdiğimde

Aydınlıklar birbir sönüp

Lanet olsun dediğimde

Yaradana sığınıp

Ya sabır çektiğimde

Seni buldum tüm güzelliğinle

Hayatın çekilmez olduğu yerde

Ve seni sevdim

Hesaplısı olmaz ya

Seni hesapsız sevdim', 'Bu son şahlanışım deyip Son kez tükendiğim yerde Her kıvılcım ertesine  Karabasan bindiğinde Ümitlerim hüsran olup Çıkmazlara girdiğimde Ayd...', ARRAY['Türk Edebiyatı','Şiir','Can Ceylan']::text[], 8.5, '{"poet":"Can Ceylan","poet_slug":"can-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hesapsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-vedat-koseoglu-3femd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerimde gözlerin,

Hülyaya dalıyorum

Yaşadığım her anı,

Bir rüya sanıyorum...

Sakın terketme beni,

Bırakma ellerimi,

Yokluğunda güneşi,

Sönecek sanıyorum...

Nasıl? Niçin? ve neden? 

Görmeden ve bilmeden,

Dudağından dilinden,

Her söze kanıyorum..

Sakın terketme beni,

Bırakma ellerimi,

Yokluğunda güneşi,

Sönecek sanıyorum...

(Kürdilihicazkar bestelenmiştir.)', 'Gözlerimde gözlerin, Hülyaya dalıyorum Yaşadığım her anı, Bir rüya sanıyorum... Sakın terketme beni, Bırakma ellerimi, Yokluğunda güneşi, Sö...', ARRAY['Türk Edebiyatı','Şiir','Vedat Köseoğlu']::text[], 8.5, '{"poet":"Vedat Köseoğlu","poet_slug":"vedat-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ruya-124-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-vedat-koseoglu-94u7d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşmesin yüzüne gölgeler annem,

Gümüş saçın pırıl pırıl parlasın,

Güzel yüzlüm, gözbebeğim, birtanem,

Dünyalar bir yana sen bir yanasın...

Karanlık gecede mehtabım sensin,

Bilinmez dertlere dermanım sensin,

Dilimde en güzel kelamım sensin,

Dünyalar bir yana sen bir yanasın...

Varsın olmasın ekmeğim aşım,

Sen yoksan eksilmez hazanım kışım,

Dinlenir bilirsin dizinde başım,

Dünyalar bir yana sen bir yanasın...

(Nihavent bestelenmiştir)', 'Düşmesin yüzüne gölgeler annem, Gümüş saçın pırıl pırıl parlasın, Güzel yüzlüm, gözbebeğim, birtanem, Dünyalar bir yana sen bir yanasın... K...', ARRAY['Türk Edebiyatı','Şiir','Vedat Köseoğlu']::text[], 8.5, '{"poet":"Vedat Köseoğlu","poet_slug":"vedat-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/annem-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgula(ya) ma!', 'sorgula-ya-ma-selcuk-demir-66mr4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşırı bir pas kızıllığında çalınan uykularım 

amuzlarıma örtülmüş şalmıdır düşünceler? 

sorguluyorum evet herşeyi! 

sessizliğimden kopan fırtınalar... 

neyi çağrıştırır? 

kim neden sayıp söver? 

insanlar neden saygısızca sever? 

kendi koyuluklarından 

neden bunalır neden kaçar? 

son bulsun diye başlangıçlar,neden ağlar? 

veya neden başlar? 

oyunları kim neden oynar? 

bizi biz yapanlar neden bırakıp kaçar? 

bizleri kim niye sınar? 

birileri söylerken doğruları, 

birileri neden herşeyi YaLANLaR! ! 

sorgular neden anlamsız? 

anlamsızlık niye zor.... 

bilinmezlik hayatımın kaçta kaçı? 

avaralık,bu soruşturma, 

bu kendi kendini yaşayamama! ! 

bilirmisin sonsuzluk acep kaç yaşında?', 'aşırı bir pas kızıllığında çalınan uykularım  amuzlarıma örtülmüş şalmıdır düşünceler?  sorguluyorum evet herşeyi!  sessizliğimden kopan fır...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Demir']::text[], 8.5, '{"poet":"Selçuk Demir","poet_slug":"selcuk-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sorgula-ya-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Benim Menecerim', 'o-benim-menecerim-necmi-unsal-0gqsr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani bana şiir diyen menecerim  İ. K ''a:

Güçlü bir dost

Gurbetin bağrında.

Serin bir meltem

Hasretin kahrında.

Omuzdaş darlıkta.

O benim menecerim.

Onundur gönlümde

En güzel yerim.

Kendisi gibi 

Sözü de çok sempatik.

Güzel işlerde aceleci,

Atik mi atik! 

Laf anlatamaz 

Düğünlerde göbeğine.

Pikniklerde dalar

Izgaranın öbeğine.

Sözü özü bir,

Samimiyeti içten.

Güzel bir sohbet buldumu,

Güller açar sevinçten.

Ey görkem sahibi,

Seni nasıl unuturum! 

Sen iste yeter ki,

Baltık''ı kuruturum.

Ey güzel insan,

Benim can menecerim! 

Senin için ben

Ölmüş tavuk bile yerim.

Bahtını hoş, keskin etsin; 

Adın gibi ihlas kılıcın.

Ruhunu teskin etsin

Ulvî manada ilacın.

24 Haziran 2004 Perşembe, Danimarka-Køge 19:20', 'Hani bana şiir diyen menecerim  İ. K ''a: Güçlü bir dost Gurbetin bağrında. Serin bir meltem Hasretin kahrında. Omuzdaş darlıkta. O benim men...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/o-benim-menecerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Aşkın Unutulmadığı Gerçeği...', 'i-lk-askin-unutulmadigi-gercegi-halil-kesken-aej24', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bundan tam on yıl önceydi

Okula giderken,

Servisin camından görürdüm seni

O ağaçlı yolda 

Hep pürtelaş giderdin

Eteklerin yerleri süpürürdü.

Beni farketmiş; 

Bazı sabahlar göz kırpar,

Bazı sabahlar gülümserdin.

Herşey bi yana da,

Gülüşünle beni mahvederdin

İsmini bildiğimden değil,

Kendimi mecnun yerine koyduğumdan; 

Bütün arkadaşlarım abla derdi,

Sadece ben Leyla...

Arkadaşlarım okula zorla,

Sadece ben zevkle giderdim.

Hiç bir sabah annem kaldırmazdı beni; 

Çünkü servis kaçarsa,

Sen de kaçardın...

Ve böylece tam on yıl geçti; 

Şimdiyse işe giderken görüyorum seni,

Bende değişen tek şey; 

Okul üniforması,

Sendeyse çok şey değişmiş:

O uzun eteğin epeyce çekmiş,

Kol çantanın yerine ise,

Kır saçlı bir bey geçmiş...

Artık asla benim olamayacağını anladım...

Ama...

İlk aşkın unutulmadığı da

Gerçekmiş....', 'Bundan tam on yıl önceydi Okula giderken, Servisin camından görürdüm seni O ağaçlı yolda  Hep pürtelaş giderdin Eteklerin yerleri süpürürdü....', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ilk-askin-unutulmadigi-gercegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir', 'sehir-ali-gencay-w37pc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabahına uyandığın şehir,neden bu hüzün,kasvet nedendir

Kadınlar,çocuklar ve adamlar, neden ölüme yürümektedir.

Dilenci, tut yine köşe başını,ırgat, dök terini,at telaşını

Çöpçüler,süpürün kaldırımları,temizleyin kandan her taşını

Okuyun! ! Dizelere dökülen,mürekkep değil kandır

Unutmayın! ! Bir şehri acısıyla yıkan,canavar değil insandır.', 'Sabahına uyandığın şehir,neden bu hüzün,kasvet nedendir Kadınlar,çocuklar ve adamlar, neden ölüme yürümektedir. Dilenci, tut yine köşe başın...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sehir-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni...', 'bekle-beni-metin-bilgen-rbokk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatın çakıllı yollarında

Mahzun bıraktığın ben

Şimdi gözlerden ırak

Bir üzgün bir şakrak

Geçmede günlerim

Yeni baharlara gebe

Uzantısıyız sevenlerin

Hasret treninde

Uzayıp gitmede

Gelemeyecek olan yarınlar

Bekle beni

Sonsuza dek ufukta.', 'Hayatın çakıllı yollarında Mahzun bıraktığın ben Şimdi gözlerden ırak Bir üzgün bir şakrak Geçmede günlerim Yeni baharlara gebe Uzantısıyız ...', ARRAY['Türk Edebiyatı','Şiir','Metin Bilgen']::text[], 8.5, '{"poet":"Metin Bilgen","poet_slug":"metin-bilgen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekle-beni-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Gelen İlk Bahar...', 'gec-gelen-i-lk-bahar-metin-bilgen-7bwr6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ömrümün geç gelen

Bu ilk baharında

Şimdi baykuşlar öter

Figan edip doyasıya

Gurup vakti gözlerim dolar

Kalbim için için ağlar

Kısıtlı kalan ömrümün

Sahte geçen son baharında

Ne rüzgarlar şarkı söylerler

Ne de mehtapta serenatlar

Avuçlarımdan yavaşça kayar

Mazide kalan umutlar

Ne Viyana’daki valsler

Ne de Venedik’teki gondollar

Sen olmayınca

Geç kalan umutlarımın

Son baharında neye yarar', 'Ömrümün geç gelen Bu ilk baharında Şimdi baykuşlar öter Figan edip doyasıya Gurup vakti gözlerim dolar Kalbim için için ağlar Kısıtlı kalan ...', ARRAY['Türk Edebiyatı','Şiir','Metin Bilgen']::text[], 8.5, '{"poet":"Metin Bilgen","poet_slug":"metin-bilgen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gec-gelen-ilk-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden İzler', 'senden-i-zler-metin-bilgen-a3hwo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tabiatın can bulduğu

Nisan akşamlarında

Şarkılardan nağmeler

Bana neler söylüyor neler

Dönmemesiye gittiğin

Yirmi beş nisan

O en acı gün

Papatyalar bile çise çise

Sana söylüyor içli dizeler

Yakıyor acıtıyor beni

Perişan etse de beni

Yaşamak şimdi daha zor

Ve de daha anlamsız

Senden bana kaldı

Bir hoş sada vasiyet

Gidenin dönmeyeceği

Yaşamın bir gerçeği

Gel de bunu kor halindeki

Yüreğime anlat

Belki anlarda yaşamı kavrar

Umutlara merhaba der

Hayat devam eder

Benimle ebediyen

Kalacaktır senden izler', 'Tabiatın can bulduğu Nisan akşamlarında Şarkılardan nağmeler Bana neler söylüyor neler Dönmemesiye gittiğin Yirmi beş nisan O en acı gün Pap...', ARRAY['Türk Edebiyatı','Şiir','Metin Bilgen']::text[], 8.5, '{"poet":"Metin Bilgen","poet_slug":"metin-bilgen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/senden-izler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutsuz musun?', 'mutsuz-musun-metin-bilgen-yb3fv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saçlarının telinde sanki meltemler gizli

Okşamak istesem de hırçın

Yılların girdabında

Bir özgün bir tutkun

Ve de mutsuz musun? 

Acaba yanılıyor muyum? 

Yaz akşamlarının koynunda

Bulutsuzluk özlemi

Beni bu kadar mı etkiledi? 

Denizdeki yakamozlar

Sahildeki çakıllar

Martılardan şarkılar

Sanki gözlerinde

Derinleştikçe gitti

Ruhuma zalimce girdi

Geçen ömrümde o günlerin

Birer hatırası sanki

Bende ebediyen yaşayacaktır

Özgün ve üzgün o özel günler.', 'Saçlarının telinde sanki meltemler gizli Okşamak istesem de hırçın Yılların girdabında Bir özgün bir tutkun Ve de mutsuz musun?  Acaba yanıl...', ARRAY['Türk Edebiyatı','Şiir','Metin Bilgen']::text[], 8.5, '{"poet":"Metin Bilgen","poet_slug":"metin-bilgen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mutsuz-musun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Arar mısın?', 'beni-arar-misin-metin-bilgen-nkmwh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağlardan esen ılgın ılgın rüzgarın esiriyim

Her güneşin doğuşu

Yeni bir umut benim için

Sensiz geçen ömrümde

Ne ilk olacak ne son

Yaşamım da belki

Yaş görmedin gözlerimde

Çırpınan yüreğim şimdi ellerinde

Söyleyemediğim dertlerim

Bilmiyorum gizlerinde

Çiçeklerden bir demet

Versem acaba ağlar mısın? 

Gelir misin göz yaşlarımın

Denizinde beni arar mısın?', 'Dağlardan esen ılgın ılgın rüzgarın esiriyim Her güneşin doğuşu Yeni bir umut benim için Sensiz geçen ömrümde Ne ilk olacak ne son Yaşamım d...', ARRAY['Türk Edebiyatı','Şiir','Metin Bilgen']::text[], 8.5, '{"poet":"Metin Bilgen","poet_slug":"metin-bilgen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/beni-arar-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Akabe İçindeyim', 'bir-akabe-i-cindeyim-galip-sinecikli-efmhs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir akabe içindeyim

nasıl çıkılır

nereye gidilir hiç bilmiyorum

uzanıyorum

kör karanlığı yırtmak istiyorum

bir dost eline muhtaç

bir yarene açım

heyhat! 

ne bir dost elini uzatıyor

ne de bir yaren derdime derman

bir akabe içindeyim

çıkamıyorum...', 'bir akabe içindeyim nasıl çıkılır nereye gidilir hiç bilmiyorum uzanıyorum kör karanlığı yırtmak istiyorum bir dost eline muhtaç bir yarene ...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-akabe-icindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Ordayım', 'yine-ordayim-i-smet-barlioglu-etjw1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine kar kapattı yüce dağları,

Yine ateşlerde, yine kordayım,

Beyaz tüller örttü yeşil bağları,

Ben yine yanında, yine ordayım.

Döndü rüyalarım yine kabusa,

Hasretten kalbime ne hal olduysa,

Tükenen ömrümden kaç gün kaldıysa

O kalan ömürle oralardayım.

Gelmek istiyorum, gelemiyorum,

Ölmek istiyorum, ölemiyorum,

Kader bırakmıyor, gülemiyorum,

Çileler içinde yaman zordayım.

Gün senle başlıyor, geceler senle,

Savaşa girmişim sanki elemle,

Derde düşüyorum her gelen günle,

Her gün ızdırapta, her gün dardayım.

Sevgi ne güçlüymüş böyle uzakta,

Kalbim bir pençede, kanım tırnakta,

Ruhum çilelerde, gövdem çarmıhta,

Bildiğim hiç yok ki; acep nerdeyim.

Yine gece geldi, uykulardasın,

Kimbilir ne rahat yataklardasın,

Tam bir mutlulukta, ferahlardasın,

Ben ise her gece işkencedeyim.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 77-78/100)', 'Yine kar kapattı yüce dağları, Yine ateşlerde, yine kordayım, Beyaz tüller örttü yeşil bağları, Ben yine yanında, yine ordayım. Döndü rüyala...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yine-ordayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Lambaları', 'sokak-lambalari-i-smet-barlioglu-z0l6f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sokak lambaları yeniden yandı,

Evlerde perdeler kapatılıyor.

Bedenim yeniden sokakta kaldı,

Kalbim ateşlerde kaynatılıyor.

Sokaklar ıpıssız, dar ve karanlık,

Yüreğim idamlık, ruhum zindanlık,

Gölgeler belirip gider bir anlık,

Bir garip bulunmuş, aldatılıyor.

Yalnızlık bir vahşi kartal çevremde,

Onulmaz yaralar açtı gövdemde,

Bir elim kederde, biri dertlerde,

Her çilem öekilip uzatılıyor.

Her perde ardında sanki sen varsın,

Ya şarkı söylersin, ya saç tararsın,

Beni bir yitirsen nasıl ararsın,

Günlerim habire azaltılıyor.

Bir sensin dolduran koca dünyamı,

Evleri, sokağı ve herbir yanı,

Canım hayalinin yorgun kervanı,

Peşinde yollarım düzeltiliyor.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 79-80/100)', 'Sokak lambaları yeniden yandı, Evlerde perdeler kapatılıyor. Bedenim yeniden sokakta kaldı, Kalbim ateşlerde kaynatılıyor. Sokaklar ıpıssız,...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sokak-lambalari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uslanmayan Gönlüm', 'uslanmayan-gonlum-i-smet-barlioglu-h4fa8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dallarda yapraklar çiçek içinde,

Derelerde sular köpükleniyor.

Uslanmayan gönlüm senin peşinde,

Kopmuş yaprak gibi sürükleniyor.

Ne çiçek çaredir azaplarıma,

Ne sular teselli dudaklarıma,

Hıçkırıkla dolu dualarıma

Renk veren saçların örükleniyor.

Sana hasret kalmak kabus düşümde,

Yeniden doğarım her görüşümde,

Aşkın bir yırtıcı kartal başımda,

Pençesinde kalbim didikleniyor.

Her nereye baksam her yer boş gibi,

İşte yaşıyorum hiç yokmuş gibi,

Kalbime bir mızrak saplanmış gibi

Feryadım göklere direkleniyor.

Sensizlik bir azap, sensizlik cefa,

Bunu ki denedim yüzlerce defa,

Seni hayal etmek en büyük vefa,

Hasret yüreğime çörekleniyor.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 81-82/100)', 'Dallarda yapraklar çiçek içinde, Derelerde sular köpükleniyor. Uslanmayan gönlüm senin peşinde, Kopmuş yaprak gibi sürükleniyor. Ne çiçek ça...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uslanmayan-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman', 'ne-zaman-i-smet-barlioglu-21q52', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir yudum içsem ağlarım,

Bağrıma zehirli oklar saplanır.

Nasıl üzülürüm, nasıl yanarım,

İçimde küllenen dertler uyanır.

Hayalin rengarenk kadehlerimde,

Duran kadeh değil, sensin elimde,

Aşkımız bir alev olur gönlümde,

Yaralı yüreğim kana boyanır.

Sanırım gelmişsin, buralardasın,

Rakıda, şarapta, biralardasın,

Bir tablo olmuşsun, duvarlardasın,

Öyle gerçeksin ki; gören aldanır.

Uzanan ellerim geri döner boş,

İçkiler kadehsiz, kadehler bomboş,

Taliim serseri, kaderim sarhoş,

Ağlayıp anlatsam kimler inanır.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 83-84/100)', 'Ne zaman bir yudum içsem ağlarım, Bağrıma zehirli oklar saplanır. Nasıl üzülürüm, nasıl yanarım, İçimde küllenen dertler uyanır. Hayalin ren...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-zaman-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumar', 'kumar-sirma-mersin-tx9ai', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat bi kumarsa

Ben bu kumarı

Kaç kişi ile oynuyorum

Bilmiyorum

24.06.04', 'Hayat bi kumarsa Ben bu kumarı Kaç kişi ile oynuyorum Bilmiyorum 24.06.04...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kumar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedendir', 'nedendir-oguzkan-bolukbasi-n8rlk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamadığım yerlerde gezmek istiyorum

Tadını bilmediğim lezzetleri tatmak

Bir sabah vakti

Gökleri çatılmamış bir dünyada uyanmak

Nedendir sen aklıma gelince böylesine duygular yaşadığım

Firar etmek istercesine

Anlamsız çiçekler açan gözlerine

Bakmaya korktuğum zamanlar', 'Yaşamadığım yerlerde gezmek istiyorum Tadını bilmediğim lezzetleri tatmak Bir sabah vakti Gökleri çatılmamış bir dünyada uyanmak Nedendir se...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nedendir-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Yazının Sesi', 'bi-yazinin-sesi-sirma-mersin-n0ddm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiir

Öksüzü kalmış imgeler

İşaretler arasında 

Soluklanırken

Önce heceler birleşip

Kelime olur

Kelimelerde yan yana gelip

Cümle olur

Böylece başlamış olur

Bir yazının seslenişi

Yazılan herşeyde 

Okunması gerekmez

Tıpkı bu yazı gibi....

25.06.04

...........................Bugüne kadar hep duygular konuşmuştu..............', 'Şiir Öksüzü kalmış imgeler İşaretler arasında  Soluklanırken Önce heceler birleşip Kelime olur Kelimelerde yan yana gelip Cümle olur Böylece...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bi-yazinin-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '23 Nisan', '23-nisan-mehmet-akbaba-l11xx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ulu önder ATATÜRK''ün eseri,

Kutlu olsun yirmiüç nisan çocuklar.

Şenlik olsun memleketin her yeri,

Kutlu olsun yirmiüç nisan çocuklar.

Atamızın bayramıdır,bu bayram.

Ay yıldız bayrağına kurban can.

Çiçeklerle süslensin bu vatan,

Kutlu olsun yirmiüç nisan çocuklar.

Semah dönsün,gökyüzünde uçaklar.

Açılsın sevgiye, kollar kucaklar.

Kör olsun kem bakan,gözler mihraklar.

Kutlu olsun yirmiüç nisan çocuklar.

Selâm sana,dalgalanan ay yıldızım.

Bayram bizim,şenlik bizim,şan bizim

Rahat uyu hep tutulacak izin.

Kutlu olsun yirmi üç nisan çocuklar.

Yiğitler kuşansın,atlar şahlansın.

Alaylar kurulsun meşale yansın.

Çoçuklar bayramlık giysin uyansın.

Kutlu olsun bayramınız çocuklar.

Sazların yanında bulundurun ney,

Hep birlikte nara atalım hey ki hey.

AKBABA var olsun,bu vatan,bu soy.

Kutlu olsun bayramınız çocuklar.', 'Ulu önder ATATÜRK''ün eseri, Kutlu olsun yirmiüç nisan çocuklar. Şenlik olsun memleketin her yeri, Kutlu olsun yirmiüç nisan çocuklar. Atamız...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akbaba']::text[], 8.5, '{"poet":"Mehmet Akbaba","poet_slug":"mehmet-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/23-nisan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Zaman Gibi Bakarsın...', 'sen-zaman-gibi-bakarsin-adnan-durmaz-pdlib', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tepeden tırnağa bulut kesilmiş gür

gümbür gümbür sonsuzu devinir içinde bin bir renk

akşamı giyinmiş tepelerin üzerinde alabildiğince derinsin

alabildiğince uzaksın

	bir şeyler okurcasına dalgaların kitabından

gecenin laciverdinden dikilmiş yıldızlı eteklerin

oysa bütün yangın yerlerini bilirsin

hicran gibi bakarsın ey kadın

harabelerden geçtin

ot bitmez kıraçlardan

sen vurulmuş göçmen kuşun yoldaşı 

mezarlıklar dolaştın 

kaç kırılmış düşün düştüğü yerde

kan ağladın-ki seller bilir avazını

şimdi dalgın ve yaralı

ceylan gibi bakarsın ey kadın

akşamının son durağı tepelerde

	özlenmeyecek kadar uzaksın

renkten renge bulutlar devinir içinde gür

hüznün ve sevincin dağları üzerinden

	sonsuza uzanan bir yol gözlerin

		derin ve pür

gökyüzünde vurulmuş kuş duygular yaşadın onca

yürek eli kolu kopuk 

kaç öksüz kaldın ortada

gayri ne dağların yıkılır senin

ne yakılır ormanın

gece giyen duygulara 

sultan gibi bakarsın ey kadın

suskunun dallarından

	yek avaz gazeller dökülen hüzün

eteklerinin kokusunda

	boşuna gül arayan serseri rüzgar

kadim bir tanrıça heykeli sanıp dudaklarında

sevda söylencelerinden öpüşler gezen akşam

ayaklarının dibinde öldüğü zaman

bakmakların yetmediği yüreğe

bilinmedik çağlayanlar dökülür

sırtında yıldızlı harmanisi gecenin

bilinmezden bilinmeze akarsın

orada sonsuzluğun son bekçisi gözlerin

ey kadın sen zaman gibi bakarsın 

							

Ekim 2001

adnan durmaz,bilirsin aşk da serseri,art yay,ank,2003', 'tepeden tırnağa bulut kesilmiş gür gümbür gümbür sonsuzu devinir içinde bin bir renk akşamı giyinmiş tepelerin üzerinde alabildiğince derins...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/sen-zaman-gibi-bakarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanlar süzülürken / Hikayeler iki (2)', 'kanlar-suzulurken-hikayeler-iki-2-gencay-coskun-ulua6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir zorunlu haykırıştı 

Hiç sesim bile çıkmamıştı 

Kaygan bir yapısı vardı 

Hayat denilen 

Keskin nesnenin 

Tutmak zorundaydım 

Onu sımsıkı ellerimde 

Kayarken ellerimden 

Kesiverdi bileklerimi 

Bu sevgisizlikte 

Tüm gücümü yitirirken 

Gözlerimde belirmişti hayali

Ulaşılmaz olanın özlemi

Hayatın kalan kırıklarını 

Kimselerin ayaklarına

Batmasın diye 

Toplama telaşından 

Bileklerimden 

Kanlar süzülürken 

İçim özgürlüğün 

İlk dalgasıyla 

Dışarı akıyordu 

Çaresiz bakıyordum 

Allı ama pulsuz renklere 

Canımda acıyordu 

Bir yandan 

Başkasının acımasın diyeydi çabam 

Çabalayıp 

Debeleyip

Güllere su verir gibi 

Siliyordum hayattan

Bıraktığım son izlerimi 

Kanlar süzülürken 

Anılarımda süzülüyordu

Büyük eleklerin 

Küçük ilmeklerinden 

Geçiyorlardı

Geçtiği yerlerde sanal hüküm sürüyorlardı 

Bir şeyler belli belirsiz 

Kayboluyordu gözlerimin önünden

Ne geleni 

Ne de gideni biliyordum 

Kanlar süzülürken 

Tek çözenli 

Çok bilinmeyenli 

Hayatsal Denklerimi

Hayati saniyelerde çözüyordum

Süzüldükçe kanlar 

Bende çözülüyordum 

Durduk yere 

Aklıma geliyordu 

Gidenlerim 

Daha gelme diyorlardı 

Az durup düşünüyordum 

Ben nereye gidiyordum

Kuş sesine uyanıyordum 

Allarla dolu yorganımdan 

Yoğurda bulaşmış parmaklarıma 

Zedelenmiş etime bakıp 

Öpüyordum usulca 

Düşürdüğüm için kendimi 

Hayattan alların içine doğru 

Af diler gibi 

Sarılıyordum beyazlara

Bem beyaz ufuklara 

Denize açılmıyordum 

İki ayağım hep karada 

Zaten açılamazdım 

Bir kez olsun

Yüzmeyi bilememiştim 

Kanlar süzülürken 

Umutlarım azalıyordu 

Bir yerlerde 

Sevdiğim çiçeklerle 

Dolu tek bir dünyam vardı 

Namzet bir gamze

Laf bile dinlemezdi

Sevgiyi hiç bilmezdi 

Ezip ezip geçerdi

Bozulan hep içimdi 

Bu yüzden dışıma 

Taşmak istemişti 

Belki düşüş bir bahaneydi 

Gidişim tamamen 

Bir kaza süsüydü 

Tek farkı okullarda 

Camları süslemeyecek kadar 

Etkili olmasıydı 

Kapıdan çevrilmeseydim 

Çoktan gitmiş olacaktım 

Kanlar süzülürken 

Yep yeni bir koku alıyordum 

Ya da koku beni alıyordu 

Yavaş yavaş beyazlıyordu dünya 

Tüm renkler ilk 

En temiz 

En saf 

Haline doğru açılıyordu

Affediyordum 

En azılı kalp kıranlarımı 

En azılı düşmanlarımı 

Sizi en yüksek makama 

Özenle affedilmiştir diye 

Havale ediyordum 

Giderken mutlu olsunlar diye

Aslında onlar hep mutluydu 

Sevgiyle oyuncak gibi 

Oynadıklarında 

Kanlar süzülürken 

Kendime geliyordum 

Gidersem 

Sevdiklerimin sesinin duyamazdım

Her ne kadar benim olmasalar da artık

Bir günde sırtını dönüp gitmek varmıydı 

Gidenlere inat ben 

Durmalıydım

Duracaktım 

Son durak geçmeden 

Arada bir yerde 

Elimde yoğurtlu bir kase 

İniverdim 

Bir şey değil yoğurdu bile yemedim 

Belki bundan sonra 

Sevdiklerime candan gülemeyip 

Sanal gülüşler çabasına girecektim 

Belki bundan sonra 

Tüm kalabalıklarda 

Hep tanıdık bir yabancı olacaktım

Adı bilinen içi bilinmeyen 

Bir iç kaçak olup 

Kendi çöllerimde 

Sevgiyi arayacaktım 

Belki bundan sonra 

Kendim hariç herkesi 

Affetmenin ağırlığını 

Ömür boyu taşıyacaktım

Kalp kıranı da sevecektim 

Cahilliğine bir şey diyemezdim

Bir gün bir şeyleri 

Benim gibi acı olarak 

Öğrenmesini de asla istemezdim 

Ama kalp kıran 

Sevgiyi öğrendiğinde 

Zaman başını çoktan almış

Bende kuyruğunda kalmış olacaktım….

Belki bundan sonra 

Kanlar süzülmeyecekti 

İçim hep birisini özleyecekti 

Her kaybedişte olmazdı belki ama benim 

Ömrüm 

Yalnızca 

Sığıntı tanıdık barınakların duvarlarında 

Ve birazda şansım varsa ki

Hiç olmadı 

Tek damla sevgisiz 

Küçük bir pencereden 

Dünyaya süzülecekti 

Not: Kaseye kavanozda diyebilirsiniz…. Ben dedim…', 'Bir zorunlu haykırıştı  Hiç sesim bile çıkmamıştı  Kaygan bir yapısı vardı  Hayat denilen  Keskin nesnenin  Tutmak zorundaydım  Onu sımsıkı ...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":158,"source_url":"https://www.antoloji.com/kanlar-suzulurken-hikayeler-iki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsin?', 'kimsin-hasan-sakman-e2ies', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlemi yakıyordu yüreğimi sevgilerin

ve umutsuzdum artık.

Arıyordum köşe bucak mutluluğu

galiba yakalıyorum kuyruğundan.

Kimsin sen? 

sesin niye çınlıyor kulaklarımda? 

Rüyada mıyım? 

öyleyse olmak istemiyorum

uyandırsın biri beni.

(16 Kasım 2001)', 'Özlemi yakıyordu yüreğimi sevgilerin ve umutsuzdum artık. Arıyordum köşe bucak mutluluğu galiba yakalıyorum kuyruğundan. Kimsin sen?  sesin ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kimsin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* H a s b i h a l *Akrostiş*', 'h-a-s-b-i-h-a-l-akrostis-halit-demir-zh0k3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'H akikattır bu sözün, yürekler yüreğinde

A şka çağırdın gözüm, özümüz özünüzde

S evgi anaç ilkedir, kardeşlik meclisinde

B u birlik-beraberlik,  binanın temelinde

İ lk önde gelir bilin, saygınlık şairlerde

H er hasbihal üyesi, taşır örf ve ananede

A rkadaşlık nevvâredir, sürercektir  ebet de

L afz-ı kelâm bilenler, bu ocağın içinde

25.06.2004

(Edebiyat, Şiir kategorisindeki Hasbihal Grubuna ithaf ediyorum.) 

Sevgili Dostum Metin Eser kardeşimin Hasbihal grubu için yazmış olduğu  ''Hasbihal'' şiirine naziredir...', 'H akikattır bu sözün, yürekler yüreğinde A şka çağırdın gözüm, özümüz özünüzde S evgi anaç ilkedir, kardeşlik meclisinde B u birlik-beraberl...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/h-a-s-b-i-h-a-l-akrostis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-hasan-sakman-8ahz1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Odamdayım,

camın önünde.

İzliyorum karanlığı korkuyla.

Korkuyorum ve üşüyorum da! 

Düşünüyorum buğulansa diye odamın camı

görünmez korkutan gecenin karanlığı.

Kurtulunca karanlığından gecenin,

giyinirim beyazlarımı

ve seni düşünürüm 

beyazlı sarılı papatyalar arasında.

Biliyorum mevsim kış! 

ay kasım, gün on yedisi

sesin net kulaklarımda

yüreğimde ise derin bir aşk endişesi...

(17 Kasım 2001)', 'Odamdayım, camın önünde. İzliyorum karanlığı korkuyla. Korkuyorum ve üşüyorum da!  Düşünüyorum buğulansa diye odamın camı görünmez korkutan ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/korku-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemiyorum', 'bilemiyorum-aydanur-basci-l7awl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni başkasıyla görmek mi

Yoksa; 

Kara toprağın olduğunu görmek mi

Daha acı olur, bilemiyorum

Buralardan çekip gitmek mi

Yoksa; 

Kapını çalıp sevdiğimi söylemek mi

Daha kolay olur, bilemiyorum

Seni unutmak mı

Yoksa; 

Unutmayacak kadar sevmek mi

Daha zor olur, bilemiyorum

Kaderimi değiştirmek mi

Yoksa; 

Kendimi değiştirmek mi 

Daha basit olur, bilemiyorum.



20.06.2003

Cuma

01.00', 'Seni başkasıyla görmek mi Yoksa;  Kara toprağın olduğunu görmek mi Daha acı olur, bilemiyorum Buralardan çekip gitmek mi Yoksa;  Kapını çalı...', ARRAY['Türk Edebiyatı','Şiir','Aydanur Başcı']::text[], 8.5, '{"poet":"Aydanur Başcı","poet_slug":"aydanur-basci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bilemiyorum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya II', 'ruya-ii-hasan-sakman-q4tdm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Derin okyanuslarda hissediyorum kendimi,

radyodan hüzünlü şarkılar dökülüyor

uykulu oda duvarları arasında.

Seni görmeden zihnimde canlandırıyorum

ve bir rüyaya dalıyorum,

                                       sessizce! 

şimdi bembeyaz bulutlara karışıyorum,

yağmur olup yağmak istiyorum üzerine! 

Bir akıntıya kapılıyorum derinliğinde 

okyanusumun.

Kaybolmaktan korkuyorum akıntında

kurtar beni,

                   ne olursun! 

(17 Kasım 2001)', 'Derin okyanuslarda hissediyorum kendimi, radyodan hüzünlü şarkılar dökülüyor uykulu oda duvarları arasında. Seni görmeden zihnimde canlandır...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ruya-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-aydanur-basci-f0joz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarım, ağaran saçlarım

Hepsi bir yana

Ben hala bekliyorum

Geçmesini bilmeyen

Bir sonraki yılları

Umutlarım, kırılan kalbim

Hepsi bir yana

Ben hala bekliyorum

Geçmesini bilmeyen

Bir sonraki ayları

Yalnızlığım, kaybolan benliğim

Hepsi bir yana

Ben hala bekliyorum

Geçmesini bilmeyen

Bir sonraki haftaları

Uykularım, kabuslu rüyalarım

Hepsi bir yana

Ben hala bekliyorum

Geçmesini bilmeyen

Bir sonraki günleri

Odam, buz gibi yatağım

Hepsi bir yana

Ben hala bekliyorum

Geçmesini bilmeyen

Bir sonraki saatleri

Mutsuzluğum, derbeder halim

Hepsi bir yana

Ben hala bekliyorum

Geçmesini bilmeyen

Bir sonraki dakikaları

Kaderim, acı kaderim

Hepsi bir yana

Ben hala bekliyorum

Geçmesini bilmeyen

Saniyeler sonundaki ölümü.

21.06.2003

C.tesi

22:00', 'Gözyaşlarım, ağaran saçlarım Hepsi bir yana Ben hala bekliyorum Geçmesini bilmeyen Bir sonraki yılları Umutlarım, kırılan kalbim Hepsi bir y...', ARRAY['Türk Edebiyatı','Şiir','Aydanur Başcı']::text[], 8.5, '{"poet":"Aydanur Başcı","poet_slug":"aydanur-basci","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bekliyorum-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinlesene', 'dinlesene-aydanur-basci-djgd2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bitmeli, bu aşk bitmeli

Yetmeli, gücüm yetmeli

Bu aşkı bitirmeye

Sonu yok seninle

Kader benden yana

Güle güle,

Sözüm sana dinlesene

Dur dinle, dinlemeden gitme

Yüzüme bak, bakmadan gitme

Gideceksen eğer

Sonu yok seninle

Kader benden yana

Güle güle, sözüm sana dinlesene

Olamam, seninle olamam

Kalamam, seninle kalamam

Bu aşk bitmeli

Sonu yok seninle

Kader benden yana

Güle güle,sözüm sana dinlesene

07.03.2003', 'Bitmeli, bu aşk bitmeli Yetmeli, gücüm yetmeli Bu aşkı bitirmeye Sonu yok seninle Kader benden yana Güle güle, Sözüm sana dinlesene Dur dinl...', ARRAY['Türk Edebiyatı','Şiir','Aydanur Başcı']::text[], 8.5, '{"poet":"Aydanur Başcı","poet_slug":"aydanur-basci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dinlesene-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünürüm', 'seni-dusunurum-hasan-sakman-4m50o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelincik tarlalarında yürürken sen,

ben kuytu bir köşede ayı izliyorum.

Gelincikler kırmızı, mor

ay beyaz.

Sevmekten galiba yorgunum biraz

çökmüşüm bir kenara

bir de sigara yakmışım.

Bu yorgunlukta bile seni düşünürüm.

(28 Aralık 2001)', 'Gelincik tarlalarında yürürken sen, ben kuytu bir köşede ayı izliyorum. Gelincikler kırmızı, mor ay beyaz. Sevmekten galiba yorgunum biraz ç...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-dusunurum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim kapalı', 'gozlerim-kapali-aydanur-basci-b5k96', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yürüyorum gözlerim kapalı

Gecenin ıssız karanlığında

Uzun ve ince bir yolda

Gökyüzünde yıldızlarla

Ve de sessizliğin sesi ile

Yürüyorum gözlerim kapalı

Etrafta öten cır cır böceğiyle

Bir de esip geçen rüzgarla

Yürüyorum gözlerim kapalı

Yürüyorum ama nereye kadar

Aslında sonu yok, bende biliyorum

Ama bir umut almış gidiyorum

Gidebildiğim, dayanabildiğim kadar

Yürüyeceğim bu yolda gözlerim kapalı

2000', 'Yürüyorum gözlerim kapalı Gecenin ıssız karanlığında Uzun ve ince bir yolda Gökyüzünde yıldızlarla Ve de sessizliğin sesi ile Yürüyorum gözl...', ARRAY['Türk Edebiyatı','Şiir','Aydanur Başcı']::text[], 8.5, '{"poet":"Aydanur Başcı","poet_slug":"aydanur-basci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gozlerim-kapali-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-ozkan-ozdogan-oht44', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senle biz,

dağı taşı yıkacak kadar

huysuz bir fırtına yüküyle,

beraber büyüyoruz.

Ne ağaç kalıyor yakmadık,

ne korkutmadık balıkçı..

Gözüm gözünü görmüyor 

bazen yağmurdan,

sesinin yerine de

ardıardına gökgürültüsü..

Bekliyoruz sonra 

güneş açsa da,

kurusa açılmış yaralarımız.

Halbuki deniz yeterdi 

canımı yakmaya,

her bir sözün yerine

gümüşî tuzuyla.', 'Senle biz, dağı taşı yıkacak kadar huysuz bir fırtına yüküyle, beraber büyüyoruz. Ne ağaç kalıyor yakmadık, ne korkutmadık balıkçı.. Gözüm g...', ARRAY['Türk Edebiyatı','Şiir','Özkan Özdoğan']::text[], 8.5, '{"poet":"Özkan Özdoğan","poet_slug":"ozkan-ozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/firtina-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-hasan-sakman-lo53n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kar yağıyor dışarıda

sanki küçük melekler gibi.

Toprak da biraz kızgın tabi,

dönüşüyor rengi beyaza,

kısaca kar hükmettiriyor rengini

konduğu toprağa.

Dalmışım bu güzelliğe

farkında değilim geçen zamanın

bir an olsun unutuyorum seni,

gözlerimi kar bürüyor

ve kar toprakta büyüyor.', 'Kar yağıyor dışarıda sanki küçük melekler gibi. Toprak da biraz kızgın tabi, dönüşüyor rengi beyaza, kısaca kar hükmettiriyor rengini konduğ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kar-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-aydanur-basci-dgty6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dışarıda yağmur yağıyor

Yine hüzün saçıyor

Öte yandan gök gürültüsü

Bu kadarı da fazla

Kaldıramam ben bu yükü

Ne yapsam ne etsem de 

İçimdeki korkuyu terk etsem

Aslında bana koyan

Yağan yağmur değil

Gök gürültüsü de değil

Sensizlik

Sensizliğin özlemi ve 

İçimdeki yalnızlık duygusu

Evet evet korkuyorum

Yalnızlıktan, sensizlikten

Ve bu karanlıktan

Herşeyden korkuyorum

Hayattan, insanlardan

Aldanmaktan, aldatmaktan

Seni benden alan

Sessiz ve sinsice

Bu karanlıktan korkuyorum

2003', 'Dışarıda yağmur yağıyor Yine hüzün saçıyor Öte yandan gök gürültüsü Bu kadarı da fazla Kaldıramam ben bu yükü Ne yapsam ne etsem de  İçimdek...', ARRAY['Türk Edebiyatı','Şiir','Aydanur Başcı']::text[], 8.5, '{"poet":"Aydanur Başcı","poet_slug":"aydanur-basci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/korkuyorum-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkum', 'korkum-aydanur-basci-9rve1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bulutlar gökyüzünde yerini almış

Yağmur yağacakmış gibi

Hava ise hafiften kızarmış

Akşam olacakmış gibi

İçimi bir korku sarmış

Yüreğim daralıyor sanki

Bir taraftan rüzgar esiyor

Bu nasıl rüzgar, aklım almıyor

Yıldızlar gökyüzünde dizi dizi

Ben yıldızlara, yıldızlar bana bakıyor

Çünkü gecenin o derin karanlığında 

O daracık sokaklarda, yalnız kaldırımlarda

Sadece gecelerin arkadaşı, 

Sırdaşı ben varım

Ne ben gecesiz, ne de 

Gece bensiz yapabilir

Çünkü ikimizde yalnızız

Belki birgün ben öleceğim

Toprak olup gideceğim

O zaman; 

Ebediyyen geceler benim olacak.

2001', 'Bulutlar gökyüzünde yerini almış Yağmur yağacakmış gibi Hava ise hafiften kızarmış Akşam olacakmış gibi İçimi bir korku sarmış Yüreğim daral...', ARRAY['Türk Edebiyatı','Şiir','Aydanur Başcı']::text[], 8.5, '{"poet":"Aydanur Başcı","poet_slug":"aydanur-basci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/korkum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderime Razıyım', 'kaderime-raziyim-metin-usengec-0pa5s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek kolay kazanılan bir duygu

Düşer bir an sahipsiz yüreğe

Bin çaba etsen bırakmaz yakanı

Taaki bulana kadar kara toprağı

Bir hayat ki sanki anlamsız sensiz

Emanet ki bu can,borcum olsun Allah''a

Ne zaman ki seni unutabilirim

O zamanki güneş doğsun

Karşılıklı seven kalplere dolsun

Ne akıl isterim ne derdime derman

Kimseden dilemem aman

Kendim sevdim kendim çekerim

Tek başıma sevdiysem

Kaderime razıyım nereye sürerse giderim..

22-Haziran-2004  02:30

Alın Yazım Kaderimsin Sana Tutkun Kalacağım..', 'Sevmek kolay kazanılan bir duygu Düşer bir an sahipsiz yüreğe Bin çaba etsen bırakmaz yakanı Taaki bulana kadar kara toprağı Bir hayat ki sa...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaderime-raziyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakışmıyor İnsanlara', 'yakismiyor-i-nsanlara-hasan-sakman-xle4c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm...

Adını duymak bile yakıyor yüreğimi.

Kaybettiğimi düşünüyorum da 

sevdiklerimi,

nefes almak gelmiyor içimden.

Durdurup kalbini sonsuz bir boşluğa,

adını bilmediğimiz bir hiçliğe

bırakarak ardında ağlayanları

yakışmıyor insanlara.

(13 Temmuz 2001)', 'Ölüm... Adını duymak bile yakıyor yüreğimi. Kaybettiğimi düşünüyorum da  sevdiklerimi, nefes almak gelmiyor içimden. Durdurup kalbini sonsuz...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yakismiyor-insanlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir Ve Ben', 'i-zmir-ve-ben-ufuk-nazim-k0zqk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İzmir ve ben

Gevrek yerdik

Susam susam kokup

Nar çiçeklerine

Takardık gülüşlerimizi.

İzmir ve ben

Bornova dan çıkıp yola

Bayraklıda kapayıp pencerelerimizi

Geçerdik kemer altının

Büyülü sokaklarından.

İzmir ve ben

İncir altında

Denize karşı

Aşklarımızı meze yapıp

İçerdik rakımızı.

İzmir ve ben

Konak meydanında

Haykırırdık umutlarımızı

Dalgalar bize hayrandı

Bir o kadar uzakken sevdamız.', 'İzmir ve ben Gevrek yerdik Susam susam kokup Nar çiçeklerine Takardık gülüşlerimizi. İzmir ve ben Bornova dan çıkıp yola Bayraklıda kapayıp ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/izmir-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulan Bir Düş', 'unutulan-bir-dus-ufuk-nazim-npo8z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah oldu

Unutulan 

Bir düş gibi geçmişim

Hep yeni ufuklara açılan

Sonsuzca bir sevgi seliyle

Doğan güneş imparatorluğu.

Perdemin bir el darbesiyle

Açılışıyla doğacak.

Karanlığın hezeyanlarından

Işık ışık sıyrılmak.

Korku molozlarının 

Arasına sıkışan

Düşün kısırlığından

Günün ilk ışığıyla 

Kurtulmak.

Ey güneş

Bereketin sonsuzca olsun

Işığınla 

Yeniden yeniden erisin

Donmuş yürekler.

Ey güneş

Sen ki en kutsal anasın

Seni bekleyenleri utandırma

Dakikliğini bozmasın

Hayin bulutlar.', 'Sabah oldu Unutulan  Bir düş gibi geçmişim Hep yeni ufuklara açılan Sonsuzca bir sevgi seliyle Doğan güneş imparatorluğu. Perdemin bir el da...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/unutulan-bir-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet Dalgalara', 'emanet-dalgalara-ufuk-nazim-23gg4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sefil bir omurgasızlık

Dik yürüyen yok sayılır.

Güneşin onurlu çocukları 

Sürüngen organizmalara

Nasıl dönüştü.

Ellerinde çelikden ikonalar

Düşlerinde

Korkak ikircikli rüzgarların

En ufak esintisinde 

Savrulan çelişkiler.

Susmak lazım

Onları görünce sessizce

Kaçmak lazım

En uzak köşelere.

Dünyadan habersiz

Yalan yanlış oyunlarda

Sessizce yaşamak.

Gözlerden uzak bir

Sıradanlık içinde

Kendine varmak.

Geçmek en ötelerine

Denizlerde fersah fersah 

Yol kat etmek

Sınırsız bir düzlük de

Eylemsiz 

Ve emanet dalgalara

Gidişin..', 'Sefil bir omurgasızlık Dik yürüyen yok sayılır. Güneşin onurlu çocukları  Sürüngen organizmalara Nasıl dönüştü. Ellerinde çelikden ikonalar ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/emanet-dalgalara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An''ımda Ben''imde Hayali Sevdam....', 'an-imda-ben-imde-hayali-sevdam-tulay-eker-xo8st', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayal miydin 

Kaktüs yaprağına konan 

Çiçeğinin ardıçıyla toprağımı saran 

Isırgan otu muydun yoksa 

Yangısı bağrıma saplanan 

Ve çoğum çoğum 

Çoğaldıkça sende 

Vuruldukça her anışımda 

Beni bana unutturan? 

Erguvanlarım 

Yedi verenlerim 

Yasemenlerim 

Gidişlerim 

Sevişlerim 

Yönelirken ölmelerim 

Oyy yar yar... 

Sana vurulmayı sevdim! 

Utanmadı isyanlarımdan çilekeş sevdam 

An''ımda taptım 

Ben''imde yaktım 

Sen''inle çoğaldım 

Yar...hep sevdim.

___ Koynumda yastığım 

Gizlice sarılıp hayallerine sığındığım 

Sımsıkı sinesinde sabahladığım 

Gecelerden karaları çalıp 

Aklımı tırlattığım 

Gözlerimi sıcaklığınla açtığım 

Öpücüklerini kuşun ağzında yakaladığım 

Açılmış gözlerim 

Sabahlamaktayım 

Vurulmuş aşım 

Açlığına gebeyim 

Doğum sancısı sensizliğim 

Bilirim.... 

Ne sen doğacaksın 

Ne de ümitlerim 

Heybemi asar giderim 

Bil ki vurmuşum şavkından 

Bil ki unutmuşum benliğimi 

Sana vermişim ben''imi 

Alıp giderim yaşımı 

Asarım boynuma 

Çekerim ipimi! 

Unuttum sormayı 

Sahi 

Sen ben oldun mu? 

Tecritte titredin mi 

Tuz bastınmı tuz 

Kanayan yaralarına 

Ben yanarken 

İt gibi titrerken 

Üşürken.. 

Bana iki damla yaş yollar mısın 

Sol yanından..... 

Öpüp koynuma koyacağım 

Sarılıp yok olacağım.', 'Hayal miydin  Kaktüs yaprağına konan  Çiçeğinin ardıçıyla toprağımı saran  Isırgan otu muydun yoksa  Yangısı bağrıma saplanan  Ve çoğum çoğu...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/an-imda-ben-imde-hayali-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönülden Bağlanmışız', 'gonulden-baglanmisiz-cafer-tayyar-ozkan-dm7bg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biz bir kere gönülden b a ğ l a n m ı ş ı z,

Yağlı kendir de g e ç s e, serden geçilmez,

Gözde yaş olsa da, s e r d e erkeklik var,

Bir k e r e sevdik mi, s o n nefeste veririz,

Sesini beynime aldım, duyulmaz ki Sevgilim...

Yüreğine asla hüzün i n m e s i n dileğim,

Sevgimden bir an bile ş ü p h e n olmasın,

Yalnız a n l a r ı n hep düşlerimle s a r s ı n,

Bir k e r e gördük mü, s o n a kadar gideriz

Adını yüreğime yazdım, silinmez ki Sevgilim...

U z a t t ı ğ ı n elinden her a c ı y a gelirim,

Tatlı d i l i n d e n gelen her ş e y i bilirim,

Y a l n ı z bir şeye g e l e m e m ışıl gözlüm,

Bir k e r e bittik mi o anda biz de b i t e r i z,

Canını canıma kattım, görünmez ki Sevgilim...

Elbette her z a m a n bal şerbeti içmeyeceğiz,

Zaman gelecek dertleşip, acıyla ağlayacağız,

Birbirimize ne dersek diyelim, kırılmayacağız,

Sevgiyle acı tatlı bu uzun yola baş koyacağız

İçime aldığım nefesin, çıkmaz ki S e v g i l i m...

11 Ekim 2002 Ankara.', 'Biz bir kere gönülden b a ğ l a n m ı ş ı z, Yağlı kendir de g e ç s e, serden geçilmez, Gözde yaş olsa da, s e r d e erkeklik var, Bir k e ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gonulden-baglanmisiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-ali-osman-donmez-szr4x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'benliğimi esir etmiş rıhtımına 

saniyelerle bordamı dövüyor zaman

hüzün; gönlümde solmayan çiçek...

ömür; menziller arası yolculuk...

aşinası olduğum kıyılardan 

‘rıhlet’ deyip kalbimi kovuyor zaman

saniyelerle bordamı dövüyor zaman

mazimde ateş, âtimde duman

‘an’la akrep olup ruhumu sokuyor zaman

yaprak dökümü: hicret...

gurup vakti: göç...

gizli bir dil gibi

hep aynı hitabeyi okuyor zaman

bir bilinmezlik tezgahında

nakış nakış ömrümü dokuyor zaman

peşimde gezen gölge, kulaklarımda çınlayan ses

aynalarda  ‘dur’ çekip boğazımı sıkıyor zaman

iman; korkularıma liman...

uyku; beyhûde bir kaçış...

gizli kapılar bulup rüyalarıma

anahtar deliğinden bakıyor zaman

köprüsüz hayat ırmağında

ecel olup akıyor zaman

ecel olup akıyor zaman

(Adına Islanıyor Saçlarım''dan)', 'benliğimi esir etmiş rıhtımına  saniyelerle bordamı dövüyor zaman hüzün; gönlümde solmayan çiçek... ömür; menziller arası yolculuk... aşinas...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Dönmez']::text[], 8.5, '{"poet":"Ali Osman Dönmez","poet_slug":"ali-osman-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zaman-130-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı AŞK', 'adi-ask-fatih-taskin-zh72d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gül koklarken aldığın kokudur 

Kokunun içindeki ruhtur,adı aşk 

Elini tuttuğun zaman atar yürek 

Yürağin çarptıkça titremektir adı aşk 

Heyecandan uyuyamazsın gece uykular 

Uykuda onun hayalini görmektir adı aşk 

Tuhaf olursun duyunca telefonda sesini 

Sesinden etkilenip bağlanmaktır adı aşk 

Tek korkum kalmaktır senden uzak 

Uzakken yakın,yakınken uzak olmaktır adı aşk 

Ezan okununca hissettiğin manadandır 

Manadan aldığın feyz dir adı aşk 

Mevlananın semahındaki sırdır 

Sırdakini gerçeğe aktarmaktır adı aşk 

Fethederken Fatih İstanbulu sığınmıştır Allaha 

Allah resuluna iman etmektir adı aşk 

Ferhat''ı,Kerem''i,Mecnun eder Yunus''u 

Yunus''un dergahındaki duygudur adı aşk 

Siyah Bereli ister birgün sevdiğine kavuşmak 

Kavuşmanın verdiği umuttur,adı aşk 

                                                   SİYAH BERELİ', 'Gül koklarken aldığın kokudur  Kokunun içindeki ruhtur,adı aşk  Elini tuttuğun zaman atar yürek  Yürağin çarptıkça titremektir adı aşk  Heye...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/adi-ask-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Canikom 1*', 'canikom-1-kubilay-enginol-o7jao', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir nur gibi düştün gönlüme

Alevler yayıldı bir anda içime

Sarmaşık gibi sarıp sarmaladı sevgin

Ne güzel,düşünüyor seni hep sevdiğin

Heyecanlandırıyor,güzel sözlerinin her kelimesi

Olurmusun sen kubilay ''ın kerimesi

Alsın bundan sonra seninle her nefesi

Dağları deler geçer sana sevgisi

Bu gönül hep seni sevecek

Bu aşk emin ol mahşere kadar sürecek

Artık mangal gibi yürek bulundu

Yakaladı bu kul mutluluğu

Bu şiir Diasphora''ya ithaf edilmiştir', 'Bir nur gibi düştün gönlüme Alevler yayıldı bir anda içime Sarmaşık gibi sarıp sarmaladı sevgin Ne güzel,düşünüyor seni hep sevdiğin Heyecan...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/canikom-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ne Acılar Gördüm', 'ben-ne-acilar-gordum-murat-demir-wwgcw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben ne acılar gördüm

Ne sevdalar tanıdım

Yapılmadan, yıkılmaya hazır

Eğreti niteliğinde

Bilir misin? 

Dağılıp yok olmak için

Bir esimlik yel bekleyen

Bulutlar gibi,

Ne aşklara, aşıklara 

Şahit oldum yok olurken,

Güneşin batışını görüp

Doğuşunu göremeden

Döşek ayazında

Tek kurşunla vurulan,

Değil sevda suyunda

Kan deryasında boğulan

Ben ne acılar gördüm

Bilirmisin?', 'Ben ne acılar gördüm Ne sevdalar tanıdım Yapılmadan, yıkılmaya hazır Eğreti niteliğinde Bilir misin?  Dağılıp yok olmak için Bir esimlik yel...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-ne-acilar-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Değerli Dost', 'en-degerli-dost-i-smail-baharsen-837c5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'en değerli dostumdun

gecenin ıssız saatlerinde var olan

içimdeki yalnızlık zincirini kıran

gönlümde benimle sabahlayan

derdimi istediğim gibi soran

sen dünyada var olmayandın

en değerli dostumdun

hayat denen hüzün bahçesinde

sevgiyle şefkatle açan güldün

mutluluk rüyalarında çıktın karşıma

bu uzun yolun en çıkmazında

sen dünyadan uzak yabancıydın

en değerli dostumdun

yıllardır doğum günümü kutlayan

mevsimlerce ömrüme çiçekce kokan

baştan başa gerçek, yalan olmayan

bir dostluk yaşattınki unutulmayan

sen dünyada doğmayandın

en değerli dostumdun

kadeh gibi şiir gibi mahsun

bir pınar suyu gibi saftın

bıkmadan gönlüme hep aktın

doyurdun beni sevgiye sevilmeye

sen dünyada bulunmayandın.....', 'en değerli dostumdun gecenin ıssız saatlerinde var olan içimdeki yalnızlık zincirini kıran gönlümde benimle sabahlayan derdimi istediğim gib...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/en-degerli-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçtim Kendimden', 'gectim-kendimden-i-smail-baharsen-v39zh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir aşk için yanarmı insan

yaktım gönlümü en derinden

hiçe saydım hayatı yıllarımı

bir aşk için geçtim kendimden

gözüme gelmedi dağlayan korlar

önüme gelmedi ağlayan anlar

canıma kıydı zalim yalanlar

bir tutku için geçtim kendimden

sahteymiş can alan o güzel gözler

yalandan bakmış o siyah gözler

bilmezdim ağlarmış tüm sevenler

bir oyun için geçtim kendimden

ahiret sorgusunu gördüm dünyada

sanma mutluluk sürdüm dünyada

ömrümde kaldı  çoktan yarıda

bir kumar için geçtim kendimden', 'bir aşk için yanarmı insan yaktım gönlümü en derinden hiçe saydım hayatı yıllarımı bir aşk için geçtim kendimden gözüme gelmedi dağlayan kor...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gectim-kendimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidipte Gelme', 'gidipte-gelme-i-smail-baharsen-wndoh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'son söz senin dilinden çıktı

gidiyorum elveda diye

bir kısa cümle dünyamı yıktı

unutma şu anı gidipte gelme

bitmiş olur sonsuz sabrım

yıkılmıştır artık saltanatın

hani boynu bükük bıraktığın

unutma şu anı gidipte gelme

önümde yırttın mektuplarımı

yüzüme çarptın yaptıklarımı

görür gibiyim pişmanlığını

unutma şu anı gidipte gelme

yıllar gönlüne vurdukça zıpkın

vicdanını eritir ateş azabın

tez olmaz gurbette sabahın

unutma şu anı gidipte gelme', 'son söz senin dilinden çıktı gidiyorum elveda diye bir kısa cümle dünyamı yıktı unutma şu anı gidipte gelme bitmiş olur sonsuz sabrım yıkılm...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gidipte-gelme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Anda İnsan', 'o-anda-i-nsan-abdulbaki-temiz-fwzt7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir an geliyor 

Aşkı yaşamak istiyor insan

Fakat içinde bulunduğu an,

Karşına onu çıkarmıyor

Bir an geliyor 

Sokağa çıkmak istiyor insan

Dışarıdaki insanların yüzlerindeki tebessümü görebilmek için

Fakat içinde bulunduğu an,

Ona dışarıda sevgi kalmadı diye fısıldıyor kapı aralığından

Bir an geliyor 

Lise yıllarına  geri dönmek istiyor insan

Fakat içinde bulunduğu an,

Onu o yıllara götüremiyor

Bir an geliyor

Boşlukta düşüyor insan

Fakat içinde bulunduğu an,

Elini uzatacak birisini çıkarmıyor karşısına

Bir an geliyor 

Sadece iyilerin olduğu bir yerde yaşamak istiyor insan

İşte o anı gerçek oluyor

Çünkü bir uçağın bombaları altında kalıyor insan...', 'Bir an geliyor  Aşkı yaşamak istiyor insan Fakat içinde bulunduğu an, Karşına onu çıkarmıyor Bir an geliyor  Sokağa çıkmak istiyor insan Dış...', ARRAY['Türk Edebiyatı','Şiir','Abdulbaki Temiz']::text[], 8.5, '{"poet":"Abdulbaki Temiz","poet_slug":"abdulbaki-temiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/o-anda-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemem', 'bilemem-husamettin-gunacti-47xbz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'insanlar,

neden kendilerine 

fısıldamaktan

korktukları şeyleri

dünyaya

haykırmak isterler

bilemem...', 'insanlar, neden kendilerine  fısıldamaktan korktukları şeyleri dünyaya haykırmak isterler bilemem......', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bilemem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Şeymi İstedim Dünyadan', 'cok-seymi-i-stedim-dunyadan-i-smail-baharsen-6i8b8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir sevgili bir temiz aşk

çok şeymi istedim dünyadan

mutlu bir hayat bir sıcak aş

çok şeymi istedim dünyadan

yıllardır mahkumum zindanlara

ermedim sonsuz gerçek aşka

kederden başka ne verdi bana

çok şeymi istedim dünyadan

yine çok sevdim yine yandım

gün gelirde gülerim sandım

çevremdeki bühtana kandım

çok şeymi istedim dünyadan

hayal kurmakla bitti hayatım

dipsiz bir kuyuya battıkça battım

dünyada kaldı benim ahlarım

çok şeymi istedim dünyadan', 'bir sevgili bir temiz aşk çok şeymi istedim dünyadan mutlu bir hayat bir sıcak aş çok şeymi istedim dünyadan yıllardır mahkumum zindanlara e...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cok-seymi-istedim-dunyadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşı, Toprağı, Altın Şehrin Kurbanları', 'tasi-topragi-altin-sehrin-kurbanlari-i-smail-baharsen-nof9j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hayat bazen bir girdaptır

labirent gibi, kaybolur insan

çıkmak istedikçe batar en dibe

ve yegane bir öyküdür var olmak

ve İstanbul hayatın ta kendisi

hayatın ikinci zor dersi 

birisi doğmak birisi yaşamak

mahşer İstanbul''da

kendini ismini kurtarmak

sevdiklerini bulmak enkazlar içinde

haliç bir başka zemberek taksim bir başka

insanlık başka burda yoksulluk başka

taşı toprağı altın İstanbul,

neden altının geçmiyor bu pazarda

neden bir şey alınmıyor neden

herkesin soracağı o kadar çok şey varki 

hangisine cevap vereceksin İstanbul 

biliyorum sende günahsızsın 

sende dünyanın bu devranın bir parçasısın

sözüm yok sana İstanbul yok

seni katil seni zalim yapanlar utansın....', 'hayat bazen bir girdaptır labirent gibi, kaybolur insan çıkmak istedikçe batar en dibe ve yegane bir öyküdür var olmak ve İstanbul hayatın t...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tasi-topragi-altin-sehrin-kurbanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahtan akşama', 'sabahtan-aksama-i-smail-hakki-kavurmaci-84kgt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'her sabah 

kar çiçeği tazeliğinde 

umutlarla 

çiçekten çiçeğe uçan kelebek 

coşkusunda bir yürekle 

ve dupduru gökyüzü berraklığında 

dinç bir beyinle 

çıkarım sıcacık yuvamdan 

açılırım yeryüzüne 

.... 

ve akşam 

kararmış bir yürek 

bulanmış bir beyin 

ve kirlenmiş ellerimle 

dönerim tertemiz 

sımsıcakcık yuvama.. 

ismail hakkı kavurmacı 

coşkularım', 'her sabah  kar çiçeği tazeliğinde  umutlarla  çiçekten çiçeğe uçan kelebek  coşkusunda bir yürekle  ve dupduru gökyüzü berraklığında  dinç b...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı Kavurmacı']::text[], 8.5, '{"poet":"İsmail Hakkı Kavurmacı","poet_slug":"i-smail-hakki-kavurmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sabahtan-aksama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bibi', 'bibi-husamettin-gunacti-umeph', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'mahallemizde bir özürlü var.

adı Bibi,doğuştan özürlü.

gerçek adını bilmez kimse.

Bibi ve baba''dan başka

birşey söylemez nedense.

üstü başı her zaman temiz,

eski ama tertemiz.

salyalı ağzı,dökük saçları,

dizlerine kadar sıvadığı paçaları,

gülen yüzü ve sevecen tavrı

onun portresini çizmeye yeter.

mahallenin sevimli maskotudur,

yaşlı babasıyla oturur.

zararsızdır,

çocuklarla oynar çokça.

alaylara,itilip kakılmaya

dayanıklıdır oldukça.

gözleriyle anlatır,

diliyle söyleyemediklerini.

anlayana

insanlık dersi verir sıkça.

ömür çocuk şu bizim Bibi,

sanki dünyayı umursamaz gibi.

sen hep böyle kal Bibi,

çıksa da dünyanın dibi...

--------

--------

inanın hep böyle kaldı.

dünyanın dibi çıkana kadar olmasa da,

ona bir araba çarpana kadar.', 'mahallemizde bir özürlü var. adı Bibi,doğuştan özürlü. gerçek adını bilmez kimse. Bibi ve baba''dan başka birşey söylemez nedense. üstü başı ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Hayallerimizle Mutluyuz', 'biz-hayallerimizle-mutluyuz-orhan-turhan-ll0vw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Durun, ne olur durun! 

Kıymayın birbirinize! 

Siz demiyor muydunuz bu dünya kimseye kalmaz diye? 

Neden bu kin,  bu nefret neden? 

Bakın arka bahçenizi ne hale getirdiniz? 

Bizlere gelecek diye mi layık gördünüz? 

İstemiyoruz, sizin olsun dünyanız

Biz hayallerimizle mutluyuz.

Kaldırın kafanızı  bakın  ağlayan bulutlara

Gözlerinden dökülen asit yağmurları;  bereket değil

Kulakları tıkayıp beyinleri kemiren  bu sesler

Coşkuyla cıvıldaşan kuşların değil.

İstemiyoruz, sizin olsun dünyanız

Biz hayallerimizle mutluyuz.

Aynalara küsmeyin, yüzleşin kendinizle

Yüreklere ektiğiniz nefret tohumudur; sevgi değil.

Bölüştüğünüz komşu hakkıdır bencilce duygularla

Bir dilim ekmek  değil.

İstemiyoruz, sizin olsun dünyanız

Biz hayallerimizle mutluyuz.

Çıkarın at gözlüklerinizi, yüreğinizle görün

Tek kaygınız zengin olmak; adam  değil.

Yükselmek için üzerine çıktığınız insandır,

Merdiven değil.

İstemiyoruz,sizin olsun dünyanız

Biz hayallerimizle mutluyuz.

Sürdürmek varken yaşamınızı insan olmak adına 

Tüm gücünüzü verip canları okuyorsunuz; kitap değil.

Acımasızca kırdığınız ademoğludur, çıkar uğruna

Rekor değil.

İstemiyoruz,sizin olsun dünyanız

Verin çocukluğumuzu bize! 

Biz hayallerimizle mutluyuz.', 'Durun, ne olur durun!  Kıymayın birbirinize!  Siz demiyor muydunuz bu dünya kimseye kalmaz diye?  Neden bu kin,  bu nefret neden?  Bakın ark...', ARRAY['Türk Edebiyatı','Şiir','Orhan Turhan']::text[], 8.5, '{"poet":"Orhan Turhan","poet_slug":"orhan-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/biz-hayallerimizle-mutluyuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçmalığa Övgüler-04', 'sacmaliga-ovguler-04-oguzkan-bolukbasi-pprj0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'heyecan taşıyan gemiler

yüklerini birer birer

limanlarıma terkettiler

ne varki gözlerin

ah o gözlerin

sonra ufuklardan korsanlar sökün sökün

heyecanımı talan ettiler

ne varki gözlerin

ah o gözlerin

rüzgarların sığındığı bir koydayım şimdi

fırtınaların üzerindeyim

belkide yeniden açılacağım denize

rahvan kanatlı bir atın sırtında uçarak

süzüle süzüle

heyecan taşıyan gemilerin güvertesine

ineceğim

ne varki gözlerin

ah o gözlerin

patlamış mısır gibi bakan

şaşkın

aralıklarından hayatın

bakmasın

heyecan taşıyan gemiler

uzak çok uzak limanlarda şimdi

senin gözlerin

benim beklediğimdi', 'heyecan taşıyan gemiler yüklerini birer birer limanlarıma terkettiler ne varki gözlerin ah o gözlerin sonra ufuklardan korsanlar sökün sökün...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sacmaliga-ovguler-04-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir hüzün bulutu', 'bir-huzun-bulutu-fetih-sait-akkaya-sasmd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir hüzün bulutu kapladı içimi 

sana o sözleri söyledikten sonra

defalarca sordum kendime

neden dedim kendime

neden böyle yaptım

beni sevmediğini deüşündüm önce

ve terk edeceğinden korktum

çünkün kalbimin yarısını sana emanet etmiştim

diğer bir yarısınıda tanrı''ya

sonunda anladım

ve şimdi kendime çok kızdım

çünkü hayat sendin

sende benim hayatımdın

bir gurur uğruna bu aşkı yıkmak

sencede yanlış olmazmı

benim hala aşka cesaretim var

seninde var mı? 

                                      okan aysu kardeşim', 'bir hüzün bulutu kapladı içimi  sana o sözleri söyledikten sonra defalarca sordum kendime neden dedim kendime neden böyle yaptım beni sevmed...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-huzun-bulutu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarınla dön artık', 'ruzgarinla-don-artik-fetih-sait-akkaya-kfj3x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir bahar akşamıydı gidişin

belkide kalbime en ağır yükü yükledin

ne kadar yalvarsam boşaydı 

dönerim demiştim bir gün 

o günü her gün bekledim

kim bilir kaçıncı sigara dudaklarımda 

seni düşünüyorum artık umutsuzca 

gözlerimde uyku yerine sen vardın geceleri; 

uyuyamıyorum artık

uyu diyorlar rüzgarlar artık uyu

gözlerimi kapatırsam ecel beni bulacak biliyorum

yapamıyorum be güzelim olmuyor

sevdalı bulutlarla yürüyor artık dostluğum

hala anımsıyorum o günleri...

ve o günlere dair eminim ki..! 

eskiden daha inatçı ve azimli olduğumuza

dön artık yürek sözlüm

benim bıraktığım yerde

seninse başalayacağın 

yerde bekliyor aşk.

gelmezsen gözlerim kapanıyor yağmur kokulum

duymadınmı bak dinle

rüzgar sana fısıldıyor 

                            SENİ SEVİYORUM', 'bir bahar akşamıydı gidişin belkide kalbime en ağır yükü yükledin ne kadar yalvarsam boşaydı  dönerim demiştim bir gün  o günü her gün bekle...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ruzgarinla-don-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var yok', 'var-yok-fetih-sait-akkaya-wvgq8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kaç gündür gökzlerim gözlerini arıyor

yokluğunda..

sensiz...

sensiz geçirdiğim her saniye bana haram 

bana ızdırap 

bana çile...

her baktığım yerde

gözlerin; 

bakmaya doyamadığım

gözlerin...

sabahlar akşamları kovalar oldu

nerdeyim..

hangi alemdeyim 

yokluğunda..

sensiz..

gözlerim artık gözlerini arıyor

sensiz gweçirdiğim her saniyenin diyeti

beni derberder 

beni çilekeş ediyor 

yokluğunda...

sensiz...

                         

                                                        (((karam)))', 'kaç gündür gökzlerim gözlerini arıyor yokluğunda.. sensiz... sensiz geçirdiğim her saniye bana haram  bana ızdırap  bana çile... her baktığı...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/var-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fantazi', 'fantazi-sadik-softa-zctyf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıldızları seninle, toplayıp harmanlasak,

Yıldız yağmurlarında saçlarını yıkasak.

Seni sükun içinde, bir güzel hazırlasak,

Gelinliğini seçsek bulut beyazlığından,

Kurtarsak ikimizi gönül yalnızlığından.

Akdeniz’den uzansak,Ege’nin mavisine,

Bulutları yüklesek,  dalgaların sesine,

Yıldızlardan ışıltı,o masum gözlerine,

Gelinliğini seçsek bulut beyazlığından,

Kurtarsak ikimizi gönül yalnızlığından.

Yıldızları süsleyip takarak neşesine,

Yüklesek sesimizi rüzgarın ensesine,

Göndersek sevgimizi sevdanın gölgesine,

Gelinliğini seçsek bulut beyazlığından,

Kurtarsak ikimizi gönül yalnızlığından.

Hamağımızı kursak,yıldızlara gümüşten,

Saçlarını süslesek, pırıltısı güneşten,

Sonra duygularımız seriliverse içten,

Gelinliğini seçsek bulut beyazlığından,

Kurtarsak ikimizi gönül yalnızlığından.

Bukle bukle dolasak,saçının kavisinden,

Gelinliğini seçsek sevginin safisinden,

Eklesek üzerine gökyüzü mavisinden.

Gelinliğini seçsek bulut beyazlığından,

Kurtarsak ikimizi gönül yalnızlığından.

Çankırı-20.06.2004', 'Yıldızları seninle, toplayıp harmanlasak, Yıldız yağmurlarında saçlarını yıkasak. Seni sükun içinde, bir güzel hazırlasak, Gelinliğini seçse...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/fantazi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşlar', 'taslar-caglar-akarsu-69329', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '..

Binlerce taş.

eski Arnavut kaldırımları...

renk-renk taşlar.

Ya da kızıl ay da ki,kaldırımlar

irili ufaklı.

Gece yürürken.

karanlıkta.

Farkına varmazsınız.

Bir tanesi eksik olunca.

tökezlenir ve düşersiniz.

Yerçekimini hissedersiniz.

Canınız acır.

İlk darbe de dizleriniz.

Yara ve bere içinde kalır.

İçiniz de bir sızı hissedersiniz

Hafifçe akmış, kanla karışık

Bir morluk kalır geriye,

Yinede,

Duramazsınız.

Yürürsünüz.

içiniz de. buruk bir mahcupluk kalır

Sağa ve sola.

Bakarsınız.

Bir gören var mı? 

diye.

Ah! ! bu kaldırımlar.

Ah '''' bu taşlar.

Bir gerçek varsa

 Benim içimde.

...

 24/haz', '.. Binlerce taş. eski Arnavut kaldırımları... renk-renk taşlar. Ya da kızıl ay da ki,kaldırımlar irili ufaklı. Gece yürürken. karanlıkta. Fa...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/taslar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neron', 'neron-hasan-dogan-81m44', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neron ateşleriyle yanarken gönül kentim,

Bir su serabı görmeyi bile beceremedim.

Günah denizinde pusulamı kaybettiğimden beri,

Her aldanışımın bedelini ödemekle geçti günlerim.', 'Neron ateşleriyle yanarken gönül kentim, Bir su serabı görmeyi bile beceremedim. Günah denizinde pusulamı kaybettiğimden beri, Her aldanışım...', ARRAY['Türk Edebiyatı','Şiir','Hasan Doğan']::text[], 8.5, '{"poet":"Hasan Doğan","poet_slug":"hasan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/neron-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezom', 'ezom-mehmet-koyuncu-i2yt9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ezom! 

Elma suyuna bandırılmış sevdamın

Yitik gelini…

Hayatının sen ertesiyle meşgul 

Sen evveli yaşanmamış sayan

Bir ucubeden dinle kendini

Eşsiz bir Leyla’sın içimde

Ki Leyla görünce bendeki seni

Aynalara küsecekti hayatı boyunca

Karanlıkları seçecekti

 insan içine çıkmaya…

Bakışlarını 

Havva’da görünce şeytan,

Önünde dururdu

Yemesin diye yasak meyvadan…

Ezom! 

Bir parçası güzelliğinden

Züleyha’ya verilseydi

Züleyhaaa! 

Diye haykırışlar duyulurdu

Kuyunun dibinden

Kendimi harab etmem boşunadır 

Güzelliğini tarif etmek uğruna

Kelimeler dilsiz

Mısralar topal

Şiirse kanadı kırık kuştur

Cemalinin diyarında…

Ezom! 

Görmemeliydim 

Geceye nazire yazan gözlerini

Bakışların Ferhad’a inat 

Delmek ister yüreğimi

O bakışların Ferhad’a verilseydi

Un ufak ederdi dağları 

Tersine akıtırdı Fırat’ı ve Dicle’yi

Davut’dan edinmiştir kalbin zırhını 

İstanbullar

 kapılarını açmış dururken

Ben sevda donanmalarını yürüttüm kalbimde

Fethedebilmek için gönlünü

 Sevda ülkesinden.

Yeni açmış gülün iniltileri duyulur

Yalnızlığın boşluğunda! 

Yokluğun paslı hançerdir vücudumda

Bana düşen harcı ızdıraptan beton duvarlar

Sevdaların paylaşıldığı aşk diyarında

Ezom! 

Demir atmış yüreğime

Hasret yüklü gemiler,

Kök salmış bedenime 

Dermansız dertler..

Yağmura hasret çatlamış toprak

İmrenir

Aşkına susamış dudaklarıma

Sonbaharda solmuş yapraklar

Şükreder görünce

sensiz solgun bedenimi

Ezom! 

Küçümseme sevdamı

Kays Sevdamın şerbetinden içseydi 

Ayaklarıma kapanırdı

Öğrenebilmek için mecnunluğu

Çöller değil kainat dar gelirdi.

Rüyalarıma gelmeyişine ağlarım 

yıllardır

Yakubi hıçkırıklara

yabancı değil mekanım

Kördür senden başkasına bu gözler

Esvabının kokusudur dermanım,

Çaresizliğe gün ekledim

Yokluğun her saniyesinde

Ömrümden ömür yitirdim

Sensizliğin gecelerinde

Eyyub’un illetine ortak vücudum

Sensizliğe doğan güneş

Karanlık sabahlarımın habercisi

Ezom! 

Kurumuş pınarlardan

Lal bülbüllerden umma yaranlık

Coşkun çağlayanlar bekle

Aşkınana kabarmış yürekten

Sevdalı nağmeler bekle eşsiz güzelliğine

Ciğeri paramparça aşık bülbülden…', 'Ezom!  Elma suyuna bandırılmış sevdamın Yitik gelini… Hayatının sen ertesiyle meşgul  Sen evveli yaşanmamış sayan Bir ucubeden dinle kendini...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Koyuncu']::text[], 8.5, '{"poet":"Mehmet Koyuncu","poet_slug":"mehmet-koyuncu","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/ezom-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni unutmayacağım', 'seni-unutmayacagim-mehmet-koyuncu-eji26', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni unutmayacağım

Bu ruh ölene,

Gözlerimin feri sönene kadar,

Duruncaya kadar kalbimin her atışıyla,

Hasta ciğerlerime nefes nefes çektiğim

Sigaramın dumanıyla,

Süzülen her gözyaşımla

Sanma,

Severek hatırlayacağım.

Yıkılan dünyamın

Biten umutlarımın faili olarak

Nefretimin her zerresini hissederek

Hatırlayacağım.

Yüreğimde sana mezar değil,

Zindan açacağım.

Göremedin sevgimin büyüklüğünü,

Ama bili ki! 

Nefretim 

Güneşin mumu gölgede bıraktığı gibi

Sevgimi sönük bırakacak.

Ne mektuplarını 

Ne de resimlerini yakacağım.

Güleceğim fotoğraftaki yapmacık edaya

Sevda sözlerini okurken

Kahkahalar atacağım

Bunları bulmak için harcadığın çabaya.

Sana titreyen sesimle

İlk “seni seviyorum” dediğim gün

Sana olan nefretimin 

Takvim başlangıcı olacak.

Bir zamanlar  sana benzettiğim güller

Mahşerde şahidim olacak.

İşte yine şafak söküyor

Güneş kendini gösteriyor artık

Bugün de nefretinle sabahladım

Ama ne geçen günler

Ne de ölümün bitirecek nefretimi

Bir gün ben ölsem bile

Kıyamete değin solmayacak

Simsiyah bir gül bitecek mezarımdan

İşte bu gül

Buram buram 

Nefretimin kokularını yayacak

Sana 

Ve beni neyiyle değiştiğini anlayamadığım

Ruhu beş para etmez dostuna…', 'Seni unutmayacağım Bu ruh ölene, Gözlerimin feri sönene kadar, Duruncaya kadar kalbimin her atışıyla, Hasta ciğerlerime nefes nefes çektiğim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Koyuncu']::text[], 8.5, '{"poet":"Mehmet Koyuncu","poet_slug":"mehmet-koyuncu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/seni-unutmayacagim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hilkat', 'hilkat-ahmet-aksoy-l3y2x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kimse tanıyamaz seni

ve duyguların

..en haşin rüzgarlara vurur

..........kimse anlayamaz

yalnızsın

ilk kez toprağına

...üfledi ruhu Tanrı

tekdin

...çevir nen varsa yaradılışa

Tanrı tekdir

....ve sen

anla

neden üstün olduğunu.', 'kimse tanıyamaz seni ve duyguların ..en haşin rüzgarlara vurur ..........kimse anlayamaz yalnızsın ilk kez toprağına ...üfledi ruhu Tanrı te...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hilkat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felaketin Olurum', 'felaketin-olurum-i-lhan-gasi-qs7an', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Giderim; 

Seni de silerim çig tutmuş yüreğimden.

Geceyi de yakarım, seni de...

Üşümüş anıları örterim üstüne titrersin.

Felaketin olur ölürüm,

Hesap soramazsın...

Buz tutar cesedimin başında bedenin 

Kan yağar gözlerinden ağlarsın! 

Benden daha çok yanarsın.', 'Giderim;  Seni de silerim çig tutmuş yüreğimden. Geceyi de yakarım, seni de... Üşümüş anıları örterim üstüne titrersin. Felaketin olur ölürü...', ARRAY['Türk Edebiyatı','Şiir','İlhan Gaşi']::text[], 8.5, '{"poet":"İlhan Gaşi","poet_slug":"i-lhan-gasi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/felaketin-olurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adınla Seslendim Başkalarına..', 'adinla-seslendim-baskalarina-okan-savci-x3wpl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen bilmezsin,

Başkalarına adınla seslendiğim günlerdi.

Uzaktın bana

Duymazdın o yüzden

Yokluğuna derlenmiş türküleri.

Oysa sen varken,

Kanayan gecelere merhem olurdu sesin

Gülüşün dağıtırdı gözlerimden bulutu

Ara sıra gelirdin ya? 

Ben o zaman anlardım hangi mevsimi soluduğumu.

Seninle başlayan bir gün

Yine seninle biterdi.

Gecenin bir yarısı

Şehrin yollarını adımlarken

Ve bağlarken o geceyi sabaha

Hayat hiç olmadığı kadar güzeldi.

Bakışlarında mahsur kaldığımda,

Deli gibi akardı zaman.

Ara sıra hüzünler karışsa da sesine

Gecemizi karartmaya yetmezdi.

Ve ben ne zaman değsem dudaklarına,

Yüzüne bambaşka bir iklim gelirdi.

Sonra gittin...

Her gün bir takvim yaprağı,

Düştü umutlarımın arasından...

Ve durdu gözlerine daldığımda çıldıran zaman! 

Başkalarına, 

Adınla seslendiğim günlerim oldu.

Gelmedin...

Şimdi bilmiyorum hangi mevsimi soluduğumu...

(Sayın Akif OKTAYın -SEN GİDERKEN- adlı şiir albümünde yorumlanmıştır)', 'Sen bilmezsin, Başkalarına adınla seslendiğim günlerdi. Uzaktın bana Duymazdın o yüzden Yokluğuna derlenmiş türküleri. Oysa sen varken, Kana...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/adinla-seslendim-baskalarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hiç Eylülde Sevdin mi?', 'sen-hic-eylulde-sevdin-mi-okan-savci-rixsl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sabah,

Zamanı durdurdun sen...

Ayrılığı ekledin sonbahara

Mevsimin bütün bulutları,

Gözlerimde birikti de

Ben yağamadım bakışlarına...

Söyle! 

Hangi güneş 

Baharı getirecek şimdi bana? 

Kadehimiz ayrılağa kalkmadı ki hiç 

Ben nasıl içebilirim yokluğuna? 

Belki,

Zamansızdı sevgim 

En az gidişin kadar! 

Elde değil bu.....

Sen hiç eylülde sevip de

Vakitsiz hüzünlere beyaz bayrak salladın mı? 

Bilemezsin sevdiğim...

Nasıl da koyuyor adama güzün geri kalanı.....

Doğduğum gündeyim şimdi..

Yoksun.

Bir başıma içip,

      Kağıda gidişini karaladım...

Hazanda sevmek akıl karı değilmiş sevgili

Anladım...', 'Bir sabah, Zamanı durdurdun sen... Ayrılığı ekledin sonbahara Mevsimin bütün bulutları, Gözlerimde birikti de Ben yağamadım bakışlarına... S...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-hic-eylulde-sevdin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Vardiyası', 'gece-vardiyasi-asili-eros-cgdha', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece bela olur

Saatler kabus vaktini vurur

Karanlıkta senin ismin aydınlanır

Vardiya vardiya sensizliği yaşarım

Bilinmez yastık altı gözyaşlarımda

Didemlerde boğulurum

Akışım durur dayanamam

Vuslat yollarında gece yolculuğu

Gelişede gidişide senin sonun

Şimdi sensizlik iz olur viran olur

Kalbimdeki mezarın dua olur

Anılar yok olur

Anılar çok olur

Anılar yol olur

Geceler şahit halim duman olur

Gece vardiyaları benden sorulur

Sense hayat boyu gamsızlığınla kalırsın', 'Gece bela olur Saatler kabus vaktini vurur Karanlıkta senin ismin aydınlanır Vardiya vardiya sensizliği yaşarım Bilinmez yastık altı gözyaşl...', ARRAY['Türk Edebiyatı','Şiir','Asılı Eros']::text[], 8.5, '{"poet":"Asılı Eros","poet_slug":"asili-eros","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gece-vardiyasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vedan...', 'vedan-i-brahim-ethem-bingul-x8tm4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yoktu yüzün bana bakarken

Son vedanı söylerken

Baharı susmuştu

Siyah gözlerin isyandayken

Şimşekler çakıyordu gözlerinden

Son vedanı söylerken

Kırmızılar akıyordu dilinden

Seni artık sevmiyorum derken

Güneş küsmüş yüzümde

Tufan sonrası izler

Harman yerine dönmüş yüreğimde

Baharı değil, sonbaharı bekler', 'Yoktu yüzün bana bakarken Son vedanı söylerken Baharı susmuştu Siyah gözlerin isyandayken Şimşekler çakıyordu gözlerinden Son vedanı söylerk...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vedan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Aşıklar Telaşta', 'butun-asiklar-telasta-baykal-kaanalp-3dnpd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sensiz kaldım boşta

aradığım güzellik başta

bütün aşıklar telaşta

yeniden bulaştım aşka', 'sensiz kaldım boşta aradığım güzellik başta bütün aşıklar telaşta yeniden bulaştım aşka...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/butun-asiklar-telasta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pipo', 'pipo-baykal-kaanalp-ztk1z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir kır kahvesinde

balıkçı lokantasının yanıbaşında

deniz karşımda

oturuyorum

elimde

nereden bulduğumu bilmediğim

bir pipo

içinde biraz tütün

gözlerim kapalı

bir nefes çekiyorum içime

sanki kumsalda

çoraplarımla yürüyormuşum gibi

çok mu? çektim ne

hafiften bir öksürük

tadı bir çeşit

tarif edemiyorum

ama yine de 

seni unutturmuyor', 'bir kır kahvesinde balıkçı lokantasının yanıbaşında deniz karşımda oturuyorum elimde nereden bulduğumu bilmediğim bir pipo içinde biraz tütü...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/pipo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kınalım', 'kinalim-derin-oger-sog5s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu son güneş deme

ay tutulur gece de biter kınalım

iki gözüm bir de yüreğimsin övündüğüm

yılları geri alıp bakabilsen geçen dünlerde sen vardın

kabuğu sert içi hicrandı kınalım

aşk çok soğuk olur bazen

yokluğu gözüme gözüme batırma kınalım

kar yağar gök dökülür don çözülür kış biter canım

ölmün bile gücünü kıskandığı rüyalarda  sen vardın

gözümün nuru  yuvandı kınalım

adın ağzımdan dökülür sanma

dudağımdaki bir hüzünde bekler kınalım

yalnız savrulur nefesim tütünün en efkarlı dumanıyla

içimin gerçeğinde eli kıvılcım bir sen vardın

yangına kibriti çakandın kınalım

aşkı iz bırakmaz bulutlara benzetme

büyüsü kemanın telleri gibi gerilir kınalım

uçan kuşun süzülüşündeki ipektir  yüreğe yürüyen

özlemlerim kadar umutsuzluklarımda sen vardın

bu sevda mezara ertelidir  kınalım.........', 'bu son güneş deme ay tutulur gece de biter kınalım iki gözüm bir de yüreğimsin övündüğüm yılları geri alıp bakabilsen geçen dünlerde sen var...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kinalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özelliğin', 'ozelligin-baykal-kaanalp-um7yj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'takıldı gözlerim özelliğine

arayıp bulamadığın güzelliğine

yaksanda içimi ateşinle

bakacağım doyasıya güzelliğine', 'takıldı gözlerim özelliğine arayıp bulamadığın güzelliğine yaksanda içimi ateşinle bakacağım doyasıya güzelliğine...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ozelligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Beyaz', 'siyah-beyaz-i-hsan-uncuoglu-refm2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Siyah Beyaz 

Ruh''un nedir bak 

Ey nas etme naz 

Zaman akar yarın 

Ya siyahtır ya beyaz, 

Aklıma gelmiyor dilimin ucunda şu an 

Bazen o kadar canlı ki duyduğum 

Gözümün önünde ne varsa herşey sanki 

Her yer renkli avucum içinde bana ortak 

Dün bugün yarın sonra hepsi dün olacak 

Ne söylersen söyle ne yazarsan yaz 

Gelecekte varlığın ya siyahtır ya beyaz, 

*** 

Elinden iş gelmeyen sonuçta kaç para eder 

Kimin haberi var sağdan soldan yurdundan 

İster ağzınla kuş tut ister ol padişah sultan 

Mutlak varsa sana dair ardından arta kalan 

Gece gündüz allamei külli cihan kahin olsan 

Ne söylersen söyle ne yazarsan yaz 

Ele bakan gözlerde ya siyahsın ya beyaz,', 'Siyah Beyaz  Ruh''un nedir bak  Ey nas etme naz  Zaman akar yarın  Ya siyahtır ya beyaz,  Aklıma gelmiyor dilimin ucunda şu an  Bazen o kadar...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siyah-beyaz-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumsal, Ayak İzlerim, Dalga...!', 'kumsal-ayak-i-zlerim-dalga-musfik-saltik-w93mt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kumsalda  yürüyorum,

Bomboş, upuzun bir kumsal 

Islak kumda kalan ayak izlerim

Sanki geçmişte  kalan günlerim

Önümde uzanan kumlar geleceğim

Hoş bir duygu  iz bırakabilmek geçmişte

Ve yeni izler bırakmak için yürümek ileriye

Bunları düşünürken kendi kendime

Birden  bir rüzgâr esmeye başlıyor 

Denizde küçük dalgalar beliriyor

Sonra büyüyor dalgalar, köpürüyor

Islak kumda hızla ilerliyor, 

İzlerimi bir bir siliyor 

Kumsal yine dümdüz oluyor

İçime bir burukluk  doluyor

Kolay değil buna katlanmak

Gözümün önünde geçmişim yok oluyor

Telaşlanıyorum  hızla  koşuyorum

Bütün gücümle kumlara basıp

Yeni izler bırakıyorum

Çabalarım sonuç vermiyor

Deniz dalgalarıyla saldırıyor

İzlerimi siliyor.

Hayatımı düşünüyorum 

Geçen yıllarımı, çabalarımı

Her şey netleşiyor birden gözümde 

Islak kumlar   “ yaşanan yıllar “ 

Ayak izlerim   “dünyada bıraktıklarım” 

Dalgalar   “ acımasızca geçen  zaman “

Öyleyse bu kadar didinmem, çabalamam

Beyhude mi  o zaman 

                                                         Haziran 2004', 'Kumsalda  yürüyorum, Bomboş, upuzun bir kumsal  Islak kumda kalan ayak izlerim Sanki geçmişte  kalan günlerim Önümde uzanan kumlar geleceğim...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kumsal-ayak-izlerim-dalga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olta ve Balıklar,....!', 'olta-ve-baliklar-musfik-saltik-5tec3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sahilde balık tutan adamlar, kadınlar

Neşeyle gülüp eğleniyorlar

Balık çok bol çıkıyor, 

Üzüm salkımı gibi doluyor oltalar

Kovaların içindeki bulanık suda

Ölümü bekleyen balıklar 

Son güçlerini toplayıp 

Kovadan denize doğru sıçrıyorlar

Önce üzülüyorum hallerine

Sonra oltalar ilişiyor gözüme

Küçük tüylerle gizlenmiş 

On beş, yirmi iğne 

Denizde süzülürken

Yavru balık sürüsü gibi görünüyorlar

Yavruları  yemek için saldıran büyük balıklar

Oltaya takılıyor, avcıyken av oluyorlar.

Demek ki göründükleri  kadar masum değiller

Can almak isteyenler bazen bedelini canlarıyla öderler.

Buraya kadar  her şey çok adil çok güzel

Ama bu kurallar neden yalnızca hayvanlara işler

Bebeklere, çocuklara, kadınlara yaşlılara kıyan caniler, 

İşkencelerini marifet gibi  kare kare resimleyenler.

Yeni ürettikleri silahları masum insanlar üzerinde deneyenler

Özgürlük getireceğim diyerek acımasızca saldırıp

İnsanları kendi vatanında esir edenler 

Menfaatçi, eli kanlı,  gözü dönmüş katiller

Neden el üstünde tutulur, değerli mücevherler gibi korunur

Törenlerle karşılanır, en iyi şekilde ağırlanır, baş tacı edilirler 

Yaradan dan damı torpilli yoksa bu  merhametten  yoksun herifler.

Neden bu dünyada hep dürüst ve masum insanlar BEDEL öderler.

                                                                         Haziran 2004', 'Sahilde balık tutan adamlar, kadınlar Neşeyle gülüp eğleniyorlar Balık çok bol çıkıyor,  Üzüm salkımı gibi doluyor oltalar Kovaların içindek...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/olta-ve-baliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal Deseydin', 'kal-deseydin-cafer-yilmaz-q59u6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir İstanbul sabahında

Boğazın sularıyla yıkadım yüzümü.

Martılar havlumu tuttu,

Ben onlara simit attım...

Tanıdık bir sima aradı gözlerim.

Sevilesi bir yürek.

Bir efkar bastı eski günlere,

Dalgaları satır satır karaladım...

Bir İstanbul vardı, sevdiğim.

Bir İstanbul kadar sevdiğim.

Ey İstanbul kokuşlum! 

Kal deseydin, gider miydim....

Fethedilmiş bir şehrin,

Fethedilememiş bir yüreği...

Surlar diktim ben de

Senin başlayıp

Senin bittiğin yere...

Arnavut kaldırımlı yüreğin,

Kanattı her yerimi...

Kız kulesi gibi uzaktın kıyılarıma...

Ne zaman seni sevsem

Adresim Yedikule zindanlarında...

Her yolcuyu kabul eder Boğaz’ın...

Bir bana yabancı kaldı limanların.

İstanbulsun işte,

İstanbul gibi acımasız.

Sebebisin tüm yaralarımın....

Yüreğinde fırtına eser 

Köpürür deniz çoğalır dalgalar.

Satır satır vurur kıyıma,

Aslında sana yazacak çok şey var...

Bir İstanbul vardı, sevdiğim.

Bir İstanbul kadar sevdiğim.

Ey İstanbul kokuşlum! 

Kal deseydin, gider miydim.....', 'Bir İstanbul sabahında Boğazın sularıyla yıkadım yüzümü. Martılar havlumu tuttu, Ben onlara simit attım... Tanıdık bir sima aradı gözlerim. ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kal-deseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuk Sevda', 'tutuk-sevda-cafer-yilmaz-skri1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıradanım, yemin ederim kaynak yapmadım hayata. Önümde ve arkamda insanlar, ve inan yok onlardan hiçbir farkım. Öyle sıra dışı bir hayat serüvenim yok ki film yapıp gişe rekorları kırayım... Hayatı varoşlarda acılı arabesklerden öğrendik bir de duvar yazılarından... Büyüklerimiz kavga ederdi biz seyrederdik. Arabesk babalarımızın şimdilerdeki deyimiyle en hit parçalarını ezbere bilirdi  mahalleli abilerimiz.... Sevdaların ne kadar yanık koktuğunu  abilerimizin kokularından anlardık. Biz küçüktük ve aşk neyimizeydi bizim. Açık hava sinemaları vardı ve tüm mahalleli akşam orada ağırlardı birbirini.... Film başlar ve en acıklı göz yaşlarıyla sel basardı sinemayı... En acıklı filmlerde çocukça kahkahaları basınca acının ne olduğunu popomuzdan anlardık... Büyüklerimiz film seyrederdi  biz de büyüklerimizi...

Ali’nin Ayşe’yi sevebilme ihtimali yoktu olsa olsa bu hak sadece Cin Ali’nin olabilirdi.Allah muhafaza gerçekten böyle bir şey oldumu  cephe duvarlara manşet atılırdı yedi mahalle duyardı. “ Ali Ayşe’yi seviyor”  hemen altlarında kahrolsun diye bir şeyler yazardı Ali de Ayşe de rezil olurdu.... Bu konuda rahatım çünkü hiçbir duvara hiçbir şekilde hiçbir kişiyle adım yan yana oturmadı. Sıradanım dedim ya o sıralar sadece seyretmek vardı.

Fener’den şimdi ki oturduğumuz yere taşındığımızda saçım o kadar uzundu ki kız sanıp öğretmenim bir kızın yanına oturtmuştu beni. Ve bu benim ilk defa bir kızın kazayla vücuduna değdiğim tarihi bir vakaydı... Erkek olduğum anlaşılınca sürgün yollandım bir başka sıraya....Bir okul arkadaşıma bir şeyler duyuyordum ayıptır söylemesi ki o zamanlar söylenmesi gerçekten ayıptı aynı Cüneyt Arkın abimize benziyordu gözleri..ben her ikisine de hayrandım o zamanlar. 

Türk istikbalinin bir ferdi olan ben, birilerine layık olma çabası içinde sadece kitaplarıma aşıktım. Arkadaşlarımın Zagor kitapları da vardı pembe dizileri de...Dersleri kırıp İstanbul sokaklarında sevda kovalarlardı ben okulda kalırdım. En moda edebi mektuplar ve şiirler  hep bana yazdırılırdı. ama. Yazımda güzeldi cümlelerimde ama ben hiç bana ait birine yazamadım.Her teneffüs başka bir arkadaşım olurdum. Ben olamazdım. Herkesin kitap kapaklarının arkasında isimler yazılırdı ben kitaplara kıyamazdım.hiç sevmedim mi? sevdim deli gibi bir zaman sonra... yıllarca sürdü sevgim yüreğimin en gizli yerinde...korkaktım...bir gün cesaretimi toplayıp söylemeye karar verdiğimde ise çok geç kalmıştım çünkü kızcağızın babasının sanırım beni bekleyecek vakti kalmamıştı.

Aşk meşk derslerine geç kağıdıyla girdim ben... Hayat bir çok konuyu anlatmıştı, bana yaşayarak öğrenmek kalmıştı.Deneme yanılma yoluyla tamir etmek gibi bir hayatı.Hayat deney bense denek olmuştum kısaca.

Sevda tutukluğum bundan olsa gerek.dilimden çok duyamayacaksın belki “ seni seviyorum” cümlesini. Sabahın erken saatinde uyku tutmadı beni. sense uyuyordun melekler gibi. Kıyamadım uyandırmaya ve kimsenin sevdiğini öpmediği bir saatte öptüm seni.....', 'Sıradanım, yemin ederim kaynak yapmadım hayata. Önümde ve arkamda insanlar, ve inan yok onlardan hiçbir farkım. Öyle sıra dışı bir hayat ser...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tutuk-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudu Gelecek Yıllara Çevir', 'umudu-gelecek-yillara-cevir-nesrin-gocmen-ukafd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pamuklar içine doğan bebeğim 

Suskun bakışını dillere çevir 

Toprağına küskün açmaz çiçeğim 

Günâhı kovansız kullara çevir 

. 

Olamaz bir engel kavuşuruz biz

Zamanı eskitmez açılmayan giz

Kapanmaz yaradır yasak sevgimiz

Umudu gelecek yıllara çevir

Sen benim gönlümün nazlı sümbülü

Habersiz yangının uçuşan külü

Görünce ufukta barış mendili 

Kahve gözlerini yollara çevir

Unuttun mu şimdi gülümsememi 

Bilirsin aklımla sevmiştim seni 

Zamansız karşında görürsen beni

Hasreti açılmış kollara çevir 

. 

26/06/2004', 'Pamuklar içine doğan bebeğim  Suskun bakışını dillere çevir  Toprağına küskün açmaz çiçeğim  Günâhı kovansız kullara çevir  .  Olamaz bir en...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/umudu-gelecek-yillara-cevir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öfkeliyim', 'ofkeliyim-yilmaz-boga-c9dqc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yüreğim sancıyor

duygularım karmakarışık

sıkılıyorum

aklımda ölüm

cesaretim yok

beceremiyorum

hep sarhoş kalmak istiyorum

içiyorum..içiyorum..içiyorum

dinmiyor öfkem

sevda kötü vurmuş

her yanım sen

düşündükçe kara gözlerini

yağmura duruyor gözlerim

dizimin bağı çözük

takatsiz

bulamıyorum tutunacak bir yer

sararmış

sonbahar yaprakları gibiyim

kadehim dertlerimle dolu

seni yaşıyorum

sensizliğimi yaşadıkça

bir kadeh 

bir kadeh daha..

sevdamı içiyorum

ölmek düşüyor aklıma..

(Sydney)', 'yüreğim sancıyor duygularım karmakarışık sıkılıyorum aklımda ölüm cesaretim yok beceremiyorum hep sarhoş kalmak istiyorum içiyorum..içiyorum...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Boğa']::text[], 8.5, '{"poet":"Yılmaz Boğa","poet_slug":"yilmaz-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ofkeliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Olur', 'gun-olur-yilmaz-boga-wqmrp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni düşünürken 

her an

bağrıyanık

coşar yüreğim

gözlerim dalar gider

dizginleyemem duygularımı

gün olur

kara gözlerini özlerim

avuçlarımda eriyen ellerini

gün olur...

benim olmadığını düşünür

kararır dünyam', 'seni düşünürken  her an bağrıyanık coşar yüreğim gözlerim dalar gider dizginleyemem duygularımı gün olur kara gözlerini özlerim avuçlarımda ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Boğa']::text[], 8.5, '{"poet":"Yılmaz Boğa","poet_slug":"yilmaz-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gun-olur-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karagözlüm', 'karagozlum-yilmaz-boga-emu6g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nedendir gözlerimdeki hüzün

tökezlemesi yüreğimin

dinleyebilir misin...

söylesem

neler çektiğimi sensiz

söylesem 

neler çektığimi

sensiz....

dinler misin karagözlüm

anlatsam 

seni canımdan çok sevdiğimi

tutsaklığımı

kara gözlerine

anlayabilirmisin...

(Sydney)', 'nedendir gözlerimdeki hüzün tökezlemesi yüreğimin dinleyebilir misin... söylesem neler çektiğimi sensiz söylesem  neler çektığimi sensiz.......', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Boğa']::text[], 8.5, '{"poet":"Yılmaz Boğa","poet_slug":"yilmaz-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/karagozlum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstersen', 'i-stersen-yilmaz-boga-5vhz3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'öldür beni istersen

umutlarımla

gözbebeklerine gömüleyim

sevmeyi öğren gözlerimde...

sana herşeyimi vereyim

korkun nedir bilemem

kilitli kalbine giremem

senden sevgi dilenemem

her gün ölmektense

bir kelimeyle

bitir bütün umutlarımı

öldür beni

umutlarım ve sevgimle

göz bebeklerine gömüleyim..

(Sydney)', 'öldür beni istersen umutlarımla gözbebeklerine gömüleyim sevmeyi öğren gözlerimde... sana herşeyimi vereyim korkun nedir bilemem kilitli kal...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Boğa']::text[], 8.5, '{"poet":"Yılmaz Boğa","poet_slug":"yilmaz-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istersen-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Sor', 'bana-sor-cengiz-oyke-gzc9u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak kaç  yıl daha yaşlandık sen gittikten sonra

Ve bu gün senin doğum günün

Bu  gün öyle sert vuruyor ki sevda  dalgaları gönül kıyılarıma

Hala içimde alevlendirmeni bekleyen birkaç parça kor

Sen gittikten sonra  öldüm, bittim demiştim ben

Yaşıyorum ama bir mart gecesinde 

Gel birde bana sor

                  

                                 Mart 2004', 'Bak kaç  yıl daha yaşlandık sen gittikten sonra Ve bu gün senin doğum günün Bu  gün öyle sert vuruyor ki sevda  dalgaları gönül kıyılarıma H...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Öyke']::text[], 8.5, '{"poet":"Cengiz Öyke","poet_slug":"cengiz-oyke","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bana-sor-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadağımda Son Bir Ok', 'sadagimda-son-bir-ok-hakan-sarkdemir-npway', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen ey bir şehri ikiye bölen denizin meltemi

saçlarımı tara, suskun bir çocuk olurum taraçanda

beni bin yıllık bir öpüşle dirilt

surların kıyısında akan kalabalıktan

sıyrılsın resmim ve sen ey avuçlarımda

bir hırçın kedi kadar

bana aşina ve tatlı rüzgar artık es

hatırlat korsanlık tarihimi

sür beni o damda esneyen kaypak güneşten

dolaplar ve rutubet arasında gerinen

kuytu bir hayvanın nefesinden beni sür

yağmurun çitlerinden örülmüş ve batan

bir günün telaşlı sarayında bir müddet

durmuş ve oyalanmışım

yıllardır uzanmışım mevsimin hamağında

orada, başka bir yağmurun beni çağıran sesi ardında

yolu kesen tırpan hattından geçip evime varamamışım

sür ellerimi kirli mecalsiz

ve buyurgan bir sahradan açılsın kanatlarım

bukağılıklarımda yeniden ürpersin kış

ve yeniden sağrımda bakırdan bir tan

beni sür kızgın bayırlara

savaş arabalarıyla çekilen bir ırmaktan

lodosu bir kadını tanır gibi tanıyan, dindirip kanırtan

denizin koşumlarında dik duran forsalardan

ordumu toplayıp getir

çoktandır kanın çekildiği akrepte

dalmış ve oyalanmışım

kromdan ve acıdan damıtılan serapmış meğer

bir kızın uzattığı galondan tattığım şarap

yani o alaşım kesmedi bende çoğalan öfkeyi

yani ateşten köpekler sıçramıştı üstüme

birden dalgınlıkla saptığım o çıkmaz sokakta

kürenmiş közdeki esrarı farkeden ve

zifiri çöpleri eşeleyen fareler

tanımadı bendeki o ıtırlı bitkiyi

sanki sırlı bir aynadan izliyorduk iklimi

ilk cinnetten kalıtılmış olan kan

süzülüyor ve akıyordu, elimden

hırsla fırlatarak baltayı

“hayır! ” dedim “bu mutsuz

ben olamam”

koşmalıydım öyleyse mirasın reddi için

bulmalıydım beni beraat ettirecek kanıtı

ve neden sonra vardığım kütükte 

uyuklayan ihtiyar puhu

bakışlarını indirerek üstüme

ve hınkırarak 

dedi ki: “asla! duymadım bugüne dek

bunca yıllık adli ömrümde

yargının kudretini böyle arzular biri

ama yine de bilemem karışık bir mesele”

katil de maktul de benmişim meğer

yani sürüyormuş bu dava doğduğum günden beri

yani ben ölene dek askıdaymış karar

oysa sandım ki tek celsede bitecek işim

ve koynumdaki metresi kandırmak için

boşamalıymışım artık içi geçmiş olanı

yani ölümün mekanik gürzünün indiği bu yerde

çoktandır dalmış ve oyalanmışım

ve çoktandır kasalarda biriken ter

o kaltak hesap pusulası, o küflü defter

sıcak nefesiyle raptolmuştu alınlarına

yani soluk benizlerine çatılmıştı intihar

ve ben durmadan boğmak istiyordum

bir berberi, bir kahyayı, bir terziyi, bir

sicil yazıcıyı, bir vaizi, bir tellalı, bir makasçıyı,

bir tefeciyi ve yine bir terziyi ve bir değnekçiyi

ve satranç oynayan bir kabileyi ve kurşun askerleri,

biletçileri, bıçak bileycileri, mezar kazıcıları

ve o derin gayyaları ve herşeyi önceden

bilip yatışan kadınları, derinden öpmeyi bilen

adamları ve piyangocuları ve çaşıtları

boğmak istiyordum ayaklarımı sabit kılınacak

yerden kesmek için uğraşan kalabalığı

yani kuşkunun çayırından üremiş

bakışlar süreğinde bir müddet

bir humma nöbetiyle birlikte

dalmış ve oyalanmışım

sen ey bir şehri ikiye dilen denizin meltemi

çoktandır dalmış ve oyalanmışım

çoktandır dalmış ve

ıpıssız

bir at gibi beklemiş bir kavşakta

o ilk atılgan çocuk ben, varırım taraçana

artık istemiyorum tükenen bir şey için

soğuk bıçaklar kapmak için acının yamacından

artık yok olan sakallarını bitkin tanrılarla

tarayan kalabalığın şehre devrildiği kızakla

batan bir gün gibi inmeyi istemiyorum

batan bir gün gibi sirenlerden,

iskele önlerinden, vitrinlerin çok katlı, loş

ve kızıl resminden, batan bir gün gibi

devrilmek, devrilmek ve devrilmek

istemiyorum, budala ve temkinli

olmanın takımından ve suçsuz ve alışkın ve horlanmış

ve tuhaf ve kancalarla çekilip

yürütülen batan bir güne açılan yorgun bir çanta gibi

ölmeyi istemiyorum

bana şimdi unutamadığım o şarkıyı mırıldan

beni karıştırıp hırçın saçlarından ürperen bir ormana

o karanlık bağrına alnımı geçir

oraya, boşanan sağnaklara

(Batık Değirmenler, 1997)', 'sen ey bir şehri ikiye bölen denizin meltemi saçlarımı tara, suskun bir çocuk olurum taraçanda beni bin yıllık bir öpüşle dirilt surların kı...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şarkdemir']::text[], 8.5, '{"poet":"Hakan Şarkdemir","poet_slug":"hakan-sarkdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":104,"source_url":"https://www.antoloji.com/sadagimda-son-bir-ok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar', 'onlar-yusuf-koc-9bo46', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya devletine tahtı kuranlar,

Selamı sabahı keser giderler,

Yalan hile ile vurgun vuranlar,

Sel gibi tufan gibi eser giderler.

Daima karnı aç doymuyor gözü,

Yüz sözün yalandır dosandokuzu,

Onuru tükenmiş kızarmaz yüzü,

Lanet tohumunu eker giderler.

Sevda dillerinde alıcı tuzak,

İnsanlık bunlara uzak mı uzak,

Kışın üşütüyor yazlar da kurak,

Göz ucuyla aşkı süzer giderler.

Dünleri sislidir yarını kara,

Aklında neler var kimdedir sıra,

Kapanmaz onların açtığı yara,

Fakiri masumu ezer giderler.

Silahı paradır yok adaleti,

Kazanayım diye kırar milleti,

Ödetirler her an halka ücreti,

Kader defterini dürer giderler.

Ona göre senin karnın pek toktur,

Her türlü haram kendine haktır,

Harmanı kucaklar ekinde yoktur,

Kıraç tarlaları kürer giderler.

Sakınmaz sözünü yazar Koç Ozan,

Balina gibidir fakirim sazan,

Onlar toz bulutu heryere sızan

Malıma canıma girer giderler.', 'Dünya devletine tahtı kuranlar, Selamı sabahı keser giderler, Yalan hile ile vurgun vuranlar, Sel gibi tufan gibi eser giderler. Daima karnı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/onlar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atıf-0-14-Babalar Gününe', 'atif-0-14-babalar-gunune-vedat-koparan-2kaii', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Saygı Ve Sevgilerimle Unutulmazlıklarımızla Anarken

Merhaba Tüm Babalara Merhaba Baba) 

Yaşadık En Delice 

En Hoyrat Rüzgârlar Eserken 

Ayrılıklar En Başta 

Gelmedik Gelemedik Hiç Bir Araya

Senin Kaç Dalın Kırılmıştı 

Benim Ki En Başta

Ne Çok Severdin 

Sınırları Tanımadan Baremi Aştıkça

Yaşadın Ya Erkenciler De 

En Deli Poyrazlarla

Dikiş Tutmaz Bu Yaşam 

Güneşi Üzerine Doğurmayan 

Seni Anlatmak Zor Küçük Dev Adam 

Hep İki Damla Bir Boğum Maviler 

Cüce Kaldım Uçkun Deryanda 

Böyle Günlere Isınamadım Nedense

Bir Yılda Bir, Kaç Yıl Yoksun, Yoklar Oysa..

Vedat Koparan 20.06.2004 (17:20)', '(Saygı Ve Sevgilerimle Unutulmazlıklarımızla Anarken Merhaba Tüm Babalara Merhaba Baba)  Yaşadık En Delice  En Hoyrat Rüzgârlar Eserken  Ayr...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/atif-0-14-babalar-gunune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşkın', 'boskin-hakan-sarkdemir-3mvh5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sanmıştım

yağmurdan evvel bu dik yamaçlara ben inecektim

hep diri ve taze kalacaktı avucumda çiçekler

ve belki geniş ve engebeli bir ovanın sonunda

kadife dar bir kapı beni bulacaktı

çoktandır elimde sakin tuttuğum kılıç

söküyor kilitleri tabutumdan tek tek

gözlerimde baharın uçuşan renkleri

siliniyor ve yakıyorum korsan ceketimi

(Batık Değirmenler, 1997)', 'sanmıştım yağmurdan evvel bu dik yamaçlara ben inecektim hep diri ve taze kalacaktı avucumda çiçekler ve belki geniş ve engebeli bir ovanın ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şarkdemir']::text[], 8.5, '{"poet":"Hakan Şarkdemir","poet_slug":"hakan-sarkdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/boskin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskidenmiş', 'eskidenmis-i-smet-barlioglu-gdyog', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eskidenmiş dağların aşka engel olduğu,

Artık dağlar sevene, bilene engel değil.

Eskidenmiş gidenin gidip de dönmediği,

Uzaklık zorluk değil, gidene engel değil.

Seven sevdiği için bir ömürlük yol gider,

Kuşun kanadı bile en sarp dağı yol eder,

Sanma ki sulak yerde, münbit yerde ot biter,

En çıplak kaya bile bitene engel değil.

Gördüğüm günden beri senin için yanarım,

Ne senden başkasını, ne birşeyi ararım,

Ateş, alev içinde kavruldu dudaklarım,

Demirden beden bile tütene engel değil.

Düştüm senin aşkına, derdim var, dermanım yok,

Bu dertten kurtulmaya en küçük imkanım yok,

Kapılmışım seline, el atıp tutanım yok,

En zorlu yardım bile batana engel değil.

Ben sırrımı sakladım, sırrım yine faş oldu,

Ben aşkından sarhoşum, lakabım ayyaş oldu,

Yatağım kara toprak, yastıklarım taş oldu,

En soğuk taşlar bile yatana engel değil.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 85-86/100)', 'Eskidenmiş dağların aşka engel olduğu, Artık dağlar sevene, bilene engel değil. Eskidenmiş gidenin gidip de dönmediği, Uzaklık zorluk değil,...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/eskidenmis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olunca', 'sen-olunca-i-smet-barlioglu-dshec', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Havaya bak, nice güzel,

Mehtap güzel, gece güzel,

Şive güzel, lehçe güzel,

Herşey güzel, sen olunca.

Rüzgar eser, fısıldaşır,

Menekşeler selamlaşır,

Kuşlar öter, cıvıldaşır,

Herşey güzel, sen olunca.

Dalgalanır arpa, buğday,

Gelincikler çeker halay,

Şarkı söyler ırmakla çay,

Herşey güzel, sen olunca.

Gökyüzünde bulut kalmaz,

Tipi çıkmaz, dolu yağmaz,

Tek bir çile kıpırdamaz,

Herşey güzel, sen olunca.

Nilüferler gülüşürler,

Tomurcuklar öpüşürler,

Sarmaşıklar güreşirler,

Herşey güzel, sen olunca.

Dünya güzel, herşey tatlı,

Yerler, gökler şatafatlı,

Mutluluklar yüzbin katlı,

Herşey güzel, sen olunca.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 87-88/100)', 'Havaya bak, nice güzel, Mehtap güzel, gece güzel, Şive güzel, lehçe güzel, Herşey güzel, sen olunca. Rüzgar eser, fısıldaşır, Menekşeler sel...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-olunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidelim', 'gidelim-i-smet-barlioglu-trg4p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Buram buram çiçek koktu havalar,

Gel el ele vere vere gidelim.

Her kelebek bir çiçeği kovalar,

Kuzuları göre göre gidelim.

Gelincikler sanki toyda, düğünde,

Menekşeler papatyalar içinde,

Oğul veren arıların önünde

Baka baka, dura dura gidelim.

Sevdamızı bilir çaylar, tepeler,

Çevremizde uçuşuyor serçeler,

Nerde uyur mehtap dolu geceler,

Akşamlara sora sora gidelim.

At kolunu omuzuma, boynuma,

Ben beline sarılayım boyuna,

Erişelim aşkımızın tadına,

Lezzetine vara vara gidelim.

Tarlaların başakları altından,

Harmanlarda göz kamaşır samandan,

Döven sürüp harmanlarda durmadan,

Ekinleri yara yara gidelim.

Kuzu, oğlak koşuşuyor, oynuyor,

Duru ırmak balıktır ki kaynıyor,

Bir kalbim var, o da sana yanıyor,

At okunu, vura vura gidelim.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 89-90/100)', 'Buram buram çiçek koktu havalar, Gel el ele vere vere gidelim. Her kelebek bir çiçeği kovalar, Kuzuları göre göre gidelim. Gelincikler sanki...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gidelim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum', 'yoruldum-yusuf-koc-00li0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Altmış yıl boyunca tozlu yollarda,

Yokuştan inişten düzden yoruldum,

Çiçeği açmayan kuru dallarda,

Tutulmayan yalan sözden yoruldum.

Harabeye dönmüş bahçeler bağlar,

Başı eğmiş mahzun dumanlı dağlar,

Her yanda anlar babalar ağlar,

Maviden yeşilden bozdan yoruldum.

Herşey odaklanmış paraya pula,

Düşmüşüz dönülmez uzun bir yola,

Halimi anlatsam sevdalı kula,

Karşılık görmeyen aşktan yoruldum.

Bazısı siyasi bazısı çoban,

Bazısı bulamaz örtecek yorgan,

Dost eli kalmamış hepsi ısırgan,

Bozuk düzen çalan telden yoruldum.

Yoruldum ben duyun hayat işinden,

Nice sevdaların koştum peşinden,

Gözlerinin hilal gibi kaşından,

Yarin haşin bakışından yoruldum.

Sayısız Koç Ozan bu yoldan geçti,

Duygular sel oldu yataktan taştı,

Sona kalan herkese bir garip baştı,

Bitirdiğim her şiirden yoruldum.', 'Altmış yıl boyunca tozlu yollarda, Yokuştan inişten düzden yoruldum, Çiçeği açmayan kuru dallarda, Tutulmayan yalan sözden yoruldum. Harabey...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yoruldum-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Gözyaşların', 'gozyaslarin-guclu-sonmez-vvpzp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözyaşların birer tuzak

Kimbilir içlerine düşen

Daha kaç aşık boğulacak

(Istanbul, Haziran 2004)', 'Gözyaşların birer tuzak Kimbilir içlerine düşen Daha kaç aşık boğulacak (Istanbul, Haziran 2004)...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozyaslarin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban Olsun Canım Sana', 'kurban-olsun-canim-sana-i-smet-barlioglu-p96mu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eller seni anlamazlar,

Sana layık olamazlar,

Benim gibi yanamazlar.

Ben aşığım bir baksana,

Kurban olsun canım sana.

El denizi görmez gözde,

El sedefi görmez yüzde,

El sefayı bulmaz sözde.

Ben aşığım bir baksana,

Kurban olsun canım sana.

El ne tanır albeniyi,

El ne bilir en iyiyi,

Kim beğenmez bir periyi,

Ben aşığım bir baksana,

Kurban olsun canım sana.

El dikensiz bir gül ister,

El zararsız bir dil ister,

El hizmeti çil çil ister,

Ben aşığım bir baksana,

Kurban olsun canım sana.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 91-92/100)', 'Eller seni anlamazlar, Sana layık olamazlar, Benim gibi yanamazlar. Ben aşığım bir baksana, Kurban olsun canım sana. El denizi görmez gözde,...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kurban-olsun-canim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım', 'kadinim-ali-gencay-qoobt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '’Kadınım,ateşim,narım, efkarım,,

Gece gel gündüz gel,dize ol bana hece hece gel

Çıkar rediflerini üzerinden,kafiye ol öyle gel

Son kurşunum kalemimde,kağıda dizil de gel

Perçem perçem saçların,gözüne sürme çek de  öyle gel

‘’kadınım,ruhum,varım,eyvahım,,

Kapa gözlerini,unut bütün söylenenleri,katıksız gel

Damarım da kansın,ruhuma cansın, ecel olda gel

Korkular büyüt gecende, şimşek,gök gürültüsü,çocuk olda gel

Bak bir yaşam sana,sus konuşma,ahraz ol lal olda öyle gel

‘’kadınım,hevesim,nefesim,sebebim,,', '’Kadınım,ateşim,narım, efkarım,, Gece gel gündüz gel,dize ol bana hece hece gel Çıkar rediflerini üzerinden,kafiye ol öyle gel Son kurşunum ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kadinim-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugünler Bulunur mu?', 'bugunler-bulunur-mu-i-smet-barlioglu-xfji1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Avutma yalanlarla mahzun gönlümü böyle,

Geldi geçiyor işte, bu günler bulunur mu? 

Sevsen de sevmesen de bana açıkça söyle,

Geldi geçiyor işte, bu günler bulunur mu? 

Bu günleri mumlarla arayıp duracağız,

Yaşlı, yorgun yıllardan maziyi soracağız,

Yersiz dargınlıklarla nereye varacapız? 

Geldi geçiyor işte, bu günler bulunur mu? 

Herbir dargın bakışın yaralıyor gönlümü,

Görmez oldum yıllardır yüzüme güldüğünü,

Gel artık barışalım, çözelim bu düğümü,

Geldi geçiyor işte, bu günler bulunur mu? 

Günlerimiz eriyor mum gibi şamdanlarda,

Güneş değildir batan, ömrümüz, akşamlarda,

Ömrümüz can veriyor çınarlarda, çamlarda,

Geldi geçiyor işte, bu günler bulunur mu? 

Ömür akıp gidiyor elimizden su gibi,

Yaşanmayan her sevda bir derin uyku gibi,

Geçen günler ömüre kurulmuş pusu gibi,

Geldi geçiyor işte, bu günler bulunur mu? 

Her dargınlık koparır her sevdadan bir parça,

Hayır kalmaz bedenden, yürekler paramparça,

Kalpler kenetlenmeli ömürler azaldıkça,

Geldi geçiyor işte, bu günler bulunur mu? 

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 93-94/100)', 'Avutma yalanlarla mahzun gönlümü böyle, Geldi geçiyor işte, bu günler bulunur mu?  Sevsen de sevmesen de bana açıkça söyle, Geldi geçiyor iş...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bugunler-bulunur-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Edepsizdir Ruhum', 'edepsizdir-ruhum-t-l-n-ayse-kayi-8sdoj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanma ki,

Seni teslim edeceğim! 

Zalimlerden zalim bilmeyesin beni,

Kırkikindi yağmurları gibi gel,

Üzerime döküldükçe,

ıslanmak zulüm olmaktan çıksın.

Sanma ki; 

Seni umutsuzca seviyorum.

Umutlarımı,

Senin bilmediklerin yüklenmiş,

Bilmediklerin için, feda ettim her şeyimi.

Fırtınalar var gönül evimde,

Fırtınalar, kasıp kavurur...

Şikayetim yok,

Kavrulmak isteyen benim.

Sanma ki; 

Edepsizdir ruhum,

Edeplerimi sana vermek için bekliyorum.

Kömür karası gözlerin için öperim dudaklarını,

Ölüm sessizliğine, aşıkların kahkahaları karışır.

Seninle olmak için,

Azrail’e meydan okurum,

Her meydan okuma,

Bir sıkımlık umuttur.

12.06.2004', 'Sanma ki, Seni teslim edeceğim!  Zalimlerden zalim bilmeyesin beni, Kırkikindi yağmurları gibi gel, Üzerime döküldükçe, ıslanmak zulüm olmak...', ARRAY['Türk Edebiyatı','Şiir','Tâlân Ayşe Kayı']::text[], 8.5, '{"poet":"Tâlân Ayşe Kayı","poet_slug":"t-l-n-ayse-kayi","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/edepsizdir-ruhum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vaha', 'vaha-naime-erlacin-gteva', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'korkudan sıyrıldığında buluyor kimliğini aşk

ayın yüzünde fî tarihinden kalma

bir gül lekesi kadar duru 

şavkıyarak

intihardan uzaklaştığında

yok saydık çölleri

yok saydık boşa dönen paslı kilitleri

sahiplenmeyi bekleyen 

kayıp belgeleri

ufuk çizgisi kapandığında

sesine dönüyor aşk

özüne dönüyor her menzil 

umulan son vaha olduğunda

susmak 

konuşmak

ve anlam adına

sorumluyum gülümden! 

(26 Haziran 2004)', 'korkudan sıyrıldığında buluyor kimliğini aşk ayın yüzünde fî tarihinden kalma bir gül lekesi kadar duru  şavkıyarak intihardan uzaklaştığınd...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/vaha-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Geri Dönersin', 'bir-gun-geri-donersin-bayram-tunca-levnz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Olur da belki bir gün geri dönersin

İhtimal bu olanları tarihe gömersin

Daha fazla yıkmadan git ne olursun

Belki, bir gün geri dönecek olursun

Rüzgarın boranlı dağları çarpması misali

Sesin kör kuyularda yankılanması misali

Dalgaların karaya çarpıp dönmesi misali

Bir gün geri dönersin bugün gitsen dahi

Gökteki cisimlerin doğup batması misali

Mevsimlerin her yıl gidip gelmesi misali

Buharın gökte rahmet olup dönmesi gibi

Bir gün geri dönersin, bugün gitsen dahi

B. Tunca/26.06.2004-06.26', 'Olur da belki bir gün geri dönersin İhtimal bu olanları tarihe gömersin Daha fazla yıkmadan git ne olursun Belki, bir gün geri dönecek olurs...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-gun-geri-donersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiraz rengi Haziran', 'kiraz-rengi-haziran-vedat-koparan-gnjxw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Yapışık kirazlar toplanır dallardan

Romantizm eser bir avuçtan bir çataktan 

İkizin birini aldım uzattım ağzımdan

Kiraz dudaklar ısırdıkça rengi suyunda 

İçim gitti dayanmadım uzandım iki dal kiraza-

Geçen gün çarşıda gelirken gözüme ilişti 

Dizilmiş kaldırıma yerli kiraz sepetleri..

Satıcıya sordum kaça kilo 

Dedi iki buçuk milyon 

Dedim çok para

İçimden iç geçirdim

Desene bu Haziran da 

Kaçırdık yine yerli kirazı da.

Ertesi gece 

Geldi bizim gençlerden

Öfkeli bulutun anne ve babası

Ellerinde bir poşet kirazla

Ah dedim 

Nerden kaça aldınız 

Yerli kiraz fiyatı aynı çok dedim

Dediler al bir tabak gel doldur ye sende

Dedim garibin sofrası fakir da olsa gönlü zengin

Hani kaç zaman önce gitmiştin de 

Geçen gün geldin ya giderken dönüşünde 

Bir kez daha bakışını

Güzel gözlerini görmek için

Bahane ile o yönden mi gidiyorsun 

Sağda boşluk solda yâr var 

Ve yine gelir misin dediğimde

Başını döndürüp baktığında

Haziran güldü ya kiraz rengiyle

Tabaktaki kirazlara uzandım 

Ellerim boş gözlerim boşluğa.

15.06.2004(06.16)', '-Yapışık kirazlar toplanır dallardan Romantizm eser bir avuçtan bir çataktan  İkizin birini aldım uzattım ağzımdan Kiraz dudaklar ısırdıkça ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kiraz-rengi-haziran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şavkında Vurulduğum (Ay) tenim Yanar', 'savkinda-vuruldugum-ay-tenim-yanar-vedat-koparan-qcbrv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-Hey hüznün isyanında yalnızlığa vuran

Gecenin rengi altın sarısına ulaşmadan

Gün doğumuna hazırlanan gelin gibi 

Gece tarar saçlarını mavi hüzünlere

Akla gelir bin bir düş çoğalan

Bir sevdadan uyanışa kaç şiir doğar -

Sen esinlerimin güzel kaynağı

Çoğalıp çağladığım...Ben ayrı aykırı

Yürek atımım içimde bir nehir akar gider 

Sen yaşanası olan aktığım engin denizime

Bilirsin üstelik ne kadar 

''Haziranda ölmek zor ''.. 

Şimdi Haziranda 

Doğumlara doğmak zamanı...

Benliğimde yeni bir bayrama hazırlanan

Haziran''a özgü çocuk sevincidir kıpırdanan

Gelirim akarım hep sana 

Sen akmasan da bu yana 

Sakladım seni sana seni bana 

Derin denizlerin koyaklarında

Yaşanacaklarımız var daha

Gecelerin derin sessizliğinde

Bil ki mai düşler hep sende

Öperim yıldızlardan en parlak olanı

Şavkır sevgi nehrine ay ışıltıları 

Bu sensizliği taşıyan yaşam gemisi

Daha ne kadar yol alacak 

Yeni gün doğumunda birlikte 

Sevgi pınarından doyasıya içmeye 

Özgürlüğü seninle demek üzere

Kavuşmak derim o gün gelende

Gelmeden önce karanfil gülüşünle

Bir öpücük kondur umut çiçeğine

Bak bir çocuğun gözlerine huşu ile

Sevginin yumuşak derin sevecenliğiyle

Bilirim okşarsın her gördüğün çocuğun saçlarını

Gözlerinle öpersin değil mi ben diye 

Ne kadar kaldı nabzımızda atan o zamana 

İstiridyenin incisinde şiirin yüreğimde

Yaşarım seni her imge her hece de

Söyle özlem yazan bu gök bu deniz

-Mavi hüzünleri demlemek bize mi düşmeli-

Sal kendini ay parıltılı bir geceye

Çekelim gecenin tülünü üzerimize 

Yıldızlar göz kırpsın yansın (ay)  tenimizde 

Uyanalım güneşle öpüşen güne 

Mavileri içerim doyumsuz gözlerinde..

Islanmışız yaşamın vurgun tutsaklığında

Sağanaklara kar beni notalara yaz beni 

Sicim gibi aptal ıslatanında yun beni 

Kitlendim anahtarı ne ettin

Gel de aç açabilirsen yaşayalım sevgimizi..

-Gözlerimi Verdim Gözlerine Her Daim Sendeyim Sevgimle-

11.06.2004', '-Hey hüznün isyanında yalnızlığa vuran Gecenin rengi altın sarısına ulaşmadan Gün doğumuna hazırlanan gelin gibi  Gece tarar saçlarını mavi ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/savkinda-vuruldugum-ay-tenim-yanar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atıf-20-Adalılara', 'atif-20-adalilara-vedat-koparan-djg31', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hey koca Beyazıt meydanı

Kaç kez ağladın etin kemiğe batışında

Kaç kez gördüm ölümlerde ölümümü

Kaç kez kan revan morlar içinde

İlk kez kırılmadım ben ilk kırıldım düştüm 

Sen asfaltlarını istediğin kadar değiş

Tarihe düştüm yirmilerin izinden 

Yetmiş sıcağın da kozasından çıktı kelebek

Tomurcuk patladı Demircioğlu Vedat’ım ben

İlk cenin ilk gün ışığıyım koca çınar hala orada benimle 

Yaprağında sevgim rüzgarda titreyişin silinmedi kan izim

Gelip geçenleri gördükçe yüzünüz benim yüzüm

Bakın ağlamıyorum karaları da bağlamıyorum 

Gün açıp her güneş vurduğunda 

Görüyorum kendi yüzümde yüzlerinizi

Unutsanız bile ben unutmadım sizleri

Solmasın diye mavi gülüşleriniz 

İlk ışıklarla kaldırıyorum tarihin kepenklerini

Bu tarih bizim tarihimiz 

Ardımızdan niceleri geldi halada gelecekler 

Bilinsin ki gündüzü katleden gecelerin sahipleri 

Bu zulüm bu talan bunca yalan sürdükçe

Gündüze sahip çıkmanın da haklı gereği var..

- “ Gün bizim Güneş Bizim 

Göğsümüzde Yanan Ateş Bizim-“**

not: sadece iki dize alıntıdır

* Nazım Hikmet Ran

** Sezen Aksu Şarkısından

28.04.2004 (05:24)', 'Hey koca Beyazıt meydanı Kaç kez ağladın etin kemiğe batışında Kaç kez gördüm ölümlerde ölümümü Kaç kez kan revan morlar içinde İlk kez kırı...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/atif-20-adalilara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerde Yaşadım', 'siirlerde-yasadim-muammer-kurt-ej90e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gavur Dağlarının eteğinde yetişdim. 

Aşkların çekilmez mevsiminde.

Sonra hasret rüzgarları seyirtti beni.

Sevda yelleri büyüttü.

İşte bundandır şiirlerimin

yüreklerde sızlaması,

hasret rüzgarlarında esmesi,

sevda yellerinde kokması,

ayrılıklarda buluşması.

Bundandır ağuyu bal eylemesi,

yalnızlığı yar.

Bundandır ayakta durmam

yıkılmayası Gavur Dağları gibi.

Ölesi dediğim zamanlarda bile,

nefes alıyorum, 

işte yaşıyorum yine,

senin yokluğunda bile.

Şiirlerde yaşadım

hayâllerde öldüm ben.

Aşk denen Zülfükar''ı

yüreğimle böldüm ben...

Bundan ötesi vız gelir bana.

Papatya gözlüm

artık anlasana...', 'Gavur Dağlarının eteğinde yetişdim.  Aşkların çekilmez mevsiminde. Sonra hasret rüzgarları seyirtti beni. Sevda yelleri büyüttü. İşte bundan...', ARRAY['Türk Edebiyatı','Şiir','Muammer Kurt']::text[], 8.5, '{"poet":"Muammer Kurt","poet_slug":"muammer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/siirlerde-yasadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Top Sendeyken İyİ Oyna', 'top-sendeyken-i-yi-oyna-necmi-unsal-i5mfb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mezar, ziyaret edilen  yer demek kelime  manası.

Akıbet  herkes ziyaret  eder  onu,  var mı dahası? 

Şu geçici âlem, canın bir nefeslik  oyun sahası.

Top sendeyken iyi oyna, olmasın yüzünün karası.

Ameller yoldaş, mezarda  olanı sakın yalnız sanma! 

Sevinç, elem, tat, lezzet hep kuru birer hayaldir, kanma! 

Ela gözün, güzel yüzün hayata bir vitrin aldanma! 

Aldanışlar ellerde  kor, hemen maşaya sarıl  yanma! 

10 Nisan 2004 Cumartesi, Danimarka-Køge  19.17

8+9', 'Mezar, ziyaret edilen  yer demek kelime  manası. Akıbet  herkes ziyaret  eder  onu,  var mı dahası?  Şu geçici âlem, canın bir nefeslik  oyu...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/top-sendeyken-iyi-oyna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Tuzaklardan Uzak', 'ask-tuzaklardan-uzak-numan-eksioglu-4fb12', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İbrahim  Tüfekçi’ye

	

			Tuzaklar uzaklara varmaman içindiler

			Her engelde bir parça etin kaldı

			Sana kalan  yüreğin ruhun beynin

			Zaten insan yalnız onlar kadardı

			Ruhun kendini daha geniş çizdi her defa

			Yüreğinse  yontup durdu kendini

			Beynin şimdi daha çok içeriyor

			Üçü de usanmadan saygılarını saldı

			İçin iç içeriyor

			En büyük matruşka o

			Ötekilerin dışı da içinde 

			İçinde aşkın vardı

	

			Aşk engele takılmaz

			Tuzakta yakalanmaz

			O hiç almadan vermek gereğinde

			Alacağınıysa her zaman aldı', 'İbrahim  Tüfekçi’ye 	 			Tuzaklar uzaklara varmaman içindiler 			Her engelde bir parça etin kaldı 			Sana kalan  yüreğin ruhun beynin 			Zat...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-tuzaklardan-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri', 'biri-numan-eksioglu-g9dxn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ses telleri  aldırılmışın biri

				Gözleri kataraktlı kaldırılmışın biri

				Kulaklarını kendisi tıkamış

				Kalbi saydam

				Beyni çöp doldurulmuşun biri

				Adımı yerinde say komutuna uyumlu

				Ne parmağında nasır ne de avuçlarında

				Alnı tersiz kendine yoldurulmuşun biri', 'Ses telleri  aldırılmışın biri 				Gözleri kataraktlı kaldırılmışın biri 				Kulaklarını kendisi tıkamış 				Kalbi saydam 				Beyni çöp dold...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/biri-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıraçlığı Sulamak', 'kiracligi-sulamak-numan-eksioglu-guvew', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boşluğumu  boşalttım

			Küstürdüm  hiçliğimi

			Şiirlerle  giderdim

			Duygusal  açlığımı

			Artık boşluğum dolu

			Hiçliğim sevgi kulu

			Ulaştığıma sundum

			Aşka ilaçlığımı

			

			Yüreğim yürekleri

			Sırtlanıp çöl geçirdi

			Lütfen siz de sulayın

			Biraz kıraçlığımı', 'Boşluğumu  boşalttım 			Küstürdüm  hiçliğimi 			Şiirlerle  giderdim 			Duygusal  açlığımı 			Artık boşluğum dolu 			Hiçliğim sevgi kulu 			U...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiracligi-sulamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maskeli Siyah Soytarı Gri', 'maskeli-siyah-soytari-gri-numan-eksioglu-noxgo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Pasa yaslanmış sırt küfle taçlanmış saç

				Çöple  beslenmiş fert isle renklenmiş renk

				Sisle çevrilmiş göz tozla sözleşmiş söz

				Cambaz pembe

		

				Kanla karışan yaş jopla yarılan baş

				Yuhlar çekilen düş yanlış çekilen diş

				Gözü yuhlayan kaş içi dışlayan dış

				Soytarı gri

	

				Hiç içermeyen iç herşey sunulan hiç 

				Yargı eliyle suç suçla güçlenmiş güç

				Dolu  sanılan boş gülü yolunan hoş

				Maskeli siyah', 'Pasa yaslanmış sırt küfle taçlanmış saç 				Çöple  beslenmiş fert isle renklenmiş renk 				Sisle çevrilmiş göz tozla sözleşmiş söz 				Camba...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/maskeli-siyah-soytari-gri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötelerde Bir Yerde', 'otelerde-bir-yerde-numan-eksioglu-fygp1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ötelerde bir yerde

			Basamaklar herkesin çıkabileceği yükseklikte

			Bir çocuk bile çıkabilir bu basamaklardan

			Kimse yukarıdakilere imrenerek bakmıyor

			İsterlerse çıkabilecekleri bir yer yukarısı çünkü

			Ve aşağılarda kuyuların dibinde kimse yok

			Kimsenin dilini  bilemesine gerek kalmamış

			Ölüm zulüm masalların konusu

			Hastalığı hasta düşürmüş bilim

			Baş ağrısı bile unutulmuş

			Verilen alınmamak üzere veriliyor

			İhtiyaç olan şeylerin hepsinin  üretimi fazlasıyla

			Herkes gerçekten sevdiğiyle beraber

			Ne fahişeliğe nede jigololuğa gerek var bu yüzden

			Kuşların bile kükreyebilme yeteneği var

			Ama hiçbir canlı kükremiyor

			Beslenmenin yeni bir yolu bulunmuş

			Yaşamak için hiçbir canlı  öldürmek zorunda değil

			Ev yapmanın metodu  değişmiş

			En büyük ev birkaç saatte yapılıveriyor

			Hava isteyen için sıcak ve soğuk

			Genelde ılık olması sağlanmış

			Kuşlar yuvalarını bir evin içinde

			Yapma özgürlüğüne sahip

			Uçaklarla en uzak gezegenlere gidip dönmek

			Bir gün sürüyor yalnızca

			Çocuklar erken  olgunlaşabiliyor

			Yaşlılar istediği yaşa geri dönebiliyor

			Herkesin yüzlerce tablosu yüzlerce bestesi

			Yüzlerce şiiri var ve hepsi gerçekten güzel

			Her şey bir daha bozulmamak üzere yapılıyor

			Şeytan ve zebanilere intihar etmek düşmüş

			Ötelerde bir yerde dediysek

			Gidilemeyecek kadar ötelerde diye anlamayın sakın', 'Ötelerde bir yerde 			Basamaklar herkesin çıkabileceği yükseklikte 			Bir çocuk bile çıkabilir bu basamaklardan 			Kimse yukarıdakilere imre...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/otelerde-bir-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgür Olduğunuzun Farkında Değilsiniz', 'ozgur-oldugunuzun-farkinda-degilsiniz-numan-eksioglu-xjmpg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özgür olduğunuzun farkında değilsiniz

		Havayı koklayıp güneşe çıktığınızda

		Kimse para istiyor mu sizden

		Biliyoruz zenginlerin ve yöneticilerin 

		Arkasından küfrediyorsunuz

		Bunun için hapse atılıyor musunuz

		Çocuklarınızı kadınlarınızı dövdüğünüz için

		Kimse kızıyor mu size

		Yoksulsanız dilenin halkımız merhametlidir

		Böylelikle zengin bile olabilirsiniz

		Ama turistlerin ve zengin muhitlerin

		Olduğu yerlerde yapmayın bu işi

		Onlara karşı ayıp olur küçük düşer devletimiz

		Ticaretle uğraşıp  bire alıp beşe sattığınızda

		Kanun yakana yapışıyor mu

		Sonra siz hiç bir işsize

		Neden işsizsin diye

Sitem eden bir yönetici gördünüz mü? 

Hastalığınızı tedavi ettiremediniz

Çocuklarınızı okutamadınız	

Başınızı sokacak bir kulübeniz yok

Sokakta yatıyorsunuz diye

İşkence ediyor muyuz size

“Zulümle gelişiyor kinle gülüşüyorsunuz “diyen

Şairler çıkıyor içinizden onlar başka 

Koroyla olmadıktan sonra

Aleyhimize şarkılar söylemenize karışıyor muyuz

Aşkı birini sevmek olarak algıladığınızda

Çok şükür demiyor muyuz

İntihar ettiğinizde

Cesedinize eziyet ediyor muyuz

Özgür olduğunuzun farkında değilsiniz', 'Özgür olduğunuzun farkında değilsiniz 		Havayı koklayıp güneşe çıktığınızda 		Kimse para istiyor mu sizden 		Biliyoruz zenginlerin ve yöneti...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ozgur-oldugunuzun-farkinda-degilsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsızların Darlığı', 'varsizlarin-darligi-numan-eksioglu-un0x6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğin yumruğu yok

				Gözlerle kulakların

				Yürekle ve beyinle iletişimi kopuk

				Dilin gözle bağlantısı kesilmiş

				Kulaklarla hislerle koparmış bağlarını

				İşte sonuç

				İşsizlerin hürlüğü  aç yatma özgürlüğü

				Acilen  göz doktoruna çıkmalı

				Kulakları bir güzel yıkatmalı

				Dilimizi kendimiz eğeleyip

				Yüreğe yumruk nakli yaptırmalı

				Yoksa yine

				Arsızların varlığı  varsızların darlığı', 'Yüreğin yumruğu yok 				Gözlerle kulakların 				Yürekle ve beyinle iletişimi kopuk 				Dilin gözle bağlantısı kesilmiş 				Kulaklarla hisler...', ARRAY['Türk Edebiyatı','Şiir','Numan Ekşioğlu']::text[], 8.5, '{"poet":"Numan Ekşioğlu","poet_slug":"numan-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/varsizlarin-darligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Göç etti...', 'goc-etti-erdal-asik-ssms2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göç etti yüreğim sevdalardan 

Ayrılıkların olmadığı 

Acıların yaşanmadığı 

sahte bakışlardan 

yalan sevgilerden 

olmayan aşklardan 

usandım riyadan 

kanın kahpesinden 

yoruldum sevmekten 

sevildiğini zannetmekten 

nefret ettim aşkı dokumaktan 

göç etti yüreğim sevdalardan', 'Göç etti yüreğim sevdalardan  Ayrılıkların olmadığı  Acıların yaşanmadığı  sahte bakışlardan  yalan sevgilerden  olmayan aşklardan  usandım ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/goc-etti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzellik Benimdir...', 'guzellik-benimdir-muammer-celik-n83wi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'benimdir güzellik 

sahip çıkarım

bacadan kovulsam 

kapıdan girerim... 

giremesem de

kapısında yatarım

ve orta yere

mahşeri kurarım...

mahşerde merhamet 

senin elinde 

adalet terazisi 

kapının zilinde

durmadan,

usanmadan çalarım... 

sırtımda çulla 

yalın ayaklarımla 

gözlerim

gözlerim... 

Ayrılmayın sakın 

o güzelin gözlerinden,

Gözlerim...! 

BirDeli

26.06.2004', 'benimdir güzellik  sahip çıkarım bacadan kovulsam  kapıdan girerim...  giremesem de kapısında yatarım ve orta yere mahşeri kurarım... mahşer...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/guzellik-benimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bencil', 'bencil-hasan-sakman-nsven', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alaca bir geyik gibi

karlı bir dağ vadisinde 

dikip kulaklarımı sizi dinliyorum.

Sesiniz geliyor dostlarım,

kalp atışlarınız bile.

Hayaller kuruyorum, sonsuz...

hani biraz zamanın gerisinde olsam

diyorum.

Biliyorum,

bencillik ediyorum.

O kadarı da olsun ya! 

Aslında en büyük bencilliği

ölürken sizden ayrılmayı istemeyerek 

ediyorum.

(13 Temmuz 2001)', 'Alaca bir geyik gibi karlı bir dağ vadisinde  dikip kulaklarımı sizi dinliyorum. Sesiniz geliyor dostlarım, kalp atışlarınız bile. Hayaller ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bencil-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki I', 'sanki-i-hasan-sakman-t9v0f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçime doğuyor 

sanki birazdan öleceğim,

derin bir sessizlik dışarıda.

Pencerem açık,

sanki esintisi vuruyor yüzüme

bu son rüzgarın

ve sankilerle sürüyor dizelerim

Korkuyorum,

lütfen kurtarın beni! 

(13 Temmuz 2001)', 'İçime doğuyor  sanki birazdan öleceğim, derin bir sessizlik dışarıda. Pencerem açık, sanki esintisi vuruyor yüzüme bu son rüzgarın ve sankil...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sanki-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksan Korkarım Ben', 'sen-yoksan-korkarim-ben-hasan-sakman-qeu27', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Işıklar sönünce daha güzel bu şehir; 

daha parlak yıldızlar,

daha kırmızı sigaramın alevi,

hayallerse daha sonsuz.

Mesela sen; 

ve gözlerin, yemyeşiller.

Kapatma sakın gözlerini

alaca karanlık ortalık.

Ne kadar güzelse bu şehir karanlıkta,

sen yoksan korkarım ben! 

Bir hiç olurum,

karanlıkta kaybolurum.

(20 Ağustos 2001)', 'Işıklar sönünce daha güzel bu şehir;  daha parlak yıldızlar, daha kırmızı sigaramın alevi, hayallerse daha sonsuz. Mesela sen;  ve gözlerin,...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-yoksan-korkarim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-hasan-sakman-ujcva', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Prangalarımı çıkarıyorum artık,

bana kalırsa sen de tadını çıkar! 

ve gidiyorum bu şehirden,

yıllar sonra acımasızlık belki

dönüp bakmıyorum bile arkama

aldırma sen! 

Yüreğim hep böyledir,

hep tutsaktır birşeylere! 

Ne bileyim dostlara, sevgiliye

iyi bak yüzüme! 

Belki bu son görüşün beni,

belki yılllar akar takvimden de 

yolum düşmez bu şehre

Israr etme, gideceğim! 

Beni ne işkenceci karakol kelepçeleri

tutar,

ne de yarin ağzından dökülen 

''gitme'' sözcükleri.

Hiçbirşey kalmasın benden geriye

istersen fotoğrafları da yak

yırt mektuplarımı lavanta kokulu

Bırak! sarılma ayaklarıma

bu sana yakışmaz

hadi sen de gel desem

biliyorum; 

bunca yazılandan sonra

o da sana yakışmaz.

(18-20 Ağustos 2001)', 'Prangalarımı çıkarıyorum artık, bana kalırsa sen de tadını çıkar!  ve gidiyorum bu şehirden, yıllar sonra acımasızlık belki dönüp bakmıyorum...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gidiyorum-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alfabe', 'alfabe-ahmet-agdere-2k8rx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkla başladı her şey, 

Adem geldi evvelden,

Aşıklar gitti de ey,

Ad düşmedi hilalden.

Bihaber saklar gönül,

Bana ne aşkımdan der.

Bilmez, donar tevekkül,

Bahtsız, buzda kalmış er! 

Celalden sual olmaz,

Can çıksa, ebedidir.

Cemalinde O solmaz,

Cisim, kalan tek gizdir..

Çiğ düşürmek ister de,

Çamura girer kendi.

Çaylak senin neyine,

Çekme yokluk çilesi.

Derya boğar Mecnun’u,

Damızlık söze döner.

Devir sürükler onu,

Dev Leyla çölde önder.

Ermez sevdasız gönül,

Emse de vakit canı.

Eskir mi gülle bülbül,

Ekse onunla anı.

Figanla taşar yürek,

Feragat eder andan.

Füsun kapar da bilek,

Firari olur candan.

Gülşen katar bahara,

Gölgesi daim kılar.

Gamdır, onsuz naçara; 

Gafilde baki çıkar.

Hatır da O’ndan gelir,

Hezeyan da can sana.

Haşmetten ateş geçir,

Hürmetler kondur başa.

Ilgımla döner yokken,

Islar yaşsız geceyi.

Irakta aşka gözken,

Irgat, sana yüreği.

İçkide medet uman,

İsraf eder masada.

İlelebet sır, umman,

İsmi durur karşıda.

Jön ve aşkta acemi,

Janjan yakışır ona.

Jet dedeye demeli,

Jurnal yazmaya başla.

Kalem taşır sevdayı,

Kah şiir, kah romanla.

Keramet kanda saklı,

Kitap, defter palavra! 

Lafla yürümez gemi,

Lâl de düşer ateşe.

Laçkadır lafçı dili,

Lazım lahuti gebe.

Mesafe gelir kısa,

Meşaledir hep yanar.

Merde kim karşı çıksa,

Madde başını sarar.

Nerden gelir de geçer,

Nazın haberi duymaz.

Neşeyle dolu beşer,

Nifaka ekmek sunmaz.

Oğul nesil çevirir,

Oluşur gece gündüz.

Ocakta sevda erir,

Okumasa elde cüz.

Ölümü yardı Yunus,

Ömrünü yedi burda.

Önem verdi ona Us,

Övdü ruhunu nurda.

Para nefsin herşeyi,

Perişan onsuz dünya.

Pervane döner beyi,

Paye yok kısır aşkta.

Rüya görür kör aşık,

Raddesiz kısır aşkta.

Rafine suda kaşık,

Riya etrafta dalga.

Sahneye konmuş piyes,

Sevişmek sevmek güya.

Saatten sonra lades,

Satıcı etten  dünya.

Şair, düşünür yazar,

Şafağı bulur gece.

Şehvete kazık çakar,

Şerik ona tek hece.

Temayüz beyaz safta,

Tarih düşmeyi bekler.

Tekmile çare rafta,

Taklite yokluk düşer.

Uçsuz bucaksız sema,

Uğuru seyre dalar.

Uçma fazla havaya,

Ucuza çakal atlar.

Ülfet, kamil yaşamda,

Üvey aşkı üfürür.

Üleştir bunu onla,

Üzüme tane düşür.

Vaveyla kopar vardan,

Vadesiz biten aşkta.

Vaatler biter yardan,

Velhasıl muhtaç O’na.

Yazarken geldik sona,

Yoğu varı bitirdik.

Yaktık aşkı kağıtla,

Yar’da yarı yitirdik.

Zarfa koydum bin mesaj,

Zarar etmesin andan.

Zarife olmaz  şantaj,

Zevk alsın okumaktan.', 'Aşkla başladı her şey,  Adem geldi evvelden, Aşıklar gitti de ey, Ad düşmedi hilalden. Bihaber saklar gönül, Bana ne aşkımdan der. Bilmez, d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":112,"source_url":"https://www.antoloji.com/alfabe-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek I', 'dilek-i-hasan-sakman-3e3e8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi küçücük bir hayal kuracağım,

sonra da bir dilek...

Dileğim kuracağım hayal olacak! 

yalnızlıktan kurtulacağım önce,

sonrası kolay geliyor bana! 

(8 Şubat 2002)', 'Şimdi küçücük bir hayal kuracağım, sonra da bir dilek... Dileğim kuracağım hayal olacak!  yalnızlıktan kurtulacağım önce, sonrası kolay geli...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dilek-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümsüyorum Hayata', 'gulumsuyorum-hayata-pinar-yilmaz-teakb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acı yagmuru altında ıslanıyorum yüreklice

Sevgisziligi kavrıyorum nasır tutmus ellerimle

Saygısızlıga gülüp geciyorum umursamazca

Nefretlerimi yutuyorum gülümsüyorum hayata', 'Acı yagmuru altında ıslanıyorum yüreklice Sevgisziligi kavrıyorum nasır tutmus ellerimle Saygısızlıga gülüp geciyorum umursamazca Nefretleri...', ARRAY['Türk Edebiyatı','Şiir','Pınar Yılmaz']::text[], 8.5, '{"poet":"Pınar Yılmaz","poet_slug":"pinar-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gulumsuyorum-hayata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'RPT-Anlamsız', 'rpt-anlamsiz-erol-dal-qjp4n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerimdeki sihrin 

